INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Varacak Sonu', 'neye-varacak-sonu-kiymet-sonmez-6jzej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neye varacak sonu

Hüzün mü

Mutlulukmu? 

Neye varacak sonu

Bir türlü  anlamıyorum.

Boşa koysam dolmuyor,

Doluya koysam almıyor.

İçim içime sığmıyor,

Neye varacak sonu 

Bir türlü anlamıyorum,

Geçermiyiz engeli,

Takılırmıyız acaba? 

O büyük güne bizde

Ulaşırmıyız acaba? 

Neye varacak sonu

Bir türlü anlamıyorum

Hem korku,

Hem umut var içimde

Ama yinede

Neye varacak sonu,

Bir türlü anlamıyorum,', 'Neye varacak sonu Hüzün mü Mutlulukmu?  Neye varacak sonu Bir türlü  anlamıyorum. Boşa koysam dolmuyor, Doluya koysam almıyor. İçim içime sı...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neye-varacak-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyazım Sanadır', 'niyazim-sanadir-yasar-tezel-uyzg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaz zambaklara takıldı,sevgi

Yedi gökkuşağı rengi

Semazenler,vurulan kudümler

İlahi musıki

Binbir renk güller

Zikirde bülbüller

Duaya bürünmüş tan yeri

Yuvaya dönen umutlar,

İşlenen günahlar

Rahmet damlaları,

açılan ufukar

Seccadem,kabe''m

Beyaz zanbaklar

Sanadır, şükrüm

sanadır tövbem

Yalnız sana niyaz', 'Beyaz zambaklara takıldı,sevgi Yedi gökkuşağı rengi Semazenler,vurulan kudümler İlahi musıki Binbir renk güller Zikirde bülbüller Duaya bürü...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niyazim-sanadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığı en güzel kim oynaya bilir?', 'yalnizligi-en-guzel-kim-oynaya-bilir-kerem-kayar-uh9fq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dokuna bilirsin belki başağın teline

Ama rüzgâr olamazsın

Görünmeden okşamayı becere bilir misin? 

Hep bir inciten yanın vardır…

Günün birinde ressamın tuvalini süsleyen

Yalnız bir siluet olabilirsin

Ama oynayamasın sıkıntı verinceye dek…

Zaman gelir ölmek istersin, umarsızca

Adının komple büyük harfler ile

Ya da alfabeyi kıskandıracak kadar

Simetrik şekiller ile yazılmasını dilersin

Ben okuyamadıktan sonra, 

onlarında okumasının

Bir önemi kalmayacak, 

ya da bir ölünün anlamı…

Yerine getirilirse dualarının

Sen bir evliyasın,

Bize de dua et denilmesinden korkarak

Che ve ya Marks önceliği tanırsın… kitaplığına

Gönlünün betimlemesine Agora meyhanesi yakışır

Eğlence yapıp kaçmamışsındır, bir gönülden oysa

Onlar gelir; veren hep sen olmuşsundur, aşka doyan onlar

“O” harfi mide bulandırır artık

gönül meyhanedir… Gideni özler, geleni hoşnut eder

Özlemeye vakit bulduğun zamanlarda 

Yapamadıklarını yapman için fırsat doğar

En güzel seni anlatan 

Yalnızlığı kıskandıracak kadar

Yalnızlık oynarsın

Oynar mısın? Diye sorulmadan…', 'Dokuna bilirsin belki başağın teline Ama rüzgâr olamazsın Görünmeden okşamayı becere bilir misin?  Hep bir inciten yanın vardır… Günün birin...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalnizligi-en-guzel-kim-oynaya-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ters Çevirdiler', 'ters-cevirdiler-yusuf-onder-bahceci-hpt80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaplumbağalar gibi yavaş, yavaş, yol alıyordum,

Tutup ters çevirdiler, bir türlü dönemedim, gülüm,

Kirpi gibi oklarım olsaydı herhalde cân yakardım,

Tutup ters çevirdiler, bir türlü dönemedim, gülüm.

Katır değilim ki, böyle yapana çifteler savurayım,

Ben eşşek değilim ki anırayım inat, inat yapayım,

İnsanım, insan eti, kemiğiyle, sevgi düşüncesiyle,

Tutup ters çevirdiler, bir türlü dönemedim, gülüm.

Ordan bilirim ben bu çaresizliği, nerde görürsem,

Nerde görürsem zavallı bir kaplumbağa çeviririm,

Elimle başını okşarım, teselli veririm, sabır dilerim,

Tutup ters çevirdiler, bir türlü dönemedim, gülüm.

Niye kaplumbağa dedim, herhalde anlarsınız siz,

Kaplumbağa çok yavaş gider, menziline varır mı,

Küçük bir çukurda ayağı kayar sırt üstü uzanır mı,

Tutup ters çevirdiler, bir türlü dönemedim, gülüm.', 'Kaplumbağalar gibi yavaş, yavaş, yol alıyordum, Tutup ters çevirdiler, bir türlü dönemedim, gülüm, Kirpi gibi oklarım olsaydı herhalde cân y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ters-cevirdiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Pınarı', 'sevgi-pinari-mustafa-bilgili-fyimy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi pınarımdan aşkım çağlarken,

Uzat gönül tasını doldur ha doldur,

İç kana kana sevdamı şifalar olsun,

Eğer beğenmezsen güzelim,gel beni öldür.

Yıkma şu gönlümü,haydi sende sev biraz,

Aşığı usandırır vallahi,sendeki bu naz,

Kışta bitti,bahar geldi arkasından yaz,

Eğer gideceksen buralardan,ne olur bildir.

Sevgi ek gönlüne,sakın kin nefret biçme,

Aşk şarabı çok tatlıdır,başka şey içme,

Yıkılmış görürsen ne olur çiğneyip geçme,

Eğer sevmiyorsan bile,tut beni kaldır.

Yüzüme gülerken,el aleme yan gözle bakma,

Bu dünyada beni yaktın,başka birini yakma,

Gönlüm sana saray olsun,oradan dışarı çıkma,

Eğer seveceksen şu gönül sana çiçektir güldür.

Sevmiyorsan açık söyle,ben tahammül ederim,

Sevene bu canım kurban,sevmeyene ne derim,

Aşkımı isteyen pek çok,birisine giderim,

Seven engel tanımaz,ona her taraf yoldur.

                                                                         04.02.1997', 'Sevgi pınarımdan aşkım çağlarken, Uzat gönül tasını doldur ha doldur, İç kana kana sevdamı şifalar olsun, Eğer beğenmezsen güzelim,gel beni ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgi-pinari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuyorum', 'susuyorum-asude-gediz-vk3f8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susuyorum

Sana başlamak istiyorum 

yeniden

kin tutmayan 

hüzne, sevgiye tutkun 

bir yürek ya...

coşuyorum

karmaşık sözlerin 

ve o konuşan yüreğin 

geliyor aklıma 

donuyorum…..

donduruyorum 

sana olan sevgime

geceye tutkun

sevgili

sus diyorum!', 'Susuyorum Sana başlamak istiyorum  yeniden kin tutmayan  hüzne, sevgiye tutkun  bir yürek ya... coşuyorum karmaşık sözlerin  ve o konuşan yü...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/susuyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Kaldım Kışlara', 'yine-kaldim-kislara-yusuf-onder-bahceci-7izqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç mevsim geldi, geçti, kalbim de hüzün biçti,

Senin olmadığın bir Dünya, benim için bir hiç ti,

O güzel gözlerin var, var ya, kâlbimi delip geçti,

Kaç mevsim geldi, geçti, kalbim de hüzün biçti.

İlkbaharda gelir dedim, gelmedi derdi bilmedi,

Umudum yaza kaldı dedim, yazın da, gelmedi,

Sonbaharda, belki gelir dedim, gelim demedi,

Kaç mevsim geldi, geçti, kalbim de hüzün biçti.

Yine kaldım kara kışlara bakarım kâr yağışlara,

Çocuklar kârdan adam yapar, bakarım onlara,

Her yer bembayaz ama benim bahtım sa kara,

Yine kaldım kara kışlara bakarım kâr yağışlara.', 'Kaç mevsim geldi, geçti, kalbim de hüzün biçti, Senin olmadığın bir Dünya, benim için bir hiç ti, O güzel gözlerin var, var ya, kâlbimi deli...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-kaldim-kislara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm!', 'dogum-gunum-mesut-ozturk-odmpj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah güneş doğdu ufuktan,

Yataktan kalktım yavaş yavaştan,

Diğer günlerden tek farklı olan? 

Bugün benim doğum günüm. Neden doğdum? 

Anam, babam, vatandan uzaktayım,

Eşim ve çocuklarımdan, ben ıraktayım,

Dertlerimle ben yine başbaşayım,

Bugün benim doğum günüm, olmaz olsun! 

Rüyalar şen şakrak bayramlar oluyor,

Gerçek hayat yine gözlerime yaşlar doluyor,

Hele bugünde yanlızlık çok acı koyuyor,

Bugün benim doğum günüm. Doğmaz olsaydım.

Halin nedir diye soran olmaz sa,

Telefonun bir tek kere bile çalmaz sa,

Düşünüpte sevenin bulunmaz sa,

Doğum günüm benim, son günüm olsun!', 'Sabah güneş doğdu ufuktan, Yataktan kalktım yavaş yavaştan, Diğer günlerden tek farklı olan?  Bugün benim doğum günüm. Neden doğdum?  Anam, ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogum-gunum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni İstemiyor Artık Bu Şehir', 'beni-i-stemiyor-artik-bu-sehir-aynur-uluc-drked', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Devlet dairelerinde başladığınız işlemleri dingin bir ruh haliyle bitirmek zordur. İşte böyle bir günde konuyu bitirecek son imza için beklerken yaşlı bir teyze geldi oturdu yanıma. Derin oflar çekerek dizlerinin nasıl da ağrıdığından, geceleri uyuyamadığından yakınıyordu. Anlatacak ne çok şeyi vardı bu yaşlı kadının. Sanki yaşamı boyunca anlatacaklarını bugüne saklamış da, şimdi hepsini sıralıyor gibi konuşuyordu oturduğu yerde. 

Oradan çıkınca Fatih`e gidecekti. Durmadan Neredeyim?  diye yer, ona göre davranabilmek için yol soruyordu. Öncelikle Sirkeci`den Eminönü`ne gitmesi gerektiğini anlattım ama, tramvaya binse bunu nasıl başaracağını bilmiyordu. Yürüse dizleri çok ağrıyordu. Aralıksız konuşması, zaman geçtikçe gerilim duygusu uyandırdı bende. Günlerdir koşuşturmuş bir bürokrasi yorgunu olarak can sıkıcı buldum istemeden bu durumu. En nihayet işlemlerimiz bitip de evraklarımız çantamızda, merdivenlerden birlikte inerken dedi ki: “Ben yetmiş üç yaşındayım görüyorsun. Kızız diye okutmadılar bizi zamanında. Babamın iki oğlu da doktor oldu. Ben de işte böyle yolunu izini bilemez bir yaşlı kadın. Ne okuma var, ne de yazma...”

Bir anda içimden bile kızardım utancımdan. Oysa sesinin tonu belli ediyordu; şimdi ne kadar anlatsa azdı. Yaşamda uğradığı haksızlıkları giderememekten kaynaklı biriktirimde onun suçu yoktu çünkü. “Teyze” dedim; “Gir koluma. Seni tramvaya bindireyim.” 

Yürümeye başladığımızda gerçek bir ilgiyle dinlendiğini fark edince; biraz önceki sızlanmaları, yavaş yavaş sohbet tadını almaya başladı. Ağrıyan dizlerine karşın Sirkeciden Eminönü`ne kadar benimle yürümeye niyetlendi. Kendisini durakların olduğu yere kadar götürüp otobüsüne bindireceğimi söylediğimde nasıl da sevindi. Koca yaşamı boyunca öğrendiği en önemli şeyi açıklar gibi dedi ki; “ Kızım; Eminönü`nde bir yaşlı teyze söyledi dersin. Oğlun için çırpınma. Bir el kızı alıyor ya, bırakıveriyor anasını. Kocam da öldü. Oturduğum evi babası oğlumun üstüne yapmıştı, o da satıverdi gitti. Alan kişi, kapıma gelip gelip Bir yatak da ben atayım odanın tekine, oldu olacak demiyor mu, nasıl da zoruma gidiyor. İki üç güne kalmaz, memleketime temelli gideceğim mecbur. Bu şehir yer bitirir insanı.Tunceli`de yoğurdun kilosu eski parayla üç yüz bin lira...Kırk yıl oldu biz İstanbul`a geleli ama buraya kadarmış. Artık beni istemiyor bu şehir. Daha yolunu izini bile öğrememeyen bu yaşlı kadına yer yok buralarda...” 

Diyecek bir söz yoktu. Otobüsüne bindirince cama vurup el sallayarak uğurladım onu. Fatihe giden bir otobüsle Tunceli`ye uğurladım... Aklımda Suriyeli şair Jana Seyda’nın bıçak gibi dizesi: 

“İstanbul, denizin yok senin.” 

“Ah canım teyzem” dedim o duymasa da. Aynı gideceğin yerde de olmadığı gibi. 

  

Aynur  Uluç

Birgün Gazetesi / 01-04-2005', 'Devlet dairelerinde başladığınız işlemleri dingin bir ruh haliyle bitirmek zordur. İşte böyle bir günde konuyu bitirecek son imza için bekle...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-istemiyor-artik-bu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırça Köşk', 'sirca-kosk-dilek-unaldi-y44am', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bana iyi huylarımı bırakırmısın

kişisel kaderimi nötr etmeye gidiyorum.

belki bir demir hindi ağacının kovuğunda

belki yeşil bir ejderhanın kanatlarında terkederim

gölgelerimi

yüzleşmenin tüm yönlerini sindirerek içime

belki bir bahar sabahı penceremden yüzüme inen dolu

yeşilin içinde eriyen su olursun

bir ömür boyu yetmiyeceklerin korkusu

yeni bahar turfandalarında geçmiş zaman anımsamalarımız 

hiçliğe yürüyen adımlarımızı unutarak

belki de hiç bilmediğim bir limanda bağışlayarak

ilk ve son kez duyumsamanı istiyorum

aşkın rollerimi

/ 

tüm halkasal küreler içiçe geldiği zaman

sırça köşküm ey atlas kemiğinde 

bana yer ayırır mısın



*Aşkın Rolleri: İlahi gücün doğadaki yansımaları

*Halkasal Küreler: Tüm Irklar', 'bana iyi huylarımı bırakırmısın kişisel kaderimi nötr etmeye gidiyorum. belki bir demir hindi ağacının kovuğunda belki yeşil bir ejderhanın ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Ünaldı']::text[], 8.5, '{"poet":"Dilek Ünaldı","poet_slug":"dilek-unaldi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sirca-kosk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kriz Bitmez', 'kriz-bitmez-mevlut-bicik-pdh3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yirmisekiz şubat’ta çıktı bir haber,

Ispanya’nın ceuta’sında söylenen şarkı.

Müslümânlara içeriyormuş hakâret n’aber,

Zavallılar bilmez ki kültürün beşiği şark-ı.

Demişler Íslâm kültürü deli’dir deli,

Íslâmdan öğrenmişlerdi wc kültürünü.

Müslümâna hayvan demişler doğrudur,belî,

Âyine-i müslim de kendisini görmüştür sürü.

Hitlerin yahûdileri kestiğinden bahisle,

Müslümânları neden pas geçti  demiş.

Ağızlarından akıttıkları salya-i habisle,

Karikatürün üzerine bir b..k daha yemiş.

Müslümâna ne dense doğrudur aslında,

Çünki birbirlerini tanımaz,irtibâtları yoktur.

Sınıfta kalmıştır müslümân uhuvvet faslında,

Başlarından eksik olmaz belâ,fesatları çoktur.

Sonsayfa-haber de okudum bunları,

Önce güldüm sonra öfkelendim,kızdım.

Kardeşim adâletinle sıraya diz şunları,

Derken etrafıma bakıp Utandım,sızdım.

Mevlüt Bicik

01.03.2006   saat  11.11

Esslingen', 'Yirmisekiz şubat’ta çıktı bir haber, Ispanya’nın ceuta’sında söylenen şarkı. Müslümânlara içeriyormuş hakâret n’aber, Zavallılar bilmez ki k...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kriz-bitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelere Saklanmak', 'golgelere-saklanmak-yasar-tezel-mdplp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görmesin beni,bilmesin sevdiğimi

Ne yediğimi ne içtiğimi

Onunla onsuz kendimden geçtiğimi

Çiçekleri onun için sevdiğimi

Söyleyeceğimi dinleyecek mi? 

Yoksa gölgeler güler

Özlem seninle tanımsızlık

Güzelliğin güneş,gölgeler aydınlık

Kaç baharlara umut aldık

Gel artık ey dilber

Hekese aydınlık saçan,

Sevdiğine karanlık', 'Görmesin beni,bilmesin sevdiğimi Ne yediğimi ne içtiğimi Onunla onsuz kendimden geçtiğimi Çiçekleri onun için sevdiğimi Söyleyeceğimi dinley...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/golgelere-saklanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Evim Olsun / Bu Bedel', 'bir-evim-olsun-bu-bedel-sevinc-kavuk-kwuy0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel dinlendiriciliği ile sohbeti zengin

Kimi roman, her yemek kitabı 

Şüphesiz tüm masallar, ne çok efsaneler

Tarihi yapılardan, harabe, sur, piramit, hamamlar...

Yarım kaldı tarihleri....

Şimdi onları okşamaya bombalar da zevklendi

Yerin dibine geçesiye utandırmaya tarihi…

Gökdelen özendiriciliğin özellikle çöküşü

Kalabalık yalnızlığın birliksel reçetesiyle ölçülü…

Bir evim olsun macerasına ne dersiniz? 

Tüm kavram, terim, resim, modelleriyle hangi halk

Politikasının renginden olacak 

Tabii bu geleceğin kitabı önemli rol oynayacak 

Evinizi yapmaya karar vereceğiniz zaman

Siyah-beyaz, belki renkli, ne bol resimli

Kimi çatısı için birer örnek, kimi terası, bahçesi…

Bu olsun evim demeyle karıştırmamak için

Toprağın, yörenin, geleceğin de kuralı

Belki bel kemiği ince, bacakları titrek, 

Dermansız, belki çöplüğe hassas, ince ruhlu…

Onca yükü kaldıramaz değil mi ama….

Her yöreden her tecrübenin 

Edinenenlerine sorun, aranın 

Her yerden bilgi toplayın...

Ama sonra sadece ve sadece sağlığınız için

Bir de yörenin, çevrenin, alanın onuruyla 

Boyu bosu, eşi eşine, dişi dişine denklikle 

Onlardan da yine bir kaçıyla koklaşarak…

Siz mutlaka ve sadece mimara gidin! 

Mühendis, müteahhit, üstenci, ustalar

Akacak su, açacak çiçek, yeşerecek ağaçlar

Çocuğa oyun, okul, eğlence, dinlence, arkadaşlıklar

Tabii en yaşlılığa kadar gereksinimli seçimler...

Hepsi mimarınıza teşekkür yüklenecek

Ve o mahallede bakışan gözlerdeki ışıklar

Sıcak tebessümle sabah işe akşam eve gelirken…

Korkmayın, mimarınız size serüvenin bir tek anını

Dahi yoklatmayacak

Dünyayı bir kez dolaşanlardan daha zengin

O renklilik, o yorgunluk, taşkınlık, şaşkınlık

Bir ev sahibi oluyorum maceranız

Sesli sessiz, renkli-donuk, hareketli-çorak

Tüm enerjinizi tüketmeye hırs ve kabuslu gecelere

Enfes eşdeğerlikte olacak…

Bu bedel ödenmez mi sizce? 

01.03.1999', 'Güzel dinlendiriciliği ile sohbeti zengin Kimi roman, her yemek kitabı  Şüphesiz tüm masallar, ne çok efsaneler Tarihi yapılardan, harabe, s...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bir-evim-olsun-bu-bedel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya da Ölüm Var', 'dunya-da-olum-var-yusuf-onder-bahceci-6rhvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar,

Namazında kırk kişi olursa belki Cennetlik olur duyarlar,

Hoca Efendi sorar, sorar, mevtayı nasıl bilirdiniz Beyler,

Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar.

Ne verirsen elin ile, o da gider senin ile, güzel amelinle,

Gel sen bu sözlerimi, cân kulağı ile dinle, geceleri, inile,

Kullar Cennete giderler ancak güzel, güzelce kulluğu ile,

Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar.

Ölüm ani gelir hesabını vermez, hedefiniyse saptırmaz,

Önder  öleceğini unutmaz, unutmaz, Allah''ını unutamaz,

Bu Dünya''da ölüm varken mutlu olmaz, olamaz, olmaz,

Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar.

Ey Şeytanı Lâini dost edinen, türlü dalavereler çeviren,

İnsanları masum olarak katleden, Allah''dır belanı veren,

Aldığı cânların karşılığı bir gün canavarlar gibi geberen,

Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar.', 'Ey bu Dünya''ya gönül veren, bir gün musallaya koyarlar, Namazında kırk kişi olursa belki Cennetlik olur duyarlar, Hoca Efendi sorar, sorar, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-da-olum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyün Dedesi', 'koyun-dedesi-aynur-avci-mipln', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelinlere söylenirsin

Evlatlarla övünürsün

Acı dolu yüreğinle

Etraflarda gezinirsin

Yüzünden belli oluyor

Yorgun yılların

Derin izleri

Sen bu köyün babası,

Mavi gözlü dedesisin.

Toprak kokan ellerin

Allaha,adanmış yüreğin

İnsanlara sigortalanmış emeğin

Herkesin ziyaretine gittiğin

Peşinden dualar ettiğin

Sen bu köyün babası,

Mavi gözlü dedesisin..', 'Gelinlere söylenirsin Evlatlarla övünürsün Acı dolu yüreğinle Etraflarda gezinirsin Yüzünden belli oluyor Yorgun yılların Derin izleri Sen b...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koyun-dedesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avutamaz', 'avutamaz-aynur-avci-q30hm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu dünyayı verseler istemem

Sesini duymayınca.

Ayı güneşi verseler istemem

Seni görmeyince

Yağmuru şimşeği verseler istemem

Gözyaşım durmayınca

Avutamaz beni hiç bir gezegen

Seni bana getirmeyince..', 'Şu dünyayı verseler istemem Sesini duymayınca. Ayı güneşi verseler istemem Seni görmeyince Yağmuru şimşeği verseler istemem Gözyaşım durmayı...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/avutamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dadaşım', 'dadasim-halil-colak-sbjkn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dadaşın elinde sopa oynatır altında atı

Cirit meydanında şahlandırırda kıratı

Kırat kişnemesiyle inletirde meydanı

Cirit meydanına da sığmaz  dadaşım

Mertlik vardır dadaşın cirit oynayışında

Zarafet vardır cirittin havada gidişinde

Hünerler gösterilir cirit meydanında

 Cirit meydanına da sığmaz  dadaşım

Seksenlik emim ciridi  da tutar havada

On beşlik delikanlı topuk vurur kırata

Yağız atlar meydan vermez de dor ata 

Cirit meydanına da sığmaz  dadaşım

Halil Çolak 1.3.2006 Ankara', 'Dadaşın elinde sopa oynatır altında atı Cirit meydanında şahlandırırda kıratı Kırat kişnemesiyle inletirde meydanı Cirit meydanına da sığmaz...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dadasim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilingir Sofrası', 'cilingir-sofrasi-aynur-avci-7tpof', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel sevgilim

Çilingir soframızı

Çam dibine kuralım

Kahve gözlüm

İçelim geceye

Böyle yaşayalım

Kadehler dolsun

Aşka-sevgiye

Sabah olmasın

Sıkı sarıl bana

Bizi kimse ayırmasın

Gel sevgilim,

Çilingir soframızı

Çam dibine kuralım

Kahve gözlüm

Her anı,böyle kulayalım

Her anı böyle yaşayalım..', 'Gel sevgilim Çilingir soframızı Çam dibine kuralım Kahve gözlüm İçelim geceye Böyle yaşayalım Kadehler dolsun Aşka-sevgiye Sabah olmasın Sık...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cilingir-sofrasi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan İnsanın Kurtudur', 'i-nsan-i-nsanin-kurtudur-mehmet-akif-tiryaki-wn9wy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İslamda insanlar sevilir,

Sana taş atana sen ekmek at denir,

Ağızdan çıkan kelimeler özenle seçilir,

Çarşılarda kartlarla kredi çekilir

Eşyalar eskir, kredi ertelenir,

Faiz kartopu gibi büyür,

Ödemeler birbiri ardından gelir,

Enflasyon yüzde altı,

Kart faizleri yüzde yüzkırkaltı,

Bunu yaşamayan ne bilir,

Darbe olursa Ankara''da

Sabaha karşı tank sesleri gelir,

Birileri radyodan seslenir,

İkindiden sonra evlerde çay demlenir,

Olay tarih aynasından gözlenir.', 'İslamda insanlar sevilir, Sana taş atana sen ekmek at denir, Ağızdan çıkan kelimeler özenle seçilir, Çarşılarda kartlarla kredi çekilir Eşya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insan-insanin-kurtudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-40 Mektup', 'yb-40-mektup-mehmet-coban-qydnp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah yolda idim

Kalabalıkla çevrildim

Toplanmış insanlar

Aralarında konuşuyorlar

Ölmüştü bir komşumuz

Kesilmişti yolumuz

Yüzler asık, 

Dillerde ağıt

Yükseliyordu sürekli

Bakışlar ürkekti

İntihar ölüm sebebi 

Bilinmiyor nedeni

Kimi; yazık diye acıyordu 

Kimi; hak etti diyordu! ....

Birkaç gün sonra

Okudum basından

Söz ediyordu intihardan

Haber vardı 

İntihar mektubundan

Hızla okudum haberi

Öğrenmek için nedeni

“Ben emekli olmuş

Bir devlet memuruyum

İçimde acı,

Dışımdan mutluyum

Yıllar yılı çalıştım

Devlet için dolaştım

Verdiği maaş yetmedi

İstekler hiç bitmedi

Sonra uydum düzene

Evet dedim her gelene

Zenginler geldi evet

Rüşvetler geldi evet

Suiistimal geldi evet

Haksızlık geldi evet

Kayırma geldi evet

Ama hakkı getiremedim

Çocuklarıma,

Helal lokma yediremedim

Garibanın işini süründürdüm

Arkası olanı güldürdüm! ...

Ailemi, çocuklarımı düşündüm

Onlara lüks bir hayat sürdürdüm

Ama gelin görün ki 

Hep böyle gitmedi

Bir gün çaldı kapımı

Adamakıllı özeleştiri

Yaktı kavurdu beni

Önüme koydu geçmişi

Haksız yaptıklarım

Karabasan uykularım

Çaldığım çırptığım

Sonsuz karanlığım

Benliğimi sardı

Uykularımı kaçırdı

Gece, gündüz karıştı

Günler birbiriyle yarıştı

Bulamadım iç barışı

Artık ailemin,

Bakamıyorum gözlerine

Gülemiyorum sözlerine

Ya insanlara, 

Bakamıyorum onlara

Konuşamıyorum onlarla

Onların gözlerine 

Her baktığımda

Yaptıklarım geliyor

Sürekli aklıma

Açılamıyorum 

Anlatamıyorum

Acımı paylaşamıyorum

Ben her gün yanıyorum

Onların her sözünde

Kuruluyor mahkeme

İçten içe yargılanıyorum

Bir türlü kurtulamıyorum

Kendimi ailemi düşünerek

Yaşamak ve yaşatmak için

Yaptığım her şey

Oldu bana mahkeme

Ne hüküm veriyor

Ne beraat ettiriyor

Her gün süründürüyor beni

Karartıyor sürekli günlerimi

Pişman olsam ki, oldum

Af dilesem ki, diliyorum

Ama bunları söyleyemiyorum

Ama bunları haykıramıyorum

Ben her gün yanıyorum

Ben her gün ölüyorum

Bu gün buna son veriyorum

Yüzünüze haykıramadıklarımı

Satır, satır size bırakıyorum

Suçlu aramayın, 

Suçlu; ne o, ne şu, ne bu! ..

Suçlu benim, 

Yalancı yaşantım, benliğim,

Yalancı umutlarım, hayallerim! ..”

Gözlerimden yaş akıyordu

Kalbim acılı yanıyordu…

Aklımdan düşünceler geçiyordu…

Ah be kardeşim, 

Koyamadık kalbine sevgiyi

Koyamadık önüne gerçeği

El veremedik dertlerine

Biliyorum şimdi birçoğu

Hak etti namussuz diyecekler

Ölümü verip, cezayı keserek

Kolay yolu seçecekler

Önemli olan gerçeğin, 

Yaşatmak olduğunu bilmeyecekler! ..

Gözlerinin önünde olan 

Her gün binlerce insanı öldüren

Asıl gerçeği bir türlü göremeyecekler! ..

Suçlu ayağa kalk! ...

Şunu, şunu yaptın

Al cezanı, çek artık

Deyip yan gelecekler

Ölüleri diriltmeyecekler

Yaşarken mezara gömüp

Asla yeşertmeyecekler! ..

Gözlerim doldu, 

Ufukta ölüme koşanlarla boğuldu..

Kalbim acıyla yandı, 

İntiharını hazırlayanlar vardı..

Ve, insanlar onları kurtaramadı! ..

Ve, insanlar onları cezalandırdı! ..

Ve insanların kalbinde, 

Sevgi, merhamet yerine

Sadece kin ve ceza vardı! ..

01.03.2006-İzmir', 'Sabah yolda idim Kalabalıkla çevrildim Toplanmış insanlar Aralarında konuşuyorlar Ölmüştü bir komşumuz Kesilmişti yolumuz Yüzler asık,  Dill...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":131,"source_url":"https://www.antoloji.com/yb-40-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuduğum Gazete', 'okudugum-gazete-mehmet-akif-tiryaki-8lxxc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Türkiye''de enflasyon yüzde yedi,

Bu gün okuduğum gazeteye yüzde yirmi zam geldi,

Canım sıkıldı,

Onu da artık okumayacağım,

Fiyatına değil,

Yüzde yirmiden.

Zaten bir yazarı takip ediyordum,

Onu da internetten izlerim,

Bu kafayla gidin, Allah selamet versin.

Gazete okuma alışkanlığı kitaba geçsin.

İsteyen istediğini seçsin.', 'Türkiye''de enflasyon yüzde yedi, Bu gün okuduğum gazeteye yüzde yirmi zam geldi, Canım sıkıldı, Onu da artık okumayacağım, Fiyatına değil, Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/okudugum-gazete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonrası Hayırdı...', 'sonrasi-hayirdi-elvan-genc-3oiz8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sinesinden bir gün umudun,

Ak pak bir bulut ayrıldı...

Bu parçalı hava o zamanlar

Pek beyazdı

Uzaklaştıkça maviliğinden göğün

Silindikçe umulmadık hayaller

Bir ağırlık kapladı

Bu hallaç pamuklarını..

Soluklandı bir dost kahvesinde

İki laf etti....

Yolcu yolunda gerek

''Devam'' dedi

Her gün koyulaşan bedenine

Niyesini bilmiyordu hüznünün

De sonu belliydi....

Gülen güneş, kartopu beyazlıklar

Çıktı bir gün karşısına aceleci

''Dur'' dedi çöreklenen karasına bulutun

Daha cevap veremeden 

Bu anlamsız öfkeye

Büyük bir gürültü koptu

Umudun rengi artık karaydı...

Ama umut ağlıyordu

Şıpır şıpır damlıyordu

Çözüyordu islerini

Yıkanıyordu vesveselerinden

Yarında sevgi vardı

Yarında ışıl ışıl güneş vardı

Ak pak bulut olmak vardı

Sonrası hayırdı...

Rahatça soluklandı bulut

Yarında umut vardı...

06.08.2002/Salı', 'Sinesinden bir gün umudun, Ak pak bir bulut ayrıldı... Bu parçalı hava o zamanlar Pek beyazdı Uzaklaştıkça maviliğinden göğün Silindikçe umu...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sonrasi-hayirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazım Abi Farkındamısın', 'kazim-abi-farkindamisin-mehmet-akif-tiryaki-4m1rx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kazım Abi farkındamısın,

Karaköy''den Aksaray ne kadar yakın.

Farzet ki cebinde paran yok,

Yürüyerek on dakikada Aksaray''dasın.

Ne ne gerek senin Halkalı,

Her gün iki saat yol, o da kapalı.

Ha metro diyeceksin haklısın,

Sen bu konularda herkesden farklısın.

İleri görüşlü ve entelsin,

Her konuda rahmetli babana benzersin,

Hata yapan siyasetçileri hemen enselersin,

Doğrumu dediklerim ha,

Ne dersin...', 'Kazım Abi farkındamısın, Karaköy''den Aksaray ne kadar yakın. Farzet ki cebinde paran yok, Yürüyerek on dakikada Aksaray''dasın. Ne ne gerek s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kazim-abi-farkindamisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Ol', 'asik-ol-turan-tuncer-kb9e8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AŞIK   OL

Ne ayrılığa kur saatleri

Nede 

Vuslata

Sen 

Sen ol

Ama

Önce 

Aşık ol

21-09-2005/İst

Alkadraz_Kuşcusu', 'AŞIK   OL Ne ayrılığa kur saatleri Nede  Vuslata Sen  Sen ol Ama Önce  Aşık ol 21-09-2005/İst Alkadraz_Kuşcusu...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asik-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Hayaller Ölür (2)', 'once-hayaller-olur-2-turan-tuncer-y4xbt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖNCE HAYALLER ÖLÜR  (2) 

Sen hiç 

Bulutlara hamak kurdunmu? 

Hayaller yaratıp

Hayal zengini oldunmu? 

Hiç kocaman çocuk olup

Sevdiğinin gözlerinde

Bilyeler gördünmü

Yeşil yeşil

                Bazende ela bakan

Korkuların oldumu? 

İçindeki ışık

                Ya kırılırsa

                       Ya sönerse

Ya yaralanırsa 

                        Hayalleri 

İçindeki çocuğun

Sen umutlarını 

Bırakıpta gittinmi? 

                              Kaldırımlarda

Hiç arkana bakmadan

Küçük insanların 

                           Umutları olur

Büyük insanların 

                            Hayalleri

Tut at beni kör kuyulara

Önce hayallerim ölsün

08-02-2005/İst

Alkadraz_Kuşcusu', 'ÖNCE HAYALLER ÖLÜR  (2)  Sen hiç  Bulutlara hamak kurdunmu?  Hayaller yaratıp Hayal zengini oldunmu?  Hiç kocaman çocuk olup Sevdiğinin gözl...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/once-hayaller-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Çoban Yıldızım', 'gozleri-coban-yildizim-turan-tuncer-rk6x8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÖZLERİ ÇOBAN YILDIZIM

Bindokuzyüzaltmışiki

Onaltı

Yirmi

Yirmiyedi

Kırküç

Bana hiç sormadılar

Emri vaki oldu doğmam

İlk aşkımdı,

                  İlk sabıkam

Tam yirmi ayım çalındı

                                Bana sormadan

Bu dahada kötüsü

Hayatıma ipotek koyuldu

İşte bu çok farklı

Sanki yeni doğdum

Hayat bir başka güzel

Daha önceleri nerelerdeydin? 

Gözleri

            Çoban yıldızım

08-02-2005/İst

Alkadraz_Kuşcusu', 'GÖZLERİ ÇOBAN YILDIZIM Bindokuzyüzaltmışiki Onaltı Yirmi Yirmiyedi Kırküç Bana hiç sormadılar Emri vaki oldu doğmam İlk aşkımdı,            ...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozleri-coban-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Şiirlerim', 'yorgun-siirlerim-yusuf-onder-bahceci-yy3sk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yorgun şiirlerime bir şiir daha ekleyeyim,

Bir şiir değil, yüzbin şiir eklesem ne diyeyim,

Vefasız yâre diyecek daha ne kaldı, diyeyim,

Bu yorgun şiirlerime bir şiir daha ekleyeyim.

Şiir yazmak marifet mi sevdiğin geri gelirmi,

Çok hata etmişim be etmişim der mi,der mi,

Yoksa seni bir böcek gibi yıllar boyu ezer mi,

Bu yorgun şiirlerime bir şiir daha ekleyeyim.

Sahi biz neden ayrıldık, sevmedik, demedik,

Onun, bunun sözü ile hareket ettik bilemedik,

Allah''ım bu nasıl iş, nasıl sevmedik demedik,

Bu yorgun şiirlerime bir şiir daha ekleyeyim.



Sana erkekçe diyemediğimi, şiirle diyeyim,

Eğer şiirleri okuyarsan, açık, açık, söyleyim,

Sade seni sevdim olmadı, olmadı be deyim,

Bu yorgun şiirlerime bir şiir daha ekleyeyim.', 'Bu yorgun şiirlerime bir şiir daha ekleyeyim, Bir şiir değil, yüzbin şiir eklesem ne diyeyim, Vefasız yâre diyecek daha ne kaldı, diyeyim, B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorgun-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku Bunu Yaygaracı', 'oku-bunu-yaygaraci-turan-tuncer-zyzxo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'OKU BUNU YAYGARACI

Yayılırsın çimene, ithal deyip söversin

Üzüm yemek istemez, sen bağcıyı döversin

Hayatın hep ''SİESTA'', iş yapanı yerersin

Dikili ağacın yok, gölgesinde yatalım

Bir kaşık suda koparırsın fırtına

Senin gibi embesil çok, hemen düşer ardına

Hayat kötü değil, sana göre ''büyükler yer küçüğü''

Bir halt beceremiyorsun,

                 Yapana saygı duy (ZARGANA) 

Normal değilsin sen, beyninin üstüne oturuyorsun

Sana kimse benzemez, bunuda yanlış biliyorsun

Doğada her varlığın bir görevi var, OT''un  B...''un

Ben çözemedim, sahi sen ne halta yarıyorsun

İyi bak tarihe, bütün büyük savaşlar

Baltaya sap olamamış, bir cahil ile başlar

Atomuda tıp için bulmuştu, embesil kullandı savaşta

Okuması olmayana, kullanma klavuzu ne yapsın

Okumayı sökmüşsün, kendini alim sanıyorsun

Bakar-görmez, duyar-anlamaz, beyin olmaz inekte

Bunu bilir her fani, bir sen bilmiyorsun

3,5 yaş IQ ile, bir halt yaptım sanıp saçmalıyorsun

Kimi emanette olsa tohumu, hizmet için diker ağacı

Meyvesi olmazsada, gölgesinde serinler bir yolcu

Ben ''Kuşcu''yum'' ey embesil, buda sana son nasihat

Doğuştan kel ve kösesin, traş senin neyine

Bu şiir sana ip ucu, girer belki olmayan beynine

17-07-2005/İst

Alkadraz_Kuşcusu', 'OKU BUNU YAYGARACI Yayılırsın çimene, ithal deyip söversin Üzüm yemek istemez, sen bağcıyı döversin Hayatın hep ''SİESTA'', iş yapanı yerersin...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/oku-bunu-yaygaraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın İnsanı ve ''Dolduruş''-2', 'zamanin-i-nsani-ve-doldurus-2-omer-dalman-zhl19', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dedik ya

Zamanın İnsanı ne de çabuk dolduruşa gelir! 

iş''te bir çay arasında veya

kallavi donatılmış bir rakı masasında

biri bir şey atar ortaya; örneğin ''spor''...

hemen coşar ''yalancı gönüller'' 

dumanın ve rakı kokularının alkışlarıyla

herkes sporcu kesilir,

onca büyümüş

yerinden kalkamaz göte göbeğe bakılmadan

(nas''olsa masa var ya, gizliyor!) 

ertesi gün herkes ne koşulara başlama

dumble''larla kol antrenmanları

yüzmelere kesintisiz devam etme sözleri verir! 

naralar atılır vahşi Vikingler gibi

kahkahalara bulanır sarhoş masa! 

ama göt-göbek büyürken

kokuşmuş, yıllanmış koltuklarda otura otura

iş bitirici ve bitirim tavırları atmaya benzemez bu iş! 

Kalkman lazım oturduğun yerden

köklenmiş kıçını kazıman lazım o rahat koltuktan! 

laf üretmeye, araba ile bakkala gitmeye

fiyatına göre konuşmaya benzemez bu iş! 

bilirim

lafa gelince nasıl da coşarsın

Ey Zamanın İnsanı! 

o penguen gibi takım elbiseleri geçirdiğinde

nasıl da kendini ''manken'' gibi görür

aynaların karşısında zaman harcarsın! 

bilirim! ..

(Mart 2006)', 'dedik ya Zamanın İnsanı ne de çabuk dolduruşa gelir!  iş''te bir çay arasında veya kallavi donatılmış bir rakı masasında biri bir şey atar or...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zamanin-insani-ve-doldurus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etik Değil', 'etik-degil-edip-caki-m7mvz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'etik değil

göz kapaklarımın arkasına

patavatsız gülüşler döşemek

don kişotluğuma

değirmenler döndürmek

etik değil

kısır bir kelebeğin kozasına

anlık yaşamlar zehretmek

tabakamdan yakılan tütünün dumanını

iblis bir şiir gibi yüzüme üflemek

etik değil

nazımlığımı sürgünlere yol etmek

ve bir ölüm sessizliğine methiyeler düzmek 

akıl karı değil

etik değil

çıplaklığımdan nehirler akıtmak

tenimi ateşlere yem etmek

de vur gitsin artık

fi tarihinden beri yaşarım

ama...

havvanın üryanlığına

ademin aşkına ve 

bir elmanın yasaklığına

eski bir yalnızlığı reva görmek

etik değil

kaburgamdan yaratıldı aşk

lakin aşk etik değil

ustalığıma ustamdın

ama artık ustam değilsin', 'etik değil göz kapaklarımın arkasına patavatsız gülüşler döşemek don kişotluğuma değirmenler döndürmek etik değil kısır bir kelebeğin kozası...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/etik-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevemedim Ölüm', 'seni-sevemedim-olum-turan-tuncer-6gmf3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SENİ SEVEMEDİM ÖLÜM

Ölüm! 

Haber vermez,

Tekmil ufuklar,

Kışladı içimde

Dört yanım ayaz keser

Yedi iklim bahar bahçe

Dağlarına, kıran vura yurdunun

Devrilsin sırasına dalların

Ölüm, bana koymazdı ya

Olmayaydım

                    Sevdanın en karasında

Yaşamasaydım

                         Ömrümün 

En güzel aşk hasadını

Karadır! 

          Bedenin ölüme yenik

                        Yenik düştüğü gece

Yürek param parça

Bütün umutlar,

              Dağılmışta orta yerinden

Savrulmuş, sere serpe geceye

Boynum kıldan ince

''Sen hiç sevmedinmi ölüm''

05-06-2005/İst

Alkadraz_Kuşcusu', 'SENİ SEVEMEDİM ÖLÜM Ölüm!  Haber vermez, Tekmil ufuklar, Kışladı içimde Dört yanım ayaz keser Yedi iklim bahar bahçe Dağlarına, kıran vura y...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-sevemedim-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüller Sultanı', 'gonuller-sultani-yusuf-onder-bahceci-oz1wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hace Muhammed Bahaeddin Şah-ı Nakşibend,

Evliyanın büyüğünden olur elinde vardır kemend,

O gönüllerin sultanıdır, o ki kötülüklere olur bend,

Hace Muhammed Bahaeddin Şah-ı Nakşibend.', 'Hace Muhammed Bahaeddin Şah-ı Nakşibend, Evliyanın büyüğünden olur elinde vardır kemend, O gönüllerin sultanıdır, o ki kötülüklere olur bend...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonuller-sultani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık (2)', 'ayrilik-2-turan-tuncer-2hujg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğine bir hüzün takılmış

Demirlemişte

                     Mavisine gözlerinin

Bütün ayrılıklar

Plaklarda ayrılık şarkıları çalıyor

Bütün 

            Zamanlara inat

Şarkılar öylesine eski

Babil''li kimi 

                   Kimi Hatuşaş''lı

Öyle ise ayrılık

Sevmektende yaşlı

Duygularım kuş misali

Hep sevgilere uçar da

Yüreğim,

Ayrılığın öksesinde tutsaktır

Biçare, umarsız

Uçamaz

Tutulmuştur kanatlarından

Çaresizlik tuzağına

Ayrılıklar üstüne

Bütün umutların yolculuğu

Garlarda trenler

                     Koylarda kalyonlar

Bir kırık taş plak

                           Yine o şarkı

................../İst

Alkadraz_Kuşcusu', 'Yüreğine bir hüzün takılmış Demirlemişte                      Mavisine gözlerinin Bütün ayrılıklar Plaklarda ayrılık şarkıları çalıyor Bütün...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayrilik-2-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Bileceksin', 'nereden-bileceksin-turan-tuncer-tqxao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'NEREDEN BİLECEKSİN 

Akrebin ayaklarına 

Betonlar dökmüşsün

Kesmekte yelkovanın yolunu

Yüreğindeki saatleri 

Beklemelere kurmuşsun

Takvimlerin 

Sonsuz uykularda

Oysa sana

Gecelerimden

Yakamozlar, mehtaplar

Günlerden

Ağustos sıcaklarını 

Getirmiştim

Nereden bileceksin

Kar oldum da eridim

23-09-2005/İst

Alkadraz_Kuşcusu', 'NEREDEN BİLECEKSİN  Akrebin ayaklarına  Betonlar dökmüşsün Kesmekte yelkovanın yolunu Yüreğindeki saatleri  Beklemelere kurmuşsun Takvimleri...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nereden-bileceksin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmam-ı Rabbani', 'i-mam-i-rabbani-yusuf-onder-bahceci-jixlc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İmam-ı Rabbani Müceddid-i Elfi Sani Ahmet Faruk-i Serhendi,

İkibin yılın müceddidi o gönüller sultanı o ki müceddidi elfi sani,

Oku kâlbinden kâlbine feyiz akar kitabıdır Mektubat-ı Rabbani,

İmam-ı Rabbani Müceddid-i Elfi Sani Ahmet Faruk-i Serhendi.', 'İmam-ı Rabbani Müceddid-i Elfi Sani Ahmet Faruk-i Serhendi, İkibin yılın müceddidi o gönüller sultanı o ki müceddidi elfi sani, Oku kâlbinde...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/imam-i-rabbani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Sevdaları', 'guz-sevdalari-turan-tuncer-61g8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜZ  SEVDALARI

Dinlediğim 

Hala, o eski şarkı

İçimdeki

              Sarhoş akşamlara

Düşmanım 

                  Şarkılara,şiirlere

Küskünüm

Adındaki hecelere

Elimde

Yorgun yaşamlar

İçimde

Güz yangınları

Birikmiş te içime 

Bütün yenilgiler

Kucaklarım

                  Yetim karanlıkları

Kurumuş 

Bir gül yaprağı

Yüzleri solmuş

                       Bir kaç resim

Elimde 

Kırılmış güz sevdaları

Sığınırım

              Yetim gecelere

15-09-2005/İst

Alkadraz_Kuşcusu', 'GÜZ  SEVDALARI Dinlediğim  Hala, o eski şarkı İçimdeki               Sarhoş akşamlara Düşmanım                    Şarkılara,şiirlere Küskünü...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/guz-sevdalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-turan-tuncer-0mthv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ANADOLU

Adın bereket olmuş yüz yıllardır

Ya hayali olmuşsun

Ya girmişsin düşlerine

Bir bitmeyen sevda

Beşiği olmuşsun medeniyetlerin

Bilgelik tarihin olmuş

Varlığın

         Var oluşun karanlığına bir ışık

Adın ''ANADOLU''

Geçen yüz yıllar bozamamış

                                         Bekaretini

Yıkılmamış, yılmamışsın

Adının ya bir afetle

Yada büyük savaşlarla anılmasından

Kah sevda olmuşsun

Adın Kerem olmuş, Ferhat olmuş

İki telde dile gelmişsin

Karacaoğlan, Pirsultan''la

Kah adalet olmuşsun aleme

Mühüründe Fatih''in, Süleyman''ın

Kah adın acının yurdu olmuş

Tuz basmışsın acılarına ağıtlarla

Sakarya''da, Afyon''da

Adın ''ANADOLU''

Ana''sın yüreği sevgi dolu

Başımı omuzuna koymak ne güzel

23-05-2005/İst

Alkadraz_Kuşcusu', 'ANADOLU Adın bereket olmuş yüz yıllardır Ya hayali olmuşsun Ya girmişsin düşlerine Bir bitmeyen sevda Beşiği olmuşsun medeniyetlerin Bilgeli...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anadolu-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Başlamak', 'yeniden-baslamak-cengiz-kapusuz-kypd4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittiğin yerde,

Hala ağlıyorum ben.

Beni de ağlattın ya...

Onca yaşanmışların ardından,

Arkana bile bakmadan.

Düşman kafasına sıkılan,

Kurşun misali,

Çektin vee

Gittin.

Gel şimdi bak bana,

Ne halde bıraktın.

İşe yaramaz kağıt parçası gibi,

Buruşturup,

Attın vee,

Yaktın.

Ama dur,

Dur daha bitmedi.

Artık ağlamayacağım,

Ayağa kalktım.

Unuttum seni.

Geleceğe umutla bakıyorum,

Yeniden başlar gibi.

Cebimden çıkarıp,

Bir sigara yakıyorum.

Uğurlar olsun diyorum.

Ben şimdi hayata

Yeniden başlıyorum...', 'Gittiğin yerde, Hala ağlıyorum ben. Beni de ağlattın ya... Onca yaşanmışların ardından, Arkana bile bakmadan. Düşman kafasına sıkılan, Kurşu...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yeniden-baslamak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim İşte', 'sevdim-i-ste-turan-tuncer-tk4yj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVDİM  İŞTE

Şehir aşkları

Bana göre değil

Varsın

Benim sevdam

Düzeyli olmasın

Kaba saba

Ama 

Ruhu olsun

Ben seni

Ölesiye değil

Ben seni

Karasabanın toprağı

Sevdiği gibi

Senin için yaşayacak  kadar

Çok sevdim

Ben 

Düzeyli ilişkilerin

Güncel donjuanı değilim

Derdim

Vitrinindeki

Sergilediğin et de değil

Ben senin 

Yüreğini sevdim

Ben senin

Gözlerindeki ışığı

Ben 

Sendeki

Beni sevmeni sevdim

12-10-2005/İst

Alkadraz_Kuşcusu', 'SEVDİM  İŞTE Şehir aşkları Bana göre değil Varsın Benim sevdam Düzeyli olmasın Kaba saba Ama  Ruhu olsun Ben seni Ölesiye değil Ben seni Kar...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevdim-iste-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacı Muhammed Şükrü', 'haci-muhammed-sukru-yusuf-onder-bahceci-g1jo9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şanlı Urfa Hazreti Hamza Camiinde medfun,

Hacı Muhammed Şükrü Şirazi babam oldun,

Sen Allah''a ve Resulüne ne güzel bir kuldun,

Şanlı Urfa Hazreti Hamza Camiinde medfun,

Hacı Muhammed Şükrü Şirazi babam oldun.', 'Şanlı Urfa Hazreti Hamza Camiinde medfun, Hacı Muhammed Şükrü Şirazi babam oldun, Sen Allah''a ve Resulüne ne güzel bir kuldun, Şanlı Urfa Ha...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/haci-muhammed-sukru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaaddin Uygun Hocaya', 'alaaddin-uygun-hocaya-yasar-tezel-pg86o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hergün elinde üçbeş gazete

Azarbeycan kafede

içilmeyi unutulmuş soğuk çayı

Makaleler,kütahya gündemi

Sigarasını derin derin çeken,

Arasıra çay molası

Neşeli insan

İnananlarıda unutma

Lütfen 

Hocam

Gönül dünyası', 'Hergün elinde üçbeş gazete Azarbeycan kafede içilmeyi unutulmuş soğuk çayı Makaleler,kütahya gündemi Sigarasını derin derin çeken, Arasıra ç...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alaaddin-uygun-hocaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana Celaleddin-i Rumi', 'mevlana-celaleddin-i-rumi-yusuf-onder-bahceci-5jj4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Konya''da Gönüller Sultanı Mevlana Celaleddin-i Rumi,

Gel, gel, ne olursan ol yine de gel, gel, gel diyor, diyor,

Sakın yanlış anlamayalım, gel de insan-ı kamil ol diyor, 

Konya''da Gönüller Sultanı Mevlana Celaleddin-i Rumi.', 'Konya''da Gönüller Sultanı Mevlana Celaleddin-i Rumi, Gel, gel, ne olursan ol yine de gel, gel, gel diyor, diyor, Sakın yanlış anlamayalım, g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mevlana-celaleddin-i-rumi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü Sevmek', 'gulu-sevmek-turan-tuncer-zquep', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜLÜ   SEVMEK

Hiç 

Aklına gelirmiydi? 

Söyleseler...

İnanırmıydın? 

Güllerin 

Sevgisi yalan

                     Karanfillerin kokusu

Bülbül boşa yanmış

Hiç düşünebilirmiydin? 

İçindeki

Her şey anlamsız,

                            Dünyanın

Demek ki 

Yalanmış

Aşk denen o duygu

Demekk ki 

Aldatmış gül, bülbül''ü

Ucuz bir diken ile

Bülbül ölümüne

Gül''ü severken

04-04-1995/Adana

Alkadraz_Kuşcusu', 'GÜLÜ   SEVMEK Hiç  Aklına gelirmiydi?  Söyleseler... İnanırmıydın?  Güllerin  Sevgisi yalan                      Karanfillerin kokusu Bülbül...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulu-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz', 'siz-sema-figen-akdogan-yba7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hanginiz ilgilendiniz yüreğimle,dokunmadınız ellerinizle bile.

Yapayalnız bıraktınız beni.

Duygularımı kaybettim,sözlerimi tükettim.

Kan damlayan yüreğimdeki yama üzerine yama vurduğum umutlarıma sarıldım.

Yalnızdım.

Şimdi kalkmış hesap soruyorsunuz! 

Bu halin nedir diye utan diyorsunuz.

Daha önce nerdeydiniz? 

Daha önce kimdi bana bunları soran.Siz miydiniz? 

Yaş çok geç belki ama ben değil asıl siz siz kendinizden utanın.

Beni bu hale getirdiniz diye.', 'Hanginiz ilgilendiniz yüreğimle,dokunmadınız ellerinizle bile. Yapayalnız bıraktınız beni. Duygularımı kaybettim,sözlerimi tükettim. Kan dam...', ARRAY['Türk Edebiyatı','Şiir','Sema Figen Akdoğan']::text[], 8.5, '{"poet":"Sema Figen Akdoğan","poet_slug":"sema-figen-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Kokulu Egin Kızına', 'cennet-kokulu-egin-kizina-sema-figen-akdogan-q0exb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine sustum ve birileri bana yutkunmamı söyledi. Kitaplarında hayata veda ettim.Olmadı mı olmuyor.Bildiğim tek şey var, sen bensin.Ruhumu kaybetmiştim.Geri ver!', 'Yine sustum ve birileri bana yutkunmamı söyledi. Kitaplarında hayata veda ettim.Olmadı mı olmuyor.Bildiğim tek şey var, sen bensin.Ruhumu ka...', ARRAY['Türk Edebiyatı','Şiir','Sema Figen Akdoğan']::text[], 8.5, '{"poet":"Sema Figen Akdoğan","poet_slug":"sema-figen-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/cennet-kokulu-egin-kizina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gıcık-Mıcık', 'gicik-micik-munevver-erilmez-l73e0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kabak lâstik takanlara,

Boşa korna çalanlara,

Çok gıcık oluyorum.

Yolda zikzak çizenlere,

Başkasının hakkını alanlara,

Çok gıcık oluyorum.

Zamanımı çalanlara,

Sözünde durmayanlara,

Çok gıcık oluyorum.

Zilzurna içenlere,

İçip, içip sızanlara

Çok gıcık oluyorum.

Yolda kaza yapanlara,

Bırakıp ta kaçanlara

Çok gıcık oluyorum.

Trafiğe  uyanları,

Işıklara  bakanları,

Hayatta sağ kalanları

Hürmetle selâmlıyorum.', 'Kabak lâstik takanlara, Boşa korna çalanlara, Çok gıcık oluyorum. Yolda zikzak çizenlere, Başkasının hakkını alanlara, Çok gıcık oluyorum. Z...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gicik-micik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kaçıncı Veda Edişim....', 'bu-kacinci-veda-edisim-dursun-elmas-1tn8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı ayrılışım,

Bu kaçıncı gözyaşım

Bu kaçıncı veda edişim

Ama,birtürlü terkedemediğim...

Sahi; 

Sizler kadar temiz,lekesiz

Sizler kadar masum,günahsız

Sizler kadar sahice

Ve sizler kadar riyâsız

Başka kim varki şu cihanda

Kuşlar kadar hür

Fakat kanatsız...

Ey! 

Ağlamaktan gözleri yanan

Bahar gözlü Ayşenur! 

Mor bakışlı Özge,

Karatalihli resimci Yağmur,

Yeni yetme Edanur...

Ay yüzlü,al yanaklı Kübra

Yemek yemeyen Büşra,

Masum bakışlı Gülây

Kınalı Emine,güllü Gülsüm

Boncuk Meryem

Eski başkan Ayşe...

Çıtır İrem,

Boynu bükük Sümeyye

karagözlü Gurbet

Lafazan Nigâr

Ve ürkek ceylan bakışlı Nilây! ..

Sen; 

Fidan boylu Eyşan

Gül Gonca''sı,gamzeli Sevda,

Afacan Furkan

Matematikçi Sultan...

Meryem''li Hatice

Muratoğlu Ahmet,Onur,Şevket

Mustafa,Enes, Misbah

Recep,Kadir İbrahim...

Pasif Esra

Yaramaz Yunus,Fevzi ve Yusuf

Topçu Ertuğrul

Demir Aysel,

Bayraklı Leyla

Ve Deregözü Ahmet...

Hepinizi...ulan hepinizi seviyorum! ..

Hem de çok! ..

Açın yüreğinizi,

Yüreğinizi bana getirin

Yüreğinizden öpeceğim

Size son defa veda edeceğim! ..

01.03.2006

Bu gün yaklaşık 18 aydır beraber olduğum minik sevgililerimden ayrıldım.', 'Bu kaçıncı ayrılışım, Bu kaçıncı gözyaşım Bu kaçıncı veda edişim Ama,birtürlü terkedemediğim... Sahi;  Sizler kadar temiz,lekesiz Sizler kad...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bu-kacinci-veda-edisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıllı', 'akilli-mehmet-akif-tiryaki-ccntx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki el ve iki yüzük bir gözlük,

Yeşil kravat ve yeşil mendil,

Burnun akıyor sen sil

Al sana yoksa bir mendil

Sil burnunu artık akmasın,

Yavaş konuş kimse anlamasın.

Anlarsa çok ayıplanırsın

Zannetme ki çok akıllısın

Ufak bir soruda

Apışıp kalırsın.', 'İki el ve iki yüzük bir gözlük, Yeşil kravat ve yeşil mendil, Burnun akıyor sen sil Al sana yoksa bir mendil Sil burnunu artık akmasın, Yava...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/akilli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne derdi varki, ağlarsın Hasan?', 'ne-derdi-varki-aglarsin-hasan-hasan-karakus-pmjko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne derdin varki,ağlarsın Hasan? 

 Uydurma sözlerle doldurdun yalan,

 Kendine gel biraz Allah''tan utan,

 Yokmudur,kalbinde Hakk''ın korkusu.

 Denizin yanında derdin bir yana,

 Nice dert üzüntü vardır; bir anla,

 Şükret haline sağlam imanla,

 Şakı bülbül gibi bırak bu yası.

 Malın var,mülkün var,neyin yok senin,

 Paran var,pulun var,ne imiş derdin,

 Sıhhatin yerinde,canın ağ senin,

 Nedir bu şikayet, dünya kaygısı.

 Hastamısın,yatakta mı yatarsın,

 Borçlumusun Hakk''a isyan yaparsın,

 Çok nankörsün,durmayarak ağlarsın,

 Şikayetin senin bir yüz karası.

  Evladın,hanımın hepsi yerinde,

  Ne ister isen hepsi sende,

  Nankörsün ağlarsın mutlu günde,

  Ben derimki sana akıl hastası.

  Şükreyle Allah''a, düşünme Hasan,

  Neler vardır,borçlu,hasta,perişan,

  Bir lokma ekmeğe eyler el aman,

  Senin evin sultanların sofrası.

  Derdim vardır diye sen hiç ağlama,

  Allah''tan gayriye ümit bağlama,

  Hamdedip şükreyle,ulu mevla''ya,

  Sil gönlünden çıkar bu kara pası.

  Geç karşıma sana bir bir sorayım,

  İstediğin nedir,bilmem bulayım,

  Sana değil,ben aklıma yanayım,

  Derdin nerde sensiz dertsizler ası.

  Başın az ağrısa,öldüm diyorsun,

  Ne gelirse Hakk''tan sen biliyorsun,

  Ağlarsın derdine ne bekliyorsun,

  Ağladıkca artar,gönül tasası.', 'Ne derdin varki,ağlarsın Hasan?   Uydurma sözlerle doldurdun yalan,  Kendine gel biraz Allah''tan utan,  Yokmudur,kalbinde Hakk''ın korkusu.  ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Karakuş']::text[], 8.5, '{"poet":"Hasan Karakuş","poet_slug":"hasan-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-derdi-varki-aglarsin-hasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamlarında', 'gurbet-aksamlarinda-muammer-dastan-5pitk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bacalar tütmez olur

