INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermişim Sırtımı Sisdağı''na', 'vermisim-sirtimi-sisdagi-na-zeki-ergin-68lot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'menekşeler açar yakında

yeşerir fındıklar

karlar erir  Sisdağında

önümüz bahar

