INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Benden Şikayetin Olmasın', 'kalem-benden-sikayetin-olmasin-omer-ziya-soyyigit-b31mh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalem, veremedim senin hakkını

Yarın benden şikayetin olmasın

İçimden geleni yaz dedim sana

Yarın benden şikayetin olmasın

Senin manan büyük, hikmetin yüce

Seninle ben yazdım nice bin hece

Seninle uykusuz kaldık çok gece

Kalem benden şikayetin olmasın

Yaz dedim kırmadın, mahcup etmedin

Manasız sözleri yazmam demedin

Gizledin sırrımı ele vermedin

Kalem benden şikayetin olmasın

Sana yemin etti Halik-ı Azam

Seninle yazıldı hem İsm-i Azam

Kur''anı sen yazdın, O ne muazzam

Kalem benden şikayetin olmasın

Ziya''yı sen yazdın ve hem Ömer''i

Bağladın beline gayret kemeri

Kağıdı, tahtayı, oydun mermeri

Yarın benden şikayetin olmasın    

9 Temmuz 1991 Üsküdar', 'Kalem, veremedim senin hakkını Yarın benden şikayetin olmasın İçimden geleni yaz dedim sana Yarın benden şikayetin olmasın Senin manan büyük...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalem-benden-sikayetin-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucu Ucuna', 'ucu-ucuna-reyhan-tataroglu-e28de', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayat bir ucum da

                                     ölüm bir ucum da

                                     ramak kaldı...

                                     avucum da', 'hayat bir ucum da                                      ölüm bir ucum da                                      ramak kaldı...                 ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ucu-ucuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülişan, Osman, Zeynep', 'gulisan-osman-zeynep-omer-ziya-soyyigit-r2mx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlümün baharıdır

Gülişan, Osman, Zeynep

Kalbimin çerağıdır

Gülişan, Osman, Zeynep

Bahçemin bülbülüdür

Bağımın sümbülüdür

Bülbülümün gülüdür

Gülişan, Osman, Zeynep

Onlar benim sürurum

Hayatımda huzurum

Yeni baştan zuhurum

Gülişan, Osman, Zeynep

Ağacımın dalıdır

Peteğimin balıdır

Ömer''in öz malıdır

Gülişan, Osman, Zeynep

10 Haziran 1991 Üsküdar', 'Gönlümün baharıdır Gülişan, Osman, Zeynep Kalbimin çerağıdır Gülişan, Osman, Zeynep Bahçemin bülbülüdür Bağımın sümbülüdür Bülbülümün gülüdü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulisan-osman-zeynep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündükçe', 'dusundukce-derya-penbe-6skxf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey fani dünya neler geldi geçti senden

Bir asır değil bin asır yaşandı sende

Irmaklar güneşin ayın yıldızların şahit oldu sırlarına

Özenle büyüttüğün çiçeklerine toz kondurmadın 

Yağmurlarınla neşeyle büyüttün onları

Gün gelecek dedin kışın ardından tekrar baharın gizlendiğini

Aynı masallardaki kahramanların tekrar canlanacağı gibi

Gizli bir hazineydi senin için bir emanetti

Sardın sarmaladın 

Her şeyden uzak tuttun 

Kötülükleri anlatmadın emanetlerine

Sarılmayan yaraları sardın

Biz insanoğlu ise emeklere karşılık ihanet ve sahtekârlıkla

Bir birimizi attık kurtlar sofrasına

En kötüsü de içimizdeki güzellikleri tamamen yok etmedik mi? 

Biz rabbimin en güzel varlıklarıydık

Bir çiçek kadar bile mücadele veremedik

Ve biz seninle var olduk seninle yok olacağız 

Sadece şimdilik erken ayrılanlar kucağımda uyuyacak 

Zamanı gelince de hesap için uyanacaklar

Kimi şefkatle kimi de acıyla haykırışla uyanacak ahirette

Uslu çocuklar alacak mükâfatını ve yaramaz çocuklarsa çekecekler cezasını', 'Ey fani dünya neler geldi geçti senden Bir asır değil bin asır yaşandı sende Irmaklar güneşin ayın yıldızların şahit oldu sırlarına Özenle b...', ARRAY['Türk Edebiyatı','Şiir','Derya Penbe']::text[], 8.5, '{"poet":"Derya Penbe","poet_slug":"derya-penbe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusundukce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdâ Ağacı', 'sevd-agaci-timur-i-likan-mkgrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen sevilmek için yaratılmışsın bir tanem

Ben de seni sevmek için

Seni sevmekten alıkoyamıyorum kendimi

Coştukça coşmuşum aşmışım bendimi

Unutmuşum beni dağlayan derdimi

Sana bir mücevher gibi sunuyorum sevgimi

Sen sevilmek için yaratılmışsın bir tanem

Ben de seni sevmek için

Bir ağacın güneşi sevdiği gibi

Kurumuş bir avuç toprağın yağan yağmuru sevdiği gibi

Seviyorum ben seni

Sevdikçe daha çok seviyorum inan ki

Sevdâ ağacında koparılmayı bekleyen

Bir aşk meyvesiyim ben

Al kopar tadıma bak benim

Tadıma bak ki damağında kalsın tadım

Benden de hiç bir zaman bıkmayasın sevgilim

Sen sevilmek için yaratılmışsın bir tanem

Ben de seni sevmek için

Ben de seni sevmek için biriciğim

(2 Mart 2006/ İstanbul)', 'Sen sevilmek için yaratılmışsın bir tanem Ben de seni sevmek için Seni sevmekten alıkoyamıyorum kendimi Coştukça coşmuşum aşmışım bendimi Un...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevda-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Çekilmez Bu Hayat...', 'aslinda-cekilmez-bu-hayat-aysun-elagoz-rf4e6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşüncelerimin kara bulutları arasında

Uçuşan ümit kuşları olmasa,

Varlığının fikri olmasa tebessümlere sebep,

Sevdanın tadı olmasa dudaklarımda,

Sen olmasan, 

Aslında çekilmez bu hayat...', 'Düşüncelerimin kara bulutları arasında Uçuşan ümit kuşları olmasa, Varlığının fikri olmasa tebessümlere sebep, Sevdanın tadı olmasa dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aslinda-cekilmez-bu-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Bekliyorum...', 'bu-aksam-bekliyorum-aysun-elagoz-sh5xu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüznüme inat

Tebessümlerini,

Sevgini,

Derin bakışlarını,

Ve tatlı sözlerini,

Kap da gel...

Bu akşam bekliyorum...', 'Hüznüme inat Tebessümlerini, Sevgini, Derin bakışlarını, Ve tatlı sözlerini, Kap da gel... Bu akşam bekliyorum......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-aksam-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Doğumu', 'askin-dogumu-zihni-duygun-biejm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili eşimin hasretiyle…..

Saat üç, uykusuz gecelerden biri daha

Yalnızlık, hem de koca şehirde

İnsan neden yalnız hisseder kendini

Bütün insanların içinde

Neden boşluğa düşüyor

Neden amaçsızlaşıyor insan

Bunu çözmeye çalışıyorum kaç zamandır.

Nafile! Çözümsüzlük beynimde…

Neden aklım hep Ankara’da, neden! ! ! 

Geçmişi düşünüyorum da

Hiç böyle olmamıştı düşüncelerim

Bakıyorum geriye doğru da

O geçmiş günlere empati yapıyorum

İnsanlar gibi sıradan

Sıradan günler geçmiş gibi

Her şey normal, iş, güç...

Hayatın gündelik telaşı, koşuşturmacası gibi

Geliyordu zaman, insanın gözüne

Hatta basit, çok basit bir devr-i alem sanki…

Ama, şimdi düşünüyorum da

Geçen zaman çok değerliymiş

Hatta, yaşanan her basit şey

Sevgiler, emekler, didişmeler, 

Kavgalar, darılmalar, kırılmalar, üzülmeler…

Kıskanmalar…

Meğer, kıymetini bilememişiz hem hayatın, hem de zamanın

Meğerki geçen günler bir şeylere gebeymiş.

Biz farkına varamamışız

Doğacak olanın hem önemini hem de ne olduğunun…

Nasıl anlayalım ki nerdeyse yirmi yıl…

Bu kadar zaman da doğum beklenir mi? 

Zaten bekleye bekleye insan kanıksamaz mı? 

Gelenin ne olduğunu? kim olduğunu? 

Peki, şimdi ne oldu da çıkıverdi.

Ortaya bu doğum

Daha ne olsun ki

Uzun zamandır evinden, eşinden ayrı kalınca insan.

İşte böyle sorguluyor geçmişi

O zamanki kavgalarıyla, sevdalarıyla, çileleriyle…

Meğer ne doğurmuş  biliyor musunuz zaman? …

Alışkanlık, mutluluk, sevgi…

Kısacası aşk! doğurmuş, aşk! …', 'Sevgili eşimin hasretiyle….. Saat üç, uykusuz gecelerden biri daha Yalnızlık, hem de koca şehirde İnsan neden yalnız hisseder kendini Bütün ...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/askin-dogumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez', 'yetmez-omer-ziya-soyyigit-yms1q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lütfun öyle büyük öyle yüce ki

Şükrünü edaya takatim yetmez

Öyle bilinmeyen bir bilmece ki

Yazmaya kağıtlar kalemler yetmez

Rabbim beni af et, pek günahkarım

Arşa çıksa azdır ah ile zarım

Nefsimin elinden pek çok bizarım

Onu zapdetmeye urganlar yetmez

Binlerce nimete nail eyledin

Hizmet-i Kur''ana fail eyledin

Bu kemter kulunu sail eyledin

Binbir dili olsa yinede yetmez

Kesmem ümidimi, Rahman Rahim sin

Hem Gafur hem Rauf hem de Kerimsin

Lütfunu umarım çünki Latıf sın

Tükenir sözcükler vasfına yetmez

Olamam elbette mekrinden emin

Korkarım narından işte bin yemin

Etme cehennemi bizlere zemin

Ya Rab azabına gücümüz yetmez

Habibini şefaatçı kıl bize

Kur''an ile başlayalım biz söze

Aman ya Rab! haset ile kem göze

Gazap, şehvet tekebbüre güç yetmez

Asan eyle sualimi vereyim

Nasip eyle cennetine gireyim

Cennetinden cemalini göreyim

Kahrına kimsenin takati yetmez

Rızana muaffak eyle Ziya''yı

Dertlerine sen verirsin devayı

Kabul eyle reddeyleme keda''yı

Ağır mihnetlere takatim yetmez

13 Eylül 1999 Tosunlu', 'Lütfun öyle büyük öyle yüce ki Şükrünü edaya takatim yetmez Öyle bilinmeyen bir bilmece ki Yazmaya kağıtlar kalemler yetmez Rabbim beni af e...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yetmez-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgi', 'bilgi-altay-taskin-tphb6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'serde nosyonluk

vardır kendince

anlamaz anlatamaz ama

zamanı gelince

götürür götüreceği yere

ışıksız gölde açar

kırışmış kağıdını

okumaya başlar

tabii kendi kendine

çalkalandıkça

o köşeden o köşeye

düşer harfler eğrice

sıralanır eğrice önüne', 'serde nosyonluk vardır kendince anlamaz anlatamaz ama zamanı gelince götürür götüreceği yere ışıksız gölde açar kırışmış kağıdını okumaya ba...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 4', 'maniler-ask-4-zihni-duygun-hmnrr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kolumdaki saati

Kurmaya kıyamıyorum

Yaktın beni yürekten

Görmeden duramıyorum

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Masa üstünde bülbül

Sevdiğim ise güldür

Yaşı küçüktür ama

Aşkı beni öldürür

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Evleri usta yârim

Ver bana müjde yârim

Ayak bastığın yerde

Ederim secde yârim

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Lapseki iskelesi

Akşamüstü serinler

Verdin bana sevdayı

Günden güne derinler

Derlenen Kişi: 

Derlenen Köy: Beypınar Köyü

Derlenen İlçe: LAPSEKİ

Derlenen İl: ÇANAKKALE

Krem giyme üşürsün

Güzel ne düşünürsün? 

Hiç boşuna düşünme

Sen sevdaya düşmüşsün

Derlenen Kişi: 

Derlenen Köy: Beypınar Köyü

Derlenen İlçe: LAPSEKİ

Derlenen İl: ÇANAKKALE

Sevdim ezelden seni

Aşkın sardı gönlümü

Gönlüm çekti çıkardı

Bunca güzelden seni

Derlenen Kişi: Mehmet ÇINAR

Derlenen Köy: 

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE

Kalenin ardı ırmak

Giydim altıparmak

Sen bal dola ben kaymak

Yiyeyim parmak parmak

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Penceremde tül perde

Perdenin ucu yerde

Yürek oynar can titrer

Yâri gördüğüm yerde

Derlenen Kişi: Havva

Derlenen Köy: Hacılar Köyü

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE', 'Kolumdaki saati Kurmaya kıyamıyorum Yaktın beni yürekten Görmeden duramıyorum Derlenen Kişi:  Derlenen Köy:  Derlenen İlçe:  Derlenen İl: ÇA...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 5', 'maniler-ask-5-zihni-duygun-oel42', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavili mavili mor çiçek

Mavili burdan geçecek

Ben bir çeşme yaptırdım

Sevdalılar içecek

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Karşıdan atlı geçti

Nalı parlattı geçti

Herkese selam verdi

Beni ağlattı geçti

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Karşımda duran sensin

Zülfünü buran sensin

Bana cellad kâr etmez

Boynumu vuran sensin

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Karanfil oylum oylum

Geliyor selvi boylum

Selvi boylumu görünce

Şen olur benim gönlüm

Derlenen Kişi: İlknur ÖZTÜRK

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Mendilimi uçurdum

Kavak yapraklarına

Ben yârimi düşürdüm

Sevda yataklarına

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Kızın adı sevimiz

Yol üstüdür evimiz

Düştük kara sevdaya

Mahvolacak birimiz

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Kuyuya kova saldım

Yârimi çakır sandım

Çakırlarda gözüm yok

Kara gözlüme yandım

Derlenen Kişi: 

Derlenen Köy: Etili Köyü

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE

Şu dağlarda ordu var

Ordu gitmiş yurdu var

Gözlerinden anladım

Sende gönül derdi var

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE', 'Mavili mavili mor çiçek Mavili burdan geçecek Ben bir çeşme yaptırdım Sevdalılar içecek Derlenen Kişi:  Derlenen Köy:  Derlenen İlçe:  Derle...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 6', 'maniler-ask-6-zihni-duygun-zfs6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeleğimin cebinde

Mavi boncuk nazarlık

Benim yâre hediyem

Bir ufacık gerdanlık

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Uzaktan gördü beni

Yuvadan sürdü beni

Ben bir garip kuş idim

O zalim vurdu beni

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Tüfeğim dolu saçma

Gel yârim benden kaçma

Yedi yerimde yara var

Bir yara da sen açma

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Su gelir aka aka

Yâr gelir baka baka

Ben yâre gönül verdim

Annemden korka korka

Derlenen Kişi: 

Derlenen Köy: Yeniköy

Derlenen İlçe: EZİNE

Derlenen İl: ÇANAKKALE

Sürü meler her yerde

Suyu berrak derede

Lale sümbül menekşe

Topladım derelerde

Derlenen Kişi: Zehra Hanım

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Uzaklar seçilmiyor

Gönüldür geçilmiyor

Gönül bir top ibrişim

Dolaşmış açılmıyor

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Pencerenin dibinde

Kaneviçe işlerim

Sevdiğimin ismini

Mendilime işlerim

Derlenen Kişi: Zeynep KAYA

Derlenen Köy: 

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE

Un eledim elekten

Tad aldım börekten

Öyle bir yâr sevdim ki

Çıkaramadım yürekten

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE', 'Yeleğimin cebinde Mavi boncuk nazarlık Benim yâre hediyem Bir ufacık gerdanlık Derlenen Kişi:  Derlenen Köy:  Derlenen İlçe:  Derlenen İl: Ç...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 7', 'maniler-ask-7-zihni-duygun-lr1yk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yoğurtlarım yağ olsun

Asma diktim bağ olsun

Varım yoğum yâr için

Yesin yesin sağ olsun

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Yüzü beyaz kar gibi

Gözleri zeytin gibi

Anasından istedim

Bana gönlü var gibi

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Zeytin topluyom zeytin

Hepsi dörder beşer

Yâr aklıma düşünce

İçime ateş düşer

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Zeytinin kökü yamuk

Dibine ektim pamuk

Geçme kız karşımdan

Yüreğim dünden yanık

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Yokuşu ben çıkarım

Yollar senin olsun

Zehri ben içerim

Hayat senin olsun

Derlenen Kişi: 

Derlenen Köy: Yapıldak Köyü

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Yaprak yaprak üstüne

Yaprak toprak üstüne

Yemin etmedim ama

Gideceğim ortak üstüne

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Karanfilim direkte

Bir yâr sevdim gurbette

Gurbette ise gurbette

Sevgi var yürekte

Derlenen Kişi: İsmail CAN

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Penceresi demirden

Parmakları emirden

Senin sözün değil mi? 

Beni böyle eriten

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE', 'Yoğurtlarım yağ olsun Asma diktim bağ olsun Varım yoğum yâr için Yesin yesin sağ olsun Derlenen Kişi:  Derlenen Köy:  Derlenen İlçe:  Derlen...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 8', 'maniler-ask-8-zihni-duygun-nnzoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pencerede tül perde

Sen koydun beni bu derde

Ben bu dertten ölürsem

Yatamam kara yerde

Derlenen Kişi: 

Derlenen Köy: Yolağzı Köyü

Derlenen İlçe: ECEABAT

Derlenen İl: ÇANAKKALE

Pembe üzüm salkımda

Yeşil yaprak ardında

Benim bir sevdiğim var

Can evimin altında

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Orak biçtim ellikle

Yâre gittim terlikle

Yâr ağladı ben sildim

Elimdeki mendille

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Mini mini pireler

Rüyalarıma girdiler

Prensesiniz kim dediler

Yârindir dediler

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Saçımda siyahım var

Bülbül gibi âhım var

Göz gördü gönül sevdi

Benim ne günahım var

Derlenen Kişi: Gülşen GÖÇEN

Derlenen Köy: Etili Köyü

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE

Şapkayı eğe eğe

Soldurdum giye giye

Sarıçiçeğe dönmüş

Sevdiğim diye diye

Derlenen Kişi: 

Derlenen Köy: Yeniköy

Derlenen İlçe: EZİNE

Derlenen İl: ÇANAKKALE

Sarı çember başında

Oyaları dışında

Ben nasıl ayrılayım

Sabah akşam karşımda

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Kadifeden kesesi

Kahveden gelir sesi

Oturmuş kumar oynar

Ciğerimin köşesi

Derlenen Kişi: Müzeyyen Hanım

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE', 'Pencerede tül perde Sen koydun beni bu derde Ben bu dertten ölürsem Yatamam kara yerde Derlenen Kişi:  Derlenen Köy: Yolağzı Köyü Derlenen İ...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler - Aşk - 9', 'maniler-ask-9-zihni-duygun-cmbxl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdirir de kaçarsın

Beni baştan atarsın

Aşkın öldürüp de

Cayır cayır yakarsın

Derlenen Kişi: Mehmet ÇINAR

Derlenen Köy: 

Derlenen İlçe: ÇAN

Derlenen İl: ÇANAKKALE

Mendilimi işledim

Sapını gümüşledim

Yârdan gelen selamı

Kalbime işledim

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: AYVACIK

Derlenen İl: ÇANAKKALE

Portakal soyamam

Konserine doyamam

Ne de sıcak kanın var

Sevmeye doyamam

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Sel gelmiş bizim bende

Ağlarım senle benle

Gözlerimin yeri var

Yanağındaki bende

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Sarı gülün dikeni

Dibindedir kökeni

Anlarsa yâri anlar

Gizli sevda çekeni

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Sarı gülüm erende

İnsaf senin nerende

Kabahat bende değil

Sana gönül verende

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Samanlıkta samanı

Atalım yaba yaba

İki gönül bir olsa

Ne yapar anne baba

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE

Saksıda gül ağacı

İnsafsız bana acı

Göz gördü gönül sevdi

Nedir bunun ilacı

Derlenen Kişi: 

Derlenen Köy: 

Derlenen İlçe: 

Derlenen İl: ÇANAKKALE', 'Sevdirir de kaçarsın Beni baştan atarsın Aşkın öldürüp de Cayır cayır yakarsın Derlenen Kişi: Mehmet ÇINAR Derlenen Köy:  Derlenen İlçe: ÇAN...', ARRAY['Türk Edebiyatı','Şiir','Zihni Duygun']::text[], 8.5, '{"poet":"Zihni Duygun","poet_slug":"zihni-duygun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/maniler-ask-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-omer-ziya-soyyigit-wdzzl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin dokuz yüz yirmi dokuz

Gelin olduğun yıl annem

Ve bin dokuzyüz otuz dört

Benim doğduğum yıl annem

Aylar geçti yıllar geçti

Yaşım on dörde ulaştı

Ayrılık bize bulaştı

Dokuz yüz kırk sekiz annem

Mektuba kaldı işimiz

On beşe geldi yaşımız

Tarhana idi aşımız

O yıllarda bizim annem

On beş ay üstüne geldim

Hasretlik ne imiş bildim

Akan göz yaşını sildim

Kavuşunca size annem

Sene bin dokuz yüz elli

Üç aralık bu da belli

Sarığımız sırma telli

Hafız olmuştum ben annem

Kur''anın ihtisasını

İlimlerin esasını

Cihanın maverasını

Arıyorduk bizler annem

Aşere takrib okuduk

Atlas ipekler dokuduk

Kötü yolda biz yok idik

Duanız korudu annem

Altmış birde asker oldum

Derdimden sarardım soldum

Gam ile kederle doldum

Uzaklarda kaldım annem

İzine geldim selamet

Yolumuz bizim melamet

Kerem eyle bir kelam et 

Dinleyeyim canım annem

Otuz ay bitti tükendi

Kopardık attık kemendi

Yolumuz çayır çimendi

Uçuyorduk bizler annem

Sivil hayata atıldık

Resmi göreve katıldık

Sanki devlete satıldık

Vekil İmam oldum annem

İlk göreve Bifara''da

Başladım kaldım orada

Ermek için ben murada

Araklı''ya indim annem

Kur''an muallimi oldum

Burda ben kendimi buldum

Neşe, sevinç ile doldum

Rabbim razı olsun annem

Dört ay İstanbul''da kaldım

Kur''an tetkikine daldım

Avrupa''dan tez bunaldım

Üç ay sonra döndüm annem

Rize''de geçti dört sene

Mesleğime döndüm yine

Sevene ve sevmeyene

Kur''an okuttum ben annem

On hafız icazet aldı

Mana denizine daldı

Ömer''inde adı kaldı

Dillerde, sevgili annem

1 Eylül 2000 Goga', 'Bin dokuz yüz yirmi dokuz Gelin olduğun yıl annem Ve bin dokuzyüz otuz dört Benim doğduğum yıl annem Aylar geçti yıllar geçti Yaşım on dörde...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/annem-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Gülmek', 'aciya-gulmek-ali-kemal-i-cen-dx7hs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fabrika çıkışı çıktık yorgun

Yüzlerde isyan 

Gülmek bile zordur

Acı içinde..

Saat aynı ayrılık

Saat yorgun yüzler gibi

Zaman bize biz zamana

Haykırıs gibi yazılır duvarlara..

Şimdi bahar çoş deli gönül

Çoş dol alanlara

Onurlu bır kavga içinde sen de gül be 

Sen gül acıya ey gonul...

Zafer yakın halkım

Zafer ellerde,

Meydanlardan gelen seslerde

Fabrika cıkışı yorugun yuzlerde

Acıya gulen her ınsan kalbinde 

Yeşeren bi solukdu bu.', 'Fabrika çıkışı çıktık yorgun Yüzlerde isyan  Gülmek bile zordur Acı içinde.. Saat aynı ayrılık Saat yorgun yüzler gibi Zaman bize biz zamana...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal İçen']::text[], 8.5, '{"poet":"Ali Kemal İçen","poet_slug":"ali-kemal-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aciya-gulmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetçi', 'gurbetci-abdulvahap-ates-tjmv7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yoksulluğun anlına dayayıp namlusunu

bundan on yıllar önce terkedip ulusunu

düştü avrupalara ortakçılar ırgatlar

köyden kasabalara döküldü marabalar

bir traktör parası bir kaç dönümlük tarla

hısımı akrabası umutla iftiharla

yıllarını  tüketti yetmedi isyan etti

tükenmeyen ümitti kesin dönüş hayali

yılların bezginliği borç ile zenginliği

harlanan ezikliği doldurdu benlikleri

evlat öksüz başıboş yarını müphem nahoş

baba barlarda sarhoş anneler çile taşı

üç beş günlük bir rahat tatsız manasız hayat

ne gün geçer ne saat keşkelerin telaşı', 'yoksulluğun anlına dayayıp namlusunu bundan on yıllar önce terkedip ulusunu düştü avrupalara ortakçılar ırgatlar köyden kasabalara döküldü m...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gurbetci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meltemim', 'meltemim-volkan-yoruc-vfrrf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsim geçsin isterim

Yaz gelsin derim

Yine yürürken aynı hayalle yollarda

Essin yüzüme güzel meltemim

Oturduğum yerde manzaram olsun isterim

Sessizden usulca nasılda düşlerim

Öylesine tadını çıkarırken hayatın

Essin yüzüme ılık meltemim

Tepede yalnız kalmak isterim

Bana özel olmasını dilerim

Elimde kankırmızı gülümle

Essin yüzüme ömrü hoş meltemim', 'Mevsim geçsin isterim Yaz gelsin derim Yine yürürken aynı hayalle yollarda Essin yüzüme güzel meltemim Oturduğum yerde manzaram olsun isteri...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/meltemim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak ve Yağmur', 'toprak-ve-yagmur-rahim-tas-h0qfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Toprak ve Yağmur

        Toprak, bir gün âşık olmuş yağmura. İstemiş babası buluttan, bulut yağmuru vermiş gitmiş. Evlenmişler toprakla yağmur. Ekin adında çocukları olmuş. Dadı tutmuşlar güneşi. Serpilip büyüdükçe güzelleşmiş ekin, güneş kıskanmış ekini sarartıp soldurmuş. Ekin ölmüş. Toprak yağmuru suçlamış. Dayanamamış üzüntüye yağmur terk etmiş toprağı. 

        Toprak kara âşık olmuş. İstemiş gökyüzünden karı, gökyüzü karı vermiş gitmiş. Evlenmişler toprakla kar.  Çimen adında çocukları olmuş. Dadılık yapmış güneş, çekememiş güzelliğini çimeni de sarartmış. Çimen de ölmüş. Anlamışlar suçlu güneş. Su vermeden bırakmışlar yavrucuklarını güneşe. Yakmış kavurmuş güneş. 

        Fidan adında çocukları olmuş. Suyunu eksik etmemişler. Dadılık yapmış güneş ama sarartmaya gücü yetmemiş. Büyümüş fidan dal salmış, Sevinmiş toprak ve kar çokça fidan yapmışlar.  Sonra ekin çimen yapmak istemiş toprak. Yağmuru hatırlamış sevgiyle, Bir bakmış ki karşısında karın yerinde duruyor. Anlamış ki az sunmuş sevgisini yağmura, üşümüş sevgisizlikten yağmur, donmuş kar olmuş. 

        Eksik etmemiş o günden sonra sevgisini toprak.  Yağmur, yağmur olarak kalmış hep. Ekin ve çimen de yapmışlar. Sonra başak, sonra meyve. Yıllarca, yıllar boyunca sürmüş, sürecek, bu aşk masalı. 

2.3.2006', 'Toprak ve Yağmur         Toprak, bir gün âşık olmuş yağmura. İstemiş babası buluttan, bulut yağmuru vermiş gitmiş. Evlenmişler toprakla yağm...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/toprak-ve-yagmur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle güzeldi annem', 'seninle-guzeldi-annem-omer-ziya-soyyigit-iuw6s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlar, ovalar, denizler

Seninle güzeldi annem

Bahar, yaz, cümle mevsimler

Seninle güzeldi annem

Baharda açan çiçekler

Bal yapan güzel böcekler

Süt, ayran, tüm içecekler

Seninle güzeldi annem

Armut, elma, erik, üzüm

Salkımları düzüm düzüm

Kaşım, kirpiğim, hem gözüm

Seninle güzeldi annem

Bülbülün nazlı sedası

Guggu''nun kibar edası

Yüce dağların safası

Seninle güzeldi annem

Yaylaların yazıları

Meleşiyor kuzuları

Sultan Murat gezileri

Seninle güzeldi annem

Köyümüz cennet bucağı

Sanki bir ana kucağı

Yakıverince ocağı

Seninle tüterdi annem

Fındık ve çay bahçeleri

Mahzun gördüm bu yerleri

Kokmuyordu çiçekleri

Ötmüyordu bülbül, annem

Kapımızda çayır çimen

Sanki ağlayacak hemen

Kalmadı cepde hiç semen

Bereket sen idin annem

Güneş ısıtmıyor beni

Hatırladıkça ah! seni

Anlıyorum yeni yeni

Şimdi kıymetini annem

Ziya aldandı bilmedi

Gözyaşlarını silmedi

Senin gibisi gelmedi

Bu dünyaya canım annem

6 Eylül 2000 Goga', 'Dağlar, ovalar, denizler Seninle güzeldi annem Bahar, yaz, cümle mevsimler Seninle güzeldi annem Baharda açan çiçekler Bal yapan güzel böcek...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/seninle-guzeldi-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-cagdas-yildiz-rolis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir leoparın sessizce yaklaşıp,

bir antilop sürüsüne saldırdığı anda; 

gözlerinizi dikip de heyecanla,

izlemediniz mi? ..

insanoğlu vahşi,

leoparlar oyuncu,

ya antiloplar..?', 'bir leoparın sessizce yaklaşıp, bir antilop sürüsüne saldırdığı anda;  gözlerinizi dikip de heyecanla, izlemediniz mi? .. insanoğlu vahşi, l...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kurban-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Baş belası', 'ask-bas-belasi-yasar-tezel-y031t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk bal tatlısı

Aşk çılgınlık rüyası

Aşk kalp ağrısı

Aşk gönül sızısı

Aşk feleğin şarkısı

Aşk dert deryası

Aşk seyahat hülyası

Aşk poyraz fırtınası

Aşk gözün cilası

Aşk bedenin elifbası', 'Aşk bal tatlısı Aşk çılgınlık rüyası Aşk kalp ağrısı Aşk gönül sızısı Aşk feleğin şarkısı Aşk dert deryası Aşk seyahat hülyası Aşk poyraz fı...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-bas-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlermisin Can', 'dinlermisin-can-emrah-karakoc-qqieu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ördü kader tuzakları

Dost edindim uzakları

Yediğim şu kazıkları

Anlatsam dinlermisin Can...? 

Sürünmeyi yaşam sandım

Sahte gülüşlere kandım

Zemheri ayında yandım

Anlatsam dinlermisin Can...? 

Sahte sahte insanları

Sandım şu gönlümün varı

Ağustos''da  yağan karı

Anlatsam dinlermisin Can...? 

Pusuya düştüm vuruldum

Suyum kesildi kurudum

Bulanık seldim duruldum

Anlatsam dinlermisin Can...? 

Ne can kaldı, nede canan

El oldu canda can olan

Nasıl vaz geçtim yaşamdan

Anlatsam dinlermisin Can...? 

Mutluluğa koşar adım

Gideriken yaralandım

Nasıl böyle karalandım

Anlatsam dinlermisin Can...? 

Güle bülbüle dargınım

Butün dostlara kırğınım

Niçin bu kadar durgunum

Anlatsam dinlermisin Can...? 

Vefa istanbul''da semtmiş

İnsanlarda yürek bitmiş

Köroğlu en son ne demiş

Anlatsam dinlermisin Can...? 

Dertler yakamı bırakmaz

Bende hayat durdu akmaz

Ateş neden beni yakmaz

Anlatsam dinlermisin Can...? 

Karakoç''un sözlerini

İyi dinle iyi emi

Geçen kara günlerimi

Anlatsam dinlermisin Can...?', 'Ördü kader tuzakları Dost edindim uzakları Yediğim şu kazıkları Anlatsam dinlermisin Can...?  Sürünmeyi yaşam sandım Sahte gülüşlere kandım ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dinlermisin-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişemem Başkasına', 'degisemem-baskasina-i-brahim-ziyali-he4v2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmek suçsa eğer

Katlanırım cezasına 

Sevgin inan buna değer

Değişemem başkasına

İster günüm gece olsun

Hayat bana zehir olsun

Desen, dünya senin olsun

Değişemem başkasına', 'Seni sevmek suçsa eğer Katlanırım cezasına  Sevgin inan buna değer Değişemem başkasına İster günüm gece olsun Hayat bana zehir olsun Desen, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ziyalı']::text[], 8.5, '{"poet":"İbrahim Ziyalı","poet_slug":"i-brahim-ziyali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/degisemem-baskasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamadan yapamam ki', 'aglamadan-yapamam-ki-omer-ziya-soyyigit-5uvjf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostlar beni ayıplaman

Ağlamadan yapamam ki

Anne acısı pek yaman

Ağlamadan yapamam ki

Altmış altı yıldan beri

Çektik biz gamı kederi

Payine koymadık seri

Ağlamadan yapamam ki

Hep işlerim kaba saba

Hiç biri gelmez hesaba

Hayatım benzer seraba

Ağlamadan yapamam ki

Anlayışlı olamadım

Rızasını alamadım

Kıymetini bilemedim

Ağlamadan yapamam ki

Yaşı doksan iki oldu

Gözleri yaş ile doldu

Gül yüzü sarardı soldu

Ağlamadan yapamam ki

Her an bize dua etti

Beddua etmeden gitti

Hükmü Mevla, ömrü bitti

Ağlamadan yapamam ki

Validem gitti ben kaldım

Başımı dertlere saldım

Çok görmeyin pek bunaldım

Ağlamadan yapamam ki

Ömer her an ağlayacak

Yüreğini dağlayacak

Hakka ümit bağlayacak

Ben ümitsiz olamam ki

8 Eylül 2000 Tosunlu', 'Dostlar beni ayıplaman Ağlamadan yapamam ki Anne acısı pek yaman Ağlamadan yapamam ki Altmış altı yıldan beri Çektik biz gamı kederi Payine ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aglamadan-yapamam-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bu', 'hayat-bu-guner-kurt-wjvup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşadığım şeyleri

Ben mi istedim 

Kader denileni

Her zaman 

Olmaz elbet

Kahkahayla yaşam

Alışacağım belki 

Göz yaşlarıma bile

Onlarla yaşamaya

Hayat bu	

İnişli çıkışlı

Eğri zikzaklı

	

Yürüdüğümüz yollar	

Hep mi düz	

Bazen yokuşlu	

Her zaman	

Olmaz elbet 	

Kahkahayla yaşam	

Yürüdükçe öğrenecek	

Her şeyde birşeyler	

Anlayacağız

	

Gülüşlerde gözyaşını	

Gözyaşında gülüşleri 	

Arayacağız', 'Yaşadığım şeyleri Ben mi istedim  Kader denileni Her zaman  Olmaz elbet Kahkahayla yaşam Alışacağım belki  Göz yaşlarıma bile Onlarla yaşama...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-bu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C a n a n ı m', 'c-a-n-a-n-i-m-mustafa-alpaydin-bc3g8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu koca çınarın engin dalıydım 

Sen nadide çiçek bense çalıydım 

Deryalarda gezen bir buz dağıydım 

Hasretin eritti beni Cananım. 

Karlı dağlar bize geçit vermese 

Doktorlar üç günlük ömrün var dese 

Harcarım uğruna vuslat kaderse 

Sensizlik ağlatır beni Cananım. 

Tutuşur yüreğim dumanı tütmez 

Yaram derindedir merhem kar etmez 

Gurbette günlerim yıl olur bitmez 

Sevdan kül eyledi beni Cananım.', 'Şu koca çınarın engin dalıydım  Sen nadide çiçek bense çalıydım  Deryalarda gezen bir buz dağıydım  Hasretin eritti beni Cananım.  Karlı dağ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/c-a-n-a-n-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Gördüm', 'sevgi-gordum-guner-kurt-0gyn4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sevgi gördüm	

Beni göz yaşları ile ağlattılar	

Sahte sevdaların yaşandığı	

Günlerde herkese	

Sevgiyi anlattılar	

Acıların halka halka zincir oluşu	

Bu zincirde tav olup sertleşiyordu	

Ben sevgi gördüm	

Çıkarsız,umarsız ve saf	

Bir o kadar doğal ve güzel	

Ben sevgi gördüm 	

Boğazımı düğümledi	

Sahte sevdaların yaşandığı	günlerde

Sevgileri büyüledi', 'Ben sevgi gördüm	 Beni göz yaşları ile ağlattılar	 Sahte sevdaların yaşandığı	 Günlerde herkese	 Sevgiyi anlattılar	 Acıların halka halka zi...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularım', 'duygularim-murathan-turk-jir5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda gibi bir gizli emel ruhuna sinmiş; 

Bir haz ki hayalden bile üstün ve derinmiş.

Gökten gelerek gönlüne rüzgar gibi inmiş,

Bir sır ki bu, ölse bile asla açamazsın…

Anlatması imkansız olan öyle bir an ki,

Hülyadaki ses varlığının gayesi sanki…

Bak emrediyor; Daldığın alemden uyan ki,

Mutlak seveceksin beni, bundan kaçamazsın

Ruhun mu Ateş yoksa o gözlermi alevden? 

Bilme bu yanardağ nasıl bir korla tutuştu

Pervane olan kendini gizlermi alevden? 

Sen istedin ondan bu gönül tutuştu

Çehren bana uğrunda ölün hazzı verince; 

Gönlümdeki azgın devi rüzgarlara attım…

Gözlerle günah işlemenin zevkini tattım..

Gözler…

Gözlerki birer parçasıdır senden ilah ın…

Gözlerki senin en katı zulmün ve silahın…

Vur! Şanlı silahınla gönül mülkü düzelsin

Sen vurukende öldürükende güzelsin', 'Sevda gibi bir gizli emel ruhuna sinmiş;  Bir haz ki hayalden bile üstün ve derinmiş. Gökten gelerek gönlüne rüzgar gibi inmiş, Bir sır ki b...', ARRAY['Türk Edebiyatı','Şiir','Murathan Turk']::text[], 8.5, '{"poet":"Murathan Turk","poet_slug":"murathan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygularim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Gönül', 'unut-gonul-durdane-demirkoparan-jxbcb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah gönül

Ah ki ne ah

Sen kimleri sevdin böyle

Kimler için yandın

O seni unutmadı mı sanırsın

Yanıyor mu hala sen gibi

Gitmedi mi  başka gönüllere

Sevmedi mi sanırsın  başkasını

Unut  gönlüm  unut

Sevdiğin  çoktan gitmiş

Gönülden 

Nefes aldığın her köşeden

Ve ismin hatırlanmaz olmuş

Üstünden yıllar geçmiş gibi

Ah gönül

Ah ki ne ah

Sen kimleri sevdin böyle

Kimler için yandın

Sevilmemişsin gönül 

Kandırma kendini

Üzülme ağlama boşa

Unut sende

Sevdiğin gibi…

Unut..', 'Ah gönül Ah ki ne ah Sen kimleri sevdin böyle Kimler için yandın O seni unutmadı mı sanırsın Yanıyor mu hala sen gibi Gitmedi mi  başka gönü...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unut-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Resim', 'son-resim-i-brahim-ziyali-tcra9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün ayrı olsakta

Güzel günler yaşadık

Sevda yarım kalsa da

Bizler aşka doymadık

Görmez belki gözlerim

Senden başka birini

Yıllar geçse beklerim 

Bana geri dönmeni

Elimden hiç düşmedi

Bende kalan son resmin

Dilimden hiç düşmedi

Şarkı gibi o ismin', 'Bugün ayrı olsakta Güzel günler yaşadık Sevda yarım kalsa da Bizler aşka doymadık Görmez belki gözlerim Senden başka birini Yıllar geçse bek...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ziyalı']::text[], 8.5, '{"poet":"İbrahim Ziyalı","poet_slug":"i-brahim-ziyali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-resim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüş Kalsın', 'gulus-kalsin-guner-kurt-zar3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle gülümseyin ki	

Yokluğunuzda	

Hep o gülümsemeler	

Kalsın resimlerde	

Yıllar hepimizin ağartıp saçlarını	

Kırıştırsa da yüzümüzü	

Anımsansın hep o gülüşlerle	

Hadi gülümseyin biraz	

Sevgi çicek açsın	

Saklasada ruhumuz	

Gizlesede bedenimiz	

Yine de tatlı bir eser kalsın	

Karanlığa inad	

O hep ışık saçsın		

Kalacaksa eğer yadigar		

Bir şey bizden		

O gülüşlerden		

O tebessümlerden		

Zerreler kalsın		

Anacaksa bizi birileri		

Böyle hatırlayıp böyle ansın', 'Öyle gülümseyin ki	 Yokluğunuzda	 Hep o gülümsemeler	 Kalsın resimlerde	 Yıllar hepimizin ağartıp saçlarını	 Kırıştırsa da yüzümüzü	 Anımsan...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulus-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halim', 'halim-guner-kurt-wpigr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlamaklı yüreğime	

Dokunma git dokunma git	

Benim bahar görecek	

Halim mi kaldı	

Küllendi sevdalar	

Tozlandı anılar	

Maziyi savurdu 	

Savurdu yıllar	

Yıllar yılı bekledim	

Tanrım bir deva	

Acıya katlanacak	

Halim mi kaldı		

Küllendi sönmez sanılan		

Sarardı solmaz denilen		

Gelip geçiçiymiş her şey		

Gerçek diye an be an yaşanan', 'Ağlamaklı yüreğime	 Dokunma git dokunma git	 Benim bahar görecek	 Halim mi kaldı	 Küllendi sevdalar	 Tozlandı anılar	 Maziyi savurdu 	 Savur...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Penceremde', 'sanal-penceremde-ayse-birgul-yilmaz-w5c5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinde boğulduğum, kaybolduğum şu günlerde

Sen bana yaklaştıkça yakınlaştıkça karışıyorum

İçimi ısıtan sevecen gözlerin derinliğinde

Aşk var gibi sanki belirsiz yitik sözlerinde

Korkarım ki ben sana alışıyorum.

Sanal penceremde gördüğüm satır satır döküldüğüm

Beklemediğim yalan, yalan güçlü göründüğüm

Gerçek tek sensin özlediğim hep düşündüğüm

Aklım çok karışık yoğun duygular yaşıyorum.

Suskunum bilemezsin tuşlara dökülen yaşlarımı

Dalgın, dağınık gün boyu bekleyen bakışlarımı

İnzivasında göremezsin dört duvar aksamlarımı

Sanıyorum ki ben artık sensiz yapamıyorum.

Yürür gibiyim bir deli fırtınanın izinde

Sen geliyorsun güneş doğuyor penceremde

.

02/02/06', 'İçinde boğulduğum, kaybolduğum şu günlerde Sen bana yaklaştıkça yakınlaştıkça karışıyorum İçimi ısıtan sevecen gözlerin derinliğinde Aşk var...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sanal-penceremde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Gece', 'sen-ve-gece-guner-kurt-8dr5q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin ismini 	

Anmakta gece	

Senin sevgini	

Göstermekte vakit	

Neden beklerim	

Böyle geceleri	

Anla sevgili 	

Anla sen beni	

Nasıl bülbül	

Yanarsa güle	

Nasıl çöl  toprak	

Hasretse sele	

Yad ederim	

Ben seni	

Seni her gece	

Ben işte böyle	

Geceleri beklerim	

Sayfa sayfa	

Anarım seni	

Vakit o vakit	

Ben aynı ben yine	

Ararım anarım seni', 'Senin ismini 	 Anmakta gece	 Senin sevgini	 Göstermekte vakit	 Neden beklerim	 Böyle geceleri	 Anla sevgili 	 Anla sen beni	 Nasıl bülbül	 Y...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-ve-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadir Geceleri', 'kadir-geceleri-mevlut-yanar-9zqwd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerimi açıpta  kadir gecelerinde

Huşu içinde sana yalvaramadım Rabbim

Bir donukluk var bende sanki hastayım gibi

Bir doktor bulamadım em bulamadım Rabbim

Ne verdiysen sen verdin sağlıklı nefesimi

Üç tane evlat verdin sürdürsünler neslimi

Bazan biraz mal verdin sınav için nefsimi

Senin dediğin gibi harcayamadım Rabbim

Elimden uçup gitti hem malım hem umudum

Yine seni bilmedim şuna buna suç buldum

Bazan haddimi aştım asi bir kulun oldum

Belki sevdinde verdin anlayamadım Rabbim

Bir nefes alana dek beni bana bırakma

Göstermezsen doğruyu güvenemem aklıma

Has tohum ekemedim ahret için dünyama

Tembellik edip yattım sulayamadım Rabbim

Tek umudum odur ki senin sonsuz rahmetin

Ve umarım elimden tutar resul Ahmedin

Affet beni Allahım affetmeyi seversin

Hüngür hüngür secdede ağlayamadım  Rabbim

9-10 kasım 2004  Kadir Gecesi', 'Ellerimi açıpta  kadir gecelerinde Huşu içinde sana yalvaramadım Rabbim Bir donukluk var bende sanki hastayım gibi Bir doktor bulamadım em b...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kadir-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimden Bir Parça', 'kalbimden-bir-parca-guner-kurt-gx0et', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbim kalbimden	

Bir parça koptu	

O an gözlerim değil	

Gönlüm ağlıyordu	

Senin gelmen 	

Buralarda havaları değiştirdi	

Oysa şimdi	

Oyasa şimdi gidiyormusun	

İnsanoğlu çok yol aldı	

Çok yol katetti	

Ayrılığa ayrılığa çare yok	

Doğanın kanunumu bu		

Yoksa Hak''tan mı		

Gitme gitme dur diyemem		

Bende yanında gelemem		

Bitmedi tabi bitmeyecek tabii		

Sevgimiz dünyadan da öte', 'Kalbim kalbimden	 Bir parça koptu	 O an gözlerim değil	 Gönlüm ağlıyordu	 Senin gelmen 	 Buralarda havaları değiştirdi	 Oysa şimdi	 Oyasa şi...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbimden-bir-parca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK VE SEVGi YALAN', 'ask-ve-sevgi-yalan-ahmet-eroglu-b74bj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalanlar içinde boğuldum kaldım

Kimseye inancım kalmadı usta

Onu bedenimde bir parça bildim

Oysa bedenine almadı usta

Kimseye inancım kalmadı usta

Bir anda ansızın kalbime girdi

Dünyayı verseler bırakmam derdi

Dertsiz yüreğime bin cefa verdi

Bir pula satıpta gitti be usta

Beni uçuruma itti be usata

Gözüme bakarken her an erirdim

Canımı istese durmam verirdim

Kalbimden gönlüne sevgi sererdim

Ellerim elinde yanardı usta

Mevsimler o gece sarardı usta

27.02.2006/Ankara', 'Yalanlar içinde boğuldum kaldım Kimseye inancım kalmadı usta Onu bedenimde bir parça bildim Oysa bedenine almadı usta Kimseye inancım kalmad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Eroğlu']::text[], 8.5, '{"poet":"Ahmet Eroğlu","poet_slug":"ahmet-eroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-ve-sevgi-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-guner-kurt-b9irn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen dağlar alır götürür

Bazen engin denizler

Yaprak ve dalga misalisindir

Sürüklenir yada savrulur  gider	

Bazen dağlarda uçan kuş 

Bazen kafeste gibi

Geçer gider ömürler böyle

Bazenlerin çarkında dişli', 'Bazen dağlar alır götürür Bazen engin denizler Yaprak ve dalga misalisindir Sürüklenir yada savrulur  gider	 Bazen dağlarda uçan kuş  Bazen ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bazen-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatalar', 'hatalar-guner-kurt-3zm3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatalar hataları doğurur	

Yapma güzel	

Dur durak ver 	

Hata her insanda olur	

Şu üç günlük dünyada 	

Bak neler olur	

Yavru kuş palazlanır 	

Yuvadan uçar	

Gelmez sanma  o gün	

O gün de gelir	

Üzme kendini	

Kırma hem beni	

İnsan isterse canım	

Güle oynaya yaşar	

Hemde yaşatır	

Kime kalmış ki dünya	

Bize de kalır	

Dün yoktuk bugün varız	

Yarın biz yokuz	

Var olacak elbet yaşam	

Dönecek devram	

Neler öğretip öğütecek	

Bilinmez yaşam	

Yaşa dünyada seninmiş gibi	

Sarıl ona alın terinmiş gibi	

Bir insan bir dünyaysa	

Kırma kalpleri	

Hatalar,kusurlarla hep dolu dünya	

Ne dert kapını çalsın	

Ne sen arala

Mutluluk var bu dünyada

Hep onu ara

Mutluluk var bu dünyada

Sen onu ara', 'Hatalar hataları doğurur	 Yapma güzel	 Dur durak ver 	 Hata her insanda olur	 Şu üç günlük dünyada 	 Bak neler olur	 Yavru kuş palazlanır 	 ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hatalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopukluklar', 'kopukluklar-yasar-tezel-evxkm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mazlumun çığlığında çığ düştü içimize

Kaç kıtadadır at koşturduğumuz ülke

Gül tohumlarına adanmış,gebe

Kursagımızda düğümlenen kelime

Anlayamadığımız ecdat nerede? 

Yavrusunu kovan,bal arısı sende

Dağ yamaçlarında kardelenlerin hası

Çölde serap,anlaşılmazlığın mayası

Kurtlar sofrası,kuzular yaylası

Semahını türkü sandığımız aynı

Zeybeğine ümit bağladığımız efe

Boğuştuğum kopukluklar

Onları okuyorlar', 'Mazlumun çığlığında çığ düştü içimize Kaç kıtadadır at koşturduğumuz ülke Gül tohumlarına adanmış,gebe Kursagımızda düğümlenen kelime Anlaya...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kopukluklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttun Beni', 'unuttun-beni-ayse-birgul-yilmaz-nlz47', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen beni unuttun, unuttun beni

Uzaklığın bana çok yakınlaştı

Unutulmuş nice şarkılar gibi

Öyle uzun zaman sessiz kaldın ki

Bıraktığın gibi değil ellerim

Öyle uzun zaman hissiz kaldım ki

Sensiz anlamı yok günlerin gecelerin

Öyle uzun zaman sensiz kaldım ki

Hiç mi hatırı yok geçen yılların

Hiç mi hatırı yok yaşananların

Hiç mi hatırı yok mutlu anların

Öyle uzun zaman aramadın ki', 'Sen beni unuttun, unuttun beni Uzaklığın bana çok yakınlaştı Unutulmuş nice şarkılar gibi Öyle uzun zaman sessiz kaldın ki Bıraktığın gibi d...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unuttun-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Senden Olur', 'sana-senden-olur-ayse-birgul-yilmaz-od8ik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalandan haramdan sakın uzak dur

Azıcık aşın kaygısız başın olsun

Sana taş atana sende gül’le vur

Az konuş öz konuş sözden uzak dur

Zaman sana uymaz sen zamana uy

Öyle an vardır ki ne gör ne de duy

Alçak gönüllü ol, hatır gönül say

Az konuş öz konuş gözden uzak dur

Sana senden olur ne olursa

Başın rahat uyur dilin durursa', 'Yalandan haramdan sakın uzak dur Azıcık aşın kaygısız başın olsun Sana taş atana sende gül’le vur Az konuş öz konuş sözden uzak dur Zaman sa...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sana-senden-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Üstünde Süs', 'sular-ustunde-sus-mevlut-yanar-9x76z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karaçay koydum adını 

içmek istedim içimi yaktın

Değdirmeden dudaklarımı 

Tansiyonumu fırlattın

Şarkısın işleyen ruhuma

Alevler gibi saçların

Güneşşin çok uzaklarda

Yaklaşşam yakarsın

Karaçayım sarı çiçek çayım

Bana bal renginde bak

Sözlerini duyayım

Ve sonra istersen yak

Yanarım gönlümdeki hasret

Sular üstünde süse

Sevdam karaçay rakset

Ölürüm dudaklarım değse', 'Karaçay koydum adını  içmek istedim içimi yaktın Değdirmeden dudaklarımı  Tansiyonumu fırlattın Şarkısın işleyen ruhuma Alevler gibi saçları...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sular-ustunde-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sevgiliye', 'dost-sevgiliye-kevser-gulistan-cakir-g9yft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben neşemi herkesle paylaşırım

Sen sessizliğimi paylaş benimle

Gözlerime dal

Orada kal

Göreceksin

Anlatmak böyle daha kolay...', 'Ben neşemi herkesle paylaşırım Sen sessizliğimi paylaş benimle Gözlerime dal Orada kal Göreceksin Anlatmak böyle daha kolay......', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dost-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yaşıma Göre', 'gonul-yasima-gore-ayse-birgul-yilmaz-p78ct', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki bir şeyler eksik

İçimde bir boşluk,

Sanki bir şeyler fazla

İçimde bir hoşluk

Aşık olmak sevilmek

Ve sevmek istiyorum

Kalbimce düşlerimce

Gönül yaşıma göre..

Eski yaralardan kurtulmak

Yeni bir gelecek kurmak

Dolu dizgin bir aşk yaşamak

İstiyorum, gönül yaşıma göre', 'Sanki bir şeyler eksik İçimde bir boşluk, Sanki bir şeyler fazla İçimde bir hoşluk Aşık olmak sevilmek Ve sevmek istiyorum Kalbimce düşlerim...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-yasima-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Çiçekleri', 'kiraz-cicekleri-birsen-ates-4l0ad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ıssız bir gecenin içindeydi gölgem

hüzünlerim taşıyordu 

öfkesini gizleyen aynalara

ruhuma dokundu yine bahar

kalkamıyorum düşlerden

özlediğim ölümü kusuyorum

intihar ediyor gece gözlerimde

uykulardan döndüm yine

geçiyor yapayalnız 

kirpiklerime asılmış bahar

sayıklıyorum

açacak yine kiraz çiçekleri

02.03.06', 'ıssız bir gecenin içindeydi gölgem hüzünlerim taşıyordu  öfkesini gizleyen aynalara ruhuma dokundu yine bahar kalkamıyorum düşlerden özlediğ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kiraz-cicekleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Fotoğraflar', 'eski-fotograflar-fevzi-gunenc-7hqom', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar benim de 

genç ve güzeldi fotoğrafım 

gün geliyor onlar da 

sararıp soluyorlar 

solmakla kalsalar iyi 

zaman içinde tek tek 

ortadan kayboluyorlar. 

haftalık fotoğraflar çekerlerdi 

fotoğrafçılar bir zamanlar

rotuş yaparlardı kara kalemle 

tab etmeden önce filmlere

artık kendileri olmayan bu fotoğraflarına bakar 

mutlu olurdu insanlar. 

Güzelleştirirlerdi yüzünüzü çirkinseniz 

burnunuza estetik yapanlar olurdu 

daha memedeydiniz o zamanlar siz 

nereden bileceksiniz. 

Ortanca halam haftalık fotoğraf 

çektirmişti o yıllarda, bir gün 

o kadar güzel çıkmıştı ki

siz “melek” deyin, ben “huri” deyim 

sormak zorunda kalmıştı o 

''Bu güzel kadın ben miyim? '' 

demeden yanlıştır, demeden ayıp 

halam, camlattırılıp çerçevelettirilerek

vitrine konmasına izin vermişti fotoğrafının 

ısrara dayanamayıp. 

O an halam dünyayı sallamayacaktır 

ama bedeliyse 

düşüncesizliğinin 

bir araba sopa olacaktır. 

Şeytanın işi gücü yok pislik peşinde gezer 

ertesi gün eniştemin koluna girer. 

ikisi fotoğrafçının önünden geçer. 

Basar mı bizimkinin yüreğini bir çarpıntı 

Görünce resmi kalayı basar eniştem

''Vay, bu karı benim karı değil mi! 

Ne de güzel çıkmış şırfıntı! ” 

“Vitrinlere fotoğrafını koydurursun ha! 

dur ben sana gösteririm eve gelince 

bir rotuş çekeyim sana da gör 

haftalık fotoğraf gibi ince...”

Ne eniştem var artık ne 

o fotoğraftaki halam 

ne de ben olacağım günü gelince…

“Pip”leyecek hepimizi azrail 

''sobe'' deyip ''solum sağım...'' 

sırra kadem basacak yarın 

fotoğrafları gibi kendileri de 

insanların.', 'Bir zamanlar benim de  genç ve güzeldi fotoğrafım  gün geliyor onlar da  sararıp soluyorlar  solmakla kalsalar iyi  zaman içinde tek tek  or...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/eski-fotograflar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Yavrum (Nasihat)', 'dinle-yavrum-nasihat-ayse-birgul-yilmaz-57y0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yavrum şimdi bizi çok iyi dinle

Her anne her baba gibi seninle

Sana en yakın biz olmak isteriz

Biz seninle gurur duymak isteriz

Önünde uzun bir hayat yolu var

Yıllarla büyüyüp serpileceksin

Her işin temeli sevgiyle başlar

Sende seveceksin, sevileceksin

Yaptığın iyiliktir yanına kalan

Her hamle bir derman katsın ömrüne

Para da şöhrette servette yalan

Hayatı yaşayıp öğreneceksin.

Helal yoldan gelsin ekmeğin aşın

Her yerde her zaman dik olsun başın

Sözüne inansın her arkadaşın

Çok zaman hatayı hoş göreceksin.

Güçlüklerden yılma, yıkılma sakın

Boş söze, hoş yüze kapılma sakın

Unutma ki yavrum yolu bir aklın

İlk önce kendine güveneceksin.

Hayat mücadele, yaşamak çok zor

Kader deme, isyan etme boş verme

Kimseden kimseye hayır gelmiyor

Yeter deme, dene, bir daha dene..', 'Yavrum şimdi bizi çok iyi dinle Her anne her baba gibi seninle Sana en yakın biz olmak isteriz Biz seninle gurur duymak isteriz Önünde uzun ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dinle-yavrum-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irak Ve Amerika', 'irak-ve-amerika-betul-pehlivan-n77l6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günün birinde, anlamsız 

Ve aniden bir savaş,

Bir sürü ölüm çığlığı,

Top, tank sesleri,

Yeri, göğü inletiyordu.

İnsanlar bıkmıştı artık.

Saddam bile bıkmıştı kaçmaktan,

Ama Amerika bırakmadı,

Irak’ın peşini,

Halk, çırıl çıplak, evsiz barksız,

Sokaklarda perişan bir halde.

Amerika petrol peşinde,

Yöneticileri Saddam ise kaçmakta.

Halk isyan ediyor,

Amerika’nın umurunda değil,

Saddam yine kaçıyor,

Durum yine aynı,

Değişmezde zaten.

Size söylüyoruz Amerika

Bırakın artık,

Şu anlamsız savaşı

Siz kurtulun, biz kurtulalım.

Bu savaşlı Dünya''dan..............

19 Ekim 2003/Kırıkkale', 'Günün birinde, anlamsız  Ve aniden bir savaş, Bir sürü ölüm çığlığı, Top, tank sesleri, Yeri, göğü inletiyordu. İnsanlar bıkmıştı artık. Sad...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/irak-ve-amerika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Ağaçtan Öğütler', 'kucuk-agactan-ogutler-betul-pehlivan-i2lgs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir küçük ağacım,

İlkbaharda açarım,

Sonbaharda yapraklarımı dökerim.

Kışın kururum,

Havanızı kirletmem,

Nefesinizi tazelerim,

Yurdunuza güzellik katarım,

Etrafa neşe saçarım.

Eğer beni kesersen,

Bende sana küserim,

Ne barınabilirsin,

Ne de oturabilirsin.

Anladın değil mi yararlarımı,

Haydi ağaç dikmeye koş.

(*)  Bu şiirim okulda birinci olmuştur. 2003-Kırıkkale', 'Ben bir küçük ağacım, İlkbaharda açarım, Sonbaharda yapraklarımı dökerim. Kışın kururum, Havanızı kirletmem, Nefesinizi tazelerim, Yurdunuza...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kucuk-agactan-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babacığım', 'babacigim-betul-pehlivan-1f4ok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün ve her gün sizin için önemlidir.

Özellikle de babalar günü v.b günler çok önemlidir.

Sen bir iş sahibisin, evin her türlü ihtiyacını giderirsin.

Bunun için, sevgili babacığım,

Bizde bu günü sana hediye ettik.

Seni seviyorum...

Bu evin tüm yükünün yarısını yüklensen bile,

Herkesin mutlaka dinlenmeye hakkı vardır.

Yaz, kış demeden çalıştın,

Evin geçimini sağladın.

Seni seviyorum...

15 Haziran 2002 Kırıkkale (23:20)', 'Bugün ve her gün sizin için önemlidir. Özellikle de babalar günü v.b günler çok önemlidir. Sen bir iş sahibisin, evin her türlü ihtiyacını g...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/babacigim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihi mardin', 'tarihi-mardin-abdulvahap-altay-w0yym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kalesinden bakınca kuş bakışı manzarası

deniz gibi görünür o yemyeşil ovası

uzaktan görüntüsü sanki kartal yuvası

nakışlı minareler,medreseler cabası

deyrulzafaran,dara,ulucami ve kırklar

her birisi ap ayrı bir tarih anlatırlar

camiler,hanlar,kilise ve hamamlar

başka yerde bulunmaz bin yüzyıllık çarşılar

ihtişamdan geçilmez cihangir kasımiye

her hanıyla gizemli yedi asırlık zinciriye

avrupa ilan etmiş uygarlık baş kenti diye

bu haysiyet ve onur yakışır mardin''liye

her ırktan her mezhepten her dilden ve her dinden

yaşarlar bir arada kürt,arap,türk demeden

modern avrupa bile ibret alıyor bizden

gel sende gör şahit ol yolun geçse mardin''den', 'kalesinden bakınca kuş bakışı manzarası deniz gibi görünür o yemyeşil ovası uzaktan görüntüsü sanki kartal yuvası nakışlı minareler,medresel...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Altay']::text[], 8.5, '{"poet":"Abdulvahap Altay","poet_slug":"abdulvahap-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tarihi-mardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı', 'coban-yildizi-kevser-gulistan-cakir-9l32y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece

Odalar sıktı beni

Balkonda buldum kendimi

Bir ses uzaklardan

- Şiişt dedi

Unuttun mu seni beklediğimi? 

Başımı kaldırdım

Yıldızımı kucakladım

Sordu bana

- Nerelerdeydin? 

Hasret kaldık uzun zamandan beri

Sevmiyor musun artık geceyi? 

Şimdi anlat bana

''Nar tanesi'' sevgilini

Eskisi gibi...

- Sus, hiç açma dedim kapanmış yarayı

Yaman şeymiş yaşamak

Geceler sevgiliyi düşünmek

Ve sana anlatmak içindi

Anlamsız artık konuşmak...

Meğer

Yüksüz bir kalbi taşımak

Dolu bir kalbi taşımaktan zormuş

Fuzûlî''yi anıyorum sık sık

''Aşk imiş her ne var ise âlemde''

Gerisi boşmuş...', 'Bir gece Odalar sıktı beni Balkonda buldum kendimi Bir ses uzaklardan - Şiişt dedi Unuttun mu seni beklediğimi?  Başımı kaldırdım Yıldızımı ...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/coban-yildizi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peynir', 'peynir-suat-seymen-qah6p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu sabah dilim nefis bir peynir tattı

damağım nasıl şapırdıyacağını sapıttı

hangi ineğin eseriydi kim bilir

mideme dedim ki, o bir başyapıttı...

aralık 2005', 'bu sabah dilim nefis bir peynir tattı damağım nasıl şapırdıyacağını sapıttı hangi ineğin eseriydi kim bilir mideme dedim ki, o bir başyapıtt...', ARRAY['Türk Edebiyatı','Şiir','Suat Seymen']::text[], 8.5, '{"poet":"Suat Seymen","poet_slug":"suat-seymen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/peynir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay/gülüm..', 'ay-gulum-selma-sengoren-axart', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay yüzünde,”elif’te gamze

Yüreğine gülümsemesi düşünce

Özlediğin hatıraların pembesinde

Sen, gülü hiç sevdin mi

İnci tanesine saklarken mavileri

Gökyüzünde uçuşan hayalinde

Sızısı düştü mü hançerine

Sen, ayrılığı hiç sevdin mi	

Gölgesinde yas tutmuş firari bakışların

Ağlarken yağmurların tanesinde

Unutulmanın kurşun yarasında

Sen, hasreti hiç sevdin mi

Avuçlarında kurak boşluğun olmazlığı

Vurgunlarda kaybolan gözbebeklerin

Nur ışığın açılarken semaya

Sen, çaresizliği hiç sevdin mi

Ceylan bakışlı yas tutar özlemine

Yaprağına yazılır solar an geçtikçe

Sevda sümbülü eğilmeden yere

Gülbaharını kışa dönüştürme

	

Sen, ölümü hiç sevdin mi? 

div align=''center''embed src=''http://www.canatilla.com/track/3maradespina.mp3'' width=''100'' height=''16'' autostart=''true'' loop=''true''/embedbr /', 'Ay yüzünde,”elif’te gamze Yüreğine gülümsemesi düşünce Özlediğin hatıraların pembesinde Sen, gülü hiç sevdin mi İnci tanesine saklarken mavi...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ay-gulum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr/sızım', 'y-r-sizim-ahmet-turan-altunsu-gefg1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'halâ suskun ar/sızım…

kabuğunda yine hangi düşlere daldın? 

hangi yanlış hesaplardan çıkan bakiyedir

ki bir başına kaldın? 

geçmek bilmiyor sızım...

saklanma yaratılarını yorgan yapıp altına...

kurma daha fazla sakil düşler...

türkuaz perdelerde yansıyan karaltına

gölgem düşer.

bense uzak mesafelerde beklerken çaresiz; 

kayıp gölgeme hasret, ölüme umarsızım.

öylesine ayarsızım...

kanıma dek işleyen bir illet şu yâr sızım.

bilmez misin yârsızım? ! .

..............02/03/2006 / Güdül / Ankara

...................Ahmet Turan Altunsu', 'halâ suskun ar/sızım… kabuğunda yine hangi düşlere daldın?  hangi yanlış hesaplardan çıkan bakiyedir ki bir başına kaldın?  geçmek bilmiyor ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yar-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hoş Olur', 'ne-hos-olur-esat-korkmaz-8oo71', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne hoş olurdu

çözüversen beni çıpadan

maviliklere açılsam

dalgalar yalasa takayı

dalgalar yakalasa  beni 

süzülen  mercanın ardında

ulaşamasam da Kızıl saçlarına

kıvrıla kıvrıla yüzüşüne asılsam 

düşsem peşine 

açılsam dalgaların emrinde enginlere

kızsam bazı 

oynaşırken savrulan sulara 

düşünmesi bile hoş 

düşüncenin sonsuzluğunda olmak

sen yokken

seninle olmak

baş başa ve  başıboş sürüklenmişken

zümrüt yeşiline yaslanmış kıyılara

mercan  kayalıklarda bağdaş kurup

mavnalarda geçişini seyre dalmak

ne güzel', 'ne hoş olurdu çözüversen beni çıpadan maviliklere açılsam dalgalar yalasa takayı dalgalar yakalasa  beni  süzülen  mercanın ardında ulaşamas...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-hos-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Kızı', 'yagmurun-kizi-i-brahim-agoren-9syqq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurun Kızı

Eteğini rüzgara savur yağmurun kızı,

savurki her baktığımda 

                  içim alev alev

                            Yüzüm ıslak ıslak olsun; 

al,al kalbimi senin olsun.

Büyüsün

           büyüsün yağmurun kızı aşkımız,

her geçen gün bulut bulut

        sağnak sağnak büyüsün.

Üşüsün kalbim sen olmaysan yanımda,

dudağına bir öpücük,

bir okşayış saçlarına

      doya doya yağmurun kızı

                               doya doya; 

gelmeden üstümüze kara bulutların şimşek çakması.', 'Yağmurun Kızı Eteğini rüzgara savur yağmurun kızı, savurki her baktığımda                    içim alev alev                             Yüzü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ağören']::text[], 8.5, '{"poet":"İbrahim Ağören","poet_slug":"i-brahim-agoren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurun-kizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezan Sesleri', 'ezan-sesleri-yunus-emre-ozsaray-223zm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ne davudi bir ses bu ne güzel bir sada

Bütün güzellikleri kendinde toplamış da

Yükseliyor öylece arş-ı âlâya

Sanıyorsun Bilal-i Habeşi hala yaşıyor

Ve Resulullah birazdan namazı kıldıracak

Sağ yanına Ebu  Bekir sola Ömer duracak

Dalıp gidiyor insan bir lahza Asr-ı Saadete

Bu sesle ulaşıyor mü''minler ebedi bir saadete

Ne ulvî bir haz bu ya Rabbi kuşatıyor dört bir yanı

İştiyakının ateşiyle yakıyor mahlûkatı

Zerreden küreye ne varsa teyakkuza geçiyor

Sonra diriliyor yeryüzünde nebatat

Hep bütün mahlûkat kulak kesilmiş dinliyor

Kavrulan tüm sineler bu sesle serinliyor

İlk nida: Allahu Ekber Medine''den yükseliyor

Selahaddin Eyyubi ile Kudüs''ü fethediyor

Ardından bir şahadet bu ne kudsi bir yemin

Ve tarumar oluyor Bizans denen o zemin

Ayasofya''dan yankılanıyor  salâh salâh sesleri

Topkapı''dan duyuluyor felahın nefesleri

Sonra yine bir nida ve yeniden Allahu Ekber

Diriliyor sandım o an Süleymaniye''den makber

Ardından dönüyor ses semtimdeki Camiiye

Yok oluyor Fatih İstanbul Kudüs

Ondan başka ne varsa, yok var olandan başka

Kayboldu hayalimden bu son çıkan ses ile

Bu ezan sesleri dolaştırdı kendime

Ve döndürdü yüzümü kaybolan tarihime

Ne şanlı bir tarihin evlatları imişiz

Ne mü''min bir ceddin mirasçıları imişiz

Rabbim sana duamdır susmasın bu ezanlar

Bu millet senin için vermişti ya çok canlar

Bir o kadar can yine sana fedadır

Yeter ki kubbemizden eksilmesin ezanlar', 'Bu ne davudi bir ses bu ne güzel bir sada Bütün güzellikleri kendinde toplamış da Yükseliyor öylece arş-ı âlâya Sanıyorsun Bilal-i Habeşi ha...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre Özsaray']::text[], 8.5, '{"poet":"Yunus Emre Özsaray","poet_slug":"yunus-emre-ozsaray","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ezan-sesleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Yok Benim', 'adim-yok-benim-atilla-guler-fcqze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilmez ellerim toprak kokusunu

yağmuru hiç yaşamadı

kanamadı hiç

bir gülün dikenini tutup

koparmadı elmayı dalından

yağmur sularında ıslanmadı saçlarım

ve okşanmadılar…yumuşacık

kokusu sinmedi fesleğenin

parmak uçlarıma

çamurlara bulanıp top oynamadım

bomboş tarlalarda

hiç ''baş'' oynamadım

alacalı misketlerimle…tozlu sokaklarda

kırmadım camlarını komşuların

kaçmadım sonra da korkudan

gizli gizli gitmedim

erotik filmler gösteren sinemalara

içmedim sigaramı tuvalette

ya da buz gibi balkonların korkuluklarına yaslanıp

burnumu hiç silmedim koluma

dövmedi beni hiç kimse 

çileden çıkıp yaramazlık yaptığımda

hiç kavga etmedim

''oraya ben oturacağım'' diye

pır pır edip

birine düşmedi gönlüm

gözlerine dalıp

tutsak olmadım bilinmezliklere

aynı havayı solumadım bir dostla

şiirlerim olmadı benim

havaya savurmadım sözleri

ne ağladım

ne güldüm

ben doğmadan öldüm

adım yok benim', 'bilmez ellerim toprak kokusunu yağmuru hiç yaşamadı kanamadı hiç bir gülün dikenini tutup koparmadı elmayı dalından yağmur sularında ıslanma...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/adim-yok-benim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-kemal-oguz-lce0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün sesinizi duymayi istedim

Herzamankinden daha cok

Bugün, özel bir günümdü

Bunu Sizde biliyordunuz

Benim dogum günümdü

Kapimi calarsiniz diye bekledim

Daha önceleri geliyordunuz

Veya, telefon acip ariyordunuz

Pencereye kostum, gelirsiniz diye

Bazen gözlerim telefona takildi

Belki ararsiniz diye

Unutmus olabilirmisiniz? 

Bir telefon bile etmediniz.

(Filderstadt, 02 Mart 2006)', 'Bugün sesinizi duymayi istedim Herzamankinden daha cok Bugün, özel bir günümdü Bunu Sizde biliyordunuz Benim dogum günümdü Kapimi calarsiniz...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bugun-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yol Nerde Biter Gardas', 'bu-yol-nerde-biter-gardas-yasar-gurlek-idh5e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkez  bir  yol   tutmus  gider

Bu    yol   nerde    biter  gardas? 

Coller     asip,   daglar    gectim

Bu    yol   nerde    biter  gardas? 

Her      cileye,    gogus   gerdim

Olmedim,de        cok     eridim

Her      yola     bir    iz   verdim

Bu    yol   nerde    biter  gardas? 

Beyaz    guller   mora    dondu

Ask     atesi,      yanip    sondu

Yollarda       ayagim       yandi

Bu    yol   nerde    biter  gardas? 

Aglamadik     gunmu      kalmis

Felek     beni     benden     almis

Alip    yerden,     yere       calmis

Bu    yol   nerde    biter    gardas? 

Sevda      seli      birden    durdu

Felek    vuracagin,    alip   vurdu

Her     yoluma     tuzak     kurdu

Bu    yol   nerde    biter    gardas? 

Yasar,i     selimle    akar    caglayan

Baci   ile   anamdir,   bana    aglayan

Bir  vefasiz  yar  idi,  beni  daglayan

Bu      sevda     nerde    biter  gardas? 

Elbette   mezarda  gardas

YASAR  GURLEK

03-03-2006

ROTTERDAM

HOLLANDA', 'Herkez  bir  yol   tutmus  gider Bu    yol   nerde    biter  gardas?  Coller     asip,   daglar    gectim Bu    yol   nerde    biter  gardas...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-yol-nerde-biter-gardas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasirlasmis Bu Sevda Derin Kokludur', 'nasirlasmis-bu-sevda-derin-kokludur-yasar-gurlek-wr66m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sey  yalan,   her sey  bos,    aldanip durdum

Sag  dondum,  sola  dondum,  hayaller  kurdum 

Anladim,ki     bu     dunya,      ah    ile    vahmis

Bosa      gonca     gullere      baglanip    durdum

Bir       belaki      aklimi,         aldi       basimdan

Bogulup        gittim,         goz          yaslarimdan

Bir         vefa        bekledim,      gardaslarimdan

Her sey  yalan,    her sey  bos,   aldanip durdum

Basimi          taslara,           vursam        hakkidir

Yillanmis        bu     ates,      bende        saklidir

Nasirlasmis       bu     sevda,      derin    kokludur

Bosa      gonca   ,  gullere,      baglanip    durdum

Bulbul       bana     diyor,ki     neden      aglarsin

Yazik  (yasar)     bosa,      yuregini        daglarsin

Irmak      olur       sel          olursun,      caglarsin

Her sey  yalan,   her sey  bos,   aldanip durdun.

YASAR  GURLEK

03-03-2006

ROTTERDAM

HOLLANDA', 'Her sey  yalan,   her sey  bos,    aldanip durdum Sag  dondum,  sola  dondum,  hayaller  kurdum  Anladim,ki     bu     dunya,      ah    ile...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasirlasmis-bu-sevda-derin-kokludur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevmek....', 'seni-sevmek-ercan-akbay-w43a7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek güzel,

    Seni sevmek daha da güzel,

    Seninle olmak hepsinden de güzel...

    Ama özlemin yok mu,

    Ayrı geçen gündüzlerde,gecelerde

    Sorma gitsin..

    O yangını,sorma hiç

     Ne bu yatak, yatak,ne bu ev, ev

    Ne bu oda,oda..

    Senin ateşinde kavrulmak kadar,

    Senin yokluğunda yanmakta güzel.....

                                         3.3.2006', 'Seni düşünmek güzel,     Seni sevmek daha da güzel,     Seninle olmak hepsinden de güzel...     Ama özlemin yok mu,     Ayrı geçen gündüzler...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sevmek-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Vakit Erken', 'daha-vakit-erken-melih-coskun-l1ckr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha vakit erken

Vurmadı akrep gecenin ikisini 

Ve gece farkında değil henüz gece olduğunun 

Daha vakit erken 

Ay ışığı çizmedi resmini daha sulara

Deniz çekiyor şehrin bütün ayyaşlarını kıyısına 

Ne kadar da kolay sarhoş olmak bu gece 

Deniz kokusunu imbiklemek ciğerlerinde

Yahut düşünmek bir çift gözün imkansızlığını kalbinde 

Onun için ağlamaklıdır bu gece bütün şarkılar 

Ve  farkında değildir gece, 

Gece olduğunun, 

Çünkü ay ışığı yıkanmamıştır henüz sularında

Şimdi kopartıp otuz yılın bağrından 

Koskoca  bir taşı yosunlar içinde 

Savursam Dolmabahçe kıyısından geceye, 

Küfretsem ağız dolusu gelen sabaha 

Biliyorum, 

Faydası olmayacak 

Denizler yükselip boğmadan bu kenti 

İsyanımı kimse duymayacak 

Tükenip, kahrolmadan 

Yüzüme kimse bakmayacak...

Gece bekçileri uyuklamaya başladı işte nöbetlerinde 

Son ışıklarda söndü apartmanlarda 

Sustu son vapurunda düdüğü

Baş başa kaldık işte seninle gece

Şiirimin anayurdu yalnızlığımla birlikte 

Kim boyadı şu masmavi denizi siyaha 

Almayın elimden kalemimi 

Bu kadar acımasız oldukça gerçek

Daha çok şiirim var yazılacak 

Daha çok gecem var 

Deniz kıyısında yalnız yaşanacak...

18 Mart 2003

www.melihcoskun.com', 'Daha vakit erken Vurmadı akrep gecenin ikisini  Ve gece farkında değil henüz gece olduğunun  Daha vakit erken  Ay ışığı çizmedi resmini daha...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/daha-vakit-erken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İstiyorum', 'yasamak-i-stiyorum-nedret-celen-dk8po', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorum

Çiçekler koklayarak

Yaşamak...

Toz,duman,barut kokusundan uzak

Güneşin bulutlardan sıyrılışını,

Mehtabı izlemek istiyorum

Sessiz gecelerde...

Barış sıcaklığında,huzur tadında

Taa... içimde duyarak

Sevgi istiyorum

Hilesiz,hurdasız,katkısız

Hissederek,tadarak

Yükselmek istiyorum

Kanat takıp,göklere değil

Basamak basamak

Ayaklarım üzerinde durarak

Yaşamak istiyorum

Çalışmak,çabalamak

Yaratmak...

Üretken bir toplumun

Ferdi olarak

El ele aydınlığa doğru koşarak

Karanlıkta her ne varsa

Yıkmak

Sonsuzluğun güneşine ulaşmak

Yaşamak istiyorum

İnsanca,uygarca

Doyasıya yaşamak...', 'Yaşamak istiyorum Çiçekler koklayarak Yaşamak... Toz,duman,barut kokusundan uzak Güneşin bulutlardan sıyrılışını, Mehtabı izlemek istiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Nedret Çelen']::text[], 8.5, '{"poet":"Nedret Çelen","poet_slug":"nedret-celen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasamak-istiyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konsomatris', 'konsomatris-ethem-turan-3pp8m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şarabın güzelliğindedir 

Sendeki güzellik 

Gece loş ışıklar  alıp götürür

Bir oyana bir bu yana

Karanlık sokaklar ağırlar seni

Sabah ışıması uykunu getirir

Günahların  ve kahreden vefasızlık 

Bütün ağırlığıyla çöker üstüne

An gelir sende tanıyamazsın kendini

Karşısından ayrılmadığın aynalar küser 

Elini tutacak sıcak elin olmaz 

Baş başa kalırsın göz yaşlarıyla

Düşlediğin evin olur belki 

Tükenmiş ruh artık seni uyutmaz 

Dönüşü istesen de geriye dönüş olmaz 

Kirlenmişliğin kokusu yayılır ruhundan

Ağır gelir bu şehrin sokakları 

Kaçıp kurtulmak istersin belki 

Gittiğin her şehir seni ağırlar 

Tekrar başlarsın bıraktığın gibi

Şarabın güzelliğindedir  sendeki güzellik 

Yıllandıkça tat verir

Mertçe çerez olursun  içki masalarına 

Alem bu ya

Sende alem kadını olursun  masalara

Senin olmayan  sahiplere 

Yem olup  gün gün yok olur

Kaybettiklerinin çukurunda kaybolursun 

Gönül kuşunu uçurmadan 

Keşkelerle dolu bir dünyada 

Bir yudum gerçek sevgiyi tatmadan 

Aşk şarabına dudak değdirmeden 

Fıçılar  dolusu içersin 

Yaşanası dünyada

 Gerçek sevgiyi bilmeden 

Ömür tüketir

Kahırlar içinde seni saracak kol 

Yanında olacak bir eş bulmadan 

Öylece geçip gidersin 

Şarabın güzelliğindedir sendeki güzellik 

Ne dersin?', 'Şarabın güzelliğindedir  Sendeki güzellik  Gece loş ışıklar  alıp götürür Bir oyana bir bu yana Karanlık sokaklar ağırlar seni Sabah ışıması...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/konsomatris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilginin Affı Olursa Bağışla', 'yenilginin-affi-olursa-bagisla-cemal-karsavran-1roak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ağlıyor düşlerim gecelerde

simgesi kaybolmuş şiir hecelerimin

lüle lüle sigaramın dumanında 

üşüyor titrek titrek

ıslık çalıyor dudağımda sevi

canlanan arzu dolu uyanış

azgın dalgalara yenik düşerken

nazı çekilir bir süreç değil biliyorum

yeni filizlenmiş yürek bağında

kurbanıyım fakirliğin ne yapsam

gümüş balığı teninde tenim

üstünü örtüyor yalanlarla süslü kelimeler

nifak çadırı açmış ovaya

esir olmuş arzuların peşinde

yenilginin affı olursa bağışla', 'ağlıyor düşlerim gecelerde simgesi kaybolmuş şiir hecelerimin lüle lüle sigaramın dumanında  üşüyor titrek titrek ıslık çalıyor dudağımda se...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yenilginin-affi-olursa-bagisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamak', 'hamak-abdulvahap-ates-u1ou3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beden sonlu hayatın hizmetindeki yamak

Her tadın arkasında ömür çürütür damak

Yarın şu yüklü bulut yarın cam gözlü serap

Nereye kadar beler dünya denilen hamak.', 'Beden sonlu hayatın hizmetindeki yamak Her tadın arkasında ömür çürütür damak Yarın şu yüklü bulut yarın cam gözlü serap Nereye kadar beler ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hamak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle bir gün olsun işte', 'oyle-bir-gun-olsun-iste-nurten-altinok-11sz1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olur da! 

Bir bayram sabahına rastlarsa vedam

Duyurmayın dostlara

Mim düşmesin kutlamalara

Gecenin bir vaktiyse eğer 

Haber vermeyin komşulara

Korku düşmesin uykulara

Olur da! 

Karakışın ak karına rastlarsa gidişim

Sessiz olsun aranızdan ayrılışım

Islanmasın kar taneleri gözlerinizde

Kıyamam hiç birinize

Dallarda ne çiçek olsun ne de meyve

Ne kar yağsın ne yağmur

Ne rüzgar essin ne boran

Öyle bir gün olsun ki

Ne gece olsun ne sabah

Ne kış ne bahar

Öyle bir günde olsun ki gidişim

Hiç kimse fark etmesin...', 'Olur da!  Bir bayram sabahına rastlarsa vedam Duyurmayın dostlara Mim düşmesin kutlamalara Gecenin bir vaktiyse eğer  Haber vermeyin komşula...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyle-bir-gun-olsun-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı Şehirdi Gözlerin Yakalandım', 'yasakli-sehirdi-gozlerin-yakalandim-sultan-i-nan-by9wu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'başımı yaslayıp bin bir gece masallarına				

okyanusların taa...dibinde bir gece					

kaldırıp bağdaş kurarak yudumladığım tarhanadan başımı		

tüm yasakları cigneyerek 					

ve yıkarak olmazları					

seni düşünüyorum					

keşke diyorum 					

keşke    					

bunca sevginin arasına 					

girmeseydi kuşku					

ve ben senin hünerli ellerindeki acemi gülüşe takılmamış olsaydım	

tüm hayata şahitliğimle sesiz duran tanığı olsaydım bu kentin		

taş olsaydım örneğin					

sus pusu olsaydım bu aşkın					

istanbul olmasaydı					

sen sıla olmasaydın					

ben eyüp sultan bulvarında ölmeseydim				

sen görmeseydin					

çekip gitmeseydim					

					

bir yanım sıla diyorum					

bir yanm istanbul					

bir yanım vapur

bir yanım kara sapan

tarlalarında taşlarla tökezletilmiş ekin

her ana seni doğuruyor bana

her çocuk bende büyüyor biraz daha hayata acemi

sokakları pezevengle taşan bu şehir 			

dişleyerek etini etimde			

her sorgu mazgalında beynimi tüketiyor			

her el bende hünerleşiyor

her silah bende hedefine yakın

her makinanın tek işcisi benim

her dişlinin zinciri bu carkı ceviren

her acı bende yok oluyor

her çılgık bende biraz daha katıyor kendini kendine

öyle canım çekiyor

öye canım çekiyor işte

ancak dudaklarında tatlanacak 

meyveyi

benbahar1111', 'başımı yaslayıp bin bir gece masallarına				 okyanusların taa...dibinde bir gece					 kaldırıp bağdaş kurarak yudumladığım tarhanadan başımı...', ARRAY['Türk Edebiyatı','Şiir','Sultan İnan']::text[], 8.5, '{"poet":"Sultan İnan","poet_slug":"sultan-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yasakli-sehirdi-gozlerin-yakalandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanrılı Siliuet', 'sanrili-siliuet-birsen-ates-54tan', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir anda değişir alın yazın

ne olduğunu anlayamadan 

düşersin kuyulara

uzatırsın elini

tutan olmaz kalakalırsın

kapatırsın kendini

dört duvar arasına

içindeki çığlıklar büyür de

hiç kimse duymaz

yapayalnız bir başına

konuşursun aynalarla 

sevecek kimseyi bulamazsın

ki o yüzden

suretini seversin sadece

kendi kendiyle dost

uzaksındır artık sevgiden

mevsimler gelip geçer

gözlerini de asarsın geceye

sanrılı siliuettir artık

göremez kimse

03.03.06', 'bir anda değişir alın yazın ne olduğunu anlayamadan  düşersin kuyulara uzatırsın elini tutan olmaz kalakalırsın kapatırsın kendini dört duva...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sanrili-siliuet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile...! ! !', 'nafile-nazan-i-zmirli-nskou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen  den  sana  kaçıyorum

ıssızlığın   sessizliğin

kaybolmuşluğun  ortasında

yağmurlarına  yakalanıyorum.

adsız   kuşların   şakıyor

yüreğimdeki  yalnızlığı  sararcasına

zirvelerime  oturuyorsun  duman  duman

ara ara çıkıyorsun kara bulutların ardından.

kıpır  kıpır  oluyor  yorgun  kalbim

koşturuyorum   yakomozlarına

azgın  dalgaların  ardından

nafile...! 

sen  hep  aldatansın

ben se med-cezirlerinde 

aldanan

sen den sana kaçıyorum

sen den sana sığınıyorum

yağmurlarına yakalanıyor

dolularına avuç açıyorum

karlarında eriyor

dalgalarında kayboluyorum

senden sana kaçıyor

seninle......................

yine sensiz kalıyorum.

20.01.2005-antalya-çıralı', 'sen  den  sana  kaçıyorum ıssızlığın   sessizliğin kaybolmuşluğun  ortasında yağmurlarına  yakalanıyorum. adsız   kuşların   şakıyor yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nafile-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmayacaksın', 'yanmayacaksin-mikdat-bal-mqcg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seversen eğer

Verirsen değer

Yanarsa çiğer

Yanmayacaksın

Düşmüşsen aşka

Dil etmez laçka

Sen ondan başka

Anmayacaksın

Olursa cinnet

Gider farz sünnet

O zaman cennet

Onmayacaksın

Rabb’a dönersen

Yanıp sönersen

Hamdi denersen

Kanmayacaksın

Ara her yerde

O çare derde

Arada perde 

Sanmayacaksın

Onu an her an

İndirdi Kur’an

Hep aşkıyla yan

Sönmeyeceksin

Rahmeti boldur

Gönlünü doldur

Bu ozan kuldur

Dönmeyeceksin', 'Seversen eğer Verirsen değer Yanarsa çiğer Yanmayacaksın Düşmüşsen aşka Dil etmez laçka Sen ondan başka Anmayacaksın Olursa cinnet Gider far...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yanmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gozlerinde Nemi Var', 'gozlerinde-nemi-var-yasar-gurlek-j9bac', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gozlerinde  nemi  var? 

Dipsiz   ucurumlar  var

Ucus bucaksiz  coller  var

Gozlerinde  nemi  var? 

Mavi  okyanuslar  var

Ask  var, 

Sevda  var,

Sevgi  var,

Gozlerinde nemi  var? 

Goz  bebeklerinde,  ben varim.

En  azindan sana  olan,  askim  var

Sevdam  var,

Birde  ne  var,  biliyormusun? 

Bir  Yarali,   yuregim  var,

Gozlerimde  nemi  var,cancan,

Sen  varsin,  sadece  sen,

Her  baktigim  nesnede,  sen,

Gozlerimde  nemi  var,

Sana  olan  askim,  var,

Sevdam  var,

Birde  ne  var  biliyormusun,

Senin  guzel,gozlerin  var,

Yetmezmi,  yetmezmi,

Al  yuregimde  senin  olsun,

Pesmurde   ben  olayim………..

YASAR  GURLEK

03-03-2006

ROTTERDAM

HOLLANDA', 'Gozlerinde  nemi  var?  Dipsiz   ucurumlar  var Ucus bucaksiz  coller  var Gozlerinde  nemi  var?  Mavi  okyanuslar  var Ask  var,  Sevda  v...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gozlerinde-nemi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depolamaya', 'depolamaya-sevinc-kavuk-vuvdk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir resim yapmıştım orta birde

Bir yerlimalı anısı üçüncü sınıfta

Yazıp, derleyip, canlandırdığım

Ama yaşım o zaman beş idi daha…

Bir nergizdi, mavinin her tonunda

Soğanı, toprağın her sıcaklığında

Fotoğraf çekerdim bağ, bahçe, mahalle

En büyük zevk, annemdi objektifimde

Karıncayı izler, sincaplarla oynardım

Doğada her güzelliği annem sanardım

Karelere ayırıp resimlemeyi denesem de

Gözüm ayrılmazdı ki silüetinden…

Yaşım sekiz olacaktı yıl sonuna az kala

Felaket değildi yaşanan henüz minik yuvamda

Bir okul töreniydi, ben ihtirasımla hatta

Öğretmenlerimin yüreklerini ezdim, bilerek ama

Yıl bin dokuz yüz yetmişe dayanmaya

Ramak kaldı diyemeden çöken kara bulut

Böcek yığıntısıyla da mikrop yaşar olura

Yüz tuttu değil, sadece mikrop artık…

Dünya yaşamı 24 saat varsayımda 

İnsan iki, pengüin yarım saatliğine 

Ziyaretçi olabiliyor ancak diyor bilimciler

Mikroplar yıldızların kiminde ama ebedi

Yıldızlarda doğuyor, kayanı da var ya hani

Kiminde yaşam var, mercekle şu görüneni

Bu yeryüzünün insan şeklinden mikropları

Orası depolamaya kulanılamaz mı acaba? 

1998  Yüreğime kâr yağdı

_____Yağan Nisan yağmuru olsaydı keşke', 'Bir resim yapmıştım orta birde Bir yerlimalı anısı üçüncü sınıfta Yazıp, derleyip, canlandırdığım Ama yaşım o zaman beş idi daha… Bir nergiz...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/depolamaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-akin-kelesoglu-m2hxq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece...

Gece bir kış gecesiydi

Buz tutmuştu dudaklarım

Dayanmış alınıma gözlerin...

Sevginin tadındaydım yumak yumak

Barbados`dan siyahi bir ipekti tenin

Nepal`de kaplan

Yârim benim

Akdeniz`de huzurlu bir insan...

Sevginin adı yok iken

Bir varmış bir yokmuşsun sen...

O sevgin

Okyanusta yücelen

Ellerinmiş meğer

Bembeyaz olduğunda gece

Sihirli ellerinde

İnanki sendin 

Tanış ellerindi senin

Tüm acılarım son buldu

Okyanusun ortasında

Uzattığında ellerini

O bana uzanan eller...

Bir varmıış bir yokmuşsun 

Sen meğer...', 'Gece... Gece bir kış gecesiydi Buz tutmuştu dudaklarım Dayanmış alınıma gözlerin... Sevginin tadındaydım yumak yumak Barbados`dan siyahi bir...', ARRAY['Türk Edebiyatı','Şiir','Akın Keleşoğlu']::text[], 8.5, '{"poet":"Akın Keleşoğlu","poet_slug":"akin-kelesoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram', 'sigaram-berk-gulen-g2k8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sigaram diye içerim,

Dumanını içime çekerim,

Küllerini cebimde saklayıp,

O sıcacık izmariti gül dudakların diye öperim

Anlamazsın ne zaman yandığını, 

Alevimle sırf küllerde kaldığını,

Bir kaç nefes daha alsam diye,

Benim gibisine katlandığını,

Anlamazsın...

Duman olup uçarken, bir sonraki dumanım olursun,

Aldanıpta kızma bana,

İçime çektiğimde seni, sen geçici duman değil,

Ebediyen ciğerim olursun, alev alev yanan...

Sen benim sigaramsın, 

En sevdiğim yanım,

Zararlı alışkanlığım,

Buz gibi bir havada içtiğim ellerim titrerken,

Bırakamadığım, tek hatıramsın bana...', 'Seni sigaram diye içerim, Dumanını içime çekerim, Küllerini cebimde saklayıp, O sıcacık izmariti gül dudakların diye öperim Anlamazsın ne za...', ARRAY['Türk Edebiyatı','Şiir','Berk Gülen']::text[], 8.5, '{"poet":"Berk Gülen","poet_slug":"berk-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sigaram-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıldım Yanlızlığıma', 'sarildim-yanlizligima-berk-gulen-ed3td', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün çok derinlere daldım

Yapayanlız sensiz,

Bir çift gördüm öpüşürken,

Ruhları bir, bedensiz

Seni düşündüm yanımda

Sarıldım yanlızlığıma,

İçim titredi buz kesildim birden

Sen yoktun yanımda...

Başımı koydum ve uzaklara baktım

Baktımki seni göreyim diye

İkimizi dansederken sarhoş

Buldum ve tebessüm ettim, gözlerimde umutla...', 'Bugün çok derinlere daldım Yapayanlız sensiz, Bir çift gördüm öpüşürken, Ruhları bir, bedensiz Seni düşündüm yanımda Sarıldım yanlızlığıma, ...', ARRAY['Türk Edebiyatı','Şiir','Berk Gülen']::text[], 8.5, '{"poet":"Berk Gülen","poet_slug":"berk-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarildim-yanlizligima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Dediğin', 'adam-dedigin-canan-motorcu-a2f50', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakışı derin olmalı adamın

Gözleriyle hissettiğini anlatmalı

Şöyle yürekten bakıverince sana

Ruhun ona akmalı

Öpüşü yumuşacık olmalı

Dudaklarına tüy gibi dokunmalı

Ta içten koparmalı seni

Nefesini hızlandırmalı

Teması sahiplenici olmalı

Bazen kelebek gibi

Bazen kaplan pençesiyle kavramalı

Bu nefis karışım damarlarını zonklatmalı

27.02.2006', 'Bakışı derin olmalı adamın Gözleriyle hissettiğini anlatmalı Şöyle yürekten bakıverince sana Ruhun ona akmalı Öpüşü yumuşacık olmalı Dudakla...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adam-dedigin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek Dediğin', 'erkek-dedigin-canan-motorcu-r4h9i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erkek dediğin sabırlı olmalı

Yapışmamalı insana

Ama başıboşta bırakmamalı

Ciddiyeti sevmeli

Laubaliliğe kaçıp

İlişkiyi cıvıklaştırmamalı

Her zaman mesafeyi korumalı

Ama kaçmaya kalksanda 

Seni salmamalı

Önce sarsmalı seni

Acılarını unutturup

Kafanı dağıtmalı

Sonra yeni baştan toparlayıp

Güven duygusu aşılamalı

27.02.2006  (22:10)', 'Erkek dediğin sabırlı olmalı Yapışmamalı insana Ama başıboşta bırakmamalı Ciddiyeti sevmeli Laubaliliğe kaçıp İlişkiyi cıvıklaştırmamalı Her...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/erkek-dedigin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüş', 'gulus-canan-motorcu-v9l9s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüşler içten olmalı

Dudaklarda kalmayıp 

Gözlere yansımalı

Keder içinde de olsan

Seni yanına alıp

Ruhunu ferahlatmalı

27.02.2006  (07:20)', 'Gülüşler içten olmalı Dudaklarda kalmayıp  Gözlere yansımalı Keder içinde de olsan Seni yanına alıp Ruhunu ferahlatmalı 27.02.2006  (07:20)...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gulus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen olmasaydın', 'sen-olmasaydin-elazigli-mustafa-kaya-i5y8t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kalbime akan bendeki 

aynı yalnızlığın olmasaydı,

ahhh…avuçlarım 

sıcak dokunuşlarını aramasaydı

ve,

hangi ağaçlar rast gelse

sen kokuyor olmasaydın

beni kokluyor olmasaydın

saçlarını ıslak bilip

taramak istemeseydim

benim seni dinleyişim gibi

senin, beni sevişlerin

sürekli kalbimde gezişlerin olmasaydı

sonsuz mavi sevdam,

kederli mavilere karışacaktı.

denizlerin ağzında,

kuytularda,

bir yalnızlık rüzgarı

olacaktım..

Mustafa kaya

03.03.2006 / çengelköy', 'kalbime akan bendeki  aynı yalnızlığın olmasaydı, ahhh…avuçlarım  sıcak dokunuşlarını aramasaydı ve, hangi ağaçlar rast gelse sen kokuyor ol...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-olmasaydin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esme', 'esme-canan-motorcu-zn0dj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ylkbahar çiçek açmy?

Dallar tomurcu?a basmy?

Benim divane gönlüm

Herzaman ki gibi hazanmy?

Esme deli rüzgar esme

Yüre?imi yerle yeksan etme

Kan a?layan ?u kalbe

Birde sen biber tuz ekme

14.02.2006', 'Ylkbahar çiçek açmy? Dallar tomurcu?a basmy? Benim divane gönlüm Herzaman ki gibi hazanmy? Esme deli rüzgar esme Yüre?imi yerle yeksan etme ...', ARRAY['Türk Edebiyatı','Şiir','Canan Motorcu']::text[], 8.5, '{"poet":"Canan Motorcu","poet_slug":"canan-motorcu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dan / set / sin...kal / bim.', 'dan-set-sin-kal-bim-nazan-i-zmirli-la8lm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'avuçlarına teslim

sıcaklığım.

topraktan toprağa 

dönme zamanı nı

ertele.

kalbim,

flizlenmeye hazır

döl.

en  özgür

düş gücün ile

bestele.

en görsel 

en özgün

uslübun ile

yarat  beni

sahnele.

dansetsin 

kalbim

estetik bir

eda ile

sen de

ve  sen 

artık   üşüme..........! ! ! ! 

.....................üşüme.........! ! ! ! 

................................ üşüme.......! ! ! ! 

03.03.2006-sende....', 'avuçlarına teslim sıcaklığım. topraktan toprağa  dönme zamanı nı ertele. kalbim, flizlenmeye hazır döl. en  özgür düş gücün ile bestele. en ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dan-set-sin-kal-bim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündükçe Daha da İnsanlaşacağım', 'dusundukce-daha-da-i-nsanlasacagim-zeynal-yaman-1n3ro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir insanım

Gönlüm deryalardan engin

Düşüncelerim sınırsız

Ben bir insanım

Dualar kadar hürüm

Ne mekân tutar beni ne de zaman

Yırtarım perdeleri bir bir

Yol alırım sonsuza

Ben bir insanım 

Yer benim için

Gök benim için

Mi''raç benim için

Kimler zincire vuracakmış beni

Kalbim zikrederken her an Allah''ı

Kimler perçinleyecekmiş dilimi? 

Ben bir insanım

Düşünme diyene inat

Düşünüyorum karanlık gecelerde

Düşüneceğim de

Güneş doğana dek dünyamıza

Artık kimse uyutamaz beni

Karanlıkların kara bağrında

Müezzinler Allahuekber diyene kadar ayaktayım

Ben bir insanım

Fıtridir idrâkim

Düşüneceğim

Ve düşündükçe daha da insanlaşacağım..:', 'Ben bir insanım Gönlüm deryalardan engin Düşüncelerim sınırsız Ben bir insanım Dualar kadar hürüm Ne mekân tutar beni ne de zaman Yırtarım p...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dusundukce-daha-da-insanlasacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buselerim sana', 'buselerim-sana-nazan-i-zmirli-1qffd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '..........sevdam............. 

..............uyan..............

uyan! 

güzel  ruh

gül  güzel  yüz

buselerim  sana

en  dokunulmamış

en  mahrem haliyle

sarıl  onlara

gözlerim  uykulu  ela  gözlerinde

dudaklarım    sıcacık  sen kokan  teninde

gitsin   yastığa  gömdüğün   sarhoşluğun

ben de

.................uyan....................

..............sevdam.................. 

.................uyan....................  

yeni  bir  gün  bekliyor 

kapının   eşiğinde 

günaydın   demeye

....................................uyan! 

03.03.2006-buselerim sana', '..........sevdam.............  ..............uyan.............. uyan!  güzel  ruh gül  güzel  yüz buselerim  sana en  dokunulmamış en  mahre...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/buselerim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Ben', 'asigim-ben-yusuf-onder-bahceci-539vb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşığım ben gözlerine, kâlbi vuran sözlerine,

Aşığım ben adına, işvesine,edasına, nazına,

Aşığım ben ceylan gibi yürür o salına, salına,

Aşığım ben gözlerine, kâlbi vuran sözlerine.

Aşığım ben gözlerine, acı olsa da sözlerine,

Aşığım ben onu Yaratan''a ve bana tanıtana,

Aşığım ben onun umursamaz davranışlarına,

Aşığım ben gözlerine, kâlbi vuran sözlerine.

Aşığım o ceylan gözlere, seviyorum sözlere,

Aşığım yola gelmeyen ahuya,esrarlı gözlere,

Aşığım çözülmeyen bilmeceye, onu heceye,

Aşığım ben gözlerine, kâlbi vuran sözlerine.

Aşığım gördüğüm anda, vurulmuşum o anda,

Aşığım hâyalimde, düşüncemde her anımda,

Aşığım haber gelse de gelmese de sonunda, 

Aşığım ben gözlerine, kâlbi vuran sözlerine.', 'Aşığım ben gözlerine, kâlbi vuran sözlerine, Aşığım ben adına, işvesine,edasına, nazına, Aşığım ben ceylan gibi yürür o salına, salına, Aşığ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asigim-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*ziyaretine Geldim*', 'ziyaretine-geldim-hulya-koroglu-mqkz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Damla damla biriktirdim seni,

Deniz olup taştın içime...

Köpük köpük seni içtim.

Santim santim boyadım gökyüzünde...

Rüzgarda sesini dinledim,

Tek hece dökülmedi dilinden...

Aşık oldum ardından,

Tekrar ve tekrar, her güneş doğuşunda

...

Ve batışında gömdüm seni mezara.

Ziyaretine geldim geceyarıları.

Belki oniki,

Belki bir gibi...', 'Damla damla biriktirdim seni, Deniz olup taştın içime... Köpük köpük seni içtim. Santim santim boyadım gökyüzünde... Rüzgarda sesini dinledi...', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ziyaretine-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-zeki-altas-tn4ap', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Körolası kalem,

Dağıttı yine döktürüyor.

İçim dışım her ne varsa,

Sayfa sayfa çeviriyor.

Sis kaplamış hayalleri,

Hece hece karalıyor.

Kelepçeli sevdaları,

Gece gündüz kovalıyor…

Umut olup yarınlara,

Uzun uzun baktırıyor.

Çile olup gönüllere,

Sessiz sessiz ağlatıyor…

Ekmek olup ağızlara,

Kıtır kıtır çiğnetiyor.

Kahır olup yarınlara,

Mahsun mahsun baktırıyor…

Şımarık ki sorma gitsin,

Ağır ağır çatlatıyor.

Kağıt  bulmuş onünde,

Çizip çizip yaralıyor.

Kör olası kalem,

Dağıttı yine döktürüyor…

Bir aşık ki kağıda mecbur,

Dere tepe aratıyor.

Benliğimi esir etmiş,

Fıkır fıkır oynatıyor.

Kırıp atsam gönlümden,

Girip cebe saklanıyor.

Tükenmez miş derler ama.

Dirhem dirhem tüketiyor.

Körolası kalem,

Dağıttı yine döktürüyor…', 'Körolası kalem, Dağıttı yine döktürüyor. İçim dışım her ne varsa, Sayfa sayfa çeviriyor. Sis kaplamış hayalleri, Hece hece karalıyor. Kelepç...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sitem-235-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazıları', 'bazilari-yusuf-onder-bahceci-i0b11', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazıları hep şiir yazar, bazıları okur ağlar,

Bazıları cândan sever, bazıları cân yakar,

Bazıları hep yollara çıkar, yollarına bakar,

Bazıları hep şiir yazar, bazıları okur ağlar.

Bazıları benim gibi sever, sevdiğini över,

Bazıları nasıl pişman olur, dizlerini döver,

Bazıları benim gibi ayırana ha bire söver,

Bazıları hep şiir yazar, bazıları okur ağlar.

Bazıları nı gece uyur mu sanar, sanarsın,

Bazıları ise, geceleri hep ağlar, ağlarsın,

Bazıları böyle ömür boyu yanar yanarsın,

Bazıları hep şiir yazar, bazıları okur ağlar.

Bazıları sever, sevdim diyemez de ağlar,

Bazılarını görsen anlarsın kâlbi kan ağlar,

Bazıları duvar diplerinde, dilinde yâr, yâr,

Bazıları hep şiir yazar, bazıları okur ağlar.', 'Bazıları hep şiir yazar, bazıları okur ağlar, Bazıları cândan sever, bazıları cân yakar, Bazıları hep yollara çıkar, yollarına bakar, Bazıla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bazilari-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde Hayallerimde Olsa Bile', 'duslerimde-hayallerimde-olsa-bile-huseyin-erdogan-jsb66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevgiyi sende buldum

aşkı sende tanıdım

sevgi dolu yüreğimle

duygu yüklü bedenimle

bir tek sana bağlandım

bil ki şiirim sevdiğim

ben seninle varım

artık ben ömrümce

hiç solmayacak bir baharım

ölünceye değin

o güzel yüreğinde

kalabilirsem eğer

bu benim için

bütün zenginliklere bedel

sen de beni

mutlu etmek istersen eğer

şairim zaten sen

benim kalbimdesin deyiver

beni delice sevdiğini söyleyiver

gün batımlarında 

gece yarılarında el ele

dolaşmak isterim seninle 

Bostancı''da Üsküdar''da sahilde

karnımız acıkınca da

yemek yeriz bir lokantada

istersen sen

bir duble rakı içersin

ben de razı olurum sevdiğim

bir tek damla bile içmeden

yeter ki

beni sarhoş etsin güzelliğin

şiirim bir kez daha anladım ki

bir başka güzelmiş 

seninle yaşamak bu alemde

düşlerimde hayallerimde olsa bile

                                03.03.2006

                              Hüseyin Erdoğan', 'sevgiyi sende buldum aşkı sende tanıdım sevgi dolu yüreğimle duygu yüklü bedenimle bir tek sana bağlandım bil ki şiirim sevdiğim ben seninle...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/duslerimde-hayallerimde-olsa-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehre Yığılıp Kaldım', 'bu-sehre-yigilip-kaldim-sahin-erturk-55a72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık seni kovalayamam

Hem yaşlandım,hemde yoruldum

Zaten PAS tuttu umutlarım

Bu şehire yığılıp kaldım

VİNÇ le bile kaldıramazsın

Kaldıramaz,kaldıramazsın

(03.03.2006)', 'Artık seni kovalayamam Hem yaşlandım,hemde yoruldum Zaten PAS tuttu umutlarım Bu şehire yığılıp kaldım VİNÇ le bile kaldıramazsın Kaldıramaz...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-sehre-yigilip-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-yusuf-onder-bahceci-ymgk9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seviyorum be, o beni hiç sevmese de,

Seviyorum, seni sevmiyorum be, dese de,

Seviyorum, benden çok, çok uzaklara gitse de,

Seviyorum, çok seviyorum, o istese de istemese de......', 'Seviyorum be, o beni hiç sevmese de, Seviyorum, seni sevmiyorum be, dese de, Seviyorum, benden çok, çok uzaklara gitse de, Seviyorum, çok se...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seviyorum-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Rabb…', 'ya-rabb-orkun-isik-n7ky3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana secdedeyken Ruhum

Bir fanilik çatışmasında,  sokak ortasında

Ayaklar altına alındı, sırtından vuruldu gururum.

Önemsemedim ölümlerimi, kefenim Güller beyazı! 

Kalbimi nefesimle vururum, aç kabristanını ben geldim, 

Sendendir şehitlik, dudaklarımda ki kevser’in mağrurum...', 'Sana secdedeyken Ruhum Bir fanilik çatışmasında,  sokak ortasında Ayaklar altına alındı, sırtından vuruldu gururum. Önemsemedim ölümlerimi, ...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ya-rabb-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç,Beş Günlük Dünya İçin', 'uc-bes-gunluk-dunya-i-cin-sahin-erturk-of6u4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üç,beş günlük dünya için

Bu kalpleri kırmak niye? 

Bu canlara kıymak niye? 

Niye dostum,söyle niye? 

Üç,beş günlük dünya için

Ters yollara sapmak niye? 

Rakı,Şarap içmejk niye? 

Niye dostum,söyle niye? 

Üç,beş günlük dünya için

LAYLA larda gezmek niye? 

Pavyonlarda sızmak niye? 

Niye dostum,söyle niye? 

Üç,beş günlük dünya için

Devletini soymak niye? 

Müslümana sövmek niye? 

Niye dostum,söyle niye? 

Üç,beş günlük dünya için

Böyle doyumsuzluk niye? 

Böyle sorumsuzluk niye? 

Niye dostum,söyle niye? 

(03.03.2006) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Üç,beş günlük dünya için Bu kalpleri kırmak niye?  Bu canlara kıymak niye?  Niye dostum,söyle niye?  Üç,beş günlük dünya için Ters yollara s...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uc-bes-gunluk-dunya-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Kız-"siz hiç ay aşığında ağladınız mı" Kitabından', 'kara-kiz-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-t5ca7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakışların pakize efsunluydu dillerin

Gül bahçemde hazan var çıkıp gittin kara kız 

Yanakların rengârenk morarırdı alların

Aklım aldı gülüşün yıkıp gittin kara kız

Gamzelerin tüllenir ter kokardı ellerin 

Bir buselik sevgiyi ekip gittin kara kız 

Sekişlerin can yakar kıskanırdı güllerin 

Mahmur mahmur bakışıp çekip gittin kara kız 

Ay parçası mor çiçek atlastan eteklerin 

Alev alev sevdamız yakıp gittin kara kız

Visalın yalan mıydı ne oldu cilvelerin

Sevdamızı ateşe döküp gittin kara kız

Huri miydin melek mi mest etti gelgellerin

Yudum yudum içmeden akıp gittin kara kız 

Senin olsun peteğin çiçeklerin balların 

Kovanıma çomağı sokup gittin kara kız

Muammaydı Ömer''e mektupların pulların 

Ciğerimi kökünden söküp gittin kara kız', 'Bakışların pakize efsunluydu dillerin Gül bahçemde hazan var çıkıp gittin kara kız  Yanakların rengârenk morarırdı alların Aklım aldı gülüşü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-kiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Göreceksin', 'bak-goreceksin-yusuf-onder-bahceci-ufoqj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahım kalmayacak, bak göreceksin diyecekler,

Ahım kalmayacak, bak göreceksin ne dilekler,

Ahım kalmayacak, bizi ayıranlar söyleyecekler,

Ahım kalmayacak, bak göreceksin diyecekler.

Ayıranları biliyorum ben ikisi de olur akrabam,

Ayıranları biliyorum ayıranların eli, ayağı aman,

Ayıranlar çok zalim, çevirdikleri filime, devam,

Ahım kalmayacak, bak göreceksin diyecekler.

Göreceksin sen, ikimizden af da dileyecekler,

Göreceksin, biz neler yapmışız be, diyecekler,

Göreceksin, zalimler, çok zor, cân verecekler,

Ahım kalmayacak, bak göreceksin diyecekler.

Öyle kolay mı kurtulmak, kolaymı ahlar almak,

Öyle kolay mı hakkını helal et, demek, gitmek,

Öyle kolay mı bir tek cânı, böyle ikiye bölmek,

Ahım kalmayacak, bak göreceksin diyecekler.', 'Ahım kalmayacak, bak göreceksin diyecekler, Ahım kalmayacak, bak göreceksin ne dilekler, Ahım kalmayacak, bizi ayıranlar söyleyecekler, Ahım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bak-goreceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*son Gece... Adam Gidiyordu*', 'son-gece-adam-gidiyordu-hulya-koroglu-dutem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''''Ağlıyor bu şehir gidişime,''''dedi.

Arabasının içinde çisil çisil yağan yağmuru izlerken.

Son geceydi ikisi içinde.

Son vedaydı.

Adam gidiyordu...

Hep gidişlerle doluydu yaşamı,

Hep ayrılıklarla dolu.

''''Beceremiyorum'''' diyordu mutlu olmayı,

''''Kayıp gidiyor avuçlarımın arasından, tutamıyorum.''''

En çok içki içmeyi severdi.

Bir de babasını.

Acı tebessümler belirirdi yüzünde, hatırladıkça.

İç çekerdi zamansız ölümüne.

Duvardaki resmine gözlerini diker,

Derin derin çekerdi sigarasının dumanını ciğerlerine.

''''Ah ulan Rıza ah! '''' derdi sitemkâr bir sesle.

Bir kere aşık olmuş.

Ulaşılması zor kadınları severmiş.

''''Yormalı beni '''' derdi.

''''Ardından koşmaktan iflahım çıkmalı.''''

Oysa yanındaki kadın, hemen indirivermişti yelkenleri.

Sevgiye açtı, sıcak bir yuvaydı düşleri.

Adam da açtı bunlara 

Ama; 

Elinin tersiyle itmeyi yeğledi.

Kadın: ''''eyvallah'''' dedi.

-Eyvallah koçum. Senden gelen zehir olsa içerim...

Son geceydi ikisi için de..

Son vedaydı...

Adam gidiyordu,

Kalansa kadın...

Çisil çisil yağan yağmur kadın için ağlıyordu...

İlk kez taş atmadılar gölde öten kurbağalara.

Gece ne vicdansızdı.

Esirgemişti yıldızları ikisinden, ayın gözlerini bağlamıştı.

Be vicdansız gece! 

Be insafsız gece! 

Bilmez misin yıldızları ne sever bu kadın, ay''ı ne sever...

Ama en çok adamı sevdi.

Hayırsız da olsa sevdi işte.

Elini adamın göğsüne koyup:

-Ben burdaki yaralı,hüzünlü çocuğu sevdim en çok, dedi.

-Vefasız, umursamaz o deli adamı değil.

Son geceydi bu.

Son veda...

Adam gidiyordu, kalansa kadın...

''''Elveda'''' dedi küçük göle,

''''Elveda'''' dedi gecenin kasvetine bürünmüş şehre...

''''Kadın, sana da elveda,

Bu son görüşüm olacak sizi, hepinize ELVEDA...''''

Adam Gitti...', '''''Ağlıyor bu şehir gidişime,''''dedi. Arabasının içinde çisil çisil yağan yağmuru izlerken. Son geceydi ikisi içinde. Son vedaydı. Adam gidiyo...', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/son-gece-adam-gidiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Var Diyorlar', 'bir-ayrilik-var-diyorlar-zeynal-yaman-ehp15', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neşe eksem gam biter

Hazin hazin bülbül öter

Dünyada ölümden beter

Bir ayrılık var diyorlar

Rüzgâr eser ılık ılık 

Şarkılarda beste yanık

Gurbet elde âlem tanık 

Bir ayrılık var diyorlar

Yaşın yaşın mektup ağlar

Mektup değil anam ağlar

Her hecesi yürek dağlar

Bir ayrılık var diyorlar

Gam yollamış mektup yazan

Uzan dert zincirim uzan

Gurbet elde mezar kazan

Bir ayrılık var diyorlar

Zeynel yolcu gelir geçer

Ecel şerbetini içer

Deste deste ömür biçer 

Bir ayrılık var diyorlar

1987', 'Neşe eksem gam biter Hazin hazin bülbül öter Dünyada ölümden beter Bir ayrılık var diyorlar Rüzgâr eser ılık ılık  Şarkılarda beste yanık Gu...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-ayrilik-var-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirleri Okumadın', 'siirleri-okumadin-yusuf-onder-bahceci-dcppc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yapılan duaları ölüler bile duyar,

Yazılan şiirleri, bir okumadın be,

Kâlbi sağır olmak ne güzel uyar,

Yazılan şiirleri, bir okumadın be.

Korkma seni rahatsız etmem be,

Şiir yazma deme, dinlemem bre,

Gel sen kâlbini ver hele bir dinle,

Yazılan şiirleri, bir okumadın be.

Yazılan şiirleri şöyle bir okusana, 

Bütün mısralar bir gül koku sana,

Ayrılıklar zordur hasret dokusana,

Yazılan şiirleri, bir okumadın be.

Korkma, korkma, elalem, ne der,

Korkma seni rahatsız etmem der,

Korkma Önder buralardan, gider,

Yazılan şiirleri, bir okumadın be.', 'Yapılan duaları ölüler bile duyar, Yazılan şiirleri, bir okumadın be, Kâlbi sağır olmak ne güzel uyar, Yazılan şiirleri, bir okumadın be. Ko...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirleri-okumadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimi Tut', 'ellerimi-tut-yalcin-giray-kaya-2pp0u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz aşkı kelebeklerden ödünç almamıştık ki! 

Kalu-kıyamete yazılan mürekkebin tarihe akan yolculuğunda

bütün SEN ve BEN’lerin güneşe tamah etmeyen gölgeleriydik biz.

Dul kalmış yetimliğe adım çırparcasına hain düşler düşürmekti firardan,

sensiz vakitlerimizin intiharı.

Sessizdik…

Sesi topraktan çalınmış kül hamuru anka kuşlarının

bulutlardaki raksına fırladı gözbebeklerimiz,

resmine bakarken.

Seni unutur gibi olduğumuzda,

çehremizde, güneş kıstırılmışlığı bir itirazın affı susulan rengi gezinirdi,

ihanet çırpınışlarının.

Ve gönlümüz hiçbir zaman sarhoş değildi…

Bakışlarının en gize büründüğü tansız vakitlerde bile,

varlığının ve lütuf oluşunun farkındalığıyla

yüreğimize gel-gitler yaşatmadan sevdik.

Biz ancak SEN’le kendimizdik.

Ve asla, sensiz her yanımız eksikken,

yarım yanlarımızı görmezden gelip kendimizle barışık olmadık, olamadık.

Yüreğimizde,

altında dokunulmazlık şırası akan müstakil sarayının

sana çıkan koridorlarında gönüllü bekçiliğini yaptığımız

sevda anıları vardı sadece.

Anla! demedim sana…

Ya da anlamaya çalış demedim.

ANLAM OL! dedim…

Cabir’in ruhuna küre çevirten, kuantumlara karışmış,

biçare beyaz önlüklerin cevapsız bakışlarla çevirdiği masaya yatırılıp,

metafizik ifşasına dua edilen bir bilinmeyendim ben (sensiz) .

Ben sana

SENİ SEVİYORUM demedim...

Seni, ulu orta hovardaca savrulan, benzer sevdaların keyif gıcırtısı

üçüncü sınıf şiir satırlarına medet olmuş lügat fazlalığı kelimelere

tepeden bakan kasketli ifadeleri aşağılayan bakışlarla sevdim ben.

Önünde durduğumuz, yığılıp kaldığımız ve adımlarımızın bir ilerisi için

bin milyon imkansızın pazarlığını yaptığı o en büyük yokuştaysa

görmezden gelindik SEN’ce.

Hiç kimsenin tuzak ikramlarına kanıp harcanmadık.

Kendi hasretimizin şiddetiyle yontup,

bizsiz olamazlığımızın gücüyle diktiğimiz aşkın surlarından,

senin kaçmalarınla düştük....

....................................................

Sana bu kadar çözülüyorsam,

seni bu kadar çözümsüz sevdiğimdendir..

Ama artık yüreğim düşüyor aşktan..

Ellerimi tut…..! ! ! ! ! !', 'Biz aşkı kelebeklerden ödünç almamıştık ki!  Kalu-kıyamete yazılan mürekkebin tarihe akan yolculuğunda bütün SEN ve BEN’lerin güneşe tamah e...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Giray Kaya']::text[], 8.5, '{"poet":"Yalçın Giray Kaya","poet_slug":"yalcin-giray-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ellerimi-tut-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anıyorum', 'seni-aniyorum-duygu-kerimoglu-p8rqk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum gecenin soluğunda

Denizden gelen isyanın

Taşlara çarpması gibi

Çınlıyor Kulaklarımda sesin



Seni söylüyorum kayan umuda

Gökten gelen yaşa

içimdeki özleme

Ve bir avuç hatıraya



Seni görüyorum uykumun en masum yerinde 

Takılmış vicdanına kelepçeler

Bakma bakma! ! 

Diyor yanağımdan süzülen umutlarıma



Seni okuyorum meçhuliyetlerle

ufacık bie elken sonsuz bir güneş

Parlaklığı meçhuliyet umudu nefes gibi

Yansıması varoluş ve yokoluşun



Seni Uğurluyorum kimsesizler köyüne

Vicdanın olmadığı

Ellerimizin var etmediği uzaklara



Ve tek bir söz kalıyor                                                                                                                                                                                           

Suyun temizlediklerinden sonra

Sessiz Sözlerle 

Sonsuzluğa E_l_V_e_D_a', 'Seni düşünüyorum gecenin soluğunda Denizden gelen isyanın Taşlara çarpması gibi Çınlıyor Kulaklarımda sesin Seni söylüyorum kayan umuda Gökt...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-aniyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evinde ki Cemre', 'evinde-ki-cemre-lokman-hamitoglu-w52ey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EVİNDE Kİ CEMRE

Umutsuzluğa karşı umut olmuş ellerin

Şer’de hayırı görmüş irfan dolu gözlerin

Cahile rehber olmuş iman özlü sözlerin

Nevruzun ilk saati havada ki cemresin...

Doğru limanda durmuş  sırlı hünerler sende 

..... Abime konmuş arlı sevgiler sende 

Namaz, niyaz, şükürle nurlu sezgiler sende

Nevruzun ilk saati ummanda ki cemresin...

Ehl-i sünnet yolunda edeplerin ahlakın 

Ahyarların kolunda  seherlerde felakın

Asla hasrete değil vuslatadır merakın

Nevruzun ilk saati güllerde ki cemresin...

Anne, baba, kardeşe özlemleri sevmeyen

Altından olsa bile uzakları övmeyen

Örfünden adetinden gelenekten geçmeyen

Nevruzun ilk saati evinde ki cemresin...

               Lokman HAMİTOĞLU', 'EVİNDE Kİ CEMRE Umutsuzluğa karşı umut olmuş ellerin Şer’de hayırı görmüş irfan dolu gözlerin Cahile rehber olmuş iman özlü sözlerin Nevruzu...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/evinde-ki-cemre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlık Yaşam', 'bir-anlik-yasam-duygu-kerimoglu-cnzpj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaldırırmlarda bıraktım hayatı

Neşemi kaldırdım dağlara

Hayatı bir bardağa doldurdum

Acı tarafından bir yudum aldım



Ateşe bir parça odun da ben attı

Alev alev yanan gözlerine sevgimi sızdırdım

Bardağı geri dökmek istedim

Ama maviyi ağlatmaya gönlüm el vermedi



Güzel bir türküydü dilime dolanan 

                                                                                                         Bir yudum daha aldım; bardağın gurbet tarafından

Sessiz usulca kalktım gönlümü uzaklardan almaya

Elimi uzattım koskoca boşluğa



Bir rüyaydı sanki eski günler

Hayatı içtim en acı günümde

Tüküyü çektim içime

Yaşamaksa eğer koskoca boşluk…', 'Kaldırırmlarda bıraktım hayatı Neşemi kaldırdım dağlara Hayatı bir bardağa doldurdum Acı tarafından bir yudum aldım Ateşe bir parça odun da ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-anlik-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kucaklasam Seni', 'bir-kucaklasam-seni-hatice-bediroglu-608gs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kucaklasam seni; 

Kızıl renkleriyle güneşin

Resimler çizeceğim

Aşka dair mavilere

Kalelerin burçlarından

Meydan okuyacağım her şeye

Gömülecek kaygılarım

Denizin derinliklerine

Deli bir çılgınlık

Oturacak gözlerime

Oynayacağım döne döne 

Çıplak ayakla

Aldırmadan cümle aleme

Bir kucaklasam seni; 

Kırılacak kabuklarım

Yüreğimin ateşi...

Sefere çıkacak damarlarımda

Saracak bedenimi volkan gibi

Öpeceğim dudaklarından tutkuyla

Bitmeyen bir yolculuğun içinde

Titreyecek içimdeki alevler

Çiçeğe kesecek tomurcuklar

Gürül gürül akmaya başlayacak hayat! 

Yaşanmadan bitecek kış mevsimi

Ve ışık seline dönecek Aşk! 

Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 - 

www.haticebediroglu.net', 'Bir kucaklasam seni;  Kızıl renkleriyle güneşin Resimler çizeceğim Aşka dair mavilere Kalelerin burçlarından Meydan okuyacağım her şeye Gömü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-kucaklasam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MaVi RüYa', 'mavi-ruya-duygu-kerimoglu-gjq3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MAVİ RÜYA 

O an sesini duymak mavi rüyanın; 

İçinden kıvrımların oluştuğunu görmek

Bitmeyeceğini,hayatın sonsuz olduğunu görmek

Onsuz olmayacağını bilmektir deniz



Yaşamın renklerinin yansımasını izlemek gün boyu 

Mavi rüyadan hiç uyanmayacağımızı anlamak

İçimi rahatlatan o su sesiyle

Ömür boyu yaşamak…



Mavi rüyanın sesi kulaklarımda; 

Odalgaların kayalara vuruşu,

O anın bitmesini istemeyişim 

Aynen bir masal havasında…



Hayatım bir şerit gibi geçiyor gözlerimin önünden; 

Balıkların su üstüne zıplayışını izlerken,

O yaşam sevinçleri mavi rüyanın içinde

Keşke benimde bir denizim olsaydı…



Her geçen gün bağlanıyorum o içten gelen sese; 

Denizi görmek istiyorum her geçen günde

Ona sevdam artıyor her kederlendiğim günde 

Mavi rüyanın içinden uyanmak istemiyorum…', 'MAVİ RÜYA  O an sesini duymak mavi rüyanın;  İçinden kıvrımların oluştuğunu görmek Bitmeyeceğini,hayatın sonsuz olduğunu görmek Onsuz olmaya...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mavi-ruya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Artık', 'ben-artik-umit-tuna-r6qmd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'An iş de o an,

Gün aynı gün,

Mevsim aynı mevsim,

Sen aynı sen,

Yıllar önceki sen.

Ben ise yılların yıprattığı,

Aşk acısının yaktığı,

Hasretten kavrulan ben,

Ben artık eski ben değilim ki,

Ben artık seni eskisi gibi sevemem ki.

Ben senden sonra çok aşklar yaşadım,

En zoru senmişsin bunu geç anladım,

Şimdi gelmişsin yanıma,

Hala seni seviyorum diyorsun.

Unuttun mu güzelim,

Yıllar önce giderken,

Elveda bile dememiştin,

Şimdi sıra bende,

Git geldiğin yere! ...', 'An iş de o an, Gün aynı gün, Mevsim aynı mevsim, Sen aynı sen, Yıllar önceki sen. Ben ise yılların yıprattığı, Aşk acısının yaktığı, Hasrett...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Ki', 'bilmem-ki-umit-tuna-yngni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem ki  aşk neden var,

Bilmem ki her aşkın sonunda ayrılık neden var,

Bilmem ki hasret özlem neden var,

Bilmem ki sebepsiz yere ayrılık neden var.

Tek bildiğim sensizde yaşayabildiğim,

Tek bildiğim seni eskisi gibi sevmediğim,

Tek bildiğim artık seni özlemediğim,

Tek bildiğim hasretinle yanmadığım.

Bir şeyi bilmiyorum, senin ne hissettiğini,

Artık bilmekte istemiyorum,

Boşver ben sensizde yaşıyorum,

Hoşça kal güzelim ben gidiyorum! ...', 'Bilmem ki  aşk neden var, Bilmem ki her aşkın sonunda ayrılık neden var, Bilmem ki hasret özlem neden var, Bilmem ki sebepsiz yere ayrılık n...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmem-ki-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gör Yeterki', 'sen-gor-yeterki-tekin-koc-cpvwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adım türkülere fidandır gülüm 

Söyledikçe açılır serpilir dalım 

Seni yangınların yakamadığı 

Seni şarkıların anlatamadığı 

Seni saçları kömür karası 

Dağların dağları yürek yakanı

Yollarında kavuşmayanı

Bu hasrettir gülüm düşmeyen bilmez

Her göz ağlar ama her göz sevemez

Nasıl anlatsam uçan kuşları 

Nasıl anlatsam akan yasları 

Nasıl duysalar karıncaları

İşte öyle zor sözde yalandır 

İşte öyle kor suda yanandır 

Yum kipriklerini sal  nehirleri 

Ağladıkça açar sevda gülleri 

Sen yeterki bil sıcak elleri 

Sen yeterki sürgünden geceyi

Sen yeterki sev tüm çocukları 

İşte tam ordayım aç gözlerini 

İşte tam ordayım sen gör yeterki', 'Adım türkülere fidandır gülüm  Söyledikçe açılır serpilir dalım  Seni yangınların yakamadığı  Seni şarkıların anlatamadığı  Seni saçları köm...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-gor-yeterki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yıldızın Ardından', 'bir-yildizin-ardindan-duygu-kerimoglu-09it9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugun yine bir yıldız kaydı

Bir ışık daha söndü berrak gökyüzünden

Yakıldı ağıtlar kayan bir yıldızın ardından

Mızraplar saplandı yanan yüreklerin içine



Bugun yine bir yıldız kaydı 

 İçinde zavallıların bulunduğu bir hastahane odasında

Kilitlendi dudaklar,ağladı gözler

Yıldız için bir son,kalanlar için bir başlangıç oldu



 Bugun yeşilliklerin olduğu bir bahar günü

Bir yıldız kaydı soğuk kayaların üstünden 

Bir yıldız daha kaydı gökyüzünden  

Bir asker daha gitti gözlerimizin önünden



Bir gün ben de kayıp gideceğim           

Yakılacak ağıtları duyuyorum

Geride bırakacaklarımı düşünüyorum

Ve elveda diyorum 



Ağıtlar yakılıyor        

Cenazeler kalkıyor                           

Bir yıldız kayarken bir yıldız daha doğuyor

Hazin bir geceden sonrasadece gurbet kalıyor...', 'Bugun yine bir yıldız kaydı Bir ışık daha söndü berrak gökyüzünden Yakıldı ağıtlar kayan bir yıldızın ardından Mızraplar saplandı yanan yüre...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-yildizin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HaYkIrIş', 'haykiris-duygu-kerimoglu-3f430', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çığlık duydum gün kararırken

Hasretin,tutkunun çığlığını duydum

Güneşin batmasıyla yükselen bir kartalın isyanını

İçten ama gereksiz bağrışmalarını



Hissettim gözlerimin kapanışıyla; 

Yüreğimin atışını ve içten haykırışını

Kabullendim yalnızlığı

Sönmüş ışıkları



Bir yağmur tanesi çekti dikkatimi; 

Pencerenin camından süzülürken...

Yalnız ve mutsuzca süzülen bir yağmur tanesi

Yerinde kalmak istediğini haykırıyordu gözlerime

Ama o da gitti...', 'Bir çığlık duydum gün kararırken Hasretin,tutkunun çığlığını duydum Güneşin batmasıyla yükselen bir kartalın isyanını İçten ama gereksiz bağ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haykiris-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konarım Çocukların Yanacığına', 'konarim-cocuklarin-yanacigina-ahmet-yozgat-c0air', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Keloğlan biner anka kuşuna,

Uçar ha babam uçar...

Az uçar, azar azar uçar

Uz uçar, uçar uzayarak.

Sulak derelerden kıvrılarak, 

Karlı tepelerden düz uçar.

Masal olur baklava lokması gibi,

Çocukların dudacığına konar.

2/:

Hoca biner Karakaçanına,

Kaçar ha babam kaçar...

Az kaçar, azar azar kaçar 

Uz kaçar, kaçar uzayarak.

Derin derelere dalıp çıkarak, 

Tepelerden inip binerek kaçar.

Fıkra olur bir lokma lokum gibi,

Çocukların yanacığına konar.

3/:

Ben de binerim bir şiir atına,

Heybeme sihirli sözler doldururum

Saçarım ha babam saçarım...

Çok saçarım, çoğalarak saçarım 

Uz saçarım, saçarım uzayarak.

Kuytu dizelere dalıp çıkarak, 

Beyitlerde inip binerek saçarım.

Dörtlük olurum bir lokma helva gibi,

Çocukların yanacığına öpücük kondururum

Dağarcığıma öpücüklü şiirler doldururum.', '1/: Keloğlan biner anka kuşuna, Uçar ha babam uçar... Az uçar, azar azar uçar Uz uçar, uçar uzayarak. Sulak derelerden kıvrılarak,  Karlı te...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/konarim-cocuklarin-yanacigina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ShAiRdiM', 'shairdim-duygu-kerimoglu-bkvms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güllerin gülüşünü anlatan şairdim bir zamanlar

Leylak kokularıyla dolmuş sokakların yalnızıydım

Gecenin yıldızlarına bakan

Kalbini umtularla sarmış şairdim...



Şairdim bir zamanlar akarsularla konuşan

Kumruların aşkını anlatan

Gizemlerle yaşayan

Güneşle kavrulan zavllı bir şairdir...



Ölümün zorluğunu bilen ama yaşama her zaman isyan eden şairdim

Dili olmayan mısralara, ölümün yalnızlığını anlatan şairdim

Hayatın zorluğunu gören ve bile bile çeken 

Yalnız ve uykusuz bir şairdim..



Masalları sevmeyen; Hayatı masal tadında gören 

Her son geldiğinde üzülen şaşkın bir şairdim

Halbuki nasıl bir çelişkdiri bu

Her son yeni bir başlangıçtır diyen bir şairdim ben



Şiirleri geride bıraktım artık

Hayata küstüm ama nedenini bilmeden

Gecenin karanlığına gömüldüm

SEssiz usulca geçtim korkutanların önünde



Bİr şairdim unutulan

Bir şairdim zavallı şaşkın

Bir filmin başlangıcında olan ama sonunu bulamayan

Korkusuzca ölüme koşan eski bir ShAiRDiM', 'Güllerin gülüşünü anlatan şairdim bir zamanlar Leylak kokularıyla dolmuş sokakların yalnızıydım Gecenin yıldızlarına bakan Kalbini umtularla...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/shairdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaf Çölüne Hoş geldiniz', 'kaf-colune-hos-geldiniz-ahmet-yozgat-dguml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Gün olur bunalırsa başınız

Mızıkçılık yapmışsa oyundaşınız

Arkadaşınız yoksa körebe için

Haydi geçin benden yana...

Ben mi kimim? 

Kaf-ı küf çölüdür adım,

Adım adım ulaşmak isterseniz

Afacan Keloğlanların dünyasına

Yani bir masal dinlemek isterseniz,

Hayaller diyarına hoş gelmişsiniz.

2/:

Ucum yok, bucağım yok.

Aylar sürer bağrımda yolculuğum.

Ufuklarım kaybolur gider,

Sisli Kaf dağlarının arasında.

Yüzeyim kendime has,

Sayın ki kumdan bir deniz.

Eğer bir hayal isterseniz,

Kaf-ı küf çölüdür adım,

Masallar diyarına hoş gelmişsiniz.

3/:

Kervanlar çangıl çungul.

Eğri boyunlu develer,

Giderler şimal yönüne,

Gelirler cenup cihetinden,

Bir o yana tuz taşır,

Su taşırlar bir bu yana,

Sakin, uysal ve sessiz.

Eğer bir hayal isterseniz,

Kaf-ı küf çölüdür adım,

Rüyalar diyarına hoş gelmişsiniz.

4/:

Size binlerce mil uzak olan

Güneş daha yakın bana.

Sapsarı ve yakıcı bir sıcak gündüzüm,

Geceleyin ay ışığında bile,

Işılar gümüşi bir yansımayla elim,

Yanar harlı tandırlar gibi yüzüm.

Ne şıpır şıpır yağmuru tanırım,

Kar ise bana çok uzak bir kavram.

Bir damla kirli ve bulanık su bile,

Bin bir altın eder çorak bağrımda.

Duruşum yüzlerce yıl,

Kuraktır tosbağa sırtı gibi,

Ağustosta kavrulan el gibi çatlak,

Kimsesiz, ayazlı gecelerde sokaklar gibi.

Eğer kara kışta üşür de sıcaklık isterseniz,

Kaf-ı küf çölüdür adresim,

Ilıman masallar diyarına hoş gelmişsiniz.', '1/: Gün olur bunalırsa başınız Mızıkçılık yapmışsa oyundaşınız Arkadaşınız yoksa körebe için Haydi geçin benden yana... Ben mi kimim?  Kaf-ı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kaf-colune-hos-geldiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Yetiş Elden Gidiyor Yavrun', 'anne-yetis-elden-gidiyor-yavrun-ahmet-yozgat-cwd4n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Şu iki yaramaz var ya: 

Birinin adı Mükremin,

Ötekininki Satılmış.

Dolanır dururlar ortalıkta,

Ellerinde kalın kalın sopalarla.

Ne mevsimlerden yaz derler,

Ne de ayazlı kışı dinlerler.

Mavi gözleri çakmak çakmak

Ağızlarının kenarı hep salyalı.

Eğer yok ise değnekleri 

Yine de boş durmaz yaramaz elleri

Ya topak ve kara taşlı 

Ya da kenarı keskin kayalı.

Mahalledeki insanları bezdirdiler

Bıktırdılar zavallı hayvanları

Bu iki haylazın kötü huyu

Sayın ki dızmanlara eş.

Anne Çomar tez yetiş,

Elden gidiyor yavru.

Yapma Mükremin dur! 

Yavru köpeği kudurttun.

Dilerim sen de kudur! 

2/:

Şu iki yaramaz var ya: 

Birinin adı Mükremin,

Ötekininki Satılmış.

Dar sokaklar onların sayılır.

Çoktan teslim olmuş ellerine,

Geniş meydanlar, kalabalık caddeler.

Sabah olup da aniden çıkınca,

Bu haylaz çocuklar ortaya,

Acele kaybolurlar bütün kediler.

Ne çınar ağaçlarında yuva kalır

Ne de saçaklarda serçe yumurtası.

Cami avlusundaki güvercinler

Korkarım soylarını tüketecekler.

Etmez zavallılara bunların ettiğini

Dağlardaki azgın kurt

Derelerdeki yabani çakal.

Sonunda teslim oldu zulümlerine çayırlar,

Yeşil bahçeler ve pancar moru bayırlar.

Çeldiler şırlayan dereler bile suyu.

Mahalledeki insanlar bezdiler

Bıktılar zavallı hayvanlar

Bu iki haylazın kötü huyu

Sayın ki şeytanlara eş. 

Anne mırnav tez yetiş,

Elden gidiyor yavru.

Yapma Satılmış dur! 

Yavru kediyi kudurttun.

Dilerim sen de kudur!', '1/: Şu iki yaramaz var ya:  Birinin adı Mükremin, Ötekininki Satılmış. Dolanır dururlar ortalıkta, Ellerinde kalın kalın sopalarla. Ne mevsi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/anne-yetis-elden-gidiyor-yavrun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çinçilya Abla', 'cincilya-abla-ahmet-yozgat-6ahkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/: 

Aldı küçük kardeş:

''Çinçilya abla,

Kış ayları geliyor ya,

Kürk istiyor annem senden,

Ayazda bacakları üşüyor da...''

1a/: 

Aldı çinçilya abla:

''Çinçilya ablayım,

Kürk veririm hediye,

Üşüyen anneler giysin, diye.

Eğer kürk isteyen anneler,

Biraz yiyecek vermişlerse bana,

Kürküm helâl onlara...''

1b/: 

Aldı çinçilya abla:

''Senin üşüyen annen, küçük

Karlı kış aylarında,

Karnım acıktığında yemek,

Susadığımda bir damla su,

Vermemişti doğrusu...''

2/: 

Aldı küçük kardeş:

''Çinçilya abla,

Havalar serinliyor ya,

Kürk istiyor ninem senden,

Romatizmaları var da...''

2a/: 

Aldı çinçilya abla:

''Çinçilya ablayım,

İşim gece gündüz kürk üretmek,

Romatizmalı nineler giysin, diye.

Eğer kürk isteyen hasta nineler,

Beni dar günümde bir sefer,

Düşünmemişlerse eğer,

Niye benden kürk isterler? ''

2b/: 

Aldı çinçilya abla:

''Senin bacakları romatizmalı ninen,

Dondurucu kış aylarında,

Karnım pek acıktığında yemek,

Susadığımda bir tas serin su,

Vermemişti doğrusu...

Herkes verdiği kadar

Alır karşılık.

Haydi başka kapıya

Burada biter arkadaşlık...''', '1/:  Aldı küçük kardeş: ''Çinçilya abla, Kış ayları geliyor ya, Kürk istiyor annem senden, Ayazda bacakları üşüyor da...'' 1a/:  Aldı çinçilya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cincilya-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Boyalı Bisikletim', 'bir-boyali-bisikletim-ahmet-yozgat-ptj92', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Sever beni binicim:

''Sevgilim canım'' diye.

Komam onu yollarda,

İleriye! 

Hep ileriye...

2/:

Bir boyalı bisikletim.

Frenlerim taş gibi.

Kaptım mı binicimi,

Uçururum kuş gibi...

3/:

Döner tekerleğim döner,

Her şey kayar geriye.

Kalmam asla yollarda,

İleriye! 

Daima ileriye...

2/:

Aslan gibi bisikletim.

Frenlerim yay gibi.

Kaptım mı binicimi,

Uçururum tay gibi...', '1/: Sever beni binicim: ''Sevgilim canım'' diye. Komam onu yollarda, İleriye!  Hep ileriye... 2/: Bir boyalı bisikletim. Frenlerim taş gibi. K...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-boyali-bisikletim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühür', 'muhur-bekir-gedikoglu-jp9ec', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuruyan damarlarım şimdi özlemle doldu

Kapkaranlık dünyama sanki bir güneş doğdu

Ruhumdaki kelebek artık uyumuyordu

Gönlüm aradığını en sonunda bulmuştu

İlk baştan söylediğim unutma o sözümü

Düşündün mü kalbime vururken aşk mührünü

Bu yola girenlerin hoş geçermiş ömürü

Kader ağını bize sessiz,  sessiz örmüştü...

Ankara 24 Şubat 2006', 'Kuruyan damarlarım şimdi özlemle doldu Kapkaranlık dünyama sanki bir güneş doğdu Ruhumdaki kelebek artık uyumuyordu Gönlüm aradığını en sonu...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/muhur-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Yollar Masallara Çıkar', 'tum-yollar-masallara-cikar-ahmet-yozgat-bhdod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ne zaman giysem,

Ayağıma sihirli pabucumu

Tılsımlı asamı alsam elime 

Düşerim önümde kıvrılan yollara,

Yollar ulaşır masallara.

2/:

Ben giderim üşenmeden,

Hiç düşünmeden onlar da gider.

Ardımda güneşle uzayıp kısalır gölgem,

Önümde kovaladıkça kaçan hayallerim,

Çın çın eder, tin tin eder...

Düşerim heyecan ile önümdeki yollara,

Yollar ulaşır masallara.

3/:

Ne zaman doğrulsam yerimden.

Puslu ve rüya gibi bir akşamüstü.

Sağ elimi gözlerime siper etsem,

Süzsem dağların üzerine gerilen ufukları,

Bulutların mor renkli saçlarını tarasam.

Sihirli pabuç ayağımda 

Elimde tılsımlı asam 

İlişir gözüm görkemli dev saraylarına,

Düşerim heyecan ile önümdeki yollara,

Tüm yollar ulaşır Kaf dağlarına.', '1/: Ne zaman giysem, Ayağıma sihirli pabucumu Tılsımlı asamı alsam elime  Düşerim önümde kıvrılan yollara, Yollar ulaşır masallara. 2/: Ben ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tum-yollar-masallara-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakarsın', 'bir-bakarsin-yusuf-onder-bahceci-utkx4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bakarsın, yüce dağların başındayım, sevda telaşındayım,

Bir bakarsın, gemileri karadan yürüten, Fatih''in yaşındayım,

Bir bakarsın, Preveze Deniz Harbi düşman gemisi batırırım,

Bir bakarsın, yüce dağların başındayım, sevda telaşındayım.

Bir bakarsın, güzel seven, sevdiğini, böyle şiirle öven, öven,

Bir bakarsın, sevdiğini bir kenara koyup da Vatanı için ölen,

Bir bakarsın, deli taylar gibi düşman cephesinde alay eden,

Bir bakarsın, yüce dağların başındayım, sevda telaşındayım.

Bir bakarsın varım, bir bakarsın yokum, ben Allah için okum,

Ölsem bile alırım ben, inşallah şehit olursam mis gibi kokun,

Korkma şöyle bir dokun dokun hele neler duyacaksın dokun,

Bir bakarsın, yüce dağların başındayım, sevda telaşındayım.

Bütün varım yok olsun,sevdaların uğrunda, şehitlik sonunda,

Ben Allah''ın doğru yolunda inşaallah şehitlik vardır sonunda,

Buradan sesleniyorum, Vatan Sevgisi İmandandır, yolunda,

Bir bakarsın, yüce dağların başındayım, sevda telaşındayım.', 'Bir bakarsın, yüce dağların başındayım, sevda telaşındayım, Bir bakarsın, gemileri karadan yürüten, Fatih''in yaşındayım, Bir bakarsın, Preve...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-bakarsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amin Alayı Şiiri', 'amin-alayi-siiri-ahmet-yozgat-bgf90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ufacıktım daha dün,

Bütün dünyam evimiz,

Annem, babam bahtiyar

Bütün ailem mutlu.

Ben ailemden emin

Ailem benden emin,

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oluyorum bu yıl...

2/:

Yaslanıp pencereye,

Dışarıyı gözlerdim.

Gördüğüm ilk çatılar,

Mahalle mektebinin.

Mektep benden emin,

Ben de oradan emin.

Amin! Amin! 

3/:

Cezbeder gördüklerim,

Okulun bahçesinde.

Her köşede bir ağaç,

Bir çeşme her bölümde

Ağaç altı saklambaç

Ebe, sobe önümde...

Ben hoppacıktan emin

Gök boncuk benden emin.

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oluyorum bu yıl...

4/:

Sonunda geldi, çattı,

Mektepli olma günüm.

Kapattı yaramazlığım

Defterini geçmişin. 

Hocalar benden emin.

Ben de onlardan emin.

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oluyorum bu yıl...

5/:

Dizildi ''amin alayı''

Kuyruk gibi arkama. 

Ağızda dualarla,

Yürüdüm yarınlara.

Dualar benden emin.

Ben de onlardan emin.

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oluyorum bu yıl...

6/:

Lezzetli yiyecekler,

Hocalara armağan.

Erişirmiş bu güne

Annesinden her doğan

Annemler benden emin.

Ben de onlardan emin.

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oluyorum bu yıl...

7/:

Bu ilk günün ilk dersi,

Yazıverdim yaprağa:

Birinci A ile ilk Be''yi,

Ne de kolay belledim

Elifba''de her şeyi.

Artık hayatım benden emin.

Ben hayatımdan emin.

Ağızlarda bir dua mırıl mırıl:

Amin! Amin! ...

Öğrenci oldum bu yıl...', '1/: Ufacıktım daha dün, Bütün dünyam evimiz, Annem, babam bahtiyar Bütün ailem mutlu. Ben ailemden emin Ailem benden emin, Ağızlarda bir dua...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/amin-alayi-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak Dünyası Haritası', 'oyuncak-dunyasi-haritasi-ahmet-yozgat-xfsjw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Benzemeyiz biz gerçeğe,

Ne de uyuşan yanımız vardır

Yeryüzünde yaşayan her şeyle

Burası oyuncaklar dünyası.

Adresimiz uzay değil,

Çocukların odası.

1a/:

Bin bir geceler gibi renkliyiz; 

Sarı, yeşil ve mavi.

Doldururuz her evi,

Benekliyiz benekli

Uç uç böceği gibi...

2/:

Bu asker, kurşun asker,

Yanındaki yakan top.

Kavrar minicik eller,

Oynaşırız: Hop hop hop! 

2a/:

Bin bir geceler gibi renkliyiz; 

Mor, turuncu, kırmızı.

Rüyalar dünyasıyız,

Hayallerin yıldızı,

Kenetliyiz kenetli.

Karınca ordusu gibi...

3/:

Şu kaçan zemberekli fare,

Kovalayan onu kedi.

Oyuncak kamyonların,

Kasa kasa taşıdığı sevgiler 

Bomboş çocuk gönüllerini

Çiçekli halılar gibi döşedi.

3a/:

Bin bir geceler gibi renkliyiz; 

Boyarız beyaz tablolarını 

Gündüz düş gören çocukların.

Gökkuşağından ipliyiz,

Çelenkliyiz çelenkli.

Anne arılar gibi...', '1/: Benzemeyiz biz gerçeğe, Ne de uyuşan yanımız vardır Yeryüzünde yaşayan her şeyle Burası oyuncaklar dünyası. Adresimiz uzay değil, Çocukl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/oyuncak-dunyasi-haritasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanağımdan Süzüzlen Son Damla', 'yanagimdan-suzuzlen-son-damla-duygu-kerimoglu-thmzi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum geceleri

Sessizlikten korkarak

Sessizce ağlıyorum

Yıkanıyor yüzüm gözyaşlarımla

Bir fırtınaya dönüyor içim 

Yaşıyorum kaygılarla süreklim

Git desen; gidecek bu yüreği

Sön desem; dinlemeyip isyan edecek

Yan desem; kararsızca bakıp beni süzecek

                                 Olmuyor deyip bitecek

Gözyaşım akıyor içime 

Kanım kuruyor

Ve sessizce ölüyorum



Kendi kendime sessizce ağlıyorum 

Okyanusa dönüyor yüreğim 

Bakıyorum, bakınıyorum...

Ve   E-L-V-E-D-A  diyorum...', 'Ağlıyorum geceleri Sessizlikten korkarak Sessizce ağlıyorum Yıkanıyor yüzüm gözyaşlarımla Bir fırtınaya dönüyor içim  Yaşıyorum kaygılarla s...', ARRAY['Türk Edebiyatı','Şiir','Duygu Kerimoğlu']::text[], 8.5, '{"poet":"Duygu Kerimoğlu","poet_slug":"duygu-kerimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanagimdan-suzuzlen-son-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevrenizdeyiz Çin Çin Çin!', 'cevrenizdeyiz-cin-cin-cin-ahmet-yozgat-a8vlw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Üstümüz lâcivert gök,

Altımız kara toprak.

Yaprak yaprak beslenir

Çimen çimen otlanırız

Aranızda bizler de varız.

Biz evcil hayvanlarız.

Sesimiz yankılanır, 

Çevrenizde: ''Çin çin çin! ''

Biz sadık dostlarınız,

Her şeyimiz sizin için.

2/:

Canınıza can katarız,

Kucaklarız sizleri.

Giyinin deri elbiseleri

Yünümüz sizin için.

Tüyümüz süstür üstünüzde

İsteseniz de istemeseniz de

Biz sizin dostlarınızız.

Sesimiz yankılanır: 

Çevrenizde: ''Çin çin çin! ''

Biz sadık hayvanlarız,

Her şeyimiz sizin için.

3/:

Koru bizi ağabey

Kıymayın ablalar bize.

Yumurtamız sizin için

Balımız güç bünyenize

İsteseniz de istemeseniz de 

Tüm çabamız sizin için.

Sesimiz yankılanır: 

Çevrenizde: ''Çin çin çin! ''

Biz sadık dostlarınızız,

Her şeyimiz sizin için.', '1/: Üstümüz lâcivert gök, Altımız kara toprak. Yaprak yaprak beslenir Çimen çimen otlanırız Aranızda bizler de varız. Biz evcil hayvanlarız....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cevrenizdeyiz-cin-cin-cin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Saka Kuşu', 'kucuk-bir-saka-kusu-ahmet-yozgat-u7hjo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir küçük sakayım

Öterim: Çıkır çıkır! 

Daldan dala konarım,

Oynarım: Çıtır çıtır! 

Kaynaktan kaynağa atlarım

Kanatlarım yorulmaz hiç.

Benim işim gözeleri arşınlamak 

taşımak tatlı ve serin suları.

Sularım hiç karşılıksız, 

Çölde susuz kalan herkesi

Ama kendim yanarım.

2/:

Ben bir küçük sakayım.

Kaynarım: Fıkır fıkır! 

Komik şeyleri severim

Gülerim: Kikir kikir! 

Gıdıklanırım yağmur damlalarından

Dağların en serin kaynaklarından

Benim işim serin sular taşımak

Gün boyu arşınlamak gözeleri.

Sularım hiç karşılıksız, 

Çölde sütsüz kalan bebeleri,

Ama kendim yanarım.

3/:

Ben bir küçük sakayım.

Zıplarım: Tıkır tıkır! 

Daldan dala konarım

Damlarım: Şıpır şıpır! 

Saklambaç oynarım dere boylarında

Dağ koyaklarında ''eşik kuyu'' oynarım.

Benim işim su taşımak

Gün boyu göz atmak vahalara.

Sularım hiç karşılıksız, 

Çölde mahsur kalan tüm canlıları

Su taşırım ama laf taşımam asla.

İnsanları ve hayvanları severim.', '1/: Ben bir küçük sakayım Öterim: Çıkır çıkır!  Daldan dala konarım, Oynarım: Çıtır çıtır!  Kaynaktan kaynağa atlarım Kanatlarım yorulmaz hi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kucuk-bir-saka-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk Afişler Süsler Odamı', 'rengarenk-afisler-susler-odami-ahmet-yozgat-c7oeu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Süsler odamın duvarlarını,

Renk cümbüşü afişler: 

Kimileri pek kızgın,

Kimisi güleç yüzlüler,

Kimisi kargacık burgacık yazılı,

Geveze sözlü kimisi 

Kimisinde derin bir yürek kazılı...

2/:

Süsler şehrin duvarlarını,

Mesaj yüklü afişler: 

Kimisi kırmızı,

Kimisinin rengi buğday gibi sarı,

Kimisi taş gibi ağırbaşlı,

Kimisi de kelebekler gibi uçarı.', '1/: Süsler odamın duvarlarını, Renk cümbüşü afişler:  Kimileri pek kızgın, Kimisi güleç yüzlüler, Kimisi kargacık burgacık yazılı, Geveze sö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rengarenk-afisler-susler-odami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluktan Kim Korkar?', 'korkuluktan-kim-korkar-ahmet-yozgat-yp00l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

''Gak guk! '' eden kargalar

Korkuluktan kim korkar? 

İşte gepgeniş tarlalar

Bakın size el ediyor karşıdan: 

''Gelin kara yağmacılar,

Gelin çapulcu kargalar! ''

2/:

Tarlaların efendisi Sabri amca

Çıkartıp ceviz sandıktan

Eski püskü ne varsa.

Bahçedeki söğüt dalından 

Sivriltip üç beş kazık 

Uçları çivi gibi,

Yontup keskin keseriyle: 

Tak tuk! Taka tık! 

Diyor ki kendi kendine:

''Yaktım artık, 

Sizi çapulcu kargalar,

Kurtulacak elinizden tarlalar! ''

3/:

''Gak guk! '' eden kargalar,

Korkuluktan kim korkar? 

İşte altın renkli başaklar,

Çağırıyor karşıdan sizleri:

''Gelin siyah yağmacılar,

Gelin çapulcu kargalar! ''

4/:

Sabri amca çiftçilerin ustası.

Bütün kuşları tanır çevredeki.

Yontar yaz boyu sipsivri kazıkları

Korkulukları diker orta yere:

''Yaktım sizi kara çapulcular! 

Kurtulacak artık sizden tarlalar! '' deyişi

İnanın ki merhametsizliğinden değil,

Tek varı yoğu elindeki

Başaklarını korumaktır amacı.', '1/: ''Gak guk! '' eden kargalar Korkuluktan kim korkar?  İşte gepgeniş tarlalar Bakın size el ediyor karşıdan:  ''Gelin kara yağmacılar, Gelin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/korkuluktan-kim-korkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daldım Aritmetiğe', 'daldim-aritmetige-ahmet-yozgat-02gv4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ben birim; 

Bütün çocukları severim,

İşim başlar masallarla benim,

Bir varmış, bir yokmuşum

Bir vakitler bir ülkede

Ülkenin başşehrinde

Anlı şanlı bir sultanım.

Ben birim; 

İşte bundandır kibirim.

2/:

İki derler adıma.

İkiziyim küçük kardeşlerinizin.

Çocuklar dayanır kapıma,

Derim ki onlara: 

''Haydi içeri girin! 

Aritmetiğe hoş geldiniz.''

3/:

Bu alemde üç diye bilinirim.

Üç kardeşin sonuncusuyum.

İki ile dördün kapı komşusuyum.

Savulun dört kardeşim geliyor 

Ben onun öncüsüyüm.

4/:

Ben dördüm; 

Bakmayın genç durduğuma,

Ömrümde pek çok şey gördüm.

5/:

Buralarda beş derler bana,

Haydi beş taş oynamaya...

6/:

Altıdır adım

Altı adımda çıkarım aya

Altı zıplamada ulaşırım yıldızlara.

Ne zaman dönsem dünyaya

Kapıda karşılar beni yedi

Kulak verelim ona

Bakalım yedi ne dedi? 

7/:

Yedi dedi ki:

''Kedi eti 7.''

''Ne dedi, ne dedi? ...''

''Ben de anlamadım ki...''

8/:

Sekizim sekiz

Neler ettiler bana yedi ile dokuz

Ah kardeşler bir bilseniz

Baksanıza halime

Ne bet kaldı ne beniz.

9/:

Bana da dokuz derler

Dokuz kardeşin sonuncusuyum.

Onun kapı komşusuyum.

0/:

Bendeniz de sıfırım 

Adım üstümde, 

Gördüğünüz gibi yokum.

Tuvalete gittim ikiz kardeşimle', '1/: Ben birim;  Bütün çocukları severim, İşim başlar masallarla benim, Bir varmış, bir yokmuşum Bir vakitler bir ülkede Ülkenin başşehrinde ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/daldim-aritmetige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni de Isıt Soba', 'beni-de-isit-soba-ahmet-yozgat-bt3kw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Tırmandım kaygan yüzlerine,

Ortalıkta ıslık çalan rüzgârların.

Buz gibi kapılarına dayandım

Ak sakallı karların.

Dondu nazik bedenim.

Sonunda, ''Merhaba,'' dedi ayaz 

Yani geldi kış baba.

Beni de ısıt soba! 

2/:

Simetrik kar taneleri

Binip uçan kıratlarına,

Soluk soluğa geldiler uzak ülkelerden,

Oturdular evlerin çatılarına. 

Çocukların yazdan kalma elleri,

Giyindiler yünden eldivenlerini.

Sonunda ''Tık tık! '' çalındı kapı

Yani geldi kış baba.

Beni de ısıt soba! 

3/:

Köşe başlarını tuttu kardan adamlar,

Çalıp babamızın eski atkısını,

Ve yamalı şapkasını Veli amcanın.

Çağırıp küçükleri yanlarına,

Dondurdular onların minik burunlarını.

Sonunda, ''Vuv! '' diye esti fırtına,

Yani geldi kış baba,

Beni de ısıt soba.

4/:

Bitti sarışın saçlı sonbahar.

Kınalı leylekler göçüp gittiler

Birer birer ılıman diyarlara.

Takvimlerden koptu aralık,

Burunları havuç gibi kızartan ocak,

Kısa boylu şubat ayını buldu.

Göründü karakışın dibi.

Elerimiz tutkal oldu yapıştı,

Kar topuna buz gibi.

Yine dondurdu herkesi kış baba

Beni de ısıt soba!', '1/: Tırmandım kaygan yüzlerine, Ortalıkta ıslık çalan rüzgârların. Buz gibi kapılarına dayandım Ak sakallı karların. Dondu nazik bedenim. So...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/beni-de-isit-soba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aile Televizyon Karşısında', 'aile-televizyon-karsisinda-ahmet-yozgat-stzss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Otururuz hemen her akşam 

Televizyonun karşısına ailecek.

Babam öyle bir dalar ki ekrana,

İlgilendirmez onu sağ sol.

İlle futbol 

İlle de futbol! 

2/:

Otururuz hemen her sabah,

Birlikte beyaz camın karşısına.

Annem sinirle susturur bizi,

Varsa yoksa pembe dizi,

İlle de pembe dizi...

3/:

Eğer bu gün okul tatilse,

Ödevlerim de bitmişse,

Yani boştaysa elim,

Benim için varsa yoksa,

İlle film, ille de çizgi film! 

4/:

Haftanın hemen her gününde,

Kumanda ablamın elinde,

Gezin ha babam gezin.

Onun için varsa yoksa,

İlle magazin 

İlle de magazin!', '1/: Otururuz hemen her akşam  Televizyonun karşısına ailecek. Babam öyle bir dalar ki ekrana, İlgilendirmez onu sağ sol. İlle futbol  İlle d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aile-televizyon-karsisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Kuyruklu Çomar', 'koca-kuyruklu-comar-ahmet-yozgat-2x8zr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Köpeğim koca kuyruk,

Sıkıntın var bilirim,

Çünkü bakarsın buruk buruk...

Çocuklar mı taşladı kulübeni? 

Yoksa haylaz kediler mi? 

Boşalttı çanağındaki yiyeceklerini. 

Tırnağını taşa mı taktın? 

Yoksa yan mı baktın zalim Çomar''a? 

Hadi söyle ağabeyine,

Kim çekti kuyruğunu? 

Neden susarsın da yorarsan beni? 

2/:

Köpeğim koca kuyruk,

Canın sıkkın bilirim,

Zira havlarsın buruk buruk...

Eğilmiş kulübenin çatısı,

Kiremitler savrulmuş neden? 

Çevresine bahçenin kemiklerin atılmış

Sana ait her şey birbirine katılmış.

Haydi söyle ağabeyine,

Kim yırttı naylon kaplı pencereni? 

Neden söylemezsin de yorarsın beni? 

3/:

Köpeğim koca kuyruk,

Hüzünlüsün bu sabah, görürüm,

Baksana, havlarsın buruk buruk

Zincirini mi çekti sokağın haylazları? 

Yazık sana! 

O yaramazları korkutamadın mı? 

Neden düşük kulakların? 

Ayakların niye kıvrık altına? 

Hadi söyle ağabeyine,

Kim kaptı kemiğini? 

Söyle lütfen, yorma beni.', '1/: Köpeğim koca kuyruk, Sıkıntın var bilirim, Çünkü bakarsın buruk buruk... Çocuklar mı taşladı kulübeni?  Yoksa haylaz kediler mi?  Boşalt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/koca-kuyruklu-comar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Problemler Arasında Kaldım', 'problemler-arasinda-kaldim-ahmet-yozgat-bdaj6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Bir minik koşup bakkala,

Adı Ayşe, Ali veya Fatma.

Alıyor kahvaltı için,

Beşi beş kuruşa,

Beş adet yumurta.

Öğretmenim tamam da,

Bana ne bundan? 

Söyle Allah aşkına! 

2/:

İki kamyon çıkıyor 

Karşılıklı iki noktadan yola,

Rengi sarı, mavi veya çalıyor mora.

Birinin sürati vuruyor doksana,

Diğer şoför daha hızlı,

İnadına basıyor gaza...

Öğretmenim tamam da,

Bana ne bundan? 

Söyle Allah aşkına!', '1/: Bir minik koşup bakkala, Adı Ayşe, Ali veya Fatma. Alıyor kahvaltı için, Beşi beş kuruşa, Beş adet yumurta. Öğretmenim tamam da, Bana ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/problemler-arasinda-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünü YARIN Yarını BUGÜN', 'dunu-yarin-yarini-bugun-gul-yazganarikan-urxpm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yok canım,

yok gülüm yok 

Koşanı yakalamaya çalışır gibi halin

Yürümeyi bile daha öğrenmedin

Emekleyerek ne kadar gideceksin...

Yok canım 

yok gülüm yok

Yanlış zamanlarda yanlış arayışlarda yüreciğin

Fırtınaya şemsiye açmaktasın

Elinde bir çıngırak ağlamaktasın....

Kışın ortasında papatya arıyorsun kırlarda,

Yaz gelince kaymak istiyorsun karlarda

Gerçek aşkı istiyorsun yalan olmuş dünyada

Yok canım 

yok gülüm yok...

oyalıyorsun kendini yalanlarınla,

Zaman duruyor mu istediğin zaman

Akan su vazgeçiyor mu çağlamaktan

Yağmur sen istiyorsun diye mi yağıyor 

Nedir istediğin dik kafalı hayattan

O seni dinlemez gülüm dinlemez 

Sen ne dersen de, her seven sevilmez...

Gel vazgeç bu sevdadan

Vazgeç gökteki yıldıza salıncak kurmaktan

Yok gülüm yok 

çocuk gibisin

Rüyayı gerçeğe çevirmek ister gibi

boş bir hayale gönül vermişsin...

İmkansızı istiyorsun, 

en imkansızı bekliyorsun hayattan...

Hadi başla o zaman

Dünü, yarın, yarını bugün yapabilir misin? 

gözünden akan yaşı bile durduramazken

kaderi nasıl değiştirirsin... 

gel vazgeç, vazgeçmelisin...', 'Yok canım, yok gülüm yok  Koşanı yakalamaya çalışır gibi halin Yürümeyi bile daha öğrenmedin Emekleyerek ne kadar gideceksin... Yok canım  y...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dunu-yarin-yarini-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiiristana Hoş geldiniz', 'siiristana-hos-geldiniz-ahmet-yozgat-8r81i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Günlerden bir gün,

Şu bizim masal haylazı Keloğlan,

Ellerinde demircinin dövdüğü asa,

Ayağında çifte su verilmiş bir çift çarıkla,

Düşmüş erken erken yollara...

Yollar uzunmuş minareler gibi,

Dağlar dağlardan daha büyük,

Keloğlansa küçücük.

Ama engin hayalleri sanki bir deniz,

Hepiniz şiiristana hoş geldiniz...

Bana hangi şiirleri getirdiniz? 

2/:

Günlerden bir gün,

Şu bizim masal yaramazı Keloğlan,

Anasının dokuduğu heybesi omzunda,

İnce ıslığı ağzında bir türkü tutturmuş,

Düşmüş kıvrım kıvrım yollara.

Kılavuzu yok sahipsiz kervanlar gibi.

Yolların kafası bozuk.

Çevrede büyüklü küçüklü binlerce iz.

Keloğlansa küçücük,

Hepiniz hayalistana hoş geldiniz...

Bana hangi hayalleri getirdiniz? 

3/:

Günlerden bir gün,

Şu bizim masal afacanı Keloğlan,

Güneşte uzayan gölgesi arkasında tin tin tin,

Düşmüş döne dolaşa uzaklara giden yollara,

Sonunda gökyüzünde yıldızlara dayanmış,

Güneş sıcak mı sıcak tandırlar gibi,

Yollar ıraktan daha uzak.

Ne bet kalmış, ne beniz,

Keloğlansa küçücük,

Hepiniz masalistana hoş geldiniz...

Bana hangi masalları getirdiniz?', '1/: Günlerden bir gün, Şu bizim masal haylazı Keloğlan, Ellerinde demircinin dövdüğü asa, Ayağında çifte su verilmiş bir çift çarıkla, Düşmü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/siiristana-hos-geldiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam Süsler Hayalimi', 'hocam-susler-hayalimi-ahmet-yozgat-13kf0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Açılır rüya pencerem

Hayallerin denizine dalarım.

Kafama tespih olur dizilir

Tıpkı Hoca''mız gibi

Fıkranın bin bir türü.

Dökülür beynime nükteler bir bir.

2/:

Günlerden bir gün...

Der ki bir komşusu:

''Düşmüş ay dede kuyuya.''

Bizim Hoca duydu ya...

Durur mu daha yerinde? 

Kapar kocaman ay''ı kuyudan,

Anında çıkarır yukarıya.

3/:

Günlerden bir gün...

Mahallede çocuklar keser önünü

Beleş sözdür dedikleri de:

''Hoca''m bana düdük al! '' 

Yanıt hazır efendide:

''Ver parayı, çal düdüğü! '' 

4/:

Günlerden bir gün...

Bazen kedi yer ciğeri,

Tartar kapıp kediyi.

Der ki: ''Bre hatun,

Eğer bu ise ciğer,

Nerede bizim Mestan? ''

5/:

Günlerden bir gün...

Yoğurt mayalar göle,

İncecik bir ipe un serer arada bir,

Varınca huzuruna Timur''un:

''Sultanım bir fil daha...'' der.

''Çok sevmişler de ötekini görünce,

Bizim ahmak köylüler.''', '1/: Açılır rüya pencerem Hayallerin denizine dalarım. Kafama tespih olur dizilir Tıpkı Hoca''mız gibi Fıkranın bin bir türü. Dökülür beynime ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hocam-susler-hayalimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşların Müzeyyen Hemşiresi', 'kuslarin-muzeyyen-hemsiresi-ahmet-yozgat-busrr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Komşumuzdu Müzeyyen abla.

Ellerini severdik onun,

Yumuşak,tüy gibiydi.

Gezinirdi saçlarımızda

Sevgili Müzeyyen ablamız,

Sanki annemiz gibiydi. 

1a/:

Bir arzusu vardı onun,

Ne ev isterdi ne para,

Hemşire olup beyaz melekler gibi

Şifa dağıtmak hastalara.

2/:

Komşumuzdu Müzeyyen abla.

Gözlerini severdik onun,

Kışta kar üstünde güneş gibiydi.

Bakarken yüzümüze,

Sevgili Müzeyyen abla,

Sanki ateş gibiydi.

2a/:

Bir gün boş arsada,

Kırık kanadını sardı,

Minnacık bir serçenin.

O günden sonra,

Bütün yaralı kuşların,

Tüy gibi elleriyle şifa dağıtan 

Melek gibi bir hemşiresi vardı.', '1/: Komşumuzdu Müzeyyen abla. Ellerini severdik onun, Yumuşak,tüy gibiydi. Gezinirdi saçlarımızda Sevgili Müzeyyen ablamız, Sanki annemiz gi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kuslarin-muzeyyen-hemsiresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıktır Benim Amcam', 'asiktir-benim-amcam-ahmet-yozgat-0xtba', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Amcam oturur harman yerine,

Başına toplar herkesi.

Türküler söyler ağız dolusu, 

Yürek dolusu şarkılar söyler.

İnler onun her vuruşuyla teller

Tımbır da tımbır...

2/:

Amcam haber verir karşı köyden,

Daha arkada kalan köylüleri anlatır.

Türküler dağıtır torba dolusu,

Dünya dolusu şarkılar dağıtır.

İnler onun her vuruşuyla teller

Zımbır da zımbır...', '1/: Amcam oturur harman yerine, Başına toplar herkesi. Türküler söyler ağız dolusu,  Yürek dolusu şarkılar söyler. İnler onun her vuruşuyla ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/asiktir-benim-amcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Pır Pır Eder', 'yuregim-pir-pir-eder-ahmet-yozgat-5ixe2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Üstümden kül rengi serçeler gider.

Kanatları pelerin olan kargalar gider.

Kuyruğu çatal kırlangıçlar gider.

Aşağıdan el sallarım sevgi ile.

Kuşların kanatçığı

Benimse yüreğim,

Pır pır eder...

2/:

Uçarım serçelerin peşleri sıra

Kanatlı rüyalarım kargaların peşinde

Kırlangıçlar ile ulaşırım ta bulutlara.

Aşağıdan selam salarım yıldızlara sevgi ile.

Kuşların kanatçığı

Benimse yüreğim

Pır pır eder...', '1/: Üstümden kül rengi serçeler gider. Kanatları pelerin olan kargalar gider. Kuyruğu çatal kırlangıçlar gider. Aşağıdan el sallarım sevgi i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregim-pir-pir-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınara Kiracı Kuş', 'cinara-kiraci-kus-ahmet-yozgat-a45b5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Uçmuş uzak yollar boyu

Bir göçmen kuş çok yorulmuş.

Ortalıkta kalakalmış sonunda,

Ne bir tek dostu var çevrede,

Ne de sıcak yuvası varmış.

Daha yeni dönmüş göçünden.

Yağmurlar yağmış üstüne,

Savrulmuş rüzgârlarda.

2/:

Uçmuş uzak ülkelerin üstünden 

Bir göçmen kuş çok yorulmuş.

Demiş kendi kendine:

''Herkes girerken evine,

Benim yalnız kalışım,

Yani benim tek başıma,

Ortalık dakalışım niye? 

3/:

Uçmuş engin denizlerin üstünden 

Bir göçmen kuş çok yorulmuş.

Tüyünü tek tek,

Teleğini çifter çifter,

Saçını tutam tutam,

Yolmuş ha yolmuş...

4/:

Uçmuş kıvrım kıvrım yollar üstünden 

Bir göçmen kuş çok yorulmuş.

Dağ başındaki asırlık yalnız çınar,

Duymuş küçük kuşun ağıtını.

Demiş ki ona:

''Dallarım var salkım saçak,

On kucak dolanmaz gövdem var,

Haydi kur yuvanı dalıma.

İster bu yanıma,

İster öbür yanıma...''

Minik kuş, kuşlar gibi sevinmiş

Hemen bir yuva kurmuş,

Gün görmüş çınarın dallarına.

Sıra gelince kirayı konuşmaya

Helel olsun çınar amcaya:

''Canın sağ olsun! '' demiş...', '1/: Uçmuş uzak yollar boyu Bir göçmen kuş çok yorulmuş. Ortalıkta kalakalmış sonunda, Ne bir tek dostu var çevrede, Ne de sıcak yuvası varmı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cinara-kiraci-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deveci Daylak''ın Son Seferi', 'deveci-daylak-in-son-seferi-ahmet-yozgat-tsuu5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Şu bizim deveci Daylak,

Çift hörgüçlü devesi ile gezinir,

Ayak yalın, baş kabak...

2/:

Bazen uçsuz bucaksız bozkırlar onun,

Yarık yarık yaylalar devenin olur.

Koca koca buğday dolu çuvalları,

Yükler sırtında taşıdığı kamburuna,

Dayanır pampal ayakları,

Yazın yakıcı tozlarına,

Kışın kıvamlı çamuruna...

3/:

Bizim deveci Daylak

Dön bir kez de bana bak! 

4/:

Şu bizim deveci Daylak,

Çift hörgüçlü devesinin önünde,

Gezinir aylak aylak...

5/:

Bazen iner susuzluktan kavrulan çöllere,

Tandır külü gibi sıcak kumlara uzanır.

Yanar ciğeri on günlük susuz gibi,

Dört bir yanda bir vaha arar,

Bulamaz, yüreği yanar.

6/:

Bizim deveci Daylak

Dön bir kez de ardına bak! 

7/:

Daylak umut ile döner geri,

Ufuklarda yol arar yorgun gözleri,

Bulamaz, yüreği yanar.

Yok olmuştur arkada bıraktığı izleri.

6/:

Zavallı deveci Daylak

Dön bir kez de devene bak!', '1/: Şu bizim deveci Daylak, Çift hörgüçlü devesi ile gezinir, Ayak yalın, baş kabak... 2/: Bazen uçsuz bucaksız bozkırlar onun, Yarık yarık ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/deveci-daylak-in-son-seferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedem Derdi ki', 'dedem-derdi-ki-ahmet-yozgat-qxtpn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Dedem sıradan bir vatandaş...

Açardı ağzını yavaş yavaş:

''Evlat,'' derdi bana.

''Bir gün boğazda Çanakkale''de...''

Anlat dede, de hele

Anlat dede bizlere...

2/:

Dedem sizin gibi bir vatandaş...

Yumardı gözünü yavaş yavaş:

''Yavru,'' derdi 

''Bir başka gün sıcak Yemen''de...''

Anlat dede, de hele

Anlat bizlere dede...

3/:

Dedem herkes gibi bir vatandaş...

Açardı ellerini yavaş yavaş: 

''Torunum,'' derdi 

''Bir gün kanlı İnönü''de...''

Anlat dede, de hele

Bizlere anlat dede...

4/:

Dedem zavallı bir vatandaş...

Yayardı yüreğini yavaş yavaş:

''Çocuğum,'' derdi 

''Bir gün sen de...''

Evet dede,

Anlat dede, de hele

Anlat dede bizlere...', '1/: Dedem sıradan bir vatandaş... Açardı ağzını yavaş yavaş: ''Evlat,'' derdi bana. ''Bir gün boğazda Çanakkale''de...'' Anlat dede, de hele Anla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dedem-derdi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Harf Ki', 'bir-harf-ki-yilmaz-aybar-7cu5e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar muzır tip varsa dünyada

      Seninle var hepsi

      Meselâ Zübük

      Zibidi

      Zirzop

      Zırdeli

      Zırcahil

      Ve züppe gibi

      Daha ne bileyim

      Örneğin Zilli

      Zıpır

      Zındık

      Zıpçıktı

      Zırtapoz

      Ve Zırtullah gibi

      Akla gelen

      Ve gelmeyen daha niceleri

      Seninle başlıyor hep

      Onlar da olmazdı belki

      Sen olmasaydın

      Ve de pek muhtemel ki

      Dünya rahat ederdi o zaman

      Harf misin dert mi

      Boşuna atmamışlar

      Alfabenin sonuna seni', 'Ne kadar muzır tip varsa dünyada       Seninle var hepsi       Meselâ Zübük       Zibidi       Zirzop       Zırdeli       Zırcahil       Ve ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-harf-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Kızın Sahibi Sarı Mehmet', 'sari-kizin-sahibi-sari-mehmet-ahmet-yozgat-54n7f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Sahibim sarı bıyıklı Mehmet,

Tarar salkım saçak kuyruğumu,

Sarı tüylü sırtımı tımar eder,

Yayılır yüzüme bereketli bir sevinç.

Doldururum ağzına dek kovayı:

''Mehmet sütümü afiyetle iç e mi? ...''

2/:

Sahibim ela gözlü Mahmut,

Samanımı geceleri bol verir,

Yemimi dolu dolu sabahları,

Yayılır mahcup yanağıma al:

''Mahmut kaymağımı da al e mi? ''

3/:

Sahibim çatık kaşlı Ahmet,

Elinde kocaman bir meşe sopa,

Hışım gibi girer alaca karanlık ahıra,

Vurur acımasız bir eda ile sırtıma 

''Yine kim ne demiş buna? ''

Şaşırırım, olurum şok:

''Ahmet sana yarım yağlı süt de yok! 

Tam yağlı peynir de yok!', '1/: Sahibim sarı bıyıklı Mehmet, Tarar salkım saçak kuyruğumu, Sarı tüylü sırtımı tımar eder, Yayılır yüzüme bereketli bir sevinç. Doldururu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sari-kizin-sahibi-sari-mehmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-saliha-tekin-6cd5u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece kurşun gibi çöktü yine

  Güneşin varlığını aratmıyor

  Yıldız dostun sesi

  Gece kurşun değil

  Kuş oluyor ak kanatlı', 'Gece kurşun gibi çöktü yine   Güneşin varlığını aratmıyor   Yıldız dostun sesi   Gece kurşun değil   Kuş oluyor ak kanatlı...', ARRAY['Türk Edebiyatı','Şiir','Saliha Tekin']::text[], 8.5, '{"poet":"Saliha Tekin","poet_slug":"saliha-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dost-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Kelepir Kuyunun Öyküsü', 'satilik-kelepir-kuyunun-oykusu-ahmet-yozgat-aklw7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bizim asabalı Halil emmi 

Ne zaman ki tanıdı musluğu

Ağzına alıp neşeli bir ıslığı

Geçmişine mil çekti

Bilmeden geleceğine sünger...

Bahçesinde bir kuyu kazılıydı Halil emminin

Babası ondan gidermişti susuzluğunu

Bütün dedeleri de

Çocukluğundan beri Halil emmi de

Hatta Halil  emminin köylüleri bile...

Artık köye terkos geldi ya

Gerek kalmadı kuyuya.

Halil emmi: ''Ama giderayak işe yarasın

Bir alıcı çıkar bakarsın.'' Dedi.

Emektar kuyuyu satışa çıkardı

Pazara tellal

Çarşıya çığırtkan saldı.

2/: 

''Haydi satılık kelepir kuyu.

Gıcır gıcır kıvrılan çıkrığı

Ve sarı çamdan kovası

Doruklardan süzülen soğuk suyu ile

Bu kuyu çok çok ucuza

Bu kuyu kelepir kuyu

Haydi alan yok mu bu suyu? 

3/:

Haydi satılık kelepir kuyu.

Çöllerde susayanlara

Bağrı yananlara kurak zamanlarda

Çorak tarlalarda... 

Haydi alan yok mu bu suyu? 

4/:

Haydi satılık kelepir kuyu.

Çevrede varken bu ev bolluğu

Bu kuyu çok çok ucuza

Bu bir kelepir kuyu

Haydi alan yok mu bu suyu? 

5/:

Haydi satılık kelepir kuyu.

Kıvrım kıvrım çıkrığı ile

Çemberli kovası bile yanında

On metre sicimi ile

Buz gibi içimi ile

Öldü fiyatına memba suyu

Bu kuyu kelepir kuyu

Haydi alan yok mu bu suyu? ''

6/:

Yapılan bunca reklam yaradı işe

Yanıt Hurşit dayıdan geldi bu seslenişe.

Üç aşağı, beş yukarı anlaştı iki komşu

Yani öldü fiyatına satıldı kelepir kuyu.

Hurşit uzatmadı işi

Kuyuyu bağladı tuvalete

O, artık fosseptik olarak hizmet edecek herkese.

7/:

Devam eden günlerde güneş yaktı kavurdu.

Savurdu bulutları ılıman rüzgar

Ne yağmur yağdı, ne kar.

Bir kuraklık kapladı dört bir yanı

Kurudu tüm dereler

Barajlar su dolmadı.

Çok geçmeden kurudu terkos gölü

Tabii ki evlerde öldü musluklar...

8/:

Hurşit emmi ah ile:

''Babadan kalık kuyum olaydı.

Yanmayacaktı ciğerim.'' diye ah etti.

Başını vurdu taşlara.

Kuruyan ağaçlara,

Susayan çocuklara,

Çatlayan dudaklara,

Bakacak yüzü yoktu.

Fosseptik koktu

Hurşit emmi veda etti kasabaya...', '1/: Bizim asabalı Halil emmi  Ne zaman ki tanıdı musluğu Ağzına alıp neşeli bir ıslığı Geçmişine mil çekti Bilmeden geleceğine sünger... Bah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/satilik-kelepir-kuyunun-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Toprak Depreşti', 'bir-gece-toprak-depresti-ahmet-yozgat-xh5rq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Gecelerden bir gecenin orta yeriydi.

Daha yeni yatmıştı annem.

Babam koyup sabah için kurduğu

Canlı hayallerini çekmeceye

Usulca girivermişti geceye.

Depreşti toprak

Uyandım sallanarak.

2/:

Bir anlıktı her şey.

Göz açıp kapayana kadar.

Beton sıvalı duvarlar patladı 

Yan yattı kirişler 

Kolonlar üstümüze devrildi 

Nice sonra bağırdı konu komşular:

''Heey! Kimse yok mu? ''

3/:

Yoktu, yoktuk, yoktular.

Artık yanı başımda ne babam vardı

Ne da sabah için kurup

Ceviz çekmeceye koyduğu 

Her gün için ayrı ayrı hayalleri.

Ne de canım annem vardı.

Bir tek ben kalmıştım yaşamda

Dünya ne kadar da dardı.', '1/: Gecelerden bir gecenin orta yeriydi. Daha yeni yatmıştı annem. Babam koyup sabah için kurduğu Canlı hayallerini çekmeceye Usulca giriver...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-gece-toprak-depresti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Şiir Babayım', 'ben-siir-babayim-ahmet-yozgat-y9fi0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Sabah oldu koşun çocuklar! 

Çıtır çıtır ve sıcak sıcacık

Koşun sabahlık gevrek şiirlere

Girin beyitler arasına usulcacık! 

2/:

Ben şiir baba, babası şiirlerin.

Tılsımlı dağarcığım dopdolu

Şirin, sıcak ve taze şiirlerle.

Kendi ellerimle sunacağım sizlere.

3/:

Yürüyün çocuklar işte gün doğdu! 

İyiye hep en iyiye

Güzele doğru biteviye

Ve yolunuz olsun hep doğrunun doğrusu.

Doğru yolsa şiirin ışıklı yolu.

4/:

Koşun çocuklar aydınlandı ortalık! 

Işıl ışılak ve ılıman ılık 

Koşun vitamin dolu şiirlere

İçin dizelerin gün ışığı şerbetini

Lık lık lık!', '1/: Sabah oldu koşun çocuklar!  Çıtır çıtır ve sıcak sıcacık Koşun sabahlık gevrek şiirlere Girin beyitler arasına usulcacık!  2/: Ben şiir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-siir-babayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Guguklu Bir Saatim Ben', 'guguklu-bir-saatim-ben-ahmet-yozgat-1qwn5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ben guguklu bir saatim...

Sayın ki sabah sabah serçe kuşu

Kuşluk vakti siyah tüylü sığırcık

Küçük kardeş kurar beni

Uyanayım diye sabah yedi buçukta

Ve kaldırayım diye kendini usulcacık.

2/:

Ben burmalı bir saatim...

Sayın ki sabah sabah çavuş kuşu

Kuşluk vakti boz tüylü balaban 

Küçük kardeş uyur erkenden sıcacık yatağında.

Ben uyumam geceler boyu

Uyku nedir? Tanımam zaten.

Ne gecenin öcülü-böcülü karanlığı

Ne de ıssızlık korkutur beni.

3/:

Ben zemberekli bir saatim...

Sayın ki sabah sabah saksağan

Kuşluk vakti masal kızı Zümrüdüanka 

Kendimi kaptırırım tik taklara.

Gün boyu yorulmuş olan küçük kardeş

Eş olmak için masal kuşuna

Dalıp rüyaların rüzgarlı uçuşuna

Beklerim ben onu yanı başında

O gökkuşağına binip ıraklara uçunca.

4/:

Ben tepesi çanlı bir saatim

Sayın ki sabah sabah ibibik kuşu

Kuşluk vakti dere boyunda telli toyum 

Yedi buçukta çalarım zilimi

Gözlerimi gözlerine dikerim

Beklerim kalkmasını küçük kardeşin

Güneşin doğmasını beklerim.

Ben guguklu bir saatim

Günü güne eklerim

Zayi olmaz emeklerim.', '1/: Ben guguklu bir saatim... Sayın ki sabah sabah serçe kuşu Kuşluk vakti siyah tüylü sığırcık Küçük kardeş kurar beni Uyanayım diye sabah ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/guguklu-bir-saatim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâhya Hamit Ağa', 'k-hya-hamit-aga-ahmet-yozgat-doyw3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Gübre kokulu küçük çiftliğin kâhyası 

Çilli yüzlü Hamit ağa

Horozlardan önce kalkar.

Erkenden koşar doru atları.

Buram buram burar bıyıklarını,

Kaşlarını silah gibi çatar. 

Takar arabayı arkaya

Sürer gider karşıdaki dağlara.

1a/:

Doru at...

Koştura koştura

Dıgı dıka, dıgı dıka...

2/:

Yarpuz kokulu küçük çiftliğin kâhyası 

Kaşık yüzlü Hamit ağa 

Tarhana içer sabahları kahvaltısında

Usulünce koşar doru atları

Kaşlarını av tüfekleri gibi çatar, 

Bakar tahta arabanın tekerlerime.

''Hım! '' der, kır saçlı kafasını sallar.

Sürer gider engin çayırlara.

2a/:

Doru at, ahşap araba...

Koştura koştura tarlalara...

Küçük tekerlekleri önde...

Dıgı dıka, dıgı dıka...

3/: 

Biçilmiş çimen kokulu çiftliğin kâhyası 

Tırpan kesiği yüzlü Hamit ağa 

Taze ot yükler tahta kasaya.

Yorgun yorgun koşar doru atları

Kaşlarını kışlada silah gibi çatar, 

Siper edip elini alnına

Uzun uzun bakar yollara

Gözden geçirir tahta arabasını 

Sürer gider uzaklara.

3a/:

Doru at, ahşap araba ve Hamit ağa...

Koştura koştura giderler tarlalara.

Küçük tekerlekleri önde

Büyük tekerlekleri arkada.

Dıgı dıka, dıgı dıka...', '1/: Gübre kokulu küçük çiftliğin kâhyası  Çilli yüzlü Hamit ağa Horozlardan önce kalkar. Erkenden koşar doru atları. Buram buram burar bıyık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kahya-hamit-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Sen Sür Arabamı', 'anne-sen-sur-arabami-ahmet-yozgat-jkbli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Aydınlık bir sabahtı

''Oğul can geldi.'' dediler.

Meğerse gelen benmişim dünyaya.

''Hani babam nerede? 

Bana gösterin babamı 

Anne sen sür arabamı.''

2/:

Hiç durmadan dönsün tekerlekler 

Arabam ilerlesin, 

Ben yürüyeyim hayata.

Bebekler büyürmüş yata yata.

''Beni babama götürün 

Ya da getirin bana babamı

Anne sen sür arabamı.''', '1/: Aydınlık bir sabahtı ''Oğul can geldi.'' dediler. Meğerse gelen benmişim dünyaya. ''Hani babam nerede?  Bana gösterin babamı  Anne sen sür ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anne-sen-sur-arabami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Badanalı Yalnız Ev', 'beyaz-badanali-yalniz-ev-ahmet-yozgat-3xf53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Öylece dururum burada

Issız bir yolun kıyısında.

Ben beyaz badanalı evim.

Ne kapımı açan bir el var

Ne de camlarımı sevenim.

Bazen çocuklar durur önümde.

Sevinirim, onlara seslenirim: 

''Gel Ekrem. Gel aç kapımı! 

Salih gel gir salonuma! 

Ocağıma iki odun atan olsa

Canlanacağım.''

2/:

Yaz gelir çevreme yeşil yeşil

Sarışın güneş doğar her sabah

Camı kırık mavi pencereme.

Ben beyaz badanalı evim.

Ne kapımı açan bir Allah''ın kulu var

Ne de ak badanamı sevenim.

Arada bir kuşlar konar çatıma

Sevinirim, onlara seslenirim:

''Gel karga. Gel tüne saçağıma! 

Sen de gel kırmızı gagalı leylek.

Gel, sen de kon isli bacama! 

Ocağıma iki odun atan olsa

Canlanacağım.''', '1/: Öylece dururum burada Issız bir yolun kıyısında. Ben beyaz badanalı evim. Ne kapımı açan bir el var Ne de camlarımı sevenim. Bazen çocuk...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beyaz-badanali-yalniz-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba Dünyanın Ne Var İçinde?', 'acaba-dunyanin-ne-var-i-cinde-ahmet-yozgat-5ql5p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Üstünde ben varım dünyanın,

Eflatun dağlarında gezerim,

Koşarım ince ve uzun yollarında,

Saklambaç oynarım gönlümce koyaklarında.

1a/:

Acaba dünyanın ne var altında? 

Dağların altında gezen var mı? 

Koşan var mı ince ve tozlu yolların altında? 

Saklambaç oynayan var mı koyaklarında? 

1b/:

Merak ederim işte.

Sahi kim var sizce? 

2/:

Dışında biz varız dünyanın.

Sokaklarında yürüyen annem var.

Babam var caddelerinde işine koşturan,

Tam altı milyar dünyalı var.

2a/:

Acaba dünyanın ne var içinde? 

Sokakların altında yürüyen anneler var mı? 

Babalar var mı işlerine koşturan? 

Kaç milyar iç dünyalı var? 

2b/:

Merak ederim işte,

Sahi ne kadar var sizce?', '1/: Üstünde ben varım dünyanın, Eflatun dağlarında gezerim, Koşarım ince ve uzun yollarında, Saklambaç oynarım gönlümce koyaklarında. 1a/: A...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/acaba-dunyanin-ne-var-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Ailenin Dökümü', 'altin-ailenin-dokumu-ahmet-yozgat-9tsw2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Babamız:

O, bizim altın adamımız. 

Gün boyu çalışan elleri nasırlı,

Siyah saçları beyazlasa da.

O, altın adamımız bizim. 

Tükenmez sevgisi ona hepimizin.

2/:

Annemiz:

O, bizim altın kadınımız.

Gün boyu mutfağa hapis olsa,

Beyaz elleri soğan koksa da.

O, altın kadınımız bizim.

Sevgisi tükenmez ona hepimizin.

3/:

Dedemiz:

O bizim altın atamız. 

Artık hiçbir işte çalışmasa,

Bastonla dolaşsa da.

O, altın atamız bizim. 

Bitmez sevgisi ona hepimizin.

4/:

Ninemiz:

O bizim altın büyükannemiz. 

Nurlu yüzü kırış kırış,

Beli baston gibi bükük olsa da.

O altın büyükannemiz bizim. 

Sevgisi bitmez ona hepimizin.', '1/: Babamız: O, bizim altın adamımız.  Gün boyu çalışan elleri nasırlı, Siyah saçları beyazlasa da. O, altın adamımız bizim.  Tükenmez sevgi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/altin-ailenin-dokumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüyünce Ne Olsam?', 'buyuyunce-ne-olsam-ahmet-yozgat-0os4i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ne olsam büyüyünce acaba? 

Düşünürüm günlerce.

Kafamda şöyle bir düşünce:

''Mesela berber olsam.

Dükkânım şuracıkta

Manav dükkanının yanı başında.

Ne zaman uzasa altın saçı

Mahalleli minnacık çocukların

İşte burada ben varım.''

2/:

Ne olsam büyüyünce acaba? 

Düşünürüm günlerce.

Kafamda şöyle bir düşünce:

''Mesela işçi olsam.

Berber dükkanını geçince ben.

Kürek babamdan miras kalma

Kazma ise dedemden...

Kavgam ekmek için

Yaz demeden, kış demeden.''

3/:

Ne olsam büyüyünce acaba? 

Düşünürüm günlerce.

Kafamda şöyle bir düşünce:

''Mesela çoban olsam.

Azman dağlar durağım.

Yanımda sürümün bekçisi çomar.

Önümde koca memeli keçilerim

Yerinde duramayan oğlaklarım

Burnu siyah batırmalı kuzularım

Mor yünlü koyunlarım

Sürer yaylalara giderim.''

4/:

Ne olsam büyüyünce acaba? 

Düşünürüm günlerce.

Kafamda şöyle bir düşünce:

''Mesela öğrenci olsam.

Bu ''a'' mı öğretmenim? 

Ya bu ne? ''Te'' mi? 

İkisi eşek mi eder, yoksa at mı? 

İki kere iki kaç eder? 

Altı mı eder iki kere üç? 

Dersimiz ne öğretmenim? 

Hayat bilgisi mi, matematik mi? ''

5/:

Ne olsam büyüyünce acaba? 

Düşünürüm günlerce.

Kafamda şöyle bir düşünce:

''Mesela çocuk olsam.

Kırlarda koşmaca oynasam,

Kayaların arkasına saklansam,

Elime kocaman bir çomak alsam, 

Çeliğin peşinden koşsam,

Bazen mavi dalgalı masallara dalsam

Geceleri kanatlansam

Kuşlar gibi rüyadan rüyaya uçsam,

Hep çocuk kalsam.''', '1/: Ne olsam büyüyünce acaba?  Düşünürüm günlerce. Kafamda şöyle bir düşünce: ''Mesela berber olsam. Dükkânım şuracıkta Manav dükkanının yanı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/buyuyunce-ne-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum''dan Atılan Cirit+', 'erzurum-dan-atilan-cirit-ahmet-yozgat-mq94u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Erzurum''dan atılan cirit

Birer birer mor bulutları delip 

Yırtıp mavi atlas gökleri bu uçtan öte uca,

en yüce burca teğet geçip kargasekmezde,

Sivri bir şeşber misali düşer mi acep? 

Sivas''ın serin yaylalarına...

Ardıçtan saçak olsam memleket saraylarına...

2/:

Erzurum''dan atılan cirit

Aşıp yeşil battaniyeye bürünmüş tepeleri,

Sıra sıra sıradağları geçip turna misali, 

Köroğlana selam verse derbentte,

Elbette Çamlıbelde karlı boralar gibi esse,

Soluğu kesilmese bozklu diyarında,

Yorgun bir cengaver ayarında,

Düşer mi acep? 

Konya''nın altın başaklı ovalarına...

Kahkullü seymenbaşı olsam memleket halaylarına... 

3/:

Erzurum''dan atılan cirit

Dönüp dolaşıp anam gibi Anadolu üstünde,

Kuş tütünde sulanıp, yemlenip yılan ödünde,

Turkuvaz Marmara''da dolaşıp vapur uskurlarıyla,

Kumruları ve martılarıyla yarışıp adaların,

Anaların saçlarına takılıp ağdaki hamsi gibi, 

Düşer mi acep? 

İnsanların hüzünlü yüreğine...

Mecliste saki olsam memleket beylerine...', '1/: Erzurum''dan atılan cirit Birer birer mor bulutları delip  Yırtıp mavi atlas gökleri bu uçtan öte uca, en yüce burca teğet geçip kargasek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/erzurum-dan-atilan-cirit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bize Yeşil Tahta', 'soyle-bize-yesil-tahta-ahmet-yozgat-uustz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Yeşil yazı tahtası 

Söyle bize: 

Ahmet mi benim adım? 

Kız kardeşim Ayşe mi? 

1a/:

Yaşama yol nerden gider? 

Söyle bize yeşil yazı tahtası 

Yani 2 x 2 kaç eder? 

2/:

Yeşil yazı tahtası

Söyle bize:

''Anne'' nasıl yazılır? 

''Baba''da kaç ''a'' var? 

2a/:

Evimize yol nerden gider? 

Söyle bize yeşil yazı tahtası 

Yani 2 x 2 kaç eder? 

3/:

Yeşil yazı tahtası 

Al eline tebeşiri: 

Yuvarlak bir ''sevgi'' çiz bize

''Barış'' çiz altı milyar kenarlı

Dosdoğru ''kardeşlik'' çiz.

3a/:

Söyle bize yeşil yazı tahtası 

Yüreğe yol nereden gider? 

Yani 2 x 2 kaç eder?', '1/: Yeşil yazı tahtası  Söyle bize:  Ahmet mi benim adım?  Kız kardeşim Ayşe mi?  1a/: Yaşama yol nerden gider?  Söyle bize yeşil yazı tahta...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soyle-bize-yesil-tahta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldü Güneş', 'uzuldu-gunes-ahmet-yozgat-f7q51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Ayşe ve ben

Yaşarız kocaman bir apartmanda

Alt alta ve üst üste.

Baktı baktı da bu halimize güneş

Öyle üzüldü öyle üzüldü ki bize

Biz de acıdık kendimize.

2/:

Yusuf ve ben

Aynı apartmanın çocuklarıyız.

Koca koca dağlara tepeden bakarız.

Sıcacık oyun toprağı kaplı zemine

Tam on beş kat uzağız.

Baktı baktı da bu halimize güneş 

Öyle üzüldü ki bize

Biz de acıdık kendimize.

3/:

Zühal ve ben

Aynı demir kapıdan gireriz.

Dairelerimiz üst üste.

Ben otururum numara 37''de

Zühallerinki ise 45''inci daire

Baktı baktı da bu halimize güneş 

Öyle üzüldü ki bize

Biz de acıdık kendimize.', '1/: Ayşe ve ben Yaşarız kocaman bir apartmanda Alt alta ve üst üste. Baktı baktı da bu halimize güneş Öyle üzüldü öyle üzüldü ki bize Biz de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uzuldu-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Mor Bisiklet', 'ben-mor-bisiklet-ahmet-yozgat-qjdz4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ben mavi çamurluklu bisikletim:

Beni bir anne etti 

Sevgili bebeğine

''Al minişim.'' diye

Yaş gününde hediye.

2/:

Ben kırmızı gidonlu bisikletim:

Uyardı oğlunu bir anne,

''Aman dikkat et! '' diye.

Yaş gününde o anne

Verdi beni sevgili oğluna hediye.

3/:

Ben sarı sepetli bisikletim:

Daha ilk gününde yaşamımın

Bindirdim son hız ile

Sert bir kayanın dibine.

4/:

Ben mor bisikletin hurdası:

Hani güzelim hayat? 

Nere burası?', '1/: Ben mavi çamurluklu bisikletim: Beni bir anne etti  Sevgili bebeğine ''Al minişim.'' diye Yaş gününde hediye. 2/: Ben kırmızı gidonlu bisi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-mor-bisiklet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozkırdaki Ağaç', 'bozkirdaki-agac-yilmaz-aybar-270qo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bozkırdaki ağaç

      Sen uzakta akan su

      Özlemi yüreğimi

      Senelerdir yakan su

      Bir sancılı bekleyiş

      Ki tükenmez bir türlü

      Ne duam işitilir

      Ne söylediğim türkü

      Kavrulmuş dallarımdan

      Haber etsinler diye

      Nice kuşlar uçurdum

      Dönmediler geriye

      Ya seni bilmediler

      Ya unuttular beni

      Kuru değnekler ile

      Hep bir tuttular beni

      Sen uzakta akan su

      Ben bozkırdaki ağaç

      Duy artık çığlığımı

      Toprağım sana muhtaç', 'Ben bozkırdaki ağaç       Sen uzakta akan su       Özlemi yüreğimi       Senelerdir yakan su       Bir sancılı bekleyiş       Ki tükenmez bi...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bozkirdaki-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kepenekli Anka Çobanı', 'mavi-kepenekli-anka-cobani-ahmet-yozgat-49uv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ben mavi kepenekli bir çobanım.

Her akşam güneş abla girince evine.

Zümrüt ankalarımı katarım önüme

''Bir varmış, bir yokmuş'' kırlarına 

Tekerleme otlatmaya çıkarım.

Severim tekerlemeyi,

Ben de tadına bakarım.

''Bir varmışı'' tadarım,

''Bir yokmuşu'' dağarcığıma atarım.

2/:

Ben yün papaklı bir çobanım.

Kaf-ı küf dağı otlağım benim.

Katarım önüme elmas ankalarımı

''Allah''ın kulu çokmuş'' yaylalarına 

Masal yaymaya çıkarım.

Severim masalları,

Ben de tadına bakarım.

Allah''ın bir kulunu tadarım,

Bir kulunu dağarcığıma atarım.

3/:

Ben kamış kavallı bir çobanım.

Vururum kıvrım kıvrım yollara.

Kulelerdeki devlere el sallarım.

Sürerim altın ankalarımı

''Evvel zaman içinde'' tarlalarına

Masal toplatmaya çıkarım.

Severim masalları,

Ben de tadına bakarım.

''Evvel zamanı'' tadarım,

Şimdiki zamanı dağarcığıma atarım

Yarınki zamanı çocuğuma saklarım.', '1/: Ben mavi kepenekli bir çobanım. Her akşam güneş abla girince evine. Zümrüt ankalarımı katarım önüme ''Bir varmış, bir yokmuş'' kırlarına  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mavi-kepenekli-anka-cobani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Sıcacık Yüreğini Anne', 'ac-sicacik-yuregini-anne-ahmet-yozgat-33w0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bir tek sen varsın dünyada

Benim için bir tek sen anne.

Bilirim, bir tek ben varım 

Dünyada da senin için.

Bak yanı başındayım hep

Sıcacık karnındayım.

İzin ver de dışarıya çıkayım.

2/:

Ben geldim işte.

Bak yanı başındayım hep

Öp yanaklarımdan anne.

Al yumucuk ellerimi avuçlarına

Üşümesin minik parmaklarım

Kasım ayında soğukta

Aralıkta ayazda

Ocakta karda.

Bir sen varsın dünyada

Bir tek sen, benim için.

Aç sıcacık yüreğini anne! 

İzin ver de gireyim içine.', '1/: Bir tek sen varsın dünyada Benim için bir tek sen anne. Bilirim, bir tek ben varım  Dünyada da senin için. Bak yanı başındayım hep Sıcac...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ac-sicacik-yuregini-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Sabahı', 'kurban-sabahi-ahmet-yozgat-v6k6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

O sabah, apayrı bir sabahtı.

Önce kardeşim güneş doğdu

Sonra ben kalktım erkenden

Annem: ''oğlum uyan.'' demeden.

1a/:

Kurbandı,

Tekbirdi,

Ve et kokusuydu,

O gün her bir köşe.

İlk önce baktım aşağıdan güneşe. 

2/:

O sabah, mahalle bir başka şendi.

Selam verdim ilk önce kardeşim güneşe

Sonra erkenden çıktım dışarı.

Çevredeki çocuklar pür neşe.

2a/:

Kurbandı,

Tekbirdi,

Ve et kokusuydu,

O gün her bir köşe.

Selam verdim ilk önce kardeşim güneşe 

3/:

O sabah, bürünmüştük bayramlıklara

İlk önce el salladım aşağıdan güneşe 

Sonra da iyi bayramlar diledim 

Mahallemizdeki büyük, küçük herkese.

3a/:

Kurbandı,

Tekbirdi,

Ve et kokusuydu,

O gün her bir köşe.

İlk önce el salladım aşağıdan güneşe.', '1/: O sabah, apayrı bir sabahtı. Önce kardeşim güneş doğdu Sonra ben kalktım erkenden Annem: ''oğlum uyan.'' demeden. 1a/: Kurbandı, Tekbirdi,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kurban-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşa Mektup Yazan Hamurabi', 'tasa-mektup-yazan-hamurabi-ahmet-yozgat-01jnm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Sakalı ak tarih dede oturup

Siyah bir taş üstüne

Sağ elinde bir Asuri çekiç

Diğerinde Babil''den kalma bir koca çivi

ÖÇivi de çivi hani, sivri mi sivri...

Dedi ki, buhurdan sesiyle:

''Yaz oğlum Hamurabi...'' 

''Ne yazam ey Tarihi? ''

2/:

Ak urbalı tarih dede çömelip 

Beyaz bir taşta dizlerinin üstüne. 

Kaşları kıvır kıvır ve iki kılıç gibi çatık, 

Ses tonu, ağır mı ağır,

Buyurdu ki yorgun sesiyle:

''Yaz be oğlum Hamurabi...'' 

''Peki Tarihi! ''

Başladı, çaresiz çivi çivi yazmaya

Tarih dedenin katibi Hamurabi,

Kil tableti çopur çopur kazmaya:

''Ey oğul! 

Çağlar öncesinden bırakıyorum

Bu taş mektubu sana miras olarak.

Peki ne bırakıyorsun sen? 

De bakayım çağlar sonrasına

Yani çocuklarına? ...''', '1/: Sakalı ak tarih dede oturup Siyah bir taş üstüne Sağ elinde bir Asuri çekiç Diğerinde Babil''den kalma bir koca çivi ÖÇivi de çivi hani, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tasa-mektup-yazan-hamurabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Uçurtmam Kuşlar', 'benim-ucurtmam-kuslar-ahmet-yozgat-cwget', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Kuşlar benim uçurtmam:

Şu gürültücü kara karga

Ya da uzun kuyruklu şu sülün

Flüt üfleyen kül renkli serçe

Ben mutlu olayım diye

Gerilirler gökyüzüne.

2/:

Kuşlar benim uçurtmam:

Şu uzun ve kırmızı gagalı leylek

Veya göğsü benekli şu keklik

Hatta şu sinirli kartallar, 

Şu yakası kürklü akbabalar

Sevinsin diye biz çocuklar

İşi gücü bırakırlar

Uçurtma olurlar gökyüzünde.', '1/: Kuşlar benim uçurtmam: Şu gürültücü kara karga Ya da uzun kuyruklu şu sülün Flüt üfleyen kül renkli serçe Ben mutlu olayım diye Gerilirl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-ucurtmam-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Çamlara Ne Oldu?', 'eski-camlara-ne-oldu-ahmet-yozgat-mwyr9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ah Halil oğlan ah! 

Uyandığımızda bir sabah

Ne kertik yapraklı meşe ağacı kalmıştı

Ne de taş gibi sert gürgen dağımızda.

O günden sonra yaylalar soldu

Eski çamlar bardak oldu.

2/:

Sorma Halil oğlan sorma! 

Keskin ve uzun saplı baltalar

Hiç acımadılar şu yamaçtaki iğneli çama.

Kıvrım kıvrım gövdeli ardıç ağacına

Ah ah! Bir sabah kalkıp 

Karşı dağlara baktığımızda

Bir de ne görelim? 

Ortalıkta ne köknar kalmıştı

Ne de beş yapraklı çınar ağacı 

Düne kadar yeşil olan dağımızda.

O günden sonra yeşil tepeler soldu

Eski çamlar bardak oldu.

3/:

Ah Halil oğlan ah! 

Uyandığımızda bir sabah 

Soldu bizde bet beniz 

Dağların yeşili de soldu.

Kalmadı eski çamlar 

Ormanlar harap oldu

Biz harap olduk.', '1/: Ah Halil oğlan ah!  Uyandığımızda bir sabah Ne kertik yapraklı meşe ağacı kalmıştı Ne de taş gibi sert gürgen dağımızda. O günden sonra ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/eski-camlara-ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldü Gülbahar', 'guldu-gulbahar-ahmet-yozgat-d8epp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Pembe rengi severdi anası 

Gül koydu adını bu yüzden

Yeşillikleri seven babası ise Bahar

Çok kolay doğurttu onu köyün ebesi

Güldü güldü Gülbahar.

2/:

Anası altın küpe taktı kulağına

Nazilli basmasından fistan babasından

Fidan gibi boy pos verdi

Sürmeli bir çift yeşil göz

Ve kırmızı yanak verdi Yaratan.

Çok zor büyüttü onu ailesi

Ağladı ağladı Gülbahar.', '1/: Pembe rengi severdi anası  Gül koydu adını bu yüzden Yeşillikleri seven babası ise Bahar Çok kolay doğurttu onu köyün ebesi Güldü güldü ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guldu-gulbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Zaman Çerileri', 'eski-zaman-cerileri-ahmet-yozgat-3qwzl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Eski zaman çerileri

Masallara yakışırlar.

Bellerine yalbırdak kılıç takıp

Hilal gibi yay alırlar ellerine.

Yolları bizim masala uğradığında

Gıpta ile bakarım ben onlara

Onlarsa çevreye sinirle bakışırlar.

2/:

Eski zaman çerileri 

Toy kuşu tüyü takarlar kasklarına.

Binip semiz atlarına

Suçlu avına çıkarlar dağlara.

Yolları benim rüyama uğradığında

Ben özlem ile bakarım onlara

Onlarsa birbiriyle şakalaşırlar.', '1/: Eski zaman çerileri Masallara yakışırlar. Bellerine yalbırdak kılıç takıp Hilal gibi yay alırlar ellerine. Yolları bizim masala uğradığı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eski-zaman-cerileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vız', 'viz-yilmaz-aybar-lvojj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün var yarın yok bir dünyadayız

      Masalları pek çok bir dünyadayız

      Çevre kirliliği vız gelir bize

      Nasıl olsa bombok bir dünyadayız', 'Bugün var yarın yok bir dünyadayız       Masalları pek çok bir dünyadayız       Çevre kirliliği vız gelir bize       Nasıl olsa bombok bir d...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/viz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-mehmet-postalli-u72dv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her insanın başkadır, birbirindin siması

Düşünmek gerekmez mi, kimdir acep ustası.?', 'Her insanın başkadır, birbirindin siması Düşünmek gerekmez mi, kimdir acep ustası.?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/usta-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Futboldur Hayatım Benim', 'futboldur-hayatim-benim-ahmet-yozgat-vcn6o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Mahallenin kıyısındaki boş arsa

Gülümser ve el sallar bana

Boş vakitlerimi yakaladığında.

Ayağımda meşinden top

Kafamda sadece futbol

Süratle dalarım arkadaşlarıma

Bir çalım, bir çalım daha...

Sahanın kenarı kalkar ayağa:

''Gol goool! ''

2/:

Mahallenin kıyısındaki boş arsa 

Halı gibi çimen döşer yüzüne

Ben yere düşmeyeyim diye.

''Gel gel.'' eder ve el sallar bana

Boş vakitlerimde.

Gözümde bir tek futbol

Hızla dalarım koşuşan ayaklara.

Bir çalım, bir çalım daha...

Arsanın kenarı kalkar ayağa:

''Gol goool! ''', '1/: Mahallenin kıyısındaki boş arsa Gülümser ve el sallar bana Boş vakitlerimi yakaladığında. Ayağımda meşinden top Kafamda sadece futbol Sü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/futboldur-hayatim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığ Gibi Geliyoruz', 'cig-gibi-geliyoruz-ahmet-yozgat-gn5bo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Dağın doruğundan kopan

O küçücük kartopu

Nasıl kocaman olursa.

Biz de öyle geliyoruz

Çığ gibi hem de

İsteseniz de istemeseniz de.

2/:

Yaşamın zirvesinden kopup

Gürül gürül akarak sarp yamaçlardan

Kuşlardan kanat apararaktan

Yuvarlanarak son hızla

Bizler geliyoruz

Kızanlarla kızlarla.

Sel gibi hem de

İsteseniz de istemeseniz de.', '1/: Dağın doruğundan kopan O küçücük kartopu Nasıl kocaman olursa. Biz de öyle geliyoruz Çığ gibi hem de İsteseniz de istemeseniz de. 2/: Ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cig-gibi-geliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Oğlu', 'ruzgar-oglu-ahmet-yozgat-qbxj1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Her koşuda en başta o

Her yarış onun hakkı.

En önce bitirir yolu.

Çekilin çekilin ortalıktan! 

Geliyor rüzgârın oğlu.

2/:

Jokey Hasbi amca

Bol verir ona kepekli arpayı.

En taze otlar onun için 

On dört yapraklı yonca

Kışın ortasında yeşil korunga

Samanı da dolu dolu.

Çekilin çekilin önünden! 

Geliyor Rüzgâr oğlu.', '1/: Her koşuda en başta o Her yarış onun hakkı. En önce bitirir yolu. Çekilin çekilin ortalıktan!  Geliyor rüzgârın oğlu. 2/: Jokey Hasbi am...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgar-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Aşkından', 'o-nun-askindan-mehmet-postalli-6o8hc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüce Rabbin aşkından nehirler çağlamakta

Bitkiler zikir çekip, bebekler ağlamakta.', 'Yüce Rabbin aşkından nehirler çağlamakta Bitkiler zikir çekip, bebekler ağlamakta....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/o-nun-askindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesut ile Münevver''in Şiiri', 'mesut-ile-munevver-in-siiri-ahmet-yozgat-ivbbl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Birinin Adı Münevver''di onların

Diğerinin ismi de Mesut...

İki ikiz kardeştiler

Mutluydu her ikisi de.

Hem Münevver mesuttu

Hem de Mesut mesut.

2/:

Evde odaları yan yanaydı

Sınıfları ise aynı okulda.

Ortak kullanırlardı 

Çantalarında olan her şeyi

Cetveli de kalemi bile.

Hem Münevver mutluydu

Hem de Mesut, mesut.

3/:

Günlerden bir gün

Yatılı verdi babaları

İkizlerden Münevver''i.

Köyde yalnız kaldı zavallı Mesut.

Kardeşlerde bitti umut.

Şimdi ne Münevver mesut

Ne de Mesut, mesut.', '1/: Birinin Adı Münevver''di onların Diğerinin ismi de Mesut... İki ikiz kardeştiler Mutluydu her ikisi de. Hem Münevver mesuttu Hem de Mesut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mesut-ile-munevver-in-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzümüz Mavi Olsun Yeter', 'gokyuzumuz-mavi-olsun-yeter-ahmet-yozgat-lnq26', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bir kovan balını severiz biz

Bir de balon uçurmayı.

Yakaladık mı güneşli bir cumartesi

Ya da rüzgarlı bir pazar

Heyecan sarar kasabada herkesi

Artık diyecek yok keyfimize

Ellerimize ''Dur! '' demeyi bilmeyiz

İplerimiz yol alır uçakların rotasında

Tam yolun ortasında

Balonlarımız karışsa ne yazar? 

Gahi sarı, gahi mor, gahi kırmızı

Salarız gökyüzüne özgür balonlarımızı.

Grileşirse rengimiz eğer

Takılmaz kafamıza

Gökyüzümüz mavi olsun yeter. 

2/:

Bir kovan balını severiz biz 

Bir de balon uçurmayı göklerde.

Bazen iplerimiz takılır bir tele

Bazen de kuru dallı ağaçlara.

Balonlarımıza vız gelir her şey

Alır başını gider kimi kez

Koşar bulutlarla eklenir kimi.

3/:

Bir kovan balını severiz biz

Bir de engin maviliklerde balon uçurtmayı.

Mahallenin boş arsası bizim sayılır

Ya da şehrin dışındaki çayır.

Her cumartesi mirastır babamızdan

Pazar ise bebeği sayılır gözümüzün

Ya da belli olmaz

Hangi gün kanat çırpacağı

Rengarenk özgürlüğümüzün.

4/:

Göçen ve göçmeyen kuşlar arkadaşımız.

Yaşımız on, on beş, yirmi ya da yirmi beş

Hepimiz kardeş, hepimiz arkadaşız.

Vız gelir yağmurlar bize.

Kasabamıza ilk bahar geldiğinde

Hiçbir engel tanımayız.

Ulaşırız bir gün mutlaka 

Kardeşimiz güneşimize.

Bir balı severiz biz

Bir de balon uçurtmayı.', '1/: Bir kovan balını severiz biz Bir de balon uçurmayı. Yakaladık mı güneşli bir cumartesi Ya da rüzgarlı bir pazar Heyecan sarar kasabada h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gokyuzumuz-mavi-olsun-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracı', 'kiraci-yilmaz-aybar-e8d08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarayların da olsa dünyada kiracısın

      Gerçek zannettiğin bir rüyada kiracısın

      Gözünü enginlere dikip de yolda çıkma

      Şaşırma pusulayı deryada kiracısın', 'Sarayların da olsa dünyada kiracısın       Gerçek zannettiğin bir rüyada kiracısın       Gözünü enginlere dikip de yolda çıkma       Şaşırma...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Aybar']::text[], 8.5, '{"poet":"Yılmaz Aybar","poet_slug":"yilmaz-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kiraci-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çepeçevre Benim İşim', 'cepecevre-benim-i-sim-ahmet-yozgat-i3pgb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Çepeçevre benim işim.

Ben bisikletçi Ali''yim

Bunalırsam kentte egzoz gazından

Atarım kendimi dağlara.

Ne bozarım havayı

Ne çevreye zarar veririm

Ne de bir ziyan o yemyeşil yaylalara.

Bütün kuşlar benimle dosttur

Bulutlar sarmaş dolaş.

Ne kayaları oynatırım yerinden

Ne de 

Kaldırırım doğadan tek bir taş.

2/:

Çepeçevre benim işim.

Ben bisikletçi Ali''yim.

Hey heylenirim doruklarda.

Yakarsa genzimi kentteki duman 

Sızmışsa gri gazlar isli bacalardan

Ozonu delik atmosfere

Dere, tepe demem 

Basarım sonuna kadar pedalımı

Vururum kendimi yeşilliklere.

Çınar ağaçları gülümser

Ben geçerken gölgelerinden.

Taze rüzgar eser ta derinden

Ürperen iliklerime.

3/:

Ben çevreci bisikletçiyim.

Çepeçevre benim işim.

Bisikletim küheylan atım,

Heyecanım kanadım...

Doğayı kirletenler kederlerinden

Bir gün kahrolurlar umarım.

4/:

Benim işim çepeçevre.

Bisikletçiyim.

Zararım dokunmaz atmosfere

Çevreci Ali diye girsin namım 

Gelecek nesillere.', '1/: Çepeçevre benim işim. Ben bisikletçi Ali''yim Bunalırsam kentte egzoz gazından Atarım kendimi dağlara. Ne bozarım havayı Ne çevreye zarar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cepecevre-benim-isim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirsin Diye', 'gelirsin-diye-mehmet-postalli-6625y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümü yollardan alamıyorum

Aklına düşerde gelirsin diye

Başka bir adreste kalamıyorum

Yanılır, şaşarda gelirsin diye

Düşmanlara inat, doğruyu seçip

Muhabbet suyundan bir yudum içip

Müşfik kollarını yay gibi açıp

Ansızın koşarda gelirsin diye

Aradaki hainleri sezerek

Zihnindeki soruları çözerek

Bu sebepsiz ayrılığa kızarak

Dağları aşarda gelirsin diye.', 'Gözümü yollardan alamıyorum Aklına düşerde gelirsin diye Başka bir adreste kalamıyorum Yanılır, şaşarda gelirsin diye Düşmanlara inat, doğru...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelirsin-diye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarzan geliyor: ''Aaaa! ''', 'tarzan-geliyor-aaaa-ahmet-yozgat-3q8gc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Tarzan geliyor: ''Aaaa! ''

Sizden hesap sormayaaaa! ...

Kıymayın biz zavallı hayvanlara.

Kırın kalbinizi

Ya da elinizi, kolunuzu

Hatta o kalın kafanızı

Ama ne olur kırmayın boynuzumuzu.

2/:

Tarzan geliyor: ''Aaaa! ''

Sizden hesap sormayaaaa! ...

Kıymayın biz zavallı hayvanlara.

Kırın sırtımızı acıtan kırbacınızı

Ya da gürgen sopalarınızı

Hatta o kalın kafanızı

Ama ne olur kırmayın kanatlarımızı.

3/:

Tarzan geliyor: ''Aaaa! ''

Sizden hesap sormayaaaa! ...

Dokunmayın biz zavallı hayvanlara.

Bozun kendi evlerinizi

Ya da kurduğunuz ilişkilerinizi

Bozun tüm yaptıklarınızı

Ama ne olur bozmayın yuvamızı.', '1/: Tarzan geliyor: ''Aaaa! '' Sizden hesap sormayaaaa! ... Kıymayın biz zavallı hayvanlara. Kırın kalbinizi Ya da elinizi, kolunuzu Hatta o k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tarzan-geliyor-aaaa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Bire Yazıyor', 'ha-bire-yaziyor-yusuf-onder-bahceci-8owfs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey dostlarım, lütfen kusura bakmayın,

Sizleri çok severim, yanlış anlamayın,

Nerede bir haksızlık görsem, kızarım,

Ey dostlarım, lütfen kusura bakmayın.

Adam şiirleri peş peşe sıralıyor nasıl,

Şiirlerinin hepsi aynı aynı masal, fasıl,

Şiirler şiir mi, nesir mi, saçma mı asıl,

Adam şiirleri peş peşe sıralıyor nasıl.

Kardeşim bırak sen az yaz ve öz yaz,

Bak, Bahar geliyor, ardından da, yaz,

Yaz yaz Vatanı, Devleti, Milletimi yaz,

Kardeşim bırak sen az yaz ve öz yaz.

Saçmalıyorsun ve kul hakkı yiyorsun,

Şöyle bak kendine, iyi mi ediyorsun,

Haksızlığa gelemem sinir ediyorsun,

Saçmalıyorsun ve kul hakkı yiyorsun.', 'Ey dostlarım, lütfen kusura bakmayın, Sizleri çok severim, yanlış anlamayın, Nerede bir haksızlık görsem, kızarım, Ey dostlarım, lütfen kusu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ha-bire-yaziyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem ve Bebek', 'deprem-ve-bebek-ahmet-yozgat-u3atv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Toprakta deprem

Mahallede köpek

Ve beşiğinde bir bebek...

1a/:

Sallandı bir sabaha karşı.

Beyaz, sarı ve mavi evler

Ve kentteki tüm mahalleler

Sallandı baştan aşağı çarşı.

Çığlık çığlığa apartmanlar.

Tuğlalar uçuştular boşlukta.

Derin uykularından uyanan

Masum bebekler acı ile ağladılar.

Havladı köpekler, kediler miyavladılar

Ay dede çırpınmakta gölde acı içinde

Yarılırken topraklar

Takla atar tüm evler

Dükkanlar takla atar

Kimi yan yatar binaların

Kimisi de tam yatar.

2/:

Toprakta deprem

Sokakta köpek

Ve beşiğinde bir bebek...

2a/:

Bir anne yıkılan duvarın altında

Can vermede bir anda:

''Yavrum nerde diyerek? ''

Ağzından kan gelerek.

3/:

Toprakta deprem

Sokakta köpek

Ve beşiğinde bir bebek...

3a/:

Bir baba çöken tavanın altında.

Yok olmada bir anda:

''Ailem nerde? '' diyerek.

Sesi uzaklaşmada gittikçe,

Derinlerde inleyerek.

4/:

Toprakta deprem 

Yıkıntılar arasında bir köpek

Tutup beşiğin peşinden.

Ulum ulum uluyarak

Çabalamada canını dişine takıp

Havlayarak hırıltıyla karışık.

Minik canı kurtarmada.

Sonunda görünür ışık.

Bebek hala ağlamada 

Ama köpeğe gülümseyerek.', '1/: Toprakta deprem Mahallede köpek Ve beşiğinde bir bebek... 1a/: Sallandı bir sabaha karşı. Beyaz, sarı ve mavi evler Ve kentteki tüm maha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/deprem-ve-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeki İle Zekiye''nin Matematik Yolculuğu', 'zeki-i-le-zekiye-nin-matematik-yolculugu-ahmet-yozgat-snhg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Binip sayıların sırtına

Sayısal bir yolculuğa çıkarız.

1 artı l eşittir ise 2''ye

Ben Zeki''yim.

Ben de Zeki''nin kardeşi Zekiye.

2/:

Köprü kurarız 10''dan ona.

Toplarız alayını bir kümeye

Tüm asal ve asalak sayıların

Sağına virgül koruz, soluna sıfır.

Ben Zeki''yim.

Ben de Zeki''nin kardeşi zekiye.

3/:

Binip sayıların tılsımlı atlarına

Çıkarız sihirli bir yolculuğa.

2 + 2 = ise 4''e

Değmeyin keyfimize

Ya 5 + 3 = değilse 7''ye

Yazıklar olsun beynimize.

Ben Zeki''yim.

Ben de Zeki''nin kardeşi zekiye.

4/:

Buluruz çevresini karenin

Ve ikiz kenar üçgenin alanını.

Birbirine çarparız rakamları.

Artanları çantamıza toplarız.

Oluruz bir küçük sayı çobanı

Sayıları uzayda yaya yaya

Ulaşırız şeffaf yıldızlara

2 kere 2 eşit ise 4''e

Bölünce 10''u 2''ye.

Dijital bir kelebek oluruz

Konarız 3''e, sonra 5''e

Yaştaş oluruz 7''ye

Ben Zeki''yim.

Ben de Zeki''nin kardeşi zekiye.

5/:

Binip sayıların sanal atlarına

Çıkarız matematiği fethe.', '1/: Binip sayıların sırtına Sayısal bir yolculuğa çıkarız. 1 artı l eşittir ise 2''ye Ben Zeki''yim. Ben de Zeki''nin kardeşi Zekiye. 2/: Köprü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/zeki-ile-zekiye-nin-matematik-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Küçücük Eniktim Ben', 'bir-kucucuk-eniktim-ben-ahmet-yozgat-bej4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir küçücük eniktim.

Belki biraz yaramaz

Birazcık da haylazdım.

Ama hiç bir zaman

Ben bunu hakketmemiştim.

Çünkü ben bir küçük eniktim.

2/:

Ben bir küçücük eniktim.

Gözlerim yumuk yumuk...

Bir ilkbahar ayında

Örtüktü pencerelerim dünyaya 

En küçük çöplüklere bile

Henüz ''Merhaba.'' demiştim

Ama uzanırdı hayallerim

Kocaman ve yağlı kemiklere.

3/:

Ben küçücük bir eniktim.

Yaşamı yeni öğrenecektim.

Güneşli bir ilkbahar sabahı

Alıp elinize gürgenden sopaları

Kargalar gibi başıma üşüştünüz.

Bir vurdunuz, iki durdunuz.

Sonra gülüştünüz keyifle.

4/:

Ben küçücük bir eniktim.

İleride çok günler görecektim.

Büyüyecek karda, kışta ve kıyamette

Emniyette olun siz diye

Kapınızı bekleyecektim.

5/:

Ben küçücük bir eniktim.

Bir ocağın bir oğlu

Yani minnacık bir erkektim.

Soyumuzu gelecekte ben sürdürecektim.', '1/: Ben bir küçücük eniktim. Belki biraz yaramaz Birazcık da haylazdım. Ama hiç bir zaman Ben bunu hakketmemiştim. Çünkü ben bir küçük enikt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-kucucuk-eniktim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Yüklü Gider Okula', 'ali-yuklu-gider-okula-ahmet-yozgat-0q2v8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Bizim Ali gider okula.

Omzunda çantası var.

Çanta ki,

Ben diyeyim otuz kilo,

Siz deyin altı batman.

Yani kendinden büyük.

''Nedir bu yük Ali? 

Nedir bu yük? ''

2/:

Sizin Ali gider okula.

Elinde cetveli var.

Cetvel ki,

Ben diyeyim bir kulaç,

Siz deyin yüz elli beş santim.

Yani boyundan büyük.

''Nedir bu yük Ali? 

Nedir bu yük? ''

3/:

Hep Aliler gider okula.

Ağzında ezberi var.

Ezber ki,

Ben diyeyim yirmi kitap,

Siz deyin iki bin sayfa

Yani beyninden büyük.

''Nedir bu yük Ali? 

Nedir bu yük? ''', '1/: Bizim Ali gider okula. Omzunda çantası var. Çanta ki, Ben diyeyim otuz kilo, Siz deyin altı batman. Yani kendinden büyük. ''Nedir bu yük ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ali-yuklu-gider-okula-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemim', 'sitemim-suleyman-zaman-17q3l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yönetenler sitemim hep sizlere

Ne acılar çektirdiniz bizlere 

İnandık verilen onca sözlere

Bunca yoksulluğa ben ne diyeyim

Tezgahta  üreten, tarlada eken

Ekmeği yapan, libasları diken

Dünyada ki tüm çarkları çeviren

Bunca insanlara ben ne diyeyim

Faizle, teşvikle milyarı vuran

Yüksekten bakıp, kibirlice duran

Halkları halklara vurup kırdıran

Bunca doyumsuza ben ne diyeyim

İnsani  gözüküp bitmez çalımı

Görmüyorlar insanlığın halını

Tanıyın dünyada onca zalımı

Bunca zalimlere ben ne diyeyim

Zamanım ne çare gerçekler böyle

Yaşam gerçeğini doğruca söyle

Her zaman her yerde sevgi var eyle

Sevgisiz yaşama ben ne diyeyim

                    03.03.2006', 'Yönetenler sitemim hep sizlere Ne acılar çektirdiniz bizlere  İnandık verilen onca sözlere Bunca yoksulluğa ben ne diyeyim Tezgahta  üreten,...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitemim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Deymezsin', 'sen-deymezsin-mustafa-dogan-4-3gslt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEN DEYMEZSİN

Sana akan göz yaşlarım şimdi deniz oldu,

Ruhum o hasret denizinde çırpındı durdu,

Kalbim senden yalnız acı ile hicran buldu,

Her gün çektirdiğin acı ile yeniden öldüm.

-

Taştan o kalbinde sevgiden eser yokmuş,

Olan yalnız, benim zavallı kalbime olmuş,

Tüm göz yaşlarım akmış kalbime dolmuş,

Anladım sevgimin karşılığı sende yokmuş.

-

Seni sevince hiç gülemedim hep üzüldüm,

Beni seversin diye hep boynumu büktüm,

Seni severken hep senden nefret gördüm,

Sonunda ben bu acınacak hallere düştüm.

-

Sen sevemezsin ki kalbinde yoktur sevgin,

Anlayamazsın beni bu sevgimi bilemezsin,

Kalbimdeki o yangını artık söndüremezsin,

Senin kalbin yok,sen sevilmeye deymezsin.', 'SEN DEYMEZSİN Sana akan göz yaşlarım şimdi deniz oldu, Ruhum o hasret denizinde çırpındı durdu, Kalbim senden yalnız acı ile hicran buldu, H...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan 4']::text[], 8.5, '{"poet":"Mustafa Doğan 4","poet_slug":"mustafa-dogan-4","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-deymezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler de Ağlar', 'erkekler-de-aglar-timur-i-likan-pxw3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erkek adam ağlamazmış

Doğru değil yalandır bu

hem de kuyruklu yalan

Erkekler de ağlar

Öyle bir ağlar ki

Ağladı mı yürekler dağlar

Dağ yürekli erkekler de ağlar

(3 Mart 2006/ İstanbul)', 'Erkek adam ağlamazmış Doğru değil yalandır bu hem de kuyruklu yalan Erkekler de ağlar Öyle bir ağlar ki Ağladı mı yürekler dağlar Dağ yürekl...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/erkekler-de-aglar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlar Olsun', 'ugurlar-olsun-mehmet-postalli-5y4vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklına koymuşsun, isteme izin; 

Gitmek istiyorsan uğurlar olsun! 

Beni dinlemeyip,  el alem sözün; 

Tutmak istiyorsan uğurlar olsun! 

İyi ders almışsın dilin çok mahir

Kendim buldum, kime edeyim kahır

Tatlı  ekmeğimi, aşımı  zehir; 

Etmek istiyorsan uğurlar olsun! 

Kendi  kuruntunla  etme gıybeti

Zengin olmayanın, olmaz kıymeti

Sen, benim değil de düşman gayreti; 

Gütmek  istiyorsan  uğurlar  olsun! 

Yeter ki acı söz, bühtan olmasın

Ahbaplar üzülüp düşman gülmesin

Hiç hak etmediğim sözler gelmesin

Çatmak  istiyorsan  uğurlar  olsun! 

Hakkım helal olsun yinede  sana

Her zaman gerekli insan insana

Dilli düdük gibi karşımdan bana; 

Ötmek istiyorsan uğurlar olsun! 

Bulanık suların görünmez dibi

Kadir Mevlam bilir ancak gâibi

Yüreğime  çakır  dikeni  gibi; 

Batmak istiyorsan uğurlar olsun! 

Yüce Rabbim, beni  bırakma darda

Aklım şaşkın, gönlüm gamda, efkarda.

İsmimi  götürüp  panayırlarda; 

Satmak  istiyorsan  uğurlar  olsun.!', 'Aklına koymuşsun, isteme izin;  Gitmek istiyorsan uğurlar olsun!  Beni dinlemeyip,  el alem sözün;  Tutmak istiyorsan uğurlar olsun!  İyi de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ugurlar-olsun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında Değil Kimse Seni Ne Kadar Çok Sevdiğimin', 'farkinda-degil-kimse-seni-ne-kadar-cok-sevdigimin-efsun-aydin-lsnfr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanma ki bittiğini söyledin diye yazıyorum…

Ben seni kalbime hergün, yaşarken yazıyorum.

Dünya şahidim olsun ki seni unutmak istemiyorum.

Yitik Sevgilinin ardından şarkılar ile ağlamak istemiyorum.

Tuhaftır belki ama sancı çeksem de hergün seni yeniden doğurmak istiyorum.

Ben galiba her yeni gün sana gebe kalıyorum.

O yüzden anne yüreğimle üzerini örtüyor,

İlacını alıp almadığını merak ediyorum.

Özledim seni diyorken, 

Yazdığım şiirleri okumamak için direniyorken,

Ve kapatıyorken kapıları yüzüme 

Ben senden daha çok ağlıyorum.

Kimse bilmiyor seni ne kadar çok sevdiğimi,

Bilmesin de zaten.

Sen bil yeter.

Kafi gelir bu bana.

Bu akşam senin için içeceğim.

Su kadar saf, kutsal bir sevgiyi kaybedecek kadar bilincimi kaybetmedim henüz.

Aklım başımda, ne yapacağımdan emin takipçinim senin.

Gurur ile söylüyorum ki…

Sevgilinim Senin.

Hala…

Ayrılık belki bir başka bahara…', 'Sanma ki bittiğini söyledin diye yazıyorum… Ben seni kalbime hergün, yaşarken yazıyorum. Dünya şahidim olsun ki seni unutmak istemiyorum. Yi...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/farkinda-degil-kimse-seni-ne-kadar-cok-sevdigimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be Kız', 'be-kiz-muammer-erturan-co0nc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Be kız! .. 

Nasıl anlatmalı sana

nerden başlamalı bilmem... 

Bir vapur güvertesinde 

rakı içerken hem 

yem atmak var martılara 

mesela... 

Koşmak var el ele 

salıp saçlarını 

ıslıklı okşayışına rüzgârın,

öpüşmek var orda burda 

iplememek kaydıyla onu bunu,

dürmek var defterini 

bir dizi ezberin 

kim ne derse desin... 

Be kız! ..

O kadar çok şey var ki 

dilimin ucunda 

o kadar çok güzellik 

var ki daha

yaşanmaya hazır her an 

ve ne kadar çok 

yaşarsan yaşa 

o kadar az ki zaman... 

Nasıl desem be kız! ..

Bir sürü önemli işin arasında(!) 

tükenip gitmek var bir

üretip durmak bir de

her an yeniden,

her an yenilenen bir aşk ile..

Anla işte be kız! ..

Sen, ben ve aşkımız...

(Ekim ''94) .', 'Be kız! ..  Nasıl anlatmalı sana nerden başlamalı bilmem...  Bir vapur güvertesinde  rakı içerken hem  yem atmak var martılara  mesela...  K...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/be-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makam Mevkii İstemiyorum', 'makam-mevkii-i-stemiyorum-yusuf-onder-bahceci-jcuxv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben Devlet Memuruyum görürüm ne acaip erkekler,

Üstüne bir etek giyse, ne güzel yakışmış diyecekler,

Kendinden yukarıda olanlara hep el etek öpecekler,

Ben Devlet Memuruyum görürüm ne acaip erkekler.

Makam, mevkii çok mu önemli veriyorlar almıyorum,

Ben sadece Devlet, Millet, Memleket diye inliyorum,

Üç kuruşluk Dünya için, kimseye, köpeklenmiyorum,

Makam, mevkii çok mu önemli veriyorlar almıyorum.

Bu makamları, mevkiileri bizlere kim verir, kim verir,

Bunların hepsi Yüce Yaratan''ın değil mi, kuluna verir,

Mayası bozuk olanlar aman makam, mevkii der der,

Bu makamları, mevkiileri bizlere kim verir, kim verir.

Bana öte Dünya''da makam, mevkii verilsin, verilsin,

Verilen mevkii de, Yaratan, işte benim kulum desin,

Önder, başka makamları, mevkiileri, söyle ne etsin,

Bana öte Dünya''da makam, mevkii verilsin, verilsin.', 'Ben Devlet Memuruyum görürüm ne acaip erkekler, Üstüne bir etek giyse, ne güzel yakışmış diyecekler, Kendinden yukarıda olanlara hep el etek...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/makam-mevkii-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Çocuk', 'kucuk-cocuk-figen-aydogmus-6i74x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Getirdiğin bahara adını koydum

Bahçemde gelincikler sensiz kalmasın diye

Hiçbirini koparmaya kıyamadım

Bıraktım vazoyu

Suskunluğun son bulsun diye tam ortalarına

Öyle ki, yanlızlık koktu bahçem

Senden bir tutam daha ektim

Yeşerecek az kaldı küçük çocuk

Ben bekliyorsam 

Senin masumluğundan

Ben seviyorsam bahçeyi 

Senin varoluşundan', 'Getirdiğin bahara adını koydum Bahçemde gelincikler sensiz kalmasın diye Hiçbirini koparmaya kıyamadım Bıraktım vazoyu Suskunluğun son bulsu...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucuk-cocuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pozitif Keske', 'pozitif-keske-gultekin-toga-butka', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sıfır Dünya´nın varıp farkına,

Yunus Emre gibi Derviş olsaydım..

Nasıl da kapıldım nasıl çarkına, 

Gönlümü yerlere sermiş olsaydım,,,

Kinim olmasaydı aldatanlara,

Acısaydım süte su katanlara

Bana açık açık taş atanlara,

Tebessümle  çiçek vermiş olsaydım..

Üf demeden derde,gama,çileme,

Parayı hiç almasaydım elime.

Avukat olsaydım bütün aleme,

Sırf kendi nefsimi yermiş olsaydım..

Gönül incitmekten ödüm kopsaydı,

Yanağımı gözyaşlarım öpseydi,,

Hakk emrini seve seve yapsaydı

Nefsimi mütmain görmüş olsaydım..

Bu aşk ile tutuşarak dolarak,

Yola düşüp nerde ise bularak,

Taptuk dergahına teslim olarak,

Hizmetle ömrümü yormuş olsaydım,

Nefsin arzusunu korumaktansa

Cikmazin icine yürümektense,

Hakikat aşkından farımaktansa

Ateşin içinde durmuş olsaydım,

Sentezi her halde sona gidilir,

Mutlaka her yönden O´na gidilir,

Can içinde gerçek cana gidilir,

Bu izi bir ömür sürmüş olsaydım..', 'Bu sıfır Dünya´nın varıp farkına, Yunus Emre gibi Derviş olsaydım.. Nasıl da kapıldım nasıl çarkına,  Gönlümü yerlere sermiş olsaydım,,, Kin...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/pozitif-keske-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Vermeli', 'selam-vermeli-yusuf-onder-bahceci-7i7bf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben herkese Selamün Aleyküm derim,

Ben anlamam, merhaba, ne haberden,

Allah''ın selamı, üzerimize olsun, derim,

Ben anlamam, merhaba, ne haberden.

Tanıdık olsun, olmasın, selamı veririm,

Selamlar dostluk ve kardeşliktir bilirim,

Birisi de bana selam verirse sevinirim,

Tanıdık olsun, olmasın, selamı veririm.

Bak şimdi çeşit, çeşit selam veriyorlar,

Naber, merhaba, canikomsun, diyorlar,

Belki bilmiyorlar belki dalga geçiyorlar,

Bak şimdi çeşit, çeşit selam veriyorlar.

Ben herkese Selamün Aleyküm derim,

Ben anlamam, merhaba, ne haberden,

Allah''ın selamı, üzerimize olsun, derim,

Ben anlamam, merhaba, ne haberden.', 'Ben herkese Selamün Aleyküm derim, Ben anlamam, merhaba, ne haberden, Allah''ın selamı, üzerimize olsun, derim, Ben anlamam, merhaba, ne habe...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/selam-vermeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nohut', 'nohut-ahmet-simsiki-qksyr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'denize atsam bir nohut,

şişer kocaman olur mu? 

tuzuyla leblebi olsa,

suyuyla yemeği,

onca balığı doyururmu? 

ya göğe atsam bir taş,

bulutlar delinir feza oyulur mu? 

geceleri yıldız düşer,

ay düşerde,

suçu benden sorulur mu?', 'denize atsam bir nohut, şişer kocaman olur mu?  tuzuyla leblebi olsa, suyuyla yemeği, onca balığı doyururmu?  ya göğe atsam bir taş, bulutla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nohut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-ali-arslan-cid42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırılmış dal uçlarından 

çatlayan bir fidanla tutunur hayat.

Kanar damarından sağılarak toprak

gölgelerinde çığlık çığlığadır.

Rengârenk soyunur.

Çıplaklığına asılıdır 

her bir kadının apak memesinde.

Çiğdemin süt kokusunda şimdi 

dökülen bahar.', 'Kırılmış dal uçlarından  çatlayan bir fidanla tutunur hayat. Kanar damarından sağılarak toprak gölgelerinde çığlık çığlığadır. Rengârenk soy...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler İki Türlü', 'gunler-i-ki-turlu-muammer-erturan-6b4wy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler iki türlü

senin için:

Ya başka yerlerdesin

benden habersiz...

Ya benimle bensiz...

Günler iki türlü

benim için de...

Ya seninle geçen...

Ya sensiz senli,

geçmek bilmeyen...

Günler iki türlü

hep gene

ikimiz için de bak! ...

Bir ortak yanımız mı desem...

Bir ortak ayıranımız mı...

Bilmem...

(10 Ocak ''95)', 'Günler iki türlü senin için: Ya başka yerlerdesin benden habersiz... Ya benimle bensiz... Günler iki türlü benim için de... Ya seninle geçen...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunler-iki-turlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızlar Okumalı', 'kizlar-okumali-yusuf-onder-bahceci-1yi7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlla erkeklere aslan gibi demeyin,

Görüyorum bayanlarda neler var,

Okuyorlar, hakim, savcı oluyorlar,

Görüyorum bayanlarda neler var.

Ben onlara teşekkürler ediyorum,

Ne güzel okuyorlar, ben biliyorum,

Sonu iyi olacak derim görüyorum,

Ben, onlara teşekkürler ediyorum.

Tüm varını, yoğunu satıp okutmalı,

Tıp, tarih okutmalı, ziraat okutmalı,

Ömür boşa geçip de, avutmamalı, 

Ben, onlara teşekkürler ediyorum.

Bizim çektiklerimiz, cehalettendir,

Kızını okutmamak cahil adettendir,

Kızlar mutlaka okumalı, ayettendir,

Ben, onlara teşekkürler ediyorum.', 'İlla erkeklere aslan gibi demeyin, Görüyorum bayanlarda neler var, Okuyorlar, hakim, savcı oluyorlar, Görüyorum bayanlarda neler var. Ben on...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizlar-okumali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Olsa da', 'olum-olsa-da-mehmet-postalli-to1yl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zulmün karşısında hakkı haykırıp; 

Yazacağım, sonu ölüm olsa da.

Dinime küfreden yüze tükürüp; 

Kızacağım sonu ölüm olsa da.

Kurtların elinde olamam koyun

Tilkiye, çakala eğemem boyun

Hainler birleşse kursa bin oyun; 

Bozacağım sonu ölüm olsa da.

Hayatımda hiç sevmedim yalanı

Kirli kalemiyle şirret salanı

Peygambere dil uzatan yılanı; 

Ezeceğim sonu ölüm olsa da.', 'Zulmün karşısında hakkı haykırıp;  Yazacağım, sonu ölüm olsa da. Dinime küfreden yüze tükürüp;  Kızacağım sonu ölüm olsa da. Kurtların elind...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olum-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüş Menzili', 'opus-menzili-muammer-erturan-wjysx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yasak masak 

günah münah 

hikâye…

Gözümün görebildiği 

aklımın erebildiği 

dilimin dönebildiği 

her yerde 

sen varsın hep... 

Ne kadar unutmaca 

o kadar kandırmaca kendimi

ne kadar kaçmaca 

o kadar koşmaca sana

inadım inat… 

Hep istedi 

öpüş menzilimde seni

hep isteyecek 

yüreğim o yürek... 

(6 Mart ''95)', 'Yasak masak  günah münah  hikâye… Gözümün görebildiği  aklımın erebildiği  dilimin dönebildiği  her yerde  sen varsın hep...  Ne kadar unutm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/opus-menzili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-i-rfan-kaban-8urxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aptalım hem  de katıksız safi  sek

Onca deneyip yanılma onca da bilim bilgi caba

Körlük bende kütüklük daha nicesi falan ama

Hepsi bir yana, sorunum sevdada...

Kim demiş sevdalı yürek dağlar deler,hadi canım

Sevdalı yürek kıyamaz ne bir şeye ne dağlara

İçine patlar enerjisi sevdanın

Ne ederse kendine eder aşık gerisi düzmece yalan

sevdalının dikili direği var mıdır ki ondan kalan

Sevda merak barındırmaz ne büyür ne azalır

Sevdayla bu güne taşınmazdı dünya

Ve bir başına sevdayla yaşanmazdı 

Ondandır sevda ölüm çağırır ölüm aranır

Geride kalanlarca sevdalar

Sevdalılar olmadan kutsanır.', 'Bir aptalım hem  de katıksız safi  sek Onca deneyip yanılma onca da bilim bilgi caba Körlük bende kütüklük daha nicesi falan ama Hepsi bir y...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevda-144-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '~~Terkedilmiş Tütün Kokusu~~', 'terkedilmis-tutun-kokusu-burcu-alpaslan-guvenli-jg35l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne kuşlar sevinebildi 

güneşin 

çıkmasına

 ne sen

ne ben sevinebildim gelmene

ne düşlerim



nedense sen; 

benim için



bembeyaz hayaller içinde

hırçın hırçın 

parlarken

-ki ışığın sonu yok-



imkansızlığının ötesinde ne gecelere yatarsın.



ellerinden tütün kokusunu çıkartır 

-bırakırsın düne- ki



umutları yeni kağıtlara sarar 

koyarsın yastığının ucuna

-lütfen gitmesinler-



için için yanar gözlerin

sızlar sıkışır 

içindeki  -yerler/im-



öylece kalırsın....



sen her gece; 



ellerinden tütün kokusunu çıkartır

sevdanın acısına basarsın....



gece/n geçer,

gün/ün geçer,

ay/ların geçer,



ellerinden tütün kokusunu çıkartır; 



hiç bıkmadan

izlemek istersin



yeşil ırmaklarımı

uykuya dalmadan evvel...



02-03-2006 İstanbul (Yaşasın Düşgücü!)', 'ne kuşlar sevinebildi  güneşin  çıkmasına  ne sen ne ben sevinebildim gelmene ne düşlerim nedense sen;  benim için bembeyaz hayaller içinde ...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/terkedilmis-tutun-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Şimdi Gel', 'ne-olur-simdi-gel-mustafa-bilgili-lnddv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O küçücük ellerini uzat ne olur,

Sımsıcak yüreğimi yakala tekrar,

Yine öp dudaklarımdan hararetle,

Toprağa düşüp soğumadan bedenim.

Uzat ellerini karanlıklar basmadan,

İçimdeki korkuları bertaraf eyle,

Sonsuz sevgilerin hepsini al,bitir,

Toprağa karışıp,çürümeden bedenim,

Bırakma ellerimi sıcak kalsınlar,

Çıkmasın aklımdan tebessümlerin,

Gel ne olursun bir tanem yalvarıyorum,

Topraklara düşüp soğumadan bedenim.

Güzel gözlerini son kez göreyim,

Sıcaklığını hissedeyim bedenimde,

Üzerime üşüşmeden yılanlar,çayanlar,

Toprağa karışıp yok olmadan bedenim.

Gel ne olursun gel yalvarıyorum,

Sevdiklerinin başı için gel,

O minnacık ellerini yine uzat,

Kapımı yine sessizce aç,

Hasta yatağıma iliş yavaşca,

Ne olur akşamlar olmadan gel,

Yüreğime acılar çökmeden gel,

Bedenim kara toprağa düşmeden gel,

Gelmek çok mu zor geliyor böyle? 

Yeminmi ettin dönmemek için? 

Boz yeminlerini Allah affeder,

Gel tut ellerimi son defa,

Kavuştur artık beni huzura,

Daha sonrada mezarıma,

Ne yapayım gelmesen gelme.

                                                     25.02.1997', 'O küçücük ellerini uzat ne olur, Sımsıcak yüreğimi yakala tekrar, Yine öp dudaklarımdan hararetle, Toprağa düşüp soğumadan bedenim. Uzat ell...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ne-olur-simdi-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-mehmet-serdar-ates-8chqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BAHAR

Toprağın altında bekledi tohum,

Baharla birlikte cana can geldi,

Bir iken bin biri ekledi tohum,

Solarken vücudum yüze kan geldi.

Tabiat kendini baharda buldu,

Koyuna kuzuyla mutlu an geldi,

Bülbül aşk gülünü ikrarda buldu,

Ağaçlar yeşerdi dala şan geldi.

02/03/2006', 'BAHAR Toprağın altında bekledi tohum, Baharla birlikte cana can geldi, Bir iken bin biri ekledi tohum, Solarken vücudum yüze kan geldi. Tabi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahar-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma Sevgilerimle', 'ogluma-sevgilerimle-halide-eksioglu-d2h83', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En acı günlerimde sana sığındım.

En kötü günlerimde senle avundum.

Sevgin yüreğimden taştı, coştu..

Çağlayan sel oldu korkularımı alıp götüren..

Sen umudum oldun, yaşama bağlandım.

sadece bir anne değildim ben...

Seni seven, bana olan sevginle dolup taşan.

Her ızdıraba katlanan..

Esirgeyen, koruyan, sana bakan ben...

Göz pınarlarında yaş görmek istemezdim.

Ağlayan sesini hiç duymazdım.

Çünkü seni ağlatmazdım.

Hatırlıyorum...

Küçücük ellerinle, beni nasıl okşadığını, sevdiğini.

Ben uyurken yanağıma değdirdiğin o sessiz öpücüklerini.

Korkularından bana sığınıp,

Şefkatli anne kucağımda uyuduğunu.

Annenim ben senin.

Sevgilerin en güzelini sen yaşattın bana.

Sevgin kalbimin en kutsal yerinde.

Gölnümde, ruhumda evladım hep sen...

Kırsam da sakın sen kırılma bana.

Kızsam da sakın sen kızma bana.

Evladım ciğerparemsin benim sen.

Yaşadığım en güzel şeyler..

Yaşayamadığım tüm mutluluklar...

Kaderlerin en hayırlısı...

Seninle olsun yavrum.

Dualarım seninle...

Kalbim seninle...

16,12,1997 Salı', 'En acı günlerimde sana sığındım. En kötü günlerimde senle avundum. Sevgin yüreğimden taştı, coştu.. Çağlayan sel oldu korkularımı alıp götür...', ARRAY['Türk Edebiyatı','Şiir','Halide Ekşioğlu']::text[], 8.5, '{"poet":"Halide Ekşioğlu","poet_slug":"halide-eksioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ogluma-sevgilerimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevdiğim İki Şey', 'cok-sevdigim-i-ki-sey-mehmet-serdar-ates-47dar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÇOK SEVDİĞİM İKİ ŞEY

Ben iki şeyi çok severim,

İkisi de masum,

İkisi de tazecik,

İkisi de körpecik,

En sıkıntılı anımda,

Olsun ikisi yanımda,

O anda güler gözlerim,

Ben ikisini de çok severim,

Birincisi çiçekler,

İkincisi bebekler.

Kırılsın onlara kalkan eller.', 'ÇOK SEVDİĞİM İKİ ŞEY Ben iki şeyi çok severim, İkisi de masum, İkisi de tazecik, İkisi de körpecik, En sıkıntılı anımda, Olsun ikisi yanımda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serdar Ateş']::text[], 8.5, '{"poet":"Mehmet Serdar Ateş","poet_slug":"mehmet-serdar-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-sevdigim-iki-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-Ben', 'sen-ben-arafat-arik-16ew1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen,

Lâv, ten.

Mağrur, şen,

Bitmez gülşen.

Yanarım gülsen,

Eşiğimdin bilsen.

Aşka tahammülsüz sen,

Hem yokluğuma üzülen.

Sırça köşkümü harap eden,

Bin kez dönüp te,çiğneyip giden. 

Viranıma kibrit çakan, yakan sen,

Vicdanına inat, gamsız bakan sen.

Ah! insafına mahpus, yitik ben,

Ve yaşını gözüne gömen.

Afet gözlerinde biten, 

Anaforunda yiten.

Eczasız esriyen,

Belânı giyen,

Susamış ben,

Bekleyen.

Lâl ten.

Sen…

14-ŞUBAT-2006', 'Sen, Lâv, ten. Mağrur, şen, Bitmez gülşen. Yanarım gülsen, Eşiğimdin bilsen. Aşka tahammülsüz sen, Hem yokluğuma üzülen. Sırça köşkümü harap...', ARRAY['Türk Edebiyatı','Şiir','Arafat Arık']::text[], 8.5, '{"poet":"Arafat Arık","poet_slug":"arafat-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-ben-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Sesi Yok ki', 'olumun-sesi-yok-ki-aynur-avci-6i22r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümün sesi yok ki duyulsun

Anlamazsın bile

Bir gün,ansızın

Haber vermeden

Görünmeden,sessizce

Girer içeri,şaşırırsın

Daha çok erken desende

Tek elin sesi duyulmaz

Artık savunacak gücün yoktur

Hiç düşünmeden

İçine sığdırdığın

Ne aşk-

Ne sevda da

Kurtaramaz

Son nefesini

Yüreğinden koparıp alır

Bazen acı duyar çırpınırsın

Bazende haberin olmaz

Allah''ın kanunu bu

Kimse bozamaz..', 'Ölümün sesi yok ki duyulsun Anlamazsın bile Bir gün,ansızın Haber vermeden Görünmeden,sessizce Girer içeri,şaşırırsın Daha çok erken desende...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olumun-sesi-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşamayacağız', 'konusamayacagiz-yusuf-onder-bahceci-ox2os', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben hep sana böyle, böyle şiirler yazacağım,

Sen bu şiirleri okuyup, okuyup, ağlayacaksın,

Ben, her gece, evinizin önünden geçeceğim,

Sense içeride ağlayıp, sızlayıp yalvaracaksın.

Biz, hiç bir zaman göz göze, gelemeyeceğiz,

Hep böyle, düşünecek, utanacak, yanacağız,

Biz, birbirimize, hâlimizi bile soramayacağız,

Biz, hiç bir zaman göz göze, gelemeyeceğiz.

Bu zalimler, ne biçim bağlamışlar yollarımızı,

Tam, omuzum dan kırmışlar, tutar kollarımızı,

Korkarım ki onlar taşır bir gün bu sallarımızı,

Bu zalimler, ne biçim bağlamışlar yollarımızı

Ey Büyük Allah''ım, kulun, sana yalvarıyorum,

Sen onu bana sevdirdin hâlim ayan diyorum,

O Gül üzülmesin, Önder sabır, sabır diyorum,

Ey Büyük Allah''ım, kulun, sana yalvarıyorum.', 'Ben hep sana böyle, böyle şiirler yazacağım, Sen bu şiirleri okuyup, okuyup, ağlayacaksın, Ben, her gece, evinizin önünden geçeceğim, Sense ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/konusamayacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamandan', 'zamandan-aylin-onder-8ne3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son sayfalarıydı,

Rüzgarla boğuşurcasına savrulan.

Acısı; 

Uçuşan umutları olamazdı.

Bazı yörelerinde dağılmış mürekpleri,

Veya o kadar ıslak ki...

Okunmak istememişçesine,

Müstehcen....

Sırayla dönüyorken hayatı

Gözlerinin ömünde,

Sicim sicim döktüğü pırlantaları yerlerde.

Oysa nasıl yavaş yaşanmıştı,

Hissede hissede

Kaldırması kolay olmayacaktı.

Replikler tırmaladı guygusallığını..

Ne oynasa faydasız,

Çekmiti hayat son kartlarını,

Kalmıştı boyun kıldan ince.

Küfrüne miydi bu büyük ceza,

Anlamsızlığı bakışlarının.

Donup kalan sadece, baht mıydı? 

Ödülü ise ise yanlızlığın....

Sertliği hissedilen rüzgarın,

Koparttığı sayfalar, yaşanmışlıklardan,

Kaybedilen zaman, ömrün ummanından,

Feryat figan tutturmuş türküsünü,

Yürüsen ne olur yürümesen

Arkana bakmadan...', 'Son sayfalarıydı, Rüzgarla boğuşurcasına savrulan. Acısı;  Uçuşan umutları olamazdı. Bazı yörelerinde dağılmış mürekpleri, Veya o kadar ısla...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zamandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzleşme', 'yuzlesme-cengiz-kapusuz-b30se', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siz siz olun dostlar,

Yüreğinizin sesine kulak verin.

Yürekten gelen sesin,

Size yaptırdığına,

Pişman olsanızda,

En azından elinizin altında

Yüzleşecek  birini bulursunuz....', 'Siz siz olun dostlar, Yüreğinizin sesine kulak verin. Yürekten gelen sesin, Size yaptırdığına, Pişman olsanızda, En azından elinizin altında...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuzlesme-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Varım', 'artik-varim-meral-deli-idlyh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gitmiyorum

vazgeçtim

sen ister git, ister kal

artık seni sevmeyeceğim....

inat deği mi

ah ah

yürek ateşimi yaktın

söndürmen icab etmez

ve git artık ey kalpsiz

yürek seni affetmez...

affetmez

MERAL DELİ', 'gitmiyorum vazgeçtim sen ister git, ister kal artık seni sevmeyeceğim.... inat deği mi ah ah yürek ateşimi yaktın söndürmen icab etmez ve gi...', ARRAY['Türk Edebiyatı','Şiir','Meral Deli']::text[], 8.5, '{"poet":"Meral Deli","poet_slug":"meral-deli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-varim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sardunya Şöleni (Sesimdeki Kuğu)', 'sardunya-soleni-sesimdeki-kugu-ayten-colakoglu-2k77j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

babam sardunya ekerdi gönlündeki bahçeye

annem terasındaki saksılarda güz yetiştirirdi

geceleri gürültüyle fısıldaşırken sardunyalar

ayışığı fütursuz masallar anlatırdı

uykularıma kimseleri almazdım

bir gece sardunyalar uykuma sızdı...

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. babam sardunya ekerdi gönlündeki bahçeye annem terasındaki saksılarda güz yetiştirirdi geceleri gürültüyle fısıldaşırken sardunyalar ayışı...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sardunya-soleni-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rus Ruleti (Sesimdeki Kuğu)', 'rus-ruleti-sesimdeki-kugu-ayten-colakoglu-tcg33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

beyaz kombinezonlu bir kadını sevdin en çok

ölmenin uçuculuğunda valsi sevdin onunla

saçlarında başlayan simli geceyi

sesindeki pastel renkli ufku sevdin

begonyalarla örtülü sedirlerde sevişmeyi

parmağının ucundaki hâleyi öpmeyi

onunla tekrar tekrar ölebilmeyi sevdin

akik bir şişede tutulan ölmek duygusunu

gümüş kabzalı silahları, kumsala yağan kovanları

ayışığı ve gece morluğunda oyunları sevdin

beyaz elleri olan bir kadını sevdin en çok...

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. beyaz kombinezonlu bir kadını sevdin en çok ölmenin uçuculuğunda valsi sevdin onunla saçlarında başlayan simli geceyi sesindeki pastel ren...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rus-ruleti-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Çocuk-II-', 'kucuk-cocuk-ii-figen-aydogmus-427ch', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoşgeldin 

Nasıl özlemişim seni 

Nasıl beklemişim zamana inat 

Yüreğim umutlara gebe kalmış yıllar yılı 

Senin kokuna hasler zavallıymışım 

Hoşgeldin 

Kalbimde ki en büyük oda senin 

Ser valizini yere ben yerleştiririm 

Hoşgeldin 

Beklemekten ak düştü saçlarıma 

Gelmeyecek korkusunu yaşatma birdaha 

Cam kırıklarından bakıyordum yollara 

Kapım çaldığında gözlerim ağlamaklıydı 

Ah küçük çocuk 

Yılların fotoğraflarını biriktirdim sana 

Yıllanmış, beklemekten kırmızı şarap 

Kadehleri getir mutfaktan 

Kutlamak gerekir bu sonu 

Hoşgeldin 

Yüreğimin küçük (büyük)    aşkı 

Sana sonsuzluğu sunuyorum 

Sana ölmeyen sevdaları 

Bitmeyecek arzuları vaadediyorum 

Fakat korkuyorum küçük çocuk çok, 

Rüya olmasından 

Kaybolacağından 

Korkuyorum.', 'Hoşgeldin  Nasıl özlemişim seni  Nasıl beklemişim zamana inat  Yüreğim umutlara gebe kalmış yıllar yılı  Senin kokuna hasler zavallıymışım  ...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kucuk-cocuk-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Serçeye Benzer...', 'bir-serceye-benzer-murat-karasu-smbi9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceyle başladı yine bir hüzzam şarkı

Bir geri dönüş uzanır maziye dogru

Gözlere küskün hatıralar canlanır ellerimizde

Gizli bir köşede yalnızlığa direniş başlar...

Hasret yüreğimizde buruk bir yangın

Şansımıza yine esmer; deli,mavi günler...

''''Bir martı renginde saklıdır ümitler! ''''

Eski bir hüzün türküsüdür dilimizdeki

Dargındır sevinçler öteden beri yüzümüze

Üstümüzde hep yağmur bulutları gezer.

Yılların yorgunluğu gizlidir yüzümüzün her çizgisinde

Hayat oyununun son perdesidir oynadığımız...

Yarım kalmış bir şeyler hep hayatımızda

Bir ipek ipliğine bağlanmış mutluluğumuz

Kanayan bir yaradır içimizde habersiz geçen yıllar

Dayanılmaz bir ağrı olmuş yaşadığımız hikayeler...

Erteledik umutları hep gelecek baharlara

Her sonbaharla yeniden yıkıldık tutuşarak

Kanadı kırık bir serçenin son çırpınışına ağladık.

Her insanın bir serçeye benzediğini düşünerek...

Her insanın bir serçeye benzediğini düşünerek...', 'Geceyle başladı yine bir hüzzam şarkı Bir geri dönüş uzanır maziye dogru Gözlere küskün hatıralar canlanır ellerimizde Gizli bir köşede yaln...', ARRAY['Türk Edebiyatı','Şiir','Murat Karasu']::text[], 8.5, '{"poet":"Murat Karasu","poet_slug":"murat-karasu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-serceye-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Taş Yüzük', 'tek-tas-yuzuk-aynur-avci-fqa4h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın tek taş yüzük olsa

Takmam

Yakut zümrüt olsa dünyan

Dönüp bakmam

Yüreğinde -taht-kursan

Uzanıp yatmam

Sen beni

Taşıyamazsın

AŞKIM

Terk ediyorum

Dünyanın bu sarhoş

Şehrini

Sonsuzluğa-sonsuzluğa..', 'Aşkın tek taş yüzük olsa Takmam Yakut zümrüt olsa dünyan Dönüp bakmam Yüreğinde -taht-kursan Uzanıp yatmam Sen beni Taşıyamazsın AŞKIM Terk ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-tas-yuzuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tapınağı', 'ask-tapinagi-muammer-erturan-2qr2o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çisil çisil yağmur

ışıl ışıl güneş 

püfür püfür seher yeli 

ne varsa kuşatan beni 

hepsinde sen... 

Ortak koşmak bu ise 

koşuyorum işte! .. 

Olacağımız kadar günahkâr 

olmuşuz zaten

duracağımız kadar durmuşuz 

koklaşmadan etmeden 

Cehennemlik olmadan temelli 

gel hadi! .. 

Hele ki şimdi

maskesiz tövbeler mevsimi 

tam da bak! .. 

Arınmak için tekmil günahlardan 

zamandır tam... 

İster sabah gel 

ister akşam 

her anında günün 

kabul olunur tövbeler... 

Ve o kutsal ateşin 

yandığı her yer

aşk tapınağı birer... 

(30 Mart ''95)', 'Çisil çisil yağmur ışıl ışıl güneş  püfür püfür seher yeli  ne varsa kuşatan beni  hepsinde sen...  Ortak koşmak bu ise  koşuyorum işte! .. ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-tapinagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksan', 'yoksan-muammer-erturan-rubgn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ucu İstanbul 

bir ucu Gebze

bir uçtan bir uca bahar

masmavi gök 

yemyeşil kırlar 

sarılı beyazlı papatyalar... 

Neye yarar 

farkı yok kıştan 

yanımda sen yoksan...

Bir ucu İstanbul 

bir ucu Gebze 

bir uçtan bir uca yollar... 

Neye yarar 

ucunda sen yoksan...

(‘95)', 'Bir ucu İstanbul  bir ucu Gebze bir uçtan bir uca bahar masmavi gök  yemyeşil kırlar  sarılı beyazlı papatyalar...  Neye yarar  farkı yok kı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoksan-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Bir Mezar Taşı Var Başucunda-', 'bir-mezar-tasi-var-basucunda-dilek-kadioglu-nm3a3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğuştan kalbi delikti Yıldız’ın 

Annesinin gözleri önünde günde güne eriyordu

Ana yüreği kaldıramıyordu bunu 

İyileşmesi için dua ediyordu Rabbine 

Bir umut ışığı doğmuştu ameliyat olacaktı

İyileşip annesinin kollarına koşacaktı

Daha bir umutlu olacaktı yarınlar

Annesi okuyacağı okulları bile şimdiden düşünmüştü

İyi bir gelecek annesine yakışan bir kız olacaktı Yıldız

Olmadı.. Olamadı..

Hayallerin, düşlerin, umutların üstünü kara toprak kapattı

Yıldız ameliyattan çıkıp koşamadı annesine

Bir candan bir can gitmişti.

Bembeyaz gelinlikle görecekken kızını

Kefenle teslim ettiler annenin ellerine 

Oysa sabah öperek dualarla yollamıştı gözünün bebeğini 

Hastalığından dolayı hiç konuşamamıştı Yıldız

Annesi gözlerine bakarak anlıyordu ne istediğini

Ameliyata girerken o küçücük dudaklarının arasından Anne kelimesi çıkmıştı

Hüzünle mutluluk o an birbirine karışmıştı

İlk kez konuşmuştu ve Annesi son kez duymuştu.

Dört yaşındaydı Yıldız annesinin mavişi yaşama sebebiydi

Ecel gence yaşlıya bakmaz…

Azrail giren evde duman tütmez, aş pişmez 

Ölümün sessizliği dolar eve

Selası veriliyor Yıldız’ın son yolculuğunu haber veriyor hoca

Tanıyan tanımayan camiye akın ediyor yalnız bırakmıyorlar 

Yıldız’ı bu  son yolculuğunda 

Küçücük  bir beden yatıyor musalla taşında 

Annesinin sıcacık kollarından ayrılan Yıldız

Anne şefkatiyle Yıldız’ı  kara toprak kucaklıyor 

Annesi beklerdi her gece Yıldız’ı başucunda 

Annesinin yerine 

Bir mezar taşı var şimdi Yıldız’ın başucunda

     YILDIZ KADIOĞLU

D:23/05/1996 Ö: 22/06/2000

''Küçücük bir beden var bu toprağın altında. O benim kızım.''.', 'Doğuştan kalbi delikti Yıldız’ın  Annesinin gözleri önünde günde güne eriyordu Ana yüreği kaldıramıyordu bunu  İyileşmesi için dua ediyordu ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-mezar-tasi-var-basucunda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Diyemem..', 'diyemem-osman-kilic-3f5di', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dur çocuk! ! Dön şuraya bak:

Mavilik içinde yüzen bu adalar

Bu köpük kitleleri

Üzüntüsüz ve sevinçsiz birer göz yığınıdır

Şaşkın ve şaşırtıcı beyaz gözlerdir..

Bırak hepsi bakadursun..

Çiçeklerini çalarak bu parkın bekçisinden

Annenin gözlerini geri almış olursun

Şaşırılmış adres

Ve onlarda ağlamak bulursun..

Sisten peçesi altında büyük bir kent

Büyük bir yosmadır İstanbul

Ve bu şehir

Pahalı yemeklerin yendiği

Günlerce çıkaramadığın acı

Sancılı parasızlığındır senin

Bilirim

Ama özenme bunlara..

Diyemem..

Senin o küçük kuraklığının göz alan zenginliği

El çabukluğundan kaynaklanır çocuk

Satılık şeyi satılmışa çeviriveren

Parasını ödemeden alışveriş..

Bırak! ! o elindekini çocuk..

Diyemem...

Sırtında kalabalık alev alev kaynarken

Sen ateşler içinde isyanına gömülmüşsün çocuk

Ve yalnızlığına..

Uyan çocuk! ! 

Diyemem..

Uyanalım! ! 

**Eskiden her gece yatağa yattığımda bana bir bisiklet vermesi için tanrıya dua ederdim.Sonra tanrının çalışma stilinin böyle olmadığını anladım,gittim kendime yepyeni bir bisiklet çaldım.Ve ondan sonraki her gece yatağa yattığımda tanrıya beni affetmesi için dua ettim (Al Capone) ..

06.03.03', 'Dur çocuk! ! Dön şuraya bak: Mavilik içinde yüzen bu adalar Bu köpük kitleleri Üzüntüsüz ve sevinçsiz birer göz yığınıdır Şaşkın ve şaşırtıc...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/diyemem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokağıma kar', 'sokagima-kar-bestami-kurtulus-d6mej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sokağıma kar yağıyordu bir sabah

hem de kar! ..

yağıyordu gerçekten! ..

ve lastik çizmelerimin altında gıcırdıyordu

utanarak bakıyordum beyazlığına

felaket başımıza gökten geliyordu

enkazım yatıyordu buzlarda

yaralı balina ezilmişliğim

ve kar omuzlarıma birikiyordu

kaba lastik çizmelerimden utanıyordum

ve gidişini düşünüyordum senin

yolları geçişini 

evine dönerken

gözyaşları donmuş köprülerden

pişmanlık bir anıt gibi oturdu hüzün kaidesine

bilmedin yine de sen

kalsan; 

ben böyle güzel ağlayamazdım

düşseydim bir kez daha

buz bulanık sulara

hele kar da böyle yağarsa

bir daha asla 

ayağa kalkamazdım', 'sokağıma kar yağıyordu bir sabah hem de kar! .. yağıyordu gerçekten! .. ve lastik çizmelerimin altında gıcırdıyordu utanarak bakıyordum beya...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sokagima-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan', 'aglayan-bestami-kurtulus-7moy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağlayan bir türkü görürsen

yol üstünde boynu bükük

korkma dokun

al eline acıları

çağır

gömülsün yüreğine

her zerren bilir

o senindir 

şalvarlı bir çığlık

yaylalardan iner yalınayak

yabancı yok, hep tanıdık

gurbet utanır

ayaklar utanır

yol boyu yollar utanır', 'ağlayan bir türkü görürsen yol üstünde boynu bükük korkma dokun al eline acıları çağır gömülsün yüreğine her zerren bilir o senindir  şalvar...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglayan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımlarımı sokak kedileri saymalı', 'adimlarimi-sokak-kedileri-saymali-abdurrahim-kahraman-1aqu7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yavaşça

Sessizce

Sensizce

Çekip gitmeliyim

Adımlarımı sokak kedileri saymalı

Kanayan yüreğimin 

Kan kokusuna iştah kabartarak

İnancım cümle kapısının tokmağında asılı

Biliyorum yerini

Bilmiyorum yerimi

Biri yıkık duvar sarmaşığında asılı

Öbürü pencerende her gece

 Avluda bıraktım gözlerimi

Yavaşça

Sessizce

Sensizce

Çekip gittim

Bilmiyorum yerimi

Biliyorum değerimi

Geceye sildirdim izlerimi

Gecelere sattım gündüzlerimi

Yavaşça

Sessizce

Sensizce

Öylece

Çekip gittim.........', 'Yavaşça Sessizce Sensizce Çekip gitmeliyim Adımlarımı sokak kedileri saymalı Kanayan yüreğimin  Kan kokusuna iştah kabartarak İnancım cümle ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Kahraman']::text[], 8.5, '{"poet":"Abdurrahim Kahraman","poet_slug":"abdurrahim-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/adimlarimi-sokak-kedileri-saymali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Bu Dünya', 'bos-bu-dunya-tahmine-yildirim-scd1o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşıklar sevgisiz yaşanmaz derler

bu duyguyla dünyayı kendilerine zindan ederler

aşk her şey demek değildir bunu bilmezler

sevgisizde yaşanır çünkü boş bu dünya

Her gün sevdiğini görmek için Tanrıya dualar yağar

seviyorum deyipte insan bazen herşeyine boğun eğer

bir kaç yılda ortaya çıkar sevgisi sahteymiş meğer

ozaman benimkide sahte olur,çünkü boş bu dünya

Benim gönlümde aşka kesinlikle yer yok artık

inanmıyorum aşka bu herkesçe aşikar ve apaçık

gönlüm anahtarsız kilitli bir sandık

gönlüme anahtar bulmaya değmez çünkü boş bu dünya

İşte bak hayatımın otuz yılı geçti bile

şimdi isyan ediyorum o korkak geçen günlerime

sevenlere yinede mutluluklar diliyorum bütün gönlümce

karşılıksız sevenler unutun sizde,çünkü boş bu dünya', 'Aşıklar sevgisiz yaşanmaz derler bu duyguyla dünyayı kendilerine zindan ederler aşk her şey demek değildir bunu bilmezler sevgisizde yaşanır...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bos-bu-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gayrı', 'gel-gayri-cengiz-kapusuz-6j8nn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollarına güller dökeyim,

Bülbülleri dallara dizeyim,

Önüne çıkan engeli yok edeyim.

Kurban olam gel gayrı.

Sevdana sevdam/ı katayım,

Güzel yüreğine can katayım,

Uğruna saraylar yapayım,

Kurban olam gel gayrı.

Sana kusur ettiysem af ola,

Deli gönlüm gelir mi yola,

Gönüller sevda/yla dola,

Kurban olam gel gayrı,

Şu yüreğime gül gayrı...', 'Yollarına güller dökeyim, Bülbülleri dallara dizeyim, Önüne çıkan engeli yok edeyim. Kurban olam gel gayrı. Sevdana sevdam/ı katayım, Güzel ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gel-gayri-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zerdüşt Gibi', 'zerdust-gibi-ufuk-nazim-gp8uk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak 

Bir deli ugraştı.

Sürekli eksilmek

Küçülmekti.

Sonlu sayıları sayan

Sonsuzunu

Sayamayacağı 

Sayılara bağlayan 

Küçüklerdik.

Bir gün

Zerdüşt olup

Çıkardı bizi ayaklarımız

Dağların doruklarına.

Bütün hayvanlarla dertleştik

Sakallarımızda

Yuvalar kurdu örümcekler.

Güneşe sarıldık 

Her sabah.

Her akşam 

Ayla koklaştık.

Ruhumuzda gökkuşakları

Yağmurla günle gülüştük.

Kana kana içtik

Yaşamın gözelerinden

Hayatı. 

Doğayla kardeştik

Ve uzaktık

Namlularından zamanın.

                        27.01.2006', 'Yaşamak  Bir deli ugraştı. Sürekli eksilmek Küçülmekti. Sonlu sayıları sayan Sonsuzunu Sayamayacağı  Sayılara bağlayan  Küçüklerdik. Bir gün...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zerdust-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-ali-riza-unal-vsgpu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstemem köşkü meşk-i sarayı,

Sen benimle ol yeter-

İstemem düğün dernek halayı-

Sen benimle ol yeter.

Zaten ben seninsem sende benimsin-

Bunu ayan et yer,

Bilirim kulunla sessizce konuşurşun-

Bunu beyan et yeter-

Ne olur bir an dahi ayrılık verme bu tiryakine-

Benim azabım zebanım,senin firakındır bilirsin-

Bu zebanın ölümdende beter-

Ne olur bu ölümü verme yeter,

Kulların senden cennet,huri gılman ister,

Sen cömert lûtufkârsın,ver onlara sen onu

Sen beni sen ile zuhur kıl yeter. Amin', 'İstemem köşkü meşk-i sarayı, Sen benimle ol yeter- İstemem düğün dernek halayı- Sen benimle ol yeter. Zaten ben seninsem sende benimsin- Bun...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istemem-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'biLmEM KaÇ deLikANlıYA EŞ', 'bilmem-kac-delikanliya-es-gul-yazganarikan-b0uxv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük bir erkek o 

Daha yaşı beş

Öyle bir yüreği var ki

Bilmem kaç delikanlıya eş...

Pamuk elleri okşar yanaklarımı,

Siler ağladığımda gözyaşlarımı,

Her sözü bir düğüm olur boğazıma,

Küsmem, darılamam oğlum ben sana..

Kızarım kendime,

An gelir yetemediğim de olur elbette

Elden ne gelir oğul

İnsanım nihayet ben de...

Sensin varım yoğum, 

Bir gün ayrı kalsak 

Uykuyu unuturum...

Aç mısın oğul, tok musun? 

Uyuttular mı seni çoktan kınalı kuzum...

Neler gelir aklıma sen yokken yanımda...

Belki de uyumadın belki  korktun yatakta....

Razıyım her haline yanımda ol da...

Diyorsun ya “anneciğim ben yokken ağladın mı” diye

“Ağlamadım oğlum yattım erken” diyorum ben de...

“gördüm zaten” diyorsun...

“Görünmezlik kremi sürdüm onun için görmüyorsun...”

“Gitmedim ki anneciğim” diyor da  kandırıyorsun....

Ben sana ölmez miyim,

Senin o kocaman kalbine gömülmez miyim...

Çabuk gel oğlum, hemen gel, uyuma oralarda

Yaramazlık da yap, tutamasınlar seni ayrı odalarda

“anneme gideceğim” de...

anneme...

iki gün de olsa dayanmıyor yüreğim sensizliğe....

yüreğin bilmem kaç delikanlıya olsa da eş,

sen daha beş yaşındasın oğlumm... beş....', 'Küçük bir erkek o  Daha yaşı beş Öyle bir yüreği var ki Bilmem kaç delikanlıya eş... Pamuk elleri okşar yanaklarımı, Siler ağladığımda gözya...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bilmem-kac-delikanliya-es-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetten Geldiler', 'cennetten-geldiler-eyup-gok-cjzu3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostları gördüm geçen

Eskiydiler

Yıllar boyu, acı çeken

Sevgiliydiler

Gözlerde yaş, aşkı seven

Yürektiler

Faniydiler, ama sevmeden

Ölmediler

Cennet denen yerden

Geldiler

Bu dünyadan göçmeden 

Ölümsüzdüler

Muhabbet vardı bakışlarda

Arkadaştılar

Merhamet vardı arayışlarda

İnsandılar

Tozlanmış bir fotoğrafta

Sonsuza kadar

Dost kaldılar.', 'Dostları gördüm geçen Eskiydiler Yıllar boyu, acı çeken Sevgiliydiler Gözlerde yaş, aşkı seven Yürektiler Faniydiler, ama sevmeden Ölmediler...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cennetten-geldiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Küstüm', 'daglara-kustum-umut-beylik-2wer7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kılıçtım, 

Kınımdan sevdalara düştüm. 

Kınımdan düşüp de, 

Dağlara küstüm. 

Yorgun ve ezik 

Bir şefkate açıldı kollarım. 

Bilinmez, 

Asi diyarların mevsimlerinde 

Leş kanlarına bulanmış sular içtim. 

Yorgunluğumu bir damla yaşa benzetip, 

Çocukluğuma durdum. 

Durdum da vuruldum. 

Tutunmuşken yıldızların kollarına, 

Esirliğime, 

On yedisindeyken düştüm. 

Öyle ki, 

Bezgin bir gecede, 

Parmaklıklara, 

Düşlerimin öfkeleriyle 

Çığlıklarla alıştım. 

İntiharlara, 

İntikamlara seninle bulaştım. 

(02.03.2004)', 'Kılıçtım,  Kınımdan sevdalara düştüm.  Kınımdan düşüp de,  Dağlara küstüm.  Yorgun ve ezik  Bir şefkate açıldı kollarım.  Bilinmez,  Asi diy...', ARRAY['Türk Edebiyatı','Şiir','Umut Beylik']::text[], 8.5, '{"poet":"Umut Beylik","poet_slug":"umut-beylik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/daglara-kustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağma Vakti Yağmur', 'yagma-vakti-yagmur-hilal-sakar-hvqb7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vakit gelmedi mi yağmur? 

Yetmedi mi bu suskunluk? 

Dolmadı mı suların? 

Hazır olmadılar mı akmaya? 

Yağ yağmur! 

Durma hadi artık yağ! 

Belki bekleyen vardır! 

Hasrettir sana.

Yağ yağmur! 

Kötülükler seninle silinsin,

Bırak yeşillik dolsun her yer.

Yağ yağmur sevgiyi anlatmaya,

Her damlanda aşkı saklama.

Yağ yağmur! 

Issızlıkta saklanma,

Yağ sevdiğin şehirlere.

Bir damlan kalmamacasına yağ! 

Yeniden doğ! 

Yağdığın şehirde.

Sende hasretsin yağmaya.

Karanlık demeden yağ! 

Yağ yağmur! 

Yorulmadın mı vazgeçmekten? 

Bıkmadın mı savaşmaktan? 

Barış ol yağmur yağ! 

Yağ yağmur! 

Yüreğine damlamak umuduyla yağ! 

Gözlerdeki ışıltı hatrına,

Son istasyona geldiğin anda.

Yağ yağmur! 

Yağmur geçirmez yelek giyilse de sen yağ! 

Bunca sene boşuna birikmedin.

Gideceğin vakit gelmezden evvel,

Severken yağ yağmur! 

Durma artık yağ! ...

yağmurmah 2006', 'Vakit gelmedi mi yağmur?  Yetmedi mi bu suskunluk?  Dolmadı mı suların?  Hazır olmadılar mı akmaya?  Yağ yağmur!  Durma hadi artık yağ!  Bel...', ARRAY['Türk Edebiyatı','Şiir','Hilal Şakar']::text[], 8.5, '{"poet":"Hilal Şakar","poet_slug":"hilal-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yagma-vakti-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük', 'gunluk-ufuk-nazim-u2ujs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgili günlük

Sayısı unutulan 

Nice insan

Güzellikleriyle göçtüler.

Bir sen kaldın bize miras.

Dertlerimi ekip

Buram buram 

Bir yaz akşamı

Sarıya evrilen

Sahanda kavrulup

Helva helva yiyilen

Emeğimsin.

Ah uzaklar

Düşmeye görsün aklına

İnsan bir dile gelirki

Değmeyin efkarına.

Bir demli çay olursun

İşte o an 

Sen insana.

Yazası gelir insanın

Bütün yaşayan yanlarını

Yorgunluktan düşer kalem.', 'Sevgili günlük Sayısı unutulan  Nice insan Güzellikleriyle göçtüler. Bir sen kaldın bize miras. Dertlerimi ekip Buram buram  Bir yaz akşamı ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunluk-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyamazmısın Sanki Beni', 'anliyamazmisin-sanki-beni-tahmine-yildirim-2by4n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç bir zaman anlamak istemedin beni

hoşuna gitmeyen huylarım için hep kırdın içimi

sana göre bilmemki beni anlamak bu kadar zormu

olduğum gibi kalsam anlıyamazmısın sanki beni

Hoşuna giden hiç bir huyum yok gibi

biraz anlayışlı olsan değişmeye çalışırım belki

ama sen kendinden başkasını asla düşünmessinki

birazda beni düşünsen anlayamazmısın sanki beni

On iki yıldır hiç bir konuda yoksun benim yanımda

kim olursa olsun sen hep olursun benim karşımda

haklıyı haksızı incelemekten akılda kalmadı kafamda

aklımı tam kaçırmadan anlayamazmısın sanki beni

                                                                                 EYLÜL:1993', 'Hiç bir zaman anlamak istemedin beni hoşuna gitmeyen huylarım için hep kırdın içimi sana göre bilmemki beni anlamak bu kadar zormu olduğum g...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anliyamazmisin-sanki-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarım Muson Yağmurlarında', 'gozyaslarim-muson-yagmurlarinda-ozay-karakus-v3n98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerinin esiri olduğum o dehşetengiz gün yanaklarındaki gamze denen koridorlarda yürüttün bakışlarımı,zavallı dudaklarıma dudaklarınla işkence ettin merhametsiz, 

ellerinle kelepçeleyip ellerimi hapsettin sevgimi avuçlarına 

ve en sonunda kalbinin zindanlarında çürüttün bedenimi 

şimdi benliğim huzur evinde ölümü bekliyor bu aşkın akabinde,ruhum çoktan gökyüzüne iltica talebinde mülteci.... 

hala bendeki anılara tutunmaya çalışan hayalin pılını pırtını toplamış gönül yurdunda göçebe...tebessümlerin sanki kırık bir namlu ucunda yivsiz ve çapsız..sevgimle suladığım aşk fidanımı yeşermeden baltaladın sapsız....gövdesini böldün,kökünden çıkardın,yaprağını topladın yani aşkın kapısını suratıma çarptın hesapsız........ 

kaşlarım boşluğa seyirtiyor, gözbebeklerim yalın tavanlarda hipnoz,alnımda kutuptan bir ter dolayısı ile buzuldan bir soğuk 

kaskatı kesilmiş boynum hareketten yoksun kramplarda felç.. 

kirpiklerin zamana ayak uydurmuş roketatar zihnimde tatbikatta..vurur düşüncelerimi hedefte görmeksizin seri atışlarda,doldur boşaltlarda kalbim emniyetsiz.....üç köşe teşkil ediyorsun bağrımı izinsiz ve emirsiz... 

her şeye rağmen sen benim meleğimdin kanatsız,sensiz tabiat nü ve sanatsız,sorgulardayım...aşkın açıklamasını taş kalbinde bırakıyorum yanıtsız,sevgimi yüreğime gömdüm anıtsız...bırakmadım seni sevmediğime dair hiç bir delil bulunamaz.... kanıtsız..... 

şimdi gururum himalaya sıra dağları gözyaşım muson yağmurlarında kan kırmızı,gönül bahçem mayın tarlası siluetinde,göğüs kafesimde oksijen karbondioksite sitemli 

nefessiz kaldım sevdiğim....... sen gittin gideli.................', 'gözlerinin esiri olduğum o dehşetengiz gün yanaklarındaki gamze denen koridorlarda yürüttün bakışlarımı,zavallı dudaklarıma dudaklarınla işk...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozyaslarim-muson-yagmurlarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilenler içinde aşkı sordular', 'bilenler-icinde-aski-sordular-mikdat-bal-82o7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilenler içinde aşkı sordular

Ateşten gömlektir yakar dediler

Ahbaplar yarenler kafa yordular

O girince akıl çıkar dediler

Dünyası başkadır bakışı başka

Kıyamı başkadır çöküşü başka

Güneşi başkadır yakışı başka

Onu yanlız aşkı yakar dediler

Kalbi parçalanmış göz yaşı akar

Aklı sevdasında yollara bakar

Tepeden tırnağa hep sevda kokar

Her şeye sevgiyle bakar dediler

Derdi zevk edinir severek çeker

Ona dert tatlıdır bal ile şeker

Sinesine çeker boynunu büker

Dünya işlerinde sakar dediler

O sadece sever umut yoksa da

Bu aşkı onu bin derde soksa da

Gözlerinden kanlı yaşlar aksa da

Sevda ummanına akar dediler

Mikdatî der sevda ateşten gömlek

Sevene gerekmez ne kap ne çömlek

Eğer gerekirse bu yolda ölmek

Severek dünyadan göçer dediler', 'Bilenler içinde aşkı sordular Ateşten gömlektir yakar dediler Ahbaplar yarenler kafa yordular O girince akıl çıkar dediler Dünyası başkadır ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilenler-icinde-aski-sordular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk Yağmur Duasında', 'tomurcuk-yagmur-duasinda-ozay-karakus-njxiw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün kızıl,gün boğuk, ben buzul,ben soğuk 

güneşin hedefinde kanserojen bedenler,bense üşüyorum ve arıyorum sığınacak bir kovuk...kuytu köşeler bana zulümkar.. 

gökyüzü karamsar ama hava olabildiğince ferah,oksijen hidrojenden feragat etmiş....bulutlar sitemkar...suya hasret tomurcuk yağmur duasında... isyankar..... 

gençliğim kayıp bürosunda alınmayı bekliyor her aşkın sonrasında....bacaklarım romatizmal sancılarda.. ayaklarım alzheimer, parmaklarım yorgun...adımlarım cefakar.... 

güzel bildiğim her şey anılarım gibi maskeli dolanır etrafımda 

çırılçıplak.. ki.. arsız...bende bir bebek üryanlığında sevmiştim seni, saf ve katışıksız, bir dost gibi sadık ve vefakar.... 

gayrı kelime haznemde dar...guatır da düğümlenir anlam fakiri ve kifayetsiz...nesnel yargılar. öznel yargılarla çatışır... 

yüklemsiz..fiiller eylemsiz,dilim boğazımda gizlenir aşikar... 

güvendiğim dağlar kardan yoksun,yar çiçeğimdi o da şimdi 

taldan yoksun....vızıldayan arı misali yarı bal bildim arıyorum petekte... yar ise bikinide,mini etekte asi ve günahkar... 

gazel döktü aşkın kuru dalları, güz mevsimi suçsuz,masum..... 

bitkilerde bitkin ben gibi,onlar bahara bende o yare tutunur isek yeniden...o zaman kalırız aciz oluruz sahtekar......', 'gün kızıl,gün boğuk, ben buzul,ben soğuk  güneşin hedefinde kanserojen bedenler,bense üşüyorum ve arıyorum sığınacak bir kovuk...kuytu köşel...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tomurcuk-yagmur-duasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan ve Yaşam', 'i-nsan-ve-yasam-seher-ercan-0px9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sürpriz bir paket gibidir 

yaldızlı kağıtlara özenle sarılan 

göz alıcı rafyalardan kurdelesiyle. 

sevinçle karşılanır 

her şey tam tekmil 

bütün olasılıklar hesaplı 

her yer,her şey ona planlı 

yerlere göklere sığdırılmaz 

herkeste bir sevinç nidası. 

başlamıştır ona verilen süre 

büyümenin dayanılmaz sızılarıyla 

büyümek kolay değildir zira. 

büyürken mutludur bebekler 

anneleri yanındaysa 

mutlu-mutsuz çocukluk 

tercih hakkı yoktur 

deli dolu gençlik 

az da olsa söz hakkı verilir 

ne yapsa sığmaz bir yere 

sıkılır daralır 

yeter der: 

ben büyüdüm artık 

aramak benim hakkım 

mutluluğu yaşayacağım. 

mutluluk peşindedir 

o farkında olmasa da 

süre devam etmektedir. 

sever-üzülür 

pişman olur-ara verir 

vazgeçer-tekrar dener 

sever-sevilir 

sonra bir gün aşk gelir. 

geçmişi kolay unutur 

hiç yaşanmamış gibi 

dünya sürekli dönmekte 

yaşam su gibi akmaktadır 

acılar yaşanır farklı 

sevinçler,başka tatlarda 

bir gün bu koşuşturmanın 

yorgunluğu hissedilir omuzlarda. 

taşıdığı büyük yükü 

biraz azaltmak ister 

oysa yük hafiflerken 

dost azalır 

sevgi azalır 

hayat zorlaşır. 

bunalır 

içinden çıkılmaz sokaklardadır 

çıkar tekrar döner 

oysa tek yönlüdür yollar 

girdiğinde fark eder 

her şeyden vazgeçmek ister 

susup konuşmak istemediğinde 

zaten kimse kalmamıştır 

hayatla baş başa ve yalnızdır. 

süresi ise devam eder hızla 

hayat ne garip der 

kendi kendine 

her insanda başka yazgı 

nasıl düşünülür 

nasıl yazılır 

nasıl karışmaz birbirine 

yazılan bunca hikaye. 

benzemez biri diğerine 

yaşananların 

baharda çiçek çiçek açar dallarda 

başak olur salınır gezer rüzgarla 

hazandır sararıp düşen yaprakta 

karlar yağar sonra tek tek saçlara. 

ve zaman hızla yaklaşır 

çok uzak sanılan 

o meçhul sona. 

03.Mart.2006', 'sürpriz bir paket gibidir  yaldızlı kağıtlara özenle sarılan  göz alıcı rafyalardan kurdelesiyle.  sevinçle karşılanır  her şey tam tekmil  ...', ARRAY['Türk Edebiyatı','Şiir','Seher Ercan']::text[], 8.5, '{"poet":"Seher Ercan","poet_slug":"seher-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/insan-ve-yasam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Dahilindeyim', 'sensizligin-dahilindeyim-ozay-karakus-hff7a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine yalnızlığın sahilindeyim..... 

dolayısıyla sensizliğin dahilindeyim..... 

bugün mavisine tecavüz edilmiş ucsuz bucaksız deniz umarsız dalgalarda...med-ceziri hiç bu kadar görmemiştim sakin.. 

sürgün hayatında martılar başımda dolanıyor, leş kargaları misali arsız.....suskunlar benli vakitlerde dilsiz gibi lakin.. 

yine karetta yumurtalarının mahalindeyim.... 

sırtımda aşkın yükü kaplumbağa halindeyim.... 

gün gün gelirim seyrederim korurum onları seni korur gibi 

çatlayacak dudaklarım gibi kabuklar alıp götürecekler onlarıda biliyorum dalgalar sahibi...... 

yine varlığının hayalindeyim..... 

pusunda gözlerim meyalindeyim... 

küskün gülüşlerim her yanım tuzak bilmem nerde fak,bubi 

mecnun olmamı bekliyor toz bulutlarıyla haber salmış sina,gobi...... 

yine anlamsızlığın mealindeyim.... 

kavramda düşünceler sualindeyim.... 

özgün fikirler üreten beynim şimdi cahil kafalara tabi 

ihtiyarlıyor sensiz her dakika içimde büyüttüğüm sabi.... 

yine içimde kopan fırtınanın celalindeyim.... 

avucumda toplanmış kederin melalindeyim....

düzgün zeminlerde kavisli yürüyorum melekesiz gabi

yanımda sensizlik var,ayağım ondan dolaşıyor mutlak bittabi... 

yine ihtiraslı emellerdeyim..... 

kuramda bilimsel temellerdeyim.... 

süzgün bakışlarım güneşim kararmış artık ayrılık hobi... 

canımda yalnızlık, hücreselim kör pencerelerde sensiz olmak bence fobi... 

yine riyakar amellerdeyim... 

tutsağında vuslatın ellerindeyim... 

vurgun yemiş kayıkçılar gibi alabana olmuş kalbi 

yaramda kanasa varmı aşkını içimden söküp alacak harbi 

yine yaşamsızım ölmelerdeyim... 

ruhumda labirent destekli bölmelerdeyim.. 

yorgun ve bitkin bedenime gönderse azrail ecel celbi 

alsada canımı ulaşamaz cesedime yine ben olurum bu aşkın galibi....', 'yine yalnızlığın sahilindeyim.....  dolayısıyla sensizliğin dahilindeyim.....  bugün mavisine tecavüz edilmiş ucsuz bucaksız deniz umarsız d...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sensizligin-dahilindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâlbime Bakıyorum', 'k-lbime-bakiyorum-yusuf-onder-bahceci-327fz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durgun akan sular gibi akıyor, kâlbime bakıyorum,

Seni nasıl sevmişim, kendime, kendime kızıyorum,

Sen bahtımın Güneşiydin be nasıl ahlar çekiyorum,

Durgun akan sular gibi akıyor, kâlbime bakıyorum.

Ne zaman arayacak, ne zaman soracak, soracak,

Ne zaman yalvaracak, ben de seviyorum diyecek,

Ne zaman baktığım yollardan bir haberin gelecek,

Durgun akan sular gibi akıyor, kâlbime bakıyorum.

Belimiz bir yerden değil ki kırk, kırk yerden kırılmış, 

Acaba ol Mecnun''da Leyla''sını, böyle mi severmiş,

Peki Leyla Mecnun''u bırakıp neden çöllere dalmış,

Durgun akan sular gibi akıyor, kâlbime bakıyorum.

Eğer, sen bu şiirleri, okuyor da, önemsemiyorsan,

Adam, kafayı mı yemiş, kardeşim, yemiş diyorsan,

Dünya''dan da bir haberin yok ki bana ne diyorsan,

Durgun akan sular gibi akıyor, kâlbime bakıyorum.', 'Durgun akan sular gibi akıyor, kâlbime bakıyorum, Seni nasıl sevmişim, kendime, kendime kızıyorum, Sen bahtımın Güneşiydin be nasıl ahlar çe...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbime-bakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozanların Dünyası -mensuriye-', 'ozanlarin-dunyasi-mensuriye-zulfikar-yapar-kaleli-4rbma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '……….Denir ki; 

………….ozanlar hayal dünyaları

………………belki de en geniş olanlardır. 

.............Doğrudur. 

……..İnsan alemde hayal ettiği müddetçe yaşar çünkü. 

……..Çünkü hayal gücü ruhun gözüdür. 

……..Ozan dünyaya buradan bakar.

..................Gözler az gördüğü, 

.............kulaklar az duyduğu ölçüde

.......... hayal gücü artar. 

..........................Hayal ruhun gizli kapısıdır 

.....................................................da aynı zamanda. 

......................Bu kapıdan iyi fikirler girdiği gibi 

................kötü fikirler de girebilmektedir. 

............Bu yüzden bazıları zaman zaman sapıtırlar.

…………………..Hiçbir şey ele geçince 

……………….hayal olduğu kadar güzel kalmaz. 

………….Hayal edilen şey renk renk, 

………..desen desen, harikulade. 

……Ele geçen bunlardan sadece bir cüzdür.

...............Dünyanın gördüğü en büyük başarı 

.............önce bir hayaldi. 

....................En büyük, 

...........................en görkemli çınar bir tohumda, 

....................deve kuşu da bir yumurtada saklıydı zira.

.....................Hayal edilmeden 

....................yeni bir şeyler üretmek mümkün mü? 

.....................Ancak yeni bir şeyler yapma çabasında

................. olan insan hata da yapar. 

.................Nitekim insanoğlu hatadan arınmış değildir. 

...........Hatalar en büyük öğretmenlerdir. 

......................................En büyük hata ise hata diye 

...........bir şey kabul etmemektir. 

....................................Ancak ilk hata saflığın, 

............sonrakiler de suçun mahsulü olduğu unutulmamalıdır.

.................”Ufak bir hatanın cezasını 

.............kıyamete kadar çekersin” diyor, Tolstoy. 

............Ama hata yapmaktan korkan insan

.............................da hiçbir şey yapmamanın 

.................................................ezikliğini yaşamaz mı? 

.......................Hayal etmek, 

....................hayali eyleme dönüştürmek

........................ hataları çoğaltan bir vasıtadır. 

.........................İnsan kendi hatalarını ancak 

..........................başkalarının gözü ile görebilir. 

...............Hz. Ali diyor ki: 

............................”Hiç kimsenin hatasını yüzüne vurmayın, 

....................hatayı işleyene başka birisinin 

................hatasını örnek göstererek anlatın.

…………………” Nitekim o zaman bir kişinin 

……………….hata yapmasını önlersiniz. 

………………..Ancak onun kararlarını da 

……….kendi kendine vermesini önlemiş olursunuz. 

……………Bu da insanın hayal dünyasını karartır. 

……………Dolayısıyla üretme gücünü yok eder, 

…………..insanı çölleştirir.

…………………O zaman hiçbir şey 

…………..umut etmeyene ne mutlu. 

…………….Çünkü o hiç hayal kırıklığına uğramaz.

……….Hayal etmeyenin ömrü de 

……………..boğazıyla tuvaleti arasında geçer. 

………….Ondan topluma hayır gelmez.

................“Allah bütün insanları mesut 

...........olsunlar diye yaratmıştır. 

........Mesut olmaları için bazı dünyevi ve 

........uhrevi kurallar koymuştur. 

........İnsanlar bunlara uymuyor, 

........bedbaht oluyorlarsa 

........bu kendi hataları yüzündendir” diyor Epıotetes.

…………..Hindistan’ın efsane lideri; Gandhi’ de

………….”İnsan kendi hatasını büyüten, 

………..başkalarınınkini de küçülten aynada görebilse, 

…………her iki hata hakkında

……….. bir fikir yürütmeye muktedir olabilir” diyor.

………… Oysa insanların hatalarını kabullenmeleri 

…………..nefislerine çok ağır gelir. 

………….Bu yüzden çoğu zaman bu gerçekleşmez.

İnsan için en güzel, 

en erdemli şey kendi hatasını görmek,

 başkalarınınkini de 

mümkün olduğu kadar örtmektir. 

Hayal dünyası geniş insanların 

hataları da çoktur.

…………….Kafeste olmak, insana uçabileceği 

……………..hissini yaşatır.(Riviere)      Ancak; 

…………….. insan tek başına hayal eder, 

……….tek başına acı çeker ve tek başına ölür. (Amiel) .

…………..Uzakta aramaya gerek yok. 

…………..Şu yakın zamanda gördüklerimiz, 

………….yaşadıklarımız bunun delili değil mi? 

Yine de 

………….“geçmiş zaman olur ki hayali cihan değer”.

………………….Sen büyük şeylerin hayaliyle yaşa, 

………..…hiç olmazsa daha küçük şeyleri yapma 

………imkanı bulursun. 

İşte, 

……………..ozanlar bunu yapıyorlar.', '……….Denir ki;  ………….ozanlar hayal dünyaları ………………belki de en geniş olanlardır.  .............Doğrudur.  ……..İnsan alemde hayal ettiği müdde...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/zy29-ozanlarin-dunyasi-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Yeterim', 'ben-sana-yeterim-hatice-guler-2om69', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimin yörüngesinde gözlerimi kamaştıran

İçin için sevdasında benliğimi

Gözbebeklerinde hasretimi

Bal dudaklarında ölüm şerbetini

Doyasıya,sevesiye içtiğim

Kızgın çöllerden geçtiğim...

Yarınlarım,umutlarım ol

Sana açık kollarımda

Seni seven ruhumda

Aşkı,huzuru, kendini bul

Ben sana yeterim

Ben sana yeterim.', 'Kalbimin yörüngesinde gözlerimi kamaştıran İçin için sevdasında benliğimi Gözbebeklerinde hasretimi Bal dudaklarında ölüm şerbetini Doyasıya...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-sana-yeterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sene 1959', 'sene-1959-bahri-kayaoglu-ozw4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sene dokuz yüz elli dokuz

Birinci ayın biri

Amcam 

Askerlik yaparken Erzurum''da

‘Kara Kağıdı’ geldiği gün

Ben doğmuşum

İsmini bana vermişler...

***

İstanbul''da

Gurbette olan babama

''Kardeşin öldü'' değil de 

''Bir oğlun oldu, gel'' diye

Telgraf çekmişler...

***', 'Sene dokuz yüz elli dokuz Birinci ayın biri Amcam  Askerlik yaparken Erzurum''da ‘Kara Kağıdı’ geldiği gün Ben doğmuşum İsmini bana vermişler...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sene-959-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatılı Öğrenci', 'yatili-ogrenci-ethem-turan-rt357', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben yatılı okul öğrencisiyim

Annem umutla doğurmuş beni 

İlk kucağına alışta 

Sanki ruhunu kucaklamış

Sımsıkı sarmış 

Zaman götürmüş annemden 

Umutlarını beklentilerini

Bir ben kalmışım 

Annemin ileriye bakan  gözleri 

Kadermiş dağın eteğinde doğup 

Okulsuz köyde yaşamak 

Kıyılmasa da küçük yaşta kopmakmış 

Anamın sıcak kucağından 

Güler yüzünden uzak kalmakmış 

Yatılı okul olmuş anamın umudu 

Sarılıp kopmakmış 

Günlerce ayrı kalmak

Birbirimizden habersiz sessizce ağlamak

Dağın eteğinde sana yer yok demiş bir kez anam 

Senin yerin şehir olacak 

Okumak kurtuluşun 

Tek başına varolmak kaderin

Yılmak yok 

Ayakların üzerinde durmak 

Umutları yeşertmek amacın 

Benim varoluşum olacak senin kurtuluşun 

Büyük adam oldu denmem

Yanık göğsünü kabartman muradım 

Ağlama uğurlarken beni anam

Sızlamasın yüreğin yokluğumda

Her Cuma gelirim 

Zaten tek günüm var Cuma 

Kavuşma günü küçük dünyamda', 'Ben yatılı okul öğrencisiyim Annem umutla doğurmuş beni  İlk kucağına alışta  Sanki ruhunu kucaklamış Sımsıkı sarmış  Zaman götürmüş annemde...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yatili-ogrenci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni yalnız sen sev..', 'beni-yalniz-sen-sev-bahri-kayaoglu-9a856', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neler çektiğimi

Bu yüreğimi, bu gönlümü

Gülüyorken ağladığımı

Bilmesinler.

Beni yalnız sen bil...

Kötülük taşımadım kalbimde

Ağlayanla ağladım, dertliyle dertlendim

Doğruyu doğru bildim, eğriyi eğri

Mertliğimi, cömertliğimi yine de

Anlamasınlar.

Beni yalnız sen anla...

Başımı saldığım sevdalara

Hep yenik düşmüşsem

Hep parça parça etmişlerse

Kalbimi en temiz duygularla açmışken onlara

Sevmesinler.

Beni yalnız sen sev...

Ve bir gün

Seni ve bazı şeyleri

Artık bırakıp gitme zamanım gelmişse

Gözlerimi kapattığım an

Ağlamasınlar.

Benim için yalnız sen ağla...', 'Neler çektiğimi Bu yüreğimi, bu gönlümü Gülüyorken ağladığımı Bilmesinler. Beni yalnız sen bil... Kötülük taşımadım kalbimde Ağlayanla ağlad...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beni-yalniz-sen-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Arkadaşım Var', 'cok-arkadasim-var-yusuf-onder-bahceci-mx1ku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya benim ne kadar çok arkadaşım var,

Şiirlerimi okuyanlar hep dostum olurlar,

Bu şiirler de, mutlaka birşeyler bulurlar,

Ya benim ne kadar çok arkadaşım var.

Herkesi seviyorum, gerçek seviyorum,

Şiirle uğraşanlar duygulu olur diyorum,

Hepsi birbirinden değerli imreniyorum,

Ya benim ne kadar çok arkadaşım var.

Allah''ı seversen, onu pek çok översen,

Hata, kusur edince, dizlerini döversen,

Dostlarının küçük kusurunu görmezsen,

Ya benim ne kadar çok arkadaşım var.

Yanlış bir kelime yazınca, ikaz etsinler,

Biz bir kuluz, beşeriz, şaşarız desinler,

Sakın, sakın hatayı yanlış anlamasınlar,

Ya benim ne kadar çok arkadaşım var.', 'Ya benim ne kadar çok arkadaşım var, Şiirlerimi okuyanlar hep dostum olurlar, Bu şiirler de, mutlaka birşeyler bulurlar, Ya benim ne kadar ç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-arkadasim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Eylül', 'yirmi-eylul-tahmine-yildirim-siznz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne çabuk geçti bak yine koca bir yıl

yıllar çok çabuk geçiyor mine, kıymetini bil

hiç ağlama güzelim sen hep gül

bak yine çok çabuk geldi o 20 eylül

Bu gün girdin tam otuzbir yaşına

bu güne kadar gelmedik kalmadıki başına

bak yavaş yavaş aklar düşüyor saçlarına

aklarda olsa saçlarında,gelir yine o 20 eylül

Sağ olan her şeyi hem görür hem duyar

ne yaparsan yap kader bazen çok acı sorar

cevaplamak içinde benim gibi garibi seçer

cevaplasanda cevaplamasanda gelir yine o 20 eylül

Allahım daha nice doğum günleri nasip eylesin bana

çocuklarımla ana baba ve hayat arkadaşımla

tüm tanıdıklar,dostlar ve akrabalarımla

gülerek ve çok mutlu geçsin her yıl gelen o 20 eylül

                                                                            20.09.1993', 'Ne çabuk geçti bak yine koca bir yıl yıllar çok çabuk geçiyor mine, kıymetini bil hiç ağlama güzelim sen hep gül bak yine çok çabuk geldi o ...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yirmi-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurumlar', 'ucurumlar-volkan-i-ncel-ehug7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurumlar

İnsanlar atlasın diye değil

Korkup

Başka bi ölüm yolu

Seçsinler diye yaratıldı', 'Uçurumlar İnsanlar atlasın diye değil Korkup Başka bi ölüm yolu Seçsinler diye yaratıldı...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ucurumlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni düşünme..', 'beni-dusunme-bahri-kayaoglu-lzd0z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni düşünme..

Rüzgarda bir yaprağım

Kervan geçmez yüce dağım

Ne ilk ne de son durağım.

Beni düşünme...', 'Beni düşünme.. Rüzgarda bir yaprağım Kervan geçmez yüce dağım Ne ilk ne de son durağım. Beni düşünme......', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beni-dusunme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-husam-hasret-dgzd8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluk yolcusuyum, yolum şadlık yoludur

Gözlerimde bin ümit, gönlüm sevgi doludur

Tanrı bağışı aşkım, günler gibi uludur

Ondan dolayı sarmış gecemi mutluluklar

Bana çok şey bağışlar şadlık taşıyan elde

Türkümü dile salar bin bir ezgili telde

Çileyi anlatmayan bir ağızda, bir dilde

Bin defa tekrar eder hecemi mutluluklar

Her mevsimde yaratır, bana bir taze bahar

Yıllar geçse de artık değişilmez bu karar

Ezelden aşinayız, doğru dostluğumuz var

Tanır beni, babamı, kocamı* mutluluklar

Koca: Irak Türkmen şivesinde bu sözcük, ata anlamına gelmektedir.', 'Mutluluk yolcusuyum, yolum şadlık yoludur Gözlerimde bin ümit, gönlüm sevgi doludur Tanrı bağışı aşkım, günler gibi uludur Ondan dolayı sarm...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutluluk-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın...', 'gunaydin-bahri-kayaoglu-fzxp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öpüp koklamadığım saçlarına günaydın

Günaydın gözlerinin rengine...

Yeni bir güne

Yeni bir umuda

Seninle başlayan her şeye,

Günaydın...', 'Öpüp koklamadığım saçlarına günaydın Günaydın gözlerinin rengine... Yeni bir güne Yeni bir umuda Seninle başlayan her şeye, Günaydın......', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunaydin-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozan', 'ozan-husam-hasret-zia0g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gerçeği hayal eder engeller çemberinde

Hayali gerçek eder sınırsız uçurumda

İçini açmak ister adalet minberinde

Sessizliğe dayanmaz haykırır her durumda

Gözü değil, gönlünü açık koyar her anda

Salıverir duygusun, yelken açar engine

Koşuğun yankısını duyar derin limanda

Bir yüzücü örneği iner derinliğine

Sözcüklerini süsler doğanın tablosunda

Gah renkli bir biçimde, gahta renksiz nakışlar

Ezgisini dinletir yaşama solosunda

Yine de son şiirini bir ahenğe bağışlar', 'Gerçeği hayal eder engeller çemberinde Hayali gerçek eder sınırsız uçurumda İçini açmak ister adalet minberinde Sessizliğe dayanmaz haykırır...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hece Sarayı', 'hece-sarayi-husam-hasret-ahlk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok şeyleri bilmezdim seni tanıdığım an

Çehrende okuverdim gizemli tümceleri

Çözümsüz sırlarınla giriştim zaman zamn

Karşılıksız uğrunda harcadım geceleri

Umutlu kucağında besledim dilekleri

Uğraştım büyüsün ki müjde salsın dünyana

Doğanın şen gözünde paylaştım gerçekleri

Saydam bir görünüşte geçit buldum hülyana

Bağışladım bir demet yasemen saçlarına

Sense bir avuç yıldız karanlığıma serptin

Aruz yüküyle koştum serbest yamaçlarına

İstediğim sarayı heceyle bana yaptın', 'Çok şeyleri bilmezdim seni tanıdığım an Çehrende okuverdim gizemli tümceleri Çözümsüz sırlarınla giriştim zaman zamn Karşılıksız uğrunda har...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hece-sarayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda..', 'elveda-bahri-kayaoglu-1gjxr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öpüp kokladığım saçlarına elveda

Elveda gözlerinin rengine...

Yeni bir güne

Yeni bir umuda

Seninle başlayan her şeye,

Elveda...', 'Öpüp kokladığım saçlarına elveda Elveda gözlerinin rengine... Yeni bir güne Yeni bir umuda Seninle başlayan her şeye, Elveda......', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/elveda-207-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zihnimin En Berrak Anına', 'zihnimin-en-berrak-anina-ufuk-nazim-lnxuf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkular nedendirki? 

Acep sende yırtılırmısın? 

Diğerleri gibi.

İçimde büyüttüm seni

Kelimeleri harmanlayıp

Kalıplara vurdum

Düşlerimi sana kattım.

Sen zihnimin

En berrak anısın.

Göçeceksin sende

En güzel anında

Takılıp kanadına

Bir şiirin.

Kendini pazarlayacaksın

Vitrinlerde

Şekillere gireceksin.

Adlar takacaklar sana

Vesikalı bir orospu gibi

Kalacaksın 

Köşelerinde şehrin.

                      27.01.2006', 'Korkular nedendirki?  Acep sende yırtılırmısın?  Diğerleri gibi. İçimde büyüttüm seni Kelimeleri harmanlayıp Kalıplara vurdum Düşlerimi sana...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zihnimin-en-berrak-anina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl seveyim kaynana seni?', 'nasil-seveyim-kaynana-seni-zernisan-aydogan-676y7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün yüzü göstermedin her gün ağlattın

Zehir dolu sözlerinle ne canlar yaktın

Sonunda bir haneyi daha kapattın

Nasıl seveyim kaynana seni? 

Oturduğun yerden senaryo yazdın

Yazdığın senaryoyu kendin oynadın

Kına yak ellerine emeline ulaştın

Nasıl seveyim kaynana seni? 

Bir gün can deyip yüzüme gülmedin

Ana gibi oturup derdimi mi dinledin

Sevgiyi saygıyı sen hiç bilmedin

Nasıl seveyim kaynana seni? 

Yüreğinde  nefret sanki taht kurmuş

Merhametin şefkatin zerresi yokmuş

Senin için iyi yok herkes kötü doğmuş

Nasıl seveyim kaynana seni? 

Korkar oldum ben senin şerrinden

Kızdınmı beddua düşmez dilinden

Kul hakkı nedir bilmezmisin sen

Nasıl seveyim kaynana seni? 

Ne günler yaşattın susuz uykusuz

Hesabını vereceksin bir gün kuşkusuz

Kırdın kolumu kanadımı bıraktın çaresiz

Nasıl seveyim kaynana seni? 

Söylediklerini yazsam bir bir kalemle

Ne defter yeter nede kelime

Gönlüm kırık ne söylesem nafile

Nasıl seveyim kaynana seni? 

Kötü tohum ektin şu yüreğime

Hasat zamanı geldi biçiyorum işte

Sonunda çıkardın ya beni de dile

Nasıl seveyim kaynana seni? 

                               Erzurum / zernişan Aydoğan', 'Gün yüzü göstermedin her gün ağlattın Zehir dolu sözlerinle ne canlar yaktın Sonunda bir haneyi daha kapattın Nasıl seveyim kaynana seni?  O...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nasil-seveyim-kaynana-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulu Türkmenim', 'ulu-turkmenim-husam-hasret-7n08o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmemiş hala yaşıyorum ben

Çelik irade taşıyorum ben

Üst üste engel aşıyorum ben

Bu benim, bu da yolumdur benim

Hakkımdan geçmem, gitse de canım

Güneş görmeyen dereden akmam

Kara dağ üste şimşek dek çakmam

Millet yolundan dışarı çıkmam

Bu benim, bu da yolumdur benim

Bu yolda ancak yükselir şanım

Horyatla gürler od püskürürüm

Türk benliğimi canla korurum

Ereğe giden yolda yürürüm

Bu benim, bu da yolumdur benim

Başı dik duran ulu Türkmenim', 'Bitmemiş hala yaşıyorum ben Çelik irade taşıyorum ben Üst üste engel aşıyorum ben Bu benim, bu da yolumdur benim Hakkımdan geçmem, gitse de ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ulu-turkmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşiş Suyu', 'kesis-suyu-ali-arslan-rxzr2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '/Makine Yüksek Mühendisi İbrahim Tuğsuz''a adanmıştır./

Keşiş haziranda yağmura doyar. 

Suyuyla kokusu akar gelir Geben dağlarının, 

Çokak yaylasının.

Apak bedeniyle, 

her damlasıyla alır gider 

bir dağ kızının kabaran hayallerini.

Kayalıklara her vuruşunda ne seller olur.

Gözyaşlarının her yağışında 

yürekler çarpar çarpar, 

akıl öyle bir korkar.

Ah keşiş, 

biriktirdiğin katman katman balçığınla,

ne inançları kaç kez yıkadın. 

Azgın sularınla 

doldurup götürürken bir geçmişi;

önünde, 

nice hayatlar kucaklanıp ötelendi. 

Nice aşklar yıkandı 

kan kızıl suyunda senin,

bereket saçarken yazgısına şimdi Çukurova’nın.

Ah keşiş, 

karnından yararken 

biz senin önünde; 

dimdik 

ant içmedik mi her seferinde inatla, 

seni durdurmaya? 

Kan kırmızı suyunu yükseltip,

gelinlik bir kız gibi 

seni,

beton elbiselerle

yeşiline katmak için Andırın dağlarının.

Bir gülümse, 

bir soluklan istedik.

Sen sakinleşirken, 

suyunun dibinden biz

binlerce ışığı hayata akıtacağız;

kucaklaşsın diye

gökyüzünde geceleri yıldızlarla.

Ay senin göl olan koynuna saklanacak. 

Kargılık köyünde, 

bir köylü kızının

gözbebeklerinin her bir yeşiline yansıtacağız aşkı.

Ah keşiş, 

bir gün seni 

sıcak, 

nem 

ve toz içinde bin bir emekle,

kulaklarından bükerken, 

biz de gülümseyeceğiz 

mutlaka 

bir gün senin önünde.', '/Makine Yüksek Mühendisi İbrahim Tuğsuz''a adanmıştır./ Keşiş haziranda yağmura doyar.  Suyuyla kokusu akar gelir Geben dağlarının,  Çokak ya...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kesis-suyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savrun', 'savrun-ali-arslan-mda4l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kışın bahara dönüşen yüzünde 

Ay karlarla,

karlarla 

kalkar düşer iner.

Savrulur Savrun,

dik yamaçlarından 

akan sularla 

kayaların oyuklarında

saklanır.

Maviye çalan mor renginde,

gülümseyen nehir çiçekleriyle akar gider kendi yüreğiyle.

Uykuya hasret yatağına,

ağlar 

cümle bedenini dolayarak.

Ay karlarla üşür,

karlarla kalkar düşer iner.

Savrun’a yaşlı bir çamdan kopan,

çürümüş kökler karışır gider.

Kösepınarın’da hüzün neden geceleri 

hep böyle dibe çöker? 

Kışın bahara dönüşen yüzünde 

Savrun karlarla,

karlarla kalkar düşer iner,

akar gider bir hayat Çukurova’ya.', 'Kışın bahara dönüşen yüzünde  Ay karlarla, karlarla  kalkar düşer iner. Savrulur Savrun, dik yamaçlarından  akan sularla  kayaların oyukları...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/savrun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Yaşamak', 'yasamak-i-smail-hakki-kavurmaci-lo1a5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'rüyada yaşar gibi

bir halin var arkadaş

dalgın, şaşkın ve suskunsun

rüya, rüya değil yaşamak.

yaşamak, koşmak, coşmak,

var olmak için, yaşamak için

yaşatmak için savaşmaktır yaşamak.

durma, susma, uyuma

uyan, haykır, koş

yeni ufuklara

yeni umutlara

koş, koş, kooş.

nedir üzerine çöken

bu uyuşukluk! 

ezilenlerin ahlarını, 

sömürenlerin kahkahalarını,

isyan edenlerin imdatlarını

ve vurdumduymazların suskunluklarını

duymazmısın.

bir bak,

güneşe, aya, yıldızlara

herkes tamtekmil görevinin başında.

sende uyan ne olur, bir sorumluluk sırtlan

kafa tut gerekirse, güneşe de, yıldızlara da,

aya da.

yaşam nedir ki! 

ezme, ezilme

sömürme, sömürülme

durma, boşverme

başkaldır sende

sırtından geçinene

hakkını vermeyene

seni sana ezdirene.', 'rüyada yaşar gibi bir halin var arkadaş dalgın, şaşkın ve suskunsun rüya, rüya değil yaşamak. yaşamak, koşmak, coşmak, var olmak için, yaşam...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yasamak-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bugün Yahut Dünkü Yarın', 'bugun-yahut-dunku-yarin-mehme-arslan-90os9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'liseli güzel kızların eteklerinin ucu

diz kapaklarına ne kadar yakınsa

o kadar yakınım sana

ve uzağım ''resim sevinci'' saçlarımın

uzunluğu kadar avuçlarına

içimdeki çocuk ha dese gelirim

bilirsin çocuk sözü dinlerim ben

handiyse hep o çocuğun sözüyle

hareket ettim seninleyken

şimdi çok katlı binaların hızlı asansörlerinin

iki kat arasını katettiği süre kadar

düşünüyorum seni

ve yetiyor doğrusu

günü kotarıyorum en azından

yarını düşünmüyorum hiç

o epey zaman önceydi

03/03/2006', 'liseli güzel kızların eteklerinin ucu diz kapaklarına ne kadar yakınsa o kadar yakınım sana ve uzağım ''resim sevinci'' saçlarımın uzunluğu ka...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-yahut-dunku-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünün Rengini Unuttum', 'gokyuzunun-rengini-unuttum-yusuf-onder-bahceci-n08vd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittin,gökyüzünün rengini unuttum,

Sen gittin denizlerimin rengini unuttum,

Sen gittin, hâyalleri mi hepten unuttum,

Sen gittin,gökyüzünün rengini unuttum.

Şimdi soruyorum ben gökyüzü ne renk,

Senden ayrı kaldım, kimler bana denk,

Sorarım, gökkuşağın da kaç tane renk,

Sen gittin,gökyüzünün rengini unuttum.

Sen giderken gökyüzü siyaha boyandı,

Benim sabrım kalmadı, sınıra dayandı,

Benim bu hâlim sadece Allah''a ayandı,

Sen giderken gökyüzü siyaha boyandı.

Gözlerime gülerken, gökyüzü maviydi,

Gözlerime gülerken Dünya pembeydi,

Bırakıp gittiğin anda, bir kurşun deydi,

Sen giderken gökyüzü siyaha boyandı.', 'Sen gittin,gökyüzünün rengini unuttum, Sen gittin denizlerimin rengini unuttum, Sen gittin, hâyalleri mi hepten unuttum, Sen gittin,gökyüzün...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gokyuzunun-rengini-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatmayan bilmez', 'tatmayan-bilmez-ali-riza-unal-pi4n4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıktığım tur dağında şimdi viraneler gördüm,

Baktığın gül bağında şimdi gülzâreler gördüm,

Bir başına ne harabat boştu bu gönül,

Aktığın bu sinede şimdi hicrâneler gördüm,

Sen alî cênâpsın lütfûnda kerameler gördüm,

Aşkın bahrına düşmüş,viraneler gördüm,

Düşte gör ey Rıza sende bu aşk-ı giryâne,

Hazinede dem be dem, divaneler gördüm..', 'Çıktığım tur dağında şimdi viraneler gördüm, Baktığın gül bağında şimdi gülzâreler gördüm, Bir başına ne harabat boştu bu gönül, Aktığın bu ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tatmayan-bilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-sacide-yaylaz-p0vsk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel

Gel artık

Sevgili gel

Gel ışığım ol

Karanlık geceme

Günüme güneşim ol

Baharım ol sevgili gel

Sevgiden yoksun yüreğime

Sevgiyle sarmak için gel

Umutlarıma umut ol

Seni özledim gel

Türkülerim ol

Düşüme gel

Sevgili gel

Gel artık

Gel', 'Gel Gel artık Sevgili gel Gel ışığım ol Karanlık geceme Günüme güneşim ol Baharım ol sevgili gel Sevgiden yoksun yüreğime Sevgiyle sarmak iç...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-280-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık-Yokluk', 'varlik-yokluk-bahri-kayaoglu-cjfcc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıplak olduğun için sana gülerler çocuk

Çıplak olduğun için sana gülerler...

Kendi çıplaklıklarından habersiz.

Sen yokluktan giyinemezsin çocuk

Sen yokluktan giyinemezsin...

Onlar varlıktan.', 'Çıplak olduğun için sana gülerler çocuk Çıplak olduğun için sana gülerler... Kendi çıplaklıklarından habersiz. Sen yokluktan giyinemezsin ço...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/varlik-yokluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-ufuk-nazim-qua2w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki tramvay arası

Kısacık anlar vardır

Anlık belleğe takılan

Hani gözlerde hüzünse hüzün

Yada mutlak bir mutluluk.

Tramvaydan inerken

Sağanaktan kaçan

Telaşlı iki göz

Ve sendeki 

Sağanak telaşı.

Esaslı bir sağanakta 

Ağırlaşan geçmişin tortusudur

Gözlerindeki durağanlık

Ve sonsuzdan 

Daha düşmemiş olan yağmur damlası.

Kapısından girerken

Bir dil kursunun 

Dilin ağırlığı kadar

Heyecanlı tatlı 

Ve tedirgindir gözlerin.

Ve öğretmen farkındadır

Sırılsıklam olusşunun

Yüzünde artan çizgilerin

Gözlerindeki sıfırdan başlayan

Hırçın ivmenin.

Farklı ırklar

Kaynaşmalar tanışmalar

Devingen dalgalar gibi 

Kaygılı gözlerin

Boşlukta dolanışı.

Ve gördün gözlerindeki telaşı

Globallesşen dünyada

Dağılmamak icin

Saklanıyor globalizm denilen

Bu emperyalist başlık.

Gözlerdeki yalan

Satılmış beyaz adama 

Gözlerdeki ışık.

Sistemli bal dağıtışları

Ve ballı parmakların yalanışları.

                              25.01.2006', 'İki tramvay arası Kısacık anlar vardır Anlık belleğe takılan Hani gözlerde hüzünse hüzün Yada mutlak bir mutluluk. Tramvaydan inerken Sağana...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gozler-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sulara Koşuyoruz', 'sulara-kosuyoruz-ali-arslan-amafx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimiz bahardır bu sabah.

Yollardayız.

Koşuyoruz.

Kıpırdamaya başlamış dolu

dolu yüreği burnunda, 

coşuyor Anadolu.

Dolarak, 

güller çiçeklerle. 

Ülkeme ne baharlar gelmiş! 

Boydan boya Çukurova; 

buğdayla, 

pamukla tohuma durup, 

bereketle donanan yeşillenmiş bir hayat!

Rengarenk baharla, 

koşuyoruz dörtnala! 

“Trink truk trak…makinalaşarak” modern atlarımızla 

su’ lara koşuyoruz.

Su’ lara volanlar, 

bentler, 

kollar vurmaya.

Su’ ları biriktirerek,

Su’ları zapt ederek, 

“Trink truk trak…makinalaşarak”

ülkemi aydınlatmaya.

Koşuyoruz.

./..

Doluyuz! 

Dolu bizim yüreğimiz.

Bugün su’ lara 

fısıldayarak kulaklarına, 

kurak yazgılarını çevirmek için 

ülkemin pırıltılı yarınlarına. 

Koşuyoruz.

Yüreğimiz bahardır bizim.

Dolarak, 

güller çiçeklerle. 

Ülkeme ne baharlar gelmiş!

Merhaba hayat; 

sana, 

çalışanlarına, 

emeğini, 

terini su’ lar için akıtanlara.

Su’ ları güç yaparak kollarında 

kadınlarımıza, 

çocuklarımıza, 

aydınlık baharlar doğuranlara.

Ve ey koca tabiat ana 

merhaba!

Sana.', 'Yüreğimiz bahardır bu sabah. Yollardayız. Koşuyoruz. Kıpırdamaya başlamış dolu dolu yüreği burnunda,  coşuyor Anadolu. Dolarak,  güller çiçe...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sulara-kosuyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıklar Gibi', 'baliklar-gibi-yusuf-onder-bahceci-5z5c9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ne insanlar tanıdım, balıklar gibi,

Ağı atıp serpsen toplarsın alıklar gibi,

Kendini zannederler gözüaçıklar gibi,

Ben ne insanlar tanıdım, balıklar gibi.

Allah, Peygamber der de, yan çizer,

Ufak bir menfaat olsa, yarı yay çizer,

Anlamasa bile, Dünya Haritası çizer,

Ben ne insanlar tanıdım, balıklar gibi.

Torik Balığı gibidir, hep tora geliyor,

Hamsi Balığı gibi de, çok küçülüyor,

Bir bakarsın Köpekbalığı görünüyor,

Ben ne insanlar tanıdım, balıklar gibi.

Yayın balıkları gibi yayılır da gezerler,

Mürekkep Balığı, mürekkep üretirler,

Plankton koymazlar, yer de bitirirler,

Ben ne insanlar tanıdım, balıklar gibi.

Gerçek Alabalık kıymetli ele gelir mi,

Sazan balığı çok kılçıklı nasıl yenir mi,

Kaypak olanlara balık gibi denilir mi,

Ben ne insanlar tanıdım, balıklar gibi.', 'Ben ne insanlar tanıdım, balıklar gibi, Ağı atıp serpsen toplarsın alıklar gibi, Kendini zannederler gözüaçıklar gibi, Ben ne insanlar tanıd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baliklar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Yorumu', 'sevginin-yorumu-asude-gediz-i4agu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi bir fidandır 

tohumu hümanizm olan.

Bir  ilaçdır 

en ölümcül hastalıklara bile şifa veren

Doğayı, renkleri, anını sever

yüreğinde sevgi olan.

En önemlisi kendini seven 

ışık saçar karanlığı 

aydınlatan 

sevgiyi izleyerek yol alan 

aldığı nefesi, birikimlerini 

sevgi potasında yoğurabilen

topluma ve kendine yararlı olandır.

Edinilen kültür bağlamında şekillenir sevgi

ortaya çıkan ise bir tarz, yaşam felsefesi

yaşamı yorumlamaktır.

Dindar  olanlar,  saptıranlar

sevap günah bazında  yorumlayanlar

tüccar  olup da ticari bağlamda 

yorumlayanlar olabilir.

Oysa; 

Sevgi 

Tanrının insanlara bağışlamış olduğu 

eşsiz bir güçdür

ne günahdır 

ne sevap

ne de maddeye giden bir yol

Bu duyguyu yaşamak onur

hissedebilmek gurur

Bu anlamda dudaktan 

fırlayanlar da  edepdir

…', 'Sevgi bir fidandır  tohumu hümanizm olan. Bir  ilaçdır  en ölümcül hastalıklara bile şifa veren Doğayı, renkleri, anını sever yüreğinde sevg...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevginin-yorumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Bir Şeyler Eksik 03-03-2006 14:25', 'hep-bir-seyler-eksik-03-03-2006-14-25-ahmet-unal-cam-u3eab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep bir şeyler eksik

...hep eksik

Gülüşlerimin arkasında hüzün var

Sanki, son umutları saklıyor ufuklar

Birazdan dörtnala çıkacak

...dörtnala...dörtnala

''unuttum'' sandığım sevdalarla atlılar...

ve..gönlümdeki kışlar yıkılacak

Yer gök bahar...

     ...yer gök bahar olacak

Biliyorum...

...bekliyorum

İçimde kırıntı kırıntı mazi

kucağımda kolu-kanadı kırık ati,

saçlarımda ak,

 gözlerimde sonbahar

Bu bekleyiş bitsin artık,

 bitsin  bekliyorum,

biliyorum...

 eksik bir şeyler var....



03-03-2006  14:25  Kalaba/Ankara

Ahmet Ünal ÇAM', 'Hep bir şeyler eksik ...hep eksik Gülüşlerimin arkasında hüzün var Sanki, son umutları saklıyor ufuklar Birazdan dörtnala çıkacak ...dörtnal...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hep-bir-seyler-eksik-03-03-2006-14-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecede Kalan Kız', 'gecede-kalan-kiz-figen-aydogmus-l8qul', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir geceye düştüm

Çıkışı  olmayan 

Yıllar yılı aynı boynu bükük küçük kızım

Gelenler bulamaz beni gidenler tekrar gelmez

Kül kedisiyim papuçlarım o geceden beri saklı

Adımı söylemez kimse

Bilmez içimdeki acıyı

Yırtıcı tiz ses üvey annemin çığlığı.

Beklemeyeceğim artık kimseyi

Gelen gelsin geceme

Bana ışığı sunacak kişiye

Gülümseyeceğim sadece', 'Bir geceye düştüm Çıkışı  olmayan  Yıllar yılı aynı boynu bükük küçük kızım Gelenler bulamaz beni gidenler tekrar gelmez Kül kedisiyim papuç...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecede-kalan-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüm', 'ay-yuzlum-asaf-sayil-t9ozj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni ilk gördüğümde; 

Terim soğudu ama,

Gözlerindeki Işıltı; 

Beni ısıttı ay yüzlüm... 

Beni hayata bağladın,

Yolumu aydınlattın,

Bir an bile aklımdan çıkmadın,

Hayatım, ay yüzlüm.', 'Seni ilk gördüğümde;  Terim soğudu ama, Gözlerindeki Işıltı;  Beni ısıttı ay yüzlüm...  Beni hayata bağladın, Yolumu aydınlattın, Bir an bil...', ARRAY['Türk Edebiyatı','Şiir','Asaf Sayıl']::text[], 8.5, '{"poet":"Asaf Sayıl","poet_slug":"asaf-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ay-yuzlum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandım yar diye diye', 'yandim-yar-diye-diye-ali-riza-unal-o7cgn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey sevgili sen aişkârsın ben ise gayb,

Bu ne hayret bu ne gönüle hitap nigâhtır

Sensiz her fiilim namazım, amelim bin ayb,

Sen ile her macâzım,bir hikmeti mübahtır.

Açtım elleri eydoost yandım,yar diye diye,

Garip düştü haller kandım yar diye diye,

Bilirim gayrın yok,her şey hemo host,

Sensin bu can bu post,yandım yar diye diye..', 'Ey sevgili sen aişkârsın ben ise gayb, Bu ne hayret bu ne gönüle hitap nigâhtır Sensiz her fiilim namazım, amelim bin ayb, Sen ile her macâz...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yandim-yar-diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-mahmut-ulusoy-dp1gw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hesap kitap kurulacak divanda

İllah sorulacak suçu dünyanın

Gelen gitti erilmiyor menzile

Öyle çok uzundur ucu dünyanın

Halil İbrahim’i ateşte yaktın

Belkise tuylardan saraylar yaptın

Yusuf’u Mısır’da kul köle sattın

Kolay kolay durmaz öcü dünyanın

Yatmış uykusuna daha ayılmaz

Yolları yok hiçbir yana ayrılmaz

Zengin fakir hiç kimseyi ayırmaz

Hele azalmamış gücü dünyanın

Biçare MESULİ kendi halında

Kara toprak saracaktır dalında

Sanki yatar  anasının yanında

Durmaz gider her gün göçü dünyanın', 'Hesap kitap kurulacak divanda İllah sorulacak suçu dünyanın Gelen gitti erilmiyor menzile Öyle çok uzundur ucu dünyanın Halil İbrahim’i ateş...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar Adam', 'i-htiyar-adam-mahmut-ulusoy-wniwx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi kimsesi yok kalmış sokakta

Bu kimin babası ihtiyar adam

Bırakmadı yuvasına gitmeye

Bu kimin babası ihtiyar adam

Ne kadar söyledi anlayamadım

Saç sakal karışmış tanıyamadım

Gözlerim dolmuştu ağlayamadım

Bu kimin babası ihtiyar adam

Gücü kalmamıştı adım atmaya

Vermediki ellerini tutmaya

Felek koymadı ki suyu yutmaya

Bu kimin babası ihtiyar adam

MESULİ’yem bilmem acele niye

Aman vermedi ki sözünü diye

Bir lokma ekmeği koymadı yiye

Bu kimin babası ihtiyar adam', 'Kimi kimsesi yok kalmış sokakta Bu kimin babası ihtiyar adam Bırakmadı yuvasına gitmeye Bu kimin babası ihtiyar adam Ne kadar söyledi anlaya...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Ulusoy']::text[], 8.5, '{"poet":"Mahmut Ulusoy","poet_slug":"mahmut-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ihtiyar-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebat Et', 'sebat-et-volkan-i-ncel-m7apk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle 

Bir aybaşı daha geçsin

Alırım istediğin elbiseyi

Daha geçen ay söyledin bana

Ama olsun

Sebat et', 'Bekle  Bir aybaşı daha geçsin Alırım istediğin elbiseyi Daha geçen ay söyledin bana Ama olsun Sebat et...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sebat-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-volkan-i-ncel-iwqzn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dayak yemişsen 

Ne olmuş

Arkadaşından

Bak ben feleğin tokadını yemişim

Sesim çıkmaz', 'Bir dayak yemişsen  Ne olmuş Arkadaşından Bak ben feleğin tokadını yemişim Sesim çıkmaz...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oglum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesiniz? ? ?', 'neredesiniz-sebnem-ezik-stn74', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neredesiniz bebeklerim,

Bisikletim..

Kaldırım taşına yazdığım,

Tebeşirim…

Neredesiniz, kirazlı eteğim,

Beyaz kazağım…

Buğulanan camlara,

Adını yazdığım,

Çocukluğum…

Nerede, nerede

Ne olur söylesenize…

Anamın sıcak kucağı,

Umutlarım, hayallerim.

Baharı bekleyen, coşkularım..

Nerede, nerede

Ne olur söylesenize…

Hepsi kaybolup gitti mi? 

Zamanın içinde..

Yoksa, yoksa

Benmi,

  Çaldırdım kendimi,

      Merhamet etmeyen senelere…', 'Neredesiniz bebeklerim, Bisikletim.. Kaldırım taşına yazdığım, Tebeşirim… Neredesiniz, kirazlı eteğim, Beyaz kazağım… Buğulanan camlara, Adı...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neredesiniz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitimsi Sözler 12', 'beyitimsi-sozler-12-huseyin-avdic-xmv0v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ilâhî I$leyi$in Neticesi

Bo$ i$ yaptigini sanma sakin yüce Rabb''in.

Neticesidir hayat, Ilâhî i$leyi$in.

Berlin, Mart 2006.', 'Ilâhî I$leyi$in Neticesi Bo$ i$ yaptigini sanma sakin yüce Rabb''in. Neticesidir hayat, Ilâhî i$leyi$in. Berlin, Mart 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beyitimsi-sozler-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 81', 'guncel-beyitler-81-huseyin-avdic-rll3q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bölünmek Irak''in Kaderidir

Kuvvetli bir din ve millet kardesligi yok Irak''ta, Irak bölünecektir üce.

Bölünmek kaderidir Irak''in, haber vermistir bunu Son Elci asirlar önce.

Berlin, Mart 2006.', 'Bölünmek Irak''in Kaderidir Kuvvetli bir din ve millet kardesligi yok Irak''ta, Irak bölünecektir üce. Bölünmek kaderidir Irak''in, haber vermi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Parçam', 'gonul-parcam-asaf-sayil-jtf6c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gizli mabedim,

Deli gönlüm,

Sensizlikten,

Yanar durur.

Gülümsemenle,

Deli gönlümde,

Acı içinde,

Mutluluk olur...

Bir bakışınla,

Deli gönlümde,

Ünvanların en payesi,

Sürgit esaret olur...', 'Gizli mabedim, Deli gönlüm, Sensizlikten, Yanar durur. Gülümsemenle, Deli gönlümde, Acı içinde, Mutluluk olur... Bir bakışınla, Deli gönlümd...', ARRAY['Türk Edebiyatı','Şiir','Asaf Sayıl']::text[], 8.5, '{"poet":"Asaf Sayıl","poet_slug":"asaf-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-parcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi çare gönlümde bir sevda nar-ı var,', 'bi-care-gonlumde-bir-sevda-nar-i-var-ali-riza-unal-a3v6o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bi çare gönlümde bir sevda nar-ı var,

Kanayan hicrânede o gülün har-ı var,

Kapandı dideler periveş dilber-i yare,

Sineye hicap canda canın arı-ı var,

 ---   nakarat   ---

hekimler şakın bu hummalı zare,

lakin aşığa  cismi canın har-ı var,', 'Bi çare gönlümde bir sevda nar-ı var, Kanayan hicrânede o gülün har-ı var, Kapandı dideler periveş dilber-i yare, Sineye hicap canda canın a...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bi-care-gonlumde-bir-sevda-nar-i-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemer Sıkma', 'kemer-sikma-mehmet-ayhan-gunaydin-jvjz0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KEMER SIKMA

Ekonomiden anlamam,

Öyle pek de kafa yormam.

Hele şiir düşünmek varken,

Anlamadığımdan haz almam.

Ya atadan borçlu doğduğumdan,

Ve ya evlada da kalacağından.

Ya da sıka sıka kemeri,

Er belimi, dilber beli yaptığından.

Sevgili ablalar, ağabeyler; 

Ben ki, en fikr-i fakir,

Ben aranızda en cahil.

Şunu söyler şunu bilir.

Bu gidiş gidiş değil.

Eskiden fakir de olsak,

İnsan değerimizi hissederdik.

Karnımız açtı, velakin

Başımız dik, insanca gezerdik.

Şimdi kuruştan liraya doğru,

Bize değer verilir oldu.

Alınteri ile çalışan bizlerin,

Değeri de hep kuruş oldu.

Beynine değil cebine,

Onu da geçtim bir de,

Sıfatta TL değerine,

Bugün bakılır oldu.

Dün fakirdik bugün de öyleyiz, 

Dün diktik, bugün eğiğiz.

Şimdi durun, hele bir düşünün! 

Böyle ne kadar devam ederiz? 

‘Bu gidiş gidiş değil

Hayra alamet değil’! 

Kopacak! dikkat çok inceldik! ! 

Sıkılan sade bel de değil! ! ! 

M. Ayhan Günaydın.

      3 Mart 2006 

          Ankara', 'KEMER SIKMA Ekonomiden anlamam, Öyle pek de kafa yormam. Hele şiir düşünmek varken, Anlamadığımdan haz almam. Ya atadan borçlu doğduğumdan, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kemer-sikma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Sevdan Öldürür', 'seviyorum-sevdan-oldurur-yusuf-onder-bahceci-k9807', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum be güzelim sevdan beni öldürür,

Öldürmese bile, bir gün olur da, süründürür,

Derdin bana ram olmuş ne zaman güldürür,

Seviyorum be güzelim sevdan beni öldürür.

Senin için ne dualar eder, dilekler dilerdim,

Hey Allah''ım birleştir beraber  ölek,derdim,

Senin için, istihare yapıp, hâyaller ederdim,

Seviyorum be güzelim sevdan beni öldürür.

Hele ki şiirler var, şarkılar var, besteler var,

Hem bunlar olmasaydı nasıl olurdu duygular,

Sevdiğinden ayrılanlar  her gecede sayıklar,

Seviyorum be güzelim, sevdan beni öldürür.

Bir gün olur da, karşılaşırsam eğer tenhada,

Sakın, bana hiçbirşey söyleme, söyleme ha,

Çekip gittiğin günden beri, bekliyorum daha,

Seviyorum be güzelim, sevdan beni öldürür.', 'Seviyorum be güzelim sevdan beni öldürür, Öldürmese bile, bir gün olur da, süründürür, Derdin bana ram olmuş ne zaman güldürür, Seviyorum be...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-sevdan-oldurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gün Örtülüyor Üzerime', 'gun-ortuluyor-uzerime-yildiz-yildiz-oib7u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gün ışıyor... İhtimal geceye yeniden doğarım daa...! 

Çıplak omuzlarına, gül kurusu tülden bir şal alır 

seher yelinden ürperir de gece

Gün sızar o saatlerde en ücra hücrelerime

Uzat elini...

      Alnıma koy...

                   Usulca indir göz kapaklarımı elinle

Vedalaş...! Ve

Ört aydınlığı yüzüme

Yaşamdan kayan son yıldız olabilirim

Acele et...! birşey dile', 'gün ışıyor... İhtimal geceye yeniden doğarım daa...!  Çıplak omuzlarına, gül kurusu tülden bir şal alır  seher yelinden ürperir de gece Gün ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gun-ortuluyor-uzerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalı Bir Çare', 'olmali-bir-care-halil-yilmaz-dqjmk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmalı bir çare bize de beyler,

Buzul eteğinde bahar bekleriz. 

Üç vekil gönderdik işte emekler,

Alın teri ile sabır çekeriz… 

Kabineden önce, yerel teşkilat…

Hizmet üretmemiş sürer saltanat,

Tüysüz yarasalar takmışlar kanat,

Turnalar(!)   gördükçe kahır çekeriz…

Değil dibe doğru, güne çırpındık.

Hizmet meydanında, önde göründük.

Gölgelere değil, Hakka sığındık.

Kuklalar revaçta hatır biçeriz…

Varsa projesi makamda olan, 

Bizler yalancıyız bu sözler yalan.

Mademki bilinir kurt olmaz çoban,

Sürüyü güdecek Tahir bekleriz… 

Teşkilattan eser varoş zengini, 

Tilki dolaşmış bulmuş dengini,

Çıldırıp da Ağrı aldan rengini,

Göstermeden acil neşter isteriz…

                     Ocak 2005', 'Olmalı bir çare bize de beyler, Buzul eteğinde bahar bekleriz.  Üç vekil gönderdik işte emekler, Alın teri ile sabır çekeriz…  Kabineden önc...', ARRAY['Türk Edebiyatı','Şiir','Halil Yılmaz']::text[], 8.5, '{"poet":"Halil Yılmaz","poet_slug":"halil-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmali-bir-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadersiz Kullar', 'kadersiz-kullar-tahmine-yildirim-haesq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsyan etmek geliyor içimden bu şansız kadere

vuruyor sanki bizi hergün yerlerden yerlere

düşmüşüz işte,gurbet denen bu illet yere

bu gurbettede,dolu galiba bizim gibi kadersiz kullar

Allaha şükür paradan yana hiç yoktur sıkıntımız

monoton hayattandır bizim tek şikayetimiz

bazan sanki hiç düşünmüyor beynimiz

kalplerininde isyanına uğrayacak bir gün bu kadersiz kullar

Anlamadımki neydi sanki bizim suçumuz

tek suçumuz,neden sanki kara olmuş bahtımız

zalim almanya sanadır hep bu kahrımız

tümden kahır olmadan,kurtulsa keşke bu kadersiz kullar

Gurbet almış bizi sımsıkı kucağına

birer tanede incir dikmiş ocağımıza

kiminide hepten hasret koymuş çoluk çocuğuna

bu gidişle buralarda yazılacak mezar taşımıza kadersiz kullar

                                                                               EYLÜL:1993', 'İsyan etmek geliyor içimden bu şansız kadere vuruyor sanki bizi hergün yerlerden yerlere düşmüşüz işte,gurbet denen bu illet yere bu gurbett...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kadersiz-kullar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgi roman kahramanları', 'cizgi-roman-kahramanlari-nevzat-ozkan-nr3qg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'vardiya nöbetçisi gibi

geceleri başucumda bekleyip

beni kötülüklerden koruyan,

rüyalarımda yalnız bırakmayıp

maceradan maceraya koşturan,

sırdaşlarım,

çizgi roman arkadaşlarım.

çelik bilek Teksas,profesör Oklitus

dikkat Mandrake geliyor,hokus pokus

şimdi de karşınızda yandaşları

avukat Koloni ve yakın arkadaşım Rodi,

sıra sizde haydi,

yüzbaşı Tommiks,konyakçı,doktor

binbirsurat ve albayın kızı Suzi.

bıkılır mı senden

bacaksız gazeteci Tenten,

Turnusol,kaptan

Dupond kardeşler,ellerinde baston.

şirin ve akıllı köpek Boncuk,

Red Kit,Düldül,

aptal köpek Rin tin tin,

baltalı ilah Zagor,obur Çiko

kaptan Swing,gamlı baykuş

komşu çocukla yapılan değiş tokuş

sonrası  tanışılan

Süpermen,Teks Viller,Kit Karson

Otsukarcının oğlu Kaan

en sadığı Altaydan gelen yiğit

gözüpek çapkın Karaoğlan,

Baybora,Bayırgülü,Balaban

sessizce çekip gittiniz dünyamdan.

yıllar ne çabuk geçti

ne çabuk büyüttünüz beni.', 'vardiya nöbetçisi gibi geceleri başucumda bekleyip beni kötülüklerden koruyan, rüyalarımda yalnız bırakmayıp maceradan maceraya koşturan, sı...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cizgi-roman-kahramanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kelime', 'i-ki-kelime-figen-aydogmus-z1xon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dostluğuna ihtiyacım var

kuru bir yaprak gibi nefesim

hıçkırıklardan boğulurken 

bir sana

birde varlığına özlem çekerim

seni ister

nokta koyamadığım kelimelerin kalabalıklığı

seni özler iki göz

göz yaşlarımı silemem

taze değil ki gözümün altında ki morluklar

avucumun boşluğunda rüzgarlar volta atar

ellerim ellerinden uzak

kırık bir ayna gibi parçalar hasretin kalbimi

sana  ulaşamayan iki sözcük 

boğazıma takılı beklemekte

gelsen yanıma

sözcükler firar edecek

bütünü yaşatacak bana mavilik

yokluğun isimsiz bir cenaze

tabutu taşıyansa o iki kelime

dirilişinle çığlık atacak', 'dostluğuna ihtiyacım var kuru bir yaprak gibi nefesim hıçkırıklardan boğulurken  bir sana birde varlığına özlem çekerim seni ister nokta koy...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iki-kelime-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hiç Uğruına', 'bir-hic-ugruina-sevilay-celik-ojkvc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar düşmüştü eteklerime yığılasıya,

Buz bağlamıştı vücudum baştan başa,

Tek sıcaklık kalbimin ortasında

Onu bari söndürme bir hiç uğruna

Yağmurlar yağıyordu karanlık sokaklara,

Sel olup gitmişti kuru gül yaprakları ya,

Tek geride kalan sevgindi bende

Onu bari sürükleme bir hiç uğruna..', 'Kar düşmüştü eteklerime yığılasıya, Buz bağlamıştı vücudum baştan başa, Tek sıcaklık kalbimin ortasında Onu bari söndürme bir hiç uğruna Yağ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Çelik']::text[], 8.5, '{"poet":"Sevilay Çelik","poet_slug":"sevilay-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-hic-ugruina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum Böyle Sensizliklerde', 'usuyorum-boyle-sensizliklerde-sebnem-ezik-538oj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üşüyorum böyle sensizliklerde

Kanatsız süzülüyorum bilmem ki nereye

Anılar bomboş mavi odalarda

Gülüşlerin örmüş duvarları

Bakışların var pencerelerde

Ayak seslerin merdiven taşında

Kokunsa yastıkta

Sense kaybolmuşsun sisli zamanlarda

Her giden gibi

Hatıralar bırakmış yerini özlem yasına

Gecenin bilmem kaçı

Bu kaçıncı nöbet yangını yüreğimde

Sessiz ağlayışlarım bomboş yollarda

Üşüyorum böyle sensizliklerde

Kanatsız süzülüyorum bilmem ki nereye

Kah yağmur damlasında

Kah rüzgarın uğultusunda

Bir gelebilsem yanına

Fısıldasam kulağına

Canıma can kardeş buda geçermi diye? 

Sen üzülme kara yazımın üstüne çekerim perde

Zaman geçer  buda biter

Ah birde hasret olmasa

Birgün geleceğini bilmek

Canıma can kardeş 

Ölümüne beklemek beklemek beklemek

SONBAHARDA......

                                                Şu an uzaklarda vatani görevini                    

                                                yapan kardeşime    SENİ ÇOK ÖZLEDİM', 'Üşüyorum böyle sensizliklerde Kanatsız süzülüyorum bilmem ki nereye Anılar bomboş mavi odalarda Gülüşlerin örmüş duvarları Bakışların var pe...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/usuyorum-boyle-sensizliklerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Duygusalım Duygusal', 'seviyorum-duygusalim-duygusal-yusuf-onder-bahceci-oigpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum, bekliyorum duygusalım, duygusal,

Benim duygularım engin denizlerde sanki sal,

Anladık gelmeyeceksin de, bari bir haber sal,

Seviyorum, bekliyorum duygusalım, duygusal.

Benim duygularım engin denizlerde sanki sal,

Dalgalarla yol alır, fırtınalarla yön bulur o  visal,

Ben seni sevmiyorum diyebilirmiyim ki  misal,

Seviyorum, bekliyorum duygusalım, duygusal.

Ayrıldım, kendimi kaptırdım kaderin rüzgarına,

Bilki, nereden eserse rüzgâr, giderim o yana,

İnan ki nasıl da yaralıyım seni sevmeden yana,

Seviyorum, bekliyorum duygusalım, duygusal.

Eğer o beni sevmiyorsa bana söylemesinler,

Kardeşim, o seni hiç sevmemiş, demesinler,

Ne olur, bana hep yalan söylesin, söylesinler,

Seviyorum, bekliyorum duygusalım, duygusal.', 'Seviyorum, bekliyorum duygusalım, duygusal, Benim duygularım engin denizlerde sanki sal, Anladık gelmeyeceksin de, bari bir haber sal, Seviy...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-duygusalim-duygusal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harput''tan Gelen Çığlık', 'harput-tan-gelen-ciglik-mehmet-sukru-bas-di7ko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakup Ağa bütün bir kış evinden çıkamamış, evinin penceresinde kış boyu yağan karı, o kar tanelerinde esareti, acıyı, açlığı, öldürücü soğuğu bütün benliği ile yaşar olmuştu.

           Askerliğini yedi senede bitirmiş ve bu yedi sene içerisinde Sarıkamış''ta 

'' O Geceyi'' yaşamış, yurdun dört bir yanından gelen, Harputlusu, Samsunlusu, Anteplisi, Mersinlisi İzmirlisi, Vanlısı hepsi birer ana kuzusu olan doksan bin silah arkadaşının, acımasız ve öldürücü soğuğa dayanamayarak donmak suretiyle şehit olduklarına şahit olmuştu.

           Bu şehitler arasında birisi vardı ki ömrü boyu onu unutamamış, her zaman, her yerde rahmet ve hasretle anmıştı. Bu şehit, Harputlu Mehmet Çavuş''tan başkası değildi. Yakup Ağa ile Mehmet Çavuş Sarıkamış''ta yazlık bir çadırda yazlık elbiseler içerisinde, ayaklarında çarık, arkalarında yazlık bir kaput, ellerine zar zor geçirdikleri birer battaniye ile biri birlerine sarılarak o amansız, o çetin, o öldürücü soğuğa birlikte göğüs germişlerdi.

           Harputlu Mehmet Çavuş her gece gökyüzündeki ''Yedi Kardeşler'' yıldız kümesine hasretle bakar, Harput''taki yavuklusunun da o yıldız kümesine baktığından emin olarak o yıldızlar aracılığı ile ona sevgisini, sevdasını gönderirdi.

           Yakup Ağa evli ve bir çocuk babasıydı. Mehmet Çavuş ise askerliğinden önce birileri istemesin diye sevdiği kızla nişanlanmış, askere gittiğinde yavuklusu ile her gece bu yıldız kümesine birlikte bakıp öylece birbirlerini görecek inancını taşır olmuşlardı. Askere gittiği gün yavuklusu, Mehmet Çavuş''a ''Seni ömür boyu bekleyeceğim.'' sözünü vermiş; Mehmet Çavuş da gönül rahatlığı ile vatan hizmetine koşmuştu.

           Harput''tan Erzurum''a, oradan da Sarıkamış''a birlikte gelmişlerdi.

           Sarıkamış Ovasında kuzeyde Allahüekber Dağı, güneyde adı gibi üzerlerindeki metrelerce karlar birer buz tabakası haline dönüşmüş Dumanlı Dağ, uzaktan bakanlar için dağla gökyüzün birleştiği nokta görünümünü veriyordu.

           Önlerinde Rus askerleri, arkalarında Ermeniler vardı. Bu Ermeniler ki yıllarca Osmanlı''nın bütün nimetlerinden faydalanmış; ancak ''Bugün için Osmanlı''nın düşmanı, bizim dostumuzdur.'' düsturu içerisinde Ruslarla birlik olmuşlardı.

           Bütün bunları göz önüne getirdiğimizde en büyük, en korkunç düşman soğuktu. Ve öyle de oldu.''O Gece'' Osmanlı''nın artık dayanacak gücü kalmamış, bu korkunç ve öldürücü soğuk karşısında bedenler dayanma gücünü teker teker yitirir olmuşlardı. Osmanlı açtı, Osmanlı çıplaktı ve Osmanlı perişandı. Osmanlı hangi amaçla buraya gelmiş, onu dahi bilmiyordu. Gidilecek denmiş ve gidilmişti.

           İşte '' O Gece'' bir Azrail değil binlerce Azrail iş başında idi. Bedenler birer birer bir buz haline dönüşüyor, ağızlarda Kelime-i Şahadetten başka bir söz çıkmıyor, çıkamıyordu.  Dişler seri bir halde biribirlerine çarpıyor, yavaş yavaş kenetlenip ağızlar kapanıyordu. Artık bedenleri zangır zangır titremiyordu. Tüm Osmanlı askeri artık ömürlerinin son demine geldiklerine inanmış, ahiretinden başka hiçbir şey düşünür değillerdi. Onlar için bu gecenin sabahı yoktu, bu gece ömürlerinin son gecesiydi.

           Herkes kendi canının derdine düşmüştü. Yakup Ağa ile Mehmet Çavuş her zamanki gibi gene biribirlerine sarılmış, ölümle yaşam arasında gerçek bir savaş veriyorlardı. Gecenin ilerlemesi ile birlikte acımasız soğuk da şiddetini artırıyor, ağızlardan çıkan nefesler bile donuyordu. Mehmet Çavuş gözlerini gene gökyüzüne dikmiş birilerini arar gibi, birilerine bir şeyler gönderir gibiydi. Dişleri biribirine daha hızlı bir şekilde çarpıyor, bedeni dayanma gücünü kaybetmiş bir şekilde tiril tiril titriyordu. Birden Mehmet Çavuş''un çenesi oynamaz, bedeni titremez oldu. Mehmet Çavuş bu amansız düşmana mağlup olmuş, donarak şehitlik mertebesine ulaşmıştı. Mehmet Çavuş artık Harput''taki yavuklusunu da göremez olmuştu.

          Yakup Ağa kucağında kaskatı kesilmiş Mehmet Çavuşunu, can yoldaşını, silah arkadaşını titreyen dudaklarıyla öpmeye çalışıyor, Yasin-i Şerif duasını okumaya gayret ediyordu.

          Sabaha karşı başlayan tipi, sayısı doksan bin olarak açıklanan şehitlerin üzerine beyazdan bir kefenlik örtmüştü. 

          Şehitleri biribirlerinden ayırmak mümkün değildi. Biribirlerine yapışık bir şekilde donmuşlardı. Ayırmak mümkün olmayınca bir subay- Bırakın kalsınlar, onları ayırmayın, talimatını verdi. Zeten aralıksız yağan kar onları toprak olup örtmüştü.

          Yakup Ağa, Yasin-i Şerif duasını bitirmiş miydi, bitirmemiş miydi bilinmez ama kucağındaki şehitle gözlerini gökyüzüne dikmiş birilerini arıyor gibiydi. Yakup ağa birden bir çığlık sesi duydu. Bu ses taaaa Harput''tan geliyordu. Harput ağlıyordu. Harput''ta bir kadın ağlıyordu.

            Yakup Ağa ''O Gece''den sonra günlerce gönlü yaralı, yüreği yaralı baygın bir şekilde günlerce yatmış. Daha sonraları esaret hayatı başlamış. Senelerce esaret altında yaşamış ve türlü türlü işkencelere maruz kalmış. Nihayet bitkin ve yorgun bir şekilde sapasağlam gittiği vatan hizmetinden bir ayağı topal olarak sılasına varabilmişti. Yakup Ağa hiçbir zaman ısınmamış, hiçbir zaman mutlu olamamış. Her zaman üşümüş, her zaman ağlar olmuş, dudaklarında ''Allah, rahmet eylesin.'' sözünden başka bir söz duyulur olmamıştı.

        Yakup Ağa, Yedi Kardeş yıldız kümesinin en önünde Mehmet Çavuş''u, arkasından yavuklusunu ve en sonunda da kendisini görür olmuştu. O günden sonra her gece gökyüzünde bu yıldız kümesini arar, derinden bir ah çeker, yaşlı gözlerle o günleri yeniden yâd ederdi. Yakup Ağa sık sık merkebine biner, Harput''a gelir, Harput''ta Mehmet Çavuşla ve Mehmet Çavuşun yavuklusuyla buluşurdu. Harput''taki bütün evliyalarla konuşur, onlara Yasin-i Şerif okur, aziz ruhlarına armağan ederdi.

         Yakup Ağa, Harput''ta devamlı bir çığlık sesini duyardı ve Harput''un hep ağladığına inanırdı. Ve o derdi ki ''Ey oğul! Harput tarihin her döneminde o kadar çok şehitler verdi ki böyle bir beldenin gülmesi mümkün değildir. Harput''un her karış toprağında sayısız şehitler yatmaktadır. Bu yüzden Harput azizdir, Harput mübarektir. Orada gezdiğinizde attığınız her adımı besmele ile atın. Çünkü o topraklarda nice Mehmet Çavuşlar, nice Aliler, Ahmetler ve Mustafalarla, şehitlerinin dönmesini bekleyen nice nice yavuklular vardır.'' 

         İşte odur budur ben de Harput''un hep ağladığını düşünürüm. Yoksa tarihler boyu medeniyetlere başkentlik yapmış, tarihler boyu ilim irfan merkezi olmuş, ünü okyanuslar ötesine gitmiş bir mukaddes beldenin böylesine mahzun, böylesine perişan bir halde bulunması mümkün müdür? 

         O Harput'' ki bünyesinde o kadar şehit, o kadar evliya barındırıyor ki bunların yüzü suyu hürmetine edilen dualar bile kabul olunamıyor. Bizler ya o duaları kalbi bütünle yapmıyoruz ya da o mübarek zatlara layık nesiller olamıyoruz. 

        Netice olarak Harput ağlıyor, biz ağlıyoruz. 

        Bütün şühedaya Rabbimden rahmetler diliyor ''Şehitlerin Namazı'' adlı bir şiirimle sizlere veda ediyorum. Kalın sağlıcakla…                       

        ELAZIĞ Nurhak Gazetesinde 2 ve 3 Mart 2006 tarihlerinde yayınlanmıştır.                                                                     

                                                                                                  

                                               ŞEHİTLERİN NAMAZI

							Şehitlerimize...

                                İki Mehmedimi Serhatta şehit ettiler,

                                Bayraklarla bezeyip, Harput''a getirdiler.

                                Ulu Camide ezanı, okudu Arap Baba,

                                Derinden derine titredi Uluova.

                                Minberde İmam Efendi verirken vaazı,

                                Kılındı huşu ile şehitlerin namazı.

                                Vatan vatan dediler, vatan için öldüler,

                                Ve melekler ordusu onları çok övdüler.

                                Bu namaz meleklerin kıldığı bir namazdı,

                                Şehitlik mertebesi, onlarda birer hazdı.                              

                                İmam Efendi önde, getiriyordu tekbir,

                                Baktılar ki Bedir''de çınlanıyor o tekbir.

                                Kazıldı kabristanlar kazma ile kürekle,

                                Defnedildi şehitler kanayan yüreklerde.

                                Siz ki içtiniz kana kana o mis şerbeti,

                                Tattınız doya doya onurlu şahadeti.

                                Cennette yerinizi hazırlamış melekler,

                                Varın kurulun, gönlünüzce aziz şehitler.                             

                                Ey ulu Harput'' um, ey evliyalar otağı,

                                Serildi öz bağrında şehidimin yatağı.

                                Ey evliyaların kol kola gezdiği belde,

                                Şehitlerime nurdan mekân, olunan belde.

   

                                Yarıya inmesin Kayabaşında bayrağım,

                                Düşmesin şehidimin elindeki sancağım.', 'Yakup Ağa bütün bir kış evinden çıkamamış, evinin penceresinde kış boyu yağan karı, o kar tanelerinde esareti, acıyı, açlığı, öldürücü soğuğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/harput-tan-gelen-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar Arasında...', 'dort-duvar-arasinda-i-brahim-ethem-bingul-m011z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şükrederim yaradanıma

Mutlu olurum verdiklerine, sahip olduklarıma

Hatırlarım baktıkça tırnaklarıma

Toprağı nasıl kazdığımı onlarla...

Tozpempedir yaşantım karşıdan bakana

Sanki yok ve olmaz ne gam ne tasa

Etten duvar etrafım insanlarla ya

El ne bilir dünyamı dört duvar arasında...

Seninle paylaşmak isterim ama

Gelir misin yanıma

Göstermek istediklerim var hayatımda

Ne o, geldin de göremiyor musun yoksa

Bari sen yapma...

Daha önce demiştim sana

Beni göremezsin ki

Yapma, at gözlüğüyle bakma...

www.iebingul.com', 'Şükrederim yaradanıma Mutlu olurum verdiklerine, sahip olduklarıma Hatırlarım baktıkça tırnaklarıma Toprağı nasıl kazdığımı onlarla... Tozpe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dort-duvar-arasinda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-mesut-ozturk-8y1xi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maddiyatın yoksa evladına bırakacak,

Bari biraz doğruluk dostluk bırak,

Evin yoksa arkandakilere bırakacak,

Bari insan olacağı kadar, samimiyet bırak.

Araban atın yoksa çocuğuna bırakacak,

Her memlekette sığınabileceği açık kapı bırak.

Paran mülkün yoksa torunlarına bırakacak,

Arkandan fatiha okuyabilecek bir evlat bırak.

Hiçbirşeyin yoksa ailene bırakacak,

Bari bir iki kelime güzel söz bırak,

Kagıtın dahi yoksa çocuklarına yazacak,

Radyo güllüge bir tane şiirini bırak.

Bunlara bile imkanın yoksa, 

Arkandakilere anlatacak bir tane dost bırak,

Eğer bunada gücün yetmezse,

Sen boşuna yaşamışsın, kusura bakma arkadaş!', 'Maddiyatın yoksa evladına bırakacak, Bari biraz doğruluk dostluk bırak, Evin yoksa arkandakilere bırakacak, Bari insan olacağı kadar, samimi...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birak-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsalar Ağlarız', 'dokunsalar-aglariz-tahmine-yildirim-vrclp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu zalim gurbette yüreğimiz her gün biraz daha yumuşuyor

günler,haftalar,aylar ve yıllar bir atlet gibi koşuyor

bu kısa ömürde insanlar neden birbiriyle savaşıyor

gözlerimiz bu durumlara o kadar doluyorki

 Dokunsalar ağlarız

İnsanın burnunun direği sızlıyor aklına geldimi vatanı

güzel vatanında ana,baba,kardeş ve can dostları

bir yıl boyunca düşünür durursun nasıldır sağlıkları 

her gün işte bu düşüncelerle dolar yüreğimiz işte o an

Dokunsalar ağlarız

Ayrılık çok zor şeymiş çekmeyenler bilmez bunu

insan ne kadarda çok özlüyor o güzel yurdunu

ayrı oldunmu yurdundan yitirmiş gibisin sanki benliğini

bir hece bir kelime yetiyor işte o an

Dokunsalar ağlarız

İnsanın kulağı hep telefonda gözü yolda oluyor

nasıl kaderse bu yıllardır hep böyle sürüyor

yıllar geçtikçe içimizdeki sızı dahada artıyor

bu ayrılıklar o kadar yettiki canımıza işte o an

Dokunsalar ağlarız.

                                                          EKİM:1993', 'Şu zalim gurbette yüreğimiz her gün biraz daha yumuşuyor günler,haftalar,aylar ve yıllar bir atlet gibi koşuyor bu kısa ömürde insanlar nede...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dokunsalar-aglariz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bir İnci Olsan', 'sen-bir-i-nci-olsan-ercan-cengiz-o5wov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEN BİR İNCİ OLSAN

sen bir inci olsan kem göze gelsen 

ben bir kabuk olur korurdum seni 

sen deryada olsan taş altında kalsan 

ben bir balık olur çıkarırdım seni 

ahvalini yazsam dünyaya duyursam 

sen kalemin ucu yazar mıydın beni 

şu fani dünyada dertten kurtulsam 

bir aşkı sevdada tanır mıydın beni 

sen senin aşkına yakar idin beni 

ben senin aşkından öze dönerdim 

behey zaman olur kervanlar durur

kaş ile göz ile yollardım seni 

aşkın mecalinden öldüm dirildim 

nice yollar geçtim şerbetin içtim 

sen bir nar olsaydın ben dalında dikenin 

kem gözle bakanın gözüne batardım 

sen benim hasretim sen benim gökyüzüm 

kavgadayım şu koca dünyada bir tek senin için 

(Adsız Fırtınalar Doğuyor)', 'SEN BİR İNCİ OLSAN sen bir inci olsan kem göze gelsen  ben bir kabuk olur korurdum seni  sen deryada olsan taş altında kalsan  ben bir balık...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-bir-inci-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk dedin ya aklıma düştü,', 'ask-dedin-ya-aklima-dustu-mesut-ozturk-43j0w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk dedin ya aklıma düştü,

Sevgi dedin ya, aklım karıştı,

Neden sevmek var ki? 

Karşılığı olmadıktan sonra,

Neden özlemek var ki? 

Kadir kıymet bilmedikten sonra,

çünkü; insan kalbine söz geçiremiyor,

Gönül bu dikene de, güle de konuyor,

Hayat bu karşılığı oluyor yada olmuyor,

Ama bir gerçek sevmeden de durulmuyor.', 'Aşk dedin ya aklıma düştü, Sevgi dedin ya, aklım karıştı, Neden sevmek var ki?  Karşılığı olmadıktan sonra, Neden özlemek var ki?  Kadir kıy...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-dedin-ya-aklima-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Tutulduğu Gece', 'ay-tutuldugu-gece-candan-sevinc-q34jr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay tutulduğu gece

Rüyalarıma açılan pencereden

Yüreğimin çökük yatağına

Beyaz izler bırakarak ilerledin

Sessiz koridordan uzandı

Kestane ağaçları

Su berraklığında dalgalandı saçların

Kar tanesi topladım üşümüş avuçlarından

Gözbebeklerine bir gamze dağıldı

Cam kırığı gülüşünün yüreğimde izi kaldı.', 'Ay tutulduğu gece Rüyalarıma açılan pencereden Yüreğimin çökük yatağına Beyaz izler bırakarak ilerledin Sessiz koridordan uzandı Kestane ağa...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ay-tutuldugu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölbaşım', 'golbasim-huseyin-bacanak-98j21', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara’nın en güzel Metropolü, 

Göllerinle övünürsün Gölbaşım. 

Girişinde taştan sembolik gülü, 

Taşlarınla övünürsün Gölbaşım. 

Gölbaşım simgen Sevgi Çiçeği’dir, 

Adına festivaller düzenlenir. 

İçimden sürekli koklamak gelir, 

Çiçeğinle övünürsün Gölbaşım. 

Mogan Gölü yol boyunca uzanır, 

Suyu derin balıkları saklanır. 

Nazlı nazlı sahiline yaslanır, 

Hayat verir Mogan sana Gölbaşım. 

Eymir Gölü mavi bir gerdanlıktır, 

Kıyıları  ağaçlarla kaplıdır. 

Balıkları baldan bile tatlıdır, 

Eymir’inle övünürsün Gölbaşım. 

Hacı Hasan köyün pirler diyarı, 

Yaylabağı’n soğuk sular kaynağı. 

Tuluntaş’ın ünlüdür mağarası, 

Ne kadar övünsen azdır Gölbaşım. 

Gelmiş, Amasya, Bayburt ve Tokat’lı,

Kırşehir, Trabzon ile Yozgat’lı

Çankırı, Çorum, Artvin ve de Kars’lı, 

Onlar artık Gölbaşı’lı, Gölbaşım. 

Ankaralı bunalınca işlerden, 

Bir yer arar kendine sahilinden, 

Derin nefes alır Mogan Gölü’nden, 

Mogan Parkla övünürsün Gölbaşım. 

Seni anlatmaya mısralar yetmez, 

Yüreğimde saklı, sevgin Gölbaşım. 

Ne kadar çalışsak hakkın ödenmez, 

Bağrında bana da yer ver Gölbaşım. 

               02.03.2006 - Gölbaşı/Ankara

               Şiirlerimin kayıt belgesi vardır.', 'Ankara’nın en güzel Metropolü,  Göllerinle övünürsün Gölbaşım.  Girişinde taştan sembolik gülü,  Taşlarınla övünürsün Gölbaşım.  Gölbaşım si...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Bacanak']::text[], 8.5, '{"poet":"Hüseyin Bacanak","poet_slug":"huseyin-bacanak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/golbasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl da Kayıp Gittin', 'nasil-da-kayip-gittin-yusuf-onder-bahceci-iz8q7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl da kayıp gittin gözlerime baka, baka,

Nasıl da kayıp gittin şu kâlbimi yaka, yaka,

Sende değil, bende hata, nasıl gittin, nasıl,

Önder, şimdi akıl başta, gel küreklere asıl.

Bu nasıl iş,  nasıl gidiştir anlamadım derim,

Şimdi, kendi kendime, inan hayret ederim,

Şimdi ellerdesin Gülüm kime sitem ederim,

Nasıl da kayıp gittin gözlerime baka, baka.

Dövmek mümkün olsa, kendimi döverdim,

Sevdiğini cidden kaçıranları fazla överdim,

Yaralı bir kartal gibi gökyüzünde dönerdim,

Nasıl da kayıp gittin gözlerime baka, baka.

Gel, istediğin kadar böyle, güzel şiirler yaz,

Gelsen yüce dağların başında fazladır ayaz,

Biliyorum be, beni sormayacak yine bu yaz,

Nasıl da kayıp gittin gözlerime baka, baka.', 'Nasıl da kayıp gittin gözlerime baka, baka, Nasıl da kayıp gittin şu kâlbimi yaka, yaka, Sende değil, bende hata, nasıl gittin, nasıl, Önder...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-da-kayip-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek Güzeldi', 'seni-sevmek-guzeldi-umit-tuna-y28mg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne yapmak istiyorum biliyor musun? 

Hiç bilmediğim yerlere gitmek,

Oralarda hayatımı devam ettirmek,

Karanlık bir odaya çekilmek istiyorum.

Sadece mum ışığı olsun,

Birde beraber çekindiğimiz resimlerimiz,

Ve bana yazdığın mektuplar,

Onları mum ışığında okumak istiyorum.

Bir yandan da ağlamak,

Sebepsizce seni aramak,

Bu karanlık odayla savaşmak,

Avazım çıktığı kadar bağırmak.

Yokluğunla varlığın arasındaki duyguyu tatmak,

Belki de sen yokken seninle olmak,

Belki de ayrılıktan pişmanlık duymak,

Ve tekrar sana koşmak…

İşte o zaman tekrar ellerini verir misin bana? 

Hiç bir şey olmamış gibi devam eder miyiz aşkımıza,

Bazen düşünüyorumda.

Senden ayrılmakla aptallık etmişim galiba,

Seninleyken ben çok mutluydum ama…

Kaderimizde bu da varmış,

Şimdi bizim aşkımızda kayıplara karışmış.

Olsun be sevgilim,

Sen  ve resimlerin,

Her satırında hasret kokan mektupların,

Bunlarla yaşamakta güzel aslında.

Birazcık acı olsa da,

Vazgeçilmezim diyordun ya bana,

Sor olsa da vazgeçtin benden,

Hadi gönlüm sen aç başka aşklara yelken! ...', 'Ne yapmak istiyorum biliyor musun?  Hiç bilmediğim yerlere gitmek, Oralarda hayatımı devam ettirmek, Karanlık bir odaya çekilmek istiyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-sevmek-guzeldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanus', 'okyanus-umit-tuna-ovkcf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni bazen bir okyanusa benzetiyorum,

Onun kadar derin ve berraksın,

Bazen de seni bir bebeğe benzetiyorum,

Onun kadar sevgiye muhtaçsın.

Bazen ulaşılmazım,

Bazen de anlaşılmazım,

Bazen hep varsın,

Bazen hiç yoksun.

Sen ne yaptığını sanıyorsun,

Koskoca bir okyanusu kirletiyorsun,

Küçücük bir hiç uğruna neler yapıyorsun,

Ulaşılmazım diyorum sana,

Bazen çok uzaksın ondan işte.

Bazen anlamıyorum seni,

Hayattan ne almak istediğini,

İşte bunun içinde anlaşılmazım diyorum sana,

Anlamıyorum seni ama.

Sende anlamıyorsun ne beni ne de sevgimi,

Senin koskoca okyanusunda küçük bir tekne olmak istedim,

Bunu da beceremedim,

Bırak kalbini çalmayı,

Sana seni seviyorum demeye bile cesaret edemedim! ...', 'Ben seni bazen bir okyanusa benzetiyorum, Onun kadar derin ve berraksın, Bazen de seni bir bebeğe benzetiyorum, Onun kadar sevgiye muhtaçsın...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/okyanus-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arardım', 'seni-arardim-candan-sevinc-hyrr1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni arardım bütün sokak vitrinlerinde

Gözlerin içime yansırdı camlardan

Saçların fırtınam olur dolanırdı boynuma

Seni arardım her akşam bir kır kahvesinde

Duruşun aklımı bozardı

Saatler sürerdi sana hasret gidermem

Dudaklarım dağları arşınlardı

Seni arardım gezindiğimiz sahil yolunda

Martılar adını sayıklardı

Gülüşlerin yıldızlardan yansırdı

Seni arardım rüyalarımda

Bir bilinmeze doğru kayardı ellerin

Tutamazdım yüreğini bir kıskaç gibi

Seni sevdiğimi söylemek isterdim

Tıkanırdı sözcükler yol vermezdi

Seni arardım tüm bahçelerde

Sümbül kokan saçlarını

Toz bulutu dudaklarını bulmak isterdim

Seni arardım gecelerde

Sabaha kadar yol alırdım sana ulaşmak için

Kıvrılıp bir köşede sana ağıtlar yakardım

Seni arardım gökyüzünde ama bulamazdım.', 'Seni arardım bütün sokak vitrinlerinde Gözlerin içime yansırdı camlardan Saçların fırtınam olur dolanırdı boynuma Seni arardım her akşam bir...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-arardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-umit-tuna-ho4ld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın? 

Seninle tanıştığımız o günü,

Mevsim sonbahardı,

Günlerden pazardı.

Hava alacakaranlıktı,

Yapraklar sararmıştı,

Göz göze geldiğimizde,

İçimiz aydınlanmıştı.

İş de o günden beri,

Ben hep aynı mevsimde,

Ben hep aynı günde,

İlk buluştuğumuz yerde.

Aynı kafede

Anılarımızı canlandırıyorum,

Bilmiyorum bu tutku ne zaman bitecek,

Deli gönlüm bu alışkanlıktan ne zaman vazgeçecek,

Şu deli gönlüm

Sadece hep seni sevecek! ...', 'Hatırlar mısın?  Seninle tanıştığımız o günü, Mevsim sonbahardı, Günlerden pazardı. Hava alacakaranlıktı, Yapraklar sararmıştı, Göz göze gel...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deli-gonlum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Mı sandın', 'mi-sandin-i-smail-arslan-mknk7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susuz akşam sabaha çıkarmı sandın

Bir damlacık suyu esirgersin benden

Söylenen söz yürekten çıkarmı sandın

Kurşunun öldürmediği taş bedenden.

Yılların süslediği uzun yollardan

Geçmişte yaşadığım tatlı anlardan

Yaşadığım unutulmaz o hazlardan

Vazgeçip uzaklara gidermi sandın.

Dünya yıkılsa yinede seninleyim

Sensiz başka bir kimseyi ben neyleyim

Ben,sevdiceğim bak işte ben böyleyim

Başka fanileri severmiyim sandın.

Yollara düşmüş umutlarım bitsede

Ağaçlar çiçeklerini hep döksede

Saçlarıma bölge bölge ak düşsede

Seni yüreğimden atarmıyım sandın.', 'Susuz akşam sabaha çıkarmı sandın Bir damlacık suyu esirgersin benden Söylenen söz yürekten çıkarmı sandın Kurşunun öldürmediği taş bedenden...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin..', 'gozlerin-gani-aslangoz-2d01e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nedendir bilinmez						                  gözlerin güneşten almış da hazzını	

güneşin lafı edilmez.

sanki saklı gözbebeklerin

içinde girift bilmecelerin.

kapamasın ne olur, o bir çift nuru ellerin

ellerin ki selvi dalınca

selvinin lafı edilmez.

böyle bir başıma koyup 

gözlerinle beraber yok mu gidişin

beni kandıramaz artık hayalin

beni kandıramaz artık gülüşün

yokluğunla savaşırım sabahlara dek

savaşın lafı edilmez.

bir engin mekana açılır

gözlerinde ruhum,

ve ruhun gözlerinde saflaşır.

çile aklaşır, sevda aklaşır

ruhlar oynaşır gözlerinin bozkırında

bedenin lafı edilmez.

gözlerinin bittiği yerde gözlerin başlar

zamanın bittiği yerde sonsuzluk.

artık bir ince soğukluktur davranan

gözlerini son bir kez göreyim

şimdi sonsuzluk muştusu vermede zaman

ölümün lafı edilmez', 'nedendir bilinmez						                  gözlerin güneşten almış da hazzını	 güneşin lafı edilmez. sanki saklı gözbebeklerin içinde girift b...', ARRAY['Türk Edebiyatı','Şiir','Gani Aslangöz']::text[], 8.5, '{"poet":"Gani Aslangöz","poet_slug":"gani-aslangoz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozlerin-230-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime bak', 'gozlerime-bak-fuat-dogan-ajjbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖZLERİME BAK 

öyle uzaklra bakma

uzakların kırılacak bir yüreği yok

her soluk öncesi gözlerime bak

gözlerime bak ki! 

karı yağmamış dağların 

kokusu sinsin yüreğine

                  Fuat DOĞAN

                        2005', 'GÖZLERİME BAK  öyle uzaklra bakma uzakların kırılacak bir yüreği yok her soluk öncesi gözlerime bak gözlerime bak ki!  karı yağmamış dağları...', ARRAY['Türk Edebiyatı','Şiir','Fuat Doğan']::text[], 8.5, '{"poet":"Fuat Doğan","poet_slug":"fuat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerime-bak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtık Sandal.', 'yirtik-sandal-mesut-ozturk-bq8fe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuk yürüyor baktım, kenardan,

Burnun da sümük, gözlerinde yaş,

Sessizce yaklaştım yanına, yavaştan,

Ayağında yırtık bir sandal, düşerken lapa lapa kar,

Korkutmadan sormak istedim,

Ne oldu? Neyin var? diye.

Bana bir baktı, bir daha baktı,

Bir isteği var gibiydi, ama utandı.

Sıkılma delikanlı anlat derdini, ben dinlerim,

Utanma, saklama gözlerini, ben bu hali bilirim,

Üşümüşsün, bak dışarda kar yağıyor,

Söyle hadi, o güzel gözlerin neden ağlıyor? 

Al mendili sil şu burnunu hele,

Yudumla çayından, utanma al simidini ye,

Ne oldu evlat, seni bu hale sokan,

Kimin kimse yok mu? Anan Atan.

Öksüzüm ben amca, anam öldü,

Yetimim ben, babam anamla birlikte öldü,

Yanlızım ben kardeşim de onlarla gözünü yumdu,

Kin doluyum ben, onlara vuran sarhoş o da öldü.', 'Bir çocuk yürüyor baktım, kenardan, Burnun da sümük, gözlerinde yaş, Sessizce yaklaştım yanına, yavaştan, Ayağında yırtık bir sandal, düşerk...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yirtik-sandal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lori Lori', 'lori-lori-ahmet-guven-g2u29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'LORÎ LORÎ 

Min axa welêt germ kir 

Bi dergûşê te lorî kir 

Hat bîra min qala dêûbavan kir 

Lorî lorî berxa’m lorî 

Xewe xweş li çaven reşnî 

Êvar dakete ser malan 

Tev li hev bû hesa se û çekan 

Xewneke xweş li ser çavan 

Lorî lorî berxa’m lorî 

Xewe xweş li çaven reşnî 

Dilê min çar parçe ye 

Her parçek mîna milkê xalkê ye 

Mirin mayîn ji boyê azadîyê 

Lorî lorî berxa’m lorî 

Xewa xweş li çavên mornî 

Peyv û Mûzik: Ahmet Güven 

TÜRKÇESİ 

NENNİ NENNİ 

Ben memleket toprağını ısıttım 

Eledim beşikte seni büyüttüm 

Aklıma geldi anamın babamın sözünü ettim. 

Nenni nenni yavrum nenni(GÜZEL BİR DÜŞ GÖR NENNİ)

Karanlık çöktü evlerin üzerine 

Karıştı birbirine it sesleri silah sesleri 

Sen güzel bir rüya gör 

Nenni nenni yavrum nenni 

Benim yüreğim dört parça 

Her parçası elin mülkü 

Ölmekte yaşamakta özgürlük için 

Nenni nenni yavrum nenni 

Söz ve Müzik; Ahmet Güven 

2002 yılında global müzik(dilimde türkü gözümde Turna) albümünden

Her anne bebeğine ninni söyler ve ninni söyleyen her dil

güzeldir.', 'LORÎ LORÎ  Min axa welêt germ kir  Bi dergûşê te lorî kir  Hat bîra min qala dêûbavan kir  Lorî lorî berxa’m lorî  Xewe xweş li çaven reşnî ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/lori-lori-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Aydın', 'gozlerin-aydin-huseyin-sigirtmac-l01e4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım cenderede ağlıyor gözüm.

Bir ömür susarım artık yok sözüm.

Sana kalsın sevgin kalmadı lüzum.

Artık son kelâmım gözlerin aydın.

Dengine ulaşmak bir hayal meğer.

Boşunaymış sana verdiğim değer.

Bir gün neden diye sorarsan eğer.

Sayende ölümüm gözlerin aydın.

Enginlere konmaz yüksek uçarsın.

Peşine düştükçe uzak kaçarsın.

Dünya sana kalmaz sen de göçersin.

Artık yok selamım gözlerin aydın.

Sığırtmaç tükendi artık son mecal.

Baş ve göz üstüne kabulüm ecel.

Şiirler hakkını ederse helâl.

Kalmaz hiç elemim gözlerin aydın.

Bursa 03 Mart 2006 Saat: 16.10', 'Canım cenderede ağlıyor gözüm. Bir ömür susarım artık yok sözüm. Sana kalsın sevgin kalmadı lüzum. Artık son kelâmım gözlerin aydın. Dengine...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-aydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanağına Düşür Beni', 'yanagina-dusur-beni-kamil-soylemez-ydt2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinde düşün beni…! 

Her kestiğin göz yaşında..

Yanağında düşün beni

O ilkbahar yağmurunda

Papatyada düşün beni…

O İlk tuttuğun aşk fallarında…

Arzularında düşün beni yüreğin koptuğunda

Sıcaklığında düşün beni, avuçların ortasında

Öptüğümde düşün,kuş olup,uçtuğumda

Aynalarda düşün beni.. 

Süslerken,yerine yüreğimi

Göz kırpmalarında düşün beni

İki sevişken göz bebeğini

Gözlerime neler,neler ettiğini..

Son baharda düşün beni

Yere düşen son yaprakla

Uçup,giden gençliğimi

Dalgalarda düşün beni..

Senin için kendimden geçtiğimi.

Martılarda düşün beni

Çığlık,çığlık pikeleştiğimi

Sofranda düşün beni

Yutmak isteyip,te yutamadığın ekmeğini….

Düşün ki,suyun olayım

Yutamadığın lokmalardan kurtarayım

Akşamlarda düşün beni

Öperken ay ile yıldızlarda,geceyi..

Anadolu da düşün beni

Bir köy pınarından

Avuç avuç içtiğim seni..

Maden ocağında düşün beni

Karanlıkta bıraktığım zeytin gözlerimi

Vardiyada yitirdiğim incilerimi

Yıllarca geceleri terlerimi içtiğimi

Rüyalarımın çekilmezliğini

Düşün ki kulun olayım

Düşün ki yolun olayım

Düşün ki çayında şekerin

Ekmeğinde otlu peynirin

Yüreğinde saf meleğin olayım

Düşün ki………..

Yıllara seni eşim diye sunayım..', 'Gözlerinde düşün beni…!  Her kestiğin göz yaşında.. Yanağında düşün beni O ilkbahar yağmurunda Papatyada düşün beni… O İlk tuttuğun aşk fall...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yanagina-dusur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Anladım', 'cok-gec-anladim-yusuf-onder-bahceci-hiuoc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılmak sevmemek değilmiş yeni anladım,

Ayrılanlar hep ümitsizmiş, çok geç anladım,

Sevdiğim gözlerime bakardı, anlayamadım,

Ayrılmak sevmemek değilmiş yeni anladım.

Ne vardı, bildiklerini bana deseydi deseydi,

Ne vardı, çaresizim, ümitsizim ben deseydi,

Ne vardı Allah aşkına derdini bana deseydi,

Ayrılmak sevmemek değilmiş yeni anladım.

Şimdi, gözlerim ufuklara dalar, dalar, gider,

Şimdi, seven kâlbimde, kimbilir ne fırtınalar,

Şimdi seni benden başka, başka kim anlar,

Ayrılmak sevmemek değilmiş yeni anladım.

Bu derdimin elinden ağlarım bizar gezerim,

Elden birşey gelmez, Gülüm, kızar gezerim,

Nerde iki seven varsa kâlbim kırık sezerim,

Ayrılmak sevmemek değilmiş yeni anladım.', 'Ayrılmak sevmemek değilmiş yeni anladım, Ayrılanlar hep ümitsizmiş, çok geç anladım, Sevdiğim gözlerime bakardı, anlayamadım, Ayrılmak sevme...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-gec-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıtıyorsun', 'acitiyorsun-fuat-dogan-irwnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ACITIYORSUN

bir bilsen

ne çok uğraşıyorum

talan ettiğin sol yanımla

her anımda sen 

ya da düşlerimde silüetin var

bazen 

ulaşılması güç bir özlemsin

bazen de 

yanıbaşımda ruhumu okşayacak

ve tenime dokunacak kadar yakınsın

fakat nerene dokunsam acıtıyorsun.

                              Fuat DOĞAN

                                     2005', 'ACITIYORSUN bir bilsen ne çok uğraşıyorum talan ettiğin sol yanımla her anımda sen  ya da düşlerimde silüetin var bazen  ulaşılması güç bir ...', ARRAY['Türk Edebiyatı','Şiir','Fuat Doğan']::text[], 8.5, '{"poet":"Fuat Doğan","poet_slug":"fuat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/acitiyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen Suyunu Sen Vermiş Gibi', 'kardelen-suyunu-sen-vermis-gibi-nizami-sunguroglu-hpax9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gamlı yüreğime sevda ekmeden

Sevda güllerini koklaman niye.? 

Kardelen suyunu sen vermiş gibi

Kararan kalbini aklaman niye.? 

Hazanla yaşayan kalbi görmeden

Dört mevsim baharı yeğlemen niye.? 

Verdiğim sevgiye dudak bükerken

Yad olan sevgiye göz kırpman niye.? 

03/03/2006

Nizami Sunguroğlu

Hollanda', 'Gamlı yüreğime sevda ekmeden Sevda güllerini koklaman niye.?  Kardelen suyunu sen vermiş gibi Kararan kalbini aklaman niye.?  Hazanla yaşaya...', ARRAY['Türk Edebiyatı','Şiir','Nizami Sunguroğlu']::text[], 8.5, '{"poet":"Nizami Sunguroğlu","poet_slug":"nizami-sunguroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kardelen-suyunu-sen-vermis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sere Sale', 'sere-sale-ahmet-guven-jquuy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SERÊ SALÊ 

‘Sarê salê binê salê 

Xızır mêvanê vê malê’ 

Daxwaza xêr û xweşiyê 

Ev daniya kal û pîrê 

Ek pîrik e,ek Xızır e 

Danî daniştî ser êre 

Herkes hilgirt para xwe 

Mîna xwîşk û bira ne 

Xızır tîne daniyê 

Pîrikê rû keniye 

Çaxanî girtiye şa bûn 

Le pisiyê dûr û ne 

Çaxan û xewa we xweş 

Çaxan û xewla we xweş 

Xızır dibê pîrêk dibê 

Ji were xêr û xweş 

Peyv û Mûzik: Ahmet Güven 

SENE BAŞI 

‘Sene bitti sene başı geldi 

Hızır eve misafir geldi’ 

İylik diler sağlık diler 

Dağıtılır Hızır lokması 

Biri Hızır Biri nene 

Ocakta aş pişirirler 

Çocuklar bacı kardeş gibi 

Herkes payını alır 

İhtiyar yemekleri getirir 

Nene gülümser 

Çocukları alır sevinç 

Bütün kötülüklerden uzak 

Tatlı uykular çocuklar 

Tatlı rüyalar 

Hızır diler nene diler 

Sizin olsun iylik ve sağlıklar 

Söz ve Müzik: Ahmet Güven 

Anadolu''da sene başlarından biride 14 şubat da kutlanır.(Çoğu yerde kış 

yarısı da denir) .Cemre daha köz olmadan,havaya,suya ve toprağa 

düşmeden müjdesi gelir. 

Yeni yıla Hızır''la girilir.Hızır halk arasında olgun insana denir.Dara düşenin 

yardımına koşar ''''Hızır sakalını ağartı''''derler. 

Sevinir çocuklar.Toplanırlar,kendi aralarından birini seçerler.Ona yundan 

sakal ve bıyık yaparlar.O Hızır olur.Ev,ev dolaşırlar.Maniler söylenir,şakalar 

yapılır.Her ev onlara yiyecek bişeyler verir.Akşamüzeri topladıkları yiyecekleri 

topluca bir eve götürürler.Hedik ve yemekler yapılır.Çocuklar için sofra 

kurulur ve hepsi toplanır sofraya kardeşçe.Özlem bu ya Hızır''ın iyliği ve bereketi de getirdiği rivayet olunur.', 'SERÊ SALÊ  ‘Sarê salê binê salê  Xızır mêvanê vê malê’  Daxwaza xêr û xweşiyê  Ev daniya kal û pîrê  Ek pîrik e,ek Xızır e  Danî daniştî ser...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sere-sale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çel', 'cel-ahmet-guven-giyf6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇEL(KÜRTÇESİ)

‘Çel,çel,çel li maran 

Çel li mişkan’ 

Lorîka min tu dergûşe î 

Tu min re pir xweş î 

Lorîka min tu şêrîn î 

Ro dibî tu gir dibî 

Bikene tu bilîze 

Dilê minê şa dibe 

Dergûşê te li ba dikim 

Ta mez dikim şa dibim 

Qurban dibim heyran dibim 

Tahez dikim têr nabim 

Garîm dikim ava te 

Dişom te dixemîlim 

Didime ser dilê xwe 

Çerx dikim nav kulîlkanda 

Peyv û Mûzik: Ahmet Güven 

KIRK(TÜRKÇESİ)

‘Yılan’ların kırkı için 

Fare’lerin kırkı için’ 

Bebeğim küçücüksün 

Kalbimsin çok tatlısın 

Bebeğim sen çok şirinsin 

Gün olur sende büyürsün 

Gül sen oyna sen 

Yüreğim sevinçle dolsun 

Beşiğini sallarım 

Sana bakar sevinirim 

Kurban olurum hayran olurum 

Sana bakar doyamam 

Sana su ısıtırım 

Çimdirir seni süslerim 

Seni kalbimin üstüne kor 

Çiçeklerin arasında gezdiririm 

Söz ve Müzik: Ahmet Güven 

BEBEKLERİN KIRKINI ÇIKARMA ADETİ 

Anadolu''da temeli nereye dayanır pek bilinmez.Bir bebek kırk günlük olursa 

kırkı çıkarılır.Kırk çakıl taşı yada kırk buğday tanesi suya konur.Isıtılan suyla 

çocuk yıkanır.Adete uygun sözler söylenir.Her tas su döküldüğünde bu 

sözler tekrarlanır.Bebeğin ağrısı,sızısı ulu sulara, yerli kayalara gönderilir. 

Yılanların,farelerin adı anılır(Kürtçe) . 

Bir söylenceye göre derlerki; Yılan bile çocuğa dokunmaz.Derlerki; çuvalın 

ağzı açılmazsa fare altından deler.Çocuğun mahsumluğuna ve zeki olmasına 

atfedilir.', 'ÇEL(KÜRTÇESİ) ‘Çel,çel,çel li maran  Çel li mişkan’  Lorîka min tu dergûşe î  Tu min re pir xweş î  Lorîka min tu şêrîn î  Ro dibî tu gir di...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/cel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atasözleri-II', 'atasozleri-ii-muharrem-cetinkaya-83loe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÜZEL SÖZLER

''Genç kuşağın Türkiye''yi daha iyi bir yere getireceğine inanıyorum. Bizler onlara köstek olmayalım yeter.''

BARIŞ MANÇO

''Kuşlar gibi uçmayı, balıklar gibi yüzmeyi öğrendik, fakat bu arada çok basit bir sanatı unuttuk. İnsan gibi yaşamak...''

MARTIN LUTHER

''Samimi olmayı vaad edebilirim; tarafsız olmayı asla.'' 

GOETHE

''Ne kadar az bilirseniz; o kadar şiddetle müdafaa edersiniz.''

BERTHARD RUSSEL

''Ne kadar bilirsen bil; söylediklerin karşındakinin anladığı kadardır.''

MEVLANA

''Yenileceğinden korkan, daima yenilir.'' 

YILDIRIM BEYAZIT

''İyi dostluklar, hesapsız kurulur.'' 

BALZAC

''Büyük beyinler fikirleri, orta beyinler olayları, küçük beyinler  ise kişileri konuşur.'' 

HYMAN RICKOVER

''Öyle horozlar vardır ki, öttükleri için güneşin doğduğunu sanırlar.'' 

H. DUNANT 

''Eğer birine birşey öğretirseniz asla öğrenmez.'' 

BERNARD SHAW

''Bir insan hangi limana ulaşmak istediğini biliyorsa, onun için her rüzgar uygundur.'' 

SENECA

''Kaptanın ustalığı deniz durgunken anlaşılmaz.'' 

ZUKIANOS 

''Bazı kitaplar tadılmak, bazıları yutulmak ve çok azı da hazmedilmek içindir.''

BACON

''Kitap ruhun ilacıdır.''

JAPON ATASÖZÜ

''Affetmek ve unutmak iyi insanların intikamıdır.''

SCHILLER

''Aşk mücadelesi değil, mücadele aşkı içinde ol.''

PEYAMİ SAFA

''Kainatta tesadüfe, tesadüf edilmez.''

SOKRAT

''Kusurumuz ne kadar çoksa o kadar kusur ararız.''

CENAP ŞEHABETTİN

''Okuyabilirseniz her insan bir kitaptır.''

W. ELLERY CHANNING

''Kargalar ötmeye başlayınca bülbüller susar.''

MEVLANA

''Herhangi bir insan vaktini nasıl geçireceğini üstün bir insan ise vaktini nasıl tasarruf edeceğini düşünür.''

SCHOPENHAVER

''Sakladığın bir sır senin esirindir. Açığa vurursan sen onun esiri olursun.''

HZ. ALİ

''Gençler ihtiyarların aptal olduğunu sanırlar ama ihtiyarlar gençlerin aptal olduğunu bilirler.''

GEORGE CHAPMAN

''Öl ve ol! İşte bunu bilmiyorsan zavallı bir misafirsin karanlık yeryüzünde.''

GOETHE

''Psikolog, güzel bir kız gördüğünde kızı değil, onabakanları inceleyen adamdır.''

I. MERLOST

'' ''Para herşeyi yapar'' diyen adam para için herşeyi göze alan adamdır.''

BENJAMIN FRANKLIN

''Cevizin kabuğunu kırıp özüne inmeyen cevizin hepsini kabuk zanneder.''

GAZALİ

''Sakın ahlak kurallarını çiğnemeyin çünkü öcünü çabuk alır.''

TOLSTOY

''Nasıl kafa sayısı kadar düşünce varsa, kalp sayısı kadarda sevgi çeşidi vardır.''

TOLSTOY

''Yenilgi eğitimden başka birşey değildir.''

WENDELL PHILIPS

''En büyük bilgelik kendine egemen olabilmektir. ''

EURIPIDES

''En büyük zafer insanın kendine hakim olmasıdır.''

PLATON

''İnsanlar her zaman kahraman olamazlar ama her zaman insan olabilirler.''

BENJAMIN FRANKLIN

''Bilirken susmak, bilmezken söylemek kadar kötüdür.''

PLATON

''Sevgi her zaman karşılık görür, kin de...''

DOSTOYEVSKI

''Öyle bir dünyada yaşıyoruz ki bir peşin hükmü söküp atmak, atomu parçalamaktan daha zor.''

EINSTEIN

''Gördüklerim beni görmediğim yaratıcının varlığına inanmaya zorluyor.''

EMERSON 

''Ancak Allah''a inandığım zaman yaşadığımı anladım.''

TOLSTOY

''Batıl inanış, zayıf kafaların dinidir.''

PLATON

''En iyi hükümet bize kendimizi yönetmeyi öğretendir.''

GOETHE

''İyiliğinize inanılmasını istiyorsanız ondan hiç bahsetmeyin.''

BALZAC

''Kardeşlerimi Allah yarattı, fakat dostlarımı ben buldum.''

GOETHE

