INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bezik oynayan kadınlar', 'bezik-oynayan-kadinlar-sair-pirinc-u6pur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '........bir oyundan taze çıkmışım 

bezik oynuyor kadınlar 

edip cansever - kayıp aşkların tadı 

taksime yürüyorum 

bir bara girip adamakıllı içmeli 

tanıdığım ilk yabancıyla da sevişmeli 

yağmur doluyor gözlerime 

ağlamıyorum...............................................................................', '........bir oyundan taze çıkmışım  bezik oynuyor kadınlar  edip cansever - kayıp aşkların tadı  taksime yürüyorum  bir bara girip adamakıllı...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bezik-oynayan-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başbaşa', 'basbasa-sair-pirinc-atr8j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'başbaşa kaldıgımız sayılı vakitlerde 

konuşmaktan yorulup sevişmekten bitkin düştüğümüzde 

kapanıyorsa gözlerim 

- ki biliyorum bana kızıyorsun 

sevgilim, uyunak değil, inan 

-o anı gözkapaklarıma çizmek içindir', 'başbaşa kaldıgımız sayılı vakitlerde  konuşmaktan yorulup sevişmekten bitkin düştüğümüzde  kapanıyorsa gözlerim  - ki biliyorum bana kızıyor...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/basbasa-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanım Erbil', 'sanim-erbil-semsettin-veli-erbilli-g3f7x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Türkçülüğün Kalesi yüce şehrimdir Erbil 

Dedelerimin yudu damarımda kanımdır 

Hep Türkmen akar suyu akan nehrimdir Erbil 

Bedenimi yaşatan hem dilim hem canımdır 

İlk ve son güvenimdir şöretim şanım Erbil 

Uğruna canım feda inanç imanım Erbil 

Adına kuban olam anım zamanım Erbil 

Onun için herşeyim canımdır cananımdır', 'Türkçülüğün Kalesi yüce şehrimdir Erbil  Dedelerimin yudu damarımda kanımdır  Hep Türkmen akar suyu akan nehrimdir Erbil  Bedenimi yaşatan h...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Veli Erbilli']::text[], 8.5, '{"poet":"Şemsettin Veli Erbilli","poet_slug":"semsettin-veli-erbilli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/turkculugun-kalesi-erbil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler ve Kadınlar', 'anneler-ve-kadinlar-adnan-durdagi-m0v72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüce Yaratanın büyük bir lütfü

Dünyalar tatlısı candır kadınlar

Herşeyden öncesi annemiz onlar

Yapraktır ağaçtır daldır KADINLAR

Kadın dedim ise ilk başta anam

Ayırmak olur mu yanında canan

Kendini unutan bizi can sanan

Şekerdir şerbettir baldır KADINLAR

Kadınlar anadır kadınlar eştir

Kadınlar bir melek kanatsız kuştur

Kadınsız bir dünya anlamsız boştur

Hayatın akışı yoldur KADINLAR

Kadınlar dünyadır hayattır bize

Onlar ile dağlar dönüşür düze

Sım sıcak sararlar kış döner yaza

Umuttur kanattır koldur KADINLAR

Çicek gibi açar mis gibi kokar

Onlar bir sevgidir gönüle akar

Hele bir severse yürekler yakar

Bilirsen kadrini güldür Kadınlar

Kadınsız bu dünya ne işe yarar

Anası Adnan''ı şevkatle sarar

Onlarsız geçen gün temelli zarar

Cennet ayağında kuldur KADINLAR', 'Yüce Yaratanın büyük bir lütfü Dünyalar tatlısı candır kadınlar Herşeyden öncesi annemiz onlar Yapraktır ağaçtır daldır KADINLAR Kadın dedim...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anneler-ve-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-sair-pirinc-o674u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç bu kadar yalnız kalmamıştım 

seni tanıyana kadar 

böyle teslim olmamıştım 

seni sevmeden önce 

sensizlik korkusu şimdi tek yoldaşım 

en yakın dostumsa 

yalnızlıgım', 'hiç bu kadar yalnız kalmamıştım  seni tanıyana kadar  böyle teslim olmamıştım  seni sevmeden önce  sensizlik korkusu şimdi tek yoldaşım  en ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödedim', 'odedim-sair-pirinc-z099p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'korkuyorum 

düşündükçe yaşadıgımız onca güzelliği 

mutluluktan ürperiyorum 

okyanusta fındık kabuguyum 

titriyorum 

sen korkma tılsımım 

ıhlamur dallarımdaki ılık esintim 

güç ver bana 

gülümse 

her şeyin bedeli var 

ben hepsini peşin ödedim.', 'korkuyorum  düşündükçe yaşadıgımız onca güzelliği  mutluluktan ürperiyorum  okyanusta fındık kabuguyum  titriyorum  sen korkma tılsımım  ıhl...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/odedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta', 'karanlikta-sair-pirinc-brb45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu kış gecesinde biz bize oturalım 

eskilerden konuşalım 

nasıl tanıştıgımızdan 

nasıl seviştiğimizden 

nasıl vazgecemediğimizden 

lambayı yakmayalım 

aramıza ışığı bile sokmayalım', 'bu kış gecesinde biz bize oturalım  eskilerden konuşalım  nasıl tanıştıgımızdan  nasıl seviştiğimizden  nasıl vazgecemediğimizden  lambayı y...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karanlikta-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefine', 'serefine-sair-pirinc-x1uva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk var sende 

kadehte dudak 

dudakta heves 

şerefine deniz yıldızım', 'aşk var sende  kadehte dudak  dudakta heves  şerefine deniz yıldızım...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/serefine-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğim Buralardan', 'gidecegim-buralardan-turkan-yakin-0ebiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gideceğim buralardan,

Umudumu gömerek.

Özlemlerimi yok ederek.

Kahırlarımı sindirerek.

Gideceğim buralardan,

Gurbetimi acıtarak.

Kayıplarımı toplayarak.

Kalanlarımı düşünerek.

Gideceğim buralardan,

Belki''lere sığınarak.

Sığamadığım yerlere,

Gönlümü küstürerek.', 'Gideceğim buralardan, Umudumu gömerek. Özlemlerimi yok ederek. Kahırlarımı sindirerek. Gideceğim buralardan, Gurbetimi acıtarak. Kayıplarımı...', ARRAY['Türk Edebiyatı','Şiir','Türkan Yakın']::text[], 8.5, '{"poet":"Türkan Yakın","poet_slug":"turkan-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidecegim-buralardan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-ali-kaybal-fly79', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutlu olmakdı hedefim, sevmeye yar geliyor,

Bir ateşdim yakarım, lakin ona kor geliyor,

Çırpınırım sevdam için, yinede hor geliyor,

Ruhumu sıkar dünya, onsuz bana dar geliyor,

Cennete giremem yarsız, ölümse zor geliyor.

Dermani bakarım gözüne, yeşerir yer demiyor,

Toprak olur basılır, aşkın yerde gör demiyor,

Deli gönlüm avare olmuş, sever dur demiyor,

Fark etmesen beni,duymasa hisler, kör demiyor,

Söz dinlemez kalbin, sevene umut ver demiyor.', 'Mutlu olmakdı hedefim, sevmeye yar geliyor, Bir ateşdim yakarım, lakin ona kor geliyor, Çırpınırım sevdam için, yinede hor geliyor, Ruhumu s...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-olur-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arınma', 'arinma-sair-pirinc-jqrjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kimi sevdiysem 

gölgesi düştü üstüme 

tozunda izim kaldı 

sevmekten sevişmekten yorgun istanbul 

bir kış günü ikindi vakti 

kabristan ziyareti 

kafir aklımla dua okudum 

topraga uzandım 

soyundum 

öldüm 

dirildim 

arındım', 'kimi sevdiysem  gölgesi düştü üstüme  tozunda izim kaldı  sevmekten sevişmekten yorgun istanbul  bir kış günü ikindi vakti  kabristan ziyare...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arinma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dümdüz', 'dumduz-sair-pirinc-isv62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kestirme yollardan yorgun 

serseri oklarla delik deşik mormaviliğim 

sağa sola sapmadan 

sonuna kadar dümdüz 

Şehriyarın binbir gece aşklarından 

ne bir yüz ne de bir iz.', 'kestirme yollardan yorgun  serseri oklarla delik deşik mormaviliğim  sağa sola sapmadan  sonuna kadar dümdüz  Şehriyarın binbir gece aşkları...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dumduz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ugur Mumcu''ya', 'ugur-mumcu-ya-sair-pirinc-39kvh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'acı..... 

düşündükçe... 

yandıkça... 

genzinde.... 

ıslak bir kara duman.... 

anladıkça.... 

yeldeğirmenlerine karşı... 

yılmayan onurlu savaşçıları.... 

ağlamaktan utanarak yutkunmak....', 'acı.....  düşündükçe...  yandıkça...  genzinde....  ıslak bir kara duman....  anladıkça....  yeldeğirmenlerine karşı...  yılmayan onurlu sav...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ugur-mumcu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-oktay-baykurt-xprfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...ben sana kendimi anlatmaktan acizim

suyu bekleyen çiçekler kadar aciz

ama güzelim işte

içimdekiler leylagil

senin vazondan dışarı çıkmadı köklerim

başka evlere dalmadı gözlerim

... 

hamur içtim elinden

 pastalar yedim rüyalarda

bilmedin

durmadın, düşleri inatlara  peşkeşledin

...

oysa ben senin sevgine yan çizmedim

kaçtım

kurtulduğumu sandığımda ellerinde kaldım

üşüdüm

derdimi anlatamadım

dinlemedin

kolumdan tutana

sırtıma zorla binene baktın

söylendin

    kulaklarını boşluğa küpeledin

hatırladın

hatırlattın

ben de bundan içimi acıttım

...

artık yeter 

çiçeklerim yenilendi

vazoların kırıldı say

saksı  aldın say

çiçeksem evinde

su getir artık bana

ne olursun

her şeye rağmen yine de seni seviyorum', '...ben sana kendimi anlatmaktan acizim suyu bekleyen çiçekler kadar aciz ama güzelim işte içimdekiler leylagil senin vazondan dışarı çıkmadı...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-seviyorum-346-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara ekspresi', 'ankara-ekspresi-sair-pirinc-pdnxs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'denizde fırtına havada bereket 

bır cuma akşamı gece treniyle 

başka bır sehre hareket 

ilk ve son kez göz göze oturup 

duvar dibi masalarında 

yabancı sokaklarda birbirimizi arayış 

bir kucuk otelde sabaha kadar 

bildiğimiz tatların yenilenen tadı 

yenı tanış ınsanlara onaylatıp 

bir gece treniyle ellerin ellerimde geri döndüğümüzde 

şehir bizi beyaz gelinliğiyle karşılasın....', 'denizde fırtına havada bereket  bır cuma akşamı gece treniyle  başka bır sehre hareket  ilk ve son kez göz göze oturup  duvar dibi masaların...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ankara-ekspresi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığı', 'ayisigi-sair-pirinc-pnzme', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki başlarınaydılar 

bir orman kuytusunda 

sabaha dek seviştiler 

su işitti..kıskandı.... 

yıkandılar ay ışıgında', 'iki başlarınaydılar  bir orman kuytusunda  sabaha dek seviştiler  su işitti..kıskandı....  yıkandılar ay ışıgında...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayisigi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatistanbul', 'anlatistanbul-sair-pirinc-9urem', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur çiseliyordu 

Nevizade akşamında 

Az içecek bol konuşacaktık 

Bana verdiklerin 

Senden esirgenenler 

söyleyemedim 

hep peşimdeydin 

Sana döndüm her seferinde 

Hep sen ordaydın 

İnanmadım..inanamadım... 

Sonunu yazmadıgım masallara 

Sen yine de anlat Istanbul...', 'Yağmur çiseliyordu  Nevizade akşamında  Az içecek bol konuşacaktık  Bana verdiklerin  Senden esirgenenler  söyleyemedim  hep peşimdeydin  Sa...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatistanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-ufuk-bayraktar-o7q1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düşün ki

insan konuşabildiği kadar insan.

kelepçe ellerde değil dillerde,

düşün...

bir farkın var mı kara yılandan

değişmeyecekse

kara yazın.

düşün ki

insan yazabildiği kadar insan

kalemler hüküm giymiş

düşün...

ne farkın var uçan kuştan

özgürlük

gökyüzünde sınırlıysa.

düşün ki

mevsimler değişiyor durmadan

boş oturma öyle

yazın değil

kışın değil

her gün düşün,

her gün düşün

çoktur işin...

ve düşün ki

düşün gerçek olmuş bir gün.', 'düşün ki insan konuşabildiği kadar insan. kelepçe ellerde değil dillerde, düşün... bir farkın var mı kara yılandan değişmeyecekse kara yazın...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dusun-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son satır', 'son-satir-sair-pirinc-t617h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kağıt bitmesin diye 

Son yazdıgım cumleyı yazdıkca siliyorum 

Hayatı oyalama oyunundan sıkılınca 

Golgeli bir sokakta eski bir ev benzeri 

Taş taş sökulecegim….', 'Kağıt bitmesin diye  Son yazdıgım cumleyı yazdıkca siliyorum  Hayatı oyalama oyunundan sıkılınca  Golgeli bir sokakta eski bir ev benzeri  T...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-satir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Not Defteri', 'not-defteri-nuray-acar-rurtb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklımdaki not defterine 

baktım dün şöyle bir

neleri yapmıştım eksiksiz,

neleri de umursamadan 

yok kabul etmiştim.

Sonra üzerini çizdiklerimi

hangi renk kalem ile dağıtmıştım.

Silinen ya tepesi olmuştu ya kuyruğu

kelimeden geriye not niyetine kalan.

Nokta koyduklarımı

artı işareti ile yıldızlarla donattıklarımı

ve hiç dokunmadan öylesine

zaman içinde silikleşen 

isteklerime baktım.

Hiçbir iz, işaret koymamıştım

bunu kaydederken dahi peşinen

umutsuzlar kervanına atmıştım

boş bir çaba gibiydi notum.

İnanmak yapmak kadar 

etkiliymiş demiş bir bilenler

diyorum inandığınızı alın 

not defterine korkmadan

Boş yere not kalacaksa 

yazmayın 

notunu bile anımsamayın

hafızanızı işgal etmesin

Düşünce denizinde 

not niyetine batırdıklarınızı

Titanik faciası ölenlerinin 

yalnız soğuk ve kimsesizliğinde

bırakmayın derim.

Bunu da not alın lütfen 

çok yıldızlı ve parlak olsun

göze çarpsın ilk bakışta

ve unutulmasın

zamanla.', 'Aklımdaki not defterine  baktım dün şöyle bir neleri yapmıştım eksiksiz, neleri de umursamadan  yok kabul etmiştim. Sonra üzerini çizdikleri...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/not-defteri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 84', 'guncel-beyitler-84-huseyin-avdic-5ebia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Mesnevî Kur''an Mi'' Diyene

Yanliz ayetler degil, ilhamlar da Allah''tan iner.

Mesnevî de Allah''tandir, mümin bunu ayirdeder.

Berlin, 1 Mart 2006.', '''Mesnevî Kur''an Mi'' Diyene Yanliz ayetler degil, ilhamlar da Allah''tan iner. Mesnevî de Allah''tandir, mümin bunu ayirdeder. Berlin, 1 Mart 2...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufak Dilenci', 'ufak-dilenci-funda-sag-5sugu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufak bir dilenci gördüm sokakta

Acıdım, biraz para verdim.

Önündeki paraya baktı

ve birde yüzüme

“Al” dedi alaycı gülerek,

“Sen bendende fakirsin, şükrettim Rabbime.”

Sıkıştırdı elime paramı

“Git” dedi,

“biraz mutluluk al kendine.”

Halbuki ben bunun için gelmiştim ufak dilenciye

Ama o bile acıdı

Acıdı bu halime…', 'Ufak bir dilenci gördüm sokakta Acıdım, biraz para verdim. Önündeki paraya baktı ve birde yüzüme “Al” dedi alaycı gülerek, “Sen bendende fak...', ARRAY['Türk Edebiyatı','Şiir','Funda Sağ']::text[], 8.5, '{"poet":"Funda Sağ","poet_slug":"funda-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ufak-dilenci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyitimsi Sözler 15', 'beyitimsi-sozler-15-huseyin-avdic-roh85', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya

Ölümlüler diyaridir bu cazip ve kâzib dünya.

Ötesizler icin olacaktir birgün hersey rüya.

---------------

Kâzib: Yalanci, aldatici.

Ötesizler: Âhiret inanci olmayanlar.

Berlin, 3 Mart 2006.', 'Dünya Ölümlüler diyaridir bu cazip ve kâzib dünya. Ötesizler icin olacaktir birgün hersey rüya. --------------- Kâzib: Yalanci, aldatici. Öt...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beyitimsi-sozler-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur Yüz/lü/m', 'nur-yuz-lu-m-selcen-boyar-trqon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zorla sev diyemem

böyle çekip gidemem

sen gidersen nur yüzlüm

başkasını sevemem

zaman bize tanık olsun

aşk gitsin uzak olsun

sen bende kal nur yüzlüm

içim dışım sen olsun

yaptığım nedirki kara 

gözlerin yanında

yaşanırmı söyle

bu aşkın ızdırabında

aşk değilse ne söyle

bu çekilen çileler

yaşamaya değmezmi 

bu kadar güzel şeyler', 'zorla sev diyemem böyle çekip gidemem sen gidersen nur yüzlüm başkasını sevemem zaman bize tanık olsun aşk gitsin uzak olsun sen bende kal n...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nur-yuz-lu-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afganlı küçük kızmışım', 'afganli-kucuk-kizmisim-guler-atas-a8r43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni keşfetmek için 

Belki bir dergi kapağında 

Çocuk gözlerimi görmeniz lazım

Bütün dünya konuşmuş 

Küçücük yüreğimden

Gözlerime vuran korkuyu

Birde titrek bacaklarımı görseydiniz

Kendinden bile kaçamayan

Afganlı küçük kızmışım

Çok korkuşum

İşgalden olmalı

Başka nasıl dikkat çekerdim

Ayıp, günah,korku

Doğarken öğrendiğimdi

Gözlerim korkusuz nasıl bakar 

Ben bile bilmem

Gözlerimdeki yağmur sonrası

Yeşili arıyorsunuz

Dünyanın bütün renkleri silindi

Yaprak yeşili gözlerimden

Yıllar geçmiş aynada görmeyeli

Unutmadığınız gözleri

İşgal yeniden

Yine arıyorsunuz 

Kapak kadını olmam için

Burada kadınlar 

O kadar benzer birbirine

o kadar hayalet gibidir ki

Biz bile ayıramayız kendimizi

Gözlerimiz

Kapalı bir çerçevenin arkasında

Çerçevedende bakmak yasaktır bana

Ayak sesim bile düşmandır

Benim olmayan bedenime

Kimliksizim işte

Kim olduğumu bilmeden

Savaşlar atlatmışım

Afganlı yeşil gözlü kadın olmuşum

kim olduğumun önemi yok

kimliksizim zaten

Zaten işgal altındayım

Zaten bir çift gözüm objektiflerinizde

Bir de kadınım

Artık o fotoğrafı

Bedenimin ve ülkemin işalcilerine sunun

             ...............................29/03/2004', 'Beni keşfetmek için  Belki bir dergi kapağında  Çocuk gözlerimi görmeniz lazım Bütün dünya konuşmuş  Küçücük yüreğimden Gözlerime vuran kork...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/afganli-kucuk-kizmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Galiçya’da İki Can', '01galicya-da-i-ki-can-ahmet-yozgat-9mbt7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'B/...

Bir ben bilirim Galiçya’yı bir de Seyfullah.

Dokuz yüz on beşinde zamanın.

Kanlı kamanın, katil kasaturanın

Yani bilimum kesici aletin

Kabzasına kadar silme kızıl kana kestiği.

Savaşın yedi düvelde rüzgâr rüzgâr estiği.

Ve cehennemi ateşin cayır cayır...

Cesur canların sapır sapır...

Yani bizim daha on dokuzumuzda

Yar yanağındaki bir damla yaş gibi

Kızgın toprağa düştüğümüz

Mavzerlerin kundağıyla öpüştüğümüz...

Kısacası bir ben bilirim Galiçya’yı ağalar

Ve koca bir kıtayı doludizgin

Yani delidolu çiğnediğimiz yılları...

Bb/...

Bir ben bilirim o sırrı saklı Galiç’i ağalar.

Seyfullah’sa kitaba kanıyla tarih düşendi.

Üşendi soğuk siperle gerdeğe girmeye

Yar yatağından kalan beden sıcaklığımız.

Amma savaş bu, cehennemin adresi yani.

Sayın ki ateş çevresinde vurgun pervaneyiz.

Silme donanma fişenk, inadına cephaneyiz...

Bir gözümüz hayâl meyal

Diğeri zalim tetik...

Mavzerler ki Alaman çıplağı yani som çelik

“Ich liebe dich! ” oymuş dipçiğine gönlü kısır bir işçi.

Kasaturalara ise “Seni seviyorum” oymuş

Bir Uşak kiliminin “eli belinde” motifiyle 

Sayın ki kalbiyle bir gelin...

Azgın selin önünde durmak ne zorsa 

Galiç’i bir ben, bir de Seyfullah bilir ağalar

Biz ki yüreğimizi asmışız palaskalara

Yani kendi darımızı kurmuşuz Galiçya’lara...

G/...

Galiçya’yı bir biz biliriz ağalar.

Galiçya da işveli haspadır ve bizi tanır

Palaskalara taktığımız yüreklerimizden.

O palaskalar ki masif ve yağlı sahtiyan

Ve iki yandan barebellum’a raftır.

Sayın ki Cebel-i Kaf’tır Galiçya dağı

Öylesine yüce ve öylesine bulut barınır.

Taranır memlekette her tetik düştüğümüzde

Ucu çengelli bir mor zülüf eşzamanda

Yüreğimiz takılır ucunun kıvrımına.

Bir yaralı telli turna selam taşır.

Taşır ki namlu dolusu.

Tekmil Osmanlı ordusu

Taşını, toprağını bilir Galiçya’nın.

Bir ben, bir de Seyfullah bilir...

S/...

Seyfullah’ın nedense gözü seğirir siperde.

Bıyığı simli sırım onun

Gözü Bahr-i Adriyatik damlası.

Palaskasında asılı kaması her daim uyanık.

Yanık mı yanık yüreği memlekette.

Galiçya bilir Seyfullah’ın tekmil halini ağalar

Mavzerinden bilir, fişenginden bilir

Hakikatte bir dağ goncasının bile

Bir teline kıyamayan merhametinden bilir.

Ama ne yapsın Seyfullah? 

Bir sabah uyandığında buluvermiş kendini

Alazlı tandırlar harmanında.

Yanmamak için yakmak gerek.

Urup merd-i meydan narasını 

Yani ta yürekten “Ya Allah! ” diyerek

Galiçya’ya namludan bakmak gerek...

Gg/...

Hınzır gibi tanır ikimizi de Galiçya ağalar.

Yani Seyfullah ve ben

Gün görmeden daha

Konmadan bir nazlı kelebek olup

Yavuklunun yanağındaki pembe yaprağa.

Toprağa garkolmuş on dokuzlu  yaşımız.

Emsalimiz, akranımız ve bilcümle yaştaşımız

Sürülmüşüz bir yağlı merhem misali Galiçya yaralarına.

Ss/...

Garip Seyfullah siperlerle sözlenmiş.

Bense görücü usulüyle nişanlanmışım

Geceyarısı devriyelerinin cesaretine.

Galiçya ki dağı taşı ile tanımış kokumuzu

Bilcümle tertip, korkumuzu büküp dört büklüm

Karanfil yaprağınca sokmuşuz kulak ardımıza.

Yardımımıza koşmuş Yemen türküleriyle

Buram buram ıtır kokan o kutsal ölüm...

Galiçya tanır ikimizi de ağalar

Ölümü de tanır, şehit kardeşim Seyfullah’ı da

Beni de tanır ağalar kanlı kabirleri Galiç’in...', 'B/... Bir ben bilirim Galiçya’yı bir de Seyfullah. Dokuz yüz on beşinde zamanın. Kanlı kamanın, katil kasaturanın Yani bilimum kesici aletin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/01galicya-da-iki-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Hüzün Seferi', '01huzun-seferi-ahmet-yozgat-3vyvt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Y/:

Yahu halamoğlu

Öyle ve iyi diyorsun amma

Bir de bu yüzü vardır hayatın sen bilmesende.

Yüreğimde bir sonbahar rüzgârına teslim

Ve serseri bir kanat çırpışı gibi serçenin.

Hatta o canı bir sıkımlık serçenin

Gözlerinde unutulmuş ve kırık

Yani buruk bir sevda öyküsü vardır

Ben varım yahu ben! 

Çiçeğe kesmiş hüzünlerim var.

Katranla kirlenmiş yüzü perdeli anılarım

Ve puhuların mekanı virane yanlarım var! 

Yani bırak kantarmasını ve çelme atımın yönünü

Sen anlamasanda halamoğlu

Diyar-ı şiire yani seferim var hüznün eline...

Yy/:

Yahu halamoğlu

Doğru ve haklı diyorsun amma

Bir de arka yüzü var madalyon gibi hayatın.

Bir parça gökkuşağı var sedefi ağızlarda

Ve acılı yüreklerin saçağına konan gri serçeler...

Hatta o bir sıkımlık serçelerin

Kınalı gagasında unutulmuş ve utangaç

Yani Kalahari’de susuz kalmış hayâllerim var.

Ben varım yani ben! 

Puslu rüyalarımın alt ucunda

Derin ve kronik bir keder ülkesinin

Alacalı ve çorak haritası var.

Limansız bir şaşkın geminin

Çaresiz başıboşluğu var engin yüreğimde.

Yani çevirme yönünü kalyonlarımın

Sen anlamasanda halamoğlu

Diyar-ı şiire yani seferim var hüznün eline...

Yyy/...

Yahu halamoğlu

Kendince doğru diyorsun amma

Bir de soluk kahverengi sevdaları var hayatın.

Yüreklerin kırmızı sızısıyla boyanmış bir özlem

Turnalara inat gökyüzü mavilğinde bile külrengi...

Ve iki kanat çırpışı kaderi kekre bir serçenin.

Hatta o bir vuruşluk serçenin

İbrişim ekli saçlarına takılmış

Ve ışığı harmanlara saçılmış bir yıldızım var.

Ben varım yahu! 

Tersinden de okunan alınyazım var.

Yalnız bir sirenin yüreğinden çalınmış

Ve zaman içinde sırı kavlamış sevdalarım var.

Yani bir sedef tespih misali dizilmiş bu kervanı eğleme

Sen anlamasanda halamoğlu

Diyar-ı şiire yani seferim var hüznün eline...

Yyyy/:

Yahu halamoğlu

Öyle diyorsun amma

Bir de acı ile kırılmış son noktası var hayatın.

Ve yaranına kanadını armağan eden

Keremleyin özverisi var

Güneşten önce doğmuş sabırı ile

Katranlı kahrı göç yolunda kahvaltı niyetine

Yüreğinde demlemiş serçenin...

Hatta o  bir fiskelik serçenin

Acılı türkülere damla damla düşmüş

Ve ağustosta üşümüş ateşleri var.

Ben varım yahu! 

Göz rengime sürülen siyahi ebru isi var.

Şakağı temmuzda dahi buz tutmuş

Ve viranelerde unutulmuş bir ömrüm var.

Yani ıhdırma mayalarımı halamoğlu

Ölüme seferim var bu gün de.

Kıyamette tatmak üzre azık niyetine çantamda

Onulmaz kederlerim var...

Sen anlamasanda halamoğlu

Diyar-ı şiire yani seferim var hüznün eline...', 'Y/: Yahu halamoğlu Öyle ve iyi diyorsun amma Bir de bu yüzü vardır hayatın sen bilmesende. Yüreğimde bir sonbahar rüzgârına teslim Ve serser...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/01huzun-seferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Yedi Tepeydi İstanbul', '01yedi-tepeydi-i-stanbul-ahmet-yozgat-onxep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Bıçkın rüzgârların yaylavari avuçlarından

Bir tek yüreğini kapabilmiştim senin...

***

Kızıl kısrak İstanbul,

Yine kalem kalem sivri ve yedi tepeliydin...

***

Köyden yeni kaymıştı bu yakaya delikanlı yıldızım.

Ellerim kahır tezgahında sağırlaşmamıştı henüz.

Cam göbeği gözlerimse bileyli bıçak sırtı...

''Hüf ki hüf! ''

Cağaloğlu’nun çakırkeyif serkeşleri,

İnadına ve habire eterli tütün üflüyorlardı,

Ankara caddesinin ofset moru atmosferine.

Müteferrikanın basımeviydi ergen eylülümüm harmanı,

Yani bir lobum magazine,

Kalan yarım ''bin temel eser''ine vurgundu Sinan''ın,

Gözlerimse Sultanahmet kubbesi...

2/:

Sırtı çıplak İstanbul,

Yine mavi mermer rengi ve yedi tepeliydin...

***

Denizden yana kaçkın,

Ve bizden yana bıçkın rüzgârlar,

Alıp alıp Sarayburnu virajından ozon alışkını esrik esintilerini,

Tabanı üç numara delik ayaklarıma çarpıyordu.

Arsız arzularım mı? 

Büzülmemişti daha utancından bir Harem arabalı vapurunda.

Seni gördüğümde bir ibis eşeleniyordu Haliç''in Eyüb''e yakın cenahında,

Bir bey oğlu camlarına hohluyordu Vilayet’in,

Ve ıslak kırbaçlar çiziyordu parmağının ucuyla vapurun camlarına.

Seninse som ve altuniydi bedenin,

Siluetin sisler ardından uğrun uğrun bakıyordu yavuklusuna...

Bense kaçıp en son masaldan bir anka kanadında,

O bıçkın ve haşarı rüzgârların avcundan,

Bir tek yüreğini kapabilmiştim senin...

3/:

Turkuvaz hançer yapraklı İstanbul,

Yine cayır cayır yanmaya durmuştun hani,

En harlı ateşinde kendi külhanının...

***

Ben bir Niğbolu önünde  yıldırımlar savuran Beyazıt’ta,

Bağrıaçık bir arzunun hüzünhanesindeydim.

Ve kolayca bükmüştüm bileğini dünlerimin.

Günlerimin biri üzüm salkımı moru,

Diğeri cavidânî bir çare gibiydi,

Kederimin kudurgan ve şarap kekreliğindeki Sirkeci’sine.

Oysa acemisiydim sevda sahillerine bir yunus gibi vurmanın,

Çünkü sığırcık yavrusu bir köyden yeni yekinmişti kaderim.

Ama parmaklarımın dili pelteleşmemişti henüz.

Gönlümse yakmıştı Septe boğazında gemilerini,

Ellerini serenine germiştim takvimin galerisinde...

4/:

Haspa kaltak İstanbul,

Yine yaşmağının altından utanmaya durmuştun,

En rezil sevişinde yüksek kaldırımlı dükkanının.

***

Şu bildik Laleli’nin yıkık kahküllü ayak takımı efeleri var ya,

İştahla kesiyorlardı Çemberli''ye doğru kaykık afilerini.

Sufilerini rahleyi tedrisinden geçiriyordu,

Araboğlu Muhittin loş bir Fatih medresesinde.

Benimse hala kasaba kasaba kokan ellerim,

Kahır tezgahlarında sağırlaşmamıştı henüz.

Bugün denizden yana bereketliydim doğrusu.

Yırtık ozon ve ofset asiti kokan Marmara esintileri,

İltica ediyorlardı iskele altlarına lağımlı utancından.

Bense bir tek yüreğini kapmıştım senin,

O bıçkın rüzgârların avcundan...

5/:

Yedi tepeli şehir

Yine değirmi ve kıvrak kalçalı

Ve kulağı sahte küpeli yosmaydın.

***

Bense Aksaray’da

Mülteci bir duygunun darağacındaydım.

Sabahın alacasına bürünen ayağı nalınlı mahmureler,

Kederlerine binip binip  Cibali tütün fabrikasına

Ya da kapkara Karaköy’de

Kepaze bir mavi sise dalıyorlardı.

6/:

Yedi tepeli şehir,

İnkar etme boşuna yine bol virajlıydın,

Ve serseri hayatlara girip çıkan yollar ağıydın.

***

Dalgındı ne hikmetse Sarayburnu leventleri bu saatlerde,

Ki Barbarosvari bıyıkları kolan gibiydi onların fi zamanından beri,

Otuz üçlük yaşları ve tespihleri balmumu kehribariydi.

Marmara’nın hırçın dalgaları,

Belki sevincinden,

Belki de utancından,

Körtopal bir salsa dansının sarmalındaydı...

***

Seni gördüğümde çöpte bir sığırcık eşeleniyordu,

Bir silik suratlı adam camlarına hohluyordu Vilayet’in,

Ve adının ilk harfini çiziyordu parmağının ucuyla...

''A''mıydı, yoksa ''Z'' miydi yazdığı, seçemiyordum,

Ya da ikisinin arası bir şeydi işte...

Ama (gavur gibi biliyordum ki) ,

O gün som ve altunîydi bedenin.

Bıçkın rüzgârların avucundan,

Bir tek yüreğini kapmıştım senin...

7/:

Dersaadet yani Tarih-i Gılmani’nin İslambol’u

Yine kalemucu gibi sivri ve Endülüs mistiği minareleriyle

Sufî bir destan kahramanıydın sanki kitabı Akşemsettin''de...

***

Bense, vildanlar semti Fatih’te,

Son hicretten beri süregelen hüznüme giydirip bir neftî derviş baranisini,

Kıyama durmuştum sevdanın mevlevihanesinde.

Şu an köyüm uzak bir gelin duruşuydu aynada.

Ellerim kozmik bir yolculukta yıldız sağmadaydı.

Gönlümse soyunmuştu sahte elbisesini.

Gözlerim külhanda kor kızılı,

Kabaran ensem bıçak sırtı mor çeliktendi.

Ol vakitte Asitane geceleri saf ipektendi...

8/:

Konstantiniyye yani dersaadet,

Yine kalemleyin sivri ve flu mistik kuleleriyle,

Bizantik bir destan kahramanıydı sanki neoroma kitabelerinde...

***

Kulağının ardı karanfilli Karagümrük berduşları,

Ayaklarının topuğuna topuğuna,

Ve kaderlerinin ters dönmüş gözüne basıyorlardı.

Nedense Sarayburnu hırçındı o gün.

Dalgalar kaçıyorlardı Marmara’ya utancından.

Seni gördüğümde bir çelik ankor eşeleniyordu,

Bir zabıtkar camlarına hohluyordu Vilayet’in,

Ve dalgalar çiziyordu parmağının ucuyla denizler şahı.

Ama yine de som ve samaniydi bedenin senin.

Zamansız ölümlerin avucundan,

Bir mayıs ayının sona iki kala zümrüt renkli gününde,

Bir tek yüreğini kapmıştım senin...', '1/: Bıçkın rüzgârların yaylavari avuçlarından Bir tek yüreğini kapabilmiştim senin... *** Kızıl kısrak İstanbul, Yine kalem kalem sivri ve y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":132,"source_url":"https://www.antoloji.com/01yedi-tepeydi-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Aşk Ve Işk''ın Atları', '01ask-ve-isk-in-atlari-ahmet-yozgat-ysz5k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ö/...

Ölüyorum...

Sıyırıp aslı üryan ruhumdaki urbayı.

Burayı bırakıp size.

Hepinizi hapsedip acının ateşine

Zamansız ve tahta atlara biniyorum.

Canımı aşkın, ruhumu ışığın gözüne sürüyorum.

Yani ölüyorum...

Arz dürülüyor kısrağımın toynaklarında.

Önümde kambur ve sahtekar bir rahip 

Yalancı yüreği puslu ve aldatıcı bir ayna gibi

Habire asılsız işaretler dikiyor önümsıra.

Gözbebeklerim kavruluyor kör ışığında cehennemin 

Hayâl meyâl seçiliyor sonsuz dip

Kara bir ağız esner gibi açılıyor sisli güzergahımda

Her dalanı yutan azgın bir ummanlar gibi.

Ölüyorum...

Can savuran harmanlar gibi! 

Öö/...

Ölüyorum...

Şafakta veda ile seğiren şakağıma tüneyen

Davetsiz ama fedakar serçeleri gözüm ile sayarak.

Kayarak münâkiz iki dünyaya.

Hepinizin tutup sahte sevdalarınızdan

Çarparak hakikat denen yekpare bir kayaya.

Mekansız refreflere ve bozonik buraklara biniyorum

Aşkın ve ışığın üstüne sürüyorum.

Yani ölüyorum...

Malayani sözler risalesi dürülüyor dudaklarımda.

Karşımda paçasından irin akan bir rahip

Dudakları yarık ve kılıç kını gibi aralık

Kan ve irin harcı kusan bir çağlayan gibi

Habire tarif etmede yalancı adresleri.

O an lisânını öğretiyor bana sonsuz dip

Bereketli ve aceleci bir imam gibi.

Ölüyorum...

Kırılgan bir saman gibi! 

Ööö/...

Ölüyorum...

Yırtıp beynimi dağlayan aritmetiği.

Kırk gün kırk gecelik kimyayı döküp saçarak.

Açarak paslı kilitlerini

Hapsolduğum sahte hengamın

Ve ellerimin yalancı kınasını silerek.

Binerek kibirsiz refreflere

Aşkın ve ışığın ağzına sürüyorum.

Yani ölüyorum...

Ömür bir kitap misali dürülüyor arkamda

Altmış yıl sırtımda boşuna taşıdığım.

O an kadir, kıymet bilmez bir rahip

Yırtılan teklifini çalıp koltuk altına

Kin kusuyor sevdamın kehribar kadehine

Bin bir başlı ve kindar bir hecin gibi.

Yüreğimi sıvazlıyor o an sonsuz dip

Işığa batan elleri kocaman bir kahraman gibi.

Ölüyorum...

Mumu yatsı vakti sönen bir yalan gibi! 

Öööö/...

Ölüyorum...

Yarıp orta yerinden yekpare narı.

Aslı yemyeşil olan baharı boyayarak kırmızıya.

Delerek ilk boyutu en incecik yerinden.

Derinden ve o lahûtî türkülerin çağrısına uyarak.

Bin ayaklı, bin bir kanatlı atlara biniyorum.

Aşkın ve ışkın gözesine sürüyorum.

Yani ölüyorum...

Yalanlar bir körük misali dürülüyor rüyalarımda

Ve bir yıldız köpüğü gibi sönüyor

Gerçek sandığım kendim.

O an karanlık ve dipsiz bir kuburda

Kurşunlara eriyor o yalancı ve diken saçlı karanlık rahip.

Edep fener tutuyor gözümdeki galerilerde

Önümdeki bir teşrifatçı çiziyor yol haritamı.

Ve emiyor emiyor sevincimi sonsuz dip

Anamızın ak sütüyle dolu derin bir umman gibi.

Ölüyorum...

Mutlu bir adam gibi!', 'Ö/... Ölüyorum... Sıyırıp aslı üryan ruhumdaki urbayı. Burayı bırakıp size. Hepinizi hapsedip acının ateşine Zamansız ve tahta atlara biniyo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/01ask-ve-isk-in-atlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-serdar-ahmet-guzel-rt11c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arkana bakma diyorsun

Bakmam! 

Tarihimsin

Geçmişim

Sevda yolum…

Kalbime kazındın

Gönül yazım

Sen istesen de

Asla unutmam

Unutamam…

Unuttuğun anda 

ölürüm...

07.03.2006 saat: 15.25', 'Arkana bakma diyorsun Bakmam!  Tarihimsin Geçmişim Sevda yolum… Kalbime kazındın Gönül yazım Sen istesen de Asla unutmam Unutamam… Unuttuğun...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutamam-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Zadegân', '01zadeg-n-ahmet-yozgat-74mlp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

De–hey bre zadegân

Gün döner devran düşer.

Kopar kırk bin katlı ipeği talanın

Tespihler çığ olur doruklardan yuvarlanır.

O zalim bağdaşı dağların yekinir yerinden

Derinden homurdanır devleri arzın

Yazın dudakları bükülür kompleksli ovalara.

Yürür ceylan ürkekliğiyle sular

Damlalar sağnak sağnak ilenir.

Yarılır son sözünde gökler...

Öbekler talan olur hoyrat ellerde

Yıldırımlar tarar öfkesinin nükleik saçlarının

Kibirli beyinlere şimşekler düşer.

De–hey bre zadegân! 

Size de gitmek düşer...

2/:

De–hey bre zadegân

Gün gelir zaman düşer.

Tel tel ayrılır yekpare sanılan hengam

Her bir teli saman uğrusundan ırak.

Sararak kozmik bir makaraya

Sabırsız saniyeler hatıralarını.

Şerit şerit düşer,

Son zaman gözlerin alasına.

Yasına oturan olmaz siyahın

Beyaz ise pulsarları şahit tutarak

Yapışır sapına her anı ayrı biçen orağın

Ve kaosun ardınca gül üfüren dudağın.

An ortasına bin bir an

Yüreğin çavlanına damardan son kan düşer.

De–hey bre zadegân! 

Sana da yaman düşer...

3/:

De–hey bre zadegân! 

Gün gelir mekan düşer.

Kopar derleyici şirazesinden

Gücü çevreleyen sahte ihata.

Yıkılır en sağlam tuğlasından

Terle sıvanan ehram.

Firavun ağıt bile yakamaz

Yüreğinin bölünen simyasına.

Kırmızılar griye tebdil olur

Sıyrılır ayhanın sırrı.

Salyalı bir ateşe atılır.

Ben sandığın süslü fotoğraf

Kıyameti davet eder, arsız sofralar

Damara haram düşer

De–hey bre zadegân! 

Tepeye süslü dam düşer...

4/:

De–hey bre zadegân! 

Gün gelir öz can düşer.

Kıvrılır üç yüz bin kanatlı ışığın dudağı

Kokar duru odalarda alacakaranlık.

Bir anlık resimler eskir ve sittin yıllık

Ölü karlar yağar can çekişen dağlara.

Bir kertenkele yalar sabahın ertesini

Nazlı kuşluk küser ihmalkâr saatlere

Bir çınar ana sanar kendini 

Ve ağzı yumşak zamansız filizini

Dolgun memelerinden ateşle besler

Sesler uzaklardan bir kutlu ferman

Zaman ulak olur küheylanlara binerek

Savrulur harmanın deli yelinde bir havadis

Pis bir aralıkta dağlanır her bir yürek

Mazlum saatlerin ardından

Eyvahlıve ahlı zulüm düşer

De–hey bre zadegân! 

Bir sabah ölüm düşer...', '1/: De–hey bre zadegân Gün döner devran düşer. Kopar kırk bin katlı ipeği talanın Tespihler çığ olur doruklardan yuvarlanır. O zalim bağdaşı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/01zadegan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Taylasanlı Şamana Dair', '01taylasanli-samana-dair-ahmet-yozgat-ikwj1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ben ki...

Semavatta halkavî bir seyyahım.

Kısır ama doyurgan bir şamanım kevkebilinde.

Omzumda ferhatvari bir taylasanla

Taaa... Oradaki kozmik kayalardanım.

Siz ki...	

Işkırlaklarınızı mavi kanlı seccade edip

Uzanmışsınız istikbari kıskançlıklar üstüne

Acaba

Hiç düşünüzü hayra yordunuz mu? 

Karanlık salyalı bir gecenin rızasında

Beyninizden dalandığınız

Kuduz ve dost köpeklere.

Toprağı süpüren eteklere can–siperâne

Sindiğinizi duydum 

Cehennemin ilk ateşlendiği gün.

Sizler ki çok sevimli

Ve çok güzel kardeşlersiniz.

Bu inancı kırık ve tekinsiz istasyonlarda

Allah aşkına söyleyin! 

Neyi beklersiniz? ..

2/:

Ben ki...

Garizî bir gezginim aşk vilayetinde.

Gerçeği bir kepenek gibi yüreğine giyinen

Yalancı ama tekin bir şamanım.

Omzumda korkutvarî bir taylasanla

Taa... Oradaki kalyoncu fenerindenim.

Siz ki...

Sirius’tan ödünç apardığınız

Yoksul ışıklarınızı zebûn edip terkedilmiş yörüngelere

Gerçek sanıp sevişmedesiniz kendi dudaklarınızla.

Hiç pusla perdeli görüşünüzü hayra yordunuz mu? 

Vurulduğunuz  Yemeni ve sarışın kurşunlara

Dimdik durdunuz mu evdeşinizden helallik dileyip.

Sarışın sidik sinmiş dilsiz kumlara

Başınızı gömdüğünüzü duydum

Güneşin sönmeye yüz tuttuğu gün.

Sizler çok tatlı

Ve çok sevimli biraderlersiniz.

Söyleyin Allah aşkına! 

Ayın arka yüzünde neyi gözlersiniz? 

3/:

Ben ki...

Cemâdât içre bir taneyim skalasında mahlukatın.

Oralarda bir yerde oturan onurunun orta yerinden

Geçirip tespih ipi gibi dehşetengiz bir ekvatoru

Sabırlar diyarından koyun gözü derleyen

Yalancı ve dosdoğru bir şamanım.

Omzumda mikailvari bir taylasanla

Taaa... Oradaki yalnız kevkeblerdenim.

Siz ki...

İlişip beynî ummanınızın saçaklarına

Damlayı siren deryası sananlardansınız.

Acaba

Hiç hayâlinizi hayra yordunuz mu? 

Ya da Dicle’nin güzergahında durulduğunuzu

Kozmik bozgunların kaçkın toynağında

Sahte utkularla bezeli halaskaran sofralarına

Hükmen hükümrân kurulduğunuzu

Ve katreyi batman saydığınızı duydum

Mevcudâtın toprağa savrulduğu son gün.

Sizler çok saf

Ve çok safdil kardeşlersiniz.

Söyleyin Allah aşkına! 

Soğuk tandırlarında yıldız mezarlarının

Hangi sıcak somunları beklersiniz? 

4/:

Ben ki...

Bahren gelip yapay taşlarla sedd-i Çin ören illerinize

Berren gidici bir şamanım mahlukat evreninde.

Omzumda hızırvarî bir taylasanla

Taa oradan... Yani zamansız bir ülkedenim.

Siz ki...

Dehri bir bengiküheylan sanıp

Gümüşlü koşumlar dizmedesiniz ezeli.

Acaba

Hiç hissiyatınızı hayra yordunuz mu? 

Mekanik bir rüzgarda avrulduğunuzu

Sırı silik bir gözgünün gözünde

Kehkeşanın en ücra nahiyesinde

Ve kurda yem olanlar klanının sakiniymişcesine

Nurun yıldızdan, ziyanın aydan sağıldığını

Saydığınızı duydum

Ayın bedr olduğu herhangi bir takvimde.

Sizler çok safdil

Ve çok salak kardeşlersiniz.

Söyleyin Allah aşkına! 

Cehenneme en yakın bu son istasyonda

Hangi cenneti beklersiniz?', '1/: Ben ki... Semavatta halkavî bir seyyahım. Kısır ama doyurgan bir şamanım kevkebilinde. Omzumda ferhatvari bir taylasanla Taaa... Oradaki...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/01taylasanli-samana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '0 Ağalar Bizimkisi Şiir Klanı', '0-agalar-bizimkisi-siir-klani-ahmet-yozgat-2os3l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ağalar bizimkisi şiir klanı... 

Yani sıradan bir yalanı, 

Şiir diye dolayıp dillerine, 

Ellerine sahte bayramlık kınalar yakan, 

Yalancı şairler harmanı...

1a/:

Şiir ökseye tutulur burda, 

Bu uğurda üç beş can yanar... 

Önce kurulur acun... Kaleml ağlar, kamış ve divit kanar.Alem bu durmaz, oturmaz; habire ığırlanır; bir batıya, doğuya hem de bir kaç kez. Tez getirin ula uşaklar! Kuru ve temiz bir bez. Yanında obez bir karakazan içre sıcacık su-yu bengi ya da musluktan ve sıradan bir tas su. ''Haydi hu! '' deyin siz de edebiyat şıkhları. ''Hu hu da hu! '' İşte zamanı hurucun bu. Her burcun  bir yanında kızıllık...  Kızlık dediğin de bir zardır nihayeti. Eti, kemiği yoktur ki dilin. Söyler de söyler. Hele bi yol dinleyin beyler. Ne der kurbağalar göl sıfatında. Kır atında bir kavram şehzadesi. Katırlar sırtında fincan. ''Dur ay can! '' Ürkütmeyelim klanı. Sırsıdır söylemenin en büyük yalanı: Zira bir azdan ay doğar yalap yalap. Çalap, güneşi saklar sözler ardına. Şemsiyeler açılır kesilince yağmur. Umur dediğin kocakarı zamanı. Kuyuların çıkrıkları zorlanır görmek için umuru. Yağmuru bir köstebek tetikler. Uğur böcekleri ağlar, her damlada. Konya''da bir kör Ahmet, halay başında... Zim zım da zım zım! Sıra sendedir kızım. Her şey senin yüzünden. Kör hançerler türküye durur, Duran’ın ağıdı misali kurar darını kara Ali. Harfleri asar. Basar gırtlağına hecelerin. Artık sıra klanın mersiye ayinine gelmiştir. Bizimkiler, otururlar Isfahan’da bir kameriyye altına. Altın suyuna banarlar şahadet parmaklarını. Başlarlar hoplatmaya yürekleri. Kürekleri söz harcına dalar. Salar azgın atlarını sarayların seyis başları. Onlar sesten piramit ustasıdırlar. Yani yalancı kafiyelerin hastasıdırlar.

1b/:

İşte tam da benim yaptığım gibi

Dibi belli bir kasaba kuyusuna

Delirir ve sekizgen taşlar atarlar

Gün olur çıkarır diye biri...

2/:

Bizimkisi şiir klanı ağalar...

Yani koşuda en artta kalanı

“Şiir budur” diye dolayıp dillerine

Ellerine sahte ipek eldivenler giyen

Yalancı şairler klanı...

2a/:

Bizimkiler, alınlarındaki vadileri dayarlar yıldızların çatısına. Batısına doğan güneş resmi çizerler dünyanın. Kayanın en yumşağından oyarlar sert heykellerini. Ebabillerini dillerine dolayıp da fil suresinin Ebrehe’ye gizli ağıtlar yakarlar. Takarlar gerdanlarına kafiyenin sahte kolyesini. Böylesini hiç bir diyarın armadası taşımaz ama. Neyse. Bizim diyarın ise en sırçasında otururlar sarayların. Uyakların en naylonuna yumulurlar...

2b/:

İşte şimdi benim yaptığım gibi

Dibi belli bir tali yol kıyısındaki kuyuya 

Delirir ve dokuzgen taşlar atarlar

Gün olur çıkarır diye biri...

3/:

Bizimkisi şiir klanı efendiler...

Yani sebepsiz bir katran savaşından

Ve izleri kaybolan atlardan arta kalanı

Şiir diye dolayıp dillerine

Ellerine sahte güneşler çalan

Yalancı şairler harmanı...

3a/:

Bizimkiler, Atina’da otururlar da Olimpos’tan ses verirler. Evirirler gündüzü geceye. Her heceye takılırlar da koca bir içeriği es geçerler. Seçerek en sahtesini kafiyenin... ''Yok ebenin...'' diyeceği gelir insanın da, ''Vay be! '' diyeceği gelmez. Eğilmez bir Piza kulesi panoraması çizerler örneğin ulu camisine Diyarbekirin. en koygunu oradadır işte kibirin ve ''inn es sabirin! '' Ya sabır der zebercet ustası dilaver efendi. Bunların ya kendi ya da büyük büyük  babalarına kadar herkes şeyhül şuaradır zaten. yani altı keten üstü merinos. Şu Olimpos da ne yakışır şiire be...

3b/:

İşte şu an da benim yaptığım gibi

Dibi belli bir köylü sakanın yufka kuyusuna

Delirir ve otuz altıgen taşlar atarlar

Gün olur çıkarır diye biri...

4/:

Bizimkisi ağalar şiir klanı...

Taşları palamarlarla bağlayan hain bir köyde

Korsan köpekleri ortalığa salanı

Şiir diye dolayıp dillerine

Yani ellerine yanıltıcı yol haritaları alan

Yalancı şairler harmanı...

4a/:

Bizimkiler, hep de yüz geçirgenli ilistirler bozkırında gözlerini süzerler. Gezerler diyarı sevdasında makyajını bir kargo gibi yanağında taşıyan güzellerin. Şairlerin en hası Karaca’yı beğenmez de terkos başı aşklarını yazarlar. (Dedim ya işte Olimpos burayla da örtüştü.)    Azar azar azarlar ağustosta (Ya da kırklarında...) . Her hususta son söz yine onlara aittir.“İttir len! ” diyesi gelir insanın ama boğaz dokuz boğumdur. Şanlı bir doğumdur onlara göre şiir. Bir Osmanlıca’ya uzanırlar, bir öz Türkçe’ye. Ama en banâl kafiyeye yenik düşerler...

4b/:

İşte tam da benim yaptığım gibi, 

Dibi belli bir Gobi çölü kuyusuna, 

Delirir ve bin altıgen taşlar atarlar, 

Nasıl olsa çıkaramaz diye biri...', '1/: Ağalar bizimkisi şiir klanı...  Yani sıradan bir yalanı,  Şiir diye dolayıp dillerine,  Ellerine sahte bayramlık kınalar yakan,  Yalancı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/0-agalar-bizimkisi-siir-klani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Karac’oğlan Güzellemesi', '01karac-oglan-guzellemesi-ahmet-yozgat-wx2hy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

“Karac’oğlan der ki kolu bağlıyım...”

1a/:

Duygusundan dağlıyım ben de karaca gibi

Torosların en cebelinin basma eteğinden

Koyun gözü saplarıyla bağlıyım zirvelere.

Bizim oralar şimdi,

Bıyık donduran ayaz ayazdır

Ama güzelleri beyazdır inadına

Kutupta altı ay oturan kar gibi

Güneş ibrişimi gibidir haspalar...

Biz bilcümle dağlılar

Sereriz de yamacına esrik dorukların

Karanlıkta körkütük sevdalarımızı

Umudu cıgara diye dumanlarız.

Bizler,

Yani hepimiz birer Karac’oğlanız...

Alayımızın kolu bağlıdır kadersizliğe

Bağlıdır babam bağlıdır...

1b/:

Onun için:

“Karac’oğlan der ki kolu bağlıyım

Ciğerciği aşk oduyla dağlıyım

Mamalı’da bir Rıdvan’ın oğluyum

Kaplan postu geydiklerim kal demiş.”

2/:

“Karac’oğlan der ki bu kimin nesi? ”

2a/:

Biz de kızıl fesi kaykık giyeriz karaca gibi

Allarız pullarız iyi seçilelim diye düğünlerde

Püskülünü dipsiz kuyulara sallarız.

Bizim oralar şimdi,

Silme ela gözlü çiğdeme keser

Yani sarışındır saçı amca oğlu dağların

Şakakları ise ala kır küheylandır

Tırıs gibi şimdi

Yani rahvan gibidir doruklar...

Ama karayağızdır bilcümle dağlılar

Kahkûllerimiz ığırlanır başaklı tarlalarda.

Tarlada tırpana düşeriz de on beşimizde

Altmış üçümüzde cephede lorke oynarız.

Bizler

Hepimiz birer Karac’oğlanız...

“İnginden ve yüceden gelir sesimiz.”

Sesimiz babam sesimiz...

2b/:

Ondan sebep:

“Karac’oğlan der ki bu kimin nesi? 

İnginden, yüceden geliyor sesi

Eğilmiş pınardan doldurur tası

İçene veriyor bal karmakarış.”

3/:

“Karac’oğlan der ki yiyip içmeden...”

3a/:

On sekizinde geçmeden serden

Adam sayılmayız nazlı dilber uğruna.

Bizim oralar şimdi,

Tarhanayla sarmaş dolaş baldıran sofrasındadır.

Ortadadır ne varsa elde, avuçta

Kara kışta nirvana buhurdanında tandır

Ağustosta asırlık kuru çınarlı çıtak boynuz

Yani kar gibi yoğurt, buz gibi ayrandır.

Biz bilcümle dağlılar

Huş kalasında seferberlik türküsü çığırır

Sefertasında azık taşırız Galiçya siperlerine

Yani kaderin bize arkadaş diye verdiği yere.

Çünkü herkesle ortaklaşa bir baş soğanız.

Bizler

Hepimiz birer Karac’oğlanız

“Geçmeyiz muhannet köprülerden.”

Geçmeyiz babam geçmeyiz...

3b/:

Ondan kelli:

“Karac’oğlan der ki yiyip içmeden

Güzeller usanmaz konup göçmeden

Muhannet’in köprüsünden geçmeden

Düşelim de azgın sele gidelim.”

4/:

“Karac’oğlan der ki konanlar göçmez...”

4a/:

oldum olası biçmez bizim harlı tırpanımız

Tarlaların yeşil kaderlerini.

Bizim oralar şimdi,

O yüzden sarışın ve başak oynaşındadır.

Dereler utangaç utangaç akmada

Uğrun bakmadadır ela gönül köprüleri...

Buğday benizlidir biz dağlılar.

Yazın kış artığı yaylaya çıkarız da

Kışın ala yorgan sarınıp gurbetele ineriz.

Mayanın en hörgüçlüsüne biner

Güzelin en zülfü dolaşanıyla sarmaşırız.

Bizler

Hepimiz birer Karac’oğlanız

Ayrılıkların en cesurunu yaşarız yazgımızda

Yaşarız babam yaşarız...

4b/:

Ondan neden:

“Karac’oğlan der ki konanlar göçmez

Bu ayrılık bizle arasın açmaz

Bir kötü gönlüm var güzelden geçmez

Ne güzele doymaz gözüm var benim.”

5/:

“Karac’oğlan der ki garibim garip...”

5a/:

Serip içi nergis dolu mitilini yıldız altına

Laciverte efelenerek yatar dağlılar.

Bizim oralar şimdi,

Geceler boyu kızıl gözlü eşkıya ateşidir.

Mavzerler çatılır mağaraların yüreklerinde

Döşünün düzünde kurşun eğlenir dağların.

Cümlesi dağlıların

Donanma fişenklik çaprazlanırız.

Kasaturalarımızla keseriz tırnaklarımızı.

Kösele kütüklüklerimiz

Lebaleb intikam ve cinayet doludur.

Kuruludur meydan-ı siyasette bizim için darağaçları.

Halatlar saf kendir lifi ve has zeytinyağıdır.

Yani bir aşk uğruna fermanlıklarız.

Bizler

Hepimiz birer Karac’oğlanız.

Kollarımız yar boynuna dolanır ilk akşamdan

Dolanır babam dolanır...

5b/:

Ondan dolayı:

“Karac’oğlan der ki garibim garip

Garibin halından ne bilsin tabip

Akşamdan soyunup koynuna girip

Boynuna dolanan kollar öğünsün.”

6/:

“Karac’oğlan der ki işin doğrusu...”

6a/:

Uğrusu çifte çatar mavzerini dağların

Doğrusu ise yar diye sarılır alaman çıplağına

Yatar düşlerinde ya da mahpusta

İnce belli bardak içre içtiği çayla.

Bizim oralar şimdi,

Karakeçili ve salkım saçak göç yoludur

Mayalar katar katardır

Yavuklular hüma yavrusu...

İti, kopuğu, uğrusu

Kan davasında kan yağması vardiyasındadır.

Dardadır yani bilcümle dağlılar.

Parmağımızı kerteriz

Uykuya basılmamak için gece nöbetinde.

Kimimiz ise tuz basar yürek yaresine

Bundandır kan uykuyu yitirmişliğimiz.

Bizler

Hepimiz birer Karac’oğlanız

Celali avlarız da sağ böğrümüzde

Sol yanımıza döner eşkıya oluruz yar yoluna

Avlanırız babam avlarız...

6b/:

Onun yüzünden:

“Karac’oğlan der ki işin doğrusu

Gökte melek, yerde hüma yavrusu

Söyleyeyim ben de sözün doğrusu

Soyunup koynuna girmeye geldim.”

7/:

“Karac’oğlan der ki ama ne fayda..”

7a/:

Kayda geçmez Osmaneli kütüklerinde

Güneşin altında doğan bebeleri dağların.

Bizim oralar şimdi,

Kahırlı ve yapayalnız maraba mezarlığıdır

Pamuk pamuk ığırlanır Çukurova

Mayıs mayıs uzar zamanıTorosların.

Ağalar pekmeze banıp bıyık burandır

Kehribar tespih şakırdatandır başucunda hayatın.

Cümlesi dağlıların

Otururluz kıl keçeler üstüne

Hemen her gece yağlı kaykana ziyafeti çekeriz.

Ekeriz ardımızca

Ve her bir pınar başına

İnce sesli bağrıyanık Barak havalarını

Yani ağzı türkü rengi marabalarız.

Bizler

Hepimiz birer Karac’oğlanız.

Beliğini teker teker öreriz de yavuklularımızın

Ağıraksak zamanı çifter çifter atlarız

Atlarız babam atlarız...

7b/:

Ondan ötürü:

“Karac’oğlan der ki ama ne fayda

Irabet kalmadı yoksula bayda

Bu ayda olmazsa gelecek ayda

On’ki ayın birisinde gidelim...”

8/:

“Karac’oğlan der ki n’olup n’olmadan...”

8a/:

Hapsolmadan dürmez dağlılar tekmil

Namus uğruna, değişken ömürlerini.

Bizim oralar şimdi,

Ya asker sülüsü kaçkınıdır şubede

Ya da kanlısını doğrayan Haydar.

Cüssemiz maya potuğunca

Söz namusa yan bakmaksa

Yüreğimiz kesilir Toroslar kadar.

Biz dağlılar

Ölümüne ve inadına severiz sevdi mi.

Ölümse kapımızı çalanda sessizce

İbrahimleyin kurbanız Sina çölünde.

Kan gölünde yüzeriz de

Kırmızıdan kestirmeyiz urbalarımızı.

Yani kaderi tam topuğundan vuranlarız.

Bizler

Hepimiz birer Karac’oğlanız.

Uğruna ölürüz inanmışsak

Ve vurulmuşsak pınar başında uğrun bir göze

Ölürüz ulan ölürüz...

8b/:

İşte onun aşkına:

“Karac’oğlan der ki n’olup n’olmadan

Dost ağlayıp düşman bize gülmeden

Biri ölüp biri ile kalmadan

Ölecekse her ikimiz ölmeli...”', '1/: “Karac’oğlan der ki kolu bağlıyım...” 1a/: Duygusundan dağlıyım ben de karaca gibi Torosların en cebelinin basma eteğinden Koyun gözü sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":215,"source_url":"https://www.antoloji.com/01karac-oglan-guzellemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '00 A s u m a n’a Ş i i r l e r: 0 0 0 8', '00-a-s-u-m-a-n-a-s-i-i-r-l-e-r-0-0-0-8-ahmet-yozgat-775mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tayyiasumanlardayım

1/:

Ben, her gece Asuman,

Burada girerim de yeryüzü yorganına,

Her sabah ayın arka yüzünde / 40 fitte yekinirim.

***

Aman maviş göklü kız,

Bil ki bizim sayımıza göre değildir zaman.

Bilirim ki ben de bunu ucundan, kıyısından Asuman, 

Bire bin verir kimi seyyarelerde yoksul başaklar.

Her hasat ayında apansız bir tensora vurulur vakit.

Işıktır, karanlık yörüngelerde kaldıran yakasını sakosunun, 

Ömür ölçüsünü kaçırmış bir terörist yağmurun, 

Ve cesareti çift boynuzlu bir savaşçının, 

Sensoruna terkiden biner 300 bin kilometre bölü saniye.

Haniye dinerdi ağlayan sesi kozmoğrafik katların.

Şimdilerde bengi atların toynak türküsü kalmakta geride.

Ben Asuman...

Basiretsiz bir duygu ile bakakalırım, 

.......ziya ile yemlenen şeffaf atlara, 

............... ve o atların şerareli toynaklarına

......................ve de sana bittabî.

De be Asuman “Ya sen bana? ”

Söyle Allah aşkına sırlarını kitabî...

2/:

Ben her gece Asuman

Burda, gerçeğin ortasında başlarım rüya görmeye

Her sabah ders-i simya / sahife 40’da bitiririm.

***

Kozmik bir el ya da gözdür Asuman, 

Dizen kadere kare kare dijital fotoğrafları.

Dizer o el ve dizgisini zamanın rahminde saklar.

Sen ve ben susmuşken, sabah alacasında...

Melekudatta dokuz ay on günlük birim zamanda,

Bengiatlar koşuşur ve konuşurlar toynaklarından.

Tek boynuzlu bir sensor işte o anda, 

Yani Hızıraşırı tayyi zamanda, 

Golyat olur vuruşur çift boynuzlu bir savaşçıyla.

Gılmanik seyislerce dağlanır atların alnı.

Kaderin ibrişim makarası açılır delirmiş gibi.

Bir vildan başak derer Berzah tarlalarında.

Ben, o an Asuman...

Başıkesik bir duygu ile zamana bakakalırım, 

.......harmandaki kozmik rençber Vildan’a... 

.........Vildan’ın bire kırk bir veren lahuti başağına,

....................ve sana bittabî.

De Asuman, ya sen bana? 

Konuş Allah aşkına sırlarını kitabî...

3/:

Ben her gece Asuman

Burada dalarım hayalin Karadeniz’ine

Her sabah satürn / enlem 40’da çıkarım.

***

Her şey ve her kes onun izinde, 

İkrar da bir babayiğtliktir sevdiğinin dizidibinde, 

Yani aslında sahte bir kehanettir bütün dediğim. 

Elediğim yıldız çecidir her akşam darı arzide

O ki yalandır, bühtandır aslına arzın, 

Akandır seyyareler ortasındaki esiri tabakada. 

Unutma ki akbaba da dişler, arzdan artan kokuşuk organiyi,

Bırak lügatide kuburlara atılmış yaniyi, maniyi...

Ve zaman yaylasında yaylayan bengiatlara bak,

Tensordan abıhayat içerler radyasyon üfürüp. 

Geçerler buutlar arası yağlı gırtlaklardan. 

Tek boynuzlu bir sensor var ya hani,

Çift boynuzlu bir Zülkarneyn savaşçısına direnir.

Bilenir bir bilge Gılmanın elinde ezeli bilgi.

Göz, kendisini kesen ışığa döner.

İner gece, palaz olur, baş kor gündüzün dizlerine.

Gözlerine palazcığın, sürme olur kuant tozları, 

Kör bir Şuayib’in Kenan elinde.

Ben, Asuman...

Bel bel bakakalırım,

..........bakmadan bile gören kör Şuayib’e... 

.............ve o Şuayib’in ziyalı sürmesine, melul ve mazlum...

....................ve sana bittabî.

De Asuman “Ya sen bana? ”

Anlat Allah için sırlarını kitabî...

4/:

Ben her gece Asuman

Burda doğarım da annemin kucağına

Her sabah maverada / peron 40’da ölürüm.

*** 

Hatırla taman! 

Tam anında atlar bir muharibi zaman.

Aniden kaybolur göz önünden en, olmadı sen, 

Yiter gider alacakaranlıkta boy pos yükseklik.

Derinlikse vurulur bir zebanînin gözünün lazerine.

Sözlerine mil çekilen her bir an, Bizantik buutlarda,

Hibernetik bir çareyle emlenir. saharada, ebabil,

Bil agözümün mavi nuru bunu da...

Demlenir hamarat annemin sabah çayı, 

Kurulur bir Barak havasının düzüne zilzal sofrası,

Işık üç yüz bin km bölü saniyenin altına düşer, 

Emcekare bir daha tartar sırrını, soğurur yörüngeleri,

Elleri teneşire dökülür fiziğin efendisinin, donar eksi 273''de

Asırların yorgunluğu sırtında, bir uca çöker kırılarak, 

Zamansa kamburlaşır ve kıvrılır kendi postuna.

Kasfiyail ki, boynuzdan bir yağdanlıktır elinde savurduğu,

Çıka gelir baranisini sokak yıldızları arasından savurarak, 

Big bangın korozyonik menteşelerini yağlar, 

Gıcır gıcır ve melodik inler artık kapılar.

Ben ki, hapahap karşıkarşı Asuman...

Ümmi bir bilge gibi bakakalırım, peşinsıra, 

........ve bir elinden can damlayan Kasfiyail’e, 

..........tabi Kasfiyail’in açtığı Berzah kapısına, 

.................ve sana bittabî.

De be Asuman “Ya sen bana? ”

Ne zaman söyleyeceksin sırlarını kitabî...

***', 'Tayyiasumanlardayım 1/: Ben, her gece Asuman, Burada girerim de yeryüzü yorganına, Her sabah ayın arka yüzünde / 40 fitte yekinirim. *** Ama...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":110,"source_url":"https://www.antoloji.com/00-a-s-u-m-a-n-a-s-i-i-r-l-e-r-0-0-0-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '00 A s u m a n’a Ş i i r l e r: 0 0 0 9', '00-a-s-u-m-a-n-a-s-i-i-r-l-e-r-0-0-0-9-ahmet-yozgat-r0325', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mevlânâ Döner Şems''e Karşı

1/:

Felek, eflâkın tekilidir Asuman

Feleğin çarkı benim.

Dönerim... 

***

Her şey döner, 

Mesela, Atomik vilayette elektronlar döner, 

Alemin şarkada ve çılgın çocukları elktronanolar döner, 

Mevlânâ durur mu Asuman? 

O da döner Tebrizli Mecnun Şems''ten yana... 

Kor kızıl tandırlarda 25 milyon selsiyusta yana yana. 

1a/: 

Döner bilcümle mevcudat,

Sancılı güneşlerin bebeği, helyum taylarına biner, 

Kişner bir at, Karatay Medresesinin karataşlı burcundan,

Doğunca bir sabah beynime ufkun ucundan,

Bir altın saçlı koçandan uçurtur altunî kelebeği vilayet,

Evet, en kesif mavilerin kor kızıl örtüsü bin kez evet! 

Zira mutlu bir başlangıçtır bu,

Işığın hûrucundan.

Ve...

Savrulur ahir zaman sevinc’ile, 

Mevlânâ durur mu Asuman? 

Düzülür kainat yolunda kozmik kafile... 

O da döner Tebrizli Mecnun Şems''ten yana... 

Kor kızıl tandırlarda 25 milyon fahrenaytta yana yana.

2/:

Cisim, ercâmın tekilidir Asuman.

Cismin en altı benim.

Dönerim... 

***

Ağama diyem, Atomik vilayette bozonlar döner,

Bir deli çocukolur fizikte kuantik bozino döner,

Mevlânâ durur mu Asuman? 

O da döner Bistamlı Bilge Bayezit''ten yana... 

Kor kızıl tandırlarda 25 milyar kere bir o yana, bir bu yana.

2a/:

Bir yüzü yanık, bağrı berk ins cönge dalar, 

Savaş kösleri vurulur yörüngede, bakır gonglar çalar da çalar, 

Savaş arasında bile asırlık zırhlar yırtılır en berk yerinden, 

Hırçın savaşçılar aniden doğrulur kendi yapageldiğine şaşırarak, 

Ve üryan bir annenin sırf esir dolu rahminden.

Esner mahmurluğu yıldızların tozlu yerinin, 

Bir kutlu ses duyulur kabirlerce derinden, 

Ayakların altından çelinen arzın direğidir, o an...

Asuman’ın yani senin çatındır bu çatırdayan.

Ve...

Savran olur savrulur evladü adem hüzn’ile

İster istemez dizilir nükleik yolda kozmik kafile...

Mevlânâ durur mu Asuman? 

O da döner Bağdatlı Arif Cüneyd''den yana... 

Kor kızıl tandırlarda 25 milyon kere milyon yana yana.

3/:

Ömür, hayatın tekilidir Asuman.

Ömrün sahibi benim.

Dönerim...

***

Birinci doğu döner

Batının ikizi döner

Mevlâna durur mu Asuman? 

O da döner Bağdatlı Bilge Halid''den yana... 

Kor kızıl tandırlarda döner İlhan''dan yana, Selçuk''tan yana.

3a/:

Galaktik primerler selam salar inceden inceye.

Sim dolayıp diline gül soluyan yıldızlar suya iner geceden,

Sulanırlar son sabahtan som zeheb ile giderler,

İlk gecedenzifafı necm ile,  yemlenirler.

Ve gergefî bakışlarla ruh dokuyan o kızlar, 

Okurlar en dolaşmaz dilleriyle sureyi Zilzalı.

Ve...

Savrulur ümmeti nebi sevinc’ile,

Düzülür genomik yolda kozmik kafile...

Mevlânâ durur mu Asuman? 

O da döner Yesi köylü Ahmed Türkistan''dan yana... 

Kor kızıl tandırlarda 10 üzeri otuz üç silaş zamanda yana yana.

4/:

Kutûr, aktarın tekilidir Asuman.

Kutûrun mili benim.

Dönerim... 

***

Ruh öğüten hüsban döner, hasdurur çeribaşları, 

Muallakta tavaf döner, değirmende germişek döner,

Mevlânâ durur mu Asuman? 

O da döner Belh ilinden Hükümdar Etem İbrahim''den yana... 

Kor kızıl tandırlarda ateşte o yana, çiçekte öbür yana.

4a/:

Haneye tecavüze yeltenir bir keten tohum, 

Ezeli ve enfusî sekonderler ak izler dokur ıslak bir baraniye.

Çizgi çizgi açılır saoşyantlar, ak berzah ıstarındaki yoz karanlık.

Uzun yolun yolcusu şihablar yorulur ve ışığın sağrısına otururlar

Gelişigüzel bir güzergahta düşerler en geriye.

Kaç zamanlık kuantik bir sadmeyle çatlar atlas bir anlık,

Ezeli ve ebedi kuşatan “Kun! ” ile vurulur topuğundan, 

Yeryüzünde yitirdiğim yüreğimi kuşatan zalim tiranlık.

Ve...

Savrulur hulûsi kalp sevinç’ile

Düzülür arafi yolda kozmik kafile...

Mevlânâ durur mu Asuman? 

O da döner Ahmetfakılı Hoca Eşki Efendi''den yana... 

Kor kızıl tandırlarda bir Kanak''tan yana, bir Çanak''tan yana.

5/:

Kevkeb, mecerrenin tekilidir Asuman.

Kevkebin sakini benim.

Dönerim...

***

Atın terkisinde bolat tengirşek, tekerlekte aks döner,

Kabirde mevta, tekkede zikir döner,

Mevlânâ durur mu Asuman? 

O da döner Konya''da Sade Sadrettin''den yana... 

Kor kızıl tandırlarda 25 milyon kez pişer yana yana.

5a/:

Kaderinden dahi kaçkın bir şuvaz sinerek denizlere.

Kör bir cengaver kurşun döker cihanın o çürük temeline.

Yetişir ardısıra, galaktik bir dönemeçte, bozdoğanlı külünkdar,

Karayerde kafileden arta kalan bizlere.

Ay benizli bir güzelin canını almaya daha zaman var,

Alır ve al kına diye yakar lahutî ellerine.

Ve...

Savrulur cismü can hüzün’ile

Dürülür bela yolunda kozmik kafile...

Mevlânâ durur mu hele düşün bi kez Asuman? 

Ben durur muyum? Söyle Allah aşkına,  a ruh u can! 

***', 'Mevlânâ Döner Şems''e Karşı 1/: Felek, eflâkın tekilidir Asuman Feleğin çarkı benim. Dönerim...  *** Her şey döner,  Mesela, Atomik vilayette...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":124,"source_url":"https://www.antoloji.com/00-a-s-u-m-a-n-a-s-i-i-r-l-e-r-0-0-0-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamam Ben', 'dayanamam-ben-erdal-ozkan-29lt2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendini fazla özletme n''olur

Senin hasretine dayanamam ben

Yıkılır bedenim bu kalbim durur

Senin hasretine dayanamam ben

Senin hasretinden başka her acı

Gelsin dayanırım başımın tacı

Sensizliğin canım yokki ilacı

Senin hasretine dayanamam ben

Seninle olmak büyük mutluluk

Ne yorgunluk yıkar ne uykusuzluk

Nedir ki, yanında açlık susuzluk

Senin hasretine dayanamam ben

Damarda kansın bedende canım

Seninle çevrildi bütün her yanım

İnan bu sözüme yoktur yalanım

Senin hasretine dayanamam ben.', 'Kendini fazla özletme n''olur Senin hasretine dayanamam ben Yıkılır bedenim bu kalbim durur Senin hasretine dayanamam ben Senin hasretinden b...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dayanamam-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakır gözler', 'cakir-gozler-selcen-boyar-m0yfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir günde gözlerine,

bakmaya geleceğim,

o derin çakır gözlerin,

İçine gireceğim.

Damarlarından aşk olup

sel olup akıp gideceğim

Bir gün; 

o gözlerde

eriyip biteceğim.

Sonra gelip o gözlerde,

sosuza dek öleceğim.', 'Bir günde gözlerine, bakmaya geleceğim, o derin çakır gözlerin, İçine gireceğim. Damarlarından aşk olup sel olup akıp gideceğim Bir gün;  o ...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cakir-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildir Bana', 'bildir-bana-erdal-ozkan-obsq7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yanımda ol güzelim

Diken bile güldür bana

Ölsen peşinden giderim

Sırat bile yoldur bana

Bir parçasın bedenimden 

Vurulmuşum ta derinden

Getir içeyim elinden

Zehir bile baldır bana

Sen benim herşeyimsin

Aşım tuzum ekmeğimsin

İstediğim yalnız sensin

Başkaları eldir bana

Seviyorsan bu naz niye

Döndürme beni deliye

Sensiz geçen bir saniye

Mevsim değil yıldır bana

Kalbi olan herkes sever

Sevmek dünyalara değer

Bir başkası varsa eğer

Çok geçmeden bildir bana.', 'Sen yanımda ol güzelim Diken bile güldür bana Ölsen peşinden giderim Sırat bile yoldur bana Bir parçasın bedenimden  Vurulmuşum ta derinden ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bildir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Ama Toprak Oldu', 'sevdim-ama-toprak-oldu-doner-ozeke-l2jz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim yine toprak aldı 

Hayali gözümde kaldı 

Sanki ölecek ne vardı 

Yetim koydun gittin beni 

Anam Babam gitti derken 

Sende terk ettin erkenden 

Söyle ne istersin benden 

Yetim koydun gittin beni 

Gerçek sevenler ölmezmiş

Ölenler bunu görmezmiş 

Yaşarken sevenlerin 

Kıymeti hiç bilinmezmiş 

Yetim koydun gittin beni 

              DÖNER TEMÜR 

                 07.03.2006

                   ANKARA', 'Sevdim yine toprak aldı  Hayali gözümde kaldı  Sanki ölecek ne vardı  Yetim koydun gittin beni  Anam Babam gitti derken  Sende terk ettin er...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdim-ama-toprak-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyişine', 'gelmeyisine-koksal-akar-nrqdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geliver ayrılıklar çıldırsın, hicrân yansın; 

Çatlayan dudaklarım gözyaşlarına kansın…

Bilirim ilkbahardır ertesi hep kışların,

Sevenler matem ile büyütür sevdasını; 

Bu yüzden karanlıktır dünyası baykuşların…

Bu yüzden hicrân kokar efsunlu bakışların.

Kaç asırdır zindanlar sıladır güllerime

Kan damlar leyli güzel sensiz, hayallerime…

Öyle bir gel ki bana akan sular durulsun; 

Mecnun ki Leyla’sına yeni baştan vurulsun.

İster ab-ı hayat ol, ister damla damla gel; 

İster mutluluk getir, ister bitmez gamla gel! ...

Yeter ki gel yaralı yüreğimin bahtına,

Periler hayran kalsın eşsiz saltanatına…

Dökülsün gözyaşların nasırlı ellerime,

Kan damlar leyli güzel sensiz, hayallerime…', 'Geliver ayrılıklar çıldırsın, hicrân yansın;  Çatlayan dudaklarım gözyaşlarına kansın… Bilirim ilkbahardır ertesi hep kışların, Sevenler mat...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelmeyisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madem Ki Uyandın...Güneşine Çırpın', 'madem-ki-uyandin-gunesine-cirpin-sultan-i-nan-zo8cc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avuntular durun

  sıvasın kollarını bütün hüzünler

    bütün insansızlığınız

      bütün pisliğiniz 

        bütün namussuzluğunuzla

          salın kudurmuş köpeklerinizi

                      gelin üstüme

                    avuntular durun

susturamaz 

  sevdamı bu suskunluklar

    bu başkaldırma varken bende

      deler dağ taş

        örs olurda çekiç altında

           yinede sağlam basar 

               yere ayaklarım

avuntular durun

  ay başım parlayacak

    koparacak Nuh un ikinci tufanını

                   avuntular durun

geliyor üstüme yağmur yüklü bulutlar

  gümbür diye 

    gümbür diye

      döküyor içini tamda  ortasına kavganın

        geliyor üstüme

          geliyor elinde menekşeli akşamlar

            salkım saçak akasyalı bahçelerime

              dilinde hanımeli çatlakları

                dalında pıtlamış çitlenbik

                  harlayıp bağrımda yanan korları

                    ve atıp ateş böceklerini karanlıklarıma

                      yediveren dallarıma

                       gökkuşağı renkleriyle geliyor

susuyor içimde birden öfke

  gülüyor tarlada iki buğday

   iki somun tanesi

      avuntular durun

         bakın nede güzel

           parlıyor sularımda

             muştulu  kızıl güneş haresi

                            benbahar1111', 'avuntular durun   sıvasın kollarını bütün hüzünler     bütün insansızlığınız       bütün pisliğiniz          bütün namussuzluğunuzla        ...', ARRAY['Türk Edebiyatı','Şiir','Sultan İnan']::text[], 8.5, '{"poet":"Sultan İnan","poet_slug":"sultan-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/madem-ki-uyandin-gunesine-cirpin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maziden bir yaprak', 'maziden-bir-yaprak-zeki-altas-6bc27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kez daha araladım kapıyı.

Soğuk bir rüzgar düştü yüreğime.

Ateş avuttu içimdeki yangını.

Puslandı gönül camlarım.

İnce bir sızı kapladı bedenimi.

Islak gözlerle seyrettim.

Son kez  titredi bacaklarım…

Bir kez daha taşıdım dünyayı omuzlarımda.

Titredi yerler kunduralarımla.

Sevdalarım yiğitti,

yiğit kaldı anılarım.

Soğuk karakış akşamlarında.

Sonra,

en hayta hokkabazlar elinde,

savruldum boşluklarda.

Son kez kayboldum dipsiz deryalarda…

Bir kez daha araladım kapıyı.

Hayal meyal kavruldum mazide.

Boncuk boncuk terledi geçmişim.

Eridim,

güneş görmüş kar tanesi gibi.

Savruldum,

yaprak misali rüzgarlarda. 

Koştum girdaplara.

Dolandı başım dönmekten.

Son kez sarıldım köpükten umutlara…

Bir kez daha araladım kapıyı.

Tatlı bir bakış düştü gözlerime.

Kırmızı bir gülle devrildim,

düştüm yerlere.

Bir çocuk ağlaması çözdü beni.

Tuz buz oldu dağlarım.

Kahrettim geçmişime.

Son kez ıslandım hazan yağmurlarında…

Şimdi köhne bir gemiyim.

Bir köşede durmaktayım.

Bitmeyen bir şiir gibi,

dizelerde dolaşmaktayım.

Aleme bakar iken,

kederlerle coşmaktayım…

Son kez araladım kapıyı.

Son kez titredi bacaklarım.

Son kez kayboldum dipsiz deryalarda.

Son kez sarıldım köpükten umutlara.

Son kez ıslandım, hazan yağmurlarında…', 'Bir kez daha araladım kapıyı. Soğuk bir rüzgar düştü yüreğime. Ateş avuttu içimdeki yangını. Puslandı gönül camlarım. İnce bir sızı kapladı ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/maziden-bir-yaprak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03Salvador''la Birinci Unutulmuş Zafer Gecesi', '03salvador-la-birinci-unutulmus-zafer-gecesi-ahmet-yozgat-s3gkw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeşilin Baba Yurdudur Yürek

1/:

Ay usta! 

Her yivli ve sert yürek,

İşveli iştahların baba yurdu sayılır.

Ayılır unutulan sevdalar gün doğanda yüreğe,

Aşk ve tamburi cinayet vaktidir şimdi,

Rengin ve ahengin parmaklarında gezinen arzu.

Yağmur vilayetine sarışın çöl yağmadadır,

Ve ay, karanlık diyarlara ağmadadır Salvo can.

***

Doğurmadan toprağa Karlofça bozgununu hamile yürekler, 

Ve gecenin erli ve bereketli koyaklarına korkuyu...

Yürüyor yüğrük atlar alaimisemada,

Biteviye tevekkel canlar yürüyor sarı ışığa doğru.

Oysa ki biz hala durmadayız araf''ın gri tüpünde niye? ...

Haydi davran Salvador...

Zaman uğraş vaktidir lime lime ibrişimler üstünde,

Uğraşsa şehvetli renklerle  boyana boyana sevişmedir,

Keten boyalı yan yatık dörtgen yaylalarında,

Aç ve kızılcıksever gurur abidelerinin ölüme düşmesidir.

***

Burasıdır kalbe komşu kırçıl dağlar haritada,

Ki oysa baba yurdudur yeşilin,

Ve kel dorukların ak sütü gibi sütleğenlerin...

Doyurup samur fırçalarını bir bereketli oturumunda,

Dinine kadar aç ve kıraç yeteneklerin,

Sürmeliyiz ufuklar arasında şiirin ve resmin diline.

Yüreğimizi kabartan şu kahverengilikler var ya,

Vadi vadi ve yamaç yamaç kösemidir dolanan her sürünün...

Lan Salvador usta, 

Bin kenarlı dörtgenler hangi tonuna çalar gökyüzünün? 

2/:

Kadim bingbanglardan beri yürüyor ışık,

Ardınca sürünüyor gölge bittabi,

Ve altın orantı yüklü sivil mangalar resmi geçitte.

Sözün ve rengin cengi süregeliyor Levni''den beri.

Kavgacılar kan, ter ve açlık içinde, 

Güzergah boylarında kangalotu yeşillerinden yemleniyorlar.

Demleniyorlar savaşçılar Çin-ü maçin''de,

Ellerinde ince belli bardaklar görünüyor,

Şeffaf ve silme yürek sıvısı tarihin bu sokağı.

Haydi davran Salvador...

Fırça ve kaleme zümrüt panoramalar sürünüyor.

Ve şiir görünüyor simetrinin tıpkılaşan arka yüzünde,

Ve kaderiyle oynaşan cilveli yüreğinde...', 'Yeşilin Baba Yurdudur Yürek 1/: Ay usta!  Her yivli ve sert yürek, İşveli iştahların baba yurdu sayılır. Ayılır unutulan sevdalar gün doğand...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/03salvador-la-birinci-unutulmus-zafer-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03Salvador''la Birinci Tarih-i Gılmani Günü', '03salvador-la-birinci-tarih-i-gilmani-gunu-ahmet-yozgat-xw1q7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyor Atlar Alaimisemada 

1/:

Usta ve ben,

Kuantumla bire bir oynaşmadayız,

İzotoplar arasında bir topalak kalbimiz,

Bugün şiir ve rengin en kıkırdak alemindeyiz.

Kalbimiz yayan yapıldak alaimisemada,

Ahenk, söz ve renk ilinde akında şimdi,

Toynağımız kan-ü revan keten yaylasındayız.

Bugünü tekmil eden önümüz mutlu,

Menzilimiz yarınlarına ulaşmak, umutlu günün...

Lan Salvador usta de hele,

Esrik keten tohumları hangi tonuna çalar gökyüzünün? 

***

Sevdaları çize çize yürüyoruz yürek ipinde,

Kozmik gösterilerin sisli cambazları yüzüyor,

Haydi davran can Salvador...

Loş güzergahımızı salyalı kurtlar bürüyor.

Aşka davet eden bir cezbe var havada,

Son yıldız da siliyor gözündeki ışın kalıntılarını,

Karamsar anılar ıssız yüreklere ağıyor,

Yürüyor altın atlar alaimisemada...

2/:

Ay usta,

Terk etme arkada rakkaslanan yeleni,

Ey yağız rengin masif aslanı zamanı içme,

Ve tarihi talan ederek koru eski suretini bulunduğun sayfada.

Ve bizi bu ıssız ada da kınalı sevda ey! 

Yani gönül ülkemizde milim milim iç çekişen can,

Say ki hakanı sahn-ı çemendir Hermes vilayetinde,

Sol alt köşesinde yaşamın mor imza hatta...

Ondandır işte kor kor olmuşluğu yürek peronlarımızın,

Yüzümüzdeki arsız ve yüzsüz utancın kızarması ondandır.

Harlı hıncımız ise sermayemizdir ala renkli cephede,

İkimiz birden istesek de istemesek de,

Akrabadan biri sayılır aşk ve pekmez bıyıklı yiğit,

Doru dağlarda mukim buğday dilli kirvemizdir,

Turkuvaz tonlamada öptüğümüz hünsa fedakarlığımız.

***

Salvo can, kızıla çalıyor yarına dair umutlar,

Eşkin bir oynaklıkla yürüyor altın atlar alaimisemada...

Işıl ışıl görünüyor albenili ucu beklenen günün...

Lan Salvador usta,

Yüreğimizdeki altın damarı hangi tonuna çalar gökyüzünün? 

***

Usta ve ben,

Kuantumla bire bir oynaşmadayız,

İzotoplar arasında bir topalak kalbimiz,

Bugün şiir ve rengin en kıkırdak alemindeyiz.', 'Yürüyor Atlar Alaimisemada  1/: Usta ve ben, Kuantumla bire bir oynaşmadayız, İzotoplar arasında bir topalak kalbimiz, Bugün şiir ve rengin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/03salvador-la-birinci-tarih-i-gilmani-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03Salvador''la İkinci Teslimiyet-i Zifaf Gecesi', '03salvador-la-i-kinci-teslimiyet-i-zifaf-gecesi-ahmet-yozgat-eb58v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi Gri Gölgesiyle Savaşan Er

1/:

Bak ey can Salvo, 

Bir doğup bir batıyor alaimisema sevdamızın steplerinde,

Ve o toz renkli külünkdardır yine bulut üreten,

Eriyor Dandanakan''da kendi gri gölgesiyle savaşan aşkadamı,

Yani asırlardır döven sevda-yı kadimi Salvo can kimdir? 

Ağzı açılmış bataklığında yiter anılar zamanın,

Bizse kapanan kapılar ardında masal ilinin.

Bir asi Kimmer mızraklısıdır beynimizin muhafızı,

Ki bir yanı kızıl baldıran arazisidir aşk haritasında,

Arka yüzü mecazi hatıralar isi...

Ne is,

Ne de mızrak yıldırır gökyüzündeki kararı,

Deliren ve dönen kızıl gözüdür şiir ve resmin.

''Mitra'' boşa hışırdar loş tapınaklarda,

Persiyan''da Zerdüşt boşuna...

Ol nedenle,

Bak, bir doğup bir batıyor alaimisema,

Ama yağmurlar her daim aşktan evvel yağıyor.

Haydi davran Salvador! 

2/:

Ay usta! 

Tarih ağır aksak, renk ve cümbüş üzerine doğuyor,

Çifte boynuz verilmiş İskender''den öncede,

Sonra fenomenler beyi Zülkarneyn''den.

Ki odur, İskendernamelerde mersiyeleri mahmuzlayan,

Ve ki odur, devindiren balçığa yenilen güneşi,

Son güreşte arkalayan antimogog ve gog ehlini.

Ya senin aşkı sürünen samur fırçan? ...

Ey canlar canı Salvo can,

İsterim ki sekisi sarıya çalsın dere boyundaki atların,

Balçıkların nötrlüğü sıvanmasın taylara ve şiire,

Ben istesem de düğünlerde silah sıkılmasın göklere maviye inat,

Sonuçta iki kepçe arası bir kaval borusudur,

Hatta her akşamında kandiller yanar kasabaların,

Yani insanların, aklını yiyen cadılar yortusudur tüm eğlencesi.

Bak bu nedenle geğirerek doğuyor soğanın acı tarihi,

Ve nev-i beşer, gerdek gününü içiyor delirerek.

Nakaratı deviniyor yeknesak ve aynılaşan aşkların,

Deviniyor ve klasikleşiyor bildik teması o türkünün...

Lan Salvador usta dökül, 

Tembel gerdek geceleri hangi tonuna çalar gökyüzünün? 

Ay usta! 

Şiir göbek adı mıdır hüznün?', 'Kendi Gri Gölgesiyle Savaşan Er 1/: Bak ey can Salvo,  Bir doğup bir batıyor alaimisema sevdamızın steplerinde, Ve o toz renkli külünkdardır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/03salvador-la-ikinci-teslimiyet-i-zifaf-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Maviydi', 'gozleri-maviydi-ayhan-isin-bzbxf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülmek haram olsun,

Ölmek helal, 

Sen yoksan! 

Aşkta haram sevgide,

Gündüzlerim, gece

Geceler helal bana

Ölüm gelsin hoş gelsin,

Sevginin bittiği yerde

Kara toprak helal olsun

Ağzımı, burnumu, gözlerimi doldursun,

Papatyalar açsın gözlerimde

Fal tuttuğun papatyalar. 

Gübre olsun 

Bedenim,

Gözyaşlarım sulasın,

Sevmiyorum çıksın falların.

Sen duaya gel

Bir mezar taşında

Sevdi ama karşılık görmedi 

Öldü,

Gözleri maviydi

Yazsın…..

05-03-2006', 'Gülmek haram olsun, Ölmek helal,  Sen yoksan!  Aşkta haram sevgide, Gündüzlerim, gece Geceler helal bana Ölüm gelsin hoş gelsin, Sevginin bi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozleri-maviydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03Salvador''la İkinci Tarih-i Müneccimbaşı Günü', '03salvador-la-i-kinci-tarih-i-muneccimbasi-gunu-ahmet-yozgat-q3wll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçağız Manş Aralıklarında 

1/:

Bırak ivecenliği Salvo can,

Plan üzre kur piramidini çorak deltaya,

Gör ki can çekişmede şimdi titiz perspektif...

Şeytandır sanat, kimi zaman,

Ve karışır sel suyu gibi aciliyete yalapşap,

Hele bir dur ve kendine öykün fırçanın son izinde,

Ve dalgalı Atlantik kıyısında ince ince sus, 

Yani mantık aralığında düşün ve dinle beni bir zaman.

Kahır ve hüzünden kaçkın,

Hatta ihaneye sürgün muhayyilenin zamansız eteklerinde ırla,

Anlamsız bir türküyü dinlet şiir diye dervişlerine.

***

Ay usta! 

Bizde yalan yok.

Tarih bütün bunları ağladı ayaklarımıza,

Bizse gülümsedik can çekişen kısrağımızın yanı başında.

Anımsasana... 

İkimiz de deli miydik neydik, 

De bana ulan oğlum Salvador? 

Çünkü sever deliler birbirlerini derler ya steplerde bağdaş kuran bilgeler. Meğerse devri Mikelanj''dan beri tanırlarmış gözbebeklerinden dervişler, merd-i kıptileri ve seni Salvo can. 

1a/:

Dur, sus, düşün ve dinle beni. 

Biz,

Yani ikimiz...

Keten örgülü saçların tarlası mıydık diyarı Kaf''ta? 

''Yo! '' diyorsun. 

Ve ben-i esver kılıklı bir kuzeylidir şimdi zaman. Unutulmuş bir kavmin fertleri miydik seninle? Ne kadar antiktik tarih-i bidayette? Otuz sayfa mı? Yo! Birlikte mi geçirirdik iğne deliğinden deveyi? Ya da tarih-i Gılmani''de yazılı bir arsız vaka mıydık? Aktı mı bütün günülerimiz kol kola Gregoryu''tan? Yo! İyi ve kötü ne kadar zıttır birbirine ben bilmem. İyi ile damgalı zamanlarımız mı oldu? Veya kötüye aşık? ... Yo! Ayrılmaz mıydı sefineler sabaha karşı limanımızdan? Kanlı et ve alçılı tırnaklarımızdan akar şiir. Bu yüzden zalim töton kasapları eliyle ayrılır kurbanlıklar sürüden. Kim kaçar kaçak Manş aralıklarında? Ben mi? Sen mi? Şiir mi? Belki de resim? ... Yo! Yardımcı olur muyduk zor anlarımızda birbirimize. Jakont''un evinde ve son akşam yemeği davetlilerine vurgun muyuz mesela? Yo! İki samimi kardeştir renk ve söz. Omzundaki apoleti ve tepesindeki plastik kaskı ağır bulur bozgunda erat. Horoz tüylü bayraklar zafer sürünür yırtıklarına. Bu sırada alemdarların kan sızar yüreğinden. Biz o alemdar mıydık yoksa? Yo! Çok iyi miydik başlangıçta? Kanlı havari savaşında teşrifatçı mı? Yo! Ve hususi bir tarihtir yaşam. Biz ve Ferhat acar külünklerimizle yonttuğumuz kutsal yeşim taşları konusunda niye ağırdan alırız? Rüzgar mı tarihte yazılanlar? Yo! Geçinip gidiyorduk somut ve soyut ahenginde. Hiç kimseye muhtaç olmadan da yaşar yoksullar. Şehr-i Babil''de mesela? Biz miydik sözü edilen fakrü zaruret Yo! Fakat uzun sürmedi türkü. Kehanet ve yıldızlar mı kralımızın yol göstereni? Zamanın mübarek zaferlerinin tarihle dostluğu nedir? Yalan mı? Ya da tarih mi Yo! Zamanla yoksul hale mi düştü son kral? En sakini ülkemizin ve ikimizin kerpiçten hanelerimiz ne alemdeydi? Tipide yitmiş miydi yolumuz? Yo! Kurtulmak mı istedik renk aralığından? Ve son kavgada budanmış kollarımızdan? Yo! Başka yerleri mi özledik, mesela Şam''ı, örneğin şarkı veya şimalin buzlarında burulan kusurlu kentimsi yerleri ya da iberik''te herhangi bir meyhaneyi? Yo! Sonunda olacağı buydu güzelliğin. En olmadık bir zamanda karar verdik kaybolan ruhumuzu aramaya Salvo can? Doğru değil mi? Belki! 

1b/:

Öyleyse niye? 

Tutsak eder bizi ben-i esver kılıklı bir kuzeyli kavim? 

Ya da ne diye töton kasapları eliyle doğranırız? ...

Ulan oğlum Salvador deliyiz ikimiz de. 

Durma davran öyleyse,

Beklemeye gelmez Şehr-i Babil''de...', 'Kaçağız Manş Aralıklarında  1/: Bırak ivecenliği Salvo can, Plan üzre kur piramidini çorak deltaya, Gör ki can çekişmede şimdi titiz perspek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/03salvador-la-ikinci-tarih-i-muneccimbasi-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '03Salvador''la Üçüncü Zaliman-ı Kimmeryan Gecesi', '03salvador-la-ucuncu-zaliman-i-kimmeryan-gecesi-ahmet-yozgat-l3crn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zifirin Katranla Akrabalığı

1/:

Ya Vinci''den evvel bilmem kaç,

Ya da sonrasındaydı Vinci''nin...

Kabzası gümüşlü Kerem''in aşk hançeriyle vuruldu aşk adamı,

İnadına utançsız ve de inatçıydı Tiflis keşişi,

Oyuyordu bir duvarcı ustalığıyla  dağları Ferhat,

Ve geceyi tarih-i kibarda keskin bir yelkovan...

Aşkın atlıları koşuşuyor söz ve renk vilayetinde,

Günleri tekdüze ışık yoluna evirerek,

Kimmer mızraklısı seviyor delirerek,

Bir elinde son uğraşta dökülen kalbi,

Diğer ezberinde geleneksel öyküler hönkürmede...

2a/:

Zifirin katranla akrabalığı aşkla nefret gibidir,

Aç ile tokun hısımlığına benzemez yaşam aralığında.

Ya da şiirle resmin... 

Müezzin kuşunun ''hyle hyle'' ötüşü bundandır işte,

Eflatunun mor ile akrabalığının sırrı maviye çalar,

Acı ve kahır yüklü ve de buhurdandır Semerkant raması.

Hüzünlü akşamlar şiir ile beslenir ışığın ülkesinde.

Bak ey yoldaş bulutlara bulanıyor sureti günün...

Lan Salvador usta hele de,

On kıratlık kahır hangi tonuna çalar gökyüzünün? 

Ay usta! 

Şiir göbek adı mıdır hüznün? 

*** 

Bakıyorum şehla bir hatıradan,

Ve görüyorum sisler ardından kızıl Sibirya''yı ben,

Ya sen? 

Zifirin katranla akrabalığını irdelemedesin,

Analizindesin ürkek yıldız şualarının mavi altında.

Tedirgin görünüyor ellerin grand kanyonda oysa,

Remil açılırsa şiirin ayak ucunda,

İnsani bir tekellümdür sonuçta seninki de,

Fakirinki ise bir mart soğuğunda şiire pekmez karıştırmaktır,

Ol sebepten soluyor kızıl kıyamet vakit varken sonbahara,

Zaten geceleri karanlıklar da kendisinden korkuyor.

Geliyor kaçma vakti ana renkler alemine usuldan, 

Haydi davran Salvador...

Yürüyor şiir kervanı.', 'Zifirin Katranla Akrabalığı 1/: Ya Vinci''den evvel bilmem kaç, Ya da sonrasındaydı Vinci''nin... Kabzası gümüşlü Kerem''in aşk hançeriyle vuru...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/03salvador-la-ucuncu-zaliman-i-kimmeryan-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gez illa gidilecekse durakların', 'gez-illa-gidilecekse-duraklarin-seckin-turk-ndfs9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gez illa gidilecekse durakların,

bekle otobüsün en gelmezini, durağın en sahipsizinde! ! 

anla ki o sevdaya denk değil yüreğin,

anla ki sıkmakla suyu çıkmaz azmin, içilmez suyu duvardan akan yağmurun! !', 'Gez illa gidilecekse durakların, bekle otobüsün en gelmezini, durağın en sahipsizinde! !  anla ki o sevdaya denk değil yüreğin, anla ki sıkm...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Türk']::text[], 8.5, '{"poet":"Seçkin Türk","poet_slug":"seckin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gez-illa-gidilecekse-duraklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir TOPAK Beyaz UMUT', 'bir-topak-beyaz-umut-gul-yazganarikan-etmsp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir topak umuttun bembeyaz

Tepenin en yükseğinde

Elimde sen, yerler buz, içimde yaz

Üşüdükçe yanar avuçlarım

erirsin olursun ayaz

Avuçladım seni umuttun bembeyaz

Sonra Uzandım 

Yuvarlandım

Dondukça uyudum 

Dondukça yandım...

Bir gürültü koptu en tepeden 

Böyle gürlerken seni hiç görmedim ben...

Üstüme üstüme geliyordun

Geldikçe büyüyordun

Oysa bir topak umuttun bembeyaz

Yakaladın beni topuklarımdan

Yeri çekip aldın ayağımın altından

Kocaman olduk sandım

Yanıldım

Bembeyazdın nasıl birden karardın

Donuyorum dondukça yanıyorum...

Avuçladım seni son gücümle

Tükendi nefesim siyahtı renginde....

Oysa bir topak beyaz umuttun elimde...', 'Bir topak umuttun bembeyaz Tepenin en yükseğinde Elimde sen, yerler buz, içimde yaz Üşüdükçe yanar avuçlarım erirsin olursun ayaz Avuçladım ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-topak-beyaz-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenişim Sana 11', 'seslenisim-sana-11-zeliha-bicer-7n56d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen yüreğine sığamazsın dar gelir.  Hem yürek hem de kendin. Kıstırılmış

bir hayvan gibi çırpınırsın çaresizce çıkışı  varmış gibi.

Seninle yine Salacak taydık. Çaylarımızı içtik. Seyrettik doyumsuz İstanbul u

elimi tutmuştun yine eskisi gibiydik sanki. _Bana ölümden bahsetme_ diyordun. Kızgın gözlerinle. _ Ha ben gittim ha sen hangimiz unuturuz birbirimizi_ diyordun.

Haklıydın. Unut muşmuydum seni? Sen benim ilkimdin. Sen yüreğime düşen cemrem gibiydin, baharı müjdeleyen.

Hani olgunlaşır ya insan, hani başka sevdalara yelken açar ya kimi zaman. O sevdalarda aşkı yaşıyorsun. Başkalarıyla paylaşıyorsun yaşamını. Kimbilir doğrularımız o dur belki. Ama ilkim sen, seninle yaşadıklarımı kimse vermiyor. Özlemiyor kimse beni senin gibi. Özlemiyorum tutkulu gecelere inat başkalarını sen gibi.

Başka sayfalarda açsak da gönül kapımızı, yaşamımda sakladıklarım arasındasın.', 'Bazen yüreğine sığamazsın dar gelir.  Hem yürek hem de kendin. Kıstırılmış bir hayvan gibi çırpınırsın çaresizce çıkışı  varmış gibi. Seninl...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seslenisim-sana-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpek Mendillere Ör', 'i-pek-mendillere-or-oktay-oksuzoglu-tcp54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi doruklarını özleyen şu beynimi 

bunca yıldır sevdasız bırakan kıskanç yazgı

kutsal doğuş gününde tutuverdi elimi

büyülü bir rüyanın dürtüsüyle coşturdu

en güzeli arayan bu şair yüreğimi.

Sevginin ve umudun cennete çevirdiği

sihirli bir dünyada yaşamak ne güzeldir,

rengârenk çiçeklerin özenle bezediği

yanık sesli kuşların türküler söylediği

saf aşkın bahçesine kurulmak ne güzeldir. 

Sana duygularımı anlatmak inan ki zor

haydi al gözlerimi kendini onlarla gör

gerçek aşkın gücüyle doğan güzellikleri

yarınlara yansıyıp oynaşan hayalleri

umut çiçekleriyle ipek mendillere ör...', 'Sevgi doruklarını özleyen şu beynimi  bunca yıldır sevdasız bırakan kıskanç yazgı kutsal doğuş gününde tutuverdi elimi büyülü bir rüyanın dü...', ARRAY['Türk Edebiyatı','Şiir','Oktay Öksüzoğlu']::text[], 8.5, '{"poet":"Oktay Öksüzoğlu","poet_slug":"oktay-oksuzoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ipek-mendillere-or-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Bal''ın ve Şahin Yılmaz’ın MSN Atışması', 'mikdat-bal-in-ve-sahin-yilmaz-in-msn-atismasi-mikdat-bal-fs5b7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durup durup yalanları yayarak 

Kandıranı görmek lazım değil mi? 

Bu ülkeyi talan edip soyarak 

Çalanlardan sormak lazım değil mi? ......Mikdat Bal 

Bala şeker, süte de su katanın, 

Seçim vakti bol keseden atanın, 

İktidarda memleketi satanın, 

Kafasını kırmak lazım değil mi? .....Şahin Yılmaz 

Bu milleti dertten derde salanın, 

Kanımızı emip kene olanın, 

Başlarını ezmek lazım yılanın, 

Bir kaç taşla yarmak lazım değil mi? ........Mikdat Bal 

Her gittiği yerde bir çam deviren, 

Bunca yıllık birikimi savuran, 

Zor görünce dansöz gibi kıvıran, 

Adamlara vurmak lazım değil mi? ....Şahin Yılmaz 

Bu milleti birbirine çattıran, 

Gece gündüz her zilleti tatıran, 

Ananeyi töreleri attıran, 

Hainleri yermek lazım değil mi? .....Mikdat Bal 

Bakmaz menfaate, bakmaz çalıma, 

İnanan koşarak gider ölüme, 

Bu millete kan kusturan zalime, 

Cezasını vermek lazım değil mi? .....Şahin Yılmaz 

Halkımızı inim inim inletip, 

Bu millete durup masal anlatıp, 

Medya ile yalanları dinletip, 

Soyanları sürmek lazım değil mi? ........Mikdat Bal 

Kuran’a, sünnete, hadise bakıp, 

Pislikten arınıp felaha çıkıp, 

Yanlış olanları kökünden yıkıp, 

Temelinden örmek lazım değil mi? .....Şahin Yılmaz 

Üç yıl oldu çok ağırdı başımız, 

Arap saçı gibi oldu işimiz, 

Bizi bizden etti AB düşümüz, 

Yüce divan kurmak lazım değil mi? .........Mikdat Bal 

Görmeyenler bilmez akı karayı, 

Yıkarsan yapılmaz gönül sarayı, 

Modernizmin azdırdığı yarayı, 

Sevgi ile sarmak lazım değil mi? ....Şahin yılmaz 

Mikdatî der saadede gel hele, 

Birlik olup kopartalım velvele, 

Pek yakında kopacak bir zelzele, 

Gerçekleri görmek lazım değil mi? ......Mikdat Bal 

Şahin der ki aklım fikrim kaç okka, 

Dostluğun baki mi olmazsa cukka, 

Gönül gözümüzü açıp da hakka, 

Hakikate ermek lazım değil mi? .....Şahin Yılmaz', 'Durup durup yalanları yayarak  Kandıranı görmek lazım değil mi?  Bu ülkeyi talan edip soyarak  Çalanlardan sormak lazım değil mi? ......Mikd...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/mikdat-bal-in-ve-sahin-yilmaz-in-msn-atismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamış Yine Şiirlerim', 'aglamis-yine-siirlerim-birsen-ates-i6jke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ruhumda öldürdüm aşk meleğini 

bir daha olmayacak yüreğimde 

artık ağlamayacak gözlerim 

gecenin seslerini dinlerken 

kalbim aşka kapalı 

ve ben yeni bir şiire sevdalı 

bu yüzden 

acımadı gülmeyi unutmuş 

onca kesiklerine rağmen 

tutunmuş i n a d ı n a 

incinmiş ruhumun gölgelerinden 

ağlamış yine şiirlerim 

07.03.06', 'ruhumda öldürdüm aşk meleğini  bir daha olmayacak yüreğimde  artık ağlamayacak gözlerim  gecenin seslerini dinlerken  kalbim aşka kapalı  ve...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamis-yine-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben benden geçtim', 'ben-benden-gectim-bestami-kurtulus-v4lpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben benden geçtim bir akşam

galiba sarhoştum da...

hoştum ama...

güvercinlerin peşinden gittim bir zaman

gül yanaktan al topuktan türküler

sonra mezeler

üzüm tanelerinden

fıstık kabuklarından 

düğün bayram 

ben 

benden sonra 

senden geçtim

iyice sarhoştum

ama çok hoştum', 'ben benden geçtim bir akşam galiba sarhoştum da... hoştum ama... güvercinlerin peşinden gittim bir zaman gül yanaktan al topuktan türküler s...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-benden-gectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana 2', 'sana-2-zeliha-bicer-v2fjj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aralar senli dizelerim, senli düşlerim 

Kayıp zamanlarda, yitirdiğim sen e 

Zamanlarda yitirdiğim diyorum da 

Aslında yitirmediğim demem gerek 

Özledim 

Öylesi oturuyorsun ki bu aralar yüreğime 

Yüreğimde olan kıskanma emi 

Sen sevdiğim, sen yaşam yoldaşım 

Sen birlikteliğimsin 

Oysa 

Eski Arnavut kaldırımlarında yaşadığım 

Gizi,gizemi hep içimde sakladığım 

Hani sen saygı duyduğum 

Hani kanım hani unutamadığım 

Bu aralar artar olduğun yüreğimde 

Özledim belli seni 

Beni sevdiğini bilmem yeter 

Yeter bu ömrüme 

__Eskilerde kalan sen e idi 

     Unutmadığım.. _____', 'Bu aralar senli dizelerim, senli düşlerim  Kayıp zamanlarda, yitirdiğim sen e  Zamanlarda yitirdiğim diyorum da  Aslında yitirmediğim demem ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lazım Değil Mi? (Mikdat Bal İle msn atışmamız)', 'lazim-degil-mi-mikdat-bal-i-le-msn-atismamiz-sahin-yilmaz-vdgq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Durup durup yalanları yayarak,

Kandıranı görmek lazım değil mi? 

Bu ülkeyi talan edip soyarak,

Çalanlardan sormak lazım değil mi? ......Mikdat Bal

Bala şeker, süte de su katanın,

Seçim vakti bol keseden atanın,

İktidarda memleketi satanın,

Kafasını kırmak lazım değil mi? .....Şahin Yılmaz

Bu milleti dertten derde salanın,

Kanımızı emip kene olanın,

Başlarını ezmek lazım yılanın,

Bir kaç taşla yarmak lazım değil mi? ........Mikdat Bal

Her gittiği yerde bir çam deviren,

Bunca yıllık birikimi savuran,

Zor görünce dansöz gibi kıvıran,

Adamlara vurmak lazım değil mi? ....Şahin Yılmaz

Bu milleti birbirine çattıran,

Gece gündüz her zilleti tattıran,

Ananeyi töreleri attıran,

Hainleri yermek lazım değil mi? .....Mikdat Bal

Bakmaz menfaate, bakmaz çalıma,

İnanan koşarak gider ölüme,

Bu millete kan kusturan zalime,

Cezasını vermek lazım değil mi? .....Şahin Yılmaz

Halkımızı inim inim inletip,

Bu millete durup masal anlatıp,

Medya ile yalanları dinletip,

Soyanları sürmek lazım değil mi? ........Mikdat Bal

Kuran’a, sünnete, hadise bakıp,

Pislikten arınıp felaha çıkıp,

Yanlış olanları kökünden yıkıp,

Temelinden örmek lazım değil mi? .....Şahin Yılmaz

Üç yıl oldu çok ağrıdı başımız,

Arap saçı gibi oldu işimiz,

Bizi bizden etti AB düşümüz,

Yüce divan kurmak lazım değil mi? .........Mikdat Bal

Görmeyenler bilmez akı karayı,

Yıkarsan yapılmaz gönül sarayı,

Modernizmin azdırdığı yarayı,

Sevgi ile sarmak lazım değil mi? ....Şahin yılmaz

Mikdatî der saadede gel hele,

Birlik olup kopartalım velvele,

Pek yakında kopacak bir zelzele,

Gerçekleri görmek lazım değil mi? ......Mikdat Bal

Şahin der ki aklım fikrim kaç okka,

Dostluğun baki mi olmazsa cukka,

Gönül gözümüzü açıp da hakka,

Hakikate ermek lazım değil mi? .....Şahin Yılmaz', 'Durup durup yalanları yayarak, Kandıranı görmek lazım değil mi?  Bu ülkeyi talan edip soyarak, Çalanlardan sormak lazım değil mi? ......Mikd...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/lazim-degil-mi-mikdat-bal-ile-msn-atismamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fransız Öpücüğü', 'fransiz-opucugu-mehmet-ayhan-gunaydin-cva6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'FRANSIZ ÖPÜCÜĞÜ

Ey! Aziz ve necip millet,

Öpülüyorsun dikkat et! ! 

Demedi demeyin,

Ben hissettim, 

Siz de edin.

Bizi öpen bu hükümet,

Masumca değil,

Fransız öpücüğü ile öpüyor,

Yahu artık sen de HİSSET! ! ! 

M. Ayhan Günaydın.

       7 Mart 2006 

           Ankara', 'FRANSIZ ÖPÜCÜĞÜ Ey! Aziz ve necip millet, Öpülüyorsun dikkat et! !  Demedi demeyin, Ben hissettim,  Siz de edin. Bizi öpen bu hükümet, Masum...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fransiz-opucugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-bestami-kurtulus-yt19h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir yorgun akşamından bir yorgun sabahına

uyku tutmaz bir gecenin

gafil vakitlerine uyandım

ilk dolmuşlarında gri sabahın

serin nefesler çektim

tütsülü ciğerlerime

kucağı mutluluklar yüklü

elleri kolları saadet dolu

düşlerimi gördüm sokağın başında

uykumu ararken kaybolmuş

sıvıştım hissettirmeden

nasılsa artık hiç yetişemez

boşver! bilmesin gittiğimi', 'bir yorgun akşamından bir yorgun sabahına uyku tutmaz bir gecenin gafil vakitlerine uyandım ilk dolmuşlarında gri sabahın serin nefesler çek...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yorgun-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yönetenle Yönetilen', 'yonetenle-yonetilen-mehmet-ayhan-gunaydin-f47zg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YÖNETENLE YÖNETİLEN

Geçen iktidarlar,

Evet…

Onlar da düdüklemişler.

Yalınız,

Eskiler,

Bunlar kadar,

Şehvetli değilmişler.

Pek anlamam ya…

Oturdum geçen,

Üstünkörü hesap yaptım.

Hesabım pek kuvvetli değil ya

İlk mektep dörde giden,

Oğluma da doğrulattım.

Uzun süredir kafayı 

Şu benzine taktıydım.

Niye bu kadar pahalı,

İyice de meraktaydım.

En son bundan önceki,

İktidarla kıyasladım.

Arada uçurum öyle fahiş ki,

Nedenini anlamadım.

Sene iki bin; başta koalisyon hükümetiymiş,

O tarihler, ekonomi büyük krize girmiş.

Her şeye zam gelmiş, başta benzine de,

Fakat krizde bile doksan sekiz senti geçmemiş.

(Çok Şükür ki Türk’üm! dolarla kıyası sevmedim,

Dünya onunla kıyaslıyor mecbur kaldım neyleyim.) 

O vakitler aşağı yukarı,

Benzin bir dolar civarı.

Hatırlayın Koalisyon zamanı…

Şimdi beyler tek başına iktidar,

Kriz de yokmuş ben onların ve matbuatın yalancısıyım,

Öyle diyorlar.

Yine aşağı yukarı; benzin bugün,

İki buçuk dolar civarı.

Oturun sizde zahmet edip düşünün,

Şu uçurumu, aradaki şu farkı…

Yani her litrede cebimden,

Bir buçuk dolar fazla alınıyor.

Ses çıkmıyor kimseden,

Karşılığında memlekete,

Hayır namına çivi bile çakılmıyor.

Çivi çakmayı bırak,

Atadan kalma ne varsa,

Tek tek de satılıyor…

Yine o vakitler iç dış,

Ne varsa toplam borç.

İki yüz yirmi milyar dolar civarı

Şimdi; 

Üç yüz altmış milyar doları katladı.

Desem; benden alınan 

Yalnız bir litre benzinde

Cebimden çıkanı

Tuttu borca yatırdı…

O zaman bu borç niye katlandı? 

Desem; gelecek için yatırıma aktarıldı,

Ben göremedim,

Sahi göreniniz var mı? 

Dört yıldır başımdalar,

Aklımda bunlardan kalan.

Duble yol hikayesi,

Bedava giden kamu malları,

Elimden giden Kıbrıs,

Irak’ta başıma geçen çuval,

BOP diye etrafıma örülen duvar,

Reklamını izledim Unakıtan,

Bir de baştakinin mal varlığı var.

Neyse…benzinden hesap açmıştık,

Hesabı yapan oğlum anladı,

Ben anlayamadım

Sahi nere gitti ağalar

Sizce bu paralar? ! ! ! 

M. Ayhan Günaydın.

      7 Mart 2006 

          Ankara', 'YÖNETENLE YÖNETİLEN Geçen iktidarlar, Evet… Onlar da düdüklemişler. Yalınız, Eskiler, Bunlar kadar, Şehvetli değilmişler. Pek anlamam ya… Ot...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/yonetenle-yonetilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kaçağı', 'dus-kacagi-fethi-aslan-8sqjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzyıllar ötesinden taşımışım gibi hasretini

öyle yorgun düştü yüreğim.

Bir sınır boyunda vurulmuşum gibi 

Ellerim kan içinde,

gözlerimde tel örgü izleri.

Gömdüm düşlerimi yokluğuna.

Tütün basıp,

hiçliğini sarıyorum yarama.

Namert elinde yatırılmış kör puslara,

makine yağı kokusuyla çevrilmiş anlıma

bir soğuk namludur şimdi hasretin.

Ve ben bir firariyim yine

dağ dağ,orman orman,

yüreğim`de gömdüğüm düşlerim

peşimde nemrut hasretin.

Polis`ten,Asker`den kaçmak degil de, 

duygulardan kaçmak zormuş 

en zoru da oymuş sevgili. 

Bilsen nasıl utanırım şairliğimden.

Düşleri rengarenk boyamak varken

düş kaçağı olmak 

koyuyor insana be sevgili....', 'Yüzyıllar ötesinden taşımışım gibi hasretini öyle yorgun düştü yüreğim. Bir sınır boyunda vurulmuşum gibi  Ellerim kan içinde, gözlerimde te...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dus-kacagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '05Apostol''la Altmış Dört Bin Sayfa … Giriş', '05apostol-la-altmis-dort-bin-sayfa-giris-ahmet-yozgat-tzuwk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Bing Bang''daydı zaman,

Onu doldurdum ışık örgülü kaseme...

Kadehime doldurduğum sayın ki sizdiniz...

Yavru tarihi, sahtiyan bir yağmurluk gibi bürünmüş ve asırlardır uyuklayan o köhne ve kendi kendine yeten ve eski bir aşka ve aykırı şiirlere hamile bir meyhanedeydim milatların ilkinde. İçiyordum altmış dört bin sayfa tutan birikimimi kahverengi, yani it sütü rengindeki kadehimin dibinden. İçiyordum anasını satıyım. Yaşadıklarım eşkenar olmayan eşaçı bir üçgendi hepi topu ya da üçgen bile değildi de ben efkar sanıyordum boğulduğum şah denizini. Yani şiir klanının şahı yine her zamanki gibi salt ipektendi. Ve çifte su verilmişti. Masifti. Ve alçakça bir çukurdaydı anılarının kısrağına binmiş olarak. Ve katran balçıklı gururdandı. Bense bir sokak kancığı gibiydim. Yaltaktım varsıllığı kendinden menkul zibidi anılarıma ne yazık ki. 

Bedenimi el aldı. 

Yel aldı yüreğimi.

Ol sebepten içiyordum anasını satıyım.

''Lan Barba ikiletme de doldur

Şıradan olsun itin ölümü

.

Atın ölümü şeytan suyundan...''

2/:

Bing Bang''dan sonra da seni doldurdum...

İçtim anasını satıyım.

Suna suna içtim,

İçtim kana kana...

Yani kanaya kanaya...

***

Kezzablar pirine gelince... 

Müseyleme swingırı kenarındaydı şah denizinin. Pundumu kolluyordu gözünün çengelinden. Habil''di ilk giren urbasını sürüyerekten meyhaneye. Yani gururun yerle bir olduğu kapıdan içeri. Kandı sızan sanırım başındaki vadiden. Vandallar kafa kafaya vermişlerdi meyhanenin ya da memleketin ücra bir kasaba masasında Kabil''in ilk vukuatını konuşuyorlardı. Bense birinci notumu düşüyordum kucağımdaki yüreğime şiir sanarak. İblis ezoterik bir düşünceye binmişti. Keten liflerinden çoraplar örüyordu bin bir ölçekli. Bu aralar Serendip adası uğunuyordu diz üstü çökmüş. Mevki-i Cidde savruluyordu asit rüzgarlarında. 

Burası son meyhane...

Korunaklı demler diyarı,

Noktanın konduğu alem yarınlara...

Bu durumda gel de içme:

''Lan Barba ikiletme de doldur,

Şıradan olsun itin ölümü,

Atın ölümü şeytan suyundan...'' diyerek...', '1/: Bing Bang''daydı zaman, Onu doldurdum ışık örgülü kaseme... Kadehime doldurduğum sayın ki sizdiniz... Yavru tarihi, sahtiyan bir yağmurlu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/05apostol-la-altmis-dort-bin-sayfa-giris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Montaj Şifa', 'montaj-sifa-cetin-hacifettahoglu-qr6jr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun zaman geçti aradan

Dün aynı filmi seyrettim

Oyun aynı,oyuncular aynı

O gün çok ağlamıştım

Dün nedense ağlayamadım bi türlü

Zorda olsa bir damla gözyaşı istedi yanaklarım

Ama nedense ağlayamadım 

Yönetmeni olduğum hayatıma o günkü vizörden bakamadım

Yıllar geçince her şey kamera önüne itildi

Bense ardında çaresiz

Benimki yalnızlık hastalığı işte

Buradan her şeyi seyretmeyi seviyorum aslında

Oyun içine oyun ekleyip,montajında gülüyorum

Çoğu zaman kendime gülüyorum

Bazen rol çark edip gülümseyişler bana dönüyor

Dedim ya benimkisi yalnızlık hastalığı

Şifayı montajda kesip yapıştırırken arıyorum

Kendimi bulup aralara ekliyorum

Zor belki uğraşmak,kesmek,yapıştırmak,eklemek

Ama

Hayatımız zaten kolaj gibi değil mi? 

Yamalı bir don gibi üzerimize giyiyoruz

Kimi arkadan,kesiyor,hissettirmeden

Biz önden yamıyoruz kesileni görmeden

Dün aynı filmi seyrettim yeniden

Oyun aynı oyuncular aynıydı

Ağlayamadım o günkü gibi

Meğer akan gözyaşlarım,çürütmüş film şeridini', 'Uzun zaman geçti aradan Dün aynı filmi seyrettim Oyun aynı,oyuncular aynı O gün çok ağlamıştım Dün nedense ağlayamadım bi türlü Zorda olsa b...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/montaj-sifa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O da', 'o-da-bilal-i-lhami-koksal-hqt8d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdiğim şarkılar sustu bir bir; 

Ben ağladım 

İstanbul durur mu ağladı o da

İçim dışım 

Her tarafım gözyaşım

Baştan ayağa buğulandı küçük bir oda...', 'Sevdiğim şarkılar sustu bir bir;  Ben ağladım  İstanbul durur mu ağladı o da İçim dışım  Her tarafım gözyaşım Baştan ayağa buğulandı küçük b...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-da-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darağacı', 'daragaci-i-lhan-kirbac-7rxpz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeşermeye başladığında tohum,

Başına neler geleceğini bilmiyordu.

Fışkırdı topraktan büyük bir hevesle,

İnsanoğluna hizmet aşkıyla.

Sayısız faydaları olacaktı,

Kalem olacaktı minik ellere,

Defter,kitap olacaktı.

Bilgiler sunacaktı sayfa sayfa,

Sıra olacaktı belki de irfan yuvalarına.

Ne heveslerle boy atmıştı,uzamıştı.

Ve beklenen gün geldi,

Sevindi,öyle sevindi ki,

Balta darbeleri yakmadı canını.

İnsanlığa faydalı olacaktı ya,

Herşeye değerdi.

Ama olmadı,hayalleri gerçekleşmedi.

Üç ayaklı bir idam sehpası yaptılar ondan,

Adını cellattan öğrendi Darağacı.

En yakın arkadaşı ucunda sallanan yağlı urgan.

Ne canlar aldı darağacı,

Devlet adamlarını mayıs sonrası,

Nice vatan evladını,yiğitleri,

Eylül sonrası.

Üzüldü darağacı,hüzünlendi,

Aldığı canlardan daha günahkarları,

Sallanırken göremediği için,

Kahretti.

Ağaç olduğuna kahretti,

''Taş olaydım dağ başında,

Yağlı urganla arkadaş olacağıma,

Yanaydım kor ateşlerde ''dedi.

Gecenin sessizliğinde,

Ağladı,ağladı darağacı.', 'Yeşermeye başladığında tohum, Başına neler geleceğini bilmiyordu. Fışkırdı topraktan büyük bir hevesle, İnsanoğluna hizmet aşkıyla. Sayısız ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Kırbaç']::text[], 8.5, '{"poet":"İlhan Kırbaç","poet_slug":"i-lhan-kirbac","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/daragaci-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca ve Antep Fıstığı', 'karinca-ve-antep-fistigi-bilal-i-lhami-koksal-t36es', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duası bile vardır karıncanın

Sırf kendi adına

Çalışkandır 

İnatçıdır

Her yerdedir bazen televizyon ekranında

Bazen bacaklarında

Hatta tüfeğin namlusunda

Acaba antep fıstığı yer mi? 

Demin verdim ben valla yemedi

Ya karnı tok

Ya da pek lüksü sevmiyor

Öyle ya hiç antep fıstığı ağacına çıkmış bir karınca görmedim ben

Hoş antep fıstığı ağacı da görmedim ya...

Neyse...', 'Duası bile vardır karıncanın Sırf kendi adına Çalışkandır  İnatçıdır Her yerdedir bazen televizyon ekranında Bazen bacaklarında Hatta tüfeği...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karinca-ve-antep-fistigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Et tırnak uyumu', 'et-tirnak-uyumu-bilal-i-lhami-koksal-k5q23', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç nalını sevmeyen at olur mu?', 'Hiç nalını sevmeyen at olur mu?...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/et-tirnak-uyumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yükselmiş Gay-Üstat', 'yukselmis-gay-ustat-omer-dalman-u8w5d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha yeni girmişlerdi bu konulara

hani şu ''mistizm, kozmoz, atral-mastral'' mevzuları...

ikisi de istekli, ama bir o kadar acemi...

biri diğerine döndü aklında takıntı kalıntılarıyla:

''acaba yükselmiş gay-üstat olamaz mı lan? ! ''

yüzünde yeni bir keşfin heyecanı

ve o zafer gülümsemesiyle...

öteki de acemi ya

bakakaldı! ..

şaşırdı

utandı

afalladı besbelli...

ne de olsa sınırsız ya kafada

''hayır'' diyemedi

''evet'' de diyemedi.

hızlı bir muhasebeye çekildi.

ama ikisi de

aydınlanmanın unisexliğinde

yeniden bedenlenmenin eşiğinde hissettiler! 

akıllarından

binlerce kişi geçti o anda

zincirleme bir gay operasyonu! ..

aslında cevap aha oracıktaydı ama

bilemediler! ..

acemiler ya, ondan...

ama o günden beri ''biri'' hiç unutmadı bu cümleyi

ağladı, sızlandı, güldü, çıldırdı ama

hep tekrar etti durdu:

''acaba yükselmiş gay-üstat olamaz mı lan? ! ''

''acaba yükselmiş gay-üstat olamaz mı lan? ! ''

''acaba yükselmiş gay-üstat olamaz mı lan? ! ''

''acaba yükselmiş gay-üstat olamaz mı lan? ! ''...

(Mart 2006)', 'Daha yeni girmişlerdi bu konulara hani şu ''mistizm, kozmoz, atral-mastral'' mevzuları... ikisi de istekli, ama bir o kadar acemi... biri diğe...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yukselmis-gay-ustat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba...', 'acaba-bilal-i-lhami-koksal-7lnaa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acaba içimdeki seni öldürmeye yeter mi

Her gün içtiğim tek dal sigaranın zehri?', 'Acaba içimdeki seni öldürmeye yeter mi Her gün içtiğim tek dal sigaranın zehri?...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/acaba-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülpembe', 'gulpembe-munevver-erilmez-1ptac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kız Gülpembe

Ne de güzelsin  öyle.

Mahallenin  oğlanları,

Hep peşinde...

Yavuklusu var diyorlar,

Doğru  mu yoksa? 

Havandan geçilmiyor,

Biraz  gülümsesen,

Ne  olur? Ümit versen', 'Kız Gülpembe Ne de güzelsin  öyle. Mahallenin  oğlanları, Hep peşinde... Yavuklusu var diyorlar, Doğru  mu yoksa?  Havandan geçilmiyor, Bira...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulpembe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç sevgiliniz evlendi mi? iki', 'hic-sevgiliniz-evlendi-mi-iki-bilal-i-lhami-koksal-n91yg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdilerde ben evli bir kadını seviyorum

Ayıp diyorlar

Ama sonradan oldu her şey

Senin gitmen

O da sonra

O da çok ayıp...', 'Şimdilerde ben evli bir kadını seviyorum Ayıp diyorlar Ama sonradan oldu her şey Senin gitmen O da sonra O da çok ayıp......', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hic-sevgiliniz-evlendi-mi-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atiye''ye', 'atiye-ye-duran-cetin-5aksh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir yazmak istedim modadır diye,

Gelmedi aklıma söylenecek dize.

Herkes neler yazmış bak size,

Ben sana ne yazayım söylesene Atiye.

Allah bir, Peygamber hak,

İstemedikleri elbette yasak.

Tağuti şeyleri sen de bırak,

Gir emrine kul olarak.

Manzara-ı millet; durum rezalet,

Yaşa, öğren, öğret; tebliğ et.

Rızasına uymayanları terk et,

Gir emrine kul olarak zikret.

Bu günler elbette geçti, geçecek,

Hak batıl mücadele etti, edecek.

Batıl şeytanla cehenneme gidecek,

Hak inananlarla yeşerip gelişecek.

Sana ihtiyaç var, unutma! 

Seninle, benimle, sizinle ve bizimle.

Kervan yürüyecek yavaş yavaş,

Gençliğini eğit, öğret; uyutma.

Aslında şiir yazmam, belki yazamam.

Yazılanları görünce ben de dayanamam.

Yazdım işte böyle saçma sapan.

İnananlara değer verdim her an.

İnananlar kurtulsun; işte budur duam.

(09/06/1991-Sarıcakaya)', 'Şiir yazmak istedim modadır diye, Gelmedi aklıma söylenecek dize. Herkes neler yazmış bak size, Ben sana ne yazayım söylesene Atiye. Allah b...', ARRAY['Türk Edebiyatı','Şiir','Duran Çetin']::text[], 8.5, '{"poet":"Duran Çetin","poet_slug":"duran-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/atiye-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Safî Soylu Sır', 'saf-soylu-sir-faruk-gokbulut-64629', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman sende durmuş, kainat sessiz

Varlık yetim kalmış, duygular hissiz

NURSEL’ine kapıldık bu gece biz

Sâfî  yaşlarla ağladık, yıkandık

Yürekleri Harran, HAVRANLI candık biz

16 Ocak 2005 

Saat: 20.00

ANKARA', 'Zaman sende durmuş, kainat sessiz Varlık yetim kalmış, duygular hissiz NURSEL’ine kapıldık bu gece biz Sâfî  yaşlarla ağladık, yıkandık Yüre...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/safi-soylu-sir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı Şiirler 03  Bizi', 'yildizli-siirler-03-bizi-nurten-altinok-s0emk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '___________*

Aşk aşk aşk

Aş aş aş

A a a 

Ne var bunda bu kadar hayret edilecek

Hiç mi aşık olmadınız

Hiç mi sayıklamadınız birinin adını

Hiç mi rüyalarınıza girmedi

Sarıp sarmalamadınız mı hiç

Öpüp koklamadınız mı

Baş tacı etmediniz mi adını soyadını

Gözlerinin rengini ezberlemediniz mi

Sesinin tonunu 

Kokusuna teninin 

Eklemediniz mi

Neyin başı

Ne bileyim ben neyin başı

Olsa olsa 

Aşk olur başımın tacı

Yüreğimin aşı

Bir de s e n varsın ya

Başımın baş belası

Ah! bir bilsen nasıl benimsin

Baş ağrım olsan 

Ömür boyu başımda taşırdım seni

Yürek yaramsın

Yüreğimi yakansın

Anlamazsın ki

Yoktur okuman yazman yasaklıya

İyi belle

A ile başlar alfabe

aŞ ile dolar tencere

aşK ile coşar yürek

Kafası giyotinlere vurulacak kadınım ben

Tövbelerim bile iflas etti senin yüzünden 

Yüz milyon kere akıl veriyorum kendime her gün

İşin kötüsü

Çok uslu bir çocuk gibi 

Dinliyorum da verilen aklı 

Düşünmeyeceksin 

- Düşünmeyeceğim

Hatırlamayacaksın

- Hatırlamayacağım

Unutacaksın

- Efendim! 

Sevmeyeceksin 

- Bir şey mi dediniz! 

Kafası kesilecek kadınsın sen

- Kafası kesilecek kadınım ben 

Rahat bırakın bendeki b i z i...', '___________* Aşk aşk aşk Aş aş aş A a a  Ne var bunda bu kadar hayret edilecek Hiç mi aşık olmadınız Hiç mi sayıklamadınız birinin adını Hiç...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yildizli-siirler-03-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs manzaraları', 'otobus-manzaralari-bilal-i-lhami-koksal-8jpdj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman otobüse binsem

Yanım da bu kitap 

Ne zaman ankaraya gelsem otobüstesin

Ne zaman bir hostese aşık olacak olsam..

Ah sen şu otobüsten bir insen...

(cemal süreya kitabı yırtık pırtık 

ama hala de şiirler

ne kadar güzeller..)', 'Ne zaman otobüse binsem Yanım da bu kitap  Ne zaman ankaraya gelsem otobüstesin Ne zaman bir hostese aşık olacak olsam.. Ah sen şu otobüsten...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otobus-manzaralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halil''im', 'halil-im-faruk-gokbulut-wtn3n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Halil’im Rahman’a rızamı anlattım

Ben gibi garibi duyar mı bilmem

Gönlümün sahilindeki ayak izine baktım

Ben de bir gün er soylu Halil olurum diye

15 Ocak 2005

Saat: 17.36

ANKARA (Atakulu Sevilla Bar) 

*Halil-ü Rahman Diyarından Esen Ilık Nefesliden…', 'Halil’im Rahman’a rızamı anlattım Ben gibi garibi duyar mı bilmem Gönlümün sahilindeki ayak izine baktım Ben de bir gün er soylu Halil oluru...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/halil-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sâki''nin Sırrı', 's-ki-nin-sirri-faruk-gokbulut-tolel', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doldur ey sâki aşk küpünden doldur

Zamanı geri al, onüç sıfır beşte durdur

Duyur sesini büyük ustanın, pir-i mugânın

Öğütülsün dertlerimiz  yansın bu canım

15 Ocak 2005

Saat: 21:37

ANKARA

Gönlümün mimarı, büyük usta Halil SOYUER’e! 

Sensizliğin sene-i devriyesinde sana hasret bir gencin

incecik sızısını kabûlünü istirham ederek sana ithaf ediyorum.', 'Doldur ey sâki aşk küpünden doldur Zamanı geri al, onüç sıfır beşte durdur Duyur sesini büyük ustanın, pir-i mugânın Öğütülsün dertlerimiz  ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saki-nin-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-baran-demir-rgz7e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir bilsen ne güzel vuruyor 

güneş yüreğime yüzüme vurur gibi

içimi ısıtıyor bu mart gününde 

ayazı hiçe sayarak

sen yoksun 

bilemezsin sıcaklığını şu an günesin

hey güzel yüzlüm

gel çık dışarıya 

güneşe gülümse ve 

merhaba de', 'bir bilsen ne güzel vuruyor  güneş yüreğime yüzüme vurur gibi içimi ısıtıyor bu mart gününde  ayazı hiçe sayarak sen yoksun  bilemezsin sıca...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/merhaba-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım', 'aklim-can-ozcan-ozkan-qp2b5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşamı

Getiren güneşin batışıydı

Kalemler tükeniyor...

Ve ben tükeniyorum...

Gece de

Aklım devrik bir cumhuriyet

Sen sessizliktesin!', 'Akşamı Getiren güneşin batışıydı Kalemler tükeniyor... Ve ben tükeniyorum... Gece de Aklım devrik bir cumhuriyet Sen sessizliktesin!...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aklim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahın mı kaldı?', 'ahin-mi-kaldi-i-lhami-arslantas-dd9yp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İflahım kesildi tükendi çıram,

Ahu dilber bende ahın mı kaldı.

Yaktın ateşine geldi mi sıram,

Ahu dilber bende ahın mı kaldı? 

Gündüz arbedeli gece hüzünlü,

Derdimi yazarım hece vezinli,

Efkâr akşamında umut izinli,

Ahu dilber bende ahın mı kaldı? 

Gül yüzünden güller açtığı zaman,

Ömrüm kıl köprüden geçtiği zaman,

Gönül aşk badesin içtiği zaman,

Ahu dilber bende ahın mı kaldı? 

Esirgemez idin aşkını benden,

Ne oldu ki sevgin kurudu kandan,

Bağrıma bastığım ziyade candan,

Ahu dilber bende ahın mı kaldı? 

Kardelen yarmıştı toprağı dörde,

Neden aramıza zan oldu perde,

Ellerin elime değdiği yerde,

Ahu dilber bende ahın mı kaldı? 

Kurudu gözeler çekildi suyum,

Hiç fayda vermedi üç deniz kıyım,

Muhabbet soframdı bir kase çayım,

Ahu dilber bende ahın mı kaldı? 

İlhamiyim can içinde zarım var,

Bu kilerde bir yeyimlik darım var,

Ömür hesabında kısmı kârım var,

Ahu dilber bende ahın mı kaldı.?', 'İflahım kesildi tükendi çıram, Ahu dilber bende ahın mı kaldı. Yaktın ateşine geldi mi sıram, Ahu dilber bende ahın mı kaldı?  Gündüz arbede...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ahin-mi-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı şarkılar söyle bana 07-032006 17:20', 'sevdali-sarkilar-soyle-bana-07-032006-17-20-ahmet-unal-cam-ak4td', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdalı şarkılar söyle bana,

Umutlu Şarkılar söyle.

Hep ayrılık,

Hep hüzün, 

Hep keder…

Yeter..yeter…yeter

Tenhada bir şair şiirler söyler

Bir aşığın dilinde acı türküler…

Yıldızlar kayar sessizce

Kavurur içimi sessiz geceler

Kavurur içimi yalnızlık,

Ağlayan bir bebek sesi,

yolunu kaybetmiş bir böcek.

Bana birşeyler söyle

Şiirler oku,öyküler anlat,

   susup kalma öylece

Bu gece içim kanıyor

Gönlüm daralıyor,

  konuş,  sohbet et,

Bu gece her yer gurbet

Anlat nolur, kavuşanları anlat

Yalnızım bu gece, yalnızım bu gece

               dilimde hazan hece hece

Hüzünlerden sarhoşum  bu gece', 'Sevdalı şarkılar söyle bana, Umutlu Şarkılar söyle. Hep ayrılık, Hep hüzün,  Hep keder… Yeter..yeter…yeter Tenhada bir şair şiirler söyler B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdali-sarkilar-soyle-bana-07-032006-17-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '06Sıyır Geceyi Lan Cemal 1', '06siyir-geceyi-lan-cemal-1-ahmet-yozgat-xn4fx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Sıyır geceyi sırların cidarından lan Cemal

Bilmez misin kurtların kışın uluduğunu

Leyla''nın mecnun diye kudurduğunu 

İşte onun için can kokar zemzem

Misk öküzü can kokar...

1a/:

Lan Cemal aç o sağır kulağını.

Ve beni dinle… 

Varsa içimizde acımasızca boğuşan bir hayvan. Yavan bir tarih sayfasında kılıçdarız demektir. Tırmık tırmık akan kan oluklarını buz gibi Fırat sanmadayız. Yani aldanmadayız. Ve üzerinde kara gecenin giydiği barani aslında hünerli ellerimizin ürünüdür Şiraz dokumalarında. Her kokuşmadan kefir sağılmaz. Tenha dağ başlarında boşuna ulur kurtlar. Talaş ve taş, toz ve toprak üçleminde kalmanın zorluğunu bilen var mı sizin cenahta, söyle lan Cemal. Yapayalnız olmuşluğumuzdur aslında delirten beni ve kavmi nisayı. Seni ise bölünmüş mevsimler üşütür. Ve onu... O mu kim? Anla işte. Zemzeme ve mis öküzüne gelince lan Cemal. Bizim atımız işlemez Demirkazık Derbendinde. 

Var git yoluna.', '1/: Sıyır geceyi sırların cidarından lan Cemal Bilmez misin kurtların kışın uluduğunu Leyla''nın mecnun diye kudurduğunu  İşte onun için can ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/06siyir-geceyi-lan-cemal-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '06Sıyır Geceyi Lan Cemal 2', '06siyir-geceyi-lan-cemal-2-ahmet-yozgat-f177g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '2/:

Sıyır geceyi beyninin cidarından lan Cemal

Bilmiyorsan öğren ki bilgelerden

Sade giyilir kahveler kapkara mırra ülkesinde

Kaşlarının arası aşk iksiri ile dağlanmış sakiler

Bir bir doldurur acı deyişlere acıkan develerini

Onun için gül kokar yalnız adamı çölün

Misk öküzü can kokar...

2a/:

Lan Cemal aç kulağını ve dinle beni. 

Kendini anlatan acılı bir mırra türküsü gibidir muhariplerin türkü çığırması. Bağırması ise Hayber’de merdi meydandır. O mırra ki bidayette arafın ayak izi idi. Ondan ötürü beynimiz köpür köpür ve paramparçadır nişangahta. Kalbimiz ise bin yapraklı bir yonca gibi ayazda kalmış ve titremekte ise yan buna işte. Bu gidişten hayır umma. Bekleme gat yaprağı çiğnemiş sakilerini diyar-ı Sana''nın. ''Ve sarmalamışken hepimiz seni ey sevda, bırakma bizi tan atana kadar.'' demişsin duydum. Sorma gayrı gerisini. Kulağımız deliktir bizimde lan Cemal. Ya da okudum tarihi gılmani''de. Sayfa on sekizde. Bizimse dalga dalga gelen sevme duygusunu bir dalga kıran gibi durdurmakta korkumuz. Basmışken bağrımıza bir dağ emsali küçük gözlü bir sevgiliyi bağ kovuğunda. Ve uluyan kamyonların sivri korkusu sinerken motorin kokusuyla şakağımıza... Mırralara ve mis öküzüne gelince lan Cemal. Bizim atımız işlemez her daim arkadan ve sinsice cenbiyelerle vuran kozaklar diyarında. 

Var git yoluna.', '2/: Sıyır geceyi beyninin cidarından lan Cemal Bilmiyorsan öğren ki bilgelerden Sade giyilir kahveler kapkara mırra ülkesinde Kaşlarının ara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/06siyir-geceyi-lan-cemal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '06Sıyır Geceyi Lan Cemal 3', '06siyir-geceyi-lan-cemal-3-ahmet-yozgat-eg4yv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '3/:

Sıyır geceyi yüreğinin cidarından lan Cemal 

Kaşları rastıklı rüzgarların üfürdüğü yalanlar

Pelerin gibi eser amazon vilayetinde

Sense delta avındasın kırık ve tahta kılıcınla

Hazin dallar onun için hışırdar

Kuşlar can çekişir şiirin satır aralarında

Misk öküzü can kokar...

3a/:

Lan Cemal aç kulağının camını. 

Sevda ve korkunun ikileminde bir buradayız, bir ta Fizan-ı uzakta. Oysa o zalim savaşçılar yine gönül cephemizde yarının acılarını çekiçlemekte. Etkilemekte bu durum da doğal olarak seni. Oysa yırtmıştın kefeni en son Sarıkamış''ta. Sorma gayrı gerisini. Kulağımız deliktir bizimde lan Cemal. Ya da okudum tarihi gılmani''de. Sayfa on dokuzda. ''Boğuluyorum.'' diyor ikimizin geride unuttuğumuz bir anımız. Burnumuzu sıkan nasırlı parmak mengene sanki. Kendimizi kurtarabilsek belki kahraman kurtarıcılar olacağız. Dolacağız ıssız gönüllerine mırra sazendelerinin. Bizce bitmez bu gece. Neredesin ey sabah? Amazon vilayetine ve mis öküzüne gelince lan Cemal. Bizim atımız işlemez İskit hükümranlığında. 

Var git yoluna.', '3/: Sıyır geceyi yüreğinin cidarından lan Cemal  Kaşları rastıklı rüzgarların üfürdüğü yalanlar Pelerin gibi eser amazon vilayetinde Sense d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/06siyir-geceyi-lan-cemal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '06Sıyır Geceyi Lan Cemal 4', '06siyir-geceyi-lan-cemal-4-ahmet-yozgat-b8tt7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '4/:

Sıyır geceyi ruhunun cidarından lan Cemal 

Eğil gayya kuyusuna yol alan sesini dinle

Kulak ver ve öğren kır saçlı rahiplerden

Dinlediğin ana rahmindeki türkülerindir

İnanmasan da her gece ikiye bölünür ay

Ondandır gecelerin ter kokması

O yüzden İblis ağlamakla gülmek arasıdır

Bakar bin çift göz melul, vadi koyaklarına

Misk öküzü can kokar...

4a/:

Lan Cemal aç kulağının tıkanan güzergahını. 

Bil ki bu gün cehennemi yaşıyor içimizdeki her zerre. Kaç kerre derilir mahşer bilir misin? Kaç kere deprenir dabbe? Eğer son ise bu derilmesi, yanma dünyada kalanlarına lan keriz. Yani dehrin sonundayız biz. Dokunuyoruz, aslında yanı başımızda cennet. Ama ellerimiz bağlanmış, kolumuz kördüğüm toprağın cidarına. Şu anda nokta içre mahpus şairleriz hepimiz. Bir ilerler iki gerileriz. Esamamiz okunuyorsa üç yüz on sekizinci ortasında ocağ-ı yeniçerinin. Onun için misk öküzü can kokar. Ayın ikiye bölünmesine gelince lan Cemal. Senin atın işlemez diyar-ı peygamberide. 

Var git yoluna sahtekar.', '4/: Sıyır geceyi ruhunun cidarından lan Cemal  Eğil gayya kuyusuna yol alan sesini dinle Kulak ver ve öğren kır saçlı rahiplerden Dinlediğin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/06siyir-geceyi-lan-cemal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Züppe', 'zuppe-munevver-erilmez-8xxy0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çekersin altına son model bir araba,

Gayrimeşru yollardan kazandığın parayla,

Düşersin Bağdat''ın yollarına.

Sanırsın ki,dünyanın karısı,kızı,

Atılacaktır kollarına,

Unutma ki,yolda giden her hatun,

Karın değilse bile,ya anandır ya bacın,

Çalma kornanı boşa,

Gitmiyor fiyakan hoşa,

Çek arabanı buralardan,

Atma havanı boşa

Çekil git evine koşa koşa.', 'Çekersin altına son model bir araba, Gayrimeşru yollardan kazandığın parayla, Düşersin Bağdat''ın yollarına. Sanırsın ki,dünyanın karısı,kızı...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zuppe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söndüm', 'sondum-yavuz-bayram-caliskan-nu0mr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şiirin parlayan yıldızı vardı,

Hayat arkamdan hep garip bakardı,

Gözlerime değmeyin ayrılıktan önce de akardı,

Atışınla yıldızım gitti söndü dün.

Bu şairin ışıldayan sevgilisi vardı,

Gamzeliydi, krizantemdi, yardı,

Yüreğini bir başka aşk sardı,

Gözleriyle göremeyecek kadar kördü,

Yitişinle güneşim battı söndü gün.

Durdu devran, durdu hayat,

Bakıyorum da, simitler de bayat,

Tutma yalnızlığı getir yanıma at,

Gidişinle yarınım öldü söndüm bütün.

http://www.geocities.com/siirhan68/', 'Bu şiirin parlayan yıldızı vardı, Hayat arkamdan hep garip bakardı, Gözlerime değmeyin ayrılıktan önce de akardı, Atışınla yıldızım gitti sö...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketimi Özledim', 'memleketimi-ozledim-esra-aydin-tini5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca yıllık ömrümde

Üç beş kere gittim

Onu hep uzaktan sevdim

Memleketimi özledim

Karadenizin deli dalgaları

Yaz ortasında serin yaylaları

Yükseklerden akan coşkun suları

Dört mevsim bereketli yağmurları

Sevdaya salar yüreğimi 

Dağların yeşil gözleri

Çırpınır durur kalbim

Sudan çıkmış hamsi gibi

Her yemeğin baş rolünde hamsi

Pilavı,buğulaması,tatlısı,köftesi

Ne de güzel olur yemesi

İnsanının zekasının nedeni

Giresun''u özledim,manzarası sisli

Gören vurulur o buğulu köyleri

Keskin virajların usta şöförleri

Hayran bırakır düz yolda gidemeyenleri

Yokuş yolları,dağınık evleri

Bağırsan dağlar emer sesini

Zeki insanı konuşur ıslığıyla

Tarihe geçer hergün ıslık dili

Şifa büyütür suyu,toprağı

Herşeye deva fındığın krallığı

Anası ağacında sallar bebeğini

Giresun,memleketim,ne çok özledim seni', 'Bunca yıllık ömrümde Üç beş kere gittim Onu hep uzaktan sevdim Memleketimi özledim Karadenizin deli dalgaları Yaz ortasında serin yaylaları ...', ARRAY['Türk Edebiyatı','Şiir','Esra Aydın']::text[], 8.5, '{"poet":"Esra Aydın","poet_slug":"esra-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/memleketimi-ozledim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-abdulhalim-i-pek-6lvkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“beni mezara sen indir.”

Söyle; 

O müstehzi gülüşünle mi,

Doyamadığım boyun büküşünle mi,

Nereme dokunsa yakan ellerinle mi,

öldüreceksin? 

Acı poyrazlar yakıyor gözlermi,

Sabırsız bekleyişleri

taşıyamaz oldu hücrelerim,

Her seher bin kez 

idam oluyor gidişin

ve ben bin kez

mezar arıyorum yokluğuna…

Söyle! ! ! 

Hayali bile ağlatan gözlerinle mi,

İğde kokulu günahkar zülüflerinle mi,

Al dudaklarından dökülen al sözlerinle mi,

Ele avuca sığmaz hasretinle mi

öldüreceksin? 

Anlamını yitirdi 

senden sonra tüm düşler,

Mabetleri yıkıldı

gönlümün

Papatyalar fallara

inanmaz oldu

Söyle; 

Gülümseyişinin derinliklerine gömüleceksem

istediğin an can vereyim…

                                                  Temmuz 2005', '“beni mezara sen indir.” Söyle;  O müstehzi gülüşünle mi, Doyamadığım boyun büküşünle mi, Nereme dokunsa yakan ellerinle mi, öldüreceksin?  ...', ARRAY['Türk Edebiyatı','Şiir','Abdulhalim İpek']::text[], 8.5, '{"poet":"Abdulhalim İpek","poet_slug":"abdulhalim-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/soyle-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümde', 'dusumde-aydin-guler-ks7q6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben yürürüm insanlar yürür gece boyunca 

Dere yatağında sürer gider izini

Doruklarda eğri büğrü sulietler

Yanı başımda bir iz düşümü gölgeler

Adeta bir karınca sessizliğiyle

Belli ki,büyük bir gizliliğin sırrı içindeler.

Bilinmez iklimleri bir çırpıda yaşarım

İçimde kopan meçhul fırtınalar var

Sonbahar akşamlarında yaprak dökümü gibiyim

Bir orta yaş delikanlılığıyla

Üstelik,yüreğimde ağırmakla hızla

Gökte; 

İlkyaz sancılarına durmuş yine çoban yıldızı

Yüce bir kavganın içinde bulutlarla

Yolunu kaybetmiş bir balıkçıya umut

Gül yüzlü,

Yeni bir günün doğuşuna

MERHABA demek için...', 'Ben yürürüm insanlar yürür gece boyunca  Dere yatağında sürer gider izini Doruklarda eğri büğrü sulietler Yanı başımda bir iz düşümü gölgele...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusumde-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Çiçeği-23', 'ates-cicegi-23-adnan-durmaz-m10ol', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aç çekirge orduları gibiydi

Gözleri cinnetli sarı

Sürü sürü saldırdılar

Cinayet kızarmış duyargaları

Yeşil başak bir tarlayı talanlar gibi

       	afat ettiler Bolu''yu

Bir ölüm kokusu sardı rüzgârı

Belki de bin yıllardır canlarından koparılan

      	has – zeamet - timar

Öşürlenmiş ana sütü ve göz yaşı aşkına

           	biriken kinleriyle

Kime ve neden saldırdığını bilemeden

Saldırdılar

       	aç - yoksul ve yalın ayak

Saldırdılar Arif Bey''in üstüne

Sardılar dört bir yanından

Ak çekerge orduları gibiydiler

Ellerinde ne taktik ne plan

Arif Bey tecrübeli kumandan

Alışık olmasa da çekilmeğe kavgadan

Çekildi vuruşa vuruşa

Eski karargahı Kızılcahamam’a

Dövüşe dövüşe yürümek

      	kan kıvılcımlanan zamanda

Göğüsler köpük köpüğe yarmak zalim hattını

Mazlumun ateşten yumruğu olmak

Yalımlar arasında ölümü çiğneyerek ilerlemek

En büyük sarhoşluğu Arif Bey''in bu

Kavga alanı derler adına

       	orada yenik düşer insana

  		ölüm korkusu

O ne müthiş bir aşk öyle

Nasıl bir yürek coşkusu anlatılamaz

Arif Bey''in  yüreği çekilmeyi kaldıramaz

Dar geliyor öfkesine bedeni

Çapulcu önünden kaçmak

ölümden beter ama zaruri

Mıntıka tek tük çalılık - tek tük taşlıktı

Hava alaca karanlık

Geride hilafet çapulcuları

Kurşunlar gelip gitmekte

Arif Bey''in Sevisi ürkek - tedbirli

Sanki kurşun sıkar iken

     	arkadaşlarını mevziler gibi

Bir kurşun saldı salgaraya

O sıra şaha kalktı Arif Bey''in atı

       	kurşun sağrısına saplandı

          		kişnedi acı acı

Arif Bey''in gözleri ateş kesildi

     	kanı beynine sıçradı

Doğrulttu silahını çekti tetiği

Eller yüzlere kapandı / dizleri dövdü

Yürekler alazlandı / kollar koptu

Diller tek söz diyemedi

Geride gericiler / sesleri kesilmişti

Bir ses- Allahım dedi

Garip anam / kadın anam / has anam

Öldük bilinmedik boz topraklarda

       	Cesedimiz garip düştü

             	ak bağrına bas anam

Bir bıçak gibi sustu

Gözlerden yürek suları boşandı yaşın yaşın

Geride gericiler takipten vazgeçmişti

Havada yıldızlara varan felaket

    	uğursuz bir suskunluk ulumakta

    		mutlaka kötüye delalet

Tutmayan elleriyle cesedi yokladılar

Yüzlerinde bağışlanmaz derinlikte bir küslük

Gözler yaş içinde

Bir ağacın altına defnettiler

Bir felaket olur diye Arif Bey''e katılmayan

      	Şerif Bey''in taburundan

           		bir garip oğlan idi rahmetli

Bir küçük kardeşi vardı aynı taburda asker

Elleriyle koymuş kara toprağa

Bir atı yaralamak suçundan öldürülen ağasını

Yasını hangi söz teselli eder

Kim dindirir yaşını

Garip anam / yetim anam / al anam

Canımın çatalı koptu dalından

       	düştü kara topraklara çabuk gel anam

Kızıl kan kesti gözleri

Kızılcahamam’a doğru at sürerken

Kâr etmedi askerlerin söyledikleri

Hain değil - düşman değil

Köle değil ki bu / asker

Öz kardeş yarası ölünce geçer...

Vardılar yatsıdan önce Kızılcahamam’a

Sessizce kuruldu çadırlar

Derin bir yas içinde atları suladılar

Yeygi verip tımarladılar

Genç askere yasaldıya vardılar

           	konuşamadılar

Havada müthiş bir hüzün kokusu

       	çığsilah uykuya vardılar

Arif Bey''in çadırında emir subayı

     	dimdik ayakta duruyor

           		ateşe hazır silahı

Arif Bey yorgun mu yorgun uyuyor

Çadırının çevresinde dört asker

           	sessizce nöbet tutuyor

Söylenir ki

     	kimsecikler görmeden

Bir karartı yaklaştı Arif Bey''in çadırına

Bir bıçak kesti brandasını

Bir namlu uzandı içeri

Vardı Arif Bey''in başına ateşlendi

Kan ve beyin fışkırdı patlayan kafa tasından

Sıvandı kan ve beyin çadırın her yerine

Ve kayboldu karanlıkta silahı sıkan

Fırlayıp çığ silah geldi askerler

Ne yapacaklarını bilemediler

Her kafadan bir ses kapladı ortalığı

İçimize casus sızdı dediler

Gidip bulalım / Varıp kaçalım

Kimse kumandan olamadı Arif Bey''in yerine

Milisler ayrılıp at sürdü sabahı beklemeden

Nizamiye erleri ve subaylar

       	sabahleyin Ankara''nın yolunu tuttu

Ve son kalan çeteler bindiler atlarına

    	Mahmuzladılar Afyon dolaylarına

Dediler ki

        	devrim''in en büyükleri

Yarbay Arif Bey ve benzerleri

Belki zaman zaman zalim ve deliydiler

Kan ve ateş günlerinde böyle şeylerin nedir değeri

Yüz binlerce can verilip varılan

ulusal kurtuluşun

          		demirden pençesiydiler

Zararından bin fazladır iyilikleri....

Söylenir ki

       	Kızılcahamam''ın Şıhlar Köy''ünden

Hafız Halil diye biri

      	yüreği yas içinde

       		ağlayarak yıkadı Arif Bey''in cenazesini

Evvel zaman Yarbay Arif atlılarıyla

Kızılcahamam''a gelmişti kış çıkarmağa

Milisleri sıkıştırdı köyleri

Atlara arpa almağa

Her köy payına düşeni getirdi

Tek Şıhlar Köyü

     	çıkıp Arif  Bey''in huzuruna

Arpa veremeyiz dedi

Arif Bey kükredi

Vereceksiniz

Ve köy kurulundan Hakkı

Arazimiz taşlık dedi

Gücümüz yoktur vermeye

      	ne arpa ne de saman

Amanı bilin mi Yarbayım / el aman

Arif Bey gazaba geldi kalktı yerinden

Köylüler tir tir titredi

Ve tir tir titreyerek

İki adım öne çıktı birisi içlerinden

Koynundan bir Kur''an çıkardı

Okumağa başladı derinden

Arif Bey kalakaldı

Yumşadı yüzünün demirindeki öfke

Okudu Hafız Halil / sesi yanık / kıraatı tam

Ve yaşlar süzüldü siğim siğim

Arif Bey''in yanaklarından

Kur''an bitti 

Söylenir ki Arif Bey defolun ulan dedi

Bir daha çıkmayın karşıma

Yalnızca bu adam kalsın Kur''an okuyacak bana

Hafız Halil anlatır ki

Kızılcahamam Karargâhında kaldım bir hafta

Arif Bey rakı içti her gün

Her gün Kur''an okuttu bana

İki nöbetçi dikti kaymakamın kapısına

Koskoca kaymakam izinsiz çıkamadı dışarıya

En iyi arkadaşı Kızılcahamam Malmüdürü

Gezip söyleşirlerdi Soğuksu boylarında

Hey gidi Arif Bey Nasıl teslim olurdu Kur''an sesine

Bir keder sarardı yüzünü

Ben okurdum / Ve o ters oturup sandalyesine

     	önüne eğip başını ağlardı her seferinde

Hem deli - hem akıllıydı diyene eyvallah / tamam

Hem iyi - hem kötü diyene

bir şey diyemem

Ama sapına kadar yiğit

Katıksız vatanperverdi vesselam

Lâkin 

      	bir Kur''an dinleme faslından sonra

Her nedense öfkelenip

        	bağırdı orada bulunanlara

Mustafa Kemal de kim oluyor be

Memleketin başka adamı yok mu

Hepsine göstereceğim

Bahara çıkalım hele...

devam edecek', 'Aç çekirge orduları gibiydi Gözleri cinnetli sarı Sürü sürü saldırdılar Cinayet kızarmış duyargaları Yeşil başak bir tarlayı talanlar gibi  ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":191,"source_url":"https://www.antoloji.com/ates-cicegi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-sevki-atik-t5dx9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soluduğum havayı,

sokağa serpti rüzgar.

Susayan düşünceme

kaskatı ördü duvar.

Çark etti deli sevinç

Çılgın heves unuttu.

İçimde gülen çocuk

dile gelmeden sustu.', 'Soluduğum havayı, sokağa serpti rüzgar. Susayan düşünceme kaskatı ördü duvar. Çark etti deli sevinç Çılgın heves unuttu. İçimde gülen çocuk ...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-226-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severken', 'severken-mustafa-sargin-41d7j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden söylemedin severken

acımadınmı beni benden alırken

cemre misalı kalbime düştün 

inandırdın bir bakış bir gülüşünlen

yıktın içimdeki maziyi benden

ensonunda ben senin oldum

Sevgi uzun kırbaçmış meğer 

alınan beddua insanı yok eder

rüya değil gördüğün ey mustafa

gönlün suskun ne söyler 

ırmak olup taşsan neyler

nice ümit yolların önünde ey mustafa', 'Neden söylemedin severken acımadınmı beni benden alırken cemre misalı kalbime düştün  inandırdın bir bakış bir gülüşünlen yıktın içimdeki ma...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/severken-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Seviyorum', 'olumu-seviyorum-sevki-atik-0y998', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ölümü seviyorum.

O,bana geldiğinde sevineceğim.

Bir balta nasıl ağacı

Yarıyorsa orta yerinden

Ben de ölüme öyle gideceğim.

Boş ver bir ayda bin kere ölüme.

O gün geldiğinde

Sadece bir kere

Ölüme merhaba...diyeceğim..

Boş ver dalkavukların sırça sarayına

Dalgaların her gün yakarışına boş ver.

Krlenmiş dünyaya arkamı döneceğim.

Selam vereceğim sonsuzluğun tahtına

Ve sonra; 

Melek-ül mevtin elini öpeceğim..', 'Ben ölümü seviyorum. O,bana geldiğinde sevineceğim. Bir balta nasıl ağacı Yarıyorsa orta yerinden Ben de ölüme öyle gideceğim. Boş ver bir a...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olumu-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sevki-atik-j8uko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bedenim ateşten

Bir

Gömlek giymiş.

Her asrın yaktığı

Odda yanarım.

Savaşlar alevden

Sellere

Dönmüş.

Barıştan bir damla

Suda sönerim.', 'Bedenim ateşten Bir Gömlek giymiş. Her asrın yaktığı Odda yanarım. Savaşlar alevden Sellere Dönmüş. Barıştan bir damla Suda sönerim....', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-254-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Koyalım İnsanların Gülüşlerine', 'bas-koyalim-i-nsanlarin-guluslerine-nilgun-acar-ritcd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel diyorsun

bütün zincirlerini kır

yozlaşmış yargıları

eriten tutsaklıkları

bakışlarınla ışıt karanlıkları

ağız dolusu yıldız tükür

çözülsün yaşamın buz tutan yüreği

bırakak çiçekli ellerini avuçlarıma

gömülsün çürümüşlükler yedi kat toprağa

gel diyorsun

kurtul altın kafesinden

çırılplak özgürlüğe bürün

savur saçlarını dalgalansın dünya

tanrı olalım yarınlarımıza

omuz verelim geceye gündüze

baş koyalım insanların gülüşlerine', 'Gel diyorsun bütün zincirlerini kır yozlaşmış yargıları eriten tutsaklıkları bakışlarınla ışıt karanlıkları ağız dolusu yıldız tükür çözülsü...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bas-koyalim-insanlarin-guluslerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Ha', 'sakin-ha-sevki-atik-92tab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinizden biri

Öldürsün beni.

Kalanlarınız,

Tükürsün

Yaşanacak ömrüme.

Sakın ha...

Ardımdan

Hayır yapmayın.

Varsa

Ek dersim

Vergi iadem,

Onunla

Kalan borcumu 

ödeyin....', 'İçinizden biri Öldürsün beni. Kalanlarınız, Tükürsün Yaşanacak ömrüme. Sakın ha... Ardımdan Hayır yapmayın. Varsa Ek dersim Vergi iadem, Onu...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sakin-ha-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz', 'siyah-beyaz-bekir-mutlu-gokcesu-wq51s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rengi yazmak isterdim

Bir rengi yazmak, kendiliğimden

Yazdıkça koyulaşıp, kabarmalıydı gölgeleri

Sağanak bulutları gibi toplamalı, içmeliydi kederleri

Yüzmeliydi sonra, yüzmeli dilediğince kendi içinde, isterse feri kesilene dek

Ya da isyan etmeliydi, ne bileyim, kendini feda etmeliydi ama kararlı ve gülerek...

Son verip tutsaklığına, fışkırtmak, kaynağı olmak isterdim, yaşamak deli dolu bir rengi

Bir bakışın, sevginin, mutluluğun, bir dokunuşun rengi, en son yansımalarına kadar ta ki...

Ben o renk olmalıydım, geçtiğim her yer o renk olmalıydı, yazdıklarım da lebalep o renk 

Bir sürü şiirler boyamalıydım rengarenk ve kendimce, basit, karmaşık, rasgele, her neyse...', 'Bir rengi yazmak isterdim Bir rengi yazmak, kendiliğimden Yazdıkça koyulaşıp, kabarmalıydı gölgeleri Sağanak bulutları gibi toplamalı, içmel...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siyah-beyaz-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlarda gelsin', 'onlarda-gelsin-saadet-ekinci-bx624', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Din iman kitaptan söz edeceksin

Unutma bir gün ölüp gideceksin

Burada belki rantlar çok kıyak

Öte yanda ama hesap vereceksin

Ortaya yüce bir divan kurulacak

Herkese tek tek hesap sorulacak

O zaman  halin bilmem ne olacak

Kaçmak yok herkes sıraya girsin

Orda dayın yok ki haber edesin

Paranda işlemez rüşvet veresin

Gözlerin tepede kimi göresin

Taksiti  yok bunun, peşin ödersin

Doğruyu yanlışı hiç düşünmeden

Helalı haramı zinhar bilmeden

Nasıl kazanıp, nerden aldın demeden

Hırsızlık yapanlar onlarda gelsin

Seçimde kapı kapı dolaşanlar

Halkın gururunu satın alanlar

Vaatler verip düzen kuranlar

Kendini  bilir onlarda gelsin

İnce ince hesap yapanlar

Her köşede kendine yer kapanlar

Kişiye özel yasa çıkaranlar

Kurtulduk demesin onlarda gelsin

Ülkeme kafir ülkesi, diyenlere 

Konya dar edildi döndüler deliye

Anaya dayak mubahmış ne dersin

Hesap sırasına hele onlarda girsin

Bunca olanlar saymakla bitmez

Sadece kağıda yazmakta yetmez

Her şey kayıtlı silinip gitmez

Ameli bozuklar sıraya girsin.', 'Din iman kitaptan söz edeceksin Unutma bir gün ölüp gideceksin Burada belki rantlar çok kıyak Öte yanda ama hesap vereceksin Ortaya yüce bir...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ekinci']::text[], 8.5, '{"poet":"Saadet Ekinci","poet_slug":"saadet-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/onlarda-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-abdulkadir-karaman-za2z6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah kalktığımda, yine yoktun yanımda… 

özlemin kanıyorken canımda… 

oysa, berâberdik bütün gece 

Ah bilsen düşlerimde neler yaptık, neler paylaştık seninle… 

Yemyeşil ormanlar arasında… 

rengarenk çiçeklerle bezenmiş sonsuz çimenliklerde… 

el ele dolaştık… kelebekleri kovaladık büyük bir zevkle… 

tatminsiz lezzetler bıraktın içime… 

mutluluk dolu gülüşlerinle 

bu gece… 

diz dize oturduk… göz göze bakıştık… 

sevginin ve sevincin coşkusuyla... 

bâzen sen omzuma yasladın başını… 

okşadım saçlarını… 

bâzen ben omzuna koydum başımı… 

saçlarımda gezdirdin çıldırtan parmaklarını… 

ellerimi alıp ellerinle, 

öptün sımsıcak öpüşlerinle… 

ellerini alıp ellerime, 

okşayarak sâkinleştirdim, 

sâdece sana has ilgimle… 

kendimizden geçmiş halde dolaştık kırlarda 

çiçekler koparıp taktım göğsüne 

heyecanlandığında destek olsun diye kalbine.. 

çıktık ve inmeyi istemedik, gökyüzüne 

bulutları kokladık… 

güneşi kovaladık…geceye meydan okuduk 

gündüzü sorguladık… 

yâni ben seninleydim… 

her şeyimle. 

sen benimleydin… 

her şeyinle. 

Dayanılmaz ve doyumsuzdu… 

Rüyada bile, olmak seninle. 

seninle dolu zamanlarla işledim 

her şeyimi… 

seninle ve sevginle boyadım. 

ama seni bulamadım yanımda 

o mutluluğun verdiği sarhoşlukla uyandım 

oldu mu ya, bu yaptığın? 

oldu mu ya, aldattığın? 

Ağlattığın oldu mu ya? 

her seni anışta içim burulur… 

acı duyarım 

ne olur! 

hiç değilse, 

acı vermesin rüyalarım! ... 

22.10.03', 'Bu sabah kalktığımda, yine yoktun yanımda…  özlemin kanıyorken canımda…  oysa, berâberdik bütün gece  Ah bilsen düşlerimde neler yaptık, nel...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ruya-240-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Paylaşalım', 'gelin-paylasalim-sevki-atik-dh0y5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelin

Dilim dilim

Ekmeği paylaşalım

Rüzgarı,karı,ayazı paylaşalım.

Paylaşalım uykuyu

En kesif gecelerde

Gelin

Yarını paylaşalım,düşüncelerde.

Güneş,

Yalnız ne sana,ne de bana

Sıcağı paylaşalım kardeşçe.

Gelin

Ölümü paylaşalım

Bosna''da,Şırnak''ta,Halepçe''de

Acıyı paylaşalım,eşitçe..

hepimizin yüreğinde kopsun fırtına

Hepimizin gözyaşları aksın Dicle''ye

Oluk oluk kabarsın duygularımız,sevince.

Gelin

Üzüntüleri paylaşalım,delice.

Kaç ömür bal eyledik kuru ekmeği

Kaç bahar özledik denizi

Artık uğramaz oldu yanımıza kahkahalar

Gelin paylaşalım

Zeytini,peyniri

Hakça paylaşalım zinciri.

Tabutlar,yalnız benim omuzlarımda

Yalnız ben kurşun sıktım,sevince

Gelin; 

Huzuru paylaşalım kardeşçe.

Hep benim kapımı çalar sessizlik

Kiracı benim,davacı ben

Hep benim öz diyarımda,parya

Sabaha koşulan hep benim

benim namluya sürülen,angarya.

Ben bilmem barları,pavyonları

Karabasan büktü belimi

Geceler,hepimize karanlık

Günler,hepimize olsun aydınlık

Gülüyorsak hepimiz gülelim

Hepimiz bilelim Antalya''ya

Marmaris''e birlikte uçalım

Zonguldak''ta grizu patlamış

Gelin

Birlikte paylaşalım...

.

Yansın yakamozlar gibi

Yıldızlar içimizde

Hasretimiz,damla damla

Birikip kalbimizde

Takalım kan güllerini

Yarınların bileğine.

Açlığı ve acıyı

İki parça kıymık gibi

Atalım,

Atalım yaramızdan.

Gelin,

Ellerimizi birleştirip alnımızda

Ve

Alnımızın son perdesini kaldırıp,

İnsanlığın son tangosunu oynayalım

Varsa yyüreğiniz 

Ölüme birlikte gülelim.

Gelin tek tabutta ölelim.', 'Gelin Dilim dilim Ekmeği paylaşalım Rüzgarı,karı,ayazı paylaşalım. Paylaşalım uykuyu En kesif gecelerde Gelin Yarını paylaşalım,düşüncelerde...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/gelin-paylasalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delice sevdiğini', 'delice-sevdigini-mustafa-sargin-nw9iv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşklarına doymadan yarım kalan

biz eskittik o yılları ağlamadan

diyen nice aşıklar gibi

sevipte birbirine sırt çevirenler

çıkmazdı hiç aklımdan

bende umutsuzdum sevgilim 

sevdiğim günden beri

delice sevdiğini şimdi anladım

sevinçten dilim tutuldu

duygularımı sana anlatamadım

ben mutluyum diyordum

yarına doğacak güneşimden

her günün sabahında yüzyüze geldiğimizden

sevgimizin o kadar üstünlüğünü anlayamamıştık', 'Aşklarına doymadan yarım kalan biz eskittik o yılları ağlamadan diyen nice aşıklar gibi sevipte birbirine sırt çevirenler çıkmazdı hiç aklım...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delice-sevdigini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Sevda', 'ask-ve-sevda-sevki-atik-w0h60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin dudağı bak

Göklerle kenetlenmiş.

İlahi emir böyle

Bu sevda denetlenmiş.

Dağlar mekanla uyum

Bu aşkı bilemekte

Siz de sevişin haydi! 

Bunu Hak dilemekte.', 'Denizin dudağı bak Göklerle kenetlenmiş. İlahi emir böyle Bu sevda denetlenmiş. Dağlar mekanla uyum Bu aşkı bilemekte Siz de sevişin haydi! ...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-ve-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Öbür Yüzü', 'askin-obur-yuzu-nevin-kalafatoglu-rwwcz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canının yandığını biliyorum aşk

Neşter izinden acıların var

Sakladığın yüreğinin rengi

Benim ki mor bilesin

Alev almış duygulardan arınmış 

Şarabi bir tutuklu gibi

Ölüm sancılarını saklıyor içinde

Ya da yok olmak aşk varken

Çevir beni tersime

Düşün ve düşle dersin

İmgelerden ürersin aşk

Şimdi

Bir küçücük melek  kondu konuverecek

Elinde mor bir menekşe

Tütün kokulu bir ev

Sevmek kalp ağrısı tersine

Yoksa ölmek mi duygusuzl

Kaçamak yiğitlik mi huysuz

İki adım da özgürlük demek değil 

Aşk sa tam tersi

Öbür yüzüne bakmak yüreğin

Rengine varmak belki de

Ruhum tutuklu olmalı aşka

Işık süzülür gün gün denize

Ki her bahar gök patlar Akdeniz’de

Nurların döküldüğü ışıklarla yunarsın

Çevir beni tersime

Düşün ve düşle dersin

İmgelerden ürersin aşk

Şimdi 

Bir küçücük melek  kondu konuverecek

Elinde mor bir menekşe

Aşk iki yüzlü bil…

07.03.2006/LARA', 'Canının yandığını biliyorum aşk Neşter izinden acıların var Sakladığın yüreğinin rengi Benim ki mor bilesin Alev almış duygulardan arınmış  ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/askin-obur-yuzu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ocak', 'ocak-altay-taskin-f741z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tütüyorsa ocağın dumanı

orada vardır hayat

dumanı ak da olsa kara da

hayata birileri bağlı...', 'tütüyorsa ocağın dumanı orada vardır hayat dumanı ak da olsa kara da hayata birileri bağlı......', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ocak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmayan Çiçekler', 'solmayan-cicekler-sevki-atik-xs2ju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '..............................................Öğrencilerime

Kuruyan bir ağaçtım,

Dalıma siz kondunuz.

Tertemiz sevginizi

Kıskanmadan sundunuz.

Şarkıdır kulağımda

Ölsem de sözleriniz.

Ruhum yıkanır yavrum,

Denizdir gözleriniz.

Ecelim de olsanız,

Öper,bağrım açarım.

Kalbim size açıktır,

Sığdıramam,naçarım.

Savaşlarda vurulur,

Melek olur isminiz.

Gökyüzünde parlayan,

Yıldızlara eşsiniz..

......

........', '..............................................Öğrencilerime Kuruyan bir ağaçtım, Dalıma siz kondunuz. Tertemiz sevginizi Kıskanmadan sundunu...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/solmayan-cicekler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-sevki-atik-dsxdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anne deyince dilim,

dilenir sevgi anne.

Bugün kendime elim

Barıştır beni anne.

Çocukken kuçağında

Hayat bu,sandım anne

Bu yaşam kavgasında

Ağlamak boştur anne.

Günüm her çizgisine

damlar,düşerdin anne.

Şu zaman silgisine

Dur desen keşke anne.

Ömrümü silebilsem

yeniden yazdır anne.

Ah! sensiz gülebilsem...

Cennet mi? Azdır anne..', 'Anne deyince dilim, dilenir sevgi anne. Bugün kendime elim Barıştır beni anne. Çocukken kuçağında Hayat bu,sandım anne Bu yaşam kavgasında A...', ARRAY['Türk Edebiyatı','Şiir','Şevki Atik']::text[], 8.5, '{"poet":"Şevki Atik","poet_slug":"sevki-atik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öç', 'oc-altay-taskin-ctdd5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşlanınca duvar olur dostum

yataklar kucak açar

ayaklar taş bağlar

hayatın dibine...

baston eş arar kendine

göz kırpar dengine

öç alır

sahibinden kendince...', 'yaşlanınca duvar olur dostum yataklar kucak açar ayaklar taş bağlar hayatın dibine... baston eş arar kendine göz kırpar dengine öç alır sahi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oc-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '~~Sarmaşdolaş Voltalar~~', 'sarmasdolas-voltalar-burcu-alpaslan-guvenli-uckun', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tut 

 ma

düşlerini

bırak

soluksuz an/ larını

gece/n gündüz/ün

hepsini koy bir kenara

acılarını savur

yük/len

unuttuğun düşlerini

yük/len

korku__larımı

sarmaşdolaş voltalarda

korkularımla/ düşlerin

ne yana adım atsalar

aynı ________yollar

otursalar çökseler şöyle bir; 

düşler sessizce

eğiliverse korku/larıma

dertlense; 

paylaşsa.....

son dal sigarasını

bahsetse; 

yük/lendiklerinin ağırlığından 

sevda/nın zorluklarından

acı/ların YEŞİL ormanlarda büyütüldüğünden

ağlasa korkularım; 

kendinden korksa

bir anda düşlerini bırakıp

doğduğu uçsuz bucaksız 

YEŞİL  ormanlara kaçsa.....

Düşler Ser''seridir! 

çığlık çığlık 

korkuların peşinden

yeşil ormanlara dalsa....

düşler korksa

düşler YEŞİL ormanlardan korksa! ! ! 

unutma der Şair; 

______düşler diz çökerde 

korkunun doğduğu yerlerde ağlar....

dayanamaz ki kahretsin! ! 

bilerek yakalanır

korkular/ım

hırpalanmış düşler/ine! ! 

ki; 

öylece aksak...

sarmaşdolaş voltalarda

hala....

korkularımla/ düşlerin

07.03.2006 İstanbul (Yaşasın Düş! gücü)', 'tut   ma düşlerini bırak soluksuz an/ larını gece/n gündüz/ün hepsini koy bir kenara acılarını savur yük/len unuttuğun düşlerini yük/len kor...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sarmasdolas-voltalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma Gülüm', 'kacma-gulum-guner-kaymak-h92rf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim derdim bana yeter

Bir dertte sen açma gülüm

Ayrılık ölümden beter

Bir dertte sen açma gülüm

Açma gülüm açma gülüm

Beni koyup kaçma gülüm

Yalnız arkadaş kalalım

Ömür boyu dost olalım

Ayrılsakta yanmayalım

Bir dertte sen açma gülüm

Açma gülüm açma gülüm

Beni koyup kaçma gülüm

Herkesin vardır yüreği 

Yeminin yoktur gereği

Güner''in bir tek dileği

Bir dertte sen açma gülüm

Açma gülüm açma gülüm

Beni koyup kaçma gülüm

Ozan Güner Kaymak / Amsterdam /07.03.2006', 'Benim derdim bana yeter Bir dertte sen açma gülüm Ayrılık ölümden beter Bir dertte sen açma gülüm Açma gülüm açma gülüm Beni koyup kaçma gül...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kacma-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Merak', 'kucuk-bir-merak-mehmet-orhan-sahin-7amn7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölümden falan değil korkum

toprak kokmak güzeldir

benimki merak 

acaba

nasıl bir ağaç bedenime kök salacak...', 'ölümden falan değil korkum toprak kokmak güzeldir benimki merak  acaba nasıl bir ağaç bedenime kök salacak......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Orhan Şahin']::text[], 8.5, '{"poet":"Mehmet Orhan Şahin","poet_slug":"mehmet-orhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kucuk-bir-merak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla arkadaş...', 'bagisla-arkadas-zafer-zengin-etnika-jfzpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

Git dedim arkadaşa; 

suyumun tadı kaçtı ’hani manasızdı her şey

dilek dilerdik ‘tan vakti olsun isterdik

öyle kırıldı ellerim ’dilimde ölüm emrin

yüreğimden dökülür ‘sevdayı görmemiş yaş

öğretmedi kimse gülmeyi ‘bağışla arkadaş

bitti konuşma ‘gül yüzünde uğurlama

sızılı ayrılış ‘yanak öpüp yolladım

ayrıldım varlığından ‘yüzüne yan olmadan

yüreğimden dökülür ‘denizi görmemiş yaş

öğretmedi kimse gitmeyi ‘bağışla arkadaş

çok istemenin dişleri ‘tırnakları sökülüyor

diyorum ki susayım ‘aşsız susuz kalayım

neden bu sancı ‘neden bu kopuş bağırıyor

yüreğimden dökülür ‘baharı görmemiş yaş

öğretmedi kimse ölmeyi ‘bağışla arkadaş

23 Şubat 2006

.', '. Git dedim arkadaşa;  suyumun tadı kaçtı ’hani manasızdı her şey dilek dilerdik ‘tan vakti olsun isterdik öyle kırıldı ellerim ’dilimde ölü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bagisla-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-tayfun-karakas-rsdq6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi okyanuslar mı temizler seni

Yoksa temizlenmek için bir kaşık su yeter mi

                                                             Beni boğmana

Soruyorum sana nefret mi duyuyorsun bana 

Yoksa onca şeye rağmen yine 

                                                            Seviyor musun beni', 'Şimdi okyanuslar mı temizler seni Yoksa temizlenmek için bir kaşık su yeter mi                                                              ...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Karakaş']::text[], 8.5, '{"poet":"Tayfun Karakaş","poet_slug":"tayfun-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/simdi-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Kavuşmak Olsun', 'adim-kavusmak-olsun-guzin-eye-dundar-bxf0i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kordonda bir akşamüstü 

üç gül sıkacağım şakaklarıma 

nilüferler açacak 

üstüne sisin 

burun kanatlarında 

acı biber kokusu 

ve ölümün tortusu 

bir damla sevda için 

dilinden düşecek beş harf 

kim   öpecek   gözlerimi

saçlarım yosun, ellerim Ege 

adım kavuşmak olsun...', 'kordonda bir akşamüstü  üç gül sıkacağım şakaklarıma  nilüferler açacak  üstüne sisin  burun kanatlarında  acı biber kokusu  ve ölümün tortu...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adim-kavusmak-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır', 'sabir-timur-i-likan-s76us', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabrın kendisi acıdır ama

meyvesi tatlı mı tatlıdır

İnsanı kederden koruyan

sabırla süslü aklıdır

Bu bekleyişlerde kim bilir

ne hikmetler saklıdır

Her şey ALLAH''ın takdiri

O her zaman haklı mı haklıdır

Zorluklara sabreden yiğit kişi

mahşerde koşan bir atlıdır

Cennet semâlarında uçan

melekler gibi kanatlıdır

(7 Mart 2006/ İstanbul)', 'Sabrın kendisi acıdır ama meyvesi tatlı mı tatlıdır İnsanı kederden koruyan sabırla süslü aklıdır Bu bekleyişlerde kim bilir ne hikmetler sa...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sabir-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan-ım-', 'fidan-im-volkan-ersoy-fp8q7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırıp kuru dallarını

Kıyıp aşağıya doğru bakan yapraklarına

Sonra neyse istediğin

En mahrem yerinden bırakmamın sebebi

seyretmek isteyişimden senin büyümeni

Volkan Ersoy 05.03.2006', 'Kırıp kuru dallarını Kıyıp aşağıya doğru bakan yapraklarına Sonra neyse istediğin En mahrem yerinden bırakmamın sebebi seyretmek isteyişimde...', ARRAY['Türk Edebiyatı','Şiir','Volkan Ersoy']::text[], 8.5, '{"poet":"Volkan Ersoy","poet_slug":"volkan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/fidan-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgınım dostlarım sizlere', 'kirginim-dostlarim-sizlere-i-lker-kesemen-x6gy9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostlarım önceden arar sorarlardı 

Şimdi ne arar nede sorar oldular 

Telefon ederim açmazlar 

Mesajlarıma cevap dahi yazmaz oldular 

Yine yanlız bir başımayım ben 

Gönlüm ise bicare 

Günlerim hasretlik içinde gecmekte 

Dostlardan cevap dahi gelmemekte 

Hep dalar giderdi gözlerim 

Taşımazdı bazen bünyemi ayaklarım 

Acıdan ve sancıdan 

İsyan eder oldu artık el ve ayaklarım 

Kendi kendime bazen şöyle diyorum 

Gitti eski dostlar 

Artık ne arar nede sorarlar 

Onlarda yar gibi vefasız oldular 

Saygılarımla                          30,08,2004', 'Dostlarım önceden arar sorarlardı  Şimdi ne arar nede sorar oldular  Telefon ederim açmazlar  Mesajlarıma cevap dahi yazmaz oldular  Yine ya...', ARRAY['Türk Edebiyatı','Şiir','İlker Kesemen']::text[], 8.5, '{"poet":"İlker Kesemen","poet_slug":"i-lker-kesemen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirginim-dostlarim-sizlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış', 'baris-mustafa-sargin-gzl3k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erkenden yola koyulduk

bileciğe doğru

hüzün geceden başlamıştı

beynimizde kıyametler kopuyor

kelimelere dökülmüyor dökülemiyor

çıt yok arabada 

üçbin dörtbin devirlen

yolu bitirmenin gayretindeyim

annesi arkadan oğlusuna

akşamdan yaptığı kurabiyeleri

yermisin diyerek uzatıyordu

iki tane zeytinli vardı

biri bana biri oğlusuna

diyerleri peynirli idi

derken

adapazarı pamukova osmaneli

sardık virajlara dağı tırmanıyoruz

mermer yatakları göründü

tepeyi aştık

kısa bir muddet sonra

bileciğe vardık

beraber olacağı arkadaşlarıylan buluştuk

zaman geçiyor vakit daralmıştı

şeyh edebali türbesine

ziyaretimizi yaptık

aşağıda çadıra gecip

kısa bir dinlenmeden sonra

kalktık ayrılığa adım adım yaklaşıyorduk

son kaçınılmazdı vedalaştık 

sessizlik zirvede 

akıllı ol oğlum dediğimi hatırlıyorum

sensiz dönüyoruz

içimizdeki volkan oluk olmuş

gözlerimizden yaş akıyor akıyordu

kan çanağına döndü gözlerimiz

ben önümü göremiyorum 

yağmurlu havada sileceği olmayan araba gibi

şunu bilesinki

gözyaşlarımla yüzümü yıkamanın 

ne kadar güzel bir şey olduğunu anladım

eve geldiğimizde herşey seni 

bize hatırlatıyordu

yatağının üstüne bıraktığın pantolonun

bizde büyük etki yaptı

kıyamet kopuyordu sanki

bir düğüm boğazıma tıkandı

ölüyorum sanki

bir gayret balkona çıktım

avazım çıktığı kadar

barış diye iki kere bağırdım

haykırışım göklere çıktı hepsi birer yıldız oldu

seni bana hatırlatan', 'Erkenden yola koyulduk bileciğe doğru hüzün geceden başlamıştı beynimizde kıyametler kopuyor kelimelere dökülmüyor dökülemiyor çıt yok araba...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/baris-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölür Gibi', 'olur-gibi-gokhan-ugur-bod27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolun ortasında

Yüzünü elleriyle kapatmış bir çocuğun,

Çarpmasına üç-beş metre kalmış kamyonu

Yüzünde hissetmesiydi çaresizliğim..

Ama ben,

Gömülmeyi bekleyen

Sağ ve sol şeride dağılmış

İki kol, iki bacak

Bir çift göz, bir beden,

Sonra sen geldin,

Sevindim,

…

Bilseydim geleceğini

Ölür müydüm hiç..

02 Temmuz 2001

16:25

Düzce', 'Yolun ortasında Yüzünü elleriyle kapatmış bir çocuğun, Çarpmasına üç-beş metre kalmış kamyonu Yüzünde hissetmesiydi çaresizliğim.. Ama ben, ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Uğur']::text[], 8.5, '{"poet":"Gökhan Uğur","poet_slug":"gokhan-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olur-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadını Bilmek', 'kadini-bilmek-yavuz-bayram-caliskan-3ll3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmeyi bilmektir kadın,

Paylaşmayı, bölüşmeyi,

Hayatın sırlarına koşmaktır kadın,

İklimleri içinde tutandır,

Şefkati, sevgiyi barındırandır,

Dürüstlüğü, temizliği arındırandır,

Aşkla sevdayı tanımaktır kadın,

Bilmektir gizleri ve anlamaktır gerçeği,

Doymaktır yanı başımızdaki hayata.

Med cezirleri yaşamaktır, 

Kaprislerle savaşmaktır,

Yarınlara verilen sözlere bağlanmaktır.

Şımarmalarını sevmektir,

Hayal kırıklıklarını görmektir,

Terk edilişleri bilmektir kadın,

Hasreti ve özlemi sindirmektir,

Gözyaşlarını kucağında dindirmektir.

Kadın gülüştür, kadın öpüştür,

Gözleri gözle görendir,

Uğruna bin defa ölünendir.

Karşılıksız sevebilendir.

Yürekleriyle koşandır,

Anadır, bacıdır, kardeştir, 

Gönlünü verdiğine bir eştir.

Yaşandıkça değerini bilinendir,

Kuşandıkça elmas gibi görünendir,

Bildik dersek yanılırız,

Kadını bilmek zordur,

Sonuçta kadın yardır,

Kimine namus, kimine ardır,

Hep erkeğin yanında vardır.', 'Sevmeyi bilmektir kadın, Paylaşmayı, bölüşmeyi, Hayatın sırlarına koşmaktır kadın, İklimleri içinde tutandır, Şefkati, sevgiyi barındırandır...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kadini-bilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-cemal-simsek-f3jg4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

Hayata gözlerimizi açtığımızda,

Ağlayarak geliriz dünyaya.

Tutarlar iki bacağımızdan,

Ters bakarız dünyaya.

İki Şaplak(1)        indirirler popo’muza,

Başlarız ağlama maratonuna.

Hayatın dikenli yollarında,

Göğüs gererken tüm acılara,

Bazen sel olur göz yaşlarımız

Ağlarız bağıra bağıra.

Bazen de akıtırız göz yaşlarımızı

Yüreğimize damla damla.

Hayatımız ağlamakla geçer,

Doğumdan ölüme kadar.

Ölürken ağlanır mı bilmem ama

Mutlaka  çıkar arkamızdan ağlayan.

(1)       Şaplak: Bazı yörelerde tokat  veya şamar anlamında kullanılır', '. Hayata gözlerimizi açtığımızda, Ağlayarak geliriz dünyaya. Tutarlar iki bacağımızdan, Ters bakarız dünyaya. İki Şaplak(1)        indirirle...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglamak-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cama Yazılan Şiir', 'cama-yazilan-siir-hulki-can-orfj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Lorca bir şiir yazıyor dolmakalemle cama 

Ha bire betikler geliyor uzak ülkelerden 

Hatalar 

Hatalar 

Maymun kayboldu

Bir başka kadınla yemek yiyor

Kara saçlarında bir iki tel ak 

Ona  bakıyor karalar içinden 

Etli ak elleri kar parçası gibi 

Hatalar

Hatalar 

Maymun kayboldu', 'Lorca bir şiir yazıyor dolmakalemle cama  Ha bire betikler geliyor uzak ülkelerden  Hatalar  Hatalar  Maymun kayboldu Bir başka kadınla yeme...', ARRAY['Türk Edebiyatı','Şiir','Hulki Can']::text[], 8.5, '{"poet":"Hulki Can","poet_slug":"hulki-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cama-yazilan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ambidekster', 'ambidekster-hulki-can-89hnf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki gözü

