INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenme', 'seslenme-olcay-aydin-9yfgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadınım.Acizim  belki sana göre.

Eksik olanım,kırılanım,kanan,kanayan,

Hem unutmayan hem ders almayanım.

Kapıdan çıkmayan camdan bakanım

Sana göre...

Bilemedin oysa güzelliklerimi,

Gözlerimden bakanların dahiliklerini.

Bilmediğin için

Kadınım hala.', 'Kadınım.Acizim  belki sana göre. Eksik olanım,kırılanım,kanan,kanayan, Hem unutmayan hem ders almayanım. Kapıdan çıkmayan camdan bakanım San...', ARRAY['Türk Edebiyatı','Şiir','Olcay Aydın']::text[], 8.5, '{"poet":"Olcay Aydın","poet_slug":"olcay-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seslenme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darginya''lilar', 'darginya-lilar-tulay-esat-o6rix', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili olamadilar Darduyar’lilara

Hepsini bu yüzden yordu Darginya’lilar

Cepleri umutlarla doluydu, sarkardi

Sirlarini yapitlarla sundu Darginya’lilar

Cocuk seslerinden, sokak serserilerinden

Kilibik sevenlerden mizah toplarlardi

Kimisi oyalardi düne küs bakislilari

Böylelikle gevsetirlerdi catik kaslilari

Sevmeyene darginlardi Darginya’lilar

Acligi tozatarak yayan kurakliklari

Sulamaya yatkindi onlarin parmaklari

Gökdelenler kisinda dag baslarindan

Gelmeye hazirlanan yavuklulari vardi

Onlar tüm insanlara yardi

Yankili protokoller getirmislerdi

Adem’le Havva’nin gecim tarzindan

Deri rengi. Dil ahengi, dini, dengi

Cinsiyeti ayirmazdi onlardaki sevgi

Dik yokusa düz gecitler kurdular

Bunlarla sonsuza bir yol buldular

„Darilmayi hic bilmedik“der gibi

Darginyada tebessümdür her biri

TÜLAY ESAT', 'Sevgili olamadilar Darduyar’lilara Hepsini bu yüzden yordu Darginya’lilar Cepleri umutlarla doluydu, sarkardi Sirlarini yapitlarla sundu Dar...', ARRAY['Türk Edebiyatı','Şiir','Tülay Esat']::text[], 8.5, '{"poet":"Tülay Esat","poet_slug":"tulay-esat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/darginya-lilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bes Kurus Degerim Yokmus', 'bes-kurus-degerim-yokmus-mustafa-aslan-2-9qh8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sinirliyim,

Kafam bozuk,

Binbir düsünce,

Hepsi kötü,

Tek kelime,

Tek hece,

Ölüm.

Denedim,

Veren ALLAH almadi canimi.

Küçük düstüm,

Bir aciz için,

Azize isyan ettim,

Varligini inkar ettim,

Pisman oldum,

Hastaneye kaldirildim,

Bir gün boyunca yattim,

Uyanmak istememistim,

Uyandim,

Gözüm saga sola bakiyordu,

Bir seveni ariyordu,

Göz yasina boguldum,

Bulamamistim,

Ne annemi,

Ne abimi,

Nede canimdan çok sevdigim yar’imi.

Bulamadim,

Görmeye bile gelmediler,

Çildirdim,

Kalktim,

Kaçtim hastaneden,

Okuluma gittim,

Yar’ime vardim,

Sordum neden gelmedigini,

Cevap olumsuz,

Gelmemek için kendimi zorladim dedi,

Anla yanlis yaptigini,

Tamam anladim,

Elin kizi,

Ölsem belkide umrumda olmaz.

Ya beni dokuz ay karninda tasiyan annem,

Ya bana 21 yildir arkadaslik eden abim,

Onlar niye gelmedi,

Çildirdim,

Sinir kirizi geçirdim,

Kimsenin umrunda olmadi belkide.

Kendimi yerden yere vurdum,

Ne anladim,

Sakin hiç birsey demeyin,

Degerimi anladim.

Bes kurus degerim yokmus.

Allahima isyan ettim,

Kusura bakmayin,

Ben tövbemi yaptim.

Hiç birsey olmamis gibi yar’imle devam ettim konusmaya.

Iyi bir gün sayilmazdi belkide,

Belkisi falan kalmadiya neyse.

Eve geldim,

Annem, abim bir ses yok,

Nasilsin,

Nasil oldun diye soran yok.

Sessiz çok sessiz,

Derdimi anlatacak bir arkadas,

Yaninda gezecek bir yoldas,

Yok.

Bir arayan,

Bir soran yok.

Nezaman olduki simdi olsun.

Sessizlik çöktü,

Ferdi Tayfurdan bir sarki,

Sizladi yüregim.

Defalarca tövbe ettim,

Bir söz bekledim ailemden,

Tövbem kabulmu bilmem ama,

Ailemin gözünde bes kurus degerim yokmus,

Bunu iyi anladim.

Tarih Ve Saati: 07-03-2006	23:49', 'Sinirliyim, Kafam bozuk, Binbir düsünce, Hepsi kötü, Tek kelime, Tek hece, Ölüm. Denedim, Veren ALLAH almadi canimi. Küçük düstüm, Bir aciz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/bes-kurus-degerim-yokmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NurLaR YaĞaR HeR GeCe..', 'nurlar-yagar-her-gece-nusret-akbayir-yzefb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateş böcekleri misali, onca yıldızdan,

Nurlar yağar her gece, bu yer yüzüne.

Onca.. seyyarenin, hesaplı yolundan,

Tecelliler dökülür, sonsuz düşünceye.

-

Ezelin-ebedin şelale misali surundan,

Bereket, mağfiret yağar.. bu gecelere.

Sorumluyken, verilen her bir duyudan,

Nice ışık, ilham.. serpiştirilir gönüllere.

-

.

06/03/2006/n.a./

İzmir.', 'Ateş böcekleri misali, onca yıldızdan, Nurlar yağar her gece, bu yer yüzüne. Onca.. seyyarenin, hesaplı yolundan, Tecelliler dökülür, sonsuz...', ARRAY['Türk Edebiyatı','Şiir','Nusret Akbayır']::text[], 8.5, '{"poet":"Nusret Akbayır","poet_slug":"nusret-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nurlar-yagar-her-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadinlar Günü Kutlu Olsun', 'kadinlar-gunu-kutlu-olsun-kemal-oguz-mame8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sekiz Mart ile övünürüz.

Kadin olmazsa dövünürüz.

Bugün Sizin mutlu gününüz.

Dünyada sesiniz duyulsun.

Hayatiniz boyu gülünüz.

Yolunuz hep aydinlik olsun.

Kadinlar Günü Kutlu Olsun! 

(Filderstadt, 08 Mart 2006)', 'Sekiz Mart ile övünürüz. Kadin olmazsa dövünürüz. Bugün Sizin mutlu gününüz. Dünyada sesiniz duyulsun. Hayatiniz boyu gülünüz. Yolunuz hep a...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kadinlar-gunu-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh ve bedenin hikayesi', 'ruh-ve-bedenin-hikayesi-abdulvahap-ates-nfxwy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ruh bir ışık huzmesi gibi dal dal uçarken

özgürlük badesini etraflara saçarken

Rabbim ense kökünden tuttu bedene attı

sorumsuz uçan ruhu gövde ile donattı

ruh hapsoldu bedene yerini kabullendi

rüyalarda hürriyet gerçekte esir idi

farketti birer birer bindiği bineğini

öğrendi her uzvunu nasıl güdeceğini

alıştı yönettiği et kemik bineğine

tohum attı suladı ekti geleceğine

gün oldu beden onu yönetti yönlendirdi

gün oldu yüreğine düştü bedenin derdi

gün oldu çatıştılar kızdılar bağrıştılar

gün oldu süklüm büklüm oturup ağlaştılar

başka bedenlerdeki ruhlarla da tanıştı

kimi yerinde saydı kimi kendini aştı

ekserisi arkadaş aradı özümsedi

beden bedeni sevdi ruh mağrur gülümsedi

iki ruh iki beden sarmaş dolaş oldular

dünya denen gemiye ne bedenler doğdular

kimisi ayrılmaya getirdi dayandırdı

kimi bıktı bunaldı  intihara kandırdı

bir kısmı ömür boyu bedene  el sürmedi 

bedeni kullanmayan ruhlara deli dendi

bazısı teskereye dek kurallara uydu 

ruh bedeni dinledi beden ruhunu duydu

kimi hapishaneyi kendiyle berbat etti

hem kendini ve hem de geleceği tüketti

ve tükendi vadeler ayrılık vakti geldi

kısa mısaydı ama dünya yine güzeldi', 'ruh bir ışık huzmesi gibi dal dal uçarken özgürlük badesini etraflara saçarken Rabbim ense kökünden tuttu bedene attı sorumsuz uçan ruhu göv...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ruh-ve-bedenin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyorum', 'yuruyorum-mustafa-aslan-2-eojq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Indim otobüsten yürüyorum,

Ama çok üsüyorum,

Sessizce esen kis rüzgari,

Içimde esen yalnizlik firtinasi,

Duygularimdaki kirginlik kasirgasi,

Yürüyorum,

Nereye dogru bilemiyorum,

Boynum bükük,

Agliyorum sessizce,

Göz yasimi buz kesiliyor yüzümde,

Kalbim titrek titrek atiyor,

Beynim durmadan düsünce pompaliyor,

Yüregim sizliyor, yaniyor, sönmek bilmiyor.

Yürüyorum,

Sessizlik var dilimde,

Tek bir kelime yok artik gönlümde,

Sessizim,

Sessizligim kimseye dokunmuyor,

Neyim var soran olmuyor,

Sormayin, sormayin,

Ben sadece yürüyorum.

Tarih Ve Saati: 08-03-2006	00:08', 'Indim otobüsten yürüyorum, Ama çok üsüyorum, Sessizce esen kis rüzgari, Içimde esen yalnizlik firtinasi, Duygularimdaki kirginlik kasirgasi,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuruyorum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Kapıdan Sızdı Nev Bahar', 'eski-bir-kapidan-sizdi-nev-bahar-ahmet-hakan-yilmazturk-eaayw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayazın kavurduğu yoksul kıran kış bahçeme

aralık kalmış eski bir kapıdan sızdı nev bahar

aydınlık yüzlü yalazıyla titredi, soğuk gölgeler

ben alabildiğine mevsimleri yaşamaya gönüllü

seyrindeyken amber kokulu mimozaların, birden

kapandı yalancı kapı, üşüdü toz toprak yeniden

kâh cebimde, kâh yanlara sarkmış ellerim

avuçlamış boşluğu, kaybetmekten korkar gibi

ürkek bakışlı, özgüvensiz bir çocuk, annesini

ışırdın hayata sarılıp, hem dar, hem esen günlerinde

sana bir şey olmaz deyişim, çiğ lokmaymış meğer

sensiz attığım her adımda ömrümden ömür gider

kâh gülüşün, kâh bakışın tazelenir belleğimde

biliyorum, herkes kendi kıyametini yaşıyor

bu yollarda sensiz yürümek içime sinmiyor

7-8 Mart 2006', 'ayazın kavurduğu yoksul kıran kış bahçeme aralık kalmış eski bir kapıdan sızdı nev bahar aydınlık yüzlü yalazıyla titredi, soğuk gölgeler be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eski-bir-kapidan-sizdi-nev-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul kızınca', 'i-stanbul-kizinca-mehmet-can-qzt6g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Islak gökyüzü..

Islak yeryüzü..

Ağlayan bulutlar..

Kızgın rüzgar..

Ve kocaman İstanbul..

Sıcak bir hava

Isıtan bir güneş

Gülen gözler  görmek isteyen.

Yalnız insanlar..', 'Islak gökyüzü.. Islak yeryüzü.. Ağlayan bulutlar.. Kızgın rüzgar.. Ve kocaman İstanbul.. Sıcak bir hava Isıtan bir güneş Gülen gözler  görme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istanbul-kizinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönüs Yolu Bulamadim', 'geri-donus-yolu-bulamadim-mustafa-aslan-2-za59u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendimi kaybettim,

Yada kayboldum,

Gittigim sevdalardan dönemedim,

Ben sevdigimi göremedim.

Gözlerim kör, görmez oldum,

Kulagim sagir, duymaz oldum,

Dilim yok, lal oldum.

Artik ben bir garip oldum.

Sevdim,

Geri dönmek istedim,

Okadar çok sevmisimki,

Kim oldugumu unuttum,

Bu dünyada ne için yasadigimi unuttum,

Kendi kaybetmisimki,

Geri dönüs yolu bulamadim.

Tarih Ve Saati: 08-03-2006	00:17', 'Kendimi kaybettim, Yada kayboldum, Gittigim sevdalardan dönemedim, Ben sevdigimi göremedim. Gözlerim kör, görmez oldum, Kulagim sagir, duyma...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geri-donus-yolu-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askta Gurur Olmaz', 'askta-gurur-olmaz-mustafa-aslan-2-4bjqu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana hep askta gurur olmaz demislerdi,

Inanmiyordum,

Hadi ya,

Böyle saçmalikmi olur diyordum,

Insan asik olduktan sonar anliyormus,

Askta gerçekten gurur olmazmis.

Kiracak sözler söyledi,

Gurur yokmu sende dedi,

Insan degilsin,

Savasta kötülük seni yendi.

Ne diyorsun sen,

Ne gururu,

Severken gururmu kalirmis,

Inanmam,

Dönmem artik sözümden,

Düsmez bu sevgi gözümden,

Artik duy be sesimi,

Anla beni,

Ne dersen de,

Yeterki sev beni,

Anla artik anlasana,

Askta gurur olmaz,

Benim gururum seni severken yokoldu.

Tarih Ve Saati: 08-03-2006	00:22', 'Bana hep askta gurur olmaz demislerdi, Inanmiyordum, Hadi ya, Böyle saçmalikmi olur diyordum, Insan asik olduktan sonar anliyormus, Askta ge...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askta-gurur-olmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar Gününüz Kutlu Olsun Kadınım.', 'kadinlar-gununuz-kutlu-olsun-kadinim-mehmet-ali-demircan-f1r4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün senin günün gülümse hüzün gönlünce,  

Kadınlar gününüz kutlu olsun kadınım.         

Kıymetin bilinmez bitmez ömrün boyunca,          

Kadınlar gününüz kutlu olsun kadınım.        

Tarlada, elinde orak kaderi biçen,     

Nazlandı diye dövülen, suskuyu seçen               

Yaban ellere atılıp, dünyadan geçen,

Kadınlar gününüz kutlu olsun kadınım.         

Çarşı, pazar zor gelince âdemler kaçar,

Evi, barkı o temizler kendinden geçer,

Akşam yemek yoktur diye tokada naçar,

Kadınlar gününüz kutlu olsun kadınım.

“Saçı uzun aklı kısa”, hakir görülür, 

Güçsüzdür zayıftır avrat, ceza verilir, 

İnsafsızca yaşamına çorap örülür, 

Kadınlar gününüz kutlu olsun kadınım. 

Katillere gelin değil, sen afiyetsin,

Can yerine BERDEL olan düşük diyetsin, 

Yobaza, gözü dönmüşe, kötü niyetsin,

Kadınlar gününüz kutlu olsun kadınım.

Kaderine isyan edip, garibim ağla, 

Ucuz kıymet biçenlere hâla el bağla,           

Sesini çıkarma yutkun, hep yürek dağla,             

Kadınlar gününüz kutlu olsun kadınım.

Bilmez misin adın candır, canandır, yardır,

Her yiğidin gönlünün bir sultanı vardır,

Yokluğun yürekte ateş, sönmeyen hardır,

Kadınlar gününüz kutlu olsun kadınım.

Sen, sessiz kaldıkça devran hep böyle gider,

Düzen değişmez, o çilen hep devam eder,

Yırtınsa da Demircan, hep hüzün, hep keder, 

Kadınlar gününüz kutlu olsun kadınım.

MADemircan.*Radyoerguvan.com

*** Aynalar Gerçeklerin Ta Kendisidir.

Konuş onunla, Doğruyu Söylemekten Çekinmeyecektir. ***', 'Gün senin günün gülümse hüzün gönlünce,   Kadınlar gününüz kutlu olsun kadınım.          Kıymetin bilinmez bitmez ömrün boyunca,           K...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kadinlar-gununuz-kutlu-olsun-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale''de Uyanış', 'canakkale-de-uyanis-nihat-malkoc-xhay5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kasırgalar savurur; buz kestirir kar bizi

Gece gündüz kavurur sıcağında nâr bizi

Çanakkale’de zaman açılır sonsuzluğa

Çağırır gül yüzüyle agûşuna yâr bizi

Sabır ateşten gömlek, dua semaya kapı

Bülbülün nağmesinde yakar ahûzar bizi

Gözlerim kapanmadan ruhum dalar uykuya

Elinde kırmızı gül, çağırır mezar bizi

Fazilet yarışında önde gider yiğitler

Zekeriya misali bölse de hızar bizi

Gayya çukurlarından beslenirse kem gözler

Sirkeyle bal misali öylece bozar bizi

Kalbin orta yerine siner kirli bakışlar

Kendimize getirir ilâhî nazar bizi

Gök yarılsa ikiye, gün batsa da şafakta

Çağların göbeğine tarihler yazar bizi

Gök kubbenin altında dolaşırken avare

Hicran ateşlerine atar intizar bizi

Hafakanlar basmadan yetiş rahmet meleği

Ölüme çeyrek kala çepeçevre sar bizi

Efkâr basar sinsice hüzün coğrafyamıza

Sevgilinin hayali eder bahtiyar bizi

Gelibolu’da yağmur fırtınaya dönüşür

Sular kaynar derinden, ateşi yakar bizi

Ürperir maveradan koparıldıkça ruhlar

Maziden arda kalan sermaye bakar bizi

Ölü toprağı serper, gaflet kurşundan ağır

Bir kez uyumaya gör yılanlar sokar bizi 

Doğar Anafartalar alacakaranlığa

Aynadaki akisler Hakk’a muştular bizi

Zaman alevden bir gül, safın önünde kısrak

Düşmanı haklarım ben dostlardan kurtar bizi

Kirli çizmeleriyle girer de haremime

Hallac-ı Mansur gibi beyhude soyar bizi

Kapımın kilidini çalan dünkü devşirme

Düşünmez, bir kalemde kızıla boyar bizi

Ay ışığı düşerken kapkaranlık geceye

Uyanışın öncüsü, muzaffer sayar bizi

Diner Çanakkale’de esen acı karayel

Suya düşer cemreler ısıtır bahar bizi', 'Kasırgalar savurur; buz kestirir kar bizi Gece gündüz kavurur sıcağında nâr bizi Çanakkale’de zaman açılır sonsuzluğa Çağırır gül yüzüyle ag...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/canakkale-de-uyanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Duramam 2000', 'sensiz-duramam-2000-yasar-gurlek-2dxqc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anasiz  cocuklar  gibiyim

Gitme  can  sensiz yapamam

Delicesine  sevdim  seni

Ben  sensizlige  dayanamam

Benim  umut  askim  sendin

Gitme  can  sensiz yapamam

Can  canimdan  ayrilirmi

Ben  sensiz  yasiyamam

Ne  olur  gitme  kal  bende

Ben  sensiz  yapamam

Baska  baska  yar  sevip

Kucaklarda  yatamam

Yasar,i   aglar   durur

Gozum  yasli  birakma

Nolur gitme  kal burda

Beni  boyle  birakma

Yasar  Gurlek

Rotterdam

HOLLANDA

08-03-2000', 'Anasiz  cocuklar  gibiyim Gitme  can  sensiz yapamam Delicesine  sevdim  seni Ben  sensizlige  dayanamam Benim  umut  askim  sendin Gitme  c...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensiz-duramam-2000-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür Dilerim', 'ozur-dilerim-esin-cinar-4fpo1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özür dilerim 

Bir anne

Bir kardeş

Bir sevgiliden

Evimde 

Barkımda

Gönül bahçemden

Sokakta

Yollarda

Ana caddeden

Tanımadan da 

Gitsem 

Peşinden

Hata yapmam

Mümkün

Olan birinden

Özür diliyorum

Onun gününde

Gönülden,gönülden ve de gönülden.

Esin Çınar

(08.MART.2006/08.03.2008)', 'Özür dilerim  Bir anne Bir kardeş Bir sevgiliden Evimde  Barkımda Gönül bahçemden Sokakta Yollarda Ana caddeden Tanımadan da  Gitsem  Peşind...', ARRAY['Türk Edebiyatı','Şiir','Esin Çınar']::text[], 8.5, '{"poet":"Esin Çınar","poet_slug":"esin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozur-dilerim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Icin Icin Agladim 2000', 'icin-icin-agladim-2000-yasar-gurlek-7mdpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cok  bekledim  geriye,  donersin  diye

Niye  sevmisimki, seni bu kadar niye

Gunlerim gelip gecti, yar  diye  diye

Ben o  yare  nasilda,  bel bagladim

Gece  gunduz,  yar,  yar,  diye  agladim

Ilk  askimin  yarasi, yillardir  kaniyor

Kalbimde  ates  oldu,  kor  kor  yaniyor

Su garip deli  gonlum,doneceksin saniyor

O  vefasiza  nasilda,   bel  bagladim

Gece  gunduz  onun  icin,  icin,  icin,  agladim

Yasar  Gurlek

Rotterdam

HOLLANDA

08-03-2000', 'Cok  bekledim  geriye,  donersin  diye Niye  sevmisimki, seni bu kadar niye Gunlerim gelip gecti, yar  diye  diye Ben o  yare  nasilda,  bel...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icin-icin-agladim-2000-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cok ararsin cok 2000', 'cok-ararsin-cok-2000-yasar-gurlek-o4maz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep  uzaktan  bakardim

Bir gun donup bakmadin

Her  kosede  aglardim

Ask  atesini  yakmadin

Hep  uzulup  agladim

Bir  gun olsun gulmedin

Mektup  yazip  yolladim

Hic  insafa  gelmedin

Isyan  ettim  ben  sana

Terki  diyar  eyledim

Ey  insafsiz  vijdansiz

Bir kez bari gulseydin

Seni  sana  birakmisim

Artik  senden  umut  yok

Bir  daha  bulamazsin  beni

Cok  ararsin  cok

Yasar  Gurlek

Rotterdam

HOLLANDA

08-03-2000', 'Hep  uzaktan  bakardim Bir gun donup bakmadin Her  kosede  aglardim Ask  atesini  yakmadin Hep  uzulup  agladim Bir  gun olsun gulmedin Mekt...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cok-ararsin-cok-2000-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni 2000', 'sev-beni-2000-yasar-gurlek-93ba0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok  yalvardın  ğitme  diye! 

Dinlemedim seni niye? 

Hasretine  dayanamam

Dönüyorum bak  geriye! 

Daha  düşmem  bir  daha

Bu  gurbetin  yollarına

Dizlerin''de  uyuyacam

Yaslanırım yar kollarına

Ellerimde  ah ellerin

Öyle  tutup  kalacağım

Bir  daha  asla  gitmem

Kulun  kölen  olacağım

Her  derdine  razıyım

Razıyım ben  gelmeye

İnan çoktan razıyım

Kollarında  ölmeye

Can  yanında  öleyim

Al bahçene  göm beni

Çiçek  olur  açarım

Her gün kokla  sev  beni

Yasar  Gurlek

Rotterdam

HOLLANDA

08-03-2000', 'Çok  yalvardın  ğitme  diye!  Dinlemedim seni niye?  Hasretine  dayanamam Dönüyorum bak  geriye!  Daha  düşmem  bir  daha Bu  gurbetin  yoll...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sev-beni-2000-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye yarar dünya kadınlar günü', 'neye-yarar-dunya-kadinlar-gunu-mikdat-bal-380ue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadınları sekiz martta görenler

Neye yarar dünya kadınlar günü

Bütün sene eza çefa verenler

Neye yarar dünya kadınlar günü

Kutlu olsun eğer bir gün yeterse

Bu kadarcık sizi tatmin ederse,

Geri kalan günler çefa kederse

Neye yarar dünya kadınlar günü! 

Yılda  bir gün neye yarar beyanlar

Her gün için anılmalı bayanlar

Hanımları sömürenler soyanlar

Neye yarar dünya kadınlar günü! 

Onlar bizim hem anamız bacımız

Her gün için olmalıyken tacımız

Kutluyorken fitne ise içimiz

Neye yarar dünya kadınlar günü

Yıl boyunca çalışırlar durmadan

Hiç kimseden yardım bile sormadan

Kodamanlar buna kafa yormadan

Neye yarar dünya kadınlar günü

Mikdatî der anam benim meleğim

O canımdır hem kolum hem bileğim

Ömür boyu mutlu etmek dileğim

Neye yarar dünya kadınlar günü', 'Kadınları sekiz martta görenler Neye yarar dünya kadınlar günü Bütün sene eza çefa verenler Neye yarar dünya kadınlar günü Kutlu olsun eğer ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neye-yarar-dunya-kadinlar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraflar Bir Dakikalıktır', 'fotograflar-bir-dakikaliktir-guzin-eye-dundar-6pdyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(fotoğraflar bir dakikalıktır)

kimlikler yırtıldı

unuttu adını

masum  çocukluk

dikenli teller kuşattı

buğday tarlalarını 

çoğaldı yokluk

çöl oldu gözleri anaların

oğul,oğul

çıplak suç 

öylece duruyordu

faili meçhul...', '(fotoğraflar bir dakikalıktır) kimlikler yırtıldı unuttu adını masum  çocukluk dikenli teller kuşattı buğday tarlalarını  çoğaldı yokluk çöl...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fotograflar-bir-dakikaliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sömürgen', 'somurgen-muammer-erturan-xe823', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haftada bir gün 

ayırabiliyorsan kendine

daha ne... 

Her anı seninle dolu 

yedi gün de benden ekle

haftada sekiz gün yaşıyorsun da 

haberin yok desene... 

Haberin yok tabii 

alıp götürdüğünden 

tüm zamanlarımı 

ve tüm zeminlerimi peşinden…

Ah gidi sömürgen! .. 

(Ekim ''94)', 'Haftada bir gün  ayırabiliyorsan kendine daha ne...  Her anı seninle dolu  yedi gün de benden ekle haftada sekiz gün yaşıyorsun da  haberin ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/somurgen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke şiirleri-1', 'ofke-siirleri-1-mehmet-can-klqd9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim ıslak bulutların ardında.. 

Yağmur yağdı,yağacak gibi gözlerimden.. 

Hayat bir fırtına gibi geçiyor. 

Dost bildiklerimin, ihanet zincirlerinden.. 

Hem kazanan,hem yenilen taraf olmak.. 

İntikam alacakken.. durmak.. 

Titrek parmaklarımın arasında duran sigara.. 

Her duman.. 

Her üfleyişte,ayrı bir hülya bulmak.. 

Dosdoğru olmanın cezasıdır çektiğim.. 

Dimdik ayakta durmanın cezası, kırılmak.. 

Bir tek ben miyim tutan sözlerini… 

Öyle ya.. 

Yenilen tarafım yine.. 

Dosdoğru oldum.. 

Suçum insan olmak..', 'Gözlerim ıslak bulutların ardında..  Yağmur yağdı,yağacak gibi gözlerimden..  Hayat bir fırtına gibi geçiyor.  Dost bildiklerimin, ihanet zi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ofke-siirleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımın Belası', 'basimin-belasi-muammer-erturan-rdbyf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şey 

ne berbat bu akşam 

ne yavan      

ne kadar yaban... 

Kahrolası rakısızlık! .. 

Kahrolası parasızlık! .. 

Kör olası kıran! .. 

Duvarlar yok mu ya 

aramızda hele 

yıkılası duvarlar…

Başka şeyler düşün

diyorum kendime 

yoksa sarpa saracak 

kötüye varacak sonu bak! .. 

Olmuyor 

olmuyor 

olmuyor 

olamıyor

ille de sen düşüyorsun aklıma 

ille de gözlerin düşüyor 

İlle de gülüşlerin... 

Düşen benim aslında 

zindanına hasretin... 

Ooof of! .. 

Of ki ne of! .. 

Bir kördüğüm ki gönlüm 

çöz çözebilirsen... 

Kaç mevsim geçmiş 

ateş bacayı saralı 

ne demeye varmış dilim 

ne atabilmişim içimden... 

Ne kurtulunamaz şeymişsin be kız! .. 

Kaçmam imkânsız 

unutmam imkânsız

çıkmam imkânsız menzilinden... 

Sen var ya sen 

ah gidi ah! .. 

Ah gidi 

başımın belası seni! ..

(Eylül ''94)', 'Her şey  ne berbat bu akşam  ne yavan       ne kadar yaban...  Kahrolası rakısızlık! ..  Kahrolası parasızlık! ..  Kör olası kıran! ..  Duva...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/basimin-belasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Ola', 'siirler-ola-muammer-erturan-oycsb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ola ki birgün 

yorgun düşer bu can,

bu suskunluktan...

Göçer giderim apansız...

Ola ki dostlar,

rakı içer başucumda

vasiyetimce...

Ola ki içlerinde sen...

Ola ki bir an,

bir film şeridi gibi geçer,

ıslanmaya yüz tutmuş

gözlerinin önünden,

yoldaşça paylaştığımız o demler...

Bilmeksizin tabii

nasıl vurgun gittiğimi 

sana meğer...

Bilsen ne farkeder hoş,

bilmesen ne; 

herşey için çok geçtir

o son perdede...

Ola ki,

son kez bakıp toprağıma

vedalaşma zamanıdır artık...

Daha fazla kararmadan ortalık zira

koyulman gerek yola...

O sıra işte,

hışırtısıyla karışık yaprakların

bir ses duyacaksın,

tanıdık bir tını,

sol memenin altında:

Uğurlar ola Ömrüm! ..

Şiirler ola! ..

(Ekim ''94)', 'Ola ki birgün  yorgun düşer bu can, bu suskunluktan... Göçer giderim apansız... Ola ki dostlar, rakı içer başucumda vasiyetimce... Ola ki iç...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/siirler-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıblem', 'kiblem-muammer-erturan-fjsjo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günbatımı alacası 

bir derin sızı içimde

bir ince hüzün, 

sazın sözün zincirlendiği 

sekizinci akşam... 

Sekiz gün 

sekiz gecedir tam 

kan kaybediyor durmadan 

en babacan umutlarım... 

Umarsız 

sana koşacağım gene 

dünya kazan 

ben kepçe... 

Düşümde sen 

işimde sen

aşımda sen,

yaşamak denen şey 

senden ibaret sanki

sırf senden… 

Bu nasıl sensizlik 

bilmem

başka kıblem yok be ya! ..

(''95)', 'Günbatımı alacası  bir derin sızı içimde bir ince hüzün,  sazın sözün zincirlendiği  sekizinci akşam...  Sekiz gün  sekiz gecedir tam  kan k...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kiblem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penguence', 'penguence-muammer-erturan-z865j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece daha geçti geçecek 

şafak sökmek üzere 

ve ayrı yerlerde başlayacağız gene 

aynı güne... 

Tükeniyor özleminle saatler 

tükeniyor ömrüm... 

Gördüğüm göreceğim

en beter işkence 

şu sensizlik... 

Uzaklara gidecektik hani 

çook uzaklara 

güneyde kavilleşmiştik ya en son 

en güneyde... 

O düşün büyüsüne işte 

takılıp kalmışım... 

Bir igloda uyanmışım 

yanımda sen... 

Gitmekten söz eden yok 

artık oralıyız 

fısıldaşmalarımız bile 

Penguence... 

(5 Ekim ''95)', 'Bir gece daha geçti geçecek  şafak sökmek üzere  ve ayrı yerlerde başlayacağız gene  aynı güne...  Tükeniyor özleminle saatler  tükeniyor öm...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/penguence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paraylami olculuyor', 'paraylami-olculuyor-ulya-erkman-7u4bp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oldukca guzel 

Bir kizdi

Calistigi kafeteryanin

Yildiziydi

Guzel huyu,nezaketiyle herkesin 

Kalbini kazanmisti''

Burada calisarak ailesine 

Yardimdi maksadi

Bir gun bir genc adam geldi

Kahve icmege

Genc kiz yorulmus oturmustu

Biraz dinlenmege

Kahvesi gelince sordu''izin yokmu

Ara vermege? ''

Baslangicti bu konusma

Beraber gezmelere

Cok sevmisti birbirini

Bu ikisi

Evlenmek istiyordu genc adam

Ciddiydi 

Takdim etmek istedi ailesine

Sevgilisini

Cok zengindi genc adamin

Ailesi

Istemediler fakirce bir kizi

Gelin diye

Genc adam cok iclenmis hakaret 

Saymisti sevgilisine

''Zengin bir kiz ama nemrut birini

Getirseydim evinize

hemen kabul ederdiniz 

Zengin gelin diye

Benim sevgilimin zenginligi kendisidir

Bence

Ailemin  parasina ihtiyacim yok

Oyleyse

Tahsilim var calisir kazanirim bize

Yeterince

Satmam askimi asla

Sizin zenginliginize', 'Oldukca guzel  Bir kizdi Calistigi kafeteryanin Yildiziydi Guzel huyu,nezaketiyle herkesin  Kalbini kazanmisti'' Burada calisarak ailesine  Y...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/paraylami-olculuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürmenaj', 'surmenaj-duygu-gunkut-lrxnr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük laf savsatası

0 kelimeler,

ki kelimelerin ciğerini söker

aklını alırdı

yitmeden

aklımın hastaları.', 'Büyük laf savsatası 0 kelimeler, ki kelimelerin ciğerini söker aklını alırdı yitmeden aklımın hastaları....', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/surmenaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taç yapmak istiyorum saçlarına', 'tac-yapmak-istiyorum-saclarina-elazigli-mustafa-kaya-v0dzj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bahar,

yakın mı.? 

çiçekler dereceğimiz gün gelecek mi..? 

taç yapmak istiyorum

saçlarına.

yıldızları bağlamak  her gece

açılmamış goncama.

Mustafa kaya

08.02.2006 / fatih', 'bahar, yakın mı.?  çiçekler dereceğimiz gün gelecek mi..?  taç yapmak istiyorum saçlarına. yıldızları bağlamak  her gece açılmamış goncama. ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tac-yapmak-istiyorum-saclarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-elazigli-mustafa-kaya-utikx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstemem,

kelebeksiz bir baharı

çiçekler savrulurken içime.

istemem,

yosun  kokmayan denizleri

senin  hatıralarını yaşatırken sahillerde..

istemem,

hiçbir martının  olmadığı gökyüzünü

senin bulutunu taşıyan maviliklerde .



Mustafa kaya

08.02.2006 / fatih', 'İstemem, kelebeksiz bir baharı çiçekler savrulurken içime. istemem, yosun  kokmayan denizleri senin  hatıralarını yaşatırken sahillerde.. is...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istemem-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usulsüz Aşk', 'usulsuz-ask-duygu-gunkut-n36op', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kapalıçarşı''daydın

dört dönüm bostanımdın.

sen; cımbız abla,

dolar olarak ne kadar da pahalıydın..

sen ah sen...

çok pahacıydın galiba abla ya...

düşüştesin,

şu anda düşeş bile olsan...

nakitim.

kendi imalatım.

aşkım,

kapalım.

çarşım.

derbi maçım.', 'kapalıçarşı''daydın dört dönüm bostanımdın. sen; cımbız abla, dolar olarak ne kadar da pahalıydın.. sen ah sen... çok pahacıydın galiba abla ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usulsuz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensın Varacagım Tek Yer', 'sensin-varacagim-tek-yer-savas-cakmakci-zi50s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Askti benim adim bir zamanlar, katran gecelerde zordakine

Yeserirdim yureklerde su yurumus otlar gibi, binlerce

Bir gun adimi yeserttim kendim icin gonlumde ve husran

Utandim kendimden, sarkilardan,senden ve asktan

Adina siirler yazilip sarkilar soylenmis asklardan

Ve tovbe ettim gonullerde yesermeye birdaha

Yoktu birdaha ask, sevmek ve sen 

Sonra yanlizlik oluverdi adim bir anda

Saat onikyi vurdugunda da donup kaldiginda da yanlizlikti adim

Yuregimdeyse nefret tukenmeyen hemde olduresiye 

Bedenin yok oldugunda gececekdi nefretim sandim

Dogru degil bu atamam biliyorum seni

Ne kalbimden ne ruyalarimdan nede diger yarimdan

Dur demek istesem izin vermez gururum 

Dugumler kelimeleri bogazlarima ve ben tekrar yanlizlik olurum.

Simdi adsiz ve yurtsuz bir gocebe

Asklar ve umutlardan yoksun

Yanlizliktan bile yanliz ve sona bes kala kederli

Zeytin dallarindan bile umudu uzmus her nefes

Kimsede yok, yukunu vurmak icin sirtina, etrafinda

Dermaninin yettigi yere kadar kararli yurumekte karanliga

Ismler yok artik mavi dusler ve ruyalar da

Olum ve sen varsin

Sensin varacagim tek yer, orda sen varsin', 'Askti benim adim bir zamanlar, katran gecelerde zordakine Yeserirdim yureklerde su yurumus otlar gibi, binlerce Bir gun adimi yeserttim kend...', ARRAY['Türk Edebiyatı','Şiir','Savaş Çakmakcı']::text[], 8.5, '{"poet":"Savaş Çakmakcı","poet_slug":"savas-cakmakci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensin-varacagim-tek-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Kala', 'bes-kala-savas-cakmakci-bqlvj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasilda tas kesmis yuregim,

Sanki duygularimi eskici babaya satmisim

Sanki takvimimde sadece acilara centik atmisim

Nasilda unutmusum bir sahana kasik atmanin tadini

Birakmis her defasinda hosluklar pesimi 

Birakmislar bosluklarda bir yere lesimi

Sabaha karsi oturmaya basladi aci uzerime

Cekiyorum kendimi yatagin en sicak kosesine

Yanlizlik yaziyorum ruyalarin otesine

Kar, firtina, gunes ve ruzgar bende sankı bır eş

Karisan mevsimler degil sadece bildigim hersey

Kaderse kilavuzum sensizlige bile deger

Tekrar bir sozluk yaziyorum ta en bastan

Mutluluk yok, anne yok, sen yoksun neden olsunki

Bugunden sonra neden bos yerler dosunki

Tek yon yazilmis bu yol fermanima

Yolcular farkli, yuzler farkli

Soylemeyi unutmusum bu tren her seye bes kala kalkti', 'Nasilda tas kesmis yuregim, Sanki duygularimi eskici babaya satmisim Sanki takvimimde sadece acilara centik atmisim Nasilda unutmusum bir sa...', ARRAY['Türk Edebiyatı','Şiir','Savaş Çakmakcı']::text[], 8.5, '{"poet":"Savaş Çakmakcı","poet_slug":"savas-cakmakci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bes-kala-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınımıza', 'kadinimiza-feride-omur-566x9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadın bir gül gibi,sevilmelidir 

Sevgiyi saygıyı, hep görmelidir 

Kadına hakları, verilmelidir 

Sevgi ile bakın kadınımıza 

Kadınlar gününde, olmaz ki dayak 

Gelir de yalvarır,hep yalınayak 

Çileli doğmuşum, yeter bu dayak 

Dayağa sebep ne kadınımıza 

Sevgiyi bulmamış, hep ağlamışsın 

Yazgı demiş yine, sen yalvarmışsın 

Hep ezmişler seni, çile çekmişsin 

Ezilmek yakışmaz kadınımıza

Emek veren, çile çeken kadınlarımızın senede 

bir gün değil hergün hatırlanması umuduyla...', 'Kadın bir gül gibi,sevilmelidir  Sevgiyi saygıyı, hep görmelidir  Kadına hakları, verilmelidir  Sevgi ile bakın kadınımıza  Kadınlar gününde...', ARRAY['Türk Edebiyatı','Şiir','Feride Ömür']::text[], 8.5, '{"poet":"Feride Ömür","poet_slug":"feride-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kadinimiza-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* O Bir Kadındı *', 'o-bir-kadindi-i-brahim-dikmen-2-j9roa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Havva idi adı

insanlığın anası

o bir kadındı

Amine idi adı

muhammedin anası

o bir kadındı

Firavunlar,krallar

ondan oldu

o bir kadındı

Padişahların anası

M.Kemalin anası

o bir kadındı

Beni doğurandı kadın

Can veren ruhuma

Ağladığımda ağlayan

Uykusuz her gece

Baş ucumda sabahlayan

O bir kadındı

Helalim olandı kadın

Tüm mahremiyle benim olan

İyi günde kötü günde

Mutlulukta kederde

Herzaman yanımda olan

Aşkım gönüldaşım

Kaşık düşmanım

Kızımın anası

Hayat arkadaşım

O BİR KADINDI

Tüm Dünya Kadınlarının bu anlamlı günlerini en içten duygularla kutluyorum.

saygı ve sevgilerimle...

08/03/2006

Aydınlı İbrahim Dikmen', 'Havva idi adı insanlığın anası o bir kadındı Amine idi adı muhammedin anası o bir kadındı Firavunlar,krallar ondan oldu o bir kadındı Padişa...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/o-bir-kadindi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul’da Yağmur var', 'i-stanbul-da-yagmur-var-ayhan-isin-zbouc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmur var sokaklarında İstanbul’un! 

nefes alışlarda bahar,

toprak kokusu, 

yüreğimde sen,

iman tahtasında bir sızı,

gidip gelişlerde korku! 

sen ve ben

camda süzülen iki yağmur tanesi,

yağmur fallarında buluşan iki damla.

İstanbul’da hüzünlüdür yağmur,

damlacıklar koşuşur

denize varmak için.

cami avlularında güvercinler,

ıslak korkmuş ve sinmiş.

ben yağmurla dimdik,

sen aklımda,

alev alev! 

Yağmur; sevincim,

umudum,

iman tahtasında sızım,

toprak kokum,

sevinçlerimin heyecanı,

çocuklar gibi koştum suların içine,

gözüne bastım birikintilerin,

ayaklarımı vurdum,

dizlerime kadar ıslandım! 

Sevincim; senden,

yağmurdan,

içimdeki çocuktan! 

toprak kokusunu,

hüzünlü İstanbul’u

iman tahtamdaki sızıyı,

artık YAĞMUR’U 

SEVİYORUM,,,,,,,,,,

07-03-2006 14:20', 'yağmur var sokaklarında İstanbul’un!  nefes alışlarda bahar, toprak kokusu,  yüreğimde sen, iman tahtasında bir sızı, gidip gelişlerde korku...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/istanbul-da-yagmur-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
