INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapraklar', 'yapraklar-halil-aksoy-0qaiw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbaharda…

Dökülen  yaprakları   izlemek,

Acı  verir  bana.

Dalından  kopan  yaprak,

Rotasız  bir  yelkenli  gibi,

Savrulurken  çaresiz,

Kırılıp  giden  umutlar

Boşa  giden  hayaller,

Gelir  hatırama.                              

Uçuşan  yapraklar,

Yaprak  yaprak  savrulurken,

Boş  umutları  yaşamak,

İçimde  bir  şeylerin  değiştiğini,

Anlamak

Anlamak,

Yaşananlarının

Geri  gelmeyeceğini.

Çocukların  gözlerinden  dökülen

Yaşlar  gibi,

Süzülür  tane  tane  akar  yere.

Çocuğun  başını  okşar  gibi.

Okşasam  her birini  bir kere.

Ağaç  salkım  saçak,

Birden  orta  yerde  kala  kalır.

Yaprağı  dökülmüş  ağaç,

Bende  yalnızlık  hissi  uyandırır.

Düşen  yaprakları  izlemek,

Kırılan  hayalleri  canlandırır.', 'Sonbaharda… Dökülen  yaprakları   izlemek, Acı  verir  bana. Dalından  kopan  yaprak, Rotasız  bir  yelkenli  gibi, Savrulurken  çaresiz, Kı...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yapraklar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Rüzgarı', 'karadeniz-ruzgari-kadir-albayrak-k3607', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar esti birden “O yok” dedi sinsice

Parladı gümüş hançer ve saplandı kalbime

Zamanla akıp gider mevsim hazan ve bahar

Ben de kapılacaktım esmeseydi o rüzgar

Afrika’nın yamyamı çalarken tamtamları

Benim için mi esti ayrılık rüzgarları

Böylesine zor muydu karşılıksız sevgiler

Sevenleri mi bulur çaresiz musibetler

Nasıl yok edeyim ben zihnim de şekilleri

Soru sormadan münker hem nekir melekleri

Ard arda taşınıyor yükselen cenazeler

Hiç birinden geldi mi bu güne kadar haber

Bazen yol da görürüm iki aşık kol kola

Eğilmiş güzel sözler fısıldar kulağına

Boğazımda bir düğüm oluşuverir o an

Yırtar sine’lerimi bir türlü yutkunamam

O rüzgar neden esti neden yok dedi seni

Bilmez miydi bu garip senle buldu kendini

Yol yoktu gözlerinden girmek için kalbine

Bana “dur” diyen kim di bu barikatlar niye

Es ey deli rüzgar es, yine es deli rüzgar

Eserken ismin zikret sesinden büyük rüzgar

Siz gelin fırtınalar kasırgalar siz gelin

Tek tek değil! ..Az gelir! ..İsterse birden esin

Arzum unutmak değil yanıp yanıp kavrulmak

Hiç olmazsa “Mabede” bu duyguyla gark olmak

Rüzgar olup esenler, esip bilmezler Hak-kı

Beni çarpan yel değil! .. Karadeniz rüzgarı! ...', 'Bir rüzgar esti birden “O yok” dedi sinsice Parladı gümüş hançer ve saplandı kalbime Zamanla akıp gider mevsim hazan ve bahar Ben de kapılac...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/karadeniz-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalarim', 'sevdalarim-sair-babaxyorgun-olji9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delidir benim sevdalarım gülüm 

Yokluğunda bile seviyorum derim 

Kötü sölemiye varmıyor dilim 

Cümleye sığmıyor sevdalarım 

Aşığım daldaki duran yaprağa 

Ben sana sular toprağa 

Ulaşırmı sesim uzaklara 

İnleşir durur sevdalarım 

Bir selam gönder ne olur bana 

Yüreğimden bir çiçek sunuyom sana 

Kara lekemi sürdüm alnına 

Tertemizdir sevdalarım 

Dağ başında kır çiçekleri 

Toprak ve suya sevgileri 

Şu gönlümdeki gülleri 

Sensiz koklar sevdalarım 

Seni çok özlüyorum bazen 

Yıkılsa keşke bu çarpık düzen 

Dünyada seni en çok seven 

Benim garip sevdalarım 

BABAXYORGUN', 'Delidir benim sevdalarım gülüm  Yokluğunda bile seviyorum derim  Kötü sölemiye varmıyor dilim  Cümleye sığmıyor sevdalarım  Aşığım daldaki d...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdalarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamani', 'zamani-sair-babaxyorgun-zxpgm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deme halını bilmiyene sakın 

Azalır derken çoğalır yükün 

Ne hala geldim hele bi bakın 

Şimdi lokmana gitme zamanı 

Dertlinin derdi dermanda saklı 

Ermez bu sırra delinin aklı 

Yıkılsın namerdin sarayı tahtı 

Mertlik ortamına gitme zamanı 

Dürüstle git açıktır yolun 

Huzuru refahı onunla bulun 

Hepiniz allaha emanet olun 

Yunus yoluna gitme zamanı 

Süzülür gözünde ecel yaşların 

Çatılır dünyaya keman kaşların 

Ağıtlar yakar tüm evlatların 

Rahmetle yoprağa gitme zamanı 

BABAXYORGUN', 'Deme halını bilmiyene sakın  Azalır derken çoğalır yükün  Ne hala geldim hele bi bakın  Şimdi lokmana gitme zamanı  Dertlinin derdi dermanda...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-halil-aksoy-a0vxx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadınım,

Ben  seni  sevdim.

Arının  çiçeği,

Koyunun  kuzusunu,

Sevdiği  gibi  sevdim.

Ellerimi,  umutlarımı,

Kalbimi  açtım  sana.

Karda  açan  güller,

Verdim  kucağına.

Kadınım,

Bakışlarını  sevdim.

Bir  çocuğa  bakarken,

Gülümsemeni.

Hasret  türküleri  dinlerken

Dalıp  gitmeni  sevdim.

Gülüşünü  neşeni,

Beni  ben  gibi  sevmeni  sevdim.', 'Kadınım, Ben  seni  sevdim. Arının  çiçeği, Koyunun  kuzusunu, Sevdiği  gibi  sevdim. Ellerimi,  umutlarımı, Kalbimi  açtım  sana. Karda  aç...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdim-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dedigin', 'dost-dedigin-sair-babaxyorgun-n5c1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost dediğin arı gibi çiçekte 

Konduğunda vızıldar dalda 

Hep olmalı kalpte gönüllerde 

Şeker bal kaymak dost dediğin 

Gel dediğimde yanıma gelen 

İçtenlikle bana gülen 

Uzattığımda elini veren 

Sıkıca bağlanır dost dediğin 

Yokluğumda merak eden 

Arada selam gönderen 

Hep başımı döndüren 

Sarhoş eder dost dediğin 

Candır hatırdır yüreğimizde 

Güldür yapraktır gönlümüzde 

Uzak deildir hep yanımızda 

Her daim olur dost dediğin 

Selamın gelse uzaklardan 

Sanki ruhumu alırsın dardan 

Ovalardan çölerden dağlardan 

Kokusu gelir dost dediğin 

Babayorgun gurbandır dosta 

Onsuz inanki ruhum hasta 

Canansız gönlüm ruhumda hasta 

Lokman hekim gibi dost dediğin 

BABAXYORGUN', 'Dost dediğin arı gibi çiçekte  Konduğunda vızıldar dalda  Hep olmalı kalpte gönüllerde  Şeker bal kaymak dost dediğin  Gel dediğimde yanıma ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dost-dedigin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben gittim', 'ben-gittim-hekim-coskun-84e3k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gitim ben

koptum senden

geride anlatamadığım her şey

beklentilerin

beklentilerim

ama her şey güzeldi.

hayallerimi, hayallerini bile kıskandığım oldu

benim dediysem; 

bencilliğimden değil! 

sahiplenmekti, hapsetmekti sevgime,

boğmaktı seni.

sen kendin olarak var olacaktın,

ben sende kalacak

sen her gelişinde, 

seni bulacaktın bende

seni ben çok sevdim biliyor musun? 

seni sevecek kadar dokundum dudaklarına

bir büse mi denir ne? 

zaman ve mekan aykırıydı düşüncelerime,

zifiri karanlıkta korkak bir çocuk gibi,

ama ıslık çalarak koştum sana.

sen bunları biliyorsun diye de daha çok sevmiştim seni

daha çok yakın olmuş

arada bir nefesçik zaman bile koymamıştım.

hissettiğim her şey,

ama her şey güzeldi,

canım yanmaya başlamıştı,

sinir hücrelerim beynime kan pompalarken,

delirip, çıldırmaya başlayacağım anlarda,

sinir harbi içinse ben; hep seni düşündüm,

hırpaladım da,

canımın her yanışını senden bildim,

tüm zamanlarımı işgal eden,

alı koyan beni,

git,

yada kal,

yada dur dahası var; 

koparıp atamadığımız ne varsa? 

ben gittim.

tüm limanlar demir atmak içindi,

başım dönmüş her ağrılarım

her dokunuşlarım

her geç kalışımda bahara

ben denizlerdeydim.', 'gitim ben koptum senden geride anlatamadığım her şey beklentilerin beklentilerim ama her şey güzeldi. hayallerimi, hayallerini bile kıskandı...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ben-gittim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-halil-aksoy-6zo4e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oğlum   Halil,

Gel  sözümü  dinle.

Mutluluğun  sırrı  bende.

Mutlu  olmak  istiyorsan,

Sana  anlatayım  dinle.

Çok  televizyon  izleme   mesela.

Haberlere  de  fazla  kafa  yorma.

Hayat  pahalılığı    varmış,aldırma.

Uykuna  dikkat  et.

Her  sabah  düzenli  yürü.

Sana  selam  vermeyenlere,

Sen  selam  ver.

Pantolonun   ütülü  olsun  daima,

Dişlerini  fırçalı,

Ayakkabıların  boyalı.

Yaptıklarından  asla  pişman  olma.

Pişman  olacağın  bir  işi  yapma. 

Kahvaltı  da  domatesi  bol  ye.

Çayının  içine  bir  dal,

Alaattin  kekiği  at.

Bak  o  zaman,

Çayı  daha  keyifli  içeceksin.

Büyük  gibi  davranma.

Çocuğunla  çocuk  gibi  oyna.

Karın  sana  ne  derse  desin,

Ona  hep   müteşekkür  olduğunu  söyle.

Kaynananla   aran   iyi  tut.

Hayallerini  erteleme.

Herkesi  sevemezsin.

Sevdiklerini  yürekten  sevmeyi  dene.

İyice  dinlen,

Başkaları  için  değil,

Kendin  için  inan.

İnandığını  sonuna  kadar  savun.

Al  işte  mutlu  bir  insansın.

Bunların  hepsi  doğru,

Sana  yalan  söyleyen  utansın.', 'Oğlum   Halil, Gel  sözümü  dinle. Mutluluğun  sırrı  bende. Mutlu  olmak  istiyorsan, Sana  anlatayım  dinle. Çok  televizyon  izleme   mes...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/nasihat-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Martı', 'i-ki-marti-seval-kemertas-yin7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ayrı kıyılarda 

iki martıydık

kanat çırpan birbirine

belki bu yüzdendi yorgunluğumuz

belki de bu yüzdendi hasret

yana yana kül olduğumuz...

oysa uzansan 

yüreğime dokuncaktın

istesen! ..

kalbimi avuçlarında tutacaktın

şimdi uzak bir şehrin sonbaharında

çiğ tanesi gibi düşüyorsun içime

yüreğim ayazında

üşüyorum...

12/07/2004', 'ayrı kıyılarda  iki martıydık kanat çırpan birbirine belki bu yüzdendi yorgunluğumuz belki de bu yüzdendi hasret yana yana kül olduğumuz... ...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iki-marti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamyamda', 'yamyamda-sair-babaxyorgun-vitpf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostluk sofrasını kurduk kuralı 

Muhabbet çorbasına banar olduk 

Sevgi kapısından girdik gireli 

Köşkü saray eyledik yamyamda 

Öğrendik saygıyı edebimizle 

Kini yok ettik sevgimizle 

Çok tatlıyız biz ruhalimizle 

Sanki düğün var yamyamda 

Canı gönülden selamlar verilir 

Eğilip erkana hemen girilir 

Sorun dierlerine burası bilinir 

Her şey bir başkadır yamyamda 

Duyulur cıvıltımız her yerden 

Bir ferahlık getir gönülden 

İşte tek farkımız dier sitelerden 

Kavga kin yok yamyamda 

Yamyam dediysek adam yemeyiz 

Kötülük nefret küslük bilmeyiz 

Aşkımız büyük asla dönmeyiz 

Dostluğa devam yamyamda 

BABAXYORGUN', 'Dostluk sofrasını kurduk kuralı  Muhabbet çorbasına banar olduk  Sevgi kapısından girdik gireli  Köşkü saray eyledik yamyamda  Öğrendik sayg...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yamyamda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinlerim', 'guvercinlerim-halil-aksoy-c8r5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güvercinlerim  vardı  benim.

Evimizin  bahçesinde.

Küçücük  bir  kulübe’de.

Ellerimle  beslerdim  onları,

Sevip  okşardım.

Alaca,  boz  güvercinlerim.

Bebekliğini  çocukluğunu  bilirim,

Hepsinin.

Önce  besler  sonra  salardım.

Alaca, boz  güvercinlerim.

Fırsatını  buldum  mu,

Hepsini,

Göklere  salardım.

Onlar  uçarken

Ben  hepsini  bir  bir  tanırdım.

Çocuğum,arkadaşım, sırdaşım,

Onlar benim hayatım.

Bir  gün  okuldan  geldim.

Çantamı  koydum.

Yemlerini  alıp,

Bahçeye  koştum.

Yuva  yerinde  yoktu.

Etrafa  baktım.

Anneme  sordum.

Oğul  dedi annem.

Bu  sevdadan  vazgeç.

Baban  sevmedi  onları.

Söktü tüm yuvaları.

Güvercinlerim  dönüyordu  havada.

Konacak  yer  arıyordu  yuvada.

Çağırdım  hepsini   geldiler.

Geldiler…

Attığım  yemleri  yediler.

Evimizin  çatısına  dizildiler.

Evimiz yok artık, 

Der gibi, ağlarcasına ötüştüler.

Bir  kaç  geceyi  çatıda  geçirdiler.

Bir  sabah  baktım  hiçbiri  yoktu.

Etrafa  baktım  çağırdım

Ses  seda  yoktu.

Uçtular  gittiler.

Kim  bilir  kimi  sevindirdiler.

Güvercinlerim,sevgili  güvercinlerim 

Şimdi   ne  yerler ne içerler.

Nerede tünerler.', 'Güvercinlerim  vardı  benim. Evimizin  bahçesinde. Küçücük  bir  kulübe’de. Ellerimle  beslerdim  onları, Sevip  okşardım. Alaca,  boz  güve...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/guvercinlerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-sair-babaxyorgun-83ocg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel senin ile dosta gidelim 

Saygı sevgisiyle selam verelim 

Dostun bahçesinde çiçek derelim 

Eşim ahbabım dostla gidelim 

Uzat elini ey güzel insan 

Muhabbet duysunlar sana her an 

Bitmez dertlerinle of ile aman 

Derdimi anlıyan tabibe gidelim 

Sakın namerde belin bağlama 

Muhabbet suyunla ona çağlama 

Hep önde ol geride kalma 

Sevgi şehrine bizde gidelim 

Dilini kötü kelama verme 

Sölesin kötü sen ona deme 

Oda iyi olur günün birinde 

Muhabbet nehrine akıp gidelim 

Sadikiyam ne oldu böle 

Güzel muhabbet döner güle 

Yetişmek için menzile 

Yunusun olduğu yere gidelim 

BABAXYORGUN', 'Gel senin ile dosta gidelim  Saygı sevgisiyle selam verelim  Dostun bahçesinde çiçek derelim  Eşim ahbabım dostla gidelim  Uzat elini ey güz...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidelim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Yazayim', 'kime-yazayim-sair-babaxyorgun-jacy5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kime yazayım ben bu halımı 

Derdimden anlıyan birimi var 

Benimle olmuyan dostlarımı 

Kader katibinemi yazayım 

Aşkta sevdada ağrıtır başın 

Erkenden gelir gönülde kışın 

Zari zaridir hep ağlayışın 

Gönül kalemiylemi yazayım 

Verdiğin sevgiyi alırmı candan 

Anlıyanda yokturki hallarından 

Ayrılırmı gönül yaylalarından 

Dağların zirvesi yelemi yazayım 

Sözün kelamın kovanda baldır 

Çiçekte arı menzilde yoldur 

Temur sonun kara topraktır 

Aşkıma sevdama naza yazayım 

BABAXYORGUN', 'Kime yazayım ben bu halımı  Derdimden anlıyan birimi var  Benimle olmuyan dostlarımı  Kader katibinemi yazayım  Aşkta sevdada ağrıtır başın ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kime-yazayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-seval-kemertas-w9y6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'alacakaranlığın küskün şafağında

ürkek karanlığın beşiğinden düşercesine

mavi gecenin dalından bir yıldız kayıyor

bir aşkın fidanından koparılan dal gibi

bak..! 

bir sevda öğütülüyor zaman değirmeninde...

kara tren çığlığında

kavrulurken yüreğim

bir yağmur damlasına karışıyor ömrüm

terketmeliyim! ..

gitmeliyim bu şehirden

seni hatırlatmayan bir yer bulmalıyım kendime

yaşanmıyor artık..

yaşanmıyor! ..

bir başka yangının küllerinde...

alacakaranlığın küskün şafağında

bütün terkedişler çöreklenmiş üstüme

içimde iliklerime işlemiş deli bir hasret

sevdamın sığmadığı yüreğim ellerimde

ve İstanbul ağlıyor gözlerimde...

şimdi koyu bir hüzünle doluyor gece

amansız bir intiharı taşırken yüreğimde

tren raylarını ıslatıyor gözlerim

açılsa da her virajım uçurumuna

sararım yaralarımı zamanın külleriyle

beni bana bırak ne olur

yollar bitti içimde...

hoşçakal canımın içi

HOŞÇAKAL

emanet ediyorum seni martı seslerine...!', 'alacakaranlığın küskün şafağında ürkek karanlığın beşiğinden düşercesine mavi gecenin dalından bir yıldız kayıyor bir aşkın fidanından kopar...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hoscakal-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamyam infoya 2', 'yamyam-infoya-2-sair-babaxyorgun-psq5b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yamyam infodur buranın adı 

İçinde saklıdır bilene tadı 

Adamlık şifresi sevgi kodu 

İyi dileklerim yamyam infoya 

Giriş odasında selam verilir 

Hoş beş ile el sıkılır 

Yanlışta olsa hoş görülür 

Yakışanda bu yamyam infoya 

Bencilliğe yer olmaz özünde 

Sahte kibir bulunmaz sözünde 

Yaratılanı sev var sözünde 

Bir selam daha yamyam infoya 

Hergün notun bir kat daha yüksek 

Gelenler diyor bir daha gelsek 

Açılmayan kapıları açsakta görsek 

Bir adım daha yamyam infoya 

Muhabbetin bal ortamın kaymak 

Nekadar kalsam olmuyor doymak 

İnsana sevgiyi burada duymak 

Alışmak demektir yamyam infoya 

Babayorgun içinde senin 

Sonsuzdur artık güvenin 

Nekadarda çok senin sevenin 

Tekrar hoşgeldiniz yamyam infoya 

BABAXYORGUN', 'Yamyam infodur buranın adı  İçinde saklıdır bilene tadı  Adamlık şifresi sevgi kodu  İyi dileklerim yamyam infoya  Giriş odasında selam veri...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yamyam-infoya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ağlarım', 'ben-aglarim-halil-aksoy-m8uls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş  doğmuş  neyime.

Doğan  güneş  herkesin

Benim  güneşim  nerede.

Başım  kabak.

Ayaklarım  çıplak.

Karşımda  ufuk  çizgisi,

Belirmez.

Doğar  benim  güneşim,

Tersine.

Ev  desen  baraka,

Derme  çatma.

İki  oda  bir  sofa.

Yalnız  yaşarım.

Soğuk  odada  yatarım.

Kimin  haberi  var.

Kime  ne? 

Güneş  doğmuş  neyime

Ben  ağlarım,

Her  gece  kaderime.', 'Güneş  doğmuş  neyime. Doğan  güneş  herkesin Benim  güneşim  nerede. Başım  kabak. Ayaklarım  çıplak. Karşımda  ufuk  çizgisi, Belirmez. Do...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-aglarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla', 'asla-sair-babaxyorgun-60zmz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzeliz güzelde güzel olunca 

Olmaz kötülükler asla orda 

Sevgi muhabbeti kalbe dolunca 

Kalmaz yürekde kinler asla 

Muhabbet duyulur insana bizde 

Bazı densizler insandır sözde 

Bir damla olsam keşke gönlünüzde 

çıkmam gönül mekanından asla 

Sevgi ibrik insan bardaktır 

Dökülen duygu damlacıklardır 

Bunlar saygı sevgi hayadandır 

Edebimi bozmam ben asla 

Babayorgun ne derin senin kuyun 

inşallah kurumaz sevgi suyun 

Tanımayanlar beni işte ben buyum 

Deişmem deişemem asla 

BABAXYORGUN', 'Güzeliz güzelde güzel olunca  Olmaz kötülükler asla orda  Sevgi muhabbeti kalbe dolunca  Kalmaz yürekde kinler asla  Muhabbet duyulur insana...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asla-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla 1', 'asla-1-sair-babaxyorgun-05iw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzeliz güzelde güzel olunca 

Olmaz kötülükler asla orda 

Sevgi muhabbeti kalbe dolunca 

Kalmaz yürekde kinler asla 

Muhabbet duyulur insana bizde 

Bazı densizler insandır sözde 

Bir damla olsam keşke gönlünüzde 

çıkmam gönül mekanından asla 

Sevgi ibrik insan bardaktır 

Dökülen duygu damlacıklardır 

Bunlar saygı sevgi hayadandır 

Edebimi bozmam ben asla 

Babayorgun ne derin senin kuyun 

inşallah kurumaz sevgi suyun 

Tanımayanlar beni işte ben buyum 

Deişmem deişemem asla 

BABAXYORGUN', 'Güzeliz güzelde güzel olunca  Olmaz kötülükler asla orda  Sevgi muhabbeti kalbe dolunca  Kalmaz yürekde kinler asla  Muhabbet duyulur insana...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asla-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamız Üşümesin Diye', 'sevdamiz-usumesin-diye-i-sa-tekin-n3fru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda türküleri söylediğimiz

Mor dağlarımıza kar yağar

Sevdalanırım yeniden

Umut damlar yüreğime

Toprağa cemre düşer

Yüreğime sevda

Toprağa umut düşer

Sevdamız üşümesin diye

Her cemre düşüşte

Ben yeniden doğarım

Dört parçaya ayrılan yüreğim

Yeniden filiz verir

Newroz ateşleri tutuşurken

Ben halay çekerim

Umutlarım yeşerir

Sevdam yeniden filizlenir

Bende saklı yüreğin

Üşümesin diye

Güneş bir başka doğar

Newrozlarda', 'Sevda türküleri söylediğimiz Mor dağlarımıza kar yağar Sevdalanırım yeniden Umut damlar yüreğime Toprağa cemre düşer Yüreğime sevda Toprağa ...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdamiz-usumesin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecermi Boyle', 'gecermi-boyle-sair-babaxyorgun-1qy0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tükenmiş sevdalar ahdi vefayla 

Sürmedim zevkini aşkla sefayla 

Dertli başım hepsi belayla 

Senin sevdanla geçermi böle 

Sevgi verdim gönül suyumdan 

Almadım aşk ve sevgi payımdan 

Memnunmu kalayım söle neyinden 

Dertlerim günüme dolarmı böle 

Gönül dağlarıma boranlar esdi 

Ceylanım dağlara ovaya küsdü 

Ayrılığın rüzgarı çok erken esdi 

Savrulan yaprağım kalırmı böle 

Olmadın dost nede yaren 

Sen ne oldun sölede bilem 

Hiç olmadınki yüzüm güldüren 

Neşem kahkaham kalırmı böle 

Bu belalı başım bölemi kalacak 

Seninle sonumuz söle ne olacak 

Ya açılacak bahtım ya öldürecek 

Bu düzende dünya kalırmı böle 

Temuriyem dertli koydum adımı 

Almadımki murat ile şadımı 

Ezrail misafir aldımı beni 

Beden ile ruhum kalırmı böle 

BABAXYORGUN', 'Tükenmiş sevdalar ahdi vefayla  Sürmedim zevkini aşkla sefayla  Dertli başım hepsi belayla  Senin sevdanla geçermi böle  Sevgi verdim gönül ...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gecermi-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Konmamış Sevda', 'adi-konmamis-sevda-seval-kemertas-o9wpm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adı konmamış öksüz bir sevda

gün be gün kök saldı 

büyüdü içimde

gözlerimin yağmurları bile; 

sen diye yağdı, 

gönlümün bahar güneşlerine...

yalan aşkının önünde eğildi gururum

yüreğim yol aldı sürgün mevsimlere...

ömrümün yaprakları dökülen

sarı hazan sayfalarında

bir anı bile kalmadı

yaşadığımız o büyük sevgiden

binlerce yıl uzağımdasın sanki

kalabalıklar içinde bile

bulup bulup kaybettiğim sen

samanyolunda  yıldız misali

kayıp gittin ellerimden...

şimdi yağmalanan duygularımın kuytusunda

sarmalayarak öksüz sevda masalını

çiğ düşüyor hayallerimin  tomurcuklarına

göğsümde bastırsam en sancılı isyanları, 

denizlerde boğsam da gözyaşlarımı, 

yine de geceler umut taşımıyor sabahlara

hüzün vuruyor, hasret yağıyor gönlümün kıyılarına...

24/04/2003', 'adı konmamış öksüz bir sevda gün be gün kök saldı  büyüdü içimde gözlerimin yağmurları bile;  sen diye yağdı,  gönlümün bahar güneşlerine......', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adi-konmamis-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birakin', 'birakin-sair-babaxyorgun-evths', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akan suya yön verilmez bırakın 

Yön kaybetmiş damlaları arayın 

Hal anlıyan üstadıma sorayım 

Bilgiyi görgüyü arife sorun 

Derdin dermana sevginle gider 

Birgün bu can beni terkeder 

Rabbim inşallah bizi affeder 

Dertliyi dertlerle tabibe sorun 

Gönül raflarıma dizildin kaldın 

Ne beni aradın nede hiç sordun 

Yokuşu bırak düz yolda yordun 

Yolcuyu yolunda hancıya sorun 

Özledim seni söle nerelerdesin 

Hangi ırak yadelerdesin 

Saygı sevgi gönüllerdesin 

Kaleme kağıda şiire sorun 

Çok şey sığar dünya ile kelama 

Ehtibar et meraba ile selama 

Bel bağlama dünya ile malına 

Evliyalara haruna sorun', 'Akan suya yön verilmez bırakın  Yön kaybetmiş damlaları arayın  Hal anlıyan üstadıma sorayım  Bilgiyi görgüyü arife sorun  Derdin dermana se...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birakin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka davet', 'aska-davet-tuncay-emrem-javpd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey oğul, sevgi için, aşk için

Biraz da kendine yenil, ne olur...

Bir süre aklı bırak, hislerinle git..

Biraz da pişman ol, zarara katlan.

Biraz da gururdan geç, ne olur...

Biraz da sevgiye, aşka esir düş. 

Biraz da kendini tutkuya bırak..

Her kavuşmanın hazzını çıkar..

Ve de kaybetmenin korkusunu tat.

Hasret ateşiyle bir yan, ne olur..

Dediğim o ki, biraz insan ol.

Günahları ve eksikleryle...

Ama sevgiyi iç, hattâ sevgi ol..

Sevgi sabır ister, sevgi affeder..

Bir an olsun -hiç olmazsa- ne olur..', 'Ey oğul, sevgi için, aşk için Biraz da kendine yenil, ne olur... Bir süre aklı bırak, hislerinle git.. Biraz da pişman ol, zarara katlan. Bi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aska-davet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canbulat', 'canbulat-sair-babaxyorgun-2q9tm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Selam sana Dostluk Yuvasi

Elimizdeki Gulu Verisimiz Baska

Guler yuzle Duran Hecosu

Bize Merhabe Demesi Baska

melis Kurt Tiryaki Halobini

Nasil Unuturum Atakanla Duneyini

Sibelini Daglari Emelini

Coskuyla Gormek Baska

Zekicanimi desem Apocanimi

Nasil Anlatsam Burasini

Eskiler vardi Nerdeler hani

Siteler icinde Durusu Baska

Sevgi saygi Senin ozunde

Seker Kaymak Bal Var Sozunde

Bir Baskalik var Senin Sesinde

Siiri Turkuyu Calisin Baska

Tahsinim Seni Unutmadim

iste Bak Hep Buradayim

Sevgiden Dostluktan yanayim

Tadiyla Burayi Paylasmak Baska

Babayorgun Soyledi Bunlari

Tekrar selam YamYam Dostlari

Allahtan Gorun Nice Yillari

Burda Olusumuz Bile Bir Baska

BABAXYORGUN', 'Selam sana Dostluk Yuvasi Elimizdeki Gulu Verisimiz Baska Guler yuzle Duran Hecosu Bize Merhabe Demesi Baska melis Kurt Tiryaki Halobini Nas...', ARRAY['Türk Edebiyatı','Şiir','Şair Babaxyorgun']::text[], 8.5, '{"poet":"Şair Babaxyorgun","poet_slug":"sair-babaxyorgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canbulat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmediğini biçemezsin', 'ekmedigini-bicemezsin-i-lhami-arslantas-td60j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yedin içtin bitti hazır,

Bahanene  kılıf hazır,

Arama hiç boşa huzur,

Ekmediğin biçemezsin.

Sevgi verip koklamazsan,

Şu gönlünü paklamazsan,

Komşun açken yoklamazsan,

Ekmediğin biçemezsin.

Sanma ki el yaran sağlar, 

Ebediyen  gözün ağlar,

Beni derin diyor bağlar,

Ekmediğin biçemezsin.

Eyvah deyip başın taşa,

Çalma sakın öyle  boşa,

Bir an önce başla  işe,

Ekmediğin biçemezsin.

Ne şah acır ne de nazır,

Üste haraç ister vezir,

Beklemekle  gelmez  Hızır,

Ekmediğin biçemezsin.

Geç kalmışsın kardeşim geç,

Gün geçmeden doğruyu seç, 

Doğrulardan istersen kaç,

Ekmediğin biçemezsin.

Der ilhami  her bir azan,

Yeridedir  yazı    yazan,

Vakit varken çalış kazan, 

Ekmediğin biçemezsin.', 'Yedin içtin bitti hazır, Bahanene  kılıf hazır, Arama hiç boşa huzur, Ekmediğin biçemezsin. Sevgi verip koklamazsan, Şu gönlünü paklamazsan,...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ekmedigini-bicemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Yangın Yeri', 'yuregim-yangin-yeri-safinur-karaerkek-9qogi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin ilk yağmuru-

Buğuya yazılan sözlerin izi gibiydi

İzi yok ama anılarım kazınmış camlarda

Camların buğusunda asılı kaldı yüreğim

Ve isyan etti yüreğim.

Bir çığlık ki kulakları sağır edici

Bir çığlık ki kimsenin duymadığı

Yıllardır aynı masalı anlattı dilim

Uyudu yüreğim.

Kaç sevişler eskittim bedenimde

Neler neler uğruna kaç defalar ve

kaçıncı uçurum çiçekleri

Yüreğimde soldurduğum sonbahar

Gözlerimden döküldü yapraklar

Yüreğim yangın yeri, yetim eli, mermi sesi

Yüreğim ananın ağıt nefesi

Kaç yazlar gördüm 

Güneş inmeden gülüşlerime

Kar kapattı düşlerimi

Kaç çıkmaz sokakta can verdi düşlerim

Sen bilsen ne bilmesen ne

Bu yürek yangın yeri

Kaç insan gördüm yüreği ellerinde

Akrep misali kaç ateş çemberi

Kaç akrep leşine tanık oldu yüreğim,sustu gözlerim

Ayaz yemiş gecelerde kayıp gençliğim

ve şimdi

Umutlarıma salıncak kurup yarınlarıma uzanıyorum

Yüreğinin en yüksek yerinde

Düşler sokağınını daha düşü görülmemiş

Mor bulutların ak vadilerinden uzanan bir kuş sesinde

Bir kar tanesi temizliğinde,kalem inceliğinde

Kitap efendiliğinde

Yaşamın kendisiyim; Geçmişin,geleceğinim

Ben sevgi,ben keder

Hüzün,hasretim

Hadi yaşa beni.  .  .', 'Güneşin ilk yağmuru- Buğuya yazılan sözlerin izi gibiydi İzi yok ama anılarım kazınmış camlarda Camların buğusunda asılı kaldı yüreğim Ve is...', ARRAY['Türk Edebiyatı','Şiir','Safinur Karaerkek']::text[], 8.5, '{"poet":"Safinur Karaerkek","poet_slug":"safinur-karaerkek","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yuregim-yangin-yeri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-mehmet-cengiz-5k6d5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'neden bukadar zalimsin? 

bilirim aşık olmadın çocuk

yüreğin titremedi benim gibi 

imkansızı yaşamadın hiç

yaşamada, temennim degil

o siyahı görmesin gülüzara alışkın gözlerin

mezar olmasın sana mavi dünya

bir nasiat daha abinden sana

ulaştığın daldan ye meyveyi

öğrenince benim gibi sevmeyi

9 mart 2006', 'neden bukadar zalimsin?  bilirim aşık olmadın çocuk yüreğin titremedi benim gibi  imkansızı yaşamadın hiç yaşamada, temennim degil o siyahı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocuk-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkeğiz', 'erkegiz-ethem-turan-ket8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erkekler ne anlar şarkıdan 

Sadece içleri yanar onların 

Kadın anlar şarkının dilinden 

Şarkılardır kadın ruhunun aynası

Erkekler ne anlar türküden 

İçine hasret koyar türkülerin

Kavuşmayı diler

Sadece söyler diliyle

Oysa kadın çektiği acıyı katar 

Ekmek teknesindeki  hamur gibi

Sevdasıyla yoğurur 

Teriyle, acısıyla,kahrıyla

Gönlünden koparak okur 

Oda bir başka söyler diliyle

Erkekler ne anlar sevdadan 

Onların derdi sadece sevdiğine sahip olmadır

Oysa kadın sevdasıyla  yaşamalıdır

Sevdiğine kendini adamalı

Ölümse yoluna kurban olmadır 

Teslimiyettir sonsuz güvenle

Ne anlarız biz sevmekten

Erkeğiz nede olsa', 'Erkekler ne anlar şarkıdan  Sadece içleri yanar onların  Kadın anlar şarkının dilinden  Şarkılardır kadın ruhunun aynası Erkekler ne anlar t...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/erkegiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynak', 'oynak-gultekin-toga-bxy5u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gürültü,curcuna,şamata hayat,

          Evi sallanıyor yolu oynuyor,

          Nefs üzere kurdukları saltanat,

          Değişken ülkesi ili oynuyor.

          Kendinden başkası ona ne yahu? 

          Babası gart moruk ana ne yahu

          Alem aglıyormuş bana ne yahu

          Günleri çıldırmış yılı oynuyor.

          Her işi hesaptır,sinsi plandır,

         Masum yüzlü zehirli bir yilandır,

         İnanılmaz asla sözü yalandır,

         Zıvanadan çıkmış dili oynuyor..

         Çok sadık tapınır nefs denen puta,

          Özür borcum olsun kızaanda ite,

         Kıvırması fırıldaktan da öte

         Dansözler halt etmiş beli oynuyor.

         Hasardır,ziyandır ardında izi,

         Daha neler çıkar çözülse gizi,

         Şerri dokunmasin sana Sentezi,

         Adamın kaş,gözü,eli oynuyor.', 'Gürültü,curcuna,şamata hayat,           Evi sallanıyor yolu oynuyor,           Nefs üzere kurdukları saltanat,           Değişken ülkesi ili...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oynak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apse', 'apse-esra-aydin-c44cl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhabayla başladık

Dertleştikçe kaynaştık

Dostumsun değer veririm

Büyüğümsün elini öperim

Ustasın,karşında eğilirim

Yol göster serilirim

Ak yeter ki,emerim

Hakkını nasıl öderim

Verdikçe verdin

Şifanın dozu fazla geldi

Yan etki olarak kaldın

Ateşim çıktı bak

Apse yaptın

(Bu şiirime ilham kaynağı olan ve yüreğime yürek katan Sayın Uğur Balcıoğlu''na sonsuz teşekkürler)', 'Merhabayla başladık Dertleştikçe kaynaştık Dostumsun değer veririm Büyüğümsün elini öperim Ustasın,karşında eğilirim Yol göster serilirim Ak...', ARRAY['Türk Edebiyatı','Şiir','Esra Aydın']::text[], 8.5, '{"poet":"Esra Aydın","poet_slug":"esra-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/apse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-ramazan-kurt-054iw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BAYRAĞIM

			Gökyüzünde dalga dalga şanıyla,

			Süzülüyor,iki gözüm Bayrağım...

			Milletimin solmaz asil kanıyla,

			Seziliyor,gülen yüzüm Bayrağım...

			Eğilirim saygı ile önünde,

			Dalgalan yurdumun dört bir yönünde,

			Kefenim ol benim mahşer gününde.

			İlkbaharım,yazım,güzüm,Bayrağım...

			Taşırım göğsümde,seni korurum.

			Okurum marşını,selam dururum.

			İffetim,namusum,haklı gururum.

			Benliğimde coşan,özüm Bayrağım...

			Sevdalıyım sana ezelden ezel,

			Ay yıldız yüzüne yakışmış güzel.

			Gönlümün içinde hep yerin özel,

			Belekten mezara,sözüm Bayrağım...

			Yaşadıkça benim haklı davamsın.

			Övündüğüm her bir yerde havamsın.

			Tabutum üstünde mutlu yuvamsın.

			Sevdan yüreğimde,közüm Bayrağım...

			Ramazanım derki öfkem celalim.

			Uğrunda dökülen kanlar helalim.

			Sarsın bedenimi nazlı hilalim! 

			Dikildiğin her yer,bizim Bayrağım...

					Temmuz 2005', 'BAYRAĞIM 			Gökyüzünde dalga dalga şanıyla, 			Süzülüyor,iki gözüm Bayrağım... 			Milletimin solmaz asil kanıyla, 			Seziliyor,gülen yüzüm B...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt']::text[], 8.5, '{"poet":"Ramazan Kurt","poet_slug":"ramazan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bayragim-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Mi?', 'sahte-mi-mustafa-aslan-2-gklsa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahte bir gülücük,

Ve kurumus güller,

Ne farklari var,

Yalan olan dünyadan.

Kendimi unuttum,

Eli düsünmeye basladim,

Hergün agladimda,

Olmadi bir yoldasim.

Güler yüz gösterdim,

Yalniz agladim,

Ben insanligi düsünürken,

Yüregime tas bagladim.

Ailem geldi ilk sirada,

Herzaman gezdiler kanimda,

Bozkurt vardi yurdumda,

Tüter hergün burnumda.

Kimse olmadi yalnizligimda.

Tarih Ve Saati: 09-03-2006	20:27', 'Sahte bir gülücük, Ve kurumus güller, Ne farklari var, Yalan olan dünyadan. Kendimi unuttum, Eli düsünmeye basladim, Hergün agladimda, Olmad...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sahte-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabret', 'sabret-i-rfan-kayagil-q6pcj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki dağın ikisinde bin hasret

Gönül der ki, sen hele bir sabret

Biz kavuşmasak, olmaz kıyamet

Bende değil  serdedir keramet

Bir bağda bin olsa üzüm.

Bin üzümde bin ayrı lezzet

Koruk tan olur da helva

Gönül der ki, sen hele  bir sabret

İçtiğim şarap değil belki de şerbet

Şerbetten şarap hasıl olursa

Sözde değil elbet, özde keramet

Helal olurdu, haramsa şarap

İçenin mayasında olmasa nefret

Gönül der ki, sen hele bir sabret

Ademoğlu bir gün alacak  ibret

Gecenin gündüzü gizlediği gün

Kesilir ömrüne belki son bilet

Bekleme o an, kimseden medet

Ne döner gidenler ne de bir haber

Felek diyorsa bu sana kader

Bir lokma, bir hırka bize yeter…', 'İki dağın ikisinde bin hasret Gönül der ki, sen hele bir sabret Biz kavuşmasak, olmaz kıyamet Bende değil  serdedir keramet Bir bağda bin ol...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sabret-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Kim İsen?', 'her-kim-i-sen-bora-eke-bee00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne aşkı yaşıyorum,

Ne de ondan kaçıyorum.

Ne mutluyum,

Ne de acı çekiyorum.

Ne ayığım,

Ne de sarhoş.

Ne güçlüyüm,

Ne de zayıf.

Daha çok ''ne'' var yazılabilecek ama...

Sonuçta sensizim işte! 

Sen her kim isen? 

(Kimsesiz Bir Yalancı - 06.08.2005)', 'Ne aşkı yaşıyorum, Ne de ondan kaçıyorum. Ne mutluyum, Ne de acı çekiyorum. Ne ayığım, Ne de sarhoş. Ne güçlüyüm, Ne de zayıf. Daha çok ''ne''...', ARRAY['Türk Edebiyatı','Şiir','Bora Eke']::text[], 8.5, '{"poet":"Bora Eke","poet_slug":"bora-eke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-kim-isen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1.1.1.1.Son Dem', '1-1-1-1-son-dem-his-kaybi-mk-s8ie3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son DEM 

Sızıntı başlar gözde

Ele veriyordur yağmur 

Ve yaprak dökümleri tende

Sonbahar, Son gelişinde 

İliklersin ceketin düğmesini 

Boynunu büker mazlum mazlum bakarsın 

Ellerini açtığın gün artık geride, rab''bine

Azrail ve sen kafa kafaya verirsin, Son dilek- ölüm -

Seninde gözyaşın tuzlu, farkı yok 

Yüzünde yıpranmış bir tebessüm 

Yorgun, yılgın, alnındaki çizgide bir bir tükenmiş ömrün 

Belli sende de iflas etmiş umut, son söz, susuyorsun

Utanmaz ve arlanmaz oldu saçların

Her düşen ak diğerine sitemkar 

göz açıp kapayana kadar geçti zaman 

Ne alındık ne de isyan ettik yokluğuna, gülüm 

Şimdi harman zamanı

Başaktan ayrılıyor buğday

Gözlerimden düşerken her damla zaman 

Gönülde saklı bir gücenmişlik bir''de ten''inde sakladığım nefesim 

Her vakit.... Son DEM; Hikaye ÖMRÜN 

Bu bir Dem''dir Gelir Alır Gider Ve Mutlak bu da geçer....

Versac_M.K', 'Son DEM  Sızıntı başlar gözde Ele veriyordur yağmur  Ve yaprak dökümleri tende Sonbahar, Son gelişinde  İliklersin ceketin düğmesini  Boynun...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/1-1-1-1-son-dem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı', 'balikci-bora-eke-vu4kt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Balıkçı kurtar beni

Bu diyardan! 

Bir çırpıda olsun herşey,

Canım çok yanmadan

Sen misinayı çektikçe

Gördüğüm ışıksa

İnsanlara bahış edilen

Sevgi Dünyası,

Daha hızlı çek.

Sonu ne olursa olsun

Yaşamak istiyorum. 

Bir anlığınada olsa,

Hissetmek istiyorum

İnsanlar gibi aşık olmayı.

(Bir Zaman Balıkçısı - 14.11.2003)', 'Balıkçı kurtar beni Bu diyardan!  Bir çırpıda olsun herşey, Canım çok yanmadan Sen misinayı çektikçe Gördüğüm ışıksa İnsanlara bahış edilen ...', ARRAY['Türk Edebiyatı','Şiir','Bora Eke']::text[], 8.5, '{"poet":"Bora Eke","poet_slug":"bora-eke","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/balikci-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yüce', 'sevgi-yuce-metin-soydeveli-skan2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onun nesi var,

Adı Aşk! 

Kendisi üç harf, tek hece 

Gücü nice? 

Ama… 

Benim harfim de hecem de fazla. 

Gücüm de o’ndan yüce. 

Yalnız o 

Neye yarar? 

Sadece ilk görüşte kalır, 

Karşılıksızsa, ses vermez

Taştan bir duvar. 

Ben girersem araya 

Merhem olurum yaraya. 

Bana sıkı sarıl, 

Benim o’na maya. 

Aşk bölünmez hecelere

Aşık olunca sadece, iki parça! 

Başkalarına yer yok 

Yaşanır iki aşık arasında. 

Dağıt beni, paylaş cömertce 

Bin parçalansam da azalmam 

Büyür, çoğalırım parçalandıkça 

Benim adım SEVGİ

Gücüm YÜCE. 

Metin Soydeveli', 'Onun nesi var, Adı Aşk!  Kendisi üç harf, tek hece  Gücü nice?  Ama…  Benim harfim de hecem de fazla.  Gücüm de o’ndan yüce.  Yalnız o  Neye...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgi-yuce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Yap Gülüm', 'gel-yap-gulum-kursad-berkkan-swo5k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana isyan dolu sözleri

Uğruna kırdığım sazları

Yürekte yanan közleri

Yakacaksan gel yak gülüm

Döner sandın beni belkide

Pişman olur gelir yine

Taş oldum döndüm çöle

Basacaksan gel bas gülüm

Yalvardım uğruna Allahıma

Yokluğunu anlattım silahıma

Yokluğun ölüm şakağıma

sıkacaksan gel sık gülüm

Savruldum kapıldım yele

Dolayıpta adını dile

Kader adlı bir çembere 

Vuracaksan gel vur gülüm', 'Sana isyan dolu sözleri Uğruna kırdığım sazları Yürekte yanan közleri Yakacaksan gel yak gülüm Döner sandın beni belkide Pişman olur gelir y...', ARRAY['Türk Edebiyatı','Şiir','Kursad Berkkan']::text[], 8.5, '{"poet":"Kursad Berkkan","poet_slug":"kursad-berkkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-yap-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-kamer-taskin-x2bzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemek,

Aramak,

Bulmak,

Kavuşmak,

Ayrılmak,

Ölmek,

Bazen hep sevmek demek.

Binbir adı var, sevmenin,

Yok başka adı, sevmemenin.', 'Özlemek, Aramak, Bulmak, Kavuşmak, Ayrılmak, Ölmek, Bazen hep sevmek demek. Binbir adı var, sevmenin, Yok başka adı, sevmemenin....', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmek-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık', 'sarmasik-metin-soydeveli-vzglo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saracaksın sarmaşık gibi boğarak      

Koşulsuz seveceksin başka yolu yok. 

Korkak olarak ödlek yaşamaktansa   

Ateşe  yanacaksın, çıralar gibi,           

Elinden öleceksin yarin cesurca.        

Umarsız bir sevdada çağlasan da      

İyi ki var diyebileceğin  olmalı. 

Vefa duygusundan uzak, sorumsuzca, 

Uzaklaşsa da senden uzun yıllarca         

Yakınlaşacaksın ona, sen yaşlandıkça.    

Gecelerde dinlenen  gündüzler gibi 

Sığınacak  kuytu limanın bulunmalı.         

Son deminde baş ucunda bir vefalı        

Can suyunu verecek biri olmalı             

Seni doğuran kadar, sevecek biri!', 'Saracaksın sarmaşık gibi boğarak       Koşulsuz seveceksin başka yolu yok.  Korkak olarak ödlek yaşamaktansa    Ateşe  yanacaksın, çıralar g...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarmasik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Delik...', 'kalp-delik-neslihan-i-sler-q68rf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir üçlemenin ikilemindeyim

Sınırlarımı zorluyorum anlamak için

Ama yine üzerimde karabulutlar

Değişimlere ayak uydurmalıyım 

Aslında biliyorum  değiştiremeyecegim kaderim

Of of anam of of babam 

Nekadar of ceksemde boş elimde ne gelir ki

Kalp delik …..

Yürek yenik….

Biliyorum acımı susturamayacağım

Of of başımın üstündeki bulutlar of

Lütfen daha fazla üzerime gelmeyin

Yorgunum bu yıpranmış grilikten

Ne olur daha fazla başımı eğdirmeyin

Tüm bunları tek bir yürekten beklemeyin

Elimdekileri özetlersek birden

Kalp delik …..

Yürek yenik ….

Yine ilkbaharın bahçesinde yazı yaşarken gördüm kendimi

Şimdi sonbaharın sabah ayazlarında kaldım yeniden

Biliyorum yine vakit doldu …

Of of başım of 

Kol kırıldı yen içindemi kaldı sanırsın

Bak yine elde ne kaldı

Kalp delik 

İşte yine vakitsiz gelen yaz dan göçme zamanı…', 'Bir üçlemenin ikilemindeyim Sınırlarımı zorluyorum anlamak için Ama yine üzerimde karabulutlar Değişimlere ayak uydurmalıyım  Aslında biliyo...', ARRAY['Türk Edebiyatı','Şiir','Neslihan İşler']::text[], 8.5, '{"poet":"Neslihan İşler","poet_slug":"neslihan-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalp-delik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destan', 'destan-altay-taskin-6zl51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben Çanakkale''yi gördüm

boğaza yaslanmış yemyeşildi

şehitlik heybetli mi heybetli

selamlıyordu gelen geçenleri

burada tarih yazılmış

tarih okunmuş

her çam ağacının dibinde

kulağınıza fısıldayan bir taş...

bayrağım dalgalanıyor

hiç şüphesiz

Türk''ün imanını taşıyor

selam sana Çanakkale

yaslan yurdumun bağrına

dokunamazlar sana

yetmiş milyon sana verir bir baş...', 'ben Çanakkale''yi gördüm boğaza yaslanmış yemyeşildi şehitlik heybetli mi heybetli selamlıyordu gelen geçenleri burada tarih yazılmış tarih o...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/destan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışınla Toplarım Gün Işığımı', 'bakisinla-toplarim-gun-isigimi-nurten-tarim-aesse', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizin dalgası kıvrıla kıvrıla serilir kıyıya

Ilık bır meltem ıslığında aşk namesi

Martılar oynaşır yakamozlarla

Sevgililer el ele yürekleri bir kumsalda

Aşk şarabını yudumlar gecenin koynunda

Bugulu bakışlarda ölmek zamanı bu an

Dursun zaman dönmesin yelkovan

Sevdanın diliyle baglandım sana

Rüzgarım oldun savurdun kendine

Goncam dedim ruhuma işledim 

Bugulu bakışında eridim bittim

Bir busen ile yandım tutuştum

Gökkuşagım oldun sardın beni

Bakışınla toplarım gün ışığımı

Yediveren gülünüm her mevsiminde', 'Denizin dalgası kıvrıla kıvrıla serilir kıyıya Ilık bır meltem ıslığında aşk namesi Martılar oynaşır yakamozlarla Sevgililer el ele yürekler...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakisinla-toplarim-gun-isigimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğin Gözleri', 'gelecegin-gozleri-ali-cengiz-turan-f5049', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş doğdu,bekliyoruz değilmi? Doğmayabilir..

Doğdu ama lambayı yaktım.

Lamba utanç içinde..

Gece oldu gün karardı,güneş gitmeyebilir.

Gitti ama lambayı yaktım.

Lamba sevinç içinde.

Hayat geceyle gündüzün içinde,

Hayret,,...

Ezbere düşünenler,

Kaba güç gösterenler,

Dünyanın içinde......! ! ! ! ! ! ! ! ! ! !', 'Güneş doğdu,bekliyoruz değilmi? Doğmayabilir.. Doğdu ama lambayı yaktım. Lamba utanç içinde.. Gece oldu gün karardı,güneş gitmeyebilir. Gitt...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gelecegin-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-i-brahim-kilinc-855h4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep dosttan bekleme,birde sen pas ver

Arada selâm ver, arada ses ver

Gönül pınarından, bir iki tas ver

Ummadığın dostlar merakta  belki.

Mesajın ulaşsın dost gönüllere

Doğru seç dostunu,koyma yerlere

Dost mızrabı değsin bırak tellere

Ummadığın dostlar çorakta belki

Dostun sâdasıdır dosta hediye

Anlatır herkese dosttan bu diye

İçi yansa içer onu su diye

Ummadığın dostlar kurakta belki', 'Hep dosttan bekleme,birde sen pas ver Arada selâm ver, arada ses ver Gönül pınarından, bir iki tas ver Ummadığın dostlar merakta  belki. Mes...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belki-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kis Mevsimi', 'kis-mevsimi-i-brahim-ethem-uzun-hkkrw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kos tum nefesinle

Actim sana kollarimi

Ben karli kimsesiz kis mevsimi

Sen gunesli bahar mevsimi

Suphesizce sev beni

Yalnizligim zindan gibi

Sicacik avuclarinla yik duvarlarimi

Derya ol

Rihtim ol

Yildirim ol

Toprak ol

Yaprak ol

Surgun ol

Gok gurultusu ol

Yumusak ol 

Sert ol

Sev beni milyon yontemle

Yaz gibi gelme

Bilirsin ondan ne nefret ettigimi

Beni deli gibi sev

Onu soyle bagira bagira kulaklarima

Onu yaz uzun tirnaklarinla  kalbime

Avucumun  icindeki cizgilere 

Gunahkar yuzumun derisine

Reddediyorum sessizce sevmeni

Karsi geliyorum  canli canli sevgiyi defnetmeni

Cinnetinle sev beni

Cadiliginla sev beni

Ahmakliginla sev beni

Acikgozlulugunle sev beni

Edepsizce dusun beni

Kanunsuzca dusun beni

Korkusuzca dusun beni

Kadinliginla dusun beni

Dolanalim birbirimize  sarmasik cicegi gibi

Dedikoduya susamis koyumuzden uzaklarda

Kalas yobaz radikal kasabamizdan uzaklarda

Dudaklarimin kanini emercesine op beni

Esir kahir dolu sehrimizden uzaklarda

Kiskanclik fitne kan dolu beldemizden uzaklarda

Asma yapraklarina  sevdigini yaz beni

Bir  gun bile ozgurlugun ve sevginin ugramadigi ulkemizden uzaklarda

Toresiz  tabusuz  kokla beni

Ahlaksizca oksa beni

Bagimsiz oku busbutun hucrelerimi

Bosalt goz yaslarini gozlerimin icine

Onlar ruhumun serbeti

Butun guzelliginle yaklas suyuma

Ayaklarin icin sudan korkma

Abdestin caiz olmaz

Cismin suyun disinda kalirsa

Sacin suyun disinda kalirsa

Tirnaklarin suyun disinda kalirsa

Memelerin bembeyaz iki ordek

Soyle bana susuz ikisi nasil yuzecek

Kivrilircasina kirilircasina sev beni

Safligimla veya aksiyonumla

Masumlugumla veya seytanligimla

Akilliligimla veya deliligimle

Cocuklugumla veya bunakligimla

Ort beni

Ciceklerle saclarinla karisik catilarla

Or cevremi

Ter kokunla ask kokunla

Dok butun yapraklarini

Silkele tum dallarini

Ziplat o sevimli tavsanlarini

Ottur o bulbul dilini

Ve dus saril saril yagmur gibi

Susuzluguma 

Sahrama

Sahillerime

Cayirlarima

Fanuslarima

Kuyularima

Yaylalarima

Bayragima

Erisin mum gibi

Busbutun kollarin

Busbutun ayaklarin

Cehennem atesi gibi yanan sehvetimin icinde

Haydi sifa ver ellerinle

Hazreti Mesihin sifasi gibi

Ask kanserime

Haydi ikiye bol saclarinla

Hazreti Musanin asasi gibi

Sevgi denizimi

Haydi aydinlat gozlerinle

Hazreti Muhammedin nuru gibi

Kapkaranlik dunyami

Olmak istiyorum senin gibi

Yemyesil bir bahar mevsimi', 'Kos tum nefesinle Actim sana kollarimi Ben karli kimsesiz kis mevsimi Sen gunesli bahar mevsimi Suphesizce sev beni Yalnizligim zindan gibi ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/kis-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Dem Hasret', 'her-dem-hasret-volkan-yoruc-83l9x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret bir rüzgardı

Eserdi mahallemizde

Yüzüme çarpar kaçardı

Koşardım peşinde

Yakalayamam uçardı

Hasret bir denizdi

Dalgalanırdı kıyımızda

Yüzerken savurur sallardı

Gidemezdim karaya

Hayalim bile yorulur, batardı

Her dem hasret

Hasretlerde bile gayret et

Sakınma düşlerini kendinden

Gülümse ve inat et

Bilirsin ki bugünlerde geçer, geçer elbet', 'Hasret bir rüzgardı Eserdi mahallemizde Yüzüme çarpar kaçardı Koşardım peşinde Yakalayamam uçardı Hasret bir denizdi Dalgalanırdı kıyımızda ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-dem-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyir', 'seyir-ugur-aydin-2-5h1bw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yıllar sonra sokağından gectim dün akşam.

perden cekilmemiş odan aydınlık 

sokak lambası sönük etraf zifiri karanlık 

seni seyrediyordum 

hüzünlü gözlerle bakıyordun 

birinimi bekliyordun...

hadi git yat düşün olacak yarınları 

dışarısı soğuk görmeni 

istemem basıma düsen karları 

yılar önce sevdiğini bekleyen 

gözlerle bakıyordun sokağa 

bu akşam hüzünlü gözlerle hayatım

bel ki yine gelirim iyi akşamlar kadınım...

iyi akşamlar kadınım...', 'yıllar sonra sokağından gectim dün akşam. perden cekilmemiş odan aydınlık  sokak lambası sönük etraf zifiri karanlık  seni seyrediyordum  hü...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seyir-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''m', 'ankara-m-aynur-sultan-iswxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '____Herkes İstanbula sevdalı. Umrumda değil o muhteşem Boğazı,

binbir gece masallarını andıran mistikliğinden bana ne, 

Benim hayranlığım başka, kimseninkine benzemiyor.

___Kimine göre resmi, soğuk, bilmem ne vesaire der dururlar. 

___Ama o puslu soğuk ayazına vuran havası bile içimi yakar durur..

Ortasinda kurulu kalenin eteklerinde ki gece kondularının bırak taşıt geçmesini, adam geçmez tek sokağını bile

hiç bir yere değişmem.

____Çocukluğum. İlk sevdam, ilk yanlışım ve 

toprağına bir bir sevdiklerimi  verdiğim ilk terk ettiğim ve hep özlediğim kent', '____Herkes İstanbula sevdalı. Umrumda değil o muhteşem Boğazı, binbir gece masallarını andıran mistikliğinden bana ne,  Benim hayranlığım ba...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ankara-m-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-cengiz-ozkan-mg52x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzelliğin sardı her bir yanımı 

Sen herkesten daha güzelsin ana 

Bir güzele kandım yaktı canımı 

Sen herkesten daha güzelsin ana 

Çok hakkın var ana nasıl öderim 

Çok özledim seni belki dönerim 

Çok güzel var ama yemin ederim 

Sen herkesten daha güzelsin ana

Dertler sende derya gönlün bir liman

Sevgin enginlerde sanki bir umman

Nur gibi görünür gözümde siman

Sen herkesten daha güzelsın ana

Nasihattır bize dediğin sözün

Bizden başka görmez kimseyi gözün

Cennet bahçesidir o güzel yüzün

Sen herkesten daha güzelsin ana

Buralarda herkes bana yabancı

Hasretin sinemde büyük bir sancı

Seviyorum seni başımın tacı

Sen herkesten daha güzelsin ana

Hey! Canım anneler can kurban size

Ak süt değil ömür verdiniz bize

Daye! bir kulak ver oğlun Cengiz''e

Sen herkesten daha güzelsin ana

daye: Anne demek', 'Güzelliğin sardı her bir yanımı  Sen herkesten daha güzelsin ana  Bir güzele kandım yaktı canımı  Sen herkesten daha güzelsin ana  Çok hakkı...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Özkan']::text[], 8.5, '{"poet":"Cengiz Özkan","poet_slug":"cengiz-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ana-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Uzakta, Ben Mezarda', 'o-uzakta-ben-mezarda-volkan-yoruc-9f7aw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasılda bakardı yüzüme

Dili varmazdı sözlere

Saklar dururdu bişeyleri yüreğinde

Bak şimdi gittin yaşayamadığım düşlerinle

Şimdi uzakta, çok uzakta

Belki bir yolda yada konakta

Ama göremeyeceğim bir diyarda

Gittiği günden beri nasılda yanar içim korlarda

Artık hatırlanmaz olmuşum

Dile gelmez bir garip kuş olmuşum

Uçmuşum, uçmuşum, uçmuşum

Konacak bir dam bulamamışda

Düştüğüm yerde mezara konulmuşum

Artık o uzakta

Ben ise mezarda', 'Nasılda bakardı yüzüme Dili varmazdı sözlere Saklar dururdu bişeyleri yüreğinde Bak şimdi gittin yaşayamadığım düşlerinle Şimdi uzakta, çok ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-uzakta-ben-mezarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufukta Kara Göründü', 'ufukta-kara-gorundu-ramazan-ates-tfmgo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak  içimde bir his var,

Çıkacağım ben düze.

Küçük ama umut var,

Çıkacağım ben düze.

Yıllar yılı ben böyle,

Ne zamana? Nereye? 

Yaklaşıyom hedefe,

Çıkacağım ben düze.

Çektim çektim bitmedi,

Kovdum yine gitmedi.

Yeter artık, yetmeli,

Çıkacağım ben düze.

Ezildikce ezildim,

Bunca yıldır üzüldüm.

Açılıyor bak gözüm.

Çıkacağım ben düze.

Ramazan Ates-Enschede-9.3.2006', 'Bak  içimde bir his var, Çıkacağım ben düze. Küçük ama umut var, Çıkacağım ben düze. Yıllar yılı ben böyle, Ne zamana? Nereye?  Yaklaşıyom h...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ufukta-kara-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehir Olur Akarım Sana', 'nehir-olur-akarim-sana-metin-soydeveli-au6gz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nehir olur akarım sana

Sen beni çağırmıyor olsan da.

Çarem yok, akmak enginlere,

Fıtratıma yazılmış sen gibi bir kere.

Set çekilemez yollarıma 

Çağlarım sevdamla. 

Düşlerime gem vuramazsınız.

Bentler, barajlar kesemez yolarım

Aşarım dağları, taşları durduramazsınız.

Set olursanız yoluma, dinlendikçe coşarım.

Koynunda uyuduğumu sanırken toprağın

Cilveleşirim güneşimle, tutamazsınız! 

Buhar olur sevdiğime kaçarım.

Şimdi dinginliğindeyim sevdamın

Enginliğine karışıp gidiyorum sevdamın.

Nehir nehir akıyorum koynuna senin

Hem denizleri, hem ömrümü dolduruyorum.', 'Nehir olur akarım sana Sen beni çağırmıyor olsan da. Çarem yok, akmak enginlere, Fıtratıma yazılmış sen gibi bir kere. Set çekilemez yolları...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nehir-olur-akarim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalan Gecelerini Benim Gibi Yaşa', 'kalan-gecelerini-benim-gibi-yasa-metin-soydeveli-f6kvc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak meyhaneci masayı

Olduğu gibi kalsın

Koy bir hüzzam

Gidenlerin ardından çalsın

Bırak söndürme mumları

Ömrüm gibi erisin, sönsün

Anlarsa sevginin değerini

Ağarmadan gün, geri dönsün

Hiçbir şey söylemeden çekip gidersin

Düşünmeden kalanın hali nice ola

Rabbim uzun ömürler versin

Kalan gecelerini benim gibi yaşa', 'Bırak meyhaneci masayı Olduğu gibi kalsın Koy bir hüzzam Gidenlerin ardından çalsın Bırak söndürme mumları Ömrüm gibi erisin, sönsün Anlarsa...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalan-gecelerini-benim-gibi-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-kevser-gulistan-cakir-5nefj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukluğuma dönmek isterim

Yorgunluklarımdan

Yine zevk alabilmek için

Ki çocuklar yaşarken

Hatta uyurken  yorulmazlar bilirim

Sonra 

Yavaş yavaş büyümek isterim

Hayatı anlaya anlaya

Ve sindire sindire an an...

Yok olmaz öyle şey, ama

Yine de böyle emrediyor hislerim...', 'Çocukluğuma dönmek isterim Yorgunluklarımdan Yine zevk alabilmek için Ki çocuklar yaşarken Hatta uyurken  yorulmazlar bilirim Sonra  Yavaş y...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilek-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudumu Gören Varmı?', 'umudumu-goren-varmi-volkan-yoruc-4icps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne düşler vardı mevsimler önce

Güzel hayaller tatlı düşler

Şimdi karanlıklarla kaplı her yanım, sevinemem

Umudumu bulabilirmiyim bilemem

Ne aşklar isterdi şu gönlüm mevsimler önce

Sevdaya tutsak hayali hoş anılardı

Şimdi her yanım karakış olmuş

Umudumu bulmama yardım edecek biri varmı?', 'Ne düşler vardı mevsimler önce Güzel hayaller tatlı düşler Şimdi karanlıklarla kaplı her yanım, sevinemem Umudumu bulabilirmiyim bilemem Ne ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudumu-goren-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karartma', 'karartma-sabahattin-hizmetli-8v8pa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benden uzakta iken

	Gözlerinin rengini sil,

	Pırıltılarını söndür.

	Sakın,

	Konuşmasınlar başkalarıyla.', 'Benden uzakta iken 	Gözlerinin rengini sil, 	Pırıltılarını söndür. 	Sakın, 	Konuşmasınlar başkalarıyla....', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/karartma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrumlu İlayda', 'bodrumlu-i-layda-kevser-gulistan-cakir-qs990', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen Bodrum''dan uzakta

Bodrumlu bir kızsın

Senin kadar güzelini

Görmemiştim İlayda

Salınırken edalı

Demir attığın adada

Uyuyordun belki de

Rüyaların Bodrum''da

Sen bütün iklimleri soludun

Tanıyorsun

Yastığınla yorganın

Maviyse uyuyorsun

Sen güzelin farkında

Güzelliğinden habersiz

Beyaz bir alev ile

Her akşam yanıyorsun...

Sen Bodrum''dan uzakta

Bodrumlu bir kızsın

Bu yüzden düğümlenir

Bakışların uzaklara

Hiç bilinmez  ne derece

Mutluydun oralarda

Çok geçmeden yelken aç

Bu pişmanlık denizinden

Yaşıyorsan hâlâ

Bil ki vatan sol yanında...', 'Sen Bodrum''dan uzakta Bodrumlu bir kızsın Senin kadar güzelini Görmemiştim İlayda Salınırken edalı Demir attığın adada Uyuyordun belki de Rü...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bodrumlu-ilayda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç', 'kiskanc-sabahattin-hizmetli-497xh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimseler girmesin diye,

	Yüksek surlarla örüp,

	Derin hendeklerle çevireceğim,

	Gözlerinden gözlerime uzanan

	Mutluluk yolunu...', 'Kimseler girmesin diye, 	Yüksek surlarla örüp, 	Derin hendeklerle çevireceğim, 	Gözlerinden gözlerime uzanan 	Mutluluk yolunu......', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kiskanc-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemedim', 'olemedim-serhat-caliskan-75mkp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabaha kadar kadere sövüp

Uyumadım kitapsız inan dün gece

Seni hainlik yerinden vurmak istedim

Kıyamadım kurşuna,inan dün gece

Rakıya,cigaraya sarıldı elim

Kendi kendime küfürler ettim

O yalan şarkımızı kaçkez söyledim

Sayamadım allahsız inan dün gece

Sevdaya ihanet sana yakıştı

Bıraktığın yaralı canlar çekişti

Ecel kapıyı çaldı açmak istedi

Sensiz toprağa mezar,diyemedi dün gece', 'Sabaha kadar kadere sövüp Uyumadım kitapsız inan dün gece Seni hainlik yerinden vurmak istedim Kıyamadım kurşuna,inan dün gece Rakıya,cigara...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olemedim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istifa', 'istifa-cengiz-suslu-wno79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varoluşun üstünden geçti belirsiz zaman,..

...insanlığından cayan,evrimle oldu hayvan...', 'Varoluşun üstünden geçti belirsiz zaman,.. ...insanlığından cayan,evrimle oldu hayvan......', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/istifa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Ayak Üstü Söyleşi', 'askla-ayak-ustu-soylesi-erdal-ercin-935ax', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk 

Sana ne diyecektim 

Güllere düşürdün beni 

Kırlarda bir kelebektim 

Ellere düşürdün beni 

Umut 

Gönlümün kavramı 

Kalmadı dünün anlamı 

Gizledin bir gün sonramı 

Fallara düşürdün beni 

Küçük bir yıldızdım 

Kaydım 

Her yeri vatanım saydım 

Bulutlarda bir damlaydım 

Sellere düşürdün beni 

Seneler kadar uzaktın 

Fark edilmez bir tuzaktın 

Yaktın yüreğimi yaktın 

Küllere düşürdün beni 

Bir kızı sevmiş dediler 

Biraz deliymiş dediler 

Neler söylediler neler 

Dillere düşürdün beni 

Özüne su yürür gibi 

Bir gün ucu görür gibi 

Sanki meyve verir gibi 

Dallara düşürdün beni 

Acıyı balda tanıdım 

Dikeni gülde tanıdım 

Gurbeti yolda tanıdım 

Yollara düşürdün beni', 'Aşk  Sana ne diyecektim  Güllere düşürdün beni  Kırlarda bir kelebektim  Ellere düşürdün beni  Umut  Gönlümün kavramı  Kalmadı dünün anlamı ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ercin']::text[], 8.5, '{"poet":"Erdal Ercin","poet_slug":"erdal-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/askla-ayak-ustu-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-kevser-gulistan-cakir-twkxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşuna çalma kapıyı

Kalbim evde değil...

Boşuna not bırakma

Döner mi belli değil!', 'Boşuna çalma kapıyı Kalbim evde değil... Boşuna not bırakma Döner mi belli değil!...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/degil-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük İnsanlar', 'kucuk-i-nsanlar-gultekin-mustafa-16edh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'küçük insanlar

ah sizler

kendi etrafınızda beş santim

bilemediniz on beş santim

cürümden ibaret 

siz küçük insanlar

hiç bir şeye hiç bir şey katan

sabah iş 

akşam dizi

harcınız filancanın kızı

yalnızken kurup durduğunuz hayalleriniz boşa

o vakitlerde yücelere çıkarmanız da kendinizi

dünya sizin gözlüğünüz kadar sanıp

akşam evde yapacaklarınızla mutlu olmanız da

televizyon ki 

senin tek öğretmenin

her şeyi biliyorsun sanıp

bir bok bilmediğini anlatamaz sana

küçük insanlar

ah sizler

küçük hesaplar senin işin

sen varsın diye karnı tok siyasetçinin

sandıkta oy verdiklerinin

ne seldeki kum tanesi gibi olmayı bildin

ne bildiğinin selde kum tanesi kadar olduğunu kabul ettin

iş üç kelimeyi bir araya getirmeğe geldiğinde

ufaldığını hissettin

aynaya da mı hiç bakmadın

söylediklerim senin iyiliğine

saygı göster senden bir fazla bilene

yaşamanız gereksiz demeye

dilim varmıyor ama

sandığın kadar değil bu dünya

sanatı gereksiz buluyorsun kendi gerekliliğini sorgulamadan

bir masa bir bilgisayar bir bordro işte senin dünyan

anlamadın kendini ölçmedin kendini

yine kaşının biri havada gezersin

küçük insanlar

ah sizler

hiç bir şeye hiç bir şey katan

sabah iş 

akşam dizi

kimsin nesin

ne kadar gereksizsin', 'küçük insanlar ah sizler kendi etrafınızda beş santim bilemediniz on beş santim cürümden ibaret  siz küçük insanlar hiç bir şeye hiç bir şey...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Mustafa']::text[], 8.5, '{"poet":"Gültekin Mustafa","poet_slug":"gultekin-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kucuk-insanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''a İnanmak...', 'allah-a-i-nanmak-ruya-deniz-demir-0w4zc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerime bakmak beni anlamak değildi. Ve hiçbir zaman gözlerime bakmamıştı ölüm. Beni tanımaktı aslında gözlerime bakmak ve gözlerimdeki hırsı gördüğünde şaşkınlıkla beklemekti. Beklemelerdeki tutsaklığa inat bir şeyler karalamaktı. Ölmekti kimi zaman. Ama ölmeyi bile sevmekti gözlerimde; gözlerime bakmak…

Gözlerine bakmak seni anlamak değildi ve de bilirim. Sözlerine aldanmaktı seni tanımak. Sözlerine aldandığımda beni aldatıp aldatmayacağındı. Kandıracak mıydın beni yoksa bir heves mi olacaktım senin için. Bunu elbet söyleyeceğin sözler gösterecekti. Ve ölmekse de sonunda sözlerine aldanmak; senin için ölmekti cesaret. Her aldandığımda yalan mı yoksa gerçek miydi sözlerin bunu anlamaktı her yolun sonunda sana dönüşlerimde…

Gözlerimize bakmak değildi bizi anlamak. Bizi sarmaktı doyasıya. Ölümün bile uzanamadığı ve tutamadığı ellerimizi sımsıkı tutmaktı bizi anlamak. Ve bize kavuşmak bütün hasretleri bitirmekti. Tüketmekti omuzlara akan yaşları ve gülümsemelerle eşitlemekti en ağlanmış şarkıyı. Bizi anlamak ölümdüyse de; bizi anlamak yaşamdı aslında…

Dünyanın her döndüğü an biraz daha yakınmaktı sevmek. Ve dünyanın merkezine yaklaşmaktı bizim için ölmek. Ve daha da yücelmek. Allah’a vaat ettiğimiz teslimatı yerine getirmekti. Biz ölmeyi seçmedik hiçbir an, ama ibadetimizdi an geldiğinde ölmek…

Dilden dökülmekti belki de anlamak dünyayı ve daha yaşanır bir hale getirmek. Dudaklarımı ıslatan bir tebessümün sıcaklığında uyanmaktı. Ölümün bile ulaşamadığı ellerini tutmaktı benim için. Anlam veren bir sevgi kadar içmekti dudaklarındaki zehri. Ve aldanmaktı hayata senin sözlerinle…

Ve ben hiçbir zaman, ve hiçbir kere yaşamamışlığım kadar sende varolmayı ant edinmiştim kendime. Ve yeminlerin en büyüğünü etmiştim…

Gözlerime bakmak beni anlamak değildi. Ve hiçbir zaman gözlerime bakmamıştı ölüm. Beni tanımaktı aslında gözlerime bakmak ve gözlerimdeki hırsı gördüğünde şaşkınlıkla beklemekti. Beklemelerdeki tutsaklığa inat bir şeyler karalamaktı. Ölmekti kimi zaman. Ama ölmeyi bile sevmekti gözlerimde; gözlerime bakmak…

Gözlerime bakmak, gözlerine bakmak, gözlerimize bakmak Allah’a inanmaktı ve yalnızca ona tapmaktı aslında…', 'Gözlerime bakmak beni anlamak değildi. Ve hiçbir zaman gözlerime bakmamıştı ölüm. Beni tanımaktı aslında gözlerime bakmak ve gözlerimdeki hı...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/allah-a-inanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sag Yanim Yikik', 'sag-yanim-yikik-yasar-gurlek-17i90', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani  derler ya  dik  dur  diye

Nasil  durayim sag  yanim yikik

Hani  derdin ya  op  saril  diye

Nasil  sarilayim su  kalbim kirik

Butun  zamanlarin en guzel  gulu

Ne sevdan kaldi ne sevgin askinda  olu

Suskundur  gonlemde  askinin   dili

Nasil soylerim su  gonlum kirik

Bir  bahar  gibiydin cabucak soldun

Kirlarin ciceklerinle gonlume  doldun

Her turlu derdini sagima  vurdun

Nasil  yasayim sag  yanim kirik

Bir gunes  gibiydin yaktikca  yakan

Derya  deniz  oldun gonlume  akan

Her  turlu  derdini yakama  takan

Nasil guleyim her yanim kirik

Yasar  Gurlek

Rotterdam

HOLLANDA

09-03-2006', 'Hani  derler ya  dik  dur  diye Nasil  durayim sag  yanim yikik Hani  derdin ya  op  saril  diye Nasil  sarilayim su  kalbim kirik Butun  za...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sag-yanim-yikik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yere Vurmali', 'yere-vurmali-yasar-gurlek-4bczp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Su  beni  kaldirip  yere  vurmali

Elin kolun ayagin kirmali

Bu  askin hesabin bir  bir sormali

Diyemezse  bir cukura alip koymali

Su  beni  ciril  ciplak  soymali

Kaynamis  kazana  alip  koymali

Gozlerini  teker  teker  oymali

Diyemezse  sopa  ile   vurmali

Su  beni  kalem ilen  yazmali

Sevmis  idim o cani burnu hizmali

Soyle diye bu bana iyi bir kizmali

Diyemezse  yerden yere  vurmali

Su  yasar,i  alip  sazi  calmali

Calamazsa  kafasinda  kirmali

Bu  sevdayi benden yare  vermeli

Diyemezse  onu  yere  vurmali

Yasar  Gurlek

Rotterdam

HOLLANDA

09-03-2006', 'Su  beni  kaldirip  yere  vurmali Elin kolun ayagin kirmali Bu  askin hesabin bir  bir sormali Diyemezse  bir cukura alip koymali Su  beni  ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yere-vurmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmisin Yar Senmisin', 'senmisin-yar-senmisin-yasar-gurlek-m4z1v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senmiydin boyle  sessizce  gelen

Senmiydin yar  senmiydin

Inanamadim bana   boyle  donusune

Hasret  idim  bir  kucucuk  gulusune

Cok  sevindim boyle  ani  gelisine

Senmisin  yar  senmisin  senmisin

Tam  bitmistim  hasretinle  askinla

Hep  bekledim sarayimla  koskumle

Cok  sevindim seni  birden  gorunce

Senmisin  yar  senmisin  senmisin

Dudagima  koydun yanan  buseni

Yillardir  bekliyordum  inan yar  seni

Ucurdun  sevincten  ucurdun   beni

Senmisin  yar  senmisin  senmisin

Yasar,i nin  bugun  gunesi  dogdu

Hasret  bitti  sevgilere  boguldu

Dunyadaki mutlu insan o   oldu

Senmisin  yar  senmisin  senmisin

Yasar  Gurlek

Rotterdam

HOLLANDA

09-03-2006', 'Senmiydin boyle  sessizce  gelen Senmiydin yar  senmiydin Inanamadim bana   boyle  donusune Hasret  idim  bir  kucucuk  gulusune Cok  sevind...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senmisin-yar-senmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hayat', 'i-ste-hayat-yasar-gurlek-yopsd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep  kötüler  bizi  bulur

Dertler  sıra  sıra  gelir

Olan bu garibe  olur

İşte  hayat  dersim  verir

Nere  gitsek  kurur  biter

Yeter  bire  felek  yeter

Bittim artık oldum heder

İşte  hayat  dersim  verir

Vara  yoka  hep  sınadın

Her   derdilen,de  denedin

Sanki  benle  var senedin

İşte  hayat  dersim  verir

Herşey  verdin  zehir  oldu

Gözlerime   yaşlar   doldu

Yoklugunda  bagrım yandı

İşte  hayat  dersim  verir

Yaşar,i  yi  çöl  eyledin

Söyle  sana  ben  neyledim

Hem  yazdım  hem  söyledim

İşte  hayat  dersim  verir

Yasar  Gurlek

Rotterdam

HOLLANDA

09-03-2006', 'Hep  kötüler  bizi  bulur Dertler  sıra  sıra  gelir Olan bu garibe  olur İşte  hayat  dersim  verir Nere  gitsek  kurur  biter Yeter  bire ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iste-hayat-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susku...', 'susku-ercan-akbay-f5o5f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çırılçıplak dallar

     Dökülmüş yapraklar

     Kuşlar uçup gitmiş

     Susmuş bütün şarkılar

     Ve sararmış doğa

     Mavi göğün altında

     Yapayalnız bir adam şimdi

     Şiirler yazıyor 

     Suskunluğa.....

                           HEY DERGİSİ    23.1.1984', 'Çırılçıplak dallar      Dökülmüş yapraklar      Kuşlar uçup gitmiş      Susmuş bütün şarkılar      Ve sararmış doğa      Mavi göğün altında ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/susku-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
