INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinmeyen Sızı', 'dinmeyen-sizi-turhan-toy-19u2u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mehtabın şavkına düşer ayazım 

hep kışta kalmışım nerede yazım 

seven gönüllerde yoktan da azım 

.............toplada zerremi ben varım sansın 

.............ruhum sabırların suyuyla kansın 

küllerin altında kalmış alazım 

ahlaki çöküşle artmış arazım 

karanlık iklimler duymaz avazım 

.............sen uyanma uyu vatanın yansın 

.............atalet içinde kalmış bir cansın 

yüreğim kan ağlar hiç dinmez sızım 

hazan mevsimiyle kesildi hızım 

mazlum coğrafyada şehittir kızım 

.............zulme dilsiz şeytan gibi susansın 

.............cahili fikrinle zehir kusansın 

haktan ayrılalı kalkmaz enkazım 

soğuk duş etkisi yakmaz ikazım 

şeytani seslerle bozulmuş sazım

.............aydınlıktan kaçıp zulme koşansın 

.............rahmeti beklerken ateştir şansın 

ihanetle kara oldu beyazım 

alem hakka dönsün budur niyazım 

şafak sökecekse adalet lazım 

.............haydi aç elini rahmet kuşansın 

.............tevhidi nizamla özgür yaşansın', 'mehtabın şavkına düşer ayazım  hep kışta kalmışım nerede yazım  seven gönüllerde yoktan da azım  .............toplada zerremi ben varım sans...', ARRAY['Türk Edebiyatı','Şiir','Turhan Toy']::text[], 8.5, '{"poet":"Turhan Toy","poet_slug":"turhan-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dinmeyen-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimim', 'kimim-evren-baloglu-16qeq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün garip bir gün ağlamaklı akşam 

Ayvalık sesiz deniz sakin 

Ve ben hüznün koyunda sahipsiz bir tekneyim 

Kimim ben bu cümbüşün ortasında bu yalnızlık neden

Herhalde yaşlanıyorum 

Artık gövdemdeki delikler kapanacak 

Boyutları çoktan aştı ve bir daha denizi kucaklayamayacağım

Ağlamak istiyorum', 'Bugün garip bir gün ağlamaklı akşam  Ayvalık sesiz deniz sakin  Ve ben hüznün koyunda sahipsiz bir tekneyim  Kimim ben bu cümbüşün ortasında...', ARRAY['Türk Edebiyatı','Şiir','Evren Baloğlu']::text[], 8.5, '{"poet":"Evren Baloğlu","poet_slug":"evren-baloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lale yanaklım', 'lale-yanaklim-elazigli-mustafa-kaya-j7wup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vurdum,

Yorgun gönlümü

Şafak aydınlığına.

Lale yanaklım

Utanç içinde

Hayat rüyasında…

Mustafa kaya

08.02.2000 / ankara', 'Vurdum, Yorgun gönlümü Şafak aydınlığına. Lale yanaklım Utanç içinde Hayat rüyasında… Mustafa kaya 08.02.2000 / ankara...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lale-yanaklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deryalar', 'deryalar-nedim-akgun-lvfjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedir kıymetin,nedir nimetin

Bulunmaz değerlerde oldu himmetin

Vefa dostusun sen işte kıymetin

Hayallere saldın beni deryalar

Dostluğun özüydü sende bulduğum,

Bir güzel uğruna hayal kurduğum,

Çıkmaz sokaklarda durup kaldığım,

Sözümün özüydü susan deryalar

İnsanlık dediğin sende var olan,

Hakikat zenginliğini içinde bulan

Mavi dünyalarda rengine boyan,

Dostlukta değerli oldu deryalar,

Bir vefasız değilsin küsmedim sana

Mutluluk yakındır kaderden yana,

Yaradan verirse bir ömür bana,

Hatırlarım seni güzel deryalar,

Düşler sokağımın hep gülü oldun

Hayaller kurdum ilhamı buldum

Senin gözünle ben dünyayı gördüm

Gördüğüm düşleri yazan deryalar

                                                       10 mart 2006

                                                         mavi', 'Nedir kıymetin,nedir nimetin Bulunmaz değerlerde oldu himmetin Vefa dostusun sen işte kıymetin Hayallere saldın beni deryalar Dostluğun özüy...', ARRAY['Türk Edebiyatı','Şiir','Nedim Akgün']::text[], 8.5, '{"poet":"Nedim Akgün","poet_slug":"nedim-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/deryalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ney anlatır ancak beni', 'bir-ney-anlatir-ancak-beni-elazigli-mustafa-kaya-csizt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimdeki depremleri

Feryatları

Hicranı

Kederleri

Ne anlatır sanırsın.

Bir ney anlatır ancak beni.

Harap ruhum,

Yılların izi.

Üflenirsem eğer,

Kapısını açacak

Ay yüzlüm.

Beni kim üfleyecek

Tek gücüm,

Dertli yüreğim,

Sırrım,

Sedef içindeki incim

Sevgilim  ….

Mustafa kaya

10.03.2006 / üsküdar', 'İçimdeki depremleri Feryatları Hicranı Kederleri Ne anlatır sanırsın. Bir ney anlatır ancak beni. Harap ruhum, Yılların izi. Üflenirsem eğer...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-ney-anlatir-ancak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biblo', 'biblo-mehmet-isikoglu-4ymmv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni metetmeye sözlerim yetmez

Aşkına düşenler yanar da tütmez

Yürek ferahlatan sendeki sevgi

Sonsuz bir hazine tükenip bitmez

Gözler aşk kuyusu yüzler gülistan

Aşıka yazdırır yüzlerce destan

Kalbine girenler yaşar cennette

Görenin gözleri arınır pastan

Rüya bahçesinde solmayan gülsün

Gönül kuşlarına konacak dalsın

Yürek yarasına dermandır dilin

Tadısın hayatın petekte balsın

Özenle yaratmış seni yaratan 

Farkın yoktur aşk yağdıran buluttan 

Hayalin gözlerde yerleşen resim 

Kalbimi fetettin eyledin vatan', 'Seni metetmeye sözlerim yetmez Aşkına düşenler yanar da tütmez Yürek ferahlatan sendeki sevgi Sonsuz bir hazine tükenip bitmez Gözler aşk ku...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biblo-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara uyandım', 'bahara-uyandim-safure-yildirim-bbtur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahara uyandım seninle

kar suyuna karışmış,

baharın ilk çiçeklerini 

beslemiş gözyaşlarım

Karanlık kış gecelerinde

korkuyla gelişen ben,

kendimden parçalar verdim

toprağa,

farkındasız.

bu toprakta yetişmiş

gül yapraklarıydı

öpmeye kıyamadığım dudakların,

bir yaz güneşi,

günün ilk ışığı gibiydi

yanımda uyandığında

sabaha açılan gözlerin..

ilkim  2005', 'Bahara uyandım seninle kar suyuna karışmış, baharın ilk çiçeklerini  beslemiş gözyaşlarım Karanlık kış gecelerinde korkuyla gelişen ben, ken...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahara-uyandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Satır Yazabilmek İçin Sana', 'tek-satir-yazabilmek-i-cin-sana-melih-coskun-blff6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek satır yazabilmek için sana 

Yazmayan kalemlerden medet umdum 

Ve kör bir bıçakla yardım sessizliğin bağrını 

Ellerim üşüyor 

Soğuktan değil ama 

Sadece yalnızlıktan üşüyor ellerim

Ellerim üşüyor

Ama sadece sensizlikten üşüyor ellerim 

Dört yanı yağmurlarla ve ihanetlerle kaplı bu şehirde 

Kendi kendimin tutsağıyım şimdi ben 

Ellerim bağlı değil,

Ne ayaklarıma dolanan zincirin acı gürültüsü 

Ne gecemin üstüne karabasan gibi çöken demir parmaklıklar 

Diyorlar ki şimdi bana; 

Sayılı gündür çabuk geçer 

Evet, geçer günler 

Ve her nasıl olursa biter zaman 

Ama nasıl sığdırır içine bunca kederi

*Unutma kalbim 

Her gece yeniden yazılacak bu şiir.

Ellerim üşüyecek tek satır yazabilmek içim sana 

Belli ki yine sensiz geçecek bu kış...

2004

www.melihcoskun.com', 'Tek satır yazabilmek için sana  Yazmayan kalemlerden medet umdum  Ve kör bir bıçakla yardım sessizliğin bağrını  Ellerim üşüyor  Soğuktan de...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tek-satir-yazabilmek-icin-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-ali-cengiz-turan-wid5q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öz olan ruhları güzelliklerle doyuran,

Şiir,roman,felsefe,edebiyat,

ve buna benzer kitapları okumayan insanları,

Büyük bir kayıpla yaşadıklarına inanırım.

ve böyle insanlar zenginseler,

Kurnası altından çeşmlere  benzetirim.

İçinde su olmayan çeşmelere bu meziyetleri,

bulunan yazarlarımızıda bildiklerini,

kendine saklamalarında suyunu akıtmayan,

Çeşmelere benzetirim..', 'Öz olan ruhları güzelliklerle doyuran, Şiir,roman,felsefe,edebiyat, ve buna benzer kitapları okumayan insanları, Büyük bir kayıpla yaşadıkla...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusunce-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnam ne yana...', 'turnam-ne-yana-zafer-zengin-etnika-4zc9n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

dil dolanır ‘

.

“ hayatın orta yerinde, kendine bakıp

ellerine ayna çakan adamın

karanfil sarılı sigarasından

burnuna dökülen dumanın sesi; 

oooff oofff…

hakkını helal eden yaşlı yolcunun

kır düşen saçlarında

son pişmanlık sevda”

vebal almadık akşamdan…



“ biliyordum oğul

öleceğimi bile bile

gittim peşinden

yüz görmedim yüzünden

hayırsız düştü yeniden

ağlayan en son ben

bakamadım yine yüzüne

toprağa verirken”

elim hani candı

ölsün istedi anası

..

pişman bir ölümlünün

kendine yiğitlik taslaması

açık seçik gördüğü gerçeğe

derdine yanması; 

anam geceme yar lazım

lazım ömrü uzatanım

“sevdanın yollara döşediği düşünceleri

kendi kendine anlatanın

sondan evvel ki aklı olsa

kopartırdı uğruna yandığını”

son sevdim

sevide evrildim

hani ellerin

ayrılığa yenildim

…

sustu sonra

sonra sustu

suslar konuştul….

….

zehrimiz sürülecek

onun adına yangınlarla

ne zaman yaz düşse anlımıza

alnımıza ter

nefesimiz düşer

ses gider

bahar ağlar yazgımıza

sonra yananlar bağırdı; 

-biz insanız, yanmamız değil ağladığımız, sizin anlayamayışınız.

toprak sünger kadar geri değil

emdiğini vermedi

dönenler gelmedi

-biliyorduk kırılan dal yapışmaz

-cana aşı, cana aşı, kan vermiş yoldaşı

her sıcak

bir günü gölgelik ederken

sevdasına döndüğü insan

kuranda

kurtaranda

sarıldı elinden

kara yobazlığın yakasına ”

cehalet ne güçlü

can alıyor tanrıdan

diyordu ki; 

can almazdı bizimkisi

benzemezdi anlattığınız

o bilincimizdeki

biri bağırdı geceye karşı

yalın yağız bıyıklı; 

size dur

size ölüm

size cehennem sunacak

size tanrınız anlatacak “

sustu sonra, sigarasından anlamaya çalıştı yanmayı

çaresiz kalmak değil, anlaşılmadan yok olmak acı ‘dedi

yürüdü bozkırın ortasında

ceylanlarla yana

karşı yoldan gördü gül yüzü

-turnam ne yana…

27 09 2005

.', '. dil dolanır ‘ . “ hayatın orta yerinde, kendine bakıp ellerine ayna çakan adamın karanfil sarılı sigarasından burnuna dökülen dumanın sesi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/turnam-ne-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanın t(adına) Vardım Varalı', 'i-syanin-t-adina-vardim-varali-aylin-ayla-selcukoglu-2ypyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İsyanın t(adına)  vardım varalı,acır dilim tuzuna banmaya... 

İçerim serin gözlerini gerberanın, 

Ya ki düşerim ardına sefil karanfillerin.. 

Kazancım olur birilerine kestiğim bilet, 

Zararım olur kendime topladığım seni yakan süreçler... 

Düşündüm ve,

Beni topladım yarıda kestiğim düşümle 

Seni topladım maziye düştüğüm küsüşümle...

10.03.2006 00.34', 'İsyanın t(adına)  vardım varalı,acır dilim tuzuna banmaya...  İçerim serin gözlerini gerberanın,  Ya ki düşerim ardına sefil karanfillerin.....', ARRAY['Türk Edebiyatı','Şiir','Aylin Ayla Selçukoğlu']::text[], 8.5, '{"poet":"Aylin Ayla Selçukoğlu","poet_slug":"aylin-ayla-selcukoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/isyanin-t-adina-vardim-varali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmadan Bir Daha Yar', 'ayrilmadan-bir-daha-yar-yasar-tezel-6844m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hislerde ağlar

Yaşananlar var

Anlamayan yar

Anlatılımayan duygular

Yıllar aşkları yıprattılar

Araya girmeden avukatlar

Çıkmadan paralar

Bir daha pişmanlıklar

Silinmeyen hatıralar var

Sevdiyse kalbin  anlar,

her seven hata yapar', 'Hislerde ağlar Yaşananlar var Anlamayan yar Anlatılımayan duygular Yıllar aşkları yıprattılar Araya girmeden avukatlar Çıkmadan paralar Bir ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilmadan-bir-daha-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilen Masalları', 'bir-bilen-masallari-muammer-erturan-bw2he', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne aşkmış bu 

hizmet aşkı yahu! .. 

Yapışmış bırakmaz koltuğu 

kırk yıldır

kırk yıl daha bırakmayacak 

bıraksalar... 

İlk soyunduğunda hizmete(!)

bacak kadar çocuktuk 

eşşek kadar adam olduk

hâlâ soyunuk... 

O hâlâ soyunuk 

biz hâlâ cıscıbıldak 

işimiz gücümüz trencilik oynamak,

önde çocuklar

arkada ''baba''

en arka vagon 

babaların babası Pentagon... 

On yılda bir 

makas değiştirir gerçi ya tren

değişen bir şey olmaz 

gidişatta pek... 

Yatışana dek ortalık 

boy göstermese de her yerde 

zat-ı âlileri 

duyurur iletisini her an 

kulaktan kulağa: 

Babanız soyunuk hâlâ... 

Bir Bilen Masallarında 

esas çocuk 

hep soyunuk 

hep soyunuk...', 'Ne aşkmış bu  hizmet aşkı yahu! ..  Yapışmış bırakmaz koltuğu  kırk yıldır kırk yıl daha bırakmayacak  bıraksalar...  İlk soyunduğunda hizme...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-bilen-masallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olduğum Zaman', 'sensiz-oldugum-zaman-ali-cengiz-turan-64kzp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz olduğum zaman güneş tutulur sanki,

O rengarenk çiçekler güzelliğini yitirir.

Dalgalarıyla köpüren masmavi denizlerin,

Hayaline dalıpta beni sana götürür.', 'Sensiz olduğum zaman güneş tutulur sanki, O rengarenk çiçekler güzelliğini yitirir. Dalgalarıyla köpüren masmavi denizlerin, Hayaline dalıpt...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-oldugum-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Kalan', 'sana-kalan-seher-ercan-knznp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mutluluğun resmi 

anılarda kalır kim bilir 

yüzündeki çizgilerin derinliğinde 

geçip giden zamanı fark edersin bir gün 

anlarsın o zaman yalnızlığını. 

sevdalı günlerin,özlemin olur belki 

yüreğini kasıp kavuran. 

dönüşü olmayan yollarda bulunca kendini 

bir rüya gibi canlanır gözlerinde 

yaşanan tüm hüzünler,ayrılıklar. 

karanlığında boşluğun 

çaresizliğine seslenirsin 

duyan olmaz sesini 

ucuz sevmelerin sızısı dolar yüreğine 

sıkar boğazını bir el sanki an be an. 

acı kokar her yer, bütün zaman 

hasretindir senin artık 

uzağında kalan her can 

susarak geçen günlerinin 

çığlığıdır şimdi sana kalan. 

10.Mart.2006', 'mutluluğun resmi  anılarda kalır kim bilir  yüzündeki çizgilerin derinliğinde  geçip giden zamanı fark edersin bir gün  anlarsın o zaman yal...', ARRAY['Türk Edebiyatı','Şiir','Seher Ercan']::text[], 8.5, '{"poet":"Seher Ercan","poet_slug":"seher-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-kalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızanım.', 'kizanim-veysel-alkan-n3dsa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sözdür yöremin garip hitabı.

Her cümle sonuna konur,KIZANIM.

Aradım,taradım birçok kitabı.

Anlamı bulunmaz sözdür,KIZANIM.

Soruyu soranlar,hemen başında.

Cevabı verenler,cümle sonunda.

Mutlaka kullanır,konuşmasında.

Anlamı bulunmaz sözdür,KIZANIM.

Samimi yaklaşıp,sevdiklerine,

Büyükler kullanır,küçüklerine.

Girmemiş TÜRKÇE''min,sözlüklerine.

Anlamı bulunmaz sözdür,KIZANIM.

İlk duyan şaşırıp,biraz bocalar.

Öğretmez bu sözü,çünkü hoca''lar.

Kullanan kalmadı,kalan koca''lar.

Anlamı bulunmaz sözdür,KIZANIM.

Duyunca gülesi,gelir insanın.

Nereden çıktı der,hangi lisanın? 

Alışıp söylenir,buna inanın.

Anlamı bulunmaz sözdür,KIZANIM.

Bilinmez,ilk önce,kime söylenmiş? 

Kim demiş ve yahut,kim icat etmiş? 

Dolanıp dillere,söylene gelmiş.

Anlamı bulunmaz sözdür,KIZANIM.

Şirinlik katıyor,konuşanlara.

Boğar bazısını,kahkahalara.

Derim ki,manasını soranlara.

Anlamı bulunmaz sözdür,KIZANIM.

Samimiyet ifadesidir,aslı.

Çünkü kullananlar genelde yaşlı.

Sizler de kullanın,gelince faslı.

Anlamı bulunmaz sözdür,KIZANIM.

MALKARALI DEDEKORKUT SAİM 

AGAM''ın tespiti doğrudur.Teşekkürler

AGAM! 

Bulunur anlayan,bulunur yazan. 

Yöremde diyorlar,çocuğa kızan. 

Anamın gönlünden,süzülüp sızan. 

Beni mest eyleyen sözdür, KIZANIM.

Kızan:Çocuk

Kızanım 1 şiiri için tıklayın', 'Bu sözdür yöremin garip hitabı. Her cümle sonuna konur,KIZANIM. Aradım,taradım birçok kitabı. Anlamı bulunmaz sözdür,KIZANIM. Soruyu soranla...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kizanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-mehmet-can-rdv1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yaramaz bir çocuk

Alıngan

Belki naylon bir bebek

Kocaman..

Etten kemikten..

Hayatı tanımadıktan sonra

Gerisi yalan..

Belki kızıl hayatın yorganısın..

Kimbilir

Beklide annenin kurbanısın', 'Sen yaramaz bir çocuk Alıngan Belki naylon bir bebek Kocaman.. Etten kemikten.. Hayatı tanımadıktan sonra Gerisi yalan.. Belki kızıl hayatın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bebek-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk', 'boncuk-mehmet-can-ipbcs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yağmur,  yine kar

Yine kalbim öyle dar

Gözlerim boncuk boncuk

Ağlamak neye yarar?', 'Yine yağmur,  yine kar Yine kalbim öyle dar Gözlerim boncuk boncuk Ağlamak neye yarar?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/boncuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışkı Makinası', 'diski-makinasi-muammer-erturan-z42h2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biri 

ışık tutar dünyaya

biri

kaşık...

Birinin aklı

başında

birinin

karnında...

Biri

insan gibi insan

biri

insan kaportasında

dışkı makinası...', 'Biri  ışık tutar dünyaya biri kaşık... Birinin aklı başında birinin karnında... Biri insan gibi insan biri insan kaportasında dışkı makinası...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/diski-makinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Böyle Biter', 'ask-boyle-biter-jale-demirdogen-lq6s4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce…

Sözcükler gider

Al gelincikler gibi cümleleri süsleyen…

Canım denmez artık

Sevgilim,aşkım,bir tanem…

Kurak bir tarla gibi kalıverir ortada

Boz bir renge boyanmış yapayalnız cümleler…

O zaman beklemek lazım; 

Yar aslında sana,o kurak cümleleriyle

Yakında gideceğim diye haber salmıştır.

Sonra…

Çılgınca esip yıkan kasırga diner

Artık zararı hesaplama anıdır

Giden neyi götürmüş,

Sana ne bırakmıştır…

Belki gönül incinmiş,

Gurur yara almıştır.

Ama çok fazla bekletmeden

Enkazı kaldırmak lazım

Artık neyi kurtarırsan yanına kardır

Nasılsa giden sana,

Ömürlük bir sızıyı hatıra bırakmıştır.

Şimdi…

Mevsim ilkbahar,güz,

Yaz ya da kış fark etmez.

Başını pencereden yana çevirmek zamanıdır

Yağmurlarla ıslanıp

Çiçeklerle konuşmak

Martılarla dost olup,

Bir simidi paylaşmak

Sezen’i tümden unutup,

Mozart’ı anmak lazımdır! 

Ve…

Sen kendinle hesaplaşıp

Hayatı yeniden sevmeye çalışırken

Cinayet mahalline geri dönen bir katil gibi

Yar yeniden geliverir

Muhtemelen dilinde son bir cümle kalmıştır.

Onu söyleyemezse rahatsız olacaktır.

Bu da genellikle hep,

‘Kendine iyi bak…ve hoşça kal’dır.

Tek kurşunla tek vuruş! 

Önce sözcükler gider….

Ve bu son cümle ile aşk böyle biter! 

Kurşun yüreği delecek,

Ve kalınabildiği kadar

Hoş kalınacaktır.', 'Önce… Sözcükler gider Al gelincikler gibi cümleleri süsleyen… Canım denmez artık Sevgilim,aşkım,bir tanem… Kurak bir tarla gibi kalıverir or...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ask-boyle-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Ihtiyacim yok', 'ihtiyacim-yok-kemal-oguz-2qoxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sair deseniz, Sair degilim

Bütün siirleri severim

Amatörce siir yaziyorum

Eger begenilip okunuyorsa

Bununla gurur duyuyorum

Taninmaya ihtiyacim yok.

Usta Sairler dururken

Güzel siirler okunurken

Tatli hayaller kurulurken

Ben kenarda dururken

Yazdigimla avunurken

Popüler olmaya ihtiyacim yok

(Filderstadt, 10 Mart 2006)', 'Sair deseniz, Sair degilim Bütün siirleri severim Amatörce siir yaziyorum Eger begenilip okunuyorsa Bununla gurur duyuyorum Taninmaya ihtiya...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ihtiyacim-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-mehmet-can-04t1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kum fırtınasına yakalanan  ruhum.

Erimekte  ince ince

Bu gece..

Titreyen  parmaklarımda

Kan çekilmekte..

Belirsizlik işte

Sıcaklıktan eser yok gibi

Buzdan dünya

İşte iki hece

Bu gece..', 'Kum fırtınasına yakalanan  ruhum. Erimekte  ince ince Bu gece.. Titreyen  parmaklarımda Kan çekilmekte.. Belirsizlik işte Sıcaklıktan eser y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-192-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Sen Hali', 'askin-sen-hali-jale-demirdogen-0662m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinin en kuytusunu sevdim; .

Durgun,ela bir gölün dibi gibiydi

Sözcüklerininse en huysuzunu! 

Onlar uslu cümlelerinin habercisiydi…

Eşkıya ruhuna giyindiğin kara yağız teninin

Kokusuna uyanmak için delirdiğim sabahlara küskünüm şimdi! 

Olsun, bekleyeceğim; 

Sabır bana alfabeden daha önce öğretilmişti! …

Bilmiyorsun; 

İnci gülüşünü kendime saklamak için

Ben bir denizkabuğu olmak istedim.

Ve bir Maria Callas çığlığında haykırmak sana

Seni ne kadar soprano sevdiğimi! ...

İstedim,

Geceleri penceresinin camına yakamoz vurmuş odamda

Sana bir şarkı yazmayı,hem de çok! 

İşte ancak şu birkaç satır…

Notaları da gözlerimden okursun artık,

Nasılsa fazla vakit yok! 

Aşk beni sıfırladı

Geçmişim yok

Geleceğim meçhul

Hissettirdiklerin yaşatacaklarının garantisi değil ki; 

Korkuyorum

Benden uzak dur! 

Kovala ruhumu,bitkin düş,yorul! 

Yo,hayır…vazgeçtim

Yaklaş…

Usulca öp de öleyim.

Hoş gör kararsızlığımı

Sen anlamazsın bendeki bu hali

Bu bendeki,aşkın sen hali.', 'Gözlerinin en kuytusunu sevdim; . Durgun,ela bir gölün dibi gibiydi Sözcüklerininse en huysuzunu!  Onlar uslu cümlelerinin habercisiydi… Eşk...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askin-sen-hali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük 2', 'dortluk-2-ali-cengiz-turan-5tcp8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnanma duyduklarına birtanem,

İnsanların vicdanı iyilik,kalbi sevmek içindir,

İnanma birbirlerine uymaz diyenlere nurtanem,

İnsanların aklı doğruluk,gözü görmek içindir.', 'İnanma duyduklarına birtanem, İnsanların vicdanı iyilik,kalbi sevmek içindir, İnanma birbirlerine uymaz diyenlere nurtanem, İnsanların aklı ...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-2-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yaprağı Ve Kalbim', 'guz-yapragi-ve-kalbim-jale-demirdogen-c65iy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalp kırılırken ses çıkarır mı? 

Benimki çıkardı. 

Hani yere düşmüş güz yaprağına ayağınızla basınca, 

Bir ses çıkar ya; 

Kalbim kırılırken çıkan ses de ancak o ses kadardı... 

Telaşlı,öfkeli ve bencildiniz 

Onun için duymadınız 

Çünkü sizin kulaklarınız değil, 

Asıl aşkınız sağırdı! ... 

Ama var ya... 

Ufalanmış bir yaprağa yeniden bastığınızda 

Aynı sesi duymayı delice arzulamak 

Besbelli... 

Yaprak için biraz ağırdı! 

Artık farketmez 

Dilerseniz kara postallarınızı çekmeyin üstümüzden 

Güz yaprağı ve kalbim 

Gidiyoruz... 

Al yanaklı, 

Yeşil gözlü, 

Uzun saçlı bir bahar 

Bizi çağırdı!', 'Kalp kırılırken ses çıkarır mı?  Benimki çıkardı.  Hani yere düşmüş güz yaprağına ayağınızla basınca,  Bir ses çıkar ya;  Kalbim kırılırken ...', ARRAY['Türk Edebiyatı','Şiir','Jale Demirdöğen']::text[], 8.5, '{"poet":"Jale Demirdöğen","poet_slug":"jale-demirdogen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guz-yapragi-ve-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-abdulvahap-ates-1bd0b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dünyada herşey bizim sanırız

varlığımız üzerinde debelenir dururuz

ama yarına isim bile koyamayız

insan ancak sebep olur

yarını, yaratan büyütür

yarını,yarınların sahibi yürütür

sonra kabir 

zamanı ancak o bilir

bize sadece hareket izni verir

dünyalara sahip oldum sanırsın

onu kullanırsın

aslında bedeninden gelir geçer

bir süzgeç gibi

her bedenine aldığın çıkarken bir şeyleri de yıpratır

kendiyle alır götürür

kazandık sandıklarımız aslında kaybettiklerimizdir belki de

ebede kimse sahip olamaz

ondan başka

bu kadar yüceliğe bu kadar cücelik

düşünsene...', 'dünyada herşey bizim sanırız varlığımız üzerinde debelenir dururuz ama yarına isim bile koyamayız insan ancak sebep olur yarını, yaratan büy...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarin-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki Sayılsın Yaşamaktan', 'ki-sayilsin-yasamaktan-muammer-erturan-hjtpl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İliklerine dek işleyecek

taşı toprağı

havası suyu 

acısı tatlısı 

karası akıyla 

ne varsa yaşama dair... 

Ki almış sayılasın

doğmuşluğundan doğan hakkını... 

Ve işleyeceksin iliklerine dek

ki çıksın ortaya 

romansa roman

türküyse türkü 

aşksa aşk

işse iş...

Ki vermiş sayılasın 

kapladığın yerin ve zamanın hakkını... 

O denli işte

iç içe olacaksın

hayatla yani

ki sayılsın yaşamaktan

verili zaman...

(''97)', 'İliklerine dek işleyecek taşı toprağı havası suyu  acısı tatlısı  karası akıyla  ne varsa yaşama dair...  Ki almış sayılasın doğmuşluğundan ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ki-sayilsin-yasamaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gel Meleğim', 'gel-gel-melegim-suheyl-turkoglu-r2ism', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk gördüğümden beri

Aşığım sana inan

Bayramlık ağızımla

Söylediklerim yalan.

Güneşin doğuşundan

Kuşların ötüşünden

Zevk almıyorum artık

Sensiz olmuyor dünyam.

Gel gel meleğim

Seni nasıl özledim

Bu yalnızlık içinde

Nasıl yaşarım.

Her yerde hatıran var

Ağlıyor bak duvarlar

Sofradaki tabakta

Yemek değil, zehir var.

Ayaklarım tutmuyor,

Gözlerim kör bakıyor,

Nefes alamıyorum

Hayat sensiz olmuyor.

Gel gel meleğım

Seni nasıl özledim

Bu yalnızlık içinde

Nasıl yaşarım.

Bestelendi.', 'İlk gördüğümden beri Aşığım sana inan Bayramlık ağızımla Söylediklerim yalan. Güneşin doğuşundan Kuşların ötüşünden Zevk almıyorum artık Sen...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-gel-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Besteleri', 'ask-besteleri-ali-cengiz-turan-hsvpj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk bestelerini yazanlar bozsun,

Aşk şiirlerini yazanlar silsin,

Kuruyan ırmaklar bırak kurusun,

Kerem ile aslının zamanı değil.

Kalpleri düşünceler açıklamıyor,

Bakışlar gülüşler inandırmıyor.

Dişlisi kırık çarklar artık dönmüyor,

Kerem ile Aslının zamanı değil.', 'Aşk bestelerini yazanlar bozsun, Aşk şiirlerini yazanlar silsin, Kuruyan ırmaklar bırak kurusun, Kerem ile aslının zamanı değil. Kalpleri dü...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-besteleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo', 'tablo-ali-cengiz-turan-x5hc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgarlar  sevgimize şarkı söylerken,

Sensiz hüzün esiyor,ağlıyorlar mı? 

Ağaçlar dallarıyla alkış tutarken,

Yeşillikler kaybolmuş soluyorlar mı? 

Yıldızlar pırıl pırıl ay gülümserdi,

Bu tablo gözlerimden yaşımla aktı.

Tek ruh olup uçarken dünya cennetti.

Sevgi pınarlarımız kuruyorlar mı? 

İki kalbin üstüne çizilen tablo,

Yarım kalmış eserin görüntüleri.

Başladığın eseri bırakma ressam,

Sevgisiz olan kalpler kuruyorlar mı?', 'Rüzgarlar  sevgimize şarkı söylerken, Sensiz hüzün esiyor,ağlıyorlar mı?  Ağaçlar dallarıyla alkış tutarken, Yeşillikler kaybolmuş soluyorla...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tablo-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahil Kal', 'cahil-kal-suheyl-turkoglu-23zil', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Çok bilen, çok yanılır.''

Öğrenmeye çalışma

Cahil kal,

Yoksa hayat boyu yanılır,

Evin yolunu bulamazsın.

''Ata Sözleri İle Taşlamalar'' kitabından.', '''Çok bilen, çok yanılır.'' Öğrenmeye çalışma Cahil kal, Yoksa hayat boyu yanılır, Evin yolunu bulamazsın. ''Ata Sözleri İle Taşlamalar'' kitabı...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cahil-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kızın Büyük Burnu', 'kucuk-kizin-buyuk-burnu-metin-onal-mengusoglu-061vm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kendi ağzın nerde

güzel kız

o kızıllık nedir öyle

nasıl oluyor

gözlerin yeşil

saçların ebrûlî kestane

ellerin nerde

güzel kız

hakiki parmakların

tüyün

ürpertilerin

dişlerin

sen yoksun

seni arkada bırakan

bir kabus

önde duruyor

bağışla

sevemiyorum seni

çünkü ben

kabuslardan korkarım', 'kendi ağzın nerde güzel kız o kızıllık nedir öyle nasıl oluyor gözlerin yeşil saçların ebrûlî kestane ellerin nerde güzel kız hakiki parmakl...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kucuk-kizin-buyuk-burnu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatirasi yuregim de', 'hatirasi-yuregim-de-ulya-erkman-yzokw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kirmizi gul elinde soylemisti

Bana sevdigini

Parklar bahceler ezberlemisti 

Hikayemizi

Otururduk dere kenarinda dinlerdik suyun

Siril siril sevgimize ahenk verisini

Kosardik omuz omuza adeta ruzgarla 

Yaris edercesine

Mehtap gulerdi bize hoslanmis gibi

Bu derin askimizdan

Yururken ciplak ayak sularda alkis gelirdi sanki

Kopuren dalgalardan

Oturunca bir agacin dibine yapraklar derdi sanki

Allah ayirmasin birbirinizden bu guzel askinizdan

Birbirimizin varligidir zaten bize hayat veren

Birimiz olmasa otekine olurdu hayat zindan

Gelince evimize ahenk katardi terastaki salincak

Birbirimize sarilip sallandikca durmadan

Konusurduk hayatin guzelliklerinden

Sonmeyecek olan askimizdan

Hayaller kurardik ne yapacagiz ilerde diye

Askimizi yormadan

Gulerdik kurdugumuz hayallere kendimiz de

Daha yetecek paramiz olmadan

Ama gitti o ne yazik kaldi sadece 

Yarali bir yurek

Mehtap mahsun bakiyordu 

Uzulerek

Derenin siriltisi sakin akiyordu 

Yoklugu hissederek

Deniz de dalgalar hircin

Bu yoklugu ozleyerek', 'Bir kirmizi gul elinde soylemisti Bana sevdigini Parklar bahceler ezberlemisti  Hikayemizi Otururduk dere kenarinda dinlerdik suyun Siril si...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hatirasi-yuregim-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-demir-erem-ovtxp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '5 yıldır ilk defa ağladım bugün,

Kanattım kabuk tutmuş sırtımdaki  yaralarımı,

İçimden atmak için seni,

Akman için tenimden…

Bana can verir sanırken seni,

Gün ve gün bedenimi kemirdiğini

Anladım bugün,

Neşteri vurdum kendime,

Hançerlerinden daha derin,

Acılarım uyuşturmuşken bedenimi,

Söktüm içimden seni,

Dağladım boşluğunu

Bir daha bedenime girememen için.', '5 yıldır ilk defa ağladım bugün, Kanattım kabuk tutmuş sırtımdaki  yaralarımı, İçimden atmak için seni, Akman için tenimden… Bana can verir ...', ARRAY['Türk Edebiyatı','Şiir','Demir Erem']::text[], 8.5, '{"poet":"Demir Erem","poet_slug":"demir-erem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bugun-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemesende', 'i-stemesende-cahit-pehlivan-zg3mn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanı durduracağım desende,

Zaman durmayıp geçecek, istemesende.

Ayrı düşeceksin sevgilindende,

Hayır hiç ayrılmayalım desende.

Gonca güller solmasın desende,

Hepsi gün gelip, solacaklar dalında.

Bülbül figanını kesmesin desende,

Mevsim hazanı getirince, susar bülbülünde.

Neye dur. Ne olur kal desende,

Görüyorsun olmuyor, senin isteğinle,

Sevgilinden ayrı düşüyorsun elbette,

Sen hayır ayrılmayalım diyerek, ayrılık istemesende,

Güller açıp, soluyor. Bülbüller susuyor.

Herşeyin başlangıcı gibi, sonunu da getiriyor.

Sen istediğin kadar hayır diye diye,

Feryat etsen de, olacak bütün bunlar.

Sen istemesende olmasın desende,

Olacak, olacak dostum, sen istemesende.

(İstanbul)', 'Zamanı durduracağım desende, Zaman durmayıp geçecek, istemesende. Ayrı düşeceksin sevgilindende, Hayır hiç ayrılmayalım desende. Gonca gülle...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istemesende-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra', 'hatira-cahit-pehlivan-lznvc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sebepsiz bir ayrılığın sonunda,

Birkaç küçük sözün çınlar kulağımda,

Seni düşünüp andıkça her gece rüyamda.

Son sözlerin yaşatır beni hatıralarda. 

Her gün eğlenirken sevgilim seninle,

Ayrıldığımızda düştük bak dillere. 

Dostumuz yok artık ne senin ne de benim.

Yalnızız şu dünyada tek başımıza sevgilim.

Bıraktığın eski bir resminle, mektupların. 

Kulaklarımda çınlayan gülüşlerin.

Hatıra olarak kalacaktır benimle,

O mazi dolu hatıralar sevgilim belki de, 

Bir gün maziye karışacaklardır seninle.

Hatıra olarak yalnız fotoğrafların kaldı elimde. 

Seni anmak isteyeceğim.

Gözyaşlarımı sile sile sevgilim sile sile.', 'Sebepsiz bir ayrılığın sonunda, Birkaç küçük sözün çınlar kulağımda, Seni düşünüp andıkça her gece rüyamda. Son sözlerin yaşatır beni hatıra...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatira-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldür Beni', 'oldur-beni-cahit-pehlivan-2majb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al eline bıçağını, hançerini

Sapla sineme sevgilim.

Hiç düşünme bu aşkın peşini,

Al eline sapla sineme hançerini,

Beni yaralayıp, öldürüyor.

Her gün seni anıp, ağlayışım.

Beni kalbimden vuruyor.

Senin hayalinle ve sözlerinle avunuşum.

Ankara', 'Al eline bıçağını, hançerini Sapla sineme sevgilim. Hiç düşünme bu aşkın peşini, Al eline sapla sineme hançerini, Beni yaralayıp, öldürüyor....', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oldur-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Yıllık Bina', 'bin-yillik-bina-muammer-erturan-flzo9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bin yıllık bina...

Temelinden çatısına

dişle tırnakla

ve özlemle

ve umutla örülmüş

her bir tuğlası...

Umurundaydı çok...

Bin yıllık bina...

Olmasa da olur

bir enkaz yığını şimdi...

Daha da beteri

çok gördü ölümü

gözü kör olası yıkım...

Sıçmışım adaletine...

(24 Kasım ''99)', 'Bin yıllık bina... Temelinden çatısına dişle tırnakla ve özlemle ve umutla örülmüş her bir tuğlası... Umurundaydı çok... Bin yıllık bina... ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bin-yillik-bina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler Bizi Söyler', 'turkuler-bizi-soyler-ali-riza-malkoc-sbhgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhsatî verir dersini

Veysel öldürür nefsini

Yad edelim gel hepsini

Türküler hep bizi söyler

Turabî’dir toprak misal

Sümmanî de özler visal

Anlayana yoktur sual

Aşıklar hep bizi söyler

Yunus Emre varır Hakk’a

Pir Sultan bir mesaj halka

Dervişlik değildir hırka

Ozanlar hep bizi söyler

Kuddûsî nakışı nurdan

Karac’oğlan dertli yardan

Akarsu da göçtü burdan

Gönüller hep bizi söyler

Ali Rıza Malkoç

Bursa  10/03/2006

www.arm.web.tr

Yad etmek: vefa ile hatırlamak

Misal       : örnek

Visal       : Sevdiğine kavuşma,ulaşma,varma

Sual        : Soru', 'Ruhsatî verir dersini Veysel öldürür nefsini Yad edelim gel hepsini Türküler hep bizi söyler Turabî’dir toprak misal Sümmanî de özler visal ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Malkoç']::text[], 8.5, '{"poet":"Ali Rıza Malkoç","poet_slug":"ali-riza-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/turkuler-bizi-soyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzet', 'farzet-bahri-capgulas-i6e26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tılsımımı kaybettim 

Seni kaybettiğimde.

Öldü dersin kendi kendine 

Beni aklına getirdiğinde.

Sakın üzülme ve düşün me; 

Çünkü ben hiç bir şeyinim.

Eskide kalmış herhangi birisiyim

Kıyıda köşede kalmış bir eşya gibiyim.

Derdetme sakın beni

Hoyratça düştüğümde hayatından

Derdetme hiçbir halimi

Senin için ha ben ha sokaktaki dilenci.

Baktığında görmene gerek yok ki

Hatırlanacak neyim var sanki

Ne paylaştık ki seninle her yan yana gelişimizde

Ne paylaştık buluşmalarda gizli gizli.

Sesimi duyduğunda heyecanlanmana gerek yok

Farz et telefonda bahsetmedim Leyla ve Mecnundan

Farzet bahsetmedim sana derin aşkımdan

Farzet hiç tanımadığın yanlış aramış biriyim ben.

Aklına getirme beni sohbet edenleri görünce

Karşılıklı oturmadık çünkü seninle

Karşılıklı bakışmadık; bakmadım gözlerine,

Farzet gülümsemedim senin sözlerine.

Farzet hiç tanışmadık

Bahri diye biri olmadı hayatında

Hiç karşılaşmadık bu dünyada

Farzet ben yokum anılarında

Farzet hiç olmadım hayatında.

				12.02.2004', 'Tılsımımı kaybettim  Seni kaybettiğimde. Öldü dersin kendi kendine  Beni aklına getirdiğinde. Sakın üzülme ve düşün me;  Çünkü ben hiç bir ş...', ARRAY['Türk Edebiyatı','Şiir','Bahri Çapgulaş']::text[], 8.5, '{"poet":"Bahri Çapgulaş","poet_slug":"bahri-capgulas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/farzet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tacına taş olayım *', 'tacina-tas-olayim-nazan-i-zmirli-5kbgw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'izin  ver! 

kalbine

taht   kurayım.

tahtın 

prensi   sen

kadının

ben   olayım.

sevda

köşkü 

aşkımız.

tacının  taşları

erdemliğinin 

ışığını.

sükütü  bilen

dilin,

bitmeyen

öykümüzün

yolunu 

bulsun........

''her  erdemli  erkeğin 

görünmeyen...............

yürekli bir kadını vardır''

10.03.2006-antalya', 'izin  ver!  kalbine taht   kurayım. tahtın  prensi   sen kadının ben   olayım. sevda köşkü  aşkımız. tacının  taşları erdemliğinin  ışığını....', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tacina-tas-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıbin Yıl Savaşları', 'altibin-yil-savaslari-muammer-erturan-frft7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altıbin yıldır işleyegelmiş

genlerine iyice

ezilip duruşu habire...

Zincirlenmedik 

tek erkek kalmayana dek

intikam tütecek 

tüm gözeneklerinden

fosur fosur...

Ne yapsan nafile...

Evet! de

haksızlık edildi size

hâlâ da edilmekte...

O davada 

yanınızdayım ben de...

Sen ne dersen de

o bildiğini okur gene...

Altıbin yıllık bilinçaltı bu

boru değil...

Kolay değil silmek

onca izi...

İlla ki çıkaracak acısını...

İlla ki acıtacak o da...

Teslimiyet

masumiyet

entrika

isyan, 

ne ararsan var 

öte yandan

oltanın ucunda,

balık ol da tutulma hadi! ..

Altıbin Yıl savaşları öncesi

böyle değildik...

Ne mülk diye birşey bilirdik

ne kölelik diye bir hâl,

geçinir giderdik ne güzel

sevişe oynaşa

komünal komünal...

(18 Haziran ''98)', 'Altıbin yıldır işleyegelmiş genlerine iyice ezilip duruşu habire... Zincirlenmedik  tek erkek kalmayana dek intikam tütecek  tüm gözenekleri...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/altibin-yil-savaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonradan Görmek', 'sonradan-gormek-metin-onal-mengusoglu-7ontv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eskiden

bir adamın

ince olan yüzü

sonradan toparlak-

laşırsa bilelim/mi/ki

acımasızlık daha çok 

yakışır böylelerine

Cebini değil keşke, insanın

zihnini zengin eden bir meslek

edinmiş olsaydım, diyorum

sözlük yazarı mı olsaydım

kelime oyuncakçısı mı yoksa

kurşun harfler döken bir dökümhanede

körükçü olmak da yeterdi belki

sırtı, evlerin çatısına benzeyen

koyu mavi bir kamyona

gazeteleri istifleyen muavin

de olabilirdim

İncecik incecik bir güneş

vursa penceremden içeri

perdenin kenarında biliyorum

ossaat gülümseyecek yüzüm

Ilık bir lodos ya da

yakalayıp geçse ucunu kasketimin

alnım yeniden ışıklanacak

ben, sonradan görme arkadaşın

hem rüzgara hem güneşe gülümsüyorum

Yüzüne bakıp kimseyi

yargılamamalı bir daha

şişman yatıp da insan

zayıf kalkabilir sabaha', 'Eskiden bir adamın ince olan yüzü sonradan toparlak- laşırsa bilelim/mi/ki acımasızlık daha çok  yakışır böylelerine Cebini değil keşke, ins...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sonradan-gormek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Olmaz Kimliği Arkadan Vurucunun', 'belli-olmaz-kimligi-arkadan-vurucunun-metin-onal-mengusoglu-dk6vu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.

kim bilir bizim bildiğimizi

suratımızda maske

kitabımızda yalan yok

tanımakta ustayızdır münafığı

ve de arkadan vuranı

öfkenin ve öçalmanın zamanını

iyi biliriz,

kim bilir bizim bildiğimizi

ölümden sonraki

ve önceki hayatı

ve mutluluğu.

duyarız

sâdık duyarız

doğmadan güneş

daha gölgesi düşmeden arza

hiçbir canlının

daha uyanmadan çiğ altında filizler

bize dar gelir yataklar

silkinir seyrederiz

ak ipliğin

kara iplikten ayrıldığı anı,

günde beş vakit temizleriz zamanı

kim bilir bizim bildiğimizi

kim tanır

arkadan vuranların yıkamadığı

sessiz kahramanı

2.

bütün düşmanlıklarınız

bize rahmet getirir

haberiniz yok

mazluma kıymak yoktu

-ya nasıl kıydınız insana-

ah

yüzünüz gerçek değil ki utana

lakin ''savaş

gerçek yüzünü gösterince''

yırtıldı maskeleriniz

çıktı münafıklığınız meydana

3.

kurşun yarasına çare bulunur

çare bulunmaz yalana

demire dayanır da dişlerimiz

kalleşliğe dayanmaz yürek

4.

toplanıp hesapladılar

unutarak büyük hesabı

unutarak insanı

arkadan avlamanın zilletini.

hedefe kim gelirse vurmak için

gül yüzlü bir çocuk mu

dul bir kadın mı

yetim mi öksüz mü kimsesiz mi

demeden

parmakları erkekçe katlandı bu zahmete

çekti tetiği

yere düşen silahsızın üstünde

kan içerek paylaştılar zaferi

hasımsız bir alanda

yumruklar gökte

5.

ama ağıt mı yakacağız.

yas mı tutacağız.

bizde güneş tutulur

yas tutulmaz,

bizde dayanmanın adı şükür

bizde bilenmenin adı sabır

bizde savaş ölüm değil hayattır

bizde düşman insan değil,

fikirdir.

silaha silahla karşı koymanın

yeri de vardır

yalnız kalleşlere uygulanamaz.

6.

sen yalnız

silah elindeyken savaşırsın

bense

senin beynini kemiren putlarla

savaştayım her an..

ben

vurulurken bile seni düşünürüm

biliyorum

benden daha çok acılar içindesin

seni mahvetmeye yeter ölüm korkusu

ölümü -yalan mı-

bir an düşünmeğe dayanamazsın

bu sana vahşeti öğretmiştir

ancak kan içince rahatlarsın.', '1. kim bilir bizim bildiğimizi suratımızda maske kitabımızda yalan yok tanımakta ustayızdır münafığı ve de arkadan vuranı öfkenin ve öçalman...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/belli-olmaz-kimligi-arkadan-vurucunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İ / ti / raf', 'i-ti-raf-nazan-i-zmirli-7lvh7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalan

unutmuşluğum 

unutmak

istediğim  

yalan

i  /   ti   /  ra  /  fım 

var  sana

istediğim  tek şey

unutulmamam

ben............................

yürekli  bir  kadınsam       

......................doğrusu

...yalan

............yalan 

.....................yalan

seni  sevmediğim  yalan.

10.03.2006-antalya', 'yalan unutmuşluğum  unutmak istediğim   yalan i  /   ti   /  ra  /  fım  var  sana istediğim  tek şey unutulmamam ben..........................', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/i-ti-raf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cila Kül Ve Kefen', 'cila-kul-ve-kefen-metin-onal-mengusoglu-5f3wf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

nerde bir boş tarla bulsalar

koşup oraya mabetler dikmek için

yine de makbuzlar bastırılır

pullar satın alınır

bu cüzdanlar biletler kimlik kartları

nasıl da sağlam onaylatılmış olur

nasıl da hıfzedilir koyunlarda

uçmuştur avuçlardan bir kez

ah, nerde kaldı bütün bu çıbanları iyileştiren ecza

nerde kaldı

şimdi dünyanın

derin, yaralı bir azası gibi

kendini eyyuba benzetmek için

sahte sabır taşlarına çarpanlar

başlarını

II

Allahım dayanılmaz birşey

görüyorum

herbiri bir köşesinde kentin

bizimkiler

piyango satıcıları.

namazı üniformalı kasketleriyle kılıyorlar

yahut simsiyah sakallı seyyarcılar olarak

başları derde girince belediyeyle

koşuyor

doluşuyorlar cami kıyılarına

ince çubukların ucunda

oyuncak bayraklar gibi diyanetleri

daha gözleri açılmamış bebelere

renkli şekerler satıyorlar.

kafam kamaşıyor birçok şeyden

bu gelen aydınlık değil sanki

cilâ

bazı cumalar ondan parlıyor

ondandır öğretmiyor

ürpertiyor bazı gazeteler

loş kuytularda

nemli koridorlarda sabahlayan çocukları.

çoktandır dev ayaklarını

toprağa gömmüş

bu selâtin (sultanların yaptırdığı)   yapıların süsü

yaşlı, boyalı bir kadını andırıyor

magazin mecmualardan kesilmiş bir yaprak gibi

öyle mahzun

ve öyle yabancı

ayrı kurtlar kemiriyor içini herbirinin

ayrı korkuları yaşıyorlar anbean

kimi bir ölünün toprağına bağlayıp umudunu

hazreti İsa''yı beklerken Mehdi diye

kimi düşlerinde çıkagelen Hızır''la uğraşıyor

kimi cebinde günaydın gazetesi

ağzı oruçlu

kiminin destan oluyor abdest alarak saygı duruşu

bütün cenazeleri kaldıran onlar

bütün mevlidleri dinleyen onlar

ve onlardır bütün mumları yakan

muskalar masklar gözboncukları

manevî sermayeler taşıyan

ve nasıl yaklaşıyorlar birbirlerine

bir hükûmet bildirisi duyunca

özgürlüğe ve demokrasiye dair.

Allahım, nasıl dayanılır, kıyam durulur

şehrin kirlenmiş toprağında

hergün bir başkasmı görüyorum

kafam kamaşıyor bazı şeylerden.

III

bürün bürün başkalarının kefenine

yaşa, hep bir başkası olarak yaşa

durmadan bir başkası olarak görün

şu halk sözcüğü meselâ nedir

gecenin ilerlemiş vaktinde

ne arıyor hafızamda

ve hanginiz halktır arkadaşlar

ve yönetmek için kendi kendinizi

kimdir sizi halkeden (yaratan)

millet''tiniz ne güzel siyahlar

sarı ırklar beyaz kırmızı tenler

ansızın halk oldunuz

''on yılda onbeş milyon''

kırıla kırıla bitmeyen kavgalarda

ansızın halk oldunuz

düştü kasketiniz öne

gayrı bakıverseniz hangi yöne

''demir ağlarla örülmüş bir vatan''

düdüklü polisler trenciler

kültür yuvaları halkevleri balolar

çok eskiden giyinmiştiniz oysa

bu tulûat kefenini

kim ne derse desin

kim savunursa savunsun geçmişinizi

kendi ellerinizle bozdunuz kendi güzelliğinizi

benimse söylemekten başka çarem kalmadı

bu çömelmenin ilâcı

bulunur yine de kendi cevherinizde

haydi başkalarının kefenine bürün

yaşa, kendin olmayarak

durmadan bir başkası olarak görün

aklım kamaşıyor benimse

''ağaç kökünü kemirmek kadar zor''

bu yalnızlık

kabuk mu bağlıyor halkın

hayır milletin yüzü

bulsam

küçük bir alâmete rastlasam

bütün bu yaraların iyileşmesine dair

kalemlerimi sevinçle kırıyorum

kalbim kamaşmıyor bir daha.', 'I nerde bir boş tarla bulsalar koşup oraya mabetler dikmek için yine de makbuzlar bastırılır pullar satın alınır bu cüzdanlar biletler kimli...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":108,"source_url":"https://www.antoloji.com/cila-kul-ve-kefen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüme Bakan Deliler', 'yuzume-bakan-deliler-metin-onal-mengusoglu-1a79x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokaklardan deliler geçti

Omuzlarına lâme yıldızlar takmışlardı

Göğüslerindeki düğmeler dore

Garip madalyonlar iri tesbihler

Kehribar kibrit kutuları tabakalar

Sokaklardan deliler geçti

Işıkta parlayan nesneler geçti

Dürülmüş bükülmüş gazeteleri

Püro gibi ağızlarına takmışlardı

Bronz büstün önüne ulaşınca

Lüküs cigaralarını yakmışlardı

Köylerin kasabaların ve şehirlerin

Herkesin delileri bir örnek

Kılıklarına kıyafet olmuş

Ne varsa palto ceket hep üniforma

Anlamsız derinlikler içeren yüzleriyle

Dönüp dönüp yüzümüze bakmışlardı

O gözleri hiç titremeyen ahbaplar

Göğüs kapıları kaygılara kapalı

Deliler, tenleri hiç buruşmayan komşular

Sokaklardan deliler geçti

Yanlarında tereddütsüz sallanan ellerinin

Lâstikten çekiciyle bir ömür boyu

Bakışlarını çivileyip çakmışlardı

Cepleri dolapları gardropları

Dopdolu kutularla ahşap ve karton

Oradan toprağa bir sır bırakmışlardı

Sokaklardan deliler geçti

Sonra bir yağmur alıp götürdü korkularını

Eridi renkler sırmalar üniformalar

Küçük renkli gölcüklere kaldı sokaklar

Delilerse hâlâ işin keyfinde

Sokaklarda su olmuş akmışlardı', 'Sokaklardan deliler geçti Omuzlarına lâme yıldızlar takmışlardı Göğüslerindeki düğmeler dore Garip madalyonlar iri tesbihler Kehribar kibrit...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yuzume-bakan-deliler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okçu', 'okcu-duygu-gunkut-xru87', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Attık ama,

Öldürdük mü sizi şimdi? 

Oklarımız bize doğruydu ama,

Bizi bölüp parçalamaksa niyetiniz,

Siz bizi hiç anlamamışsınız...

ne yazık ki iki gruba ayrıldık

ama çok  bilge insanlardık...

Tüm yelpazeler açılırken,

Serinlemeyen tüm erkler,

Kaderinize boyun eğmek mi

Kederiniz? 

ne yazık ki iki gruba ayrıldık

ama çok geçici insanlardık...

Yemin ettim barışa.

ne yazık ki tek bir müfrezeydik,

biz bizeydik.', 'Attık ama, Öldürdük mü sizi şimdi?  Oklarımız bize doğruydu ama, Bizi bölüp parçalamaksa niyetiniz, Siz bizi hiç anlamamışsınız... ne yazık ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/okcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Ötesi(Cehennem)', 'bizden-otesi-cehennem-omer-bolat-3lp9k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi gidiyorsun…

Kilitleniyor lûgatim.

Düşmemek için elinden

Çırpınıyorken kalbim,

Ne söylesem yere düşüyor

Her kelime.

Şaşıyorum…

Sevgim ve gururum,

Şizofrenik bir vâkıanın

Takıntısında.

Kalbimse,

İçimde patlayan volkan lavların

Akıntısında.

Ve ortak dengenin ritmine uyan dilim

Susuyorum…

Kapıdan dışarı

İlk adımını atıyorken,

Büyüyor gözbebeklerim.

İkinci adımında

Beni bana satıyorken,

Kördüğüm oluyorum saçının teline.

Bozuluyor ritmim,

Çözülüyor vâkıam,

Ürkek bir ceylan gibi

Ellerim değiyor eline.

Ağlıyorum…

Korku doluyor bakışlarım

Yakarış mı istersin? 

Gözyaşı mı istersin? 

Dünyalara bedel yüreğim,

Önüne hangi cenneti sersin? 

Söyle ne dersin? 

Son bir defa,

Soruyorum…

Birinci kat,

İkinci kat,

En tepede yedinci kat.

Yada boşver! 

Devir elinin tersiyle

“Bizi” kaldır at! 

Sensizliğin cehennemine

Gidiyorum! ...

10 Mart 2006 Cuma

Adapazarı', 'Şimdi gidiyorsun… Kilitleniyor lûgatim. Düşmemek için elinden Çırpınıyorken kalbim, Ne söylesem yere düşüyor Her kelime. Şaşıyorum… Sevgim v...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bizden-otesi-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarflar', 'zarflar-ahmet-agdere-gyi5p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Henüz kullanılmamış zarflar, 

Çekmecenin gözlerinde bekler. 

Birilerine gönderilmek için, 

Yanıp tutuşup oflar çeker. 

Sararmış, pörsümüş zarflar, 

Aç kurt misali ağzı açıklar,

Fırtınalı bir kış gününde, 

Okşanmak, sevilmek ister...

Ve dilimde söylenmemiş sözler,

Bahara doğru, yüreğimde biter.

Gözlerinin dibinde özlemimi görünce,

Ansızın dilim, zarfın tutkalına gider…', 'Henüz kullanılmamış zarflar,  Çekmecenin gözlerinde bekler.  Birilerine gönderilmek için,  Yanıp tutuşup oflar çeker.  Sararmış, pörsümüş za...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zarflar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-kemal-bayrakci-w02tx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlasan

gözyaşların  ateştir 

damlar yüreğime

ince sızımsın

Kaf dağı kadar yakın

düşlerim kadar uzak

imkansızımsın

Sürgünden dönmenin sevinci gibi

içime aktığın o an

Sanki bedenimden

sessizce ruhumu çalan

hırsızımsın.

Yıldırımlar düşmez içime

nurunun nakşettiği

zırhımsın

Bir gün görmesem

dudaklarımdaki tebessümün katili

efkarımsın

Gözlerinde

gözlerimi hapseden bir büyü

baktığın o an

Kül olsam

karşılığı yok hasretimin

hicranım

imkansızımsın.', 'Ağlasan gözyaşların  ateştir  damlar yüreğime ince sızımsın Kaf dağı kadar yakın düşlerim kadar uzak imkansızımsın Sürgünden dönmenin sevinc...', ARRAY['Türk Edebiyatı','Şiir','Kemal Bayrakcı']::text[], 8.5, '{"poet":"Kemal Bayrakcı","poet_slug":"kemal-bayrakci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-an-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunay Akın', 'sunay-akin-kemal-bayrakci-orlba', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'derler ki tanrıdır yalnızca

yoktan var eder her cismi

çirkin bir bedende oysa

güzel bir ruh yaratır

yüreğinden şair kısmi.

tarifsiz bir hazla çekerim içime

kız kulesi eli kokan şiirlerini

gözümde canlanır hayal meyal hatıralar

görmesem de çocuk düşlerimin müzesini.

kimse görmez şairlerden başka

gözlerindeki ışık gülümser

kalbi de var oyuncakların

oyuncakçının önünde bir çocuk ağlasa

bilirim hüzünlenir güleç yüzün

kulakların çınlar sunay akın.

derim ki şairlerdir yalnızca

yaratır tanrının unuttuğunu

aklından hiç çıkarmaz oysa

bir ozan sözcüklere yolculuğunu.

                                     08.2005', 'derler ki tanrıdır yalnızca yoktan var eder her cismi çirkin bir bedende oysa güzel bir ruh yaratır yüreğinden şair kısmi. tarifsiz bir hazl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Bayrakcı']::text[], 8.5, '{"poet":"Kemal Bayrakcı","poet_slug":"kemal-bayrakci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sunay-akin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakı Sofrasında Boşalan Tabure', 'raki-sofrasinda-bosalan-tabure-eren-caglar-niron-b80fd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sessiz bir vedaydi

aslinda ölümü

ama biz hoscakal derken

o duymadı

gormedigi gibi gozyaslarimizi.

peki ama simdi ben

kiminle agliyacagim

kiminle gulecegim

Raki sofrasinda...

Eren Çağlar Niron

2005', 'sessiz bir vedaydi aslinda ölümü ama biz hoscakal derken o duymadı gormedigi gibi gozyaslarimizi. peki ama simdi ben kiminle agliyacagim kim...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/raki-sofrasinda-bosalan-tabure-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Gibi Saldırırsam(FRENLE BENİ)', 'kurtlar-gibi-saldirirsam-frenle-beni-sahin-erturk-ik7un', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk iklimlerden sana geliyorum

Aşka susamış,kurumuş dudağım

Aç kurtlar gibi sana saldırırsam

Ne olur birşey yap,FRENLE BENİ

(10.03.2006)', 'Soğuk iklimlerden sana geliyorum Aşka susamış,kurumuş dudağım Aç kurtlar gibi sana saldırırsam Ne olur birşey yap,FRENLE BENİ (10.03.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kurtlar-gibi-saldirirsam-frenle-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '@@@ Vakitsiz Yağarım @@@', 'vakitsiz-yagarim-i-brahim-dikmen-2-ffx4q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer cesaretin varsa

Kaçma benden çık karşıma

Bir ömür sende kalırım

Benzemem başkalarına

@@@@@@@@@@@@

Adam gibi adam soyum

Senin olur varım yoğum

Sevgi yüklü bir yağmurum

Vakitsiz yağarım kalbine

Adam gibi adam soyum

Senin olur varım yoğum

Sevda yüklü bir yağmurum

Zamansız  yağarım şehrine

@@@@@@@@@@@@

Korkma benden adam yemem

Seviyorsan gel yürekten

Üç maymunu hiç oynama

Yakalarım gözlerinden

@@@@@@@@@@@@@

Adam gibi adam soyum

Senin olur varım yoğum

Sevgi yüklü bir yağmurum

Vakitsiz yağarım kalbine

Adam gibi adam soyum

Senin olur varım yoğum

Sevda yüklü bir yağmurum

Zamansız  yağarım şehrine

10/03/2006

Şarkı sözü olarak yazdım olumlu olumsuz eleştirilerinizi beklerim.

Aydınlı_İbrahim Dikmen', 'Eğer cesaretin varsa Kaçma benden çık karşıma Bir ömür sende kalırım Benzemem başkalarına @@@@@@@@@@@@ Adam gibi adam soyum Senin olur varım...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vakitsiz-yagarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Nerde Demokrasi?', 'hani-nerde-demokrasi-sahin-erturk-axaal', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Meydanlarda gören var mı? 

Söylemlerde gören var mı? 

Gören var mı,gören var mı? 

Hani nerde,Demokrasi? 

Kurumlarda gören var mı? 

Okullarda gören var mı? 

Gören var mı,gören var mı? 

Hani nerde,Demokrasi? 

Aydınlarda gören var mı? 

Yazarlarda gören var mı? 

Gören var mı,gören var mı? 

Hani nerde,Demokrasi? 

Sözde adı,özgürlükmüş

Her yerlerde konuşmazmış

Baskılarla susturulmuş

Hani nerde,Demokrasi? 

(10.03.2006) 

 KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Meydanlarda gören var mı?  Söylemlerde gören var mı?  Gören var mı,gören var mı?  Hani nerde,Demokrasi?  Kurumlarda gören var mı?  Okullarda...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hani-nerde-demokrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Beraber! ! !', 'hep-beraber-saim-bastik-oszxu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelin canlar, memleketi

Soyanlara yuh diyelim! 

Vatanseverlere kötü

Diyenlere yuh diyelim! 

Bitiripte derdi gamı

Saracak sandım yaramı

Allah deyipte haramı

Yiyenlere yuh diyelim! 

Altyapısı Tâlibandan

Hınç alıyor garibandan

Değiştim deyip Îmandan

Cayanlara yuh diyelim! 

Dost edinir puştu,piçi

Başkasına atar suçu

Hilâlin yerine haçı

Koyanlara yuh diyelim! 

Oğlum, kızım diye diye

Sahip çıktı bütün köye

Kul hakkını yiye yiye

Doyanlara yuh diyelim! 

HARÎMÎ, şu talancıya

Riyakara, yalancıya

TÜRK yerine yabancıya

Uyanlara yuh diyelim! 

09/03/2006', 'Gelin canlar, memleketi Soyanlara yuh diyelim!  Vatanseverlere kötü Diyenlere yuh diyelim!  Bitiripte derdi gamı Saracak sandım yaramı Allah...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hep-beraber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeseydim Yazarmıydım', 'sevmeseydim-yazarmiydim-yusuf-onder-bahceci-spgoo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni böyle sevmeseydim şiirler yazarmıydım,

Yazdığım şiirde, hep böyle kızar, kızarmıydım,

Yıllardır bekliyorum ölmüşüm sanki sağmıyım,

Seni böyle sevmeseydim şiirler yazarmıydım.

Yazdığım bu şiirleri okursan mutluluğum olur,

Bilmiyorum, bu sevdanın sonunda neler olur,

Önder çoktan ölmüş sanki sorgu sualmi olur,

Yazdığım bu şiirleri okursan mutluluğum olur.

Senin vefasız gözlerine takıldı, kaldı gönlüm,

Dedim ya asırlar oldu çoktan çoktan, öldüm,

Anladım sen beni hiç sevmiyorsun be gülüm,

Senin vefasız gözlerine takıldı, kaldı gönlüm.

Bir gün şiirleri, nefes almadan, okuyacaksın,

Her şiirde, hayret, hayret, hayret, diyeceksin,

İşte o zaman bileceksin, eyvahlar edeceksin,

Bir gün şiirleri, nefes almadan, okuyacaksın.', 'Seni böyle sevmeseydim şiirler yazarmıydım, Yazdığım şiirde, hep böyle kızar, kızarmıydım, Yıllardır bekliyorum ölmüşüm sanki sağmıyım, Seni...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmeseydim-yazarmiydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-erdal-ozkan-huc6b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beklerken gönlümce seven birini

Yenildim zamana,ağardı saçlar

Sabah üzerine çekti tülünü

Yorgun gözlerime çöktü akşamlar

Beklemek anladım bir hazin şarkı

Hayatın ölümden kalmadı farkı

Karanlık içimde bir garip korku

Bir sevda ateşi yaktı akşamlar

Çaresiz dünüm, umutsuz yarın

Bu günümün durağı hep acıların

Deliye çıkacak korkarım adım

Bu ismi bana taktı akşamlar', 'Beklerken gönlümce seven birini Yenildim zamana,ağardı saçlar Sabah üzerine çekti tülünü Yorgun gözlerime çöktü akşamlar Beklemek anladım bi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamlar-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zavallı', 'zavalli-yusuf-onder-bahceci-nodvk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zavallı, kurgulu oyuncaklar gibi, kurarsın oynar,

Zavallı sanki bir robot verdiğin komutlara uyar,

Sanki papağan duyduğunu iki kelimeyi söyler,

Zavallı, kurgulu oyuncaklar gibi, kurarsın oynar.

Zavallı at dersin atar, sat dersin hepsini satar,

Zavallı kuş tüyü yorganlar yatakda yatar, yatar,

Zavallı sonunu düşünmez haraç mezatla satar,

Zavallı at dersin atar, sat dersin hepsini satar.

Benim katım yok, yatım yok, villalarım hiç yok,

Benim şerefim ve haysiyetim, gayet pek çok,

Benim öte Dünya''ya götürecek bir şeyim yok,

Zavallı at dersin atar, sat dersin hepsini satar.

Babandan miras kalmışsa çok kolay satarsın,

Para her şey değildir be, sen kimi kandırırsın,

Topraklarım şehit kanıyla sulanmış utandırırsın,

Babandan miras kalmışsa çok kolay satarsın.', 'Zavallı, kurgulu oyuncaklar gibi, kurarsın oynar, Zavallı sanki bir robot verdiğin komutlara uyar, Sanki papağan duyduğunu iki kelimeyi söyl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zavalli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Tekrar Kavuşuruz', 'belki-tekrar-kavusuruz-hasan-i-yigun-fllun', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımdan keşke''leri attım

Geriye iyi ki''ler kaldı

İyi ki seni tanımışım

İyi ki seni sevmişim

Hayatımdan ama''ları attım

Geriye belki''ler kaldı

Belki beni affedersin

Belki tekrar sana kavuşurum

Sen de hayatından at bir tanem

Bütün keşke''leri, ama''ları at

Belki o zaman tekrar kavuşuruz

Belki...', 'Hayatımdan keşke''leri attım Geriye iyi ki''ler kaldı İyi ki seni tanımışım İyi ki seni sevmişim Hayatımdan ama''ları attım Geriye belki''ler ka...', ARRAY['Türk Edebiyatı','Şiir','Hasan İyigün']::text[], 8.5, '{"poet":"Hasan İyigün","poet_slug":"hasan-i-yigun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belki-tekrar-kavusuruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kârların Erimesini Bekleyeceğim', 'k-rlarin-erimesini-bekleyecegim-yusuf-onder-bahceci-45hbv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kârların erimesini bekleyeceğim, esrarlı gönlünde,

Zannetme seni unuttum, adın, adın, her an dilimde,

Güzel gözlerin aklıma gelir kendi kendime gülerim,

Biraz sonra üzülürüm kendi kendime neler ederim,

Kârların erimesini bekleyeceğim, esrarlı gönlünde,

Zannetme seni unuttum, adın, adın, her an dilimde...', 'Kârların erimesini bekleyeceğim, esrarlı gönlünde, Zannetme seni unuttum, adın, adın, her an dilimde, Güzel gözlerin aklıma gelir kendi kend...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karlarin-erimesini-bekleyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pınarlar Lağımdır Şimdi', 'pinarlar-lagimdir-simdi-zeynal-yaman-zpol1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlarım şu garip manzarayı dalınca seyre

Kalbimin içine bir hançer saplanır zehirden

Gece boyu sorular... Gözlerim takılır fecre

Bir ölüm iniltisi gelir hâmir-i mâyemden

Kimim ben? Sahi, biz kimiz? Bize böyle ne oldu? 

Her cevap zehirli bir akreptir ruhuma sokan

Kurumuş öz suyu yurdun gülleri açmaz oldu

Şimdi düşman lağımıdır pınarlarından akan

Artık biz bizde değiliz şimdi başka bizleriz

Her an yalana teslim her an yalanı izleriz

Şubat 87', 'Ağlarım şu garip manzarayı dalınca seyre Kalbimin içine bir hançer saplanır zehirden Gece boyu sorular... Gözlerim takılır fecre Bir ölüm in...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/pinarlar-lagimdir-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıkamış', 'sarikamis-kemal-bayrakci-9drru', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suratlarında bir kırbaç gibi şaklıyordu ayaz

Çocuktular yüreklerine ilk sevda düşmüştü o yaz.

Mahmut hasan musa kemal ökkeş ali yakup mustafa 

O an memet olup bindiler limandan demir alan vapura.

Horon teperken azgın dalgalar vardılar Trabzon’a

Zehirli bir engerek gibi çöreklenmişti soğuk Erzincan’da

Bir sevgili gibi dağların boynuna kollarını doluyordu patikalar

Toprağın ılık nefesini arıyordu delik postallardan ayaklar.

Girdiği gibi çıkmaz domdom kurşunu körpe teninden

Bedenindeki esaretten vazgeçer Memet vazgeçmez hürriyetinden.

Bastırdılar içlerinde özledikleri anların taze kokusunu

Söküp attılar ciğerlerinden bir habis gibi ölüm korkusunu.

Olmaz onların kabri nabızlarda atan birer anıttır

İstiklal ateşidir sönmez,içlerinde haykıran anttır.

Güneş firaridir ya da boğulmuş zemherinin kemendiyle

Yürüdüler damarlarındaki yangının peşinden kefenleriyle.

Bir karınca katarı gibi ağdılar dağların yamaçlarına

Tifüs aç kurt misali saldırıyordu yorgun vücutlarına.

Gümüşten kanatlarıyla kar yarin yüzünü getirirdi sıladan

İliklerine işledikçe beyazı, kavuşmaktı son dilekleri Tanrı’dan.

Çıkarıp kalbini koydu Nene Hatun erlerin torbasına azık

Öyle uzun sürmez toprağı kanla öpülen yerde karanlık

Halay çekercesine atıldılar türkücesine ölümün kollarına

Yürekleriyle yazdılar tarihi anaların dinmeyen gözyaşlarına.

.

Karın altında doksan bin yürek hala sımsıcak atıyor

Üstünde kardelenler,dolu dolu bir hayat mutlu yatıyor.

Ruhları küllenmez birer kordur Allah-u Ekber  tepesinde

Tüfekleri patlamaya hazır bekler asırlarca siperinde.

Arsız bir çocuk gibi tırmanıyordu mehtap gökyüzüne

Rüzgar bir şarapnel parçası gibi çarpıyordu yüzlerine.

Ölümün yakıcı soluğu okşasa da hummalı bedenlerini

Son nefesi çıkmadıkça yere düşürmez göğsündeki cevherini.

Her sabah yeniden dalgalanır umutları hayatın bağrında

İçli bir şarkıyı tutuşturur sıla hasreti ağızlarında.

Kurşun alınlarına bir ana busesi gibi sıcacık değince

Gözlerinde şavkıyordu sevdiklerinin yüzü ölmeden önce.

Ağlıyorum,gözlerime dalgası vuruyor beyaz hüznün

Kanatıyor süngüye benzeyen acısı bin dokuzyüz ondördün.

Kara kışında bıraktın Ey Asker açmadan baharını çırılçıplak

Anamızın ak sütü gibi helaldir koynunda yattığın toprak.

                                                                           Şubat-2006', 'Suratlarında bir kırbaç gibi şaklıyordu ayaz Çocuktular yüreklerine ilk sevda düşmüştü o yaz. Mahmut hasan musa kemal ökkeş ali yakup mustaf...', ARRAY['Türk Edebiyatı','Şiir','Kemal Bayrakcı']::text[], 8.5, '{"poet":"Kemal Bayrakcı","poet_slug":"kemal-bayrakci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sarikamis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Yatılı Okul (Öykü) -', 'yatili-okul-oyku-semsettin-kaya-8cshd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yatılı okula yazıldığım zaman on iki yaşındaydım. Ailemden uzakta, ortaokulun birinci sınıfına başlamıştım. Yazıldığım okul, köyümüze epey uzaklıkta bir şehirdeydi. Uzun süreli tatiller gelmedikçe eve pek gidip gelemiyordum. Hem maddi imkansızlıklar buna el vermiyordu hem de derslerimden geri kalarak bana umut bağlayan ailemi hayal kırıklığına uğratmak istemiyordum. Ama şehir yaşantısını da hiç sevmemiştim. Kendimi çok güçsüz ve yalnız hissediyordum. Araba gürültüleri, gizli bir endişe ve korku barındıran insan bağırışmalarını  üstümde bir ağırlık gibi hissediyordum. Çok yalnızdım. Sokaklarda yürürken her an başıma bir olay gelecek sanıyordum. Ailemi o kadar çok özlüyordum ki bazen her şeyi bırakıp köyüme gitmek istiyordum. Ama kendi kendime verdiğim sözler ve bir gün aileme ıspatlamak istediğim başarılarımı düşünerek bundan vazgeçiyordum. Kaldığım yatılı okulda sağlık koşulları çok kötüydü. Çok çeşitli yerlerden gelmiş yüzlerce çocuk bir arada yaşıyordu. Yedi ile on beş yaşları arasında  yüzlerce çocuk vardı. Çocukların çoğu taşradan, köy ortamından geldiği için şehirdeki çocuklar gibi temizlik alışkanlıklarını edinememişti. Okulun idaresi de her şeyi aynı anda düzeltmeye yetişemiyordu. Zaten yeteri kadar personel yoktu. Sular çoğu zaman kesik oluyordu. Öğrencilerin bir kısmı yıkanma fırsatı bulamıyorlardı. Sular, içi paslanmış depolarda korunmaya çalışılıyordu. Bütün bunların dışında okulda asayişi sağlamak, çocukların didişmelerine engel olmak, onca çocuğu kontrol altına almak ayrı birer sorundu. Kavga çıkmadan biten bir gece yoktu. Her sabah mutlaka birilerinin bir eşyası çalınıyordu. Çocukların neredeyse hepsi mutsuzdu. Kimisi kötü rüyalar gördükten sonra uyanıp ağlıyordu. Geceleri uykuda annelerini çağırıyorlardı. Anladığım kadarıyla hiç biri kendini güvende hissetmiyordu. Yatakhanelerde sürekli ağır bir koku vardı. Yıkanamayan çocuklar, gece altını pisleten yaşı küçük çocuklar ve bu çocukları yaşları küçük olduğu için ezmeye çalışan büyük yaştaki çocukların gürültüleri… Bir tavşan gibi uyumak zorundaydık. Her an birileri dolabını karıştırabilir yada biri gelip ayakkabını, battaniyeni alıp götürebilirdi. Sabahları kalkıp ayakkabısını yerinde bulamayan çocuklar oluyordu. Ağlaya ağlaya görevlilere giderlerdi. O gün ayağına uyan bir ayakkabı bulunduysa ne ala… Yoksa bütün günü çıplak ayakla geçirmek hatta derslere bu vaziyette katılmak zorunda kalırlardı. En kötüsü kış aylarında yataklarına gittikleri zaman battaniyenin yerinde yeller estiğini görmek olurdu. Bu yüzden kendimi tam anlamıyla uykuya bırakıp yeterince dinlendiğimi hatırlayamıyorum. Ders çalışmak için uygun bir ortam bulamıyordum. Her yer çocuk kaynıyordu ve sürekli bağrışma halindeydiler. O kadar çoktular ki seslerini birbirlerine ulaştırmak için bağırmak zorunda kalıyorlardı. Zamanla bu onlarda bir alışkanlık haline geldiği için artık gerekmediği yerlerde de seslerini yükselterek konuşuyorlardı. Geniş salonlarda bile sürekli bir uğultu vardı. Bu yüzden önceleri ders çalışmak konusunda epeyce sıkıntı çektim. Daha sonraları bu ortama alışmış olacağım ki artık pek rahatsız olmadan çalışmaya başlamıştım. Bütün bunların yanında okuldaki ders saatleri ayrı bir kabus gibi yaşanırdı. Sınıflar tıklım tıklım doluyordu. Her sırada üç yada dört kişi otururdu. Okulda yatılı kalanların dışında çevre mahallerden gündüzlü olarak okumaya gelen çocuklar da vardı. Bunlarla beraber sınıflarımızın mevcudu neredeyse iki katına çıkardı. Böyle bir ortamda ders işlemek çok zordu. Öğretmenlerimiz de bu durumdan bezmiş gibi görünüyorlardı. Derslere isteksizce girdiklerini yüzlerinden okuyabilirdiniz. Bütün bu kalabalığın içinde kendimi kaybolmuş gibi hissediyordum. Sahip olduğum bilgileri ve yeteneğimi ortaya çıkarmak için bir türlü fırsat bulamıyordum. Öğretmenler ders boyunca konu anlatmaktan çok öğrencilerin sessiz olmalarını sağlamaya çalışıyorlardı. Böyle bir ortamda hiç kimsenin yaşadığı şeyden dolayı mutlu olabileceğini sanmıyorum. Öğretmenler de öyleydi. Bir zamanlar sahip oldukları idealist düşüncelerini, heyecanlarını kaybetmiş gibi görünüyorlardı. Onlar da bir an önce böyle bir yerden kurtulma çabası içindeydi düşündüğüm kadarıyla… Geceleri yatakhaneme geldiğim zaman o kadar yorgun hissediyordum ki kendimi, ayakta duracak hal bulamıyordum. Zayıf olan bünyemden dolayı diğer çocuklara göre daha bitkin oluyordum. Yatağıma bir an önce uzanıp dinlenmek istiyordum. Oysa duygularım farklı şeyler istiyordu. Aslında heyecanlı bir çocuktum. Sürekli konuşmak gülmek bir şeylerden söz etmek istiyordum. Ama içinde bulunduğum ortam bu isteklerimi yaşamak için uygun olmaktan çok uzaktı. Çocukların konuştuğu konular farklıydı. Daha doğrusu hiç bir şey konuşmuyorlardı, sürekli didişiyorlardı. Bu yüzden kendimi daha çok yalnız hissediyordum. Kimseyle ilişki kuramıyordum. Bunu belki de ben istemiyordum. Yalnız kalmak her ne kadar acı verici olsa da bunu ben tercih ediyordum. Böylece aylar geçti. Bu süre içinde yalnızlığımı giderecek yeni buluşlar aramaya başladım. Önceleri bir radyo almayı düşündüm. Ailemin verdiği az miktardaki parama kıyamamama rağmen dışarıya çıkabildiğim ilk hafta sonunda bir seyyar satıcıdan küçük bir el radyosu aldım. Bu çok hoşuma gitmişti. Köydeyken de evde hep radyo dinlerdim. Okula geldiğimden beri radyo dinleyememiştim. Böyle bir karar verdiğim için kendi kendimle gurur duymuştum. Bu arada radyo dinlemeyi ne kadar çok özlediğimi anladım. Çok mutlu olmuştum. Heyecanla okula geri dönüp bulduğum ilk kuytu köşede radyomu açıp dinlemeye başladım. O gün yalnız kalmayı o kadar istiyordum ki okuldaki çocuklara rastlamamak için köşe bucak kaçıyordum adeta… Kimsenin gitmediği gölgelik kuytu yerlere gidiyordum. Ders aralarında dışarı çıkmıyor, sınıfta cebimde taşıdığım radyomu çıkarıp dinliyordum. Akşamları yatmadan önce kulaklıklarını takarak dinliyordum. Çoğu zaman radyomu kapatmadan uykuya dalıyordum. Sabah uyandığımda pilleri bitmiş vaziyette buluyordum onu. Artık kendimi eskisi gibi yalnız hissetmiyordum. Köydeyken dinlediğim programları burada da dinleyebiliyordum. Bu bana aynı zamanda aileme yakın olduğum hissini veriyordu. Sanki onların yanındaymışım gibi hissediyordum. Bu yüzden eskiye göre daha iyi hissediyordum kendimi. Ama bu pek uzun sürmedi. Yine radyomu kapatamadan uykuya daldığım bir geceden sonra sabah uyandığımda radyomun yerinde yeller esiyordu. Yatağımı büyük bir titizlikle aramama rağmen bulamamıştım. Radyom çalınmıştı. Yatakhanede yatanlara doğru baktım. Ve bütün hiddetimle; 

-Radyomu kim aldı..? diye bağırdım. Herhalde böyle bir sesi benden ilk defa duymuş olacaklar ki bütün çocuklar bir anda susup bana doğru baktı. Çok kötüydüm. Ne yapacağımı bilemiyordum. Bir defa daha bağırsam aynı sesi çıkaramayacaktım. Üstelik ağlayacaktım. Kimin yaptığını hiç kimse bilmiyordu. Kimi suçlayacağımı bilemiyordum. O kadar çok çocuk vardı ki… Bunu gidip görevlilere anlatmak istemedim. “Okula elektronik eşya  getirmeyin diye uyarmıştık biz sizi” diye cevap vereceklerdi. Bu bana hiçbir şey kazandırmayacaktı. Yatağımdan kalktım. Ve bütün dolapları arayacağımı söyledim. Kimse itiraz etmedi. Sonra mahçup oldum. Vazgeçtim. Yatağıma gidip oturdum ve ağladım. Neden insanlar başka insanların mutluluklarını yaşamalarına engel oluyorlardı? Bir türlü tahammül edemiyordum. Neden mutlu bir insanın mutluluğunu başka bir insan bozmak istiyordu? Neden kötülük yapmak istiyordu insanlar? 

Yine eski yalnız günlerime geri dönmüştüm. Birkaç gün süren keyifli zamandan sonra her şey eskisi gibi olmuştu. Öteki çoğunluk beni kendine benzetmeyi başarmıştı. Bir daha radyo almamaya karar verdim. Aynı şeyi bir daha yaşamak istemiyordum. Ama bunun yerine başka bir alternatif bulmam gerekiyordu. Benim için uzun geçen bir süre böyle bir boşlukta yaşadım. Sadece derslere giriyordum. Ayaküstü konuştuğum birkaç çocuk dışında kimseyle iletişim kurmuyordum. Akşam olunca da yatağıma çekiliyor, hiç alışık olmadığım halde erken uyumaya çalışıyordum.

Bir gün Türkçe dersimiz esnasında öğretmenim aklıma çok güzel bir fikir getirdi. Okulumuzda bir kütüphane varmış. Ben dahil neredeyse hiç kimsenin bundan haberi yoktu. Haberi olsa bile kimsenin umurunda olduğunu sanmıyorum. Bu yüzden kütüphane unutulup gitmişti. Öğretmenlerin bile onca sorunun içinden akıllarına gelebileceğini sanmıyorum. Ta ki tesadüfen bir derste Türkçe öğretmenimizin aklına gelene kadar… Buna çok sevindim. İlk ders arasında yerini keşfetmeye gittim. İdare bölümünün arka kısmında kapısı kilitli bir bölüm vardı. O kadar az kullanılmış olmalıydı ki kapısı bile pas tutmuştu. Kapısı kilitli olduğu için içeri girememiştim. Dersten hemen sonra Türkçe öğretmenimi bulup kapısını açtırmasını istedim. Kütüphaneyle ilgilenmeme öğretmenim şaşırmış olacak ki; 

-Adın ne senin? Dedi. O gün anladım ki Türkçe öğretmenim adımı o güne kadar öğrenememişti. Bu beni biraz üzdü ama sınıflarımızın durumunu düşününce ona da biraz hak verdim. Ayrıca derslerde ben de kendimi gösterme fırsatı bulamamıştım. Ama bu bir başlangıç sayılabilirdi; 

-Adım Kemal öğretmenim. Kitaplara bakabilir miyim? Belki okumak için güzel kitaplar vardır diye düşünmüştüm. Dedim.

-Elbette, kitaplara ilgi duyuyor olmana sevindim. Öyle öğrencilere pek rastlanmaz buralarda… Sen burada biraz bekle ben anahtarı bulmaya çalışayım. Deyip odadan çıktı. Bir süre sonra elinde bir anahtarla geldi ve beraber kütüphaneye doğru gittik. Böyle bir olay karşısında öğretmenim etkilenmiş olmalıydı ki benimle beraber kütüphaneye gelme zahmetine bile girmişti. Kilitli kapıyı açtıktan sonra karanlık ve uzun bir salona girdik. Işık az olduğu için içerisini pek göremiyordum. Gözlerim biraz alıştıktan sonra raflarda dizili kitapları gördüm. Bir sürü kitap vardı. Öğretmenimin yardımıyla iki tanesini seçip aldım. Sonra çıktık. Öğretmenim hala inanamıyordu; 

-Bu kitapları okuyacaksın değil mi Kemal? Götürdükten sonra okumadan geri getirme. Dedi. 

-Elbette okuyacağım öğretmenim. Bitince yenisini alabilir miyim? 

-Bitince kitapları bana getir, ben sana yeni kitap veririm dedi. Bana verilen kitapları not aldıktan sonra teşekkür ettim ve ayrıldım. O günden sonra  bütün ders aralarında, ve bulduğum her uygun zamanda kitap okumaya başladım. Akşam oldu mu yatakhaneye erken çıkar yatağımda uyuyana kadar kitap okuyordum. Bu beni bir sürü kötü duygudan uzaklaştırıyordu. Aileme duyduğum özlemi bir nebze unutuyordum. Kitaplarda özlem duyduğum yerleri, beraber yaşamak istediğim insanları bulabiliyordum. Merak ettiğim bir çok yer ve konu hakkında bilgi sahibi oluyordum. Aynı zamanda bir sürü dost ediniyordum kitaplardan. Kendimi artık yalnız hissetmiyordum. İyi yürekli roman kahramanı arkadaşlarım vardı. Gitmediğim halde her tarafını dolaşmış gibi bildiğim ülkeler vardı. Oradaki insanları tanıyordum. Alışkanlıklarını, sevdikleri şeyleri ve en güzel yönlerini biliyordum. Kimi zaman oradaki köylülerle beraber bahçelerde çalışıyor, kimi zaman iyi insanları kötülüklerden korumaya çalışan bir kahramana yoldaşlık ediyordum. Günler nasıl geçiyor bilmiyordum. Derslerime de zaman ayırıyordum. Türkçe öğretmenim beni artık çok iyi tanıyordu. Bana bakarken diğer öğrenciler içinde özel bir yere sahip olduğumu hissedebiliyordum. Kitaplarım bittikçe onun yardımıyla yeni kitaplar alıyordum. Hatta öyle çok okuyordum Türkçe öğretmenim bazen; 

-Bu gidişle kütüphanemizi büyütmemiz lazım Kemal, sen buradaki kitapları yakında bitirirsin. Diyordu. Okuldaki diğer bütün keşmekeşin çok dışına çıkmıştım. O kadar uzaklaşmıştım ki çocuklar bile beni unutmuş gibiydiler. Kendi aralarında didişirlerken beni görmezlerdi bile…Bir gölge gibi yaşıyordum aralarında. Ama asıl yaşadığım yerler onların çok uzağında ve onların asla tahmin edemeyeceği kadar güzel yerlerdi. Bunu onların da bilmesini çok isterdim. Ama o kadar uzaktılar ki… O kadar ilgisizler di ki… Onların konuştuğu konular bana o kadar sıradan, gereksiz ve basit geliyordu ki… Çoğu zaman bu konular yüzünden kavga ediyorlardı. Ne kadar üzücüydü…

Havalar soğumaya başlamıştı. Yatakhanelere birer battaniye daha konulmuştu. Öğretmenlerimiz battaniyelerimize sahip çıkmamızı tembihliyorlardı. Zayıf bünyemden dolayı daha dikkatli davranıyordum. Kalın giysiler giymeye özen gösteriyordum. İlk zamanlara göre okula daha çok alışmıştım. Derslerim de iyiydi. Özellikle Türkçe öğretmenimle diyaloğum çok iyiydi. Eskisi kadar tanınmadık bir çocuk değildim. Bu arada epeyce kitap okumuştum. Kitap almak istediğim zaman Türkçe öğretmenim kütüphanenin anahtarını artık bana veriyordu. Tek başıma giderek istediğim kitapları seçip alabiliyordum. Okulun ilk döneminin yarısı bitmişti. İlk dönemi başarıyla bitirip elimde güzel bir karneyle köyüme gitmeyi hayal ediyordum. Annem beni kapıda karşılayacaktı. Sımsıkı sarılacaktım ona. Benimle gurur duyacaklardı. Kardeşlerime örnek olacaktım. Tatil boyunca bütün özlemlerimi giderecektim. Bol bol radyo dinleyecek, ailemle sohbet ederek vakit geçirecektim. Bunları düşündükçe zamanın bir an önce geçmesi için dua ediyordum. Bir yandan da hayalimdeki gibi bir karneyle eve gitmek için daha çok çaba gösteriyordum. Kendimi okuduğum kitaplardaki kahramanlar gibi görüyordum. Güzellikler için zorluklara katlanan ve mücadele etmekten korkmayan, yılmayan kahramanlar gibi… Bir gün eve dönüp sevdiklerimin yüzünü güldürecektim.

Bir gece yine yatağımda uzanmış kitap okuyordum. Yatmak için henüz erken idi. Biraz daha kitap okumak istiyordum. Ama ansızın başıma bir ağrı saplandı. Biraz sonra geçer diye hiç dikkate almamıştım önceleri. Ama zaman geçtikçe başımın ağrısı şiddetleniyordu. Kitap okumayı bırakıp yüzümü yıkamaya gittim. Yatağıma dönüp tekrar uzandım ama hiçbir faydası yoktu. Başımın ağrısı çok kötü bir hal almıştı. O saatte kimseyi rahatsız etmek istemiyordum. Çocukların çoğu uyumaya başlamıştı bile…Yatağımda kıvranıyordum. Bitmesi için dua ediyordum. Bir yandan da başka şeyler düşünmeye çalışıyordum. Ama bir türlü acının önüne geçemiyordum. O saatte okulda nöbetçi bir iki görevli olurdu. Onlar da öteki binada bulunan idare kısmında olmalıydılar. Oraya gidecek kadar güçlü hissetmiyordum kendimi. Sabaha kadar dayanmaya karar verdim. Hayatımda bu kadar acı hissettiğimi hatırlamıyordum. Ter içinde kalmıştım. Başım patlayacak gibiydi. Bütün bunlara rağmen sesimi başka çocuklara duyurmamaya çalışıyordum. Ve çok acı çekiyordum. 

Sabaha kadar dayandım. Hiç uyumamıştım. Ama o yaşıma kadar yaşadığım en büyük acıyı yaşamıştım. Sabah şafak söker sökmez idareye gittim. Türkçe hocamı bulmak istiyordum. Ama bulamadım. Baş ağrısının yanında mide bulantısı da başlamıştı. Ayakta duracak halim yoktu. Bulduğum ilk öğretmene durumu anlattım. Beni öğretmenler odasına aldı. Ve görevli hemşire gelene kadar orada beklememi söyledi. O kadar çok acı çekiyordum ki buna katlanabileceğimi hiç sanmıyordum. Öğretmen beni bırakıp dışarı çıktı. Odada yalnız kaldım. Kusmak istiyordum. Bin bir güçlükle tuvalete kadar gittim ve kustum. Sonra bir çocuğun yardımıyla yerime geldim. Odada o halde epeyce bekledim. En sonunda dayanamayıp kendimi yere bıraktım. Çok kötüydüm. Bir süre sonra bir öğretmen kapıyı açtı. Yerde yattığımı görünce beni azarladı; 

-Kalk koltukta otur, başka yer bulamadın mı yatmak için? Dedi.

-Çok hastayım öğretmenim? Dedim.

-O zaman hemşireye git. Dedi. Ona, beni buraya başka hocanın bıraktığın hemşireyi beklememi söylediğini anlatmaya çalıştım. 

-Pekiyi o zaman şu koltukta otur hemşire gelince gidersin. Deyip gitti. Bir süre daha öylece kaldım. Öğle saatlerine doğru hemşire odaya geldi. Beni inceledi ve okuldaki hizmetlilerden biriyle beraber hastaneye gönderdi…

Hastanede uzun bir süre sıra bekledikten sonra doktora göründüm. Ayaküstü yapılan muayenede yüzümdeki sarılığa bakan doktor; 

-Bu çocuk sarılık…dedi. Reçeteye birkaç ilaç yazdıktan sonra bizi geri gönderdi. Okula geri getirildim. Hiç yemek yiyemiyordum. İlaçlarımı almak için meyve getirdiler. Meyveleri büyük zorlukla yedikten sonra ilaçlarımı içtim. Sonra gidip yatağıma yattım. Ama acı bir türlü geçmiyordu. Üstelik başım da dönüyordu. Canım hiçbir şey istemiyor gözlerim kararıyordu. Çocuklar derslerine gittiler. Yanımda kimse kalmadı. Yatakhanede bir başıma kaldım. Uzun bir süre mücadele ettim. Ama bir türlü gelişme olmuyordu. En sonunda idareye tekrar gitmeye karar verdim. Bin bir zorlukla yatakhanemin kapısına çıktım. Bir süre sonra oradan geçen bir çocuktan yardım istedim. Uzun bir uğraştan sonra idare binasına kadar gittik. Oradaki öğretmenlere iyi olmadığımı daha da kötüleştiğimi söyledim. Durumu gören öğretmenler beni tekrar hastaneye göndermeye karar verdiler. Bir daha yola çıktık. Akşamüzeri hastaneye vardık. Bu defa acil girişinden hastaneye girdik… Ancak hastanede nöbetçi doktor dışında kimse yoktu. Bana bir iğne yaptılar. Nöbetçi doktor durumun ciddi olabileceğini söyleyerek bizi başka bir ilde bulunan büyük bir hastaneye sevk edeceğini söyledi. O akşam, içinde başka yaralıların da bulunduğu bir ambulansla yola çıktık. İki saatlik yol boyunca o kadar acı çektim ki öleceğimi düşünmeye başladım. Yolda defalarca kustum. Midemde hiç bir şey kalmadığı için beyaz bir sıvı çıkıyordu sadece. Gözlerim artık hiçbir şey göremiyordu. Başım dönüyor ve patlayacak kadar ağrıyordu. Hastaneye ulaştığımızda gece olmuştu. Beni hemen nöbetçi doktorlara götürdüler. Gerekli tetkikler için kan alındı. Koluma bir serum takıldıktan sonra bir odaya yatırdılar. Gerisini hayal meyal hatırlıyorum. O geceyi öyle geçirdim. Sabah uyandığımda kendimi biraz daha iyi hissediyordum. Kolumdaki serumun etkisi olabilir diye düşündüm. Ama hala çok kötüydüm. Yanımda kimsecikler yoktu. Okuldan benimle beraber gönderilen görevli etrafta yoktu. Sonradan öğrendiğim kadarıyla geceyi bir yakınının evinde geçirmişti. Saat dokuz gibi doktor geldi ve tetkiklerimi incelediklerini, hastalığımın tifo olduğunu söyledi. Hastaneye çok geç geldiğimizi biraz daha gecikseymişiz hastalığın daha kötü sonuçlara neden olabilecek dereceye geldiğini anlattı. Daha önce bana hastalığıma konulan teşhis yanlış çıkmıştı. Doktor burada bir süre yatmam gerektiğini söyledikten sonra gitti. Bir süre sonra okul tarafından görevli olarak gönderilen kişi geldi. İlgililerden hastalığım ile ilgili bilgiler aldıktan sonra tekrar gitti ve akşama kadar gelmedi. Gece gelir diye düşünüyordum. Ama gece de gelmedi. O gün akşama kadar bir sürü ilaç içirdiler, iğneler yapıldı. Akşama doğru ağrılarım biraz azaldı ama hala başım dönüyor, yemek yiyemiyordum. Ayakta duramadığım için tuvalete odamdaki başka hasta yakınlarının yardımıyla gidiyordum. O gece nasıl geçti bilmiyorum. Ertesi gün öğleye doğru görevli yine geldi. Bu defa benimle konuştu. Ona iyi olduğumu söyledim. Ailemin hastalığımı duymamasını, beni okulda bilmelerini, bunun için okulumu aramasını ve uyarıda bulunmasını istedim. Adam bana okulu arayacağına dair söz vererek tekrar gitti. Ailem hasta olduğumu, hele ki başka bir ile nakledildiğimi ve orada hastanede yattığımı öğrenirlerse  çok kötü olacaklarını biliyordum. Babam kendini parçalardı üzüntüden. Onca yokluk içinde kalkıp hastaneye kadar geleceklerdi. Bir sürü üzüntü ve bir sürü masrafa sebep olacaktım. Onların üzülmelerini istemiyordum. Benim bütün hayallerim onları sevindirmekle ilgiliydi. Onlar, benim okuldan elimde başarılı bir karneyle eve dönmemi bekliyorlardı. Benimle gurur duyup kardeşlerime örnek göstereceklerdi. Düştüğüm bu durumu onlar görmemeliydi. Ben de çok üzülürdüm. Adam gittikten sonra yine yalnız kaldım. İlk dört günüm öylece geçti. Dördüncü gün yattığım odaya tanımadığım bir bayan ve erkek geldi. Adımı sordular. Şaşkınlıkla “benim” dedim.; 

-Merhaba Kemal. Çok geçmiş olsun. Biz senin akrabalarınız. Burada yaşıyoruz. İkimiz de burada öğretmenlik yapıyoruz. Okulunun yöneticileri bir akrabanı aramışlar, onlar da bizi aradı. Seninle ilgilenmemizi istediler. Biz de duyar duymaz hastaneye geldik. Bak yengen sana kitap getirmiş, onları da yatarken okursun. Dediler. Buna çok sevinmiştim. Özellikle kitaplara çok sevindim. Yanımda bir süre oturdular. Onlarla ilk defa tanışıyordum. İyi insanlardı. Onlardan durumu aileme bildirmemeleri konusunda söz aldım. Sonra izin isteyip ayrıldılar. Onlar gittikten sonra hemen kitapları okumaya başladım. İki gün boyunca bu kitapları okuyarak vakit geçirdim. Görevli adam iki gün boyunca gelmedi.  Durumum ilk güne göre biraz daha iyiydi. Yoğun bir ilaç tedavisi görüyordum. Üçüncü gün görevli bir daha geldi. Doktordan benimle ilgili bilgiler aldı. Sonra yanıma geldi; 

-Kemal ben bugün okula dönüyorum. İdareden çağırmışlar beni… Sen hastaneden çıkınca buradaki akrabaların gelip seni alacakmış. Doktorla konuştuk. Bu arada okula dönersen eğer, benim hastaneden sık sık ayrıldığımı söyleme olur mu? Sorarlarsa hep yanımdaydı dersin. Arada bir ihtiyaç oldu mu dışarı çıkar, sonra hemen geliyordu dersin. Olur mu? 

-Olur söylerim. Dedim. Sonra adam çekip gitti. Aradan iki gün geçti, sonra akrabalarım tekrar geldiler. Bu defa kitap getirmemişlerdi. Okuduğum kitapları onlara geri verdim. Yanımda bir süre oturdular. Hastaneden çıkınca beni alacaklarını ve eve göndereceklerini söyleyip gittiler. Yine yalnız kaldım. Bu defa kitap da yoktu. Zaman geçmek bilmiyordu. Dışarıyı o kadar özlemiştim ki… Ama hala ayakta tek başıma duramıyordum. Yaklaşık on gün geçmişti. Derslerimden çok geri kalacağımı düşündükçe üzülüyordum. Artık o hayal ettiğim karneyi alamayacaktım. Doktorlar uzun bir süre hastanede kalacağımı söylüyorlardı. Yanımda artık kimse kalmamıştı. Aynı odada bulunduğum hasta yakınları yardım ediyordu çoğu zaman. Odada bulunan diğer hastaların yanında sürekli yakınları dururdu. Meyveler, hediyeler getirirlerdi. Böyle durumlarda kendimi o kadar yalnız ve incinmiş hissediyordum ki… Bazen getirdikleri meyvelerden bana da getirip ikram ediyorlardı. Yemek istemiyordum. Çünkü bana acındığını hissediyordum. Meyve yerken bana dönüp baktıkları zaman yüzlerinde gördüğüm ifade beni incitiyordu. Bu nedenle hastaneden çıkacağım günü iple çekiyordum.

Bir gece aniden bir çığlık sesiyle uyandım. Odamdaki insanlar bağıra çağıra hastalarını kollarından tutup aşağı indiriyorlardı. Koridorda da aynı kargaşa vardı. Her taraftan insan sesleri geliyordu. Herkes panik içinde merdivene doğru kaçıyordu. Daha ne olduğunu anlayamadan odamda kimse kalmamıştı. Yapayalnız kalmıştım. Kolumda serum vardı. Koridorlardan hala insan sesleri geliyordu. Aşağıya doğru kaçıyorlardı. “Yangın var” diye bağıran bir ses duydum. Durumu anladığımda yanımda kimse kalmamıştı artık. Ne yapacağımı bilemiyordum. Çok halsizdim. Yatağımda doğruldum. Başım döndüğü için tekrar uzandım. Ne olacaksa olsun diye geçirdim içimden. O kadar yalnızdım ki halime ağlamak geldi içimden. Gözlerim doldu. Kalkıp kaçabilsem, ben de kaçacaktım ama kendimde o gücü bir türlü bulamadım. Koridorlardaki uğultu azaldı. Herkes dışarı kaçmıştı. Belki de birazdan yanarak ölecektim. Ne kadar kötü bir şeydi. Ne hayaller kurarken başıma neler gelmişti. Üstelik hastalıktan kurtulmak için geldiğim hastanede bir odada yapayalnız yanarak ölecektim. On iki yaşımdaydım daha… Annemi düşündüm. Beni okulda biliyordu. Eve döneceğim günü iple çekiyordu. Babam her ne kadar annem kadar duygularını açığa vurmasa da beni çok özlediğini biliyordum. Ben de çok özlemiştim onları… Bütün gücümü kullanarak doğruldum ve yatağımdan indim. Ama ayakta duramıyordum. Kolumdaki serumu askıdan indirdim bir elime aldım. Öbür elimle de emekleyerek kapıya kadar gittim. Belki biri beni orada görür de yardım etmek ister diye düşündüm. Ama kimse yoktu. Bağırsam sesimi duyamayacak kadar uzaktaydılar. Dışarıdan öyle bir uğultu geliyordu ki sesimi hiç kimse duyamazdı. Başım dönüyordu. Merdivenden aşağı doğru emekleyerek inmeye başladım. Ama bir kat bile inemeden merdiven boşluğunda hareket edemez hale geldim. Orada kendimi bıraktım. Ne olacaksa olsun dedim içimden. Kolumdaki serumu artık taşıyamayacağım için yere bıraktım. Ve damarımdaki kanlar serumun içine dolmaya başladı. Yapacak bir şeyim yoktu artık. Öylece bekleyecektim. Yarı baygın vaziyette ne kadar bekledim bilmiyorum. Bir süre sonra insan sesleri gelmeye başladı. Binaya giriyor olmalıydılar. Alt koridorlardan sesler geliyordu. Gözlerimi kapattım. Kısa bir süre sonra odamda yatan hastanın yakını olan kadın geri dönerken beni orada uzanmış vaziyette bulunca; 

-Aaa çocuk burada kalmış. Nasıl aklımıza gelmedi? 

-Buraya kadar nasıl geldin Kemal? Aman Allah’ım serum şişesi kan dolmuş! Yazık, kimsesi olmayınca ortada kaldı. Nasıl aklıma gelmedi. Deyip beni kolumdan tutup doğrulttu. Serum şişemi eline aldı ve başka kişilerin de yardımıyla yatağıma kadar taşıdı. İnsanların beni bu kadar acınacak bir durumda görmelerini hiç istemiyordum. Gördükleri kadar çaresiz olmadığımı göstermek istedim; 

-İstesem inebilirdim ama seslerinizi duyunca vazgeçtim. Dedim. O günden sonra iyice içime kapandım. Kimseyle yüz yüze gelmek istemiyordum. Düştüğüm durumdan utanmıştım. Hastalığım bir an önce iyileşse de çıksam diye dua ediyordum. Yavaş da olsa sağlığım iyiye doğru gidiyordu. Artık hastaneden çıkıp evime gideceğim günden başka bir şey düşünmüyordum. Hastanede yaklaşık bir aydır yatıyordum. Bana kitap getiren akrabalarım bir defa daha ziyaretime gelip gitmişlerdi. Artık zamanın geçmesini bekliyordum. Sabahları hastanede verilen kahvaltıdan sonra ilaçlarımızı içiyorduk. Sonra doktorlar hastaları gezerek durumlarına bakıyorlardı. Derken öğle yemeği çıkar. Herkes yemek yer, sonra akşam olmasını beklerdik. Bir gün doktorlar kontrollerini yapıp çıktıktan sonra yattığım odanın kapısı birden açıldı. Ve karşımda babamı gördüm. Hiçbir şey diyemedi. Sonra bir çığlık attı. Babamı ilk defa böyle görmüştüm. Çocuk gibi ağlayarak gelip boynuma sarıldı; 

-Of of oğlum. Dedi. Başka bir şey diyemiyordu, ağlıyordu. Sonra nefesini toplayarak; 

-Neden haber vermedin oğlum. Haberim olsaydı…. Sonra yine ağlamaya başladı.

-Tamam baba, ben çok iyiyim. Neden geldin? Zaten birkaç güne kadar gelecektim ben. Kim haber verdi sana? 

-Bırak bunları şimdi oğlum. Seni o lanet okula göndermeseydim keşke… Neler geldi başımıza. Küçücük çocuk uzak yerlerde… Nasıl düşünmedim..? 

-Baba abartma, herkes gibi ben de hastalandım ve iyileşiyorum. Evde de olsam belki hastalanırdım. Olacağı oymuş. Tamam artık. Bak ben iyiyim.

Babamın geleceğini bilmiş olsaydım. Önceden kendimi toparlardım. Beni böyle bitkin görmesine izin vermezdim. Ama ansızın gelmiş, kendimi yatağa halsiz bir vaziyette bıraktığım anda odaya girmişti. Arkasında da bana kitap getiren akrabalar vardı. Onlara doğru sert sert  baktım. Bu nedenle akrabam söze girme gereği duydu; 

-Kemal’cim memleketteki akrabamız, sen nasıl olsa iyi oldun diye babana haber vermiş. Hem gelip seni görsün, hem de babanla beraber köyünüze geri dönersiniz diye düşünmüş. Bizim de haberimiz yoktu. Baban bu sabah geldi. Merak etme biz ona her şeyi anlattık. Bizim misafirimiz olacak. Zaten doktorların iki gün içinde çıkacağını söylüyorlar. Üzülecek bir şey yok. Diye uzun bir konuşma yaptı. 

Bu arada babama daha dinç görünme çabasıyla kalkıp yatağıma oturdum. Yerimden kalkıp kapıya kadar gidip geldim. İyi olduğum konusunda onu inandırmaya çalışıyordum. Annemi kardeşlerimi sordum. Hepsi hastalandığımı duymuş çok üzülmüşler. Annem ağlamış. O da gelmek istemiş. Çocuklar küçük diye gelememiş.

-Baba hepiniz buraya gelmeyin, üzülmeyin diye size hasta olduğumu söylemedim zaten. Ne kadar üzüleceğinizi ve neler yapacağınızı biliyordum. Neyse iyileştim artık. Yakında beraber köye gideriz artık. Dedim. Ziyaret saatinin bitimine kadar yanımda oturdular. Sonra akrabalarımda kalmak üzere yanımdan ayrıldı. Sabah yine geleceğini söyledi ve gittiler. Babamın gelişine ve beni o halde görüp düştüğü durumdan dolayı çok üzülmüştüm. Ama bir yandan da gizli bir sevinç hissediyordum. Odamdaki hasta yakınlarına düşündükleri kadar yalnız olmadığımı göstermiş oluyordum. 

Ertesi gün babam yine hastaneye geldi. Uzun bir süre yanımda kaldı. Bir sürü meyve ve çikolata getirmişti. Sanki hastaneye gelemediği günlerin acısını çıkarıyordu. Getirdiği onca şeyi yiyemezdim. Ama öteki hastalara benzemeye başlamıştım. Benim de komidinimin üstünde bisküviler, çikolatalar ve meyveler vardı artık. O gün de babam akrabalarda kalmaya gitti. Akşamüzeri hemşireler yarın taburcu olacağımı söylediler. Buna çok sevindim. Zaten son iki gündür kendi işlerimi kendim görecek duruma gelmiştim. Ayağa kalkıp dolaşabiliyordum.

 O geceyi nasıl bitirdim bilemiyorum. Sabaha kadar heyecandan uyuyamadım. Ve nihayet sabah oldu. Kahvaltı ve son kontrolden sonra babam akrabalarımla beraber geldi. Yüzlerinde bir sevinç vardı. Ben de çok mutluydum. Babam; 

-Oğlum, Edip amcan bizi arabasıyla götürecek. Dedi. Bu çok güzel bir haberdi. Yolda zorluk çekmeyecektik. Hastane işlemlerimi bitirdikten sonra uzun bir zamandır giymediğim elbiselerimi giydim. Çok zayıflamış olduğumu o zaman anladım. Pantolonum epeyce genişlemişti. Üstümden düşecek gibi duruyordu. Babama bunu belli etmeden kemerimi sıktım ve eşyalarımızı alıp hastaneden çıktık. Dışarıya ilk çıkışım yeniden bir doğuş gibiydi. Kış mevsimi olmasına rağmen hava açık ve güneşliydi. Güneşin ışıkları o kadar keskindi ki gözlerimi alamıyordum. Temiz hava solumayı o kadar özlemiştim ki defalarca derin derin nefes aldım. Sonra babamdan bana bir simit almasını istedim. Hastanenin önündeki küçük parkta bir süre oturduk. O kadar güzeldi ki her şey… Yaşamak ne güzel diye düşündüm. Bu arada akrabalar da doktorun yazmış olduğu ilaçları almış gelmişlerdi. Sonra hep beraber arabaya binip yola koyulduk. Şehrin içinden etrafı seyrede seyrede geçtik. Buraya hastane için geldiğim geceyi düşündüm. Bir kabus gibiydi. Bir daha hatırlamak istemiyordum o geceyi. Ve biraz sonra şehir geride kaldı. 

…

Okul okuduğum şehre yaklaşıyorduk. Aynı zamanda evime de yaklaştığımı hissediyordum. Çok heyecanlıydım. Ama içim biraz buruktu. Anneme hayal ettiğim gibi dönmeyecektim. İstediğim gibi olmayacaktı. Bu yüzden üstüme bir hüzün çökmüştü. Düşüncelere dalmıştım. Bu arada okul okuduğum şehrin ilk evleri görünmeye başlamıştı. Arabayı süren akrabam bana dönerek; 

-Kemal’cim, geçerken senin okula da uğrayıp hastaneden çıktığını bildirelim, izin işini de halledip yolumuza devam edelim. Dedi. Ben okula gitmek istemiyordum. Bir an önce evime yetişmek annemin kucağına atlamak istiyordum. Ama akrabamın dedikleri doğruydu.

-Olur. Dedim hoşnutsuz bir tavırla… Bir süre sonra araba okulumuzun bahçesine girdi. Ve üçümüz arabadan indik. Çocuklar azalmıştı sanki. Okulda hiç alışık olmadığım bir sessizlik vardı. Bana mı öyle geliyordu? Bu şaşkınlığımı görmüş olacak ki akrabam; 

-Okullar yarıyıl tatiline girdi biliyorsun değil mi Kemal? 

-Bilmiyordum Edip amca… Daha var sanıyordum.

-Hadi bakalım idareye gidelim de senin karnen nasılmış bir bakalım. Dedi. İçimde bir ürperti oldu. Benim karnem nasıl olabilirdi ki? Son yazılıların hiç birine girememiştim. Bütün derslerden kalmış olmalıydım. İdareye beraber gittik. Bizi okulun müdür yardımcısı karşıladı. Akrabam kendini tanıttıktan sonra hatırlamış olacak ki; 

-Kemal sen misin? Şu hastalanan çocuğumuz..? 

-Evet, benim öğretmenim. Dedim.

-Türkçe öğretmenin senden epeyce bahsetmişti. Derslerin çok iyiymiş. Teşekkür bile almışsın. Aferin sana… Dedi. Havalara uçacak gibiydim. Nasıl olurdu. Ben son yazılıların hiç birine girememiştim ki. Bir yanlışlık mı vardı? Ama müdür yardımcısı imdadıma koşar gibi Akrabama ve babama dönerek gerekli açıklamayı yaptı; 

-Kemal’in dersleri çok iyiymiş. Hastalığı nedeniyle son yazılılara giremedi. Ama Türkçe öğretmeninin fikri ve diğer öğretmenlerinin onayıyla Kemal’in karnesini ilk yazılılarını göz önüne alarak düzenledik. İlk yazılı sonuçları da son derece iyi olduğu için oğlumuz teşekkür almaya hak kazanmış. Öğretmenlerinin ortak kanaatine göre Kemal son yazılılara da girseydi aynı başarıyı hatta daha iyisini gösterecekti. Özellikle Türkçe öğretmeni bu konuda çok emin ve ısrarlıydı.

-Babam beni tuttuğu gibi kucağına aldı ve alnımdan öptü.

-Aferin benim oğluma. Senden her zaman bunu bekliyordum. Bütün her şeye rağmen senden beklediklerimi yine yaptın. Dedi.

Gerekli işlemleri yaptık ve tekrar yola çıktık. Çok sevinçliydim. Teşekkür belgemi elimde sıkı sıkı tutuyordum. Bir an önce eve yetişmek istiyordum. Ve tepenin ardında nihayet köyümüzün dumanlı evleri göründü. Evimizin avlusuna girdiğimiz zaman dünyaya yeniden gelmiş kadar mutluydum. Kapıda annemi gördüm. Bacaklarımdaki bütün kuvvetimle koştum. 

-Anneeee…! 

-Oğluummm.

10.03.2006

Ankara	

[email protected]', 'Yatılı okula yazıldığım zaman on iki yaşındaydım. Ailemden uzakta, ortaokulun birinci sınıfına başlamıştım. Yazıldığım okul, köyümüze epey u...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Kaya']::text[], 8.5, '{"poet":"Şemsettin Kaya","poet_slug":"semsettin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/yatili-okul-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzlü', 'i-ki-yuzlu-kemal-bayrakci-z0gfq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iki yüzlüdür hayat seni yanıltmasın tanı

şarkıdaki kedi gibi nankördür bir tarafı

bir tarafı sadık sanki Sivas kangalı

unutulmuş yeminlerde bırakma ruhum yaralı

sesiyle aldatır çeker cilvesiyle kuyusuna

düşer kalırım gözlerinin dipsiz uçurumuna.

iki yüzlüdür dünya ürpertir bedenini ince

koynunda karanlıklar biriktirir sinsice

bir tarafı kül eder sevgilerin tenini

sabahın şebnemi doldurur içine sevincini

bir tarafı kıskıvrak yakalar kalırım ablukada

istersen uğruna ceset haydut olurum kavgada.

aşk iki yüzlüdür yanaşınca iskelesine

bir tarafı örer kozasını gizlice yüreğine

karşılıksızsa saplar bağrına suretinin kılıcını

sözcüklerden yaratır bir şair sevdiğinin tacını

kozasından çıkmış kelebektir diğer tarafı

bakışlarında yazılıdır hislerinin itirafı.

insan iki yüzlüdür inanmazsan rüzgara sor

sırrı dökülmüş aynalardan son sözü duyulur

bir tarafı hayatın bestelediği ıslık

almasa da verir kalbinde yarattığını

diğer tarafı çürümüş bir mevsim kaygan ıslak

hiçbir kitap yazmaz gözlerinin anlattığını.

iki yüzlüdür dostluklar hep alış veriş

yıllarca testide sakladığımız güneşimiz tükenmiş

bazen gülüşler alırız okyanuslarca dudakları doldurmaz

bir damla gözyaşı veririz bazen okyanuslara sığmaz

incinen yerlerime dokunmasın anıların elleri

derindedir kimse bilmez yaşadığım sonsuz deprem.

ben uydurmadım iki yüzlüdür yeryüzü

geceler bende kalsın sen al gündüzü

bir tarafı mavi atlas rüyaların sarnıcı

sensizliktir içimdeki kıyametin başlangıcı

nereye gitsem titrer yüreğimin kandili

ince bir sızıdır diğer yanımda ayrılık saatleri.

bir sabah ansızın unutur ömrüm seni

bir akşam çıldırasıya özlerim yüzünün tanyerini

iki yüzlüdür yaşadıklarım hüznün fotoğrafı

izin ver şiirler sarsın kırılan yüreğini.

                                         

                                                  01.2006', 'iki yüzlüdür hayat seni yanıltmasın tanı şarkıdaki kedi gibi nankördür bir tarafı bir tarafı sadık sanki Sivas kangalı unutulmuş yeminlerde ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Bayrakcı']::text[], 8.5, '{"poet":"Kemal Bayrakcı","poet_slug":"kemal-bayrakci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/iki-yuzlu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Adeta Yüreğine Hapsettin', 'beni-adeta-yuregine-hapsettin-huseyin-erdogan-9nx8o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biliyor musun sevdiğim? 

ben kendimi kaybettim

bir bakabilir misin? 

senin oralarda var mıyım? 

bulursan sakın bırakma

sıkıca tut ellerimi

sen benim gönlümü fethettin

beni adeta yüreğine hapsettin

söyler misin? 

saklanmakta haksız mıyım? 

bil ki senin yanında

ben müebbete bile razıyım

sevmek aşık olmak

bu olsa gerek

insan mapusluğu da göze alıyor

hem de severek isteyerek

senden hiç ayrı kalmak istemem

keşke her yerde

senin gölgen oluversem

denizde dalga olsam

sen kulaç attıkça

o muhteşem bedenini okşasam

ışık olup gözlerine dalsam

dünyaya hep benimle baksan

ah! gel desen bir ışık yaksan

sana doğru koşsam koşsam

sevgili şiirim yeter ki

sana kavuşmak olsun sonunda

vallahi yıllarca koşsam da hiç yorulmam

haydi haydi çağır beni koşup geleyim sana

hasretine dayanamıyorum artık beni anlasana

                                    10.03.2006

                                  Hüseyin Erdoğan', 'biliyor musun sevdiğim?  ben kendimi kaybettim bir bakabilir misin?  senin oralarda var mıyım?  bulursan sakın bırakma sıkıca tut ellerimi s...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beni-adeta-yuregine-hapsettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümü Kopardılar Soldurdular', 'gulumu-kopardilar-soldurdular-yusuf-onder-bahceci-jdv24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özenle yetiştirdiğim, o nâzlı, nâzlı gülümü,

Gülümü kopardılar, insafsızlar, insafsızlar,

Yıllar oldu beklerim, çözemedim düğümü,

Gülümü kopardılar, insafsızlar, insafsızlar.

Dalından koparsa gül, solar artık çaresiz,

Bana derdin nedir diye sormayın çaresiz,

Cânımdan çok sevdiğim, ellerde ümitsiz,

Dalından koparsa gül, solar artık çaresiz.

Evvel, bülbüller konardı, o güllerin dalına,

Zalimler acımadı sevenlerin gözyaşlarına,

Nasıl nasıl dayanırım mahsun bakışlarına,

Evvel, bülbüller konardı, o güllerin dalına.

Bu Dünya''da zalimlere hiçbirşey olmuyor,

Önder çok sevmiş bir türlü yüzü gülmüyor,

Baktırdığım falların da hepsi ayrılık çıkıyor,

Bu Dünya''da zalimlere hiçbirşey olmuyor.', 'Özenle yetiştirdiğim, o nâzlı, nâzlı gülümü, Gülümü kopardılar, insafsızlar, insafsızlar, Yıllar oldu beklerim, çözemedim düğümü, Gülümü kop...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumu-kopardilar-soldurdular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapını Aç', 'kapini-ac-umit-tuna-swd0x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapını aç al beni içeri,

Sil gözyaşları mı,

Sev beni,

Unut bütün olan biteni.

Yeniden sevelim eskisi gibi,

Dünya döndükçe seveceğim ben seni,

Güneş doğdukça özlerim,

Yıldızlara sana olan aşkımı anlatırım.

Yazdığım şiirleri yıldızlara okurum,

Sabah pencerende doğan güneşin olurum,

Akşam balkonda otururken en parlak yıldızın olurum,

Gözlerimi açtığın her yerde ben seni bulurum.

Sen yokken yanımda üşürüm,

Senin yokluğun korkutur beni,

Yatağıma giremem tek başıma,

Üşüdüm yine aşkım,

Gel bu akşam yanıma! ...

ÇILGIN MUHASEBECİ', 'Kapını aç al beni içeri, Sil gözyaşları mı, Sev beni, Unut bütün olan biteni. Yeniden sevelim eskisi gibi, Dünya döndükçe seveceğim ben seni...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kapini-ac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerse Ol Yüce Allah', 'dilerse-ol-yuce-allah-zeynal-yaman-ni58e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dilerse ol Yüce Allah deryayı nâr eyler

Kurutup dalda yaprağı gülzarı hâr eyler

O ki ''ölüden diri diriden ölü çıkarır''

İsterse her doğan günü kuluna zâr eyler

Önce Karun misâli yâr eyler şu âlemi

Sonra bozar ahengini dünyayı dâr eyler

Sorulmaz hikmeti yaptığı hiç bir işin

Bakarsın zâr bakarsın nâr bakarsın kâr eyler

1990', 'Dilerse ol Yüce Allah deryayı nâr eyler Kurutup dalda yaprağı gülzarı hâr eyler O ki ''ölüden diri diriden ölü çıkarır'' İsterse her doğan gün...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dilerse-ol-yuce-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor Deniz', 'agliyor-deniz-ayse-kok-9qb8h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmiş artık herşey

        Son bulmuş efsanemiz

        Issızlığa bürünmüş

        O  güzel sahilimiz

        Silinmiş kumlardan

        Şimdi bizim izlerimiz 

        Bak hıçkıra hıçkıra ağlıyor deniz

       Feryadı duyuluyor   kabaran dalgalarda

       Artık bitmez isyan var o kızgın sularda

       Gezdiğimiz  tekneler kalmış çok uzaklarda

       Derin maviliğini  bırakarak siyaha

       Bak bizi  düşünerek ağlıyor deniz

       O mutluluk resmimiz saklı hala kıyıda

       Düşlerimiz yalnız kalmış şimdi birkaç anıda

       Dalgaların sesi var yankılanan ağıtta

       Bak bize üzülerek ağlıyor  deniz

      Sensiz yalnız dolaştığım bu temmuz  akşamında

      Gözlerini görürüm gecenin mehtabında

      O  efsunlu günlere yeniden daldığımda

       Hatıralar katmerlenir yalnızlığımda

      Gözyaşları karışarak  dalgalarına

      Bak çağlayarak ağlıyor deniz', 'Bitmiş artık herşey         Son bulmuş efsanemiz         Issızlığa bürünmüş         O  güzel sahilimiz         Silinmiş kumlardan         Şi...', ARRAY['Türk Edebiyatı','Şiir','Ayse Kök']::text[], 8.5, '{"poet":"Ayse Kök","poet_slug":"ayse-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agliyor-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum 13. (Yerel)', 'usagum-13-yerel-mikdat-bal-sz7pq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeter arttuk diye diye yorulduk

Ne duyan var ne uyan var uşağum

Bu vatanda vatan içun vurulduk

Maşa olup can kıyan var uşağum

Kimi dağa çıkmış tuttu meşeyi

Kimi bürokrattır tutmuş köşeyi

Düşmanlarun zehirlidur her şeyi

Hem yılan var hem çıyan var uşağum

Eşkıyalar şehirde mi inde mi

Vurguncular çeşit çeşit yöntemi

Kapkaçcılar meşgul eder gündemi

Kalem ile çok soyan var uşağum

Bizimledur gündüzleri çokları

Gece olur saplar bize okları

Nerde saygı nerde insan hakları

Ne ihtiram ne sayan var uşağum

Çıkar biri maval okur anında

Yapacağı bir şeyi yok onun da

Bu kâr kalmaz edenlerun yanında

Yalan dolan bir beyan var uşağum

Mikdatî der bıraksalar yeterum

Düşmanlara dünyayı dar ederum

Balta naçak inlerine giderum

Ne dinleyen ne duyan var uşağum', 'Yeter arttuk diye diye yorulduk Ne duyan var ne uyan var uşağum Bu vatanda vatan içun vurulduk Maşa olup can kıyan var uşağum Kimi dağa çıkm...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/usagum-13-yerel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var', 'var-afiq-agdamli-f0qp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Telebeler, agah edim men sizi,

Dekanlıqda çeşid-çeşid yalan var.

Oradadır rüşvetxoru, dinsizi,

Qul haqqını acımadan alan var.

Min bir cure teleler var orada,

Çalışırlar, çatmaq üçün murada.

Bilinmez ki, kim var indi sırada,

Feqirlere hazırlanmış palan var.

Bir cellad var, qılıncıysa qayıbdır,

Bu qılıncla neçe yazıq soyubdur.

Kim deyer ki, beşi elli sayıbdır? 

Bu soyğunla kiseleri dolan var.

Ezmkardır, çox sadiqdir postuna,

Çox adildir, güzeşt etmez dostuna.

Şire dönür, ov çıxanda rastına,

Onun üçün ''ödenecek plan'' var.

Onun üçün pul her derde devadı,

Pulun varsa günahların revadı.

Çox düşünme, bir yana at savadı,

Qiymet üçün qönçe iken solan var.

Ağdami, şerefmiş,ar imiş bu pul,

Hesreti çekdiren yar imiş bu pul.

Deyirem ne yaxşı var imiş bu pul,

Ne yaxşı ki,derdeçare qılan var.', 'Telebeler, agah edim men sizi, Dekanlıqda çeşid-çeşid yalan var. Oradadır rüşvetxoru, dinsizi, Qul haqqını acımadan alan var. Min bir cure t...', ARRAY['Türk Edebiyatı','Şiir','Afiq Agdamlı']::text[], 8.5, '{"poet":"Afiq Agdamlı","poet_slug":"afiq-agdamli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/var-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İhtimal', 'bir-i-htimal-elvan-genc-j5gv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle bir gün

O duyguyu pay etsek

Hiç konuşmasan SEN

Sussam BEN

Vakitsiz bir zamanda

Öylece seyretsek

Bakmasam SANA

Ve sen BANA 

Sadece arzuyu hissetsek

Ne müthiştir

Tenin uyumu

Olabiliri farzetsek..

Bir ihtimal

Düşler gerçek ya

Diye bu anı

Zihnimize nakşetsek..

09.03.2006', 'Seninle bir gün O duyguyu pay etsek Hiç konuşmasan SEN Sussam BEN Vakitsiz bir zamanda Öylece seyretsek Bakmasam SANA Ve sen BANA  Sadece ar...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-ihtimal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yine Sevdim Diyeceğim', 'ben-yine-sevdim-diyecegim-yusuf-onder-bahceci-wii4y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alsalar seni benden, prangalar vursalar, kadem,

Ben yine sevdim diyeceğim, sevdim, diyeceğim,

Hallac-ı Mansur''a neler ettiler benim sevdiceğim,

Ben yine sevdim diyeceğim, sevdim, diyeceğim.

İbrahim''i ateşe attılar da, gül bahçesi olmadı mı,

Sümeyye''yi, parça parça ettiler, şehit olmadı mı,

Yunus Emre, Taptuğun kapısında, var olmadı mı,

Ben yine sevdim diyeceğim, sevdim diyeceğim.

İki Cihan Serverini, çok üzmediler, üzmediler mi, 

Bilal-i Habeşi''yi kızgın çöllerde gezdirmediler mi,

Sen bu davadan vazgeç başımız ol demedilermi,

Ben yine sevdim diyeceğim, sevdim diyeceğim.

Hâk''kın davası,hâlkın davası, birbirine karışmış,

Hâktan korkmayan zalimlerin hepsi de aşırırmış,

Hâkkı bilmeyen körler, düz yolda yolu şaşırırmış,

Ben yine sevdim diyeceğim, sevdim diyeceğim.', 'Alsalar seni benden, prangalar vursalar, kadem, Ben yine sevdim diyeceğim, sevdim, diyeceğim, Hallac-ı Mansur''a neler ettiler benim sevdiceğ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-yine-sevdim-diyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okumasa da Yazacağız', 'okumasa-da-yazacagiz-yusuf-onder-bahceci-rmbej', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nâzlı yâr şiirleri okusa da, okumasa da yazacağız,

Kâlbimizde hasreti, kesreti gözyaşlarını bulacağız,

Baki değiliz elbet bir gün bizlerde toprak olacağız,

Nâzlı yâr şiirleri okusa da, okumasa da yazacağız...', 'Nâzlı yâr şiirleri okusa da, okumasa da yazacağız, Kâlbimizde hasreti, kesreti gözyaşlarını bulacağız, Baki değiliz elbet bir gün bizlerde t...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/okumasa-da-yazacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baksana Nasıl Ayırdılar', 'baksana-nasil-ayirdilar-yusuf-onder-bahceci-2sgav', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim için ne düşünürsen Allah sana on misli versin,

Ne düşünecekler ki kardeşim baksana nasıl ayırdılar,

Sonrada kenara çıkıp gülmeyen kaderimizi kayırdılar,

Ne düşünecekler ki kardeşim baksana nasıl ayırdılar.', 'Benim için ne düşünürsen Allah sana on misli versin, Ne düşünecekler ki kardeşim baksana nasıl ayırdılar, Sonrada kenara çıkıp gülmeyen kade...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baksana-nasil-ayirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Ne Hâle Gelmiş', 'dunya-ne-h-le-gelmis-yusuf-onder-bahceci-8awki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya ne hâle gelmiş,

Dostluk yalan, sevgi yalan değilmi,

Bak ağlayıp duruyorsun,

Gelip hâlini sordu mu, sordu mu,

Ben sorana rastlamadım,

Ben sevene rastlamadım,

Yıllarca sevip taptığın,

Başına hep taç yaptığın,

Ellerden de kıskandığın,

Sevgi yalan, dostluk yalan değil mi,

Bak ağlayıp duruyorsun,

Gelip hâlini sordu mu,

Ben sorana rastlamadım,

Ben sevene rastlamadım....

Yıllar önce yazdığımız bir şiir, 

Müslüm Gürses tarafından okunan...', 'Dünya ne hâle gelmiş, Dostluk yalan, sevgi yalan değilmi, Bak ağlayıp duruyorsun, Gelip hâlini sordu mu, sordu mu, Ben sorana rastlamadım, B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-ne-hale-gelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nemrut (Sesimdeki Kuğu)', 'nemrut-sesimdeki-kugu-ayten-colakoglu-orwgu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

çölü yalayıp yuttu hilkat garibesi

elinde çalı süpürgesi yüzüne daldı Nemrut’un

mavinin sürgünü ve çöl efendisinin mahkûmu

melekler mutlu mazisini alıp dünyaya serdi

rüyalarını örttü o uykusuz kadının

lâhitten sızınca lânet, kehanet gerçekleşti

güneş eteklerini toplayarak kaçarken

kadının gövdesi kum yangınına dönüştü

karanlığı anlayan yok, çölün hüznünü de...

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. çölü yalayıp yuttu hilkat garibesi elinde çalı süpürgesi yüzüne daldı Nemrut’un mavinin sürgünü ve çöl efendisinin mahkûmu melekler mutlu ...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nemrut-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Birgün Anlarsın', 'belki-birgun-anlarsin-yusuf-onder-bahceci-mh7g2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki birgün anlarsın,

Hatalarını, günahlarını,

Gözlerin yaşlarla dolar,

Başını avuçların içine alır,

Alır da düşünürsün,

Neden böyle yaptım diye,

Belki sen de benim gibi,

Gizli, gizli,

Sessiz, sessiz,

Ağlıyorsundur geceleri....', 'Belki birgün anlarsın, Hatalarını, günahlarını, Gözlerin yaşlarla dolar, Başını avuçların içine alır, Alır da düşünürsün, Neden böyle yaptım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/belki-birgun-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Taneleri', 'kar-taneleri-ercan-agtas-mgjrm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'titredim

ezgi oldum bağlamada

sevdalarım sıcak nefeslerdi

geceye sessizce aktı

ve gözlerimde eriyen kar taneleri

söylendim

ağıt oldum sinede

anılarım yol boyu uzandı

kaldırım taşlarında yosun bağladı

ve gözlerimde eriyen kar taneleri

gelmedin

sıla oldun yüreğimde

hüzünlerim camlarda buğulandı

ve gözlerimde eriyen kar taneleri

herhanbirzaman/herhangibirdörtduvar', 'titredim ezgi oldum bağlamada sevdalarım sıcak nefeslerdi geceye sessizce aktı ve gözlerimde eriyen kar taneleri söylendim ağıt oldum sinede...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kar-taneleri-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz Sevinci', 'yakamoz-sevinci-elif-kerenciler-2hycw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'papatya sevinciydi

papatya sevinceydi sevdamız

ömrümün bir dönemi açılıp

yakamoz vakti kapanırken

yıldızlar söz verdi, bu gece

denizimin üstünü aya bırakacaklarmış

ay gökyüzündeki tek ışık

ben denizin derinliklerindeki tek yıldız 

tüm ışığını hissetmek istiyorum

sudaki yansımalar dahil

çünkü seni seviyorum', 'papatya sevinciydi papatya sevinceydi sevdamız ömrümün bir dönemi açılıp yakamoz vakti kapanırken yıldızlar söz verdi, bu gece denizimin üst...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yakamoz-sevinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Şiir Yazmazsam', 'sana-siir-yazmazsam-yusuf-onder-bahceci-wz4i4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer, bir gün sana şiir yazmazsam,

Bilki kesilmiştir, kesilmiştir nefesim,

Eğer, şiirde seviyorum, demezsem,

Ben aklımı yitirmişim demek bilesin,', 'Eğer, bir gün sana şiir yazmazsam, Bilki kesilmiştir, kesilmiştir nefesim, Eğer, şiirde seviyorum, demezsem, Ben aklımı yitirmişim demek bil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sana-siir-yazmazsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-alptekin-biber-r4t9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya ben insan değilim

.................hiç olmadım,

....hep olduğumu sandım...

Ya da 

.....utansın

........insan olduğunu sanan...

Alptekin Biber / 9 Mart 2006', 'Ya ben insan değilim .................hiç olmadım, ....hep olduğumu sandım... Ya da  .....utansın ........insan olduğunu sanan... Alptekin B...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insan-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Önce Şiirler Yazacağım', 'senin-i-cin-once-siirler-yazacagim-yusuf-onder-bahceci-skm0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için önce şiirler yazacağım,

Sonra, bu şiirleri besteleyeceğim,

Sesimde güzel ise sesleyeceğim,

Senin için önce şiirler yazacağım.', 'Senin için önce şiirler yazacağım, Sonra, bu şiirleri besteleyeceğim, Sesimde güzel ise sesleyeceğim, Senin için önce şiirler yazacağım....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senin-icin-once-siirler-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Koşayım', 'sana-kosayim-selahattin-yetgin-0vpv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzak denizler düşlüyorum yorgun usumda

Yüzüme çarpan dalga seslerinin yosununda

Dinle çığlığımı ey sevgili belki uçurumunda

Seni yitirmeye korktuğumca var olacaksın

Islak yıldızlara ve deniz kızlarına ağ atarken balıkçılar

Gözlerinde büyütüp yüreklerinde sakladıklarına ağlarlar

Düşleri talanlaşan yapay okyanuslarda çürür  hep ağlar

Anlamaya çalışma boşuna seyrine doyulmazdır dağlar

İncecik bir çizgiden anlamsız kavramlar üreterek

Yüreğindeki ihtirasları ebedi bir tutkuya beleyerek

Yanıtı imkansız tüm sorulara dileğini yükleyerek

Avuçlarının içindeki çizgileri sev nefesini üfleyerek 

Işıkların karanlığa saklandığı yorgun gecelerde

Dilerim ki, bakışlarının yeşil ağlarına takılayım

Kırıntılı bir ekmek gibi gözlerinde ıslanayım

Namlusunu arayan bir kurşunca sana koşayım', 'Uzak denizler düşlüyorum yorgun usumda Yüzüme çarpan dalga seslerinin yosununda Dinle çığlığımı ey sevgili belki uçurumunda Seni yitirmeye k...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-kosayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teninde Bir Çocukluk', 'teninde-bir-cocukluk-ercan-agtas-nmuts', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içimde bir burukluk

daldım da

bu kentin kalabalığına

uzattım ellerimi bir soğuk

avuçlarıma esen ılık bir buğuluk

geceyi saran bir soğukluk

gülüm

tenine dokunsam

teninde bir soğukluk

yürüdüm de

bu kentin dar sokaklarında

sarıldım içimde ürkek bir çocuk

avuçlarıma esen bir yokluk

geceyi saran bir çocukluk

gülüm

tenine dokunsam

teninde bir çocukluk

içimde bir sen

yoksun da

bu kentin ortasında

arıyorum seni kendimle

avuçlarıma esen bir sessizlik

geceyi saran bir sensizlik

gülüm tenine dokunsam

teninde bir sensizlik

herhanbirzaman/herhangibirdörtduvar', 'içimde bir burukluk daldım da bu kentin kalabalığına uzattım ellerimi bir soğuk avuçlarıma esen ılık bir buğuluk geceyi saran bir soğukluk g...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/teninde-bir-cocukluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeyrek Kala', 'ceyrek-kala-yasar-tezel-ibdau', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İz düşümünde çığ düşmüşse saçlara

Gönül viran olma dostu içinde ara

Barıştıysan kalb sarayındaki padişahla

Misk anberler içinde kevserler akar', 'İz düşümünde çığ düşmüşse saçlara Gönül viran olma dostu içinde ara Barıştıysan kalb sarayındaki padişahla Misk anberler içinde kevserler ak...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ceyrek-kala-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar Tacını Taktım Bugün', 'asiklar-tacini-taktim-bugun-candan-sevinc-kdwop', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşıklar tacını taktım bugün

Yüreğime de gözlerini kazıdım

Bir başka mutluyum şimdi

Kapılar açıldı sessiz

Kırgınlıklar kül olup uçtu

Aşıklar tacını taktım bugün

Ellerim özgür şimdi

Yak dedi yüreğim bu ateşi

Yak ki durulsun deniz

Sevda bahçenden geçsin

Rüya güzellikteki kız

Aşıklar tacını taktım bugün

Bir başka duruyorum şimdi

Başım dumanlı dağlarda

Bir başka mutluyum şimdi.', 'Aşıklar tacını taktım bugün Yüreğime de gözlerini kazıdım Bir başka mutluyum şimdi Kapılar açıldı sessiz Kırgınlıklar kül olup uçtu Aşıklar ...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/asiklar-tacini-taktim-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk da düşer', 'ask-da-duser-candan-sevinc-7xr6q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman hayata arkamı dönsem

Bir kör bıçak saplanır

Dalgalı bir acı koşar yüreğime

Dayandığım dal kopar birdenbire

Bilenmiş sözcüklerin celladı olurum

Dipsiz karanlıklar içinden fışkırır özüm

Ve ben bir şahin kadar yırtıcı

Bir serçe kadar zavallı kalırım 

Sensizlikte

Aşk da düşer böylece,kendince.', 'Ne zaman hayata arkamı dönsem Bir kör bıçak saplanır Dalgalı bir acı koşar yüreğime Dayandığım dal kopar birdenbire Bilenmiş sözcüklerin cel...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-da-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden İçeri', 'benden-i-ceri-ercan-agtas-p9psz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ben var benden içeri

alır götürür

benden yoksun beni

benim hissettiğim acı

senin senden habersiz

benin bana verdiği

istemsiz bir hissin tadı

herhanbirzaman/herhangibirdörtduvar', 'bir ben var benden içeri alır götürür benden yoksun beni benim hissettiğim acı senin senden habersiz benin bana verdiği istemsiz bir hissin ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benden-iceri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Gibi Eskidi Yüzün', 'bir-gun-gibi-eskidi-yuzun-candan-sevinc-ksoye', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gibi eskidi yüzün

Yürünen yollar gibi geride kaldın

Bir zamanlar güllerle dolu mağaramda

Suskunluğu bozulmamış bir zambaktın

Derin ırmaklardan çalmıştım seni

Şimdi ellerim çekemiyor bu yükü

Soluklanmak için diz çöküyorum güneşe

Ve sana menekşeler uzatıyorum geçmişten.', 'Bir gün gibi eskidi yüzün Yürünen yollar gibi geride kaldın Bir zamanlar güllerle dolu mağaramda Suskunluğu bozulmamış bir zambaktın Derin ı...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gun-gibi-eskidi-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
