INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetim', 'gurbetim-turkan-yakin-ndbnb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı paylaşamadım,

Dostlarımı anlayamadım.

Kaderime doyamadım.

Acılarıma yanamadım.

Hasretine dayanamadım.

Toprağını koklayamadım.

Gurbetime sızlanamadım.

Ayrılığa katlanamadım.

Ah özledim, çok özledim.

Hem değerlerimi, hem de kendimi.

Gurbetim yitirdi beni.

Yitirdi de, bitirdi beni.', 'Yalnızlığımı paylaşamadım, Dostlarımı anlayamadım. Kaderime doyamadım. Acılarıma yanamadım. Hasretine dayanamadım. Toprağını koklayamadım. G...', ARRAY['Türk Edebiyatı','Şiir','Türkan Yakın']::text[], 8.5, '{"poet":"Türkan Yakın","poet_slug":"turkan-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarların Ruhu', 'ruzgarlarin-ruhu-bekir-gedikoglu-9377c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarların Ruhu

Özgürdür türkülerim ruhu rüzgara benzer

Gönlün biri incinse hemen yardıma gider

Simit satıcısının dili beni heceler

Koç yiğitler meydanda kulağı beni dinler

Mahpushane içinde var idamlık adamlar

Attığı voltaların boyu çok kısa çıkar

Ayakta prangalar gönül kelepçe kırar

Yavuklunun yazdığı türküden gönül coşar

Çölde bir sabi kalsa elbette ağlayacak

Anne diye ağlarken etrafına bakacak

Minicik elleriyle anaya gel yapacak

Boşanan göz yaşları türkü gibi akacak

Dertli başın sevdası içten içe artarmış

Bu dünya bir olsa da derde deva olmazmış

Yaralı olan yürek kuytu yere kaçarmış

Ağzında aşk türküsü çağıl, çağıl akarmış

Ankara 10 Mart 2006

Bekir GEDİKOĞLU', 'Rüzgarların Ruhu Özgürdür türkülerim ruhu rüzgara benzer Gönlün biri incinse hemen yardıma gider Simit satıcısının dili beni heceler Koç yiğ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ruzgarlarin-ruhu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durgun Akan Sular Gibiyim', 'durgun-akan-sular-gibiyim-yusuf-onder-bahceci-k2l5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durgun akan sular gibiyim,

Peşindeyim senin güzelim,

Esen yellerle, çıkar gelirim,

Peşindeyim senin güzelim.

Kelebekler gibi konacağım,

Arılar gibi ballar yapacağım,

Yaralı kartal gibi bakacağım,

Peşindeyim senin, güzelim.

Tatlı esen meltem rüzgarıyla,

Yalçın dağların eriyen kârıyla,

Özlemle bekler kâlp efkârıyla,

Peşindeyim senin, güzelim.

Yavrusunu yitiren ceylan gibi,

Güllere özlem, bülbüller gibi,

Bahçede solan güllerim gibi,

Peşindeyim senin, güzelim.', 'Durgun akan sular gibiyim, Peşindeyim senin güzelim, Esen yellerle, çıkar gelirim, Peşindeyim senin güzelim. Kelebekler gibi konacağım, Arıl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durgun-akan-sular-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğreti Kelâm', 'egreti-kel-m-tulay-sustam-up8k6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tüyü yetmemiş bir çocuk

ne anlar ağaç budamaktan

.

.

dul bir kadın / bir kere toprak ana olur

sokak çocuğu / gündüzleri ayak basmaz toprağa

hayat; bir tek sütü çekilmiş kadını emzir(e)   mez...', 'tüyü yetmemiş bir çocuk ne anlar ağaç budamaktan . . dul bir kadın / bir kere toprak ana olur sokak çocuğu / gündüzleri ayak basmaz toprağa ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/egreti-kelam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutup Yıldızım', 'kutup-yildizim-mustafa-dogan-4-3fwk6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KUTUP YILDIZIM

Ilık bir bahar esintisi gibisin, 

Usulca ruhumu saran,

Kokladığım o papatyalar gibisin, 

İçimde hisseder duyarım seni,

Kır çiçekleri gibi kokar tenin,

Kalbime sevgiyi dolduran gözlerin,

Duygularımın o açlığını doyurur,

Umutlarıma yeniden can gelir, 

Ümitlerim coşar o bakışlarınla,

O gözlerinin derinliklerine,

Yıldızlar yuva kurmuş gibi,

Bu kaybolmuşluğuma,

Kalbimin yitik o duygularına,

Yol olan o bakışların sahibisin,

İşte o sensin kalbimin kutup yıldızı,

Sen bana hayatı sevdiren güzelsin.', 'KUTUP YILDIZIM Ilık bir bahar esintisi gibisin,  Usulca ruhumu saran, Kokladığım o papatyalar gibisin,  İçimde hisseder duyarım seni, Kır çi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan 4']::text[], 8.5, '{"poet":"Mustafa Doğan 4","poet_slug":"mustafa-dogan-4","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kutup-yildizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç göz yaşı sonra geleceksin', 'kac-goz-yasi-sonra-geleceksin-eren-caglar-niron-ke5e6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç göz yaşı sonra geleceksin

Özledim…

Çalındı benden gülen yüzüm

bu yüzdendir ki 

geçen her bir dakika 

bir doz daha artıyor hüznüm.

Gelişin olmadı ki hiç, gidişin olsun

Ama ben yinede dönüşünü bekliyorum.

Söyle, kaç gözyaşı sonra geleceksin,

ve kaç gülücük sonra gidecek…

Eren Çağlar Niron

2003', 'Kaç göz yaşı sonra geleceksin Özledim… Çalındı benden gülen yüzüm bu yüzdendir ki  geçen her bir dakika  bir doz daha artıyor hüznüm. Gelişi...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kac-goz-yasi-sonra-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımazsın Atanı', 'tanimazsin-atani-yusuf-onder-bahceci-d9uon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soysuzlar için mi kurtardılar ki bu, Vatanı,

