INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Çemberi', 'huzun-cemberi-yasar-tezel-yk2hd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Matem tutmuşsun,gec bile kaldın 

Yandığım acılar değil ayrılığın

Gitmedin ki hiç duygu yumağım

Gözlerin hapsindeyim,sevdayım

Çekmez bu gönlüm yükü

ne baharı ne yazı,aşk iki arada kaldı

Yasemin çiçeğinde gizlendi,rüyası

Rüyalar ağladı,ney ağladı

Aşka giden yollara karlar yağdı

İzleri kaldı', 'Matem tutmuşsun,gec bile kaldın  Yandığım acılar değil ayrılığın Gitmedin ki hiç duygu yumağım Gözlerin hapsindeyim,sevdayım Çekmez bu gönlü...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-cemberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu', 'i-nsanoglu-umit-tuna-l3bmn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu yaşıma kadar anlayamadım insanları,

Hep birbirlerinin arkasından dönen dolaplar,

Birbirleri hakkında dedikodular,

Yıllardır anlayamadım ben,

Neden insanlar çıkarcılar.

Sadece kendi menfaatleri için varlar,

Neden bir ekmeği ikiye bölmekten korkarlar,

Neden bir tas suyu paylaşmazlar,

Neden birbirleri için bir şeyler yapmazlar.

Yıllardır anlayamadım,

Biz insanlar bu dünyada neyiz,

Her şeye sahip olmaya çalışan biz,

Biz niye hiç ölmek istemeyiz.

Neden hep benim deriz,

Bizim demekten kaçınırız,

Bazıları kuş tüyü yataklarda,

Bazıları kartonlar üzerinde yatar.

Bazıları için yaz kış fark etmez,

Bazıları kışın ortasında soğuktan ölür.

Neden paylaşmayı bilmez insan,

Vardır bu dünyanın sonu,

Niye hiç mahşeri düşünmez,

Niye hep güçsüzü hor görür.

İnsanoğlu bu doymaz ki paraya,

Bir de erkekse yer karılarla,

Neden hep böyledir bu duygu,

Yoksa gerçekten yok mu,

Bu dünyanın sonu! ...

ÇILGIN MUHASEBECİ', 'Bu yaşıma kadar anlayamadım insanları, Hep birbirlerinin arkasından dönen dolaplar, Birbirleri hakkında dedikodular, Yıllardır anlayamadım b...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/insanoglu-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykularımda Kucakladım', 'uykularimda-kucakladim-ercan-agtas-mc264', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin yokluğunda çok sevdim ben seni

en güzel iklimlere sardım

sevecen umudumla sarıldım

senin yokluğunda kendimle özledim

düşlerimdeydin

ki ben sana

bir balık düşü gibi

usulcana sarıldım

rüyalarımdaydın

ki ben seni

pul pul uyudum

uykularımda kucakladım

pul pul uyandım

gözlerimdeydin

ki ben seni

ağlamadım

ağlayamadım

yüreğimde sakladım

yüreğimdesin

ki ben

yanmadım

yangınlar yandı da yanmadım

yanamadım

herhanbirzaman/herhangibirdörtduvar', 'senin yokluğunda çok sevdim ben seni en güzel iklimlere sardım sevecen umudumla sarıldım senin yokluğunda kendimle özledim düşlerimdeydin ki...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/uykularimda-kucakladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerce Ağladım', 'gunlerce-agladim-yusuf-onder-bahceci-m2xba', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu Dünya''da, bir tek seni, seni sevmiştim,

Boşa sevdalanma o seni sevmiyor dediler,

İnanmadım, inanamadım günlerce ağladım.

Dünya''da, bir tek sana, sana güvenmiştim,

Güvendiğin dağlarına, kârlar yağdı, dediler,

İnanmadım, inanamadım günlerce ağladım.', 'Bu Dünya''da, bir tek seni, seni sevmiştim, Boşa sevdalanma o seni sevmiyor dediler, İnanmadım, inanamadım günlerce ağladım. Dünya''da, bir te...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunlerce-agladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş', 'gidis-bilal-i-lhami-koksal-cwpoc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi gidiyorum 

Bir daha iki yakası bi araya gelmeyecek bu kentin

Bu cümleyi ben mi kurdum

Yoksa başka bir yerden mi duydum inan bilmiyorum

Her şey o kadar otobüs ki...

Bu gidişimi sana bırakıyorum

Hatta bıraktığım işimi gücümü

Bıraktığım günde iki üç dal sigarayı

Ve ikisini benim yaşadığım

Otuz sekiz''i kalan ikindi yağmurlarını

Şimdi sana ne istanbulun yoğurduna özenilen kanlıcasını

Ne bir çay bu kadar mı güzel olur ortaköyünü

Ne ordan nereye bakarsan bak güzel görürsün çamlıcasını

Ne yaza yaza bitiremeyeceğin taksimini,

istiklalini

Ben sana daha önce hiç bir şiirde duymadığın

Ümraniyede

Küçük yarım bir hayat bırakıyorum 

Bilmem nasıl başa çıkarsın bu koskoca şehirle

Ben sana bir gidiş bırakıyorum

Gelişi olmayan

Sana yollar bırakıyorum -üzgünüm-

Hiç bir zaman hiç bir yere varmayan..', 'Şimdi gidiyorum  Bir daha iki yakası bi araya gelmeyecek bu kentin Bu cümleyi ben mi kurdum Yoksa başka bir yerden mi duydum inan bilmiyorum...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gidis-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Acı Dokunuşu', 'kaderin-aci-dokunusu-ercan-agtas-xk435', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşadıklarım ve yaşayacaklarım

bunlar benim kaderim mi

yoksa kaderin acı dokunuşu mu 

bu bendeki

mezartaşlarına yazılan

merhumun ruhuna El-Fatiha

peki kadertaşımız da olsaydı

ne yazardı…

sevdiklerim ve seveceklerim

bunlar benim mutluluğum mu

yoksa mutluluğun ince yansıması mı

bu bendeki

bir odanın nemini alan

günbaşlangıcı pencereden sızan güneş

ya yüreğimizin paslanan nemini

ne alırdı…

herhanbirzaman/herhangibirdörtduvar', 'yaşadıklarım ve yaşayacaklarım bunlar benim kaderim mi yoksa kaderin acı dokunuşu mu  bu bendeki mezartaşlarına yazılan merhumun ruhuna El-F...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaderin-aci-dokunusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysel', 'aysel-yasar-tezel-nd6ml', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çiçekler arasında sümbül

Boynu büküğüm  gül

Kulağında tatlı fısıltı

Aysel

Tesellim ol,sevgili

Gün doğmadan,tan ''ı

Espirilerinin güzel yanı

Sıkılmasın aşığın canı

Aysel

Lodostu esti gitti

Dilimden ne düştü bilmem

Sensizlik içime sinen dem

Sen ol mekanım olsun yemen

Aysel

Gün doğdu aktı gitti', 'Çiçekler arasında sümbül Boynu büküğüm  gül Kulağında tatlı fısıltı Aysel Tesellim ol,sevgili Gün doğmadan,tan ''ı Espirilerinin güzel yanı S...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aysel-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuşlar', 'gocmen-kuslar-candan-sevinc-u943w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göçmen kuşlar

Umut yolculuğuna çıktılar

Giderken yanlarına

Çocukların rüyalarını da aldılar

Gelecek ilkbahara

Yemyeşil getirecekler.', 'Göçmen kuşlar Umut yolculuğuna çıktılar Giderken yanlarına Çocukların rüyalarını da aldılar Gelecek ilkbahara Yemyeşil getirecekler....', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gocmen-kuslar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük - VI', 'dortluk-vi-hamit-pala-rw0sr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda çekenlerin bağrı hep yanık olurmuş

Kavuşmayı bekler iken ayrılık olurmuş

Korkarım ki seni görenler âşık olurmuş

Kavuşmayı bekler iken ayrılık olurmuş

06.08.2000 Antalya', 'Sevda çekenlerin bağrı hep yanık olurmuş Kavuşmayı bekler iken ayrılık olurmuş Korkarım ki seni görenler âşık olurmuş Kavuşmayı bekler iken ...', ARRAY['Türk Edebiyatı','Şiir','Hamit Pala']::text[], 8.5, '{"poet":"Hamit Pala","poet_slug":"hamit-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak izlerin', 'ayak-izlerin-bestami-kurtulus-nhqrs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yerde senin küçük ayak izlerin

aklımda senden kalan kokun bulaşık

doğarken ölümüdür bu yeşil filizlerin

uzanır bacakların boyunca bir sarmaşık

yeşil muhteris bir soytarı

ve hırçın ve bıçkın ve bir o kadar sırnaşık

ayaklarının altında seriliveren çimenliğe

akıp gider parmaklarının ucundan bir hayalet 

yaz gelmesin bitmesin bu nemli bahar

yağmurlardan ıslanmazsak kim yeşerir böyle dalında 

en kuytu yerlerinde açılıveren laleler ve gül 

murt yaprağından bir çelenk içinde ılık karanlık 

kokusu oğul balı, tadı gözyaşı bir ırmak

sen fark etmezsin bu karanlık dehlizde

bir karışık yol gibi uzar gider önünde

ah tutkularım bunca ağır olmasaydı

aşk vurgun yemiş en derinde 

yüreğim ne kadar götürür bu yabani ormanı

daha ne denli yansın, kavrulsun içim

nefesinle savruluyor külü dumanı

kararıp bozuluyor her renk ve her biçim

patlıyor bana nar kızılı taneler 

yığılıp bir köşede kalakalıyor volkan

bir ben duyuyorum yüreğinin içinde

fırtınadan sonra dingin bir liman', 'yerde senin küçük ayak izlerin aklımda senden kalan kokun bulaşık doğarken ölümüdür bu yeşil filizlerin uzanır bacakların boyunca bir sarmaş...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayak-izlerin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Vadisini İzliyorum', 'kurtlar-vadisini-i-zliyorum-yusuf-onder-bahceci-fnmrh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gerçek mafyalar Kurtlar Vadisine mafyadır diyor,

Dangalak bilmiyor ki bunlar mafyalarla savaşıyor,

Bu diziyi iyi izlemeden köpekler gibi de saldırıyor,

Gerçek mafyalar Kurtlar Vadisine mafyadır diyor.

Bu diziyi pür dikkat izliyor, çok şey öğreniyorum,

Polat Alemdar tam bir Türk Gencidir, seviyorum,

Ben buradan kanı bozuk olanlara, sesleniyorum,

Bu diziyi pür dikkat izliyor, çok şey öğreniyorum.

Kurtlar Vadisi Dizisiyle flimi gişe rekorları kırıyor,

Diziyi ve flimi izleyenler mutmain mutmain oluyor,

Herhalde, gerçek mafyaların da, yerleri daralıyor,

Kurtlar Vadisi Dizisiyle flimi gişe rekorları kırıyor.

Ne diyor Büyük Atamız Türk öğün, çalış ve güven,

Bu flimler, bana öz güven veriyor, bana, öz güven,

Böylesi flim ve dizileri izleyelim öğrenelim desem,

Ne diyor Büyük Atamız Türk Öğün, çalış ve güven.', 'Gerçek mafyalar Kurtlar Vadisine mafyadır diyor, Dangalak bilmiyor ki bunlar mafyalarla savaşıyor, Bu diziyi iyi izlemeden köpekler gibi de ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kurtlar-vadisini-izliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Çiçekleri', 'huzun-cicekleri-sair-ayisigi27-ele5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde öyle büyük keder ve hüzün varki 

Teselli etmez ne ay nede yıldız bu gece 

Esen rüzgarla gelir sanki uzaklardan sesin 

Issız karanlık sokaklarda ararım her an seni 

Karanlıklarda savurdum hüznümü kederimi 

Yıldızlardan ışık savurdum her yere 

Her gecenin sabahında çiçeklerde ben olurum 

Her açtığımda açar benle hüzün çiçekleri 

Gözyaşlarım çisil çisil düşer yapraklarımdan 

Her Gelen baharda açar hüzün çiçekleri', 'İçimde öyle büyük keder ve hüzün varki  Teselli etmez ne ay nede yıldız bu gece  Esen rüzgarla gelir sanki uzaklardan sesin  Issız karanlık ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ayışığı27']::text[], 8.5, '{"poet":"Şair Ayışığı27","poet_slug":"sair-ayisigi27","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-cicekleri-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmadan Ol', 'korkmadan-ol-mehmet-emin-dogan-ffcsu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimi ışıldatıyor,

Buğulanan gözlerinden saçılan alevler. 

Ruhumu üşütüyor, 

Titreyen dokunuşlarının masum sıcaklığı. 

Avucumu yakan alevlere dokunamıyorum. 

Çakmak olmuş, kor kor kıvılcım saçan bakışların. 

Bir rüzgar sanki, fırtınaları sarsan fısıltının nağmeleri. 

Sade bir bakış, derindeki hissi yansıtan, en incesinden, 

Sade bir gülüş, yaşmaktaki gülü inciten, en damarından, 

Sade bir sevda, kendine itirafı titreten, en harbisinden, 

Sade bir sessizlik fırtınaları çağıran, en çığırtkanından, 

Sen de biliyorsun; 

Devlerin susmayacağını, 

Korkunun yatmadığını ve cesaretin uyumadığını. 

Ve hatta sen de biliyorsun, 

Yalanların esir aldığı doğruları. 

Hangi hezeyanın yankısı, karanlığı yıpratan bu feryatlar 

Hangi korkunun cesareti, suskunluğa meydan okuyan devlerin kükreyişi. 

Hangi sevdanın esareti, bakışları acıyla dolduran gözlerin pınarı. 

Hangi vicdanın muhasebesi, seni, sana yenik düşüren kavgalar 

Sen de bilemezsin, 

Islanmadan, sonbaharın korkak yağmurlarında, 

Üşümeden, güneşin kavurduğu kumsallarda, 

Yanmadan ölüm saçan kor alevlerde, 

Kaç bahar yaşattığını, kalbine…. 

Haydi söyle, 

İstediğin zaman, 

Bulabildiğin kelimelerle, 

Dayanabileceğin netlikte. 

Korkuların beklentilerini aşmadan,

Nefretin sevgine meydan okumadan, 

Esaretin cesaretini kırmadan, 

Ve

Çaldığım kalbinden beni azat etmeden, 

Hangi baharı bekletiyorsun yüreğine. 

Kaç geceyi dost edindin, karanlığı boğarken, 

Kaç sevdanın meskeni oldun, ayazları yakarken, 

Kaç günün sabahını kucakladın akşamı beklerken, 

Kaç yolculuğu tükettin ellerin kolların bağlıyken…', 'Kalbimi ışıldatıyor, Buğulanan gözlerinden saçılan alevler.  Ruhumu üşütüyor,  Titreyen dokunuşlarının masum sıcaklığı.  Avucumu yakan alevl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Doğan']::text[], 8.5, '{"poet":"Mehmet Emin Doğan","poet_slug":"mehmet-emin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/korkmadan-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Gece', 'bir-de-gece-ercan-agtas-evxgg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüznün gülleri soldurduğu vakitler

karanlığın

ellerime

yıldızları ağladığını duyarım

ve geceye akan

her yıldızla

yitip giden sevdaları

bedenime sararım

kaç kez fırtınalarda uçtu

bir ellerim

bir bedenim

bir ben savruldum

bir de gece

gözlerim bir gri yosun gözyaşıyla

ıslanmışlığı

ve yalnızlığıyla titreyen

bir çocuk

acemi bir ressam hevesiyle

yüreğime çizdim

kaç kez yangınlarda yandı

bir gözlerim

bir yüreğim

bir ben yıkıldım

bir de gece

herhanbirzaman/herhangibirdörtduvar', 'hüznün gülleri soldurduğu vakitler karanlığın ellerime yıldızları ağladığını duyarım ve geceye akan her yıldızla yitip giden sevdaları beden...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-de-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzler Kalır', 'i-zler-kalir-yasar-tezel-zq4md', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni anımsatan 

İnan çok şey kaldı bende

Beynimde senin dedikodun

Karamsar gecede ay dede

görünsede

Düşünceler,ağrıyan başım

Hep o günler, gidip gelmeler

Uzak çok uzaklarda

Esir ettiniz aşkı

Umut var,belkide yok gibi

Bu çölde su çıkarsa

Saçlarında çağlayan akar

Gönlümü içine salıvermek

gelir içimden

Atarım derinliklerine

yüzme bilmem 

Tutan olmaz elimden', 'Seni anımsatan  İnan çok şey kaldı bende Beynimde senin dedikodun Karamsar gecede ay dede görünsede Düşünceler,ağrıyan başım Hep o günler, g...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/izler-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Mazlumun Ahı Kalır', 'sanma-mazlumun-ahi-kalir-yusuf-onder-bahceci-b3xqk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanma ki mazlumların ahı kalır, Allah intikamını alır,

Düşmanların içine, ne korkular, ne aslanları bırakır,

Allah''ın hâs kulları, Allah''ım yeter artık medet dese,

Sanma ki mazlumların ahı kalır, Allah intikamını alır.', 'Sanma ki mazlumların ahı kalır, Allah intikamını alır, Düşmanların içine, ne korkular, ne aslanları bırakır, Allah''ın hâs kulları, Allah''ım ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanma-mazlumun-ahi-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sevda', 'bu-sevda-mikdat-bal-t1u40', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nice canlar verdik bitmedi hala

Taptaze dipdiri yaşar bu sevda

Yediden yetmişe çoğu müptela

Bayrağı elinde koşar bu sevda

Mevcut yaraları sarana kadar

El ele hedefe varana kadar

Koşar adımlarla Turana kadar

Bütün hudutları aşar bu sevda

Yüksekte tutarak milli şuuru

Gönlümüze ışık İslamın nuru

Tanımadan hiç bir engeli suru

Yıkarak bendini aşar bu sevda

Mikdatî bu bayrak yere inmeden

Koşarız bu yolda geri dönmeden

İçerden içerden yanıp sönmeden

Ölmüyor yaşıyor çoşar bu sevda', 'Nice canlar verdik bitmedi hala Taptaze dipdiri yaşar bu sevda Yediden yetmişe çoğu müptela Bayrağı elinde koşar bu sevda Mevcut yaraları sa...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sevda-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ele Seviremki', 'seni-ele-seviremki-zinnur-tiryaki-ww5te', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni Ele Seviremki

Diyecahsan Niye? Bennam İşde Ele.

Seni Görende Yüregim Bir Hoş Olir,

Yanir,Yanir Dutuşir.Diyirsenki Niye? İşde Ele.

Ahşam Olir,Davar,Nahır Mal Gelir.

Sayiram Sayiram Biri Ekşik.Birde Dönirem Sen Yohsan.

Gine Diyirsen Ki Niye? Ne Bilim İşde Ele.

Sekide Ekmek Yiyirem.Lavaşi,Civili Dürüm Edirem.

Kıtliram.Boğozumda Dügümlenir.

Sen Ahlıma Gelirsen.Gine Diyirsen Ki Niye? İşde Ele.

Anam Örtüleri Sarir.Yataceyıh,Mahcuplaniram.

O Da Gidirya Külli Beçare Galiram.

Sahın Deme Niye? Bennam, İşde Ele.

Guşluğa Doğri Daliram.Hayal Gurmuş,Rüyada Görmüşem.

Sen Bennensen.Sevinmiş,Sevinmiş,Tergan İçinde Galmışam.

Birde Uyaniram Yasdığa Sarılmışam.

Ama Deme Niye? Ne Bilim İşde Ele.

Sabağınan Horozlar Ötir,Gahiram.Bir Cigara Yahiram

.Tavuhlara,Culuhlara Yem Verirem.Tutduğumi Öpirem.

Seni Culuhlara Bile Benzedirem.

Diyecahsan Niye? Ne Bilim İşde Ele.

Babam Beni Gapiya Goymir Diyirsen.Ey Helt Yiyirsen.

Ahşama Geder Goni Gomşiyi Gezirsen.

Ezen,Bibin,Emin Gile Gidirsen.İsdesen,Bene Görünürsen.

Madem Ele Gapiya,Cama Hatta Tırhıca Çıh.

Yüzün Görim.Görimde Orda Ölim.

Diyirsenki Niye? Ne Bilim İşde Ele.

Şair: Zinnur Tiryaki', 'Seni Ele Seviremki Diyecahsan Niye? Bennam İşde Ele. Seni Görende Yüregim Bir Hoş Olir, Yanir,Yanir Dutuşir.Diyirsenki Niye? İşde Ele. Ahşam...', ARRAY['Türk Edebiyatı','Şiir','Zinnur Tiryaki']::text[], 8.5, '{"poet":"Zinnur Tiryaki","poet_slug":"zinnur-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-ele-seviremki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-mustafa-bilgili-7vjla', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gelir katlanılmaz acılara düşersen eğer,

Beni hatırla,yapabilirsen eğer sadece gül geç,

Benim çektiğim acıları bir düşün hele,

Hele,hele benim yandığım ateşleri bir düşün,

Hiç kimse benden daha çok yanamaz,

Hiç kimse benim gibi acıda çekemez,

Sen bile olsan nihayetinde.

Bir gün gelir mutluluktan uçarsan eğer,

Beni hatırla,daha da çok mutlu ol gülüm,

Bende bir zamanlar çok  çok mutluydum,

Bu kara sevda ateşlerine atılmadan önce,

Yerlere göklere sığdıramazdım sevgimi,

Hiç kimse benim mutluluklarımı yaşayamaz,

Sen bile olsan nihayetinde.

Bir gün gelir kararsızlığa düşersen eğer,

Beni hatırla gülüm,sadece gül ve geç,

Benimde kararsız kaldığım günler oldu,

Yaşamla ölüm arasında sürekli gidip gelen,

Ben yaşamayı seçtim her defasında,

Mutsuzluğu yenmek için ümitlerim vardı,

Sende yaşamayı,mutluluğu ve aşkı seç gülüm

                                                            07.03.1997', 'Bir gün gelir katlanılmaz acılara düşersen eğer, Beni hatırla,yapabilirsen eğer sadece gül geç, Benim çektiğim acıları bir düşün hele, Hele,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-hatirla-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha neyim olacaktın', 'daha-neyim-olacaktin-abdulvahap-altay-su2k0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '**neyim olacaktın**

              Daha neyim olacaktın ey yarim,sevdamdın benim,

        yaşama sevincim,umudum,köhne dünyamda kırılmayan direncim,

        ilk göz ağrım kara sevdam, yarimdin benim, 

       ışık sızmayan gecelerde aydınlığım

   ,içine sırlarımı sakladığım sandığım,

        kalbinde sevdamı   büyütüğüm varlığımdın,

      

            daha neyim olacaktın vefasız, 

           havasızlığımda nefesimle alıp  rahatladığım

        dardayken ferahlığım,uğruna bütün gençliğimi harcadığımdın benim

  ,Denize düşenin yılana sarıldığı gibi sarılmıştım    sana....

               sendin ceylan bakışlım üzerine ağıtlar sevda türküleri yaktığım,

       memnu meyvam,kara sevdam,uğrunda destanlar yazdığım vazgeçil-

       mezimdin benim,,,,

      varmıydı bırakıpta gitmek,varmıydı seveni heder etmek,

       hangi sevda kitabında yazılıydı kalbi söküp götürmek,, 

      varmıydı ulan erkekçe duygularla alay etmek

  ,sana ne vermedim''ki ey zalim, dünyadaki yegane varım 

       şerefim, namusum, arım,uğruna öldüğüm yarımdın....

      sendin ceylan bakışlım üzerine ağıtlar sevda türküleri yaktığım

 , memnu meyvam kara sevdam,uğruna destanlar yazdığım,

          sendin,

       sen yanımdayken hangi bela, hangi musibet direncimi kırabilir,

    hangi insan sana olan duygularıma yaklaşabilirdiki

  ,benden ne ummadın da gittin ey zalim, 

      hani yarim  olacaktın,bana benim sevdamla bağlanacaktın

 ,aşkımıza benim gözümle bakacaktın

   ,belki beni o zaman anlayacaktın, 

     vefasız

                  demekki olmuyor gidiyorsun,demekki sevdamı eziyorsun,

         mademki kolumu kanadımı kırıyorsun,git o zaman durma git,

               artık benim için hiç bir şey ifade etmiyorsun...........

                     3-7-2004

                                                                                              abdulvahap altay', '**neyim olacaktın**               Daha neyim olacaktın ey yarim,sevdamdın benim,         yaşama sevincim,umudum,köhne dünyamda kırılmayan di...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Altay']::text[], 8.5, '{"poet":"Abdulvahap Altay","poet_slug":"abdulvahap-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/daha-neyim-olacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Dilki', 'ali-dilki-sedat-kocabey-5sfd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hicivlerin ustasısın,

Yok üstüne bilesin ki,

Doğruluğun hastasısın,

Çağdaş şair Ali Dilki.

Kaleminin ucu keskin,

Yazdığında yoktur riskin,

Uyumazsın miskin miskin,

Çağdaş şair Ali Dilki.

Şiir ile yaşıyorsun,

Satırlarla coşuyorsun,

Her yarayı kaşıyorsun,

Çağdaş şair Ali Dilki.

Haklıları övdüğün çok,

Hak edeni dövdüğün çok,

Kaleminle sövdüğün çok,

Çağdaş şair Ali Dilki.

Bilemedik kıymetini,

Yapmayız da gıybetini,

Bilen bilir heybetini,

Çağdaş şair Ali Dilki.

İşkembeden atmıyorsun,

Çamurlara batmıyorsun,

Dostunu hiç satmıyorsun,

Çağdaş şair Ali Dilki.

Gazetede köşen güzel,

Bakıyorum neşen güzel,

Şanslı sana düşen güzel,

Çağdaş şair Ali Dilki.', 'Hicivlerin ustasısın, Yok üstüne bilesin ki, Doğruluğun hastasısın, Çağdaş şair Ali Dilki. Kaleminin ucu keskin, Yazdığında yoktur riskin, U...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ali-dilki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşsana..!', 'konussana-yalcin-giray-kaya-kzhkl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceleri gelirdin eskiden, çocuktum..

Yıldızların bana gülen yanlarını damağımda gezdiremez,

ufuksuz kalmak adına güneşin uykusuna düşman kesilir,

ve çift kat yorganın altında kölen olurdum.

Artık gündüzlerim de senin..

Attığım her adımda, kalbimdeki tedirgin titreyişlerin

gözlerime evham çekiştirdiği göl kararı bakışlarım

ve kurmayı unuttuğum hayallerim, senin.

Başlangıçlarım oldun sen hep benim..

Ve hep bir adım ilerisine gitmeye cesaret edemediğim başlayışlarımın

etrafına dikenlerinle yatıp,

kararsızlıklarımın üzerine biçimsiz suların namahremi gibi sıçradın.

Sen tutsak öfkelerimdeki açlığımsın..

Parçalanmış haklarımın elime yapışan izole namus lekelerini

gözyaşlarıma azımsayan, içimin avaz avaz susan çığlısın.

Dişisin..

Ama alımlı halin de yok senin..

Aynada kendimi göremeyecek kadar içime saklandığım zamanlarda

şeytan rüküşlü cilvelerin, karanlığıma ancak senin kadar çirkin gelirdi.

Kılığımdaki eğretimdin, yapıştın bana..

Ateşimden uzak bıraktığım yalnızlığımı nefesimle ısıtmaya çalışırken,

kaçırdığım vedalara namussuzca peydah olan onursuz sevgilimdin.

Günahlarım kadar vefalıydın..

Tebessümün etrafında toplanıp,

keyfi, aymazlığımın en çığırsız haliyle ayağımda salladığım vakit bile,

bana gelen sana dair bir şeylerimdin.

Hep sustum, hatırsızlığına kahrımdan..

İhtiyacına süzüldüğüm hevesli kalabalıklar

soru şeklinde üzerime geldiklerinde bile, boğazımdaki düğüm yetişirdi,

suskun duruşlarımın cenaze merasimlerine

ve ben seni yutkunurdum.

………………………………………………….

Bırak da artık ben de kaybolayım karanlıklarda..

Ben de mağlup olayım üç beşine küfrün..

Terk edileyim düşe kalka, bağrım yarı çıplak, dumanlı..

Kayıplığın dillere dolansın ve ben kayıp düşeyim ayyaş çukurlara..

Acılardan pay alayım..

izin ver yaşayayım.

Sırılsıklam sensizlik çekiyor canım..

Sivri uçlu dostluğun,

müşteri kılıklı sevda suretiyle beni sarmaladığın bu bilimsel aşk bitsin n’olur,

razıyım bir bakışlık hayata (sensiz) .

…………………………………………

Yarım kalmış bir sevmenin kulpundayım şimdi..

Ama biliyorum,

oksijeni formülüyle yuttuğum, baharlara kapaklandığım,

omuzlarıma deli yanlarımdan kalma kükreyişler giydirip,

ceplerimi ünlemlerine şaşıramadığım meftut umutlarla doldurduğum

bir zamanda yine geleceksin...

……………………………..

Ne susuyorsun…? 

Konuşsana…! 

Korkuyorum sesini özlemekten...!', 'Geceleri gelirdin eskiden, çocuktum.. Yıldızların bana gülen yanlarını damağımda gezdiremez, ufuksuz kalmak adına güneşin uykusuna düşman ke...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Giray Kaya']::text[], 8.5, '{"poet":"Yalçın Giray Kaya","poet_slug":"yalcin-giray-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/konussana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsim Koyamıyorum', 'i-sim-koyamiyorum-figen-aydogmus-zx5s3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını koyamadım henüz

Bilinmez diyorum şimdilik

Bu kıramp neden girdi kalbime

Anlamak zor 

İmkansız değil ama

Yıkılıyor üstüme caddeler boyu binalar

Kaçışlar yaşıyorum dünden

Yokuşlar daha dik

Soluk soluğa çıkışlardan iniyorum yuvarlanarak aşağa

Birşey, isimsiz vuruyor kırbacını

Canım acımıyor da kızıyorum kendime

Neden beni buldu diye

Neden çekiyorum bu kahroluşu

Yıkılıyor, koskoca bedenim bir sözle

Oracıkta yumru olup kalıyorum

Caresiz.

Zavallı.

Bir kör düğüm atılmış üstüme çözemiyorum

Gözlerim bulanık göremiyorum', 'Adını koyamadım henüz Bilinmez diyorum şimdilik Bu kıramp neden girdi kalbime Anlamak zor  İmkansız değil ama Yıkılıyor üstüme caddeler boyu...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isim-koyamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandık...', 'sandik-i-brahim-ethem-bingul-xlh51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski çamaşırları,

Sandıktaki hatıraları

Ortalığa çıkardım da

Baktım, ne var ne yok diye...

Çok ilginç,

Sen hep varmışsın

Hiç değişmemiş

Ve aynen kalmışsın...

www.iebingul.com', 'Eski çamaşırları, Sandıktaki hatıraları Ortalığa çıkardım da Baktım, ne var ne yok diye... Çok ilginç, Sen hep varmışsın Hiç değişmemiş Ve a...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sandik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgiler', 'cizgiler-deniz-yavuz-tyjxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen kendi yolunu kendin çizdin

Ben senin çizgilerinle kesişmeyi bekledim

Ve sonra

Ben kendi eğrimi kendim çizdim

Hiçbir gün, hiçbir yerde

Hiç kimseyle

Kesişmeyeceğini bile bile...', 'Sen kendi yolunu kendin çizdin Ben senin çizgilerinle kesişmeyi bekledim Ve sonra Ben kendi eğrimi kendim çizdim Hiçbir gün, hiçbir yerde Hi...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yavuz']::text[], 8.5, '{"poet":"Deniz Yavuz","poet_slug":"deniz-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cizgiler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-sacide-yaylaz-6iavw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasreti anlatırım ben dinlerim 

Aşkınla yanar ah eder inlerim 

Soldu bak bahçem de açan güllerim 

Vefasız yar söyle şimdi nerdesin. 

İnan sevgili seni çok özledim 

Gittin sen ben bir daha hiç gülmedim 

Düşledim çok hayalini görmedim 

Vefasız yar söyle şimdi nerdesin

Geçse de yıllar, ben seni beklerim.

Kor ateşlerde, yansa da yüreğim.

Yine seni sevdiğimi söylerim.

Vefasız yar, söyle şimdi nerdesin.', 'Hasreti anlatırım ben dinlerim  Aşkınla yanar ah eder inlerim  Soldu bak bahçem de açan güllerim  Vefasız yar söyle şimdi nerdesin.  İnan se...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Derin ki', 'oyle-derin-ki-ercan-agtas-nqlc1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yokluğun

buzdan kesiyor tenimi

sensizliğim oluyor

ellerime

damla damla akıtıyor geceyi

uykusuzluğum oluyor

öyle uzak ki

şimdi elllerin

yıldızlara uzanırcasına

ellerim ellerine uzanıyor

gecenin alaca karanlık kuşağı

bir kırlangıcın kanatlarında çırpınıyorum

ilk güz yağmurları gözlerin

gözlerinde ıslanıyorum

ve toprağın kestane rengini soluyorum

öyle derin ki

şimdi gözlerin

gözlerinin kıyılarında boğuluyorum

ve zaman aynaları gecede kırdı

yüreğime yaprak yaprak sensizliğini yansıttı

ve zaman aynaları yine gecede kırdı

tenime toprak toprak sensizliğini akıttı

öyle bir çoşkuyla soyundu ki

ağaçlar sevdalarını

ve bütün umutlarını

sensizliğin kokusunu tenime bırakırcasına

sonbaharın hüzünlü kollarına bıraktı

herhanbirzaman/herhangibirdörtduvar', 'yokluğun buzdan kesiyor tenimi sensizliğim oluyor ellerime damla damla akıtıyor geceyi uykusuzluğum oluyor öyle uzak ki şimdi elllerin yıldı...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oyle-derin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şemdinli''de Bir Sabah...', 'semdinli-de-bir-sabah-ugur-deniz-ulkegul-gxq3g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölümün en güzel haliydi belki

Bakışlarında donup kalmıştı tebessüm

Üç yaşında bir gonca, taze gül kokusu

Namlunun ucunda can veren masum..

Hiç bir günahın dokunmadığı ten

En mavi düşlerin pervasız tutkusu

Toprağa aykırı, mezara sığmaz beden

Gözlerinde okunan o son bakış korkusu..

/Çünkü namluya tapan eller

Kutsanmış muzafferiyetler aradı..

Dağları yurt edindi ötekiler

Yol kesti Halo, Hüseyin’i taradı…./

Vakitsiz geldi haberin

Daha dün mektubun vardı buraya

İzin günü yakın, siz yolumu gözleyin

Haber salın demişsin, kardeşim Mustafa’ya..

Sen ki, ölmek kolay iş derdin

Bu zor’a nasıl dayanılır sevdalım? 

Aklım başımda değil, yüreğim yangın

Şimdi yola savrulmuş kırık bir dalım….

/Çünkü okyanus ötesinden bir ses

Kulağına fısıldadı soysuz Eylül’ün..

Yaprak dökümüne gebe alınan nefes

Kavurdu gövdesini açılan gülün……/

Utandık insan olmaktan

Kar değildi yolları kapatan beyim

İsimsiz doğup sürgün yaşamaktan

Yoruldu vurdukça vurulan yüreğim..

Buralarda bomba sesiyle başlar gece

Kundakta bebeler kin büyütür koynunda

On beşinde ölüm kusar dudağındaki hece

Yirmisinde uslanmaz bir eşkıyadır yurdunda..

/Çünkü Şemdinli’de bir sabah

Tahrik gücü yüksek sesler duyulur..

Sinsi bir pazarlık kapı ardında

Bir orospu tavrıyla üzerini soyunur…/

Hangisi dost, hangisi düşman

Çölemerik yaylasında kim kimi vurur? 

Konuştukça suç, sustukça pişman

Öldükçe kahraman denir durulur……

Bu nasıl devran, bu nasıl düzen

Çanakkale oradan bakar da durur

Hiç mi yoktur etrafta aklıyla gezen

Şehitler diyarında, hayın sorulur…

/Çünkü ucuzdur bu ülkede can

Saltanat içinde dolaşır durur iblis

Bir elin parmağından süzüldükçe kan

Sırıtır kendini doğrayan beyinsiz…/', 'Ölümün en güzel haliydi belki Bakışlarında donup kalmıştı tebessüm Üç yaşında bir gonca, taze gül kokusu Namlunun ucunda can veren masum.. H...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/semdinli-de-bir-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldin', 'geldin-serap-mutlu-ec1y2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geldin…

en dar yerinde karanlığın... 

iklimi değişti gecenin...

uzak bir ezgiydi sabahlar... 

gözlerin uzak sabahların örtüsüydü 

uyanırken toprak...

gözlerin uzak sevdaların düşü…

gözlerin sessizliğin gülüşü...

sevmeyi öğrenmeden dokunmayı öğrendin... 

yürümeyi bilmeyen bir çocuğun koşar adımları gibi

eksik, ürkek akıyordu ellerin ellerime... 

ellerin ellerime çoğalıyordu

sıcaklığını duyuyordum...

içimde bir yalnızlık ölüyordu...

sevgiye soğuyordu ellerim...

derinlerime bir korku siniyordu...

bir korku sancıma doğuyordu,

bir korku aklıma ürüyordu...

oysa dokunuşunda ağlamak isterdim...

hissetmek isterdim parmaklarının ucundaki sancıda,

yüreğine hapsedemediğin, 

söz dinletemediğin sevgini... 

hissetmek ve göz yaşlarıma eklemek isterdim.... 

geldin…

en tarafsız yerinde yalnızlığın... 

bir gölge akıyordu geceye... 

sesin yerleşiyordu kuytularıma, soluğun, kokun... 

ilmek ilmek çoğalırken, 

yolunu çizerken karanlığa, 

ayaklarım çırılçıplak, 

ellerim telaşa vermiş ateşi...

gözlerim hazırlığında uğurlamanın, 

yüreğim yalnızlığın suskunu...

geldin…

en yorgun korkularında sevdanın... 

yitik ateşler yanıyordu dağlarda....

kır çiçeklerine ölgün sisler sarıyordu şehri... 

kısır bir çığlık yayılıyordu... 

zaman acıya gebe... 

zaman susuyordu...

geldin…

gidişinden korkutarak düşlerimi... 

oysa ben seni nasıl sınırsızca... 

oysa ben seni nasıl umarsızca...

oysa ben seni nasıl korkusuzca sevmek isterdim... 

sevmek ve biriktirmek yalnızlığıma....', 'geldin… en dar yerinde karanlığın...  iklimi değişti gecenin... uzak bir ezgiydi sabahlar...  gözlerin uzak sabahların örtüsüydü  uyanırken ...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/geldin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli şirk', 'gizli-sirk-ali-riza-unal-fcdgi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne gariptir nefsi heva,put olur gider-

bin başa buyruk,küt olur gider-

bir zan-ı yücelik sarar vehmi varını-

Halıka agyar,zıt olur gider.', 'ne gariptir nefsi heva,put olur gider- bin başa buyruk,küt olur gider- bir zan-ı yücelik sarar vehmi varını- Halıka agyar,zıt olur gider....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gizli-sirk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyor muyduk?', 'yasiyor-muyduk-serap-mutlu-m2kzk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşıyor muyduk? 

Yoksa yaşam mı bize ölüyordu? 

Islak mıydı gözlerin, ellerin sıcak mıydı? 

Günün bir vakti aklıma düşüyordun

Gözlerimi gülüyordum

Her şey aykırı bir tarafıydı yaşamın

Sen düşlerimde çoğalıyordun

Yüreğini vuruyordun düşlerime

Güneşli bir gün gibi doğuyordun içime

Sana uyanmak istiyordum

Uyanmak ve bir daha uyumamak 

Toplayıp sevdamı, özlemimi 

Kaçıyordum yorgun ufuklara

Bir renk ezgisi oluyordun

Yine sen oluyordun

Oysa ben yaşamı böyle sevdalamıyordum

Pırıl pırıl giriyordun düşüme

Yıldızları kıskandıracak güzellikte

Sarıyordum büyüyordun

Gün geçtikçe, duydukça, gördükçe...

.........

Korkarım gözlerimden fışkıracaksın bir gün

Fışkıracaksın da yer gök senle dolup taşacak

Ve hiçbir şey kalmayacak sana ait olmayan

Gözlerimin önünde...

Gözlerimi kapıyorum, kapıyorum...

İçiiimmmm....

Yağmurlu bahar türküleriyle

İçiiiiimmmm...

Çocuk sevinçleriyle

İçimmm..... 

Senle Doluyor', 'Yaşıyor muyduk?  Yoksa yaşam mı bize ölüyordu?  Islak mıydı gözlerin, ellerin sıcak mıydı?  Günün bir vakti aklıma düşüyordun Gözlerimi gülü...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yasiyor-muyduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-ercan-agtas-dh35e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gece siyah bir mermer

yüzünde buzdan düşler gezer

gece kaygısızca kayıp bir esmer

teninde ılık yeller eser

birazdan erir 

buzdan düşler

siyah mermerin yüzü bulanır

kaygısız esmer kayıplara karışır

gece kara bir kadındır

kolları uzun bedenlere uzanır

gece sessiz pervasız bir pencere

sarhoş dalgalar gibi gider ve gelir

bazen de ayak diretir

gelir ve gitmez

işte o zaman gece 

yatıya gelmiştir

herhanbirzaman/herhangibirdörtduvar', 'gece siyah bir mermer yüzünde buzdan düşler gezer gece kaygısızca kayıp bir esmer teninde ılık yeller eser birazdan erir  buzdan düşler siya...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-218-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum!', 'korkuyorum-serap-mutlu-vnl3l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkuyorum sevdiceğim

Korkuyorum işe yaramaz bir yürek gibi

Rezil, küçük, iğrenilesi bir böcek gibi

‘’yakışmıyor sana’’ diyorsun biliyorum

ya ben, ben değilim? 

Biryerlerde kaldım tutsak

Yada ben hiç olmadım? 

.........

Çirkinlerim çoğalıyor

İsyanlarımı tutamıyorum

Çocuklar gibi ağlamak

Ahhh ağlamak... yüreğimi parçalamak

Çaresizliğimi haykırmak

Bağırmak sevgimi? 

Duymayışların geliyor aklıma

İnanmayışalrın, görmeyişlerin

Susuşun diyorum, susuşun..

Rezil korkulu

Siniyorum kuytularıma...

Bu kör karanlık daha ne kadar? 

Daha ne kadar var terkedişine?', 'Korkuyorum sevdiceğim Korkuyorum işe yaramaz bir yürek gibi Rezil, küçük, iğrenilesi bir böcek gibi ‘’yakışmıyor sana’’ diyorsun biliyorum y...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korkuyorum-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a', 'ask-a-mesut-sutcu-gs1ia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Attılar beni aşk kuyusuna,

Götürdüler yare kanlı yüreğimi.

Bir ip uzanır mı kör karanlığa,

Çıkarsalar benden benliğimi.

Alsalar satsalar da ne gam,

Erişmek varsa yar toprağına.

Mısır''a sultanlık boş makam,

Talibim gözündeki zindana.', 'Attılar beni aşk kuyusuna, Götürdüler yare kanlı yüreğimi. Bir ip uzanır mı kör karanlığa, Çıkarsalar benden benliğimi. Alsalar satsalar da ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-a-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-suleyman-demir-668te', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'n''olur beni de alın,beni de aranıza,

bahar aydınlığında  kalamam ki geceler! 

yemin olsun Allaha dokunmam yaranıza,

sizden başka da yaren bulamam ki geceler! 

yolun sonuna kadar yürüsem cadde sokak,

alır mısınız beni,bir mezarda buluşsak? 

bu fani sevdalıya kalmadı açık kucak,

bundan sonra da çocuk olamam ki geceler!', 'n''olur beni de alın,beni de aranıza, bahar aydınlığında  kalamam ki geceler!  yemin olsun Allaha dokunmam yaranıza, sizden başka da yaren bu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kacis-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dans', 'dans-guler-ilgaz-bqvax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şükürler olsun

Endişelerimden uzakta

Güneş doğdu ya

Korkularımla içiçeyken

Ay doğdu ya

........................................

Şükürler olsun gözlerime

Güneşi doğarken

Ayı batarken

Aynı anda

Gördüm ya

İçimin içime sığmadığı anda', 'Şükürler olsun Endişelerimden uzakta Güneş doğdu ya Korkularımla içiçeyken Ay doğdu ya ........................................ Şükürler ols...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dans-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Didem...', 'didem-ali-baksi-e8zwh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karadır gözleri ellerden

Bırakır varmadan uzakları

Burgu saçları tellerden

Sözleri dokunur içime 

Acıdan uzak düşlerde

Yıkar sözleri görmeden

Benleri yaşamadan

Gider bir başına 

Gittigi ben olurum

Uzaklara...

Nefesi uzundur boyundan

Savurur rüzğar gibi

Kokusunda kalırım ben

Yaşayamadıgım teninde

Sıcak ve soguk

Kelimeler iyi gelir

Yaşlansada bir gün daha...', 'Karadır gözleri ellerden Bırakır varmadan uzakları Burgu saçları tellerden Sözleri dokunur içime  Acıdan uzak düşlerde Yıkar sözleri görmede...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/didem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-ercan-agtas-tkg0b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen yoktun

sensizliğe sensiz yattı

dalgaların kırpaçlarıyla kıyıya vurdu bedenim

sen yoktun

yürekte gece yandı

şu karşiki dere boyu uzanan ağaçların dallarında

titredi yalnızlığım

senle giden kendim

bu benim bende ölümüm

sen yoktun ki

kaç gece dar ağacına

gitti gitti geldi ellerim

kaç gece idamları astım boynuma

her gece bir işkence sesi

her gece bir çığlığın

yüreğimde acı acı iniltisi

sen yoktun

Picasso''nun anılarını ölümsüzleştirdi

saçlarının uçlarına yıldızları çizdi ellerim

sen yoktun

sıvası çürümüş binaların duvarlarında

gezindi gözlerim

senle giden kendim

bu benim bende ölümüm

sen yoktun ki

kaç gece dar ağacına

gitti gitti geldi ellerim

kaç gece idamları astım boynuma

her gece bir işkence sesi

her gece bir çığlığın

yüreğimde acı acı iniltisi

herhanbirzaman/herhangibirdörtduvar', 'sen yoktun sensizliğe sensiz yattı dalgaların kırpaçlarıyla kıyıya vurdu bedenim sen yoktun yürekte gece yandı şu karşiki dere boyu uzanan a...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-yoktun-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Şiir', 'en-guzel-siir-mesut-sutcu-cguuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gözlerimde pırıltı,

Yüreğimde coşkun bir nehirsin.

İçimde gittikçe büyüyen

Koca bir şehirsin.

Ben aşkının şairi,

Sen, bildiğim

En güzel şiirsin.', 'Sen gözlerimde pırıltı, Yüreğimde coşkun bir nehirsin. İçimde gittikçe büyüyen Koca bir şehirsin. Ben aşkının şairi, Sen, bildiğim En güzel ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-guzel-siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Bey', 'hakim-bey-eren-caglar-niron-xr0bp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çaldı diyorum,çaldı benden.

Hayır, hakim bey şikayetçi değilim.

Sen göremezsin onda saklı kalbim.

Sen bilemezsin nasıl rüyalar görmekteyim…

Şikayetçiyim hakim bey! 

Kitaba, kanuna gerek yok,

Siz onu bana mahkum edin…

Eren Çağlar Niron

2001

Adana', 'Çaldı diyorum,çaldı benden. Hayır, hakim bey şikayetçi değilim. Sen göremezsin onda saklı kalbim. Sen bilemezsin nasıl rüyalar görmekteyim… ...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hakim-bey-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyada', 'ruyada-suleyman-demir-0j0kq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bahar gelmiş,yaz gelmiş,dallar yeşil ne çare? 

karlı,buzlu,zemheri bir kış kalmış içimde! 

zindana döndü yürek kime gitsin biçare? 

kırık kanatlı,garip bir kuş kalmış içimde! 

sormayınız ki nedir bu sebeb-i efkarın,

kapkara iki gözden bakış kalmış içimde! 

yetmiyor gülüşmeye cıvıltısı baharın,

kaf dağına giden bir yokuş kalmış içimde! 

gitmek vakti gelse de bu kasvet dünyasından,

zehirli bir dudaktan öpüş kalnış içimde! 

nerde uyanır bilmem bu gönül rüyasından,

duman duman dağılan bir düş kalmış içimde!', 'bahar gelmiş,yaz gelmiş,dallar yeşil ne çare?  karlı,buzlu,zemheri bir kış kalmış içimde!  zindana döndü yürek kime gitsin biçare?  kırık ka...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruyada-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silik Bir Zaman', 'silik-bir-zaman-serap-mutlu-x1aiu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ormansın...

Vaktiyle kızıl yangınlar barındırmış yüreğinde... 

Güneşin, toprağın yüzüne muhtaç bir ormansın... 

Yemyeşilliğin akıyor en kurak yerine sevdanın... 

Saflığın kokularını tutukluyor... 

Çam kokusu, bahar serinliği akıtıyorsun sehere...

Genzimde yanık bir koku kalıyorsun...

Bazen derin bir denizsin...

Onca çoğalan balıklara, istiridyelere inat,

Gidildikçe en kuytularına 

Maviliğinin sessizliğinde ürpertiyorsun...

Dalgaların ateşe veriyor kumsallarını köpük köpük... 

Beyazında boğuluyor günler, geceler usulca...

Usulca kanat çırpıyor bir martı,

Yakamozlarının pırıltısını yazıyor en sancılı yerine zamanın...

Bazen bir volkansın...

En sinsice yerinde alışılmışlığın,

Alev alev yakıyorsun sevinçlerini... 

Çözülüyor buz zindanlarında hapsolmuş düşlerin... 

Kanıyor yaraların kaldığı yerden...

En acılı bilinmezliğe ışıldıyorsun...

Bazen küçücük bir çocuk...

Büyümeyen yanlarının yarım düşleri, 

Eksik dillerinin uçurtmalı gülüşleri, 

Terkedilmiş bir oyuna koşuyorsun...

Bazen yoksun... 

Ürkek kuytularını vuruyorsun olmadığın yerlere... 

Alev gözlerini yakıyorsun, 

Korkularını yazıyorsun bildiğime...

İsyanlarını içime eziyorsun...

Olmadığının karanlığındayım şimdi

Kalabalığının gürültülü yalnızlığı korkutuyor beni 

Adımlarımı gizliyorum düşlerime 

Saklıyorum en yıldızlı gülüşlerimi

En saklı saatlerime korkuyorum 

Gizemli dile gelişlerini düşünüyorum...

Sen geldin ya...

Her şey geliverdi ardın sıra... 

Yüzlerce sözcük döküldü dillerime... 

Yüzlerce anlam oldun düşüncelerimde....

Şimdi bennnn.....

Hangisini konuşsam kolay olurdun? ? ? 

Yaniii hangi anlama sığdırsaydım seni...

Şimdi ben...

Aklımın, duygularımın kesmediği 

Silik bir zamana ilerliyorum....

Şimdi ben...

Korkuyorum....', 'Bir ormansın... Vaktiyle kızıl yangınlar barındırmış yüreğinde...  Güneşin, toprağın yüzüne muhtaç bir ormansın...  Yemyeşilliğin akıyor en ...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/silik-bir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-suleyman-davut-kenanli-e2rjn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üç güneş dönüşü bu dert bende

yok olan çelik balyoz ensemde

zincirle çevrilmiş bu bedende

kader der bekleriz ezelde

çift ay dönüşü dolunaylı gece

gel git ler yaşanır içlerimde

kelimeleri eler kalburdan hece

mühürler vurulur kısmete kadare

tek dünya dönüşü ellerim gökte

çıkış isterim beklerim bende

kelepçeler vurulur ezelden ebede

koyu buhranlı karanlık mahsene', 'üç güneş dönüşü bu dert bende yok olan çelik balyoz ensemde zincirle çevrilmiş bu bedende kader der bekleriz ezelde çift ay dönüşü dolunaylı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Davut Kenanlı']::text[], 8.5, '{"poet":"Süleyman Davut Kenanlı","poet_slug":"suleyman-davut-kenanli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutsak-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbüle Tavsiye(1 Beyit)', 'bulbule-tavsiye-1-beyit-fikret-polat-erzum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ne avaz, ne bu feryat, zorun ne bülbül

Kara toprak üzerinde gülden gayrı çiçek mi yoktur', 'Bu ne avaz, ne bu feryat, zorun ne bülbül Kara toprak üzerinde gülden gayrı çiçek mi yoktur...', ARRAY['Türk Edebiyatı','Şiir','Fikret Polat']::text[], 8.5, '{"poet":"Fikret Polat","poet_slug":"fikret-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bulbule-tavsiye-1-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar', 'aglar-suleyman-davut-kenanli-474nx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimden değil yaş,gönlümden akar

dışlarım güler,içlerim ağlar

tükenmiş bir hırs,hevesi dağlar

derdi yalnız çeken anlar', 'gözlerimden değil yaş,gönlümden akar dışlarım güler,içlerim ağlar tükenmiş bir hırs,hevesi dağlar derdi yalnız çeken anlar...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Davut Kenanlı']::text[], 8.5, '{"poet":"Süleyman Davut Kenanlı","poet_slug":"suleyman-davut-kenanli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aglar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Çelişkisi', 'sen-celiskisi-mesut-sutcu-hkxbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üşüyorum yine,

Alnımı öpen soğukluk sen misin? 

Saçlarımı okşayan rüzgar,

Göz kapaklarımdaki ağırlık,

Uykularıma gardiyan...

Ya da varla yok arasında düşlerden misin? 

Sahi sen bu alemden misin? 

Kelimeler gibi,

Nefesler de düğümleniyor boğazımda.

Ve ellerimdeki malum titreyişler.

Ah şu zalim tuhaflığım,

Nihayetsiz kaygılarım.

Bir de aklımı zorlayan o keskin sorular:

İçimde yitip giden biri mi var

Yoksa sen kaybettiğim ben misin? 

Uzaklar mı? 

Bak, ilerde uzanan bir çizgi.

Uzaklara vardıkça uzaklaşılır bir yerlerden

Ve arayışlar nice kaybedişlerdir belki.

Anla ki çelişkilerle doluyum

Çürümüş umutlarla.

Tedirgin de olsa yaşıyorum işte...

Bulamadım hala soruların cevabını,

Dur sakın söyleme! 

Ben, masallardaki meydana atılmış

Eli kolu bağlı bir suçlu; 

Sen de

Beğenmem gereken ölümlerden misin? ..', 'Üşüyorum yine, Alnımı öpen soğukluk sen misin?  Saçlarımı okşayan rüzgar, Göz kapaklarımdaki ağırlık, Uykularıma gardiyan... Ya da varla yok...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-celiskisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aksaray', 'aksaray-umit-tuna-5soeo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boyumuzca başakların arasında,

Bazen arpa bazen buğday tarlasında,

Daha küçüktük büyüdük oralarda,

Babam çobandı benim,

Anam gündelikçi.

Babamın peşinde gider,

Dağ, tepe demeden koyun güderdik,

Ekmek parası için,

Şafak sökmeden dağlarda gezerdik.

Koyunları kurttan korurduk,

İki lokma için bazen iki gece dağda dururduk,

Biz zorlukların arasında,

Tarla süren anamızla.

Traktör başındaki dedemizle,

Köyün belki en fakir ailesi olsak bile,

Alnımızın teriyle,

Büyüdük koca memleketimizde.

Biz Aksaray’lıkdık,

Arpayı buğdayı hep biz satardık,

Tarladan samanı biz kaldırırdık,

Biz başakların arasında,

Kümesten çaldığımız tavuklarla,

Geldik bu yaşımıza.

Bizim köyde araba yoktu ama,

Köyün en güzel kır eşeği dedemindi,

Semeri atardım ona,

Hemen giderdik köyün çarşısına.

Al yazmalı kızlara bakardım oralarda,

Hepsinde gözüm vardı ama,

Babam çobandı benim,

Anam gündelikçi,

Vermezler ki istediğim kızı.

Ne tarlam var,

Ne de malım,

Ne de seni alacak başlık param.

Her şeye rağmen,

Kanımda Aksaray,

Canımda Aksaray,

Unutmam ben seni canım memleketim.

Ben hep senin taşını toprağını,

Eğri minareni,

Ihlara vadini,

Özleyip durmaktayım,

Ben Aksaray’lıyım! ...

ÇILGIN MUHASEBECİ', 'Boyumuzca başakların arasında, Bazen arpa bazen buğday tarlasında, Daha küçüktük büyüdük oralarda, Babam çobandı benim, Anam gündelikçi. Bab...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/aksaray-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisa', 'nisa-mesut-sutcu-o7smx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çorak topraklara düştü yolum Nisa... 

İsimsiz şehirlerin,gergin caddelerinde 

Bir yığın sancı taşıyor omuzlarım. 

Çorak topraklarda su aramak değildi benimkisi. 

Bir öksüz su damlacığı götürmekti; 

Yazık ki olmadı 

Götüremedim Nisa... 

Öfkeli gözlerin kızgınlığında 

Buharlaşıp uçtu öksüzlüğü rahmetin. 

Şah damarıma kadar hissettim üşüdüğümü. 

Ama caddeleri süsleyen bu ışıklar gibi, 

Üşüyemedim Nisa... 

Hangi savaştı hatırlamıyorum. 

Hangi sürgünden kalma, sırtımdaki izler. 

Yalnızca bir kaç şeyi anımsıyorum: 

Sınırların olmadığı bir dünyada, 

Sosyal kargaşaların mahkum ettiği 

Dev adamların öldüğünü gördüm. 

Haberin yok senin. 

Artık cesetlere heyecanlanmadan bakmayı öğrendim. 

Çürüyüp gitmiş duygularımı gördüm de 

Aralarında kendimi, 

Göremedim Nisa... 

Yeniden sevmek mi? 

Yeniden ölmek olur da, 

Yeniden sevmek olmaz Nisa... 

Kanım çekildi, 

Bütün damarları kurudu yüreğimin, 

Bırakıp gidişinden bu yana. 

Buralara boşuna mı geldiğimi sanıyorsun. 

Mademki sen yoksun: 

O zaman sonsuza dek sensizlik bana. 

Dediğim de oldu. 

Senden sonra kimseyi sevemedim Nisa... 

Anlatmama gerek yok aslında. 

Aşırı dozda narkoz almış duygular, 

Sancısız değişimini yaşıyor hayatlarının. 

Hepimizde mevcut,derin neşter izleri... 

Ne tür ameliyatların kadavrası olduğumuz da meçhul. 

Eskisi gibi kahramanlar da yok artık. 

Herkes kendi filminin figüranı 

Ve artık herkes buralı. 

Bir kısır döngüdeki 

Basit dişlilerden biriyim ben de... 

Yani istediğin gibi olmadı, 

Yapamadım Nisa... 

Görüyorsun ya! 

Çorak topraklara attım kendimi. 

Son trenini de kaçırdım ütopyanın. 

Sensizliğin sonsuzluğunda dolaşıp, 

Leşimi yiyecek akbabalar arıyorum şimdi. 

Yani,canımı senin tükendiğin yola 

Veremedim Nisa... 

Belki esir düşerim, 

İyimser işgallerin birinde. 

Fersizliğimin sorgusuna çekerler beni. 

Cezasını verirler tüm suçlarımın. 

Son sözün imzasına bırakılır her şey... 

Yine de keskin tereddütlerdeyim, 

Yalın kaygılarda... 

Senin acılarını yaşadım da... 

Senin gibi destansı ve yüreklice 

Ölemedim Nisa...', 'Çorak topraklara düştü yolum Nisa...  İsimsiz şehirlerin,gergin caddelerinde  Bir yığın sancı taşıyor omuzlarım.  Çorak topraklarda su arama...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/nisa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ESKİci', 'eski-ci-ercan-agtas-p5yg3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ESKİden

ESKİ bir kulübede 

bir adam yaşarmış

ESKİ sandığından bir gün

ESKİ anılarını

çıkarmış bir bir

ESKİ eşyalarınızı alırım

değiş tokuş yaparım

para veririm

diye bağıran

ESKİciye satmış

ESKİ anılarını

karşılığında da

ESKİ bir palto almış

soğuk havada iyi gelir demiş

üzerine giyinmiş

bir an eli cebine gitmiş

ESKİ bir gazete parçasına sarılı

ESKİ sararmış

saf ipekten

ESKİ bir mendil

avuçlarına gelmiş

cebinden çıkarmış

uzun süre mendile bakmış

dalmış

üşümüş

ESKİciyi aramış

ESKİ anılarına ağlamış

herhanbirzaman/herhangibirdörtduvar', 'ESKİden ESKİ bir kulübede  bir adam yaşarmış ESKİ sandığından bir gün ESKİ anılarını çıkarmış bir bir ESKİ eşyalarınızı alırım değiş tokuş y...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eskici-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezgiler ve Türküler', 'ezgiler-ve-turkuler-ercan-agtas-2dqu5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ezgiler

öyle derinleşseler

....... derinliğime inseler

............................ inseler de derinliğime

............................................... derinleşseler

türküler

öyle yanık söylenseler

................. söylendiğimi işitseler

........................................ işitseler de söylendiklerimi

............................................................. söylenseler

herhanbirzaman/herhangibirdörtduvar', 'ezgiler öyle derinleşseler ....... derinliğime inseler ............................ inseler de derinliğime ....................................', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ezgiler-ve-turkuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müstezat', 'mustezat-hamit-pala-e59r6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sensiz ne yaparım, 

                              ne olur benim hâlim? 

Ağlayıp yanarım; sen

                              nerdesin şimdi yârim? 

Teselli vermez hiç bana

                              herkes olmuş zalim

Ağlayıp yanarım; sen

                              nerdesin şimdi yârim? 

07.02.1998 Van', 'Ben sensiz ne yaparım,                                ne olur benim hâlim?  Ağlayıp yanarım; sen                               nerdesin şimd...', ARRAY['Türk Edebiyatı','Şiir','Hamit Pala']::text[], 8.5, '{"poet":"Hamit Pala","poet_slug":"hamit-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mustezat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '08-Çocuk', '08-cocuk-mehmet-emin-dogan-ynyqa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüğüm lüzum üzere şiirlerimi bu platformdan kaldırdım. Dostlardan özür dilerim...', 'Gördüğüm lüzum üzere şiirlerimi bu platformdan kaldırdım. Dostlardan özür dilerim......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Doğan']::text[], 8.5, '{"poet":"Mehmet Emin Doğan","poet_slug":"mehmet-emin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/08-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Perdelik Oyun', 'i-ki-perdelik-oyun-ercan-agtas-6u5kj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-birinci sahne-

    (perde)       

ağaçlar koşuşuyor durmuyor

ellerim dudaklarına

duruyor

ağaçlar koşuşuyor durmuyor

ellerim yanaklarına

duruyor

-ikinci sahne-

    (perde)       

ağaçlar uçuşuyor uyumuyor

ellerim ellerine 

uzanıyor

ağaçlar uçuşuyor uyumuyor

elllerim tenine 

uyuyor

herhanbirzaman/herhangibirdörtduvar', '-birinci sahne-     (perde)        ağaçlar koşuşuyor durmuyor ellerim dudaklarına duruyor ağaçlar koşuşuyor durmuyor ellerim yanaklarına dur...', ARRAY['Türk Edebiyatı','Şiir','Ercan Ağtaş']::text[], 8.5, '{"poet":"Ercan Ağtaş","poet_slug":"ercan-agtas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iki-perdelik-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsancıl', 'i-nsancil-firat-candir-hw195', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık hiç gülmüyor

Hep ağlıyorum

Bana kızma ne olur

Ağlamakta

Gülmek kadar insancıl...

Artık hissetmiyorum

Hep duyarsızım

Bana kızma ne olur

Acılarda

Mutluluk kadar insancıl...

Artık hiç konuşmuyor

Hep dinliyorum

Bana kızma ne olur

Ölmekte

Yaşamak kadar insancıl...', 'Artık hiç gülmüyor Hep ağlıyorum Bana kızma ne olur Ağlamakta Gülmek kadar insancıl... Artık hissetmiyorum Hep duyarsızım Bana kızma ne olur...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çandır']::text[], 8.5, '{"poet":"Fırat Çandır","poet_slug":"firat-candir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insancil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz Ten', 'siyah-beyaz-ten-tulay-sustam-mgt6f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kendimi bulana kadar

