INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartopu', 'kartopu-yasemin-ayzin-oktxu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sobanyn üstünde kar topu eritirdik.

Annemizden gizli gizli.

Üşüyen ellerimize aldırmazdık.

Keşfetmek istediğimiz; 

Suyla ateşin nasyl dans edebildiğiydi.

Çocuk kalbimiz bilemezdi,

Ateşe değer değmez kaçıp giden damlaların, 

Aşkın yüreğimizde byraktığı izler gibi olacağını.', 'Sobanyn üstünde kar topu eritirdik. Annemizden gizli gizli. Üşüyen ellerimize aldırmazdık. Keşfetmek istediğimiz;  Suyla ateşin nasyl dans e...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Ayzin']::text[], 8.5, '{"poet":"Yasemin Ayzin","poet_slug":"yasemin-ayzin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kartopu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldum', 'vuruldum-mehmet-sait-akkus-n47b3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç yorulmaz sanırdım

Seni sayıklayıp anardım

Hasretine döner yanardım

Gelen geçenden sorardım

Yorulmaz kalemim sanırdım

Hep sesine koşardım

Kağıttan uçaklar yapıp yollardım

Kalemi alıp hep seni yazardım

Bilirdin seni nekadar çok severdim

Düşmez bedenim sanırdım

sevgi yağmuru olup yağardım

Seni her görüşte yeniden doğardım

İçimdeki nefreti boğardım

Sevmem diyen dilleri doğrardım

Yoruldum güzelim yoruldum

Seni özlemekten yoruldum

Sevdana koşmaktan yoruldum

Seni seviyorum demekten yoruldum

İnaki be güzelim

İki çift gözüne

İki talı sözüne

Seni seviyorum deyişine

Yorulmadan vuruldum', 'Hiç yorulmaz sanırdım Seni sayıklayıp anardım Hasretine döner yanardım Gelen geçenden sorardım Yorulmaz kalemim sanırdım Hep sesine koşardım...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vuruldum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lazım', 'lazim-mehmet-sait-akkus-ct7of', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş gibi doğman lazım

Yağmur gibi yağman lazım

Yüreğime akman lazım

Şarp olup içmek lazım

Seni candan sevmek lazım

Gelip seni görmek lazım

Yar uğrunda ölmek lazım

Senin bunu bilmen lazım', 'Güneş gibi doğman lazım Yağmur gibi yağman lazım Yüreğime akman lazım Şarp olup içmek lazım Seni candan sevmek lazım Gelip seni görmek lazım...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lazim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaksan ne olur', 'yaksan-ne-olur-zati-erbas-m4og7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yak

beni

yak 

cehennemin en derin yerinde

ne 

kalır ki

geriye

kendine  benzer surette yaratmışsan eğer

ben

nasıl olsa bulurum bir cennet kendime', 'yak beni yak  cehennemin en derin yerinde ne  kalır ki geriye kendine  benzer surette yaratmışsan eğer ben nasıl olsa bulurum bir cennet ken...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaksan-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy', 'koy-nihal-gungor-7aivq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin acılarını,ağıtlarını,

götürdün gömdün günışıyınca,

bir avuç şehre.

Yüklediğin umutları,

saça saça döndün gün batıncaya.....

bir avuç köye.

               SİİRT-1992', 'Gecenin acılarını,ağıtlarını, götürdün gömdün günışıyınca, bir avuç şehre. Yüklediğin umutları, saça saça döndün gün batıncaya..... bir avuç...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/koy-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı Misali', 'sarki-misali-huseyin-sonmez-naedx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde esen tatlı bir meltem,

Bir gül,bir lâle,bir sümbül oldun,

Dillerden düşmez şarkı misali,

Ruhuma,canıma,kanıma doldun.

Yalnızdım ben, sen gelmeden önce,

Bir umut,bir ışık,sevgi oldun,

Dillerden düşmez şarkı misali,

Ruhuma,canıma,kanıma doldun.

Gönlümde her an bir elif çizen,

Bir sel,bir nehir,bir ırmak oldun,

Dillerden düşmez şarkı misali,

Ruhuma,canıma,kanıma doldun.

Yürek dağında söylenen güfte,

Bir nota,bir ses,bir beste oldun,

Dillerden düşmez şarkı misali,

Ruhuma,canıma,kanıma doldun.', 'İçimde esen tatlı bir meltem, Bir gül,bir lâle,bir sümbül oldun, Dillerden düşmez şarkı misali, Ruhuma,canıma,kanıma doldun. Yalnızdım ben, ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarki-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokmu Sesimi Duyan', 'yokmu-sesimi-duyan-fatma-ay-omdav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yapmali? insan sagligini hice sayanlara.

Ne yapmali? Insanlarin hayatini karartanlara.

Ne yapmali? Insanlarin issiz,caresiz kalmasina neden olanlara.

Ne yapmali,ne yapmali,ne yapmali? 

Kader birkez gulmedimi gulmuyor.

Nerede olsa sanssizlik onu buluyor.

Simdi caresiz kivranip duruyor.

Derdine derman ariyor Fatma.

2§ Ekimde bindi ucaga.

Kavusacakti ana,baci ve vatanina.

kavustu onlara,kavustu ama:

Felaketi oldu,bu kavusma ona.

Birgun gitti doktora.

Doktor dedi: Ameliyat Fatma.

Tahliller,ultrason ve netice.

Ameliyat olman gerek dediler ona.

18 Kasimda yatti ameliyat masasina.

Ve sonra 1,2,3,4 derken uyudu kaldi masada.

Cerrahlar asildilar ses tellerine.

Asildilar hunharca.

Oysa tedavi olabilirmis ilacla.

Uyandiginda,doktor geldi yanina.

Basarili bir operasyondu, dedi ona.

Ne basari,ne basariyaaaaa.

Asil sorunlar basladi 1 hafta sonra.

Ses yok,azap cok,stres cok.

Oysa cok basit dedilerdi ona.

Hala gecmedi,bitmedi,iyilesemedi fatma.

Dondu sonra Belcika''ya.

Sorunu bitmedi,tedavi goruyor hala.

Doktorlar,Logopedistler.

Care ariyor derdine fatma.

Ses yine kisik,yine bugulu.

Sesi cikmiyor,hatta calisamiyor.

Bunlar yetmezmis gibi 

Iside erdi sona,issizde kaldi fatma.

Sesi cikmayan kisinin  iside olmaz ya.

Dogru,patronlarda hakli bu konuda.

Simdi soruyorum tum  siir dostlarina.

Ne yapsin fatma bu durumda? 

Ne yapsin,ne yapsin,ne yapsin Fatma?', 'Ne yapmali? insan sagligini hice sayanlara. Ne yapmali? Insanlarin hayatini karartanlara. Ne yapmali? Insanlarin issiz,caresiz kalmasina ned...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yokmu-sesimi-duyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyine!', 'neyine-mesut-ozturk-0zmra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duydum ki, yine bombalar patlıyor,

Cahil insanlar, terörü hortlatıyor,

Asker anası durmadan ağlıyor,

Evlat acısı, bahar gelse neyine.

Minicik yavrular babaya hasret,

Soruyor kendine yine mi gurbet,

Terör boy salmış saçıyor vahşet,

Yetim kalanın, çiçek açsa neyine.

Dul kalacak yine yeni gelinler,

Izdırap ve çile haberleri dinler,

Ne yazık, durmuyor bu katiller,

Mehmetler ölüyor, güneş doğsa neyine.

Bitsin bu vahşet saçan cinayetler,

Hey cahiller bu Dünya herkese yeter,

Ağlayan çok gülmek isteyeni göster,

Acılar oldukça, Bahar gelse neyine.', 'Duydum ki, yine bombalar patlıyor, Cahil insanlar, terörü hortlatıyor, Asker anası durmadan ağlıyor, Evlat acısı, bahar gelse neyine. Minici...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neyine-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapissin', 'hapissin-sezgin-cetin-3mm59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya düşlerimde gülen çocuksun

yada gözlerimde yüzen balık

Kapaklarımın hapsindesin', 'Ya düşlerimde gülen çocuksun yada gözlerimde yüzen balık Kapaklarımın hapsindesin...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hapissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kaçamazsın', 'kacamazsin-huseyin-sonmez-eayyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne ben senden ne sen benden,

Kaçamazsın bu sevgiden,

Kurtul artık şu kibirden,

Kaçamazsın bu sevgiden.

Her şey güzel bizim için,

Bunca nazın neden niçin,

Yanmayalım için için,

Kaçamazsın bu sevgiden.

Mutluluk var bu sevgide,

Birazcık dur beni dinle,

Yaşanır mı hayat kinle? 

Kaçamazsın bu sevgiden.

Çare değil kaçıp gitmek,

Sevdiklerini terk etmek,

Her şeyi birden yok etmek,

Kaçamazsın bu sevgiden.', 'Ne ben senden ne sen benden, Kaçamazsın bu sevgiden, Kurtul artık şu kibirden, Kaçamazsın bu sevgiden. Her şey güzel bizim için, Bunca nazın...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kacamazsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüm', 'dusum-i-brahim-sarihan-il3vn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkım bitmiyor güzel

Yüreğimde saklı tüm ömre bedel

Kokunla avutur beni esen yel

Ağlarsam yokluğuna gözyaşım sel

Hasretinle kaldım yalnız bıraktın beni

Gözlerim arar oldu ışıltılı gözlerini

Tutmayı özledim yumuşak ellerini

Karaladığım mısrada şiirlerdesin şimdi

Anlatılmıyor aşkım derin derin şöyle

Yetmiyor kağıt-kalem dile döksem de

Benim gibi bir sevip yaşarsan sende

Anlarsın o zaman beni kalp gözünle

Yine dün gece seni düşümde gördüm

Bukleli saçlarını usulca bir öptüm

Gözlerine bağlandım ayrılmadı gözüm

Şimdi yalnızca mazisin bunlarsa düşüm

(Hakkâri, 20 Kasım 2003)', 'Sana olan aşkım bitmiyor güzel Yüreğimde saklı tüm ömre bedel Kokunla avutur beni esen yel Ağlarsam yokluğuna gözyaşım sel Hasretinle kaldım...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve Galata', 'i-stanbul-ve-galata-sabit-carpar-gfhdi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul’da 

Batmakta  olan  güneşin kızılyansıması

Camlara vurdukça

Garip bir hüzün çöker içime

Nedendir bilmem  hava karardıkça

Suretim ürperti ve ben seyir halindeyiz

Önce Yeryüzünün yıldızları olan 

Evlerin tek göz odalarındaki ışıklar

Hızla birer  birer yanmaya başlar

Top oynayan  misket oynayan

Saklanbaç  oynayan çocuklar

Birer birer evlerine gider

Önce büyük sitelerin üst katları görünmez 

Ve senin hafif ışıltını görürüm sokak lambam

Hafiften bir esinti var ağır oluyor ıssız oluyor 

İstanbul’da akşam oluyor

Bir Şair kalıyor 

Bir İstanbul caddeleri 

Bir İstanbul sokakları

Sabahımı paylaşan sokak lambam 

Gece uzun sıkıcı olmasın

Ben çay demleyeyim

Senin ışığın biraz daha kuvvetlensin 

Komşumuz yıldızlar henüz gözükmedi 

Hele onlarda bir misafir olsun

Önce sen başla Üstünde balık ekmek Yediğimin  galata köprüsü

Kimbilir  üstünden geçenleri

Bir Allah birde sen

Oltalarla balık  tutan gençleri anlat

Her balık tutanda sevinçlerini

Kalem tutmadan para kazanmayı öğrenen

Su satan,simit satan  ayakkabı boyayan, 

Ufacık elleri anlat. 

İhtiyar amcanın gözyaşları içerisinde 

Gençliğini özleyişini sitem edişini

Of ulan of diyerek tütün çekişini 

Anlat Galata,anlat  gece uzun', 'İstanbul’da  Batmakta  olan  güneşin kızılyansıması Camlara vurdukça Garip bir hüzün çöker içime Nedendir bilmem  hava karardıkça Suretim ür...', ARRAY['Türk Edebiyatı','Şiir','Sabit Çarpar']::text[], 8.5, '{"poet":"Sabit Çarpar","poet_slug":"sabit-carpar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/istanbul-ve-galata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyade oldum ziyade', 'ziyade-oldum-ziyade-sezgin-cetin-auwcc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ziyade oldum ziyade 

kahve fincenlarından kaçırıp telvesini

Toprağa ektim.

Tek umudum bir filizdi

Nafile, ziyade oldum 

hem de...

Çöp tenekelerinin gürültülerini duydum 

______________________gece yarılarında

sivri hançer citlerden atlayanları gördüm

______________________şafak sökerken

Yamalı pantolonlarını giyip sokak sokak 

______________________dolaşanları gördüm

pınarları dağlanmış mor olmuş gözleri,biçare yürekleri

gördüm de gördüm....

______________________dünyanın dönekliğinde 

Ziyade oldum ziyade

gögüs kafesinden çıkarıp yürekleri 

toprağa gömdüm

topraktı temelimizdi, temizlerdi

verirdi bize bebek yüreğimizi

tek umudum topraktı

nafile, ziyade oldum 

hem de...

Ziyade oldum ziyade

çiçek açan dalından koparıp hayatı 

sunabilirdim önüne 

tek umudum şiirdi 

Nafile ziyade oldum

Hem de....', 'Ziyade oldum ziyade  kahve fincenlarından kaçırıp telvesini Toprağa ektim. Tek umudum bir filizdi Nafile, ziyade oldum  hem de... Çöp teneke...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ziyade-oldum-ziyade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Meleğim', 'canim-melegim-huseyin-sonmez-6zarq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şeyimi kaybetsem seni kaybetmem,

Çektiğim çileden şikâyet etmem,

Ellerini bırakmam bir yere gitmem,

Her şeyimsin benim canım meleğim.

Gözlerimde ışık,içimde cansın,

Bırak şu kalbi senin için yansın,

Şarkılar söyleyip hep seni ansın,

Her şeyimsin benim,canım meleğim.

Gecemde yıldızım,gündüzümde güneş,

Yoktur ki dünyada senin gibi eş,

Sönmeyen bir alev,sönmeyen ateş,

Her şeyimsin benim, canım meleğim.

Mor menekşem,sümbülüm beyaz lalem,

Gönlümün sultanı,varlığım,harem,

Dert ortağım benim ezeli yarem,

Her şeyimsin benim,canım meleğim.', 'Her şeyimi kaybetsem seni kaybetmem, Çektiğim çileden şikâyet etmem, Ellerini bırakmam bir yere gitmem, Her şeyimsin benim canım meleğim. Gö...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-selda-ozturkmen-50cpi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün her yer babam kokuyor...

Gülmekten usanmış güllerim,

Onlar bile babam kokuyor...

Kopmuş yüreğimin salıncakları,

Susmuş her an şakıyan kuşları...

Bırakın beni! 

Konuşulacak ne varsa konuştum...

Yok artık sınırlarımın mihengi,

Sessizliğime solmuş ölümün rengi...

Bugün her yer ''sen'' kokuyor baba! 

Daha kaç kere öleceksin? 

Biliyorum,

Gittiğin gün geri döneceksin...

(04.03.2006)', 'Bugün her yer babam kokuyor... Gülmekten usanmış güllerim, Onlar bile babam kokuyor... Kopmuş yüreğimin salıncakları, Susmuş her an şakıyan ...', ARRAY['Türk Edebiyatı','Şiir','Selda Öztürkmen']::text[], 8.5, '{"poet":"Selda Öztürkmen","poet_slug":"selda-ozturkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/babam-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi!', 'simdi-mesut-ozturk-jc0t4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıcacık demlenmiş taze çayın yanında,

Mis kokan bir de çıtır simit olsaydı.

Deniz kokan akdenizin koyunda,

Şimdi Türkiye de olmak vardı.

Özlemişim memlekette gezmeyi,

Pırıl pırıl sularında yüzmeyi,

Az günüm var  bitiriyorum çileyi,

Mapus bile olsa memlekette olmak vardı.

Buz tutmuş vicdansızın gönlüne,

Birde bahar güneşi doğsa yüzüne,

Dönmek istiyorum ben özüme,

Şimdi Ankarada olmak vardı.', 'Sıcacık demlenmiş taze çayın yanında, Mis kokan bir de çıtır simit olsaydı. Deniz kokan akdenizin koyunda, Şimdi Türkiye de olmak vardı. Özl...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birikenler', 'birikenler-gulay-yildiz-i9z9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiçkimsenin bilmediği bir derinin içinde 

yaralı bir kuytu içim... 

dokunmasınlar diye 

yaramı büyütmeye razı oldum, 

acımaktayım... 

bir ben var 

__sanıyordum tek yakın! 

oysa yanıldığım yazıldı kadere

iki gülücükle...

Bildiğim tüm yaşananlara inat

Beklenilen yokedicisi misin geçmişin? 

Var mı büyülü asanla huzuru saçma yetin? 

Her ''evet'' e bir ''gel'' var bende', 'hiçkimsenin bilmediği bir derinin içinde  yaralı bir kuytu içim...  dokunmasınlar diye  yaramı büyütmeye razı oldum,  acımaktayım...  bir be...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birikenler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-kagizmanli-mehmet-kesen-ledil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne refah bir hayat

Nede ki sihirli bir dünya

İçim seninle dolsun

Kalbim kalbinde olsun', 'Ne refah bir hayat Nede ki sihirli bir dünya İçim seninle dolsun Kalbim kalbinde olsun...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Mehmet Kesen']::text[], 8.5, '{"poet":"Kağızmanlı Mehmet Kesen","poet_slug":"kagizmanli-mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istek-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsa da tutmasa da', 'tutsa-da-tutmasa-da-omer-dalman-munb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çoğu gider bu işi

en temiz, en sade, en sessiz yerde yapar.

bense bu kez

tersine

iş yeri WC''sinde yaptım.

karşımda ''lütfen klozete katı madde atmayınız'' uyarısı

kabin içindeki o sessizlik...

bal gibi de -duru- kaldım

ve aslanlar gibi orada

o herkesin ''pis'' saydığı yerde

titreşe titreşe

en ulvi halimde hem de

günlük duamı ediverdim! 

ne oldu? 

yoksa Allah''ın kakası ''tukaka'' mı oldu? ! 

onu-bunu bilmem

aslanlar gibi ettim günlük duamı! 

tutmasa da, bana

tutsa da, bana...

(Mart 2006)', 'çoğu gider bu işi en temiz, en sade, en sessiz yerde yapar. bense bu kez tersine iş yeri WC''sinde yaptım. karşımda ''lütfen klozete katı madd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tutsa-da-tutmasa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi esen gözyaşları', 'mavi-esen-gozyaslari-sezgin-cetin-vds8f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi esen gözyaşları vardı

yelkenlide...

her damlası bir vaha daha gömerdi

yüreğine...

Mavi gören umutları vardı

Güneş görmeyen karanlık sokaklarında

yüzünün...

kırmızı toprak yarılmış

bereket sanmıştı onu

nasıl da hasretti

toprak, bereket, ürün

dost sanmıştı onu 

sıcak,kurak yaz gecelerinde...

Yeşil bakan gözleri vardı

sözlerinin

dimdik ve korkusuzca

aşk ile bakan gözleri vardı

düşlerinde...

ezilmişlik bir nebze olsun 

untturmamıştı kendini,

yorgun dizlerine.

Papatyalarla fallar bakardı

bundan pek yakın,

pek çok sene içerisinde

vücudu titrerdi hep 

yad ederken geçmişi

kucağına alırdı babası

korurdu, severdi

tekrar tekrar öperdi.

annesiydi ağladığı doyasıya

bir magarada yaşar ve 

tek anahtarı anasında saklıydı

koynunda yatıp geceleri

sıcak nefesini

hissederdi boynunda

ve....... ürperirdi...

Dalgıç adamlar gezerdi

beyninde,

vurgun yememeyi onlardan 

öğrenmişti

karanlık yolları vardı 

gölgesinde

Dünü bugünü hatta

geleceği de....', 'Mavi esen gözyaşları vardı yelkenlide... her damlası bir vaha daha gömerdi yüreğine... Mavi gören umutları vardı Güneş görmeyen karanlık sok...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mavi-esen-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-nese-ersoy-9dbj4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gideceksin biliyorum

koynuma kış doldurup birazdan

bir başına kalacak yine ellerim

boynum yine eksik bir yandan', 'gideceksin biliyorum koynuma kış doldurup birazdan bir başına kalacak yine ellerim boynum yine eksik bir yandan...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/serzenis-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donan Gözyaşları', 'donan-gozyaslari-kagizmanli-mehmet-kesen-1ymnj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor durmadan

Havalar iyice soğudu

Bak daha ağustosun ortasındayız

Ama ben üşüyorum

Vay geldi bu kış fakirlerin haline

Odunun kilosu oldukça pahalı

Nereden bulsun kömürü

Yorgansız yataksız vatandaş

Hele bekarların işi iyice zor

Sobası yok olmasına yok ya

Bari sırtını ısıtacak avradı olsa

Bu nasıl memleket bu nasıl iş

Görülmemiş felaket olacak bu kış

Hayvanlar bar bar bağıracak açlıktan

Ve yine bebekler üşüyecek beşiklerinde 

Bir annenin gözyaşları akacak

Buz tutacak yanaklarında

Bir baba soğuktan donacak

Çocukları için gittiği ormanda

Fırtına tipi aman vermeyecek

Boğulacak evine ulaşamadan

Ve yine gerinecek kodamanlar

Sımsıcak koltuklarında

Izdıraplı annenin gözyaşları

Yanaklarında dondukça', 'Yağmur yağıyor durmadan Havalar iyice soğudu Bak daha ağustosun ortasındayız Ama ben üşüyorum Vay geldi bu kış fakirlerin haline Odunun kilo...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Mehmet Kesen']::text[], 8.5, '{"poet":"Kağızmanlı Mehmet Kesen","poet_slug":"kagizmanli-mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/donan-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-huseyin-sonmez-nfdcy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşığım sana gözüne kaşına,

Rahmet kokan ekmeğine, aşına,

Kırlardaki çiçeğine,dağlardaki taşına,

Aşığım sana memleketim.

Kem gözler uzak dursun senden,

Ne istersen iste dile benden,

Tanrım seni korusun kederden,

Aşığım sana memleketim.', 'Aşığım sana gözüne kaşına, Rahmet kokan ekmeğine, aşına, Kırlardaki çiçeğine,dağlardaki taşına, Aşığım sana memleketim. Kem gözler uzak durs...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/memleketim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-kagizmanli-mehmet-kesen-okjyz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben neyim sen nesin

Orasını bilmem ama

Ben bir hiç

Sense bir boşluksun

Hiçle boşluk

Oldukça acıklı değil mi

Aslında böylesi daha iyi

İkisi tamamlar birbirini

Arada açıklık olmaz', 'Ben neyim sen nesin Orasını bilmem ama Ben bir hiç Sense bir boşluksun Hiçle boşluk Oldukça acıklı değil mi Aslında böylesi daha iyi İkisi t...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Mehmet Kesen']::text[], 8.5, '{"poet":"Kağızmanlı Mehmet Kesen","poet_slug":"kagizmanli-mehmet-kesen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bosluk-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Hüzün Düştü', 'gozlerime-huzun-dustu-selcen-boyar-75as5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gülü sevmiyorsun

Bana gülüm demiyorsun

Gözlerime hüzün düştü

Gözlerimi görmüyorsun

Sen geceyi sevmiyorsun,

Geceleri gül/müyorsun,

Gül/lerime hazan düştü,

Baharımı vermiyorsun.

Sen heceyi sevmiyorsun,

Hece küstü bilmiyorsun,

Şiirlere ölüm düştü,

Azraili görmüyorsun.', 'Sen gülü sevmiyorsun Bana gülüm demiyorsun Gözlerime hüzün düştü Gözlerimi görmüyorsun Sen geceyi sevmiyorsun, Geceleri gül/müyorsun, Gül/le...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerime-huzun-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-huseyin-sonmez-jllke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cıvıl cıvıl ötün kuşlar,

Hürrriyet sizin adınız,

Mutluluğa uçun kuşlar

Hürriyet sizin hakkınız.

Bende hür olmak istedim.

Sizin gibi...

Uçmak istedim

Doyasıya...

Uçamadım.

Kanat taktım

Kanadımı açamadım.

Uçun kuşlar uçun

Hürriyete uçun...', 'Cıvıl cıvıl ötün kuşlar, Hürrriyet sizin adınız, Mutluluğa uçun kuşlar Hürriyet sizin hakkınız. Bende hür olmak istedim. Sizin gibi... Uçmak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kuslar-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunu bil!', 'bunu-bil-mesut-ozturk-oo5z9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dost var, fakirlere yardım eden,

Bir arkadaş var, gönüllere hitab eden,

Bir insan var, herkese saygı gösteren,

Bunu bil ve çaresizliğe kapılma.

Bir ana var, evladını hep düşünecek,

Bir baba var yavrusuna kanat gerecek,

Bir kardeş var karşılıksız güvenecek,

Bunu bil ve yalnızlığa düşme.

Bir yar var, sevecek sevdirecek,

Bir diyar var ardından özletecek,

Unutma bütün bunlar birgün bitecek,

Bunu bil ve ihanete kalkışma.

Bir Kuran var, sıkıca sarılacağın,

Bir peygamber var, hayatına bakacağın

Bir Allah var, büyüklüğüyle tapacağın,

Bunu bil ve sakın inkara kalkma.', 'Bir dost var, fakirlere yardım eden, Bir arkadaş var, gönüllere hitab eden, Bir insan var, herkese saygı gösteren, Bunu bil ve çaresizliğe k...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bunu-bil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk', 'umutsuzluk-selcen-boyar-fgc0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bir hüsran,

Yine bir kayıp.

Yine yeniden bir umutsuzluk

Yakıp kavuran,

Bilinmezliğe savrulan bir mutsuzluk.

Bir kaygı,

Bir kuşku,

Ruhumda deli bir huysuzluk.

nereye gitsem benimle,

Kahrolası uğursuzluk.', 'Yine bir hüsran, Yine bir kayıp. Yine yeniden bir umutsuzluk Yakıp kavuran, Bilinmezliğe savrulan bir mutsuzluk. Bir kaygı, Bir kuşku, Ruhum...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umutsuzluk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâmil Dede', 'k-mil-dede-huseyin-sonmez-rxqn4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün sana uğradım,

Kâmil dede.

Tekerlekli sandalyede,

Elinde kitap dalmıştın.

Ruhunu enginlere salmıştın,

Sessizce aldım

Elinden aşını,

Yavaşca arkaya yasladım

Başını.

Hafif ateşin vardı.

Biliyorum bu dünya

Sana dardı.

Ne fırtınalı günlere

İmza atmıştın,

Kimsesizler için

Varını yoğunu satmıştın.

Hatırlar mısın? 

Üşüdüğüm günleri

Bana sarılıp yatmıştın.

Sevincime sevinç,

Neşeme neşe katmıştın.

Kâmil dedem meleğim

Annem babam

Sen olmuştun sen,

Senin sayende okudum,

Yürüdüm,koştum ben.

Artık ayağa kalk! 

Zorlukları yen

Kâmil dedem meleğim.', 'Dün sana uğradım, Kâmil dede. Tekerlekli sandalyede, Elinde kitap dalmıştın. Ruhunu enginlere salmıştın, Sessizce aldım Elinden aşını, Yavaş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kamil-dede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mahkemesi', 'ask-mahkemesi-bilal-bahadir-jtyj1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah erken kalkıp hazırlanmalı

Hakime’nin yanına düzgün çıkmalı

Ne de olsa ya başlayış yada bitiş

Ne de olsa son celse

Karar duruşması var aşk mahkemesinde

Aynanın karşısına geçip hazırlanmalı

Sinek kaydı cinsinden tıraş olmalı

Bir de taramalı saçları

Bir de… vakit tamam yola çıkmalı

Karar duruşması sevda pastanesinde

Mübaşir bağırıyor:

- İki kahve, biri sütlü, diğeri sade

Karar duruşması var aşk mahkemesinde

Yaz kızım: bu deli bunu çok sevdi

Bu ise bu aşka değer vermedi

Mahkeme düşündü kararını verdi

Kalemi kırdı aşk mahkemesi.', 'Sabah erken kalkıp hazırlanmalı Hakime’nin yanına düzgün çıkmalı Ne de olsa ya başlayış yada bitiş Ne de olsa son celse Karar duruşması var ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bahadır']::text[], 8.5, '{"poet":"Bilal Bahadır","poet_slug":"bilal-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-mahkemesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim sensiz', 'sensizim-sensiz-fatma-ay-a0kj2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz olmadigim hic olmadiki.

Sensizlikle yogrulmadigim hic olmadiki.

Sensiz mutlu oldugum hic olmadiki.

Sensizde olsa,seninlede olsa hic gulmedimki.

Agliyor icim simdi sensizligime.

Yaniyorum simdi seninle sensizligime.

Kahrediyor beni dusunceler ve sensizlik.

Senin bu yaptiklarinin hepsi bencillik.

Gene sessiz, gene sensizim.

Gene suskun, gene uzgunum.

Gene mutsuz, gene oksuzum.

Gene sensizim,sensizim, sensiz.', 'Sensiz olmadigim hic olmadiki. Sensizlikle yogrulmadigim hic olmadiki. Sensiz mutlu oldugum hic olmadiki. Sensizde olsa,seninlede olsa hic g...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-mihrican-karaca-yw8yq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman bir gece yarısı,

Gözlerim boşluğa dalmış.

Elimde kağıt,kalem varmış,

Sigaram içmeden tabakta yanmış.

Bir zamanlar yalnızlığı seçerdim,

Kendimi boş odalara kilitlerdim.

Başımdan gitsinler diye sepetlerdim

Şimdi yalnızlık çekilmiyor gel.

Yalnızlık kaderim olmuş

Arayıpta beni bulmuş

Şimdi o yüzlere

Özür diliyorum binlerce kere.', 'Zaman bir gece yarısı, Gözlerim boşluğa dalmış. Elimde kağıt,kalem varmış, Sigaram içmeden tabakta yanmış. Bir zamanlar yalnızlığı seçerdim,...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-355-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm', 'koyum-mihrican-karaca-q5d10', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolları var yarı beton,yarı taşlı,topraklı

İnsanları var yarı yufka,yarı taş yürekli

Dedikodu desen almış başını gidiyor

Evler virane olmuş,insanlar köyü terkediyor

Hala altta hayvanlar,üstte insanlar yaşıyor

Kimse gördüklerinden ibret almıyor

Bildiğini söyleyip,bildiğini okuyor

Birlik,beraberlik yok herbiri ayrı yola sapıyor

Köylü yuvasını çekip çeviremiyor,

Yolsuzluklarda çare arıyor.

Anlar bozulan düzenlere ağlıyor

Vah benim köyüm, gözünden kan damlıyor

Adam evine odun getirmiyor

Kadın Eşeği alıp orman gidiyor

Akşam olunca ''''Hani yemek''''diyor

Kadın bunlar erkek işi diyemiyor

Akşam olunca hem yemek hemde dayak yiyor

Vah benim(Kıran köyüm)  insanlarıda kırıyor

Muhtarıda anlatsam satırlarda yetmez

Köyün derdi burada bitmez.', 'Yolları var yarı beton,yarı taşlı,topraklı İnsanları var yarı yufka,yarı taş yürekli Dedikodu desen almış başını gidiyor Evler virane olmuş,...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koyum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalk Baba', 'kalk-baba-mihrican-karaca-susyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugünün hatrına benim hatrıma

Kalk baba bugün bayram

Gelinmesi imkansız yolların

Ucundasın bilirim ama; 

Bugün bayram kalk baba

Bir dua gönderiyorum

Yıllarca hasret olduğum 

Ellerinden öperek

Bugünün hatrına,benim hatrıma

Bugün bayram kalk baba

Senin kadar usta olamadım

Sensiz yuvamı kuramadım

Baba ben mutlu olamadım

Bugünün hatrına,benim hatrıma

Bugün bayram kalk baba.

Bu dünyada dert,gam çok

Yattığın yerde rahat uyu baba

Rahmetin bol olsun baba

Seni unutamam seni seviyorum baba', 'Bugünün hatrına benim hatrıma Kalk baba bugün bayram Gelinmesi imkansız yolların Ucundasın bilirim ama;  Bugün bayram kalk baba Bir dua gönd...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kalk-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-bilal-bahadir-v51zt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BAHANE

Kahvaltıdan sonra çıktım sokağa

Şimdi evimize dönemiyorum

Anneme bir bahane bulmuştum ama

Önce aklımdaydı şimdi unuttum

Arkadaşlarla maç ettik önce

Sonra bilye oynadık hepsini yuttum

Hah hay! Üç bilyem vardı on oldu,

Ali’yi ne güzel de uyuttum

Duvarın kenarında beş taş oynadık

Ali bilyelerinin öcünü aldı

Karnımız acıktı dutlara daldık

Çalıntı da olsa güzeldi tadı 

Kızmadın değil mi güzel anneciğim

Vakit nasıl geçti inan unuttum

Sana bir bahane bulmuştum ama

Önce aklımdaydı şimdi unuttum

Hava karardı diye kızmazsın di mi

Beni bir daha öyle dövmezsin di mi

Bir daha olmaz kızma anne

Akşam olduğunu valla unuttum.', 'BAHANE Kahvaltıdan sonra çıktım sokağa Şimdi evimize dönemiyorum Anneme bir bahane bulmuştum ama Önce aklımdaydı şimdi unuttum Arkadaşlarla ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Bahadır']::text[], 8.5, '{"poet":"Bilal Bahadır","poet_slug":"bilal-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bahane-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enes''im', 'enes-im-selcen-boyar-ti757', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollarında okulun

Yele benzer Enes''im.

Zilin ince sesiyle,

Sel''e benzer Enes''im.

Yüreği kalmaz kinde,

Koşar, çoşar zinde,

Bayrağımız renginde,

Gül''e benzer Enes''im.

Bilemezki hiç yalan,

Ne kötülük, ne dolan,

Ötelere boy salan,

Dal''a benzer Enes''im.

Öğrenmek hevesinde,

Muhabbet var nefesinde,

Bülbüller kafesinde,

Dil''e benzer Enes''im.

Saf yüreği ak''ta

Oyunu hamakta,

Lezzeti damakta,

Bal''a benzer Enesim.

Acıya gürleyen,

Güzelliği birleyen,

Yıldızla parlayan,

Al''a benzer Enesim.

.....Canım kardeşim Elif Bozdoğan''ın oğlum Enes Kaan''a 2000 yılın da yazdığı bu şiiri sayfama eklemek istedim.', 'Yollarında okulun Yele benzer Enes''im. Zilin ince sesiyle, Sel''e benzer Enes''im. Yüreği kalmaz kinde, Koşar, çoşar zinde, Bayrağımız rengind...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/enes-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin O', 'sensin-o-mihrican-karaca-ewjr6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensin beni bu hallere koyan

Dualar edip

Allaha yalvarıp

Beni dileyen sensin

Eline geçincede,

Yerden yere vuran.

Elaleme rezil eden sensin

Kıymetimi bilmeyensin

Hergün biraz daha yitirensin

Sensin beni bu hallere koyan.

Para hırsın aşkını aşmış

Aklında,şuurunda kaçmış

Edepsizlik boyunu geçmiş

sensin beni bu hallere koyan.', 'Sensin beni bu hallere koyan Dualar edip Allaha yalvarıp Beni dileyen sensin Eline geçincede, Yerden yere vuran. Elaleme rezil eden sensin K...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensin-o-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gözler', 'o-gozler-i-brahim-sarihan-6ob7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelsen kollarıma çat kapı bir gece

Sarılsan sımsıkı titreyen bedenime

Kondursan dudaklarıma küçücük bir buse

Anlatırdım bıkmadan sevgimi o gözlere

Çok özlediğimi söylesem çıldırırsın belki

Duymalısın kalbimin çarpışını ispatlar çünkü

İşitsem sıcak sesini olurum sevinçten deli

Rüyalara yatsam görür müyüm o gözleri

Acı veriyor artık sensizlik buralarda zor

Geçmek bilmiyor zaman bir de bana sor

Irak geçen şu dakikalar yüreğimde kor

Hasret yaşatan zamana hesap sorulmuyor

Büyük bir aşk var minicik hücrelerimde

Güç veriyor bana seni her düşündüğümde

Müthiş güzelliğinse ilhamım şiirlerime

Çıkmaz bu aşk kalbimden ta derinlerde

Sen sevgili yalnız benim için yaşa

Ömrümü adadım ben gözlerinin uğruna

Tek bir gülüşün bile inan yeter bana

Ağlamasın o gözler kıyamam ben aşkıma

(Hakkâri, 02 Aralık 2003)', 'Gelsen kollarıma çat kapı bir gece Sarılsan sımsıkı titreyen bedenime Kondursan dudaklarıma küçücük bir buse Anlatırdım bıkmadan sevgimi o g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-gozler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahve Gözlüm', 'kahve-gozlum-mihrican-karaca-bexh3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün oılur bende gidersem

Arama beni kahve gözlüm.

Gittiğim yerden kara haber gelende

Ahım kalmış olmadı ne dernek nede düğün.

Öyle bağlanmışımki sanırsın kör düğüm.

Geç kalmam gelirim yarına yada bu gün

Sana zahmet vermem kahve gözlüm.

Seven sevevnin bilirmiş suçınu

Sevdim ama değiştiremedim huyunu

Ellerinle kazdın kendi kuyunu

Çıkaramam seni kahve gözlüm.', 'Bir gün oılur bende gidersem Arama beni kahve gözlüm. Gittiğim yerden kara haber gelende Ahım kalmış olmadı ne dernek nede düğün. Öyle bağla...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kahve-gozlum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girne Limanı', 'girne-limani-oktay-oksuzoglu-dd23s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak, Girne limanında Ay yakamoza daldı

balıklarla öpüşüp ışıklarda yıkandı

aşka geldi bir anda tavernada cümbüşler 

bu akşam bu limana yine cennet dadandı..

Yeryüzünde yaşanan bu en gerçek cenneti 

beyinlere taşırken renkli bir tablo gibi

şarkılar, artırıyor sevgide bereketi; 

düşmanlık bu limanda yine sınıfta kaldı..

Dostluğa ve huzura  kucak açan yatlarda

güneşin batışıyla başlayan bayramlarda

gökyüzünü güldüren rengarenk maytaplarda

barış özlemlerinin güzel yüzü yansıdı..', 'Bak, Girne limanında Ay yakamoza daldı balıklarla öpüşüp ışıklarda yıkandı aşka geldi bir anda tavernada cümbüşler  bu akşam bu limana yine ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Öksüzoğlu']::text[], 8.5, '{"poet":"Oktay Öksüzoğlu","poet_slug":"oktay-oksuzoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/girne-limani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut (tu)', 'umut-tu-kerem-kayar-pz684', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün içinde, en heyecan verici

hayallerimizin eserlerini üretirken, çamurda

toprağım kokusu siniyordu tenimize...

Ardından, saklı bir ağaçın gölgesinde

işte dram, 

sen bir anne

ben ise bir baba rolünde, değişmeyen

insanların üreme sistemi hakkında

bir bilgimiz olmadan, bir çocuğumuz oluverdi...

Çocukluğumuzu yaşarken, çocuğumuzu nasıl 

büyütebilirdik ki? 

sahte gülücüklerin nasıl, mimik olduğunu öğrenmeden

tadına doyuyorduk, samimi kahkahaların...

Evcilik tadında günler,

Bu arada, zaman buldukça aşkın tanımını öğreniyorduk

alay edilmemek için, soru sormadan sadece gözlüyorduk...

Öpüşmeyi sanatsal içeriğinden çıkarıp

dudaklarımızın sıcaklığını paylaşıyorduk

zaman toprak hasteri çeken yağmur hızında...

Ve biz aşık oluyorduk

Oysa çocuktuk; 

açılmayan kanatların büyüklüğünü,

bir of çekmeden kederi,

En önemlisi, nereden bilirdik

mutluluğunu vuslatın, aşık olmadan...

Çocukca yaşarken, çocuk sahibi olduk ya

o ağaçın gölgesinde, Aşk doğurmuştu Umut''tu

nereden bilirdik ki? Kavuşmak bir

umut(tu) ...', 'Gün içinde, en heyecan verici hayallerimizin eserlerini üretirken, çamurda toprağım kokusu siniyordu tenimize... Ardından, saklı bir ağaçın ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Kayar']::text[], 8.5, '{"poet":"Kerem Kayar","poet_slug":"kerem-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/umut-tu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisehir Gecelerinden Sesleniyorum.', 'eskisehir-gecelerinden-sesleniyorum-fatma-ay-s9mtc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskisehir gecelerinden sesleniyorum.

Sensiz bu kacinci gun batimi.

Neden alip gittin? Benligimi,hayatimi.

Sorulari bitmez bu kacinci gecem bilmem.

Ve kacinci Eskisehir gecelerinden seslenmem.

Ben hala uyumadim.Bir umut bekliyorum.

Senden,esen yelden,gecelerden.

Bir umut bekliyorum her an.

Senden ve Eskisehir semtlerinin birinden.

Sesimi duyuyormusun? 

Hickiriklarla,gulucukler.

Dudagimda donmus. Eskisehir gecelerinde.

Hersey,herkes yabanci bana.

Fakat seni tanidim burada.

Acilari tanir oldum.

Ve en onemlisi hayatimi.....

Seni tanidim.

Ayriliklarin.....

Sevginin yuce kanitidir derler.

Bu dogrumu? 

Eger oyle ise.......

Bu soze karsin sabrediyorum.

Ve seni bekliyorum inan bana.

Geciyor hep aylar,yillar. 

Ben hep bekliyor, sabrediyorum.

Inan bana.

Bu sarkiyi sever diye dinliyorum.

Ve icimden,haykirarak, gel,gel artik.

Ve sesleniyorum,Eskisehir gecelerinden birkez daha.

  

                Yazdigim tar:18-10-1979', 'Eskisehir gecelerinden sesleniyorum. Sensiz bu kacinci gun batimi. Neden alip gittin? Benligimi,hayatimi. Sorulari bitmez bu kacinci gecem b...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ay']::text[], 8.5, '{"poet":"Fatma Ay","poet_slug":"fatma-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/eskisehir-gecelerinden-sesleniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar Yolların İçimizden Geçiyor', 'firar-yollarin-i-cimizden-geciyor-necmettin-topcu-liupe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin sevdan; 

Yangınları içimizde çıkartıp

İçimizden başka yerlere kaçmaktı...', 'Senin sevdan;  Yangınları içimizde çıkartıp İçimizden başka yerlere kaçmaktı......', ARRAY['Türk Edebiyatı','Şiir','Necmettin Topçu']::text[], 8.5, '{"poet":"Necmettin Topçu","poet_slug":"necmettin-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/firar-yollarin-icimizden-geciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Soğukta Beklemez', 'olum-sogukta-beklemez-sair-karizma51741-ndnuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir kapıdan çıkıverir gözlerinin kıvılcımları 

başaklar tutuşur ardısıra. 

hüznünün yoğunlaştığı,sinema şeridinin yürüdüğü anlarda 

kapıları kapatman nafile. 

kim duyacak sessiz çığlıklarını,ya da kim mani olacak 

gölgelere. 

ve bir elin uzanıpta,boğazına düğümlendiği anda seslerin 

acı siren seslerini senden başka duyan olmayacak. 

kapı nasıl açıldığı ise bir zaman,sessizce kapanacak 

ardından zamansızlığın varoluşuna. 

senin sevdalanışın,senin hüzünlenişin boş be gülüm. 

zaman tüneline girdiysen eğer,kaçışın yok bu sevdadan. 

ne para ne pul ne şöhret ne güzellik,ne sevdan ne hüznün, 

ölüm soğukta beklemez gülüm...', 'bir kapıdan çıkıverir gözlerinin kıvılcımları  başaklar tutuşur ardısıra.  hüznünün yoğunlaştığı,sinema şeridinin yürüdüğü anlarda  kapıları...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olum-sogukta-beklemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup-2-Sevgi Kuşum', 'mektup-2-sevgi-kusum-vedat-koparan-5wj6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beni anlayacağının bilinciyle yazıyorum biliyor musun kalbimin ağrısında her an yokluğun sancıları büyürken bir gün erken gidişime değil de senin üzüleceğini düşündükçe ağrılarım artıyor daha da üzülüyorum bunu düşünmeden yapamıyorum

atomları iç içe geçip o denli ayrışan karmaşıklığın içinde yoksun hareler zaman pençesinde 

büyütürken senin olan senleri bende

kalbimin ağrısı hafif yatıştı şimdi farklı atmakta 

görmenin bilmenin heyecanında hoş bir kıpırtı

seni görmek ne güzel mektubunu yazıyordum

olmadığın her ana akıyordum zarfı yapıştırmadım

yaşamın; her anını anlamlandırmak derdimiz olduğundan, yürek ağrımızı büyütse de 

bu anlamda çoğaltmak ve çoğaltırken dönüşüp dönüştürmek bize özgüydü 

ve sen gözlerime düşen bir hayaldin yaşanası gerçekliğinle.

varmışçasına sayarak birlikte yazdık mektubumuzu 

oysa sen henüz gelmemiştin gözlerine yapıştım gözlerindeyim 

gidişler dönüşenlereydi özlenmelerimizde

dostluk, arkadaşlık, sevgilerimiz; özlemlerimizde ki özgürlüğün erdemiyle tutkuları ezilmişliğinde yoksunluklarda insana.

en güvenilir en güçlü yanımız sevgi sığınaktı yüreğimizde kör karanlıklara vuran 

onu biriktirdik, büyüttük yolculuğumuz tutulmaz düşlerleydi, bundandı aynı denize akan olmamız yaşanası düşlere.

vururken pencereden kış üşümeleri uzaklar kanamalı yalnızlıklar büyütürken erkenci değildi ama gel geçte hiç değildi zaman o sevgi kuşu bir gece yürek perçemine konuverdi 

fıkralar, müzikler, şiirler yaşama dair ne varsa düşünce duygu pınarlarımızda,

gecenin sessizliğini anlamlandırıp güne erdirendi, zaman hem bir su gibi akan birbirini tamlayan olurken bir yandan gelişlerin gözbebeklerini büyütendi, beklemek bekleyene hep zor gelirdi.

sen aldın sözü güz düşünde

kendine çeken sevgi dolu bakışın 

bir ağustos sıcağı gibi aktın içime

taç yapıp öpüverdim geceyi alnından

gece anlam buldu yıldız gönencinde

ay güneşe tutuldu yıldız utandı kaçtı 

mavileri büyüten iç denizleri okyanustu, anneler ne tez ağlar ne tez güler bir sözle

uzak mesafeler tayyare olur seyyarelerde

göğün acısından acıları sağıp üzerime yağdıran bu çöken karabulutlarda yaşamdaki tüm tutsaklıklarımızı aşan sevgi sarmalı candan cana yürek sesinde gelen bu mektuptu.

sen bana hep gel 

ne kadar kırıkların varsa 

dök gel 

sen bana hep gel 

ama hiç gitme 

sevinç yağmurlarını 

bakışlarında dök gel

öylece kal

bazen durgun meltemli rüzgâr olursun ten okşamasında bazen bağrımı yakan boran

hüzün yağmurları kuytuluklara kaçışlarda gidişinde boşaltırken gök denizi son yağmurlarda başladı  öpmeye bakmaya doyamadığım bu gelen bahardır sen gözlerinde etekleri tutuşan 

incili han açar kapısını pus tutanda

tarihin burçlarından bakar insanlığa 

ne kötü heyhat insanlık düşmüş ayağa

kör gözlü değil zaman kurulu hep an’a

bakar kör olmuşuz akamamışız zamana

kara gün haberi diye atmacalar yolunu kollasa da 

salalım yüreğimizde büyüttüğümüz sevgi kuşunu

hadi durmak yok sen bana koş ben sana

kanat açsın yaralıda olsa varacaktır aşkla 

hoş geldin merhaba sevgi kuşum merhaba 

Bitmedi...

Vedat Koparan 07.03.2006', 'beni anlayacağının bilinciyle yazıyorum biliyor musun kalbimin ağrısında her an yokluğun sancıları büyürken bir gün erken gidişime değil de ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/mektup-2-sevgi-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebruli Duygu', 'ebruli-duygu-sair-karizma51741-yw51f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seyrederken karmakarışık düşünceler arasından, 

bir yorgan gibi uzanmış denize bembayaz köpüklere bürünen dalgaları. 

ve geri dönerkende turkuaz düşlerin arasından geçerek 

kendi benliğine doğru doludizgin bembeyaz köpükleriyle kayboluşunu ufukta, 

uzaklarda bir yerde birleşir kızıla boyanmış bembeyaz bulutlarla kaplanmış çizgide, 

ve yalnız kalınca insan düşlerinin perde arasından hayata bakışlarını görüyor. 

ve ağzında anlamsız bir türkü ile çağırırcasına: 

''sende gel dalgaların ses çıkarmadığı anlara, 

gözyaşlarım sana aksın, sende bana.''', 'seyrederken karmakarışık düşünceler arasından,  bir yorgan gibi uzanmış denize bembayaz köpüklere bürünen dalgaları.  ve geri dönerkende tur...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ebruli-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşerim', 'duserim-vedat-koparan-lhcno', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yıldız düşer bir yıldız 

Sen, o düşer

Bir ben düşerim canda cana 

Zamansız apansız acılarla

Dağ zirvesi sevdamla düşerim sana

Yalın yapıldak esen rüzgârla bir dağ değilim dayanılası

Yılların acılarıyla izini sürdüğüm şu adaletsiz kırık yaşamda

Pusatlarda vurulmuş gecikmiş bir sevdayım yaşanası 

Gözleri mil çekili aydınlıklarda

Yaşanmamış bir yaşamım yarım kalmış her anım

Düşerim eşkıya bir yıldız nasıl düşerse 

Buz kesen sabah ayazında erken düşer çiy yaşam dalına

Zamansız açan bir çiçek nasıl açar donar kalırsa

Düşerim kanırtarak savrulup yana döne

 yaprak yaprak toprağın bağrına 

Ağlama gözüm ağlama 

Bu topraklar ne gözyaşları içti 

Ne acılar çekti

Ekmeğini alıp koltuk altına götürememişsen evine 

Kalmışsan hacizde rehine sevgisizlikte sevgiyle 

Tutunduğun dirençli bir dal sevgi kalmıştır elinde

Sen türkü bakışlı kuşkanadında mavileri getiren 

Bir gecesin özlemin esen rüzgârında 

Ben zamansız bir ağrıyla sevda yaprağında düşen

Ağlama yüreğim ağlama 

Dindir sızını bastır göğsüne acını

Ha bir eksik ha bir fazla 

Olmasam ne çıkar 

Anlam katamamışsam yaşama

Vedat Koparan 08.03.2006', 'Bir yıldız düşer bir yıldız  Sen, o düşer Bir ben düşerim canda cana  Zamansız apansız acılarla Dağ zirvesi sevdamla düşerim sana Yalın yapı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/duserim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Nasıl Bakışdı', 'o-nasil-bakisdi-i-smail-dogan-ax7we', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O nasıl bakışdı öyle ah! GÜLÜM,

Gözleri gözüme baktı yürüdü.

Yüreğmim içine okudu gazel,

Beni de ardına taktı yürüdü.

Kaşına gözüne sürmüş nakışı,

Cayır  cayır yaktı  bir tek bakışı,

Geçerken yanımdan şimşek çakışı,

Yüzümden bir çimdik büktü yürüdü. 

Gönlümün meleğne benziyor başı,

Aydan almış  sanki o hilal kaşı,

İnciden dizili  bembeyaz  dişi, 

Dilimi   dişimi  söktü  yürüdü.

Doymadım parlayan zeytin gözüne,

Dayanmaz yüreğim çilve nazına,

Dokunupda  ere-medim  hazına,

Aşkın  tohumunu  ekti yürüdü.

Yaradan yaratmış asil genleri, 

Hele yüzündeki siyah benleri,

Terlemiş, kokulu, nemli tenleri,

Burnuma gül gibi koktu yürüdü.

Çırpınır yüreğim uçar yerinden,

Kıskanırım seni başka birinden,

Yanıyor bedenim sevda korundan,

İliğmi,  kemiğmi  yaktı  yürüdü.

Sensiz koca dünya dar artık bana,

GÜLÜM; sen bir yana dünya bir yana, 

Uykusuz gözlerim boyandı kana,

Kanıma,  serime  aktı  yürüdü.

DOĞANİ sana kul, koru şanımı,

Aşkınla suladın damar kanımı,

Kavuşmazsam Mevlam alsın canımı,

Dünyayı  başıma  yıktı  yürüdü.

10.3.2006', 'O nasıl bakışdı öyle ah! GÜLÜM, Gözleri gözüme baktı yürüdü. Yüreğmim içine okudu gazel, Beni de ardına taktı yürüdü. Kaşına gözüne sürmüş n...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/o-nasil-bakisdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marka meraklısı!', 'marka-meraklisi-mesut-ozturk-jdy2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen en güzel ortamlarda gezersin,

Pantolonun gömleğin kalitelisini giyersin,

Arabanın son model olanını sürersin,

Ha! Birde en lüks lokantalarda yemek yersin.

Markası olmalı kullandığın herşeyin,

Korkun hiç yok, kurtulmuş zaten geleceğin,

Biz kimiz? olamayız senin düzeyin,

Herşeye doymuşsun, kalmamış göreceğin.

Dinle! Benim bir sözün var; Sana söyleyeceğim? 

Dış görüntü önemli değil, dinle bitmedi diyeceğim.

Bilmiyorum belki de yok sana vereceğim.

Bizlerin gönlü kaliteli, marka adı; Dost yüreği!', 'Sen en güzel ortamlarda gezersin, Pantolonun gömleğin kalitelisini giyersin, Arabanın son model olanını sürersin, Ha! Birde en lüks lokantal...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/marka-meraklisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olabilmek', 'seninle-olabilmek-burak-alemdar-sem8s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizliğin saati vurdu yine bedenime

Geldi çöktü sensizliğin karanlığı

Seveceksin ihtimali ve gözlerin...

Aldı götürdü uzak diyarlara ihtimalli, ihtimalsiz...

Karanlığı yırtıpta gözlerini görebilmek...

Sevda ırmağında ceylanlarla su içebilmek..

Ve belkide kalmadan gitmeden sevebilmek..

Sen ve düşüncemle mümkünmü..? 

Her seferinde acı çekermiş yanlızlığım

Ve her seferinde düşünmekten seni..

Sadece görünürmüş yaşam..

Dibine batmadan dünyanın...

Düşüncelerimde sensizim ve yoksulum..

Sevmeyi öğrendim sende...19 yaşında

Ve 19 sene bağlanmışım düğümüne..

Karanlığın gölgesinde..

Artık vakti geldi karanlıktan çıkmak..

Acımadan gözlerimi açabilmek..

Seni düşünmek,

Sana varmak,

Ve seninle olabilmek

Artık vakti geldi...', 'Sensizliğin saati vurdu yine bedenime Geldi çöktü sensizliğin karanlığı Seveceksin ihtimali ve gözlerin... Aldı götürdü uzak diyarlara ihtim...', ARRAY['Türk Edebiyatı','Şiir','Burak Alemdar']::text[], 8.5, '{"poet":"Burak Alemdar","poet_slug":"burak-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seninle-olabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamazsın', 'dayanamazsin-i-smail-dogan-h1mje', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Terk edip giderken öldürdün beni, 

Arama  boşuna,  dayanamazsın. 

Pişman olur da bir gelirsen geri, 

Hiç bakma kaşıma, dayanamazsın. 

Giderken geride acılar kaldı, 

Kanayan yüreğim uykuya daldı, 

Şu kirli ahlağın  ömrümü çaldı, 

Yıpranmış yaşıma, dayanamazsın. 

Duvarlar üstüme üstüme gelir, 

Uykusuz halimi geceler bilir, 

Sevgisiz bir hayat, tükenir ölür, 

Zehirli aşıma, dayanamazsın. 

Unuttum her şeyi dünyam yıkıldı, 

Yanık kalbim üzülmekten sıkıldı, 

Tüm resmin yıtıldı, mektup yakıldı,

Kızarmış şişime, dayanamazsın. 

Beni pis oynuna  edersin alet,

Olursun eş dostun gözünde zillet

Gün gelir ölürsem duyarsın elbet,

Çürümüş döşüme, dayanamazsın.

Der DOĞANİ dur gardaş dinle beni,

Her gün mum  ışığıyla  arar seni,

Kader  işte; yeniden kur evini,

Hayat güzel değer, dayanmalısın.', 'Terk edip giderken öldürdün beni,  Arama  boşuna,  dayanamazsın.  Pişman olur da bir gelirsen geri,  Hiç bakma kaşıma, dayanamazsın.  Giderk...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dayanamazsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sessizliği', 'mevsim-sessizligi-vedat-koparan-qf0sv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kıyılar öyle sakin kupkuru bir güz söylencesinde 

Bu mevsimde kıyılar, sesiz sokaklar, çıplak dallar gibi 

Yalınayak gezdiğin o günler kalmıştır geride

Yavaştan iç deniz çekmeye başlar kendini

Anılar buharından arayışın izi düşer gözlerine. 

Sessizliğin sesidir ortalığı çınlatan 

Dinlemek, duymak istenir ”sesinde şarkısı aşkın” güncesi 

Fırtınada kara bulutlardır toplanan

Serçeler eşlik eder, gelir sığırcık kanatlarında kar üşümesi

Kekremsi vişneçürüğüdür genzine dolanan

Kalmamıştır artık eski zamanların tadı 

An gelir bir öğlen rehavetinde 

uyumak istersin kahve şekerlemesiyle

Gözlerin aranır, sözlerin aranır, sımsıcak ellerin aranır 

Uzanılan hep bir hayal ötesi boşluktur

Eğreltiotu gibi devrilir kalırsın kıyılar boyuna.

Hüzün anlarıdır sana gelmelerim 

Mevsim sessizliğini verdin akşam gönencinde 

Oysa gök mavisinden sevinçleri toplamak isterdim

Yıldız kovalayan gözlerinde

ölümüne bir intihar çiçeğidir bittiğim 

Vedat Koparan 10.03.2006', 'Kıyılar öyle sakin kupkuru bir güz söylencesinde  Bu mevsimde kıyılar, sesiz sokaklar, çıplak dallar gibi  Yalınayak gezdiğin o günler kalmı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mevsim-sessizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimin Sancılarında Büyüyen Kırıklar', 'i-cimin-sancilarinda-buyuyen-kiriklar-vedat-koparan-d9iau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Yaşamak şakaya gelmez dersin iyi dersin usta

Bilirsin ki bu denli zora girmiş, O denli ekmek üretilip alamazken

Onca fabrika iş alanı varken işsiz kalınırken 

Gece çökünce yorgun yataklar bedenleri sararken

Üşüyen bedenler iki büklüm bir boğum olur sancılar içinde kıvrılırken

Kaç bomba düşer kaç parçaya bölünür vurgun yaşamlar 

İçimin sancılarında büyür habire kırıklar 

Hey kızılca kıyametin habercileri, sararmış yüzler görürüm 

avurtları çökmüş çocuk yüzlerinde, bir avuç kalmış toprağa serpilecek tohumlar 

Anla beni usta çok fenayım 

Çıkartıp söksem derim yüreğimi göğsümden..)

Anlatımı bile ne zor öyle yalnız öyle bir kırıklık var ki içimde 

İsyan büyütüyorum her seferinde batıp doğan güneşle 

Ağlıyor içimin çocuğu boşa akan bir çoban çeşmesinde

Sen geliyorsun bir beni böyle dirençle tutan düş gezginliğime

Bu hangi sarı saman çöpüdür ateşler içinde gözüme batan

Bu hangi yitik geçmiş zaman rüzgârıdır böyle esip kavuran

Bu hangi güz yaprağıdır dalından kopmuş rüzgârda savrulan 

Bu hangi limandır gemilerin uzak geçişinde bir başına kalınan

—Söyle Ne Olur İçimin Sancıları Ne Zaman Diner EğerSen Yoksan -

Vedat Koparan 10.03.2006', '(Yaşamak şakaya gelmez dersin iyi dersin usta Bilirsin ki bu denli zora girmiş, O denli ekmek üretilip alamazken Onca fabrika iş alanı varke...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icimin-sancilarinda-buyuyen-kiriklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Çok Yürekler Yıpranır', 'en-cok-yurekler-yipranir-candan-sevinc-0fvwe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakarım giden günlerin ardından

Ne çok anı yazılır

Bu bilinmez kargaşa içinde

En çok yürekler yıpranır

Tadarım havadaki o masum kokuyu

Ne çok kapı kapanır

Bu huysuz dümen içinde

En çok yürekler yıpranır

Alırım ellerime dünden kalan baharı

Ne çok cümle harcanır

Bu hayali boşluk içinde

En çok yürekler yıpranır.', 'Bakarım giden günlerin ardından Ne çok anı yazılır Bu bilinmez kargaşa içinde En çok yürekler yıpranır Tadarım havadaki o masum kokuyu Ne ço...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-cok-yurekler-yipranir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kagittan Kaltak Kadin', 'kagittan-kaltak-kadin-i-brahim-ethem-uzun-d4fvd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gozlerin meydan okuyor bana

Kabul ediyorum meydan okumana

Ey korkaklarin korkagi yaklas yanima

Yildirimin gurultusuz bak sana

Silahini cikar vur beni

Goreceksin sana olan reddimi

Kiskanclik katre sende

Kiskanclik tufan bende

Hazreti Mesih gibi degilim

Sag yanagima vurunca sol yanagimi  cevireyim

Deynek elime gecti artik benim

Diledigim gibi kiskancligimi yirtayim

Ey  en son tanidigim kadin

Karekterinin surlari  kagittan

Duygularinin kiymeti uc kurus dirhemden

Varligimin yoluna set de ceksen 

Korkacak miyim ki kim oluyorsun ki sen

Uyariyorum seni  kendi kendine kibirlenmekten

Yarin goreceksin kimim ben

Gorecegim memelerin  yarin

Gulu solduktan sonra kimsin sen

Beni ikinci bir sevgiyle mi tehdit ediyorsun

Erkekligimi baska bir erkeklikle mi tehdit ediyorsun

Biyik altindan guluyorum sen gormuyorsun

Ben biliyordum zaten 

Sen bes para etmezsin

Birakmadim  hic bir kadini meyvesini yemeden

Alirim kokusunu minikcik olsa bile ihanetin

Isterse arkasina saklansin kaf daginin

Senin yanina yaklasan kim olursa olsun

Benim kolem bile olamaz isterse sultan olsun

Memelerinin mermerlerine kazidigim destanlari okusun

Erkeklik nasil olurmus gorsun anlasin

Biliyorum kolem cildiracak birden

Memelerinde hala  yankilanan

Sihirli parmaklarimin atesli sesinden

Onu oldurmeye yetecek hemen eminim

Cisminin her noktasina bastigim muhrum

Kuyunun kapagini ben actim ilk

Billur berrak suyunu ben ictim ilk

Birak icsin pesimden gelen kolem

Bulanik bulasik suyumu kuyunda biraktigim', 'Gozlerin meydan okuyor bana Kabul ediyorum meydan okumana Ey korkaklarin korkagi yaklas yanima Yildirimin gurultusuz bak sana Silahini cikar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kagittan-kaltak-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halüsinasyon', 'halusinasyon-tulay-sustam-fgebq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni kendimde gördüm.

kimbilir! ...

ben kimdeyim?', 'seni kendimde gördüm. kimbilir! ... ben kimdeyim?...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/halusinasyon-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten Üşümede', 'ten-usumede-vedat-koparan-84b3o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tükensin tüm zamanlar yansın geceler 

Barutumuz sınırsız nasılsa yürek atımında 

Demleniyorum güzel gözlerinde 

Gelince gidişinin anı 

Daraldıkça zaman daralıyorum 

Tutamıyorum kendimi asi bir rüzgâr olup 

Kırıyorum sevda ağacımın dallarını 

Zonklatıyorsun şah damarımı

Çatlatıyorum gecenin kristal camını 

Gece ve Sen bir de ah uzak zamanlar 

O güzel gözlerine baktıkça taçlanıyor 

Bir başka alevleniyor gece

Ten üşümesi yokluğun ateşine düşüyor

Bir ben şiirde dizelerim yanıyor

Ne güzel mütevazı bir sestir ki o içinin sesi 

Alır beni kendine nasıl çeker bir bilsen 

Suyun çektiği aç toprağın suyu içtiği kadar

Sende kalır sende kaybolurum

Vedat Koparan 09.03.2006', 'Tükensin tüm zamanlar yansın geceler  Barutumuz sınırsız nasılsa yürek atımında  Demleniyorum güzel gözlerinde  Gelince gidişinin anı  Daral...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ten-usumede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katran Karası Gece', 'katran-karasi-gece-murat-akcan-5gumt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Katran karası gece

Derin ve sessiz

Sevda ateşin,

Kayan bir yıldız gibi

Düşer yüreğime.

Özlemin olur

Yüreğimdeki ateş.

Akar gözlerimden

Kızılcık damlası.

Sensiz geçen,

Her gecem

katran karası

Mart-2005/Adana', 'Katran karası gece Derin ve sessiz Sevda ateşin, Kayan bir yıldız gibi Düşer yüreğime. Özlemin olur Yüreğimdeki ateş. Akar gözlerimden Kızıl...', ARRAY['Türk Edebiyatı','Şiir','Murat Akcan']::text[], 8.5, '{"poet":"Murat Akcan","poet_slug":"murat-akcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/katran-karasi-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordukça', 'sordukca-volkan-odabas-p22qi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sordukça büyüyor dünyamız,

sordukça seviyor bizi.

belki bir ağaç gibi ayaklarımız; 

sordukça öğreniyor toprağı sevmeyi...

ölüm de bir sorudur; 

yanıtsız...

yalnızca:

yaşar gider,

akıllarda ve 

alışkanlıklarda...', 'sordukça büyüyor dünyamız, sordukça seviyor bizi. belki bir ağaç gibi ayaklarımız;  sordukça öğreniyor toprağı sevmeyi... ölüm de bir sorudu...', ARRAY['Türk Edebiyatı','Şiir','Volkan Odabaş']::text[], 8.5, '{"poet":"Volkan Odabaş","poet_slug":"volkan-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sordukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen Gecede', 'usuyen-gecede-vedat-koparan-0oe8z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceye sıradağlardır gölgesinde uzanan

Uzak kalıyor resmin gözlerimin neminde

Çekip alamıyorum gülüşünü bakışından

Camın buğusu dağılmış odam buz kesmekte

Gelmiyorsun can gelemiyorsun cana

İçinin denizinde köpürmekte dalgaların

Akamıyorsun nehir gibi yardan salınırcasına

Sarsak sancıların koynunda büyüttüğün tutsaklığın

Kıramıyorsun gecenin belini vurup isyanını karanlığın

Yaşanan an bir parmak ucu dokunuşu geceden alınan

Engeller aşılmaz, sınırlar o kadar uzak değil oysa 

O bakış tufanında öptük taçlandırarak geceyi alnından

Ve bir gün daha yitip gider çekilir gecenin perdesi

Günün anısı belleğimize kayda değerleriyle geçerken

Sen yorgun bedeninle uykuya dem vuran saatlerine

Ben geceye gece bana, sensiz saatlere gitmekteyim

Yeni doğacak günü karşılamak üzere gözlerinde

Vedat Koparan 09.03.2006', 'Geceye sıradağlardır gölgesinde uzanan Uzak kalıyor resmin gözlerimin neminde Çekip alamıyorum gülüşünü bakışından Camın buğusu dağılmış oda...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/usuyen-gecede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskil Böyle Biline (Aksaray''ın Eskil İlçesine)', 'eskil-boyle-biline-aksaray-in-eskil-i-lcesine-yavuz-bayram-caliskan-ezf42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sofradan sızgıtları eksik olmaz,

Azıkları olmadan asla tarlaya gelmez,

Kini, gafleti, onlar asla bilmez,

Tozu ile toprağı ile Eskil böyle biline.

Süt ile pirinçten zerde yaparlar,

Misafiri daha yoldan kaparlar,

Bir kenara atarsan Aksaray’dan koparlar,

Tozu ile toprağı ile Eskil böyle biline.

Karatepe’den Böget’e uzanan sazlar,

Bir başka yaşanır Eskil’de yazlar,

Salına salına yürür Eskil’de kızlar,

Tozu ile toprağı ile Eskil böyle biline.

Akgöl’den öte bir ışık görünür,

Gelen arabalar toza bürünür,

Yaylanın serininde insan sarınır,

Tozu ile toprağı ile Eskil böyle biline.

Elinden tutarsan insan yücelir,

Bir adım atarsan Eskil on gelir,

Yiğitlik otağını insan burada bulur,

Tozu ile toprağı ile Eskil böyle biline.

Yavuz Bayram aklına geleni söyler kalemiyle,

Eskil’li dostluğu, kardeşliği sunar eliyle,

Akar durur mertlik, insanlık seliyle,

Tozu ile toprağı ile Eskil böyle biline.', 'Sofradan sızgıtları eksik olmaz, Azıkları olmadan asla tarlaya gelmez, Kini, gafleti, onlar asla bilmez, Tozu ile toprağı ile Eskil böyle bi...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eskil-boyle-biline-aksaray-in-eskil-ilcesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Doğum', 'kutlu-dogum-mehmet-sukru-bas-7eaox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldi cihane, gelmişlerin sultanı,

Pirunur oldu afak, hakk nail oldu.

Kırıldı cehaletin paslı zinciri,

Karanlık gönüller aydınlık oldu.

Bir öksüzdü dünyaya geldiği zaman,

Yaradan o öksüzün vasisi oldu.

Hira dağında Cebrail''le beraber,

Kutup oldu aleme, nurangah oldu.

Alemlere rahmet kıldıya onu hakk,

Yer ile yeksan putlar, yerle bir oldu.

Ey can dön şu alemin iksirine bak,

Olmasaydı bu doğum,alem n''olurdu? 

Ne mübarek olay bu kutlu doğum,

Alemlere rahmetin serpildiği an.

Yok olması batılın doğması hakk''ın

Her hakkın sahibine verildiği an.', 'Geldi cihane, gelmişlerin sultanı, Pirunur oldu afak, hakk nail oldu. Kırıldı cehaletin paslı zinciri, Karanlık gönüller aydınlık oldu. Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kutlu-dogum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak yirmiden iki önce..', 'safak-yirmiden-iki-once-bilal-i-lhami-koksal-qmdig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başlamak...

Soğuğun iyiden iyiye haddini aştığı hatta bayağı ukalalaştığı zamanlarda

Sanırım hala sana aşığım.

Bu sabah aynaya bakarken kendi kendime 

''Seni unuttum'' dedim 

Kendim bile inanmadım

Sonra sular akmadı

Nedense bir kaç gündür böyle oluyor

Ben musluğa küfrettim 

Suyun günahını demirlere ödetiyorlar bilesin

Senin suçunla ben cezalanıyorum

Eyvah diyeceğim çok senelerim oldu

Hatta senelerden uzun günlerim

Galiba bir yalanmış bizimkisi

Hani beş ondalık sağanaklar gibi

Ama galiba gerçekten de yalanmış seninkisi

Dilime bir şarkı kaldı

Kelimelerinin çoğunu unutuyorum

Hayallerimi kim -senin üstüne kurmuyorum

Alfabenin her harfine eşit mesafede duruyorum

Beni beter ettin ya buralarda

Her şeyi 

Her şeyi senden biliyorum', 'Başlamak... Soğuğun iyiden iyiye haddini aştığı hatta bayağı ukalalaştığı zamanlarda Sanırım hala sana aşığım. Bu sabah aynaya bakarken kend...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/safak-yirmiden-iki-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıksa adam ne desen hayra yorar', 'asiksa-adam-ne-desen-hayra-yorar-bilal-i-lhami-koksal-lxsov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demek ''sonumuz yok''

Demek ki doğruymuş

Hala beni seviyorsun', 'Demek ''sonumuz yok'' Demek ki doğruymuş Hala beni seviyorsun...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/asiksa-adam-ne-desen-hayra-yorar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarda Sevda', 'daglarda-sevda-mustafa-yigit-5s1o4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaz bahar demeden,

Dolanırım Dağların zirvesinde.

Kırarım zincirleri

Özgürlüğü yaşarım,

Gök le Yerin birleştiği yerde.

Yağmur bulutları sarar,

Akıtır göz yaşlarını

Suya hasret ormanlar,

Yoldaş olur yalnızlığıma

Sevdalanırım..dağların zirvesinde.

Yeniden gülümser Güneş,

Salınır gelinliğiyle

Baharda ağaçlar.

Kuşlar şarkı söyler,

Coşku dolar gönlüme

Hür yaşarım dağların zirvesinde.

Mart-2006-Adana', 'Yaz bahar demeden, Dolanırım Dağların zirvesinde. Kırarım zincirleri Özgürlüğü yaşarım, Gök le Yerin birleştiği yerde. Yağmur bulutları sara...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit']::text[], 8.5, '{"poet":"Mustafa Yiğit","poet_slug":"mustafa-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglarda-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Tozları kaldı*', 'tozlari-kaldi-zernisan-aydogan-l87zp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilimden türkü şarkı düşmezdi

Kalpte kötülük yok yüzler gülerdi

Gitti  gençlik elden geri gelmez ki

O eski günler nerede kaldı

Toz pembe bir hayatım vardı

Pembesi gitti de tozları kaldı

Gittiğim yollar hep yokuş çıktı

Bedenim yoruldu gücüm kalmadı

Tutunacak birtek dalım olmadı

O eski günler nerede kaldı

Toz pembe bir hayatım vardı 

Pembesi gitti de tozları kaldı

Saçıma ak düştü yüze çizgiler

Ayaklarda fer yok tutmuyor dizler

Yaşlanınca insan ilgi ister saygı ister

O eski günler nerede kaldı

Toz pembe bir hayatım vardı

Pembesi gitti de tozları kaldı

Yıprattı beni şu zalim yıllar

Dertler acılar sahte dostluklar

Su misali aktı ömrümden yıllar

O eski günler nerede kaldı

Toz pembe bir hayatım vardı

Pembesi gitti de tozları kaldı 

                          10 Mart 2006/Erzurum', 'Dilimden türkü şarkı düşmezdi Kalpte kötülük yok yüzler gülerdi Gitti  gençlik elden geri gelmez ki O eski günler nerede kaldı Toz pembe bir...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tozlari-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Plaka', 'plaka-bilal-i-lhami-koksal-kbo7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden sonra

Ben burada hani hep il olmak isteyen ilçeler gibiyim

Kendi plakama özlemli...', 'Senden sonra Ben burada hani hep il olmak isteyen ilçeler gibiyim Kendi plakama özlemli......', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/plaka-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni sorarsan...', 'beni-sorarsan-bilal-i-lhami-koksal-3aenh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni sorarsan hala her halinden şikayetçi yine

Kahverengi rengi...', 'Beni sorarsan hala her halinden şikayetçi yine Kahverengi rengi......', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/beni-sorarsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Dünyası', 'cile-dunyasi-ali-cengiz-turan-txzes', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar çaresizdir zaman karşı,

Önüne kattıklarını alıp gidiyor,

Bir boşluk misala yutarcasına,

Kemiği toprağa saçıp gidiyor.

Çağımız zamanla yarış etsede,

Seneler geçsede ömür bitsede,

Hertürlü zevklerle sefa etsede,

Zaman dediğimiz ayırt etmiyor.

Yıllar geçtikçe,gençlik gittikçe,ömür bittikçe,

Gençliğin canlılığın yavaş yavaş tükendikçe,

Bedeni yakan alev sessiz sessiz söndükçe,

Ayı veyahut merihi fethetmek neymişki? 

Zaman dediğimiz akıpta geçen,

Ömürleri yutan,Hayatı biçen,

Acıları açan dertleri silen,

Zaman dediğimiz bilmem dururmu?', 'İnsanlar çaresizdir zaman karşı, Önüne kattıklarını alıp gidiyor, Bir boşluk misala yutarcasına, Kemiği toprağa saçıp gidiyor. Çağımız zaman...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cile-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozan', 'ozan-nihat-yucel-hhsqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu insan denilen varlık

Kadrini bilmez ozanın

Dargınlıklar düşmanlıklar

Aklına gelmez ozanın

Sevgisi gönlünden taşar

Kendi benliğini aşar

Sıkıntı içinde yaşar

Hiç yüzü  gülmez ozanın

Zaman ulu bir akıştır

Aşk yürekte bir yakıştır

Yarası nakış nakıştır

Derdi onulmaz ozanın

Ozan olan bunu bilir

Bir gün sıra ona gelir

İnsan doğar yaşar ölür

Eseri ölmez ozanın

1974', 'Şu insan denilen varlık Kadrini bilmez ozanın Dargınlıklar düşmanlıklar Aklına gelmez ozanın Sevgisi gönlünden taşar Kendi benliğini aşar Sı...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-ethem-turan-zqzrw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde gözlerim yine

En özgür nedir diye düşündüm 

Milyarlarca gök cisimleri mi 

Yoksa uzaya ışık saçan yıldızlar mı diye

Hiç sorumsuz nedir diye düşündüm nedense 

Yeni doğan çocuk geldi hatırıma 

Olsa,olsa odur diye 

Kimin sevgisi,sevdası sonsuzdur düşündüm 

Annem geldi gözümün önüne 

Ölümü hiç eden nedir dedim kendime 

Hiç düşünülmeden uğruna ölünen

Toplumları  millet eden nedir dedim 

Vatan geldi  karşıma 

İnsanı  temizleyen gönül ilacı nedir dedim 

İnanç geldi aklıma

İnsanı insan eden nedir dedim 

Karakter çıktı karşıma 

Doğruları bilmenin ne önemi var diye düşündüm 

Cilalı ayakkabılar, marka arabalar 

Hatırlı dostlar varken 

Doğruları söylemenin ne önemi var

Söylenilse de ortalığı karıştıran 

Milleti soyan nasılsa birileri çıkar 

Özgürüm dediğin her anda 

Bulutlar kapatmamışsa

Ancak yıldızlara bakarsın

Sınırlarını zorlamadan  iç çekmeden 

Gönül rahatlığıyla 

Bir çocuk sorumsuzluğuyla 

Bakar dalarsın  memleket rüyalarına', 'Gökyüzünde gözlerim yine En özgür nedir diye düşündüm  Milyarlarca gök cisimleri mi  Yoksa uzaya ışık saçan yıldızlar mı diye Hiç sorumsuz n...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ozgurluk-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Geldikki', 'neden-geldikki-ali-cengiz-turan-1a4yy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akıllar menfaat,nefs menfaat,

Sevişmek menfaat,sevgi menfaat,

Tarlayı hor görüp ekiş menfaat,

Menfaatlar içinde neden geldikki? 

Sevgiler menfaat,ömür menfaat,

Düşünce menfaat,görüş menfaat,

Her şeyin kalesi doğruluksa,

Bilinmeyen dünyaya niye geldikki? 

Gözlerin gördüğü nesne menfaat,

Ciğerin aldığı hava menfaat,

Beynin düşündüğü hayal menfaat,

Menfaatlar dünyasına neden geldikki?', 'Akıllar menfaat,nefs menfaat, Sevişmek menfaat,sevgi menfaat, Tarlayı hor görüp ekiş menfaat, Menfaatlar içinde neden geldikki?  Sevgiler me...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-geldikki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Gezegenler', 'olu-gezegenler-ali-cengiz-turan-9qshw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölü gezegenler hayat arıyor,

Hayat yaymak için,

Güneş arıyor ışık saçmak,

sevgi yaymak için.', 'Ölü gezegenler hayat arıyor, Hayat yaymak için, Güneş arıyor ışık saçmak, sevgi yaymak için....', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olu-gezegenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+Alıp Başımı Gitmeliyim', 'alip-basimi-gitmeliyim-zeki-ergin-jxq3o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alıp başımı gitmeliyim

açık denizlere yelken açıp

bir de sevgili olursa yanımda

umurumda olmazdı

güneş ve ayazda yanmalarım

özgür deniz kuşları yoldaşım

olurdu balıklar sırdaşım

_erenköy 10mart2006', 'alıp başımı gitmeliyim açık denizlere yelken açıp bir de sevgili olursa yanımda umurumda olmazdı güneş ve ayazda yanmalarım özgür deniz kuşl...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alip-basimi-gitmeliyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Sevilmek', 'sevmek-sevilmek-ali-cengiz-turan-7gmg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek sevilmek için ne yazayım ki,

Sevilenler sevenler bir şeyler yazmış,

Şu kısacık hayata ne kanayım ki

Zaman boşluklarında mezarlar kalmış.

Eğri ile doğruyu ne sorayım ki,

Bilinen doğruluklar dillerde kalmış,

Hızla geçen zamana ne kızayım ki,

Kötülüğü iyiliği zaman yaratmış.', 'Sevmek sevilmek için ne yazayım ki, Sevilenler sevenler bir şeyler yazmış, Şu kısacık hayata ne kanayım ki Zaman boşluklarında mezarlar kalm...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-sevilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretin Varsa', 'cesaretin-varsa-halil-aksoy-clfys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamaya  cesaretin  varsa

Varsa  sevmeye  niyetin

Nefes al.

Işıltılı  gözlerle  bak  etrafına.

Gönlünü  açık  tut,

Güneş  ışıkları  girsin  dünyana.

Yaşamaya  cesaretin  v arsa

Varsa  sevmeye  niyetin,

Cesur  ol, cesurca  sev.

Avluda  toplanan güvercinlere 

Yem  at mesela.

Bir  ağlayan  çocuğun  gözyaşlarını sil.

Küçük  bir  kediyi  okşa

Başını  gökyüzüne  kaldır.

Avazın  çıktığı   kadar,

Haykır  sevdiğini.

Gökyüzünden  dökülen,

Yağmur  taneleri,

Anlatsın  sevgini.

Cesur  olmak  zor  bu  devirde.

Zor  delice  sevmek.

Başını  göğe  kaldırıp,

Haykırabilirsen,

Fırtınalara  karşı  koyabilirsen,

İşte  o  zaman  cesurca  seversin.', 'Yaşamaya  cesaretin  varsa Varsa  sevmeye  niyetin Nefes al. Işıltılı  gözlerle  bak  etrafına. Gönlünü  açık  tut, Güneş  ışıkları  girsin ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cesaretin-varsa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nat-ı Rasül', 'nat-i-rasul-dilaver-ozturk-xg2d4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ya Rasül,susuzum

Her mümin gibi sana kavuşmak,

Ravzana dokunmak,

En büyük arzum.

Allah''ın rahmetinden nasip almak,

Hac mevsiminde Arafatta olmak,

Ne yüce cülus,ne yüce hediye.

Ya Rasül beni de şafaatinden

Nasibini alanlardan eyle..

Evet büyüklüğün şüphe götürmez,

Rasüllüğün sınır tanımaz,

Ama nicedir ki nasipsizler aramaz,sormaz,anlamaz.

Ya Rasül, içimdeki şu derin boşluğu

Senin sevginden başkası doldurmaz.

Güneş bile sensiz şu dünyayı ısıtmaz,

Geceler gündüz olmaz,

Ay doğmaz,güneş batmaz sevginsiz.

Ama bu ağaçki kökünü kurutamadılar.

Zincirlere vurdular,

Derince yapraklarını budadılar,

Ancak nafile zincirler kırıldı.

Budanan yapraklardan yeni filizler çıktı.

Ya Rasül, İslam yayıldı.

Ebu Cehiller yok değil,

Her zaman var.

Ama şefatinle mücadele edecek 

Hamzalar her zaman çıkar.

Çünkü bu yol büyük, 

Bu yol yalnız değil.

Yalnız değil kapalı bacım,

Mahzun arkadaşım.

Her zaman yanımızdasın,

Bizlere hala İslamı anlatmaktasın.

Ne yücesin,ne mübareksin

                                                     uşak  10.03.2006', 'Ya Rasül,susuzum Her mümin gibi sana kavuşmak, Ravzana dokunmak, En büyük arzum. Allah''ın rahmetinden nasip almak, Hac mevsiminde Arafatta o...', ARRAY['Türk Edebiyatı','Şiir','Dilaver Öztürk']::text[], 8.5, '{"poet":"Dilaver Öztürk","poet_slug":"dilaver-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/nat-i-rasul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Gerçeği', 'hayatin-gercegi-halil-aksoy-pcrot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yediveren  gülü  gibidir  hayat.

Zaman  hayatın  bir  bütünü.

Sevinçler,coşkular,acılar,

Zamanın  bir  ürünü.

Zaman  açar  en  derin  yaraları  içimizde.

Silinmez  izler  bırakır  yüzümüzde.

Anlatılmaz  acılar  bırakır  derinde.

Bitti  dediğinde,

Sona  geldiğini  hissettiğinde,

Silinmese  bile  en  derin  izleri,

Ustadır,  tecrübeli,

Hayata  bağlamak  için,

İçerir  en  acı  reçeteyi.

Yediveren  gülü  gibi,

İçimizde  patlayıverir,

Hayat  çiçeği.

Her  zaman  gizemlidir.

Vardır  sürprizleri.

Bilinmez  zamanın  bize  ne  getireceği.

Bilinmez  gecelerin  gebeliği.

Bilinen  bir  şey  var,

Tarifsiz  acıların   bile

Zaman  içinde  külleneceği.

Hayat  yediveren  gülü  gibidir,

Zaman  onun  eti   kanı kemiği

İşte  budur  yaşamımızın  gerçeği.', 'Yediveren  gülü  gibidir  hayat. Zaman  hayatın  bir  bütünü. Sevinçler,coşkular,acılar, Zamanın  bir  ürünü. Zaman  açar  en  derin  yarala...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayatin-gercegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım ve Ben', 'kizim-ve-ben-halil-aksoy-3n0td', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her  sabah  güneş  doğarken,

Kaldırır  hepsini  erkenden.

Sıra  sıra  dizer,

Hepsine  can  gelir,

Okşayıp  severken.

Oyuncak  değildir  onlar,

Hepsinin  bir  adı  vardır.

Kızım  yalnız  oynayamaz,

Onlarla  beraber  benide  kaldırır.

Herkesin  bir  rolü  vardır.

Bana  da  bir  görev  düşer.

Rolümü  iyi  yapamazsam,

Beni  azarlar,  kulağımı  çeker.

Bazen  baba  olurum,

Bazen  ağabey  bazen  çocuk

Onun  hayaline  hayranım.

Yetişmeye   gücüm  yetmez.

Onunla  ben  de   olurum

Bazen  yetişkin

Bazen  küçük  bir  çocuk.

Her  sabah  merak  ederim,

Kızım  benden  ne  ister.

Kızımın  emrine  amadeyim.

Başarırız  küçük  dünyasında

Büyük  işler.

İnsan  hayattan  başka  ne  ister.

Bizim  evde  hayat,

Böyle  gelir  böyle  geçer.', 'Her  sabah  güneş  doğarken, Kaldırır  hepsini  erkenden. Sıra  sıra  dizer, Hepsine  can  gelir, Okşayıp  severken. Oyuncak  değildir  onla...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kizim-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen varken vede yokken ben!', 'sen-varken-vede-yokken-ben-mesut-ozturk-y6733', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siyah saçlı,kahverengi gözlüydüm,

Şimdi kel vede maalesef körüm.

Uzun boylu normal kiloluydum,

Şimdi zayıf vede maalesef kamburum.

Hep spor yapar hareketler ederdim,

Şimdi tembel vede maalesef hantalım.

Çıkacak saçlarım,  yanına geldiğimde,

Görecek gözlerim,seninle güldüğünde,

Gidecek kamburum, herşey yoluna girdiğinde,

Koşacak ayaklarım beni yeniden sevdiğinde.

Bir önerim var, kendine iyi bak,

Bir ricam var, hiçbir zaman değişme,

Bir isteğim var, beni unutma,

Bir sözüm var, seni seviyorum.

Ve bir gerçek, sen özelsin.', 'Siyah saçlı,kahverengi gözlüydüm, Şimdi kel vede maalesef körüm. Uzun boylu normal kiloluydum, Şimdi zayıf vede maalesef kamburum. Hep spor ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-varken-vede-yokken-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurum Mavisi', 'ucurum-mavisi-serap-mutlu-65e2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevda düzlüğe çıkamadı…

gözyaşlarını tutamadı… 

hazin karanlığı yıkamadı… 

zincirleri kıramadı… 

tutsaklığı vuramadı…

sevda dünlere kaldı… 

sevda yarını aldı… 

kurak bir yağmura daldı… 

sevda yanıldı…

kör karanlık içiliyor şimdi, 

sevdanın boğazında büyüyor isyan…. 

Işığına sefilim, hadi tut güneşimi, karanlığına boğ beni…

……

görüyor musun uçurum mavisini? 

Issız güzelliğini duyuyor musun? 

Görsen boğulurdun, duysan kanatırdın sesini

duymuyorsun… 

görmüyorsun…

boğuluyorsun….

……

gidiyorsun... 

görüyorum adımlarının hüzünlü izlerini..

gidişine uyandırma beni...

uyuyorum sevginin ölümsüzlüğünde...

uyuyorum ıslak sessizliğimde.... 

sancılı geceleri yanıma alıp uyuyorum...

uyandırma beni.... 

seziyorum gidişini...

seziyorum bitişini...

gidişini görüyorum... 

gidişine uyandırma beni... 

gidişlere ağlamıyorum artık... 

yanmıyorum bitişlere... 

gitmiyorum de ağlat beni...

haykırma büsbütün yıkılmışlığımı...

bitmiyorum de ağlat beni....

gitmiyorum de...', 'sevda düzlüğe çıkamadı… gözyaşlarını tutamadı…  hazin karanlığı yıkamadı…  zincirleri kıramadı…  tutsaklığı vuramadı… sevda dünlere kaldı…  ...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ucurum-mavisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadını Öpmek Sorumluluk İster...', 'bir-kadini-opmek-sorumluluk-i-ster-halil-aksoy-6kwfv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Kadını Öpmek Sorumluluk İster...', 'Bir Kadını Öpmek Sorumluluk İster......', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bir-kadini-opmek-sorumluluk-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsme', 'kusme-guner-kurt-mcyv5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elde sevda

Elde şefkat 

Gördüm sanma

Üz istersen beni

Ölesi kahret ama

Bu inattan vazgeç

Beni unut yada

Lakin  yaşayamam

Ben böyle 

Hadi gül biraz

Biraz gülümse

Eller eldir

Daha söyletme

Bana sen

Bana sevdan

Bana aşkın

Ya çek vur

Bir tek kurşun

Ötesi vurgun

Bana sen gerek

Anla işte

Üz istersen

Ama ne olur 

Küsme', 'Elde sevda Elde şefkat  Gördüm sanma Üz istersen beni Ölesi kahret ama Bu inattan vazgeç Beni unut yada Lakin  yaşayamam Ben böyle  Hadi gül...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kusme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ben Sevdim', 'seni-ben-sevdim-salim-erben-9oxo8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bendeki seni sevdim

Aşka dair ne varsa 

Gözleriyin kahvesi işledi

Bakışlarını yüreğime

Okudum adını yazdım 

Kitaplara sığmayan 

Benim sevdamın

Ben bendeki seni sevdim

Sen sevmeden önce 

Kutsal bildiğim ne varsa

İlkin

Gelmiş geçmiş bitirdim

Hükümsüz kıldım 

Çıplak ellerine bıraktım 

Çaresizliğimi yüreğimden

Anlıyormusun beni 

Seni ben sevdim zalım', 'Ben bendeki seni sevdim Aşka dair ne varsa  Gözleriyin kahvesi işledi Bakışlarını yüreğime Okudum adını yazdım  Kitaplara sığmayan  Benim se...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-ben-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Hüzünler', 'islak-huzunler-serap-mutlu-popy6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerin, düşlerin, yüreğin tutulmuşsa geceye...

gün doğar gece sanırsın,

aklın fikrin yıldızlardadır

ne gün seni aydınlatır

ne de gece yanına alır....

gece susar, susar gider...

üşür suskunluğun...

bir ses duyulur uzaklardan, çarpar yakamozlara.. 

bir ses ki yüreğin sımsıcak ardında...

inanamazsın... 

inanamazsın büyüleyen yankısına...

uyanır sessizliğin...

uyanır gider ne varsa... 

neyin varsa soyunur gider ardından...

korkar korku bilmez gözlerin,

görmedim sanır gördüğünü...

uzanır yere dağılır... 

görmedim der aldanır...

sorasın gelmez... 

ya bu çırpınan kuş? 

sorasın gelmez...

neden çırpınır? .... 

korkar soruların....

üşür suskunluğun... 

o güzel kuşa bakasın gelmez... 

üşür bakışların...

için sımsıcak... 

beklemediğin gelmiş kapına...

gelişinin güzelliği.... 

büyür korkuların...

bir papatya çıkar önüne... 

gecenin karanlığına inat...

yitik buruk gülümser... 

hasretinle gülümser...

ellerinin kokusu....

ah bir bilsem dediğin... 

gülümser papatya... 

boğulmuş kokusuna ellerinin...

bir sen gülemezsin... 

karanlığına tutsak...

hasretinin bildik yankısı...

kulaklarında aynı şarkı... 

gözlerinde aynı gülümsemenin izi...

inanasın gelmez... 

dolar dolar taşarsın... 

ıslak hüzünler yanı başında.... 

içini acıtan bir yokluk uğuldar... 

boğazında boğuk bir sözcük... 

düştü düşecek... 

dağıldı dağılacak geceye... 

yutkunur yutkunur boğulursun....

büyür suskunluğun....

nasıl ılık bir meltem eser...

nasıl uyku çeker canın...

başını yaslasan kucaklayacak yastık seni... 

bir uzansan bitecek her şey sanki...

bilinmeyen soluksuz bir uyku.... 

sonsuz bir düş sanki... 

kapatsan gözlerini... 

gidecek sanki her şey....

bütün hüznün, yorgunluğun, umutsuzluğun...

kapatasın gelmez... 

direnirsin hayaline.. 

boğulmak istersin o delice hüzne... 

boğulmak gözlerine, gülüşüne... 

nasıl seversin o her yanını sarmalayan hüznü...

eriyip gidesin gelir hayaliyle... 

o boğan geceyi nasıl seversin...

nasıl seversin hasreti... 

içi güneş dolu çığlıklar atasın gelir....

içinden bir yol uzanır papatyalara... 

gecenin karanlığına inat, 

köpük köpük beyazına bir yol uzanır....

kokusuna uzanır...

onun kokusuna....

uzanır gider neyin varsa... 

yapayalnız kalırsın....

ürkekliğin kalır geriye...

birde hüznün... 

nasıl seversin o hüznü... 

nasıl seversin...

dur...

hayrete düşürme bakışlarını....

“hüzünde sevilir mi? ”  deme...

gülüşüme yoksan... 

hüznüm güzelleşir seninle....

hüznüm dolar gidişine...

gelişime yoksan...', 'gözlerin, düşlerin, yüreğin tutulmuşsa geceye... gün doğar gece sanırsın, aklın fikrin yıldızlardadır ne gün seni aydınlatır ne de gece yanı...', ARRAY['Türk Edebiyatı','Şiir','Serap Mutlu']::text[], 8.5, '{"poet":"Serap Mutlu","poet_slug":"serap-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/islak-huzunler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-halil-aksoy-4813t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir küçük kelebek olsam.

Kanatlanıp uçsam.

Rüzgar alsa götürse,

Kocaman bir denize.

Salıverse beni,

Sonsuz maviliklere.

Kanatlarım olsa mavi.

Süzülsem göğe.

Ben bir kelebek olsam.

Mavi bir kelebek.

Konsam mavi çiçeklere.

Dolaşırım tüm maviliklerde.

Ben bir kelebek olsam,

Mavi kelebek.

Bıkmadan uçarım,

Mavi gözlerinin içinde.', 'Bir küçük kelebek olsam. Kanatlanıp uçsam. Rüzgar alsa götürse, Kocaman bir denize. Salıverse beni, Sonsuz maviliklere. Kanatlarım olsa mavi...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kelebek-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susamaktan Korkuyorum Sana', 'susamaktan-korkuyorum-sana-hamza-cobanoglu-n2clk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin terlemiş anne

Çok mu üzdüler seni

Sözlerin keder kokuyor anne

Çok mu üzdüler seni

kokladığım bütün kır çiçekleri; 

Soluyor anne

Bari sen bırakma beni

Ne olur solma anne! 

Kalemimde mürekkep

Damarlarımda kan

Akıyor ya anne

Yüreğimi acılar dağlıyor

Dağlıyor anne! 

Yüzündeki kırışıklıklara çare yok mu

Ya saçlarını boyasak

gelmez mi geriye

O güzelim yılların...

Yüreğin kocaman olmuş anne

Susamaktan korkuyorum sana

Toprağıma değmesin

Gözyaşlarım istiyorum

Varsın şimdi boşalsın,

Boşalsın mendillere.', 'Gözlerin terlemiş anne Çok mu üzdüler seni Sözlerin keder kokuyor anne Çok mu üzdüler seni kokladığım bütün kır çiçekleri;  Soluyor anne Bar...', ARRAY['Türk Edebiyatı','Şiir','Hamza Çobanoğlu']::text[], 8.5, '{"poet":"Hamza Çobanoğlu","poet_slug":"hamza-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/susamaktan-korkuyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç', 'ac-mehmet-can-amous', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geriye bakma 

Önüne bak..

İlerle..

Eski aşkları unut..

Yenilerinden ümit kesme

Sakın bağlanma

Aç kollarını..

Sadece  bekle..', 'Geriye bakma  Önüne bak.. İlerle.. Eski aşkları unut.. Yenilerinden ümit kesme Sakın bağlanma Aç kollarını.. Sadece  bekle.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ac-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Yasak', 'rubai-yasak-nihat-yucel-gzurh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdimse suçum ne yoksa sevmek mi yasak

Eller iki gül dalıysa övmek mi yasak

Hicran bitmez bağrımı dövmek mi yasak

Kaderse eğer bu söyle sövmek mi yasak

                                                       Şubat/71', 'Sevdimse suçum ne yoksa sevmek mi yasak Eller iki gül dalıysa övmek mi yasak Hicran bitmez bağrımı dövmek mi yasak Kaderse eğer bu söyle söv...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana / 2', 'ana-2-emrah-karakoc-gry5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yağmur yağdı ki, bir rüzgar esti

Ne zaman mı? henüz dün akşam üstü

O an da aklıma dünlerim düştü

Ağlamadım Ana yarınlar için

Dolup geldi yaşlar bir an gözüme

Hafif sızı düştü garip gönlüme

Bin bir sitem geldi o an dilime 

Ağlamadım Ana yarınlar için

Üzerime yağmur yağarken hızla

Bir rüzgar vardı ki yaz ortasında

İşte o an oğlun dert ortasında

Ağlamadım Ana yarınlar için

Dalıp da dünlere gitmişken bir an

Bir gök gürlemesi duydum o zaman

Yağmur bir başladı etraf toz duman

Ağlamadım Ana yarınlar için

Bin bir türlü sorun varken başımda

Elimi uzattım ben sıgarama

Paketimde kalan en son sıgara

Yoldaşım olmuştu o anlık için

Ağlamadım Ana yarınlar için', 'Bir yağmur yağdı ki, bir rüzgar esti Ne zaman mı? henüz dün akşam üstü O an da aklıma dünlerim düştü Ağlamadım Ana yarınlar için Dolup geldi...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ana-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmet Ola', 'rahmet-ola-halil-aksoy-sn6lg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaşlarını  çattığında,

Upuzun    bir  duvar  gibi,

Görünürdü  suratı.

Duvarı  delecek  gibiydi,

Bakışları.

Yarı  ağarmış  sakalı,

Postal  gibi  bıyıkları.

Çocuklar  onu  gördü  mü? 

Kaçacak  delik  arardı.

Büyükler  yutkunarak,

Hatrını  sorardı.

Konuşmazdı  kimseyle

Açmazdı  derdini  kimseye.

Paltosunu  savurur.

Yürürken  bir  o  yana

Bir  bu  yana  salınır,

Sanki  düşecek  gibi  olur.

Tekrar  doğrulurdu.

Kimse  evinin  perdelerini

Açık  görmemiş  bu  güne  kadar.

Gerçi  perde  denemez  onlara

Kapatsın  diye  camı

Asmış  bir  çuhayı.

Kimisi  onun  deli   olduğun,

Kimisi  cinlerin  olduğunu,

Söylerdi.

Kimse  bilmezdi  gerçek  derdini.

Bilmezdi  kimse  kalbini,

Bir  gün  Salası  verildi.

Açıldı  artık,

Kapısı,  penceresi.

Yudular  namazını  kıldılar

Hep  bir  ağızdan rahmet   okudular

Dağılmıştı  cinleri  perileri.

Yaradan   rahmet  eylesin,

Hamdi  dili  Hamdi’yi.', 'Kaşlarını  çattığında, Upuzun    bir  duvar  gibi, Görünürdü  suratı. Duvarı  delecek  gibiydi, Bakışları. Yarı  ağarmış  sakalı, Postal  gi...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/rahmet-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Kumral Saçlı Güzel', 'rubai-kumral-sacli-guzel-nihat-yucel-uw2u1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevsem kumral saçlarının her telini

Tutsam bırakıp bir daha tutsam elini

Bir yan bakışın benden alıp gitti beni

Ey kız bu garip senle sever yad elini

                                              Nisan/73', 'Sevsem kumral saçlarının her telini Tutsam bırakıp bir daha tutsam elini Bir yan bakışın benden alıp gitti beni Ey kız bu garip senle sever ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-kumral-sacli-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olurdu!', 'ne-olurdu-hamza-cobanoglu-w8hob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne olurdu yarin bakir elleri avcuma

Terleten bakışları yüreğime saplansaydı

Devasa ellerim çelik parmaklık

Kalbim dipsiz bir boşluk olur

Bırakmazdı onları

Sonsuza kadar...

Sevişen kediler misali çekilip bir kenara

Mırıl mırıl koklaşsaydık sessizce

Yazılıp koca meşenin dibine

Örtünseydik bulutlar yorganını

Kaldırımları eskitseydik bir ömür boyu

Teslim olsaydık ecele elele

Ve yeniden doğsaydık

Kenetlenmiş ellerimizle.', 'Ne olurdu yarin bakir elleri avcuma Terleten bakışları yüreğime saplansaydı Devasa ellerim çelik parmaklık Kalbim dipsiz bir boşluk olur Bır...', ARRAY['Türk Edebiyatı','Şiir','Hamza Çobanoğlu']::text[], 8.5, '{"poet":"Hamza Çobanoğlu","poet_slug":"hamza-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-olurdu-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-emrah-karakoc-cukdf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağla gözlerim ağla 

Yana yana dön ağla

Siz çok mutluydunuz dün

Bu günlere yan ağla

Ağlamak çare değil

Hüzüne verme meyil

Nasıl terkedilmiştin

Ogünlere dön ağla

Ne hayallerin vardı

Hepside yarım kaldı

Yarın tamamlarsın be

Bak yarına ne kaldı

Sen şu ana dön ağla

Bu gün için yan ağla', 'Ağla gözlerim ağla  Yana yana dön ağla Siz çok mutluydunuz dün Bu günlere yan ağla Ağlamak çare değil Hüzüne verme meyil Nasıl terkedilmişti...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerim-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-dilaver-ozturk-ryaal', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlerden bir gün olmuş

Gökyüzünde yıldızlar başka parlak,

Ay yüzüme gülümsüyor,

Mevsimlerden ilk bahar,

Mutluluğum filizleniyor,

Yokluğumda varoluyorum.

Ya Rabbim,sana binlerce şükrediyorum,

Bu ben bir daha böyle olabilir miyim? 

Hayatı bu kadar çok,bir daha sevebilir miyim?', 'Günlerden bir gün olmuş Gökyüzünde yıldızlar başka parlak, Ay yüzüme gülümsüyor, Mevsimlerden ilk bahar, Mutluluğum filizleniyor, Yokluğumda...', ARRAY['Türk Edebiyatı','Şiir','Dilaver Öztürk']::text[], 8.5, '{"poet":"Dilaver Öztürk","poet_slug":"dilaver-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutluluk-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murtaz Ağa', 'murtaz-aga-halil-aksoy-d9ily', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kedileri   hiç  sevmezdi,

Murtaz  ağa.

Gördüğünü   kovalar,

Tuttuğunun  kuyruğuna,

Teneke  bağlardı.

İblis  hayvan  der,

Peşinden,

Tekme  sallardı.

Canı  gibi  sevdiği

Bir  kuşu  varmış.

Onu  bir  kedi  kapmış  dediler.

Ondanmış  düşmanlığı.

Gerçek mi…

Bilinmez  ama,

Bilinen  bir şey  var.

Kediler  kaçar 

Murtaz  ağa  kovalar.', 'Kedileri   hiç  sevmezdi, Murtaz  ağa. Gördüğünü   kovalar, Tuttuğunun  kuyruğuna, Teneke  bağlardı. İblis  hayvan  der, Peşinden, Tekme  sa...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/murtaz-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiiri Gece Yazdım', 'bu-siiri-gece-yazdim-hamza-cobanoglu-xo5eq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana mı kaldı bu kaldırımlar,

Boş sokaklar, dolu boşluklar,

Başımdaki ağrılar,

Yüreğimde sancılar...

Sonbahardan kalma bir gül yaprağı,

Kimi zaman denizin üzerinde bir kuş misali

Bana mı kaldı kayıp gitmek derin maviliklere,

Garipsenecek kadar ıssız yerlere...

Yine gülüyor karanlıklar halime

Şafak söker ancak şu garip bedenime

Aman! Çekin şu güneşin önüne perde üstüne perde

Gözlerim dayanmaz böyle bir hengameye.

Ben gecelerin çocuğuyum

Mehtaplar benim için, yakamozlar, yaldızlar

Benim için uçuşuyor gökyüzünde yıldızlar,

Semalardan boşalan yumuşak hıçkırıklar...

Suya düşen ben miyim bu karanlıkta

Yoksa gölgem mi boğulan

Bir rüya mı, bir hayal mi,

Karanlıkta boğulan?', 'Bana mı kaldı bu kaldırımlar, Boş sokaklar, dolu boşluklar, Başımdaki ağrılar, Yüreğimde sancılar... Sonbahardan kalma bir gül yaprağı, Kimi...', ARRAY['Türk Edebiyatı','Şiir','Hamza Çobanoğlu']::text[], 8.5, '{"poet":"Hamza Çobanoğlu","poet_slug":"hamza-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-siiri-gece-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Çınarım', 'sevgili-cinarim-halil-aksoy-wm60z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir  çınar  var,

Penceremin  önünde.

Her  sabah  kalkınca,

Ona  bakarım.

Havanın  durumunu

Yapraklarından  anlarım.

Yazın  sıcakta,

Gölgesinde  yatar,

Canım  sıkılınca,

Dallarını  sayarım.

Sakın  kuruma  çınarım

Sen  olmazsan,

Ben  ne  yaparım.', 'Bir  çınar  var, Penceremin  önünde. Her  sabah  kalkınca, Ona  bakarım. Havanın  durumunu Yapraklarından  anlarım. Yazın  sıcakta, Gölgesin...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgili-cinarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemiyorum', 'olemiyorum-emrah-karakoc-tukf3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden uzaklarda seninleyim ben 

Hayalin gözümden gitmiyor neden

Söyle gülüm bana ben nasıl edem

Senden uzaklarda yapamıyorum

İsterim dağına yağmasın karlar

İnşallah yüreğin sevinçle atar

Benim yüreğimde dert katar katar

Yarısını sana dilemiyorum

Hep dündeyim gülüm bu günüm kayıp

Gönderdiğin resmi elime alıp

Kim bilir ne hayallere dalıp

Kurduğum rüyadan çıkamıyorum

Emrah ne diyor bak dinle gönüldaş

Benim için bizim mekanda dolaş

Ölüyorum burda ne olur ulaş

Senden uzaklarda ölemiyorum', 'Senden uzaklarda seninleyim ben  Hayalin gözümden gitmiyor neden Söyle gülüm bana ben nasıl edem Senden uzaklarda yapamıyorum İsterim dağına...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olemiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oluş', 'olus-hulya-dogrusozlu-hs01d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hiçtim düş oldum

kalem düştü bir ele

yazın oldum

bir satır kayıttım şimdi

evren kitaplığında

okundum söz oldum

söz söylendi ses oldum

ses çınladı patladı düşün

fışkırdı beyaz ışık

bakamayan göz oldum

kırıldı ışık renk oldum

sığamazken bir yere

bir el kadar ete doldum,

Mavi ve parlaktı gezegen.', 'Bir hiçtim düş oldum kalem düştü bir ele yazın oldum bir satır kayıttım şimdi evren kitaplığında okundum söz oldum söz söylendi ses oldum se...', ARRAY['Türk Edebiyatı','Şiir','Hülya Doğrusözlü']::text[], 8.5, '{"poet":"Hülya Doğrusözlü","poet_slug":"hulya-dogrusozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Mahallem', 'guzel-mahallem-halil-aksoy-9xetf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat  vardı  bizim  mahallede.

Her  sabah  6’da. 

Karşı  ki  komşu,

Arabasını  çalıştırır.

Kapıcı  Rasim  efendi,

Yarım saat  geçmeden,

Kapı  kapı  dolaşıp  ekmek,  ekmek,

Diye  bağırırdı.

Çingeneler  öyrek öyrek   geçerdi,

Sokağımızdan.

Atlı  arabalarıyla.

Kuşlar  aynı  saatte  ötmeye  başlardı.

Hayat  vardı  bizim  mahallede

Sütçü  bağırarak  kulakları  çınlatır.

Sek  sek  oynardı  çocuklar

İp  atlardı.

Teneke  davullar  çalarlardı.

Aynı kediler toplanırdı,

Mahallenin çöp bidonlarına,

Öğle  yemeğine.

Selamlar  hep  aynı   saatte  verilirdi.

Hafif  başlar  öne  eğilerek,

Sevinçler  dertler  hep  paylaşılırdı.

Şimdi  nasıl  acaba,

Benim  mahallem.

Güzel  mahallem.', 'Hayat  vardı  bizim  mahallede. Her  sabah  6’da.  Karşı  ki  komşu, Arabasını  çalıştırır. Kapıcı  Rasim  efendi, Yarım saat  geçmeden, Kap...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/guzel-mahallem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-dilaver-ozturk-ylz21', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık yüzüne bakamam. 

Çünkü solmuş bir gül gibisin.

Biliyorum asla benim değilsin ve

Başka gönüllerdesin.

Ama hiç bir gönülde bendeki gibi,

AÇAMIYORSUN........', 'Artık yüzüne bakamam.  Çünkü solmuş bir gül gibisin. Biliyorum asla benim değilsin ve Başka gönüllerdesin. Ama hiç bir gönülde bendeki gibi,...', ARRAY['Türk Edebiyatı','Şiir','Dilaver Öztürk']::text[], 8.5, '{"poet":"Dilaver Öztürk","poet_slug":"dilaver-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tomurcuk-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Perdeler', 'eski-perdeler-ahmet-simsiki-5sk7d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eski perdeleri kestim,

mendil yaptım.

şimdi bol bol ağlıyorum artık.

ne ellerime siliyorum

gözyaşlarımı salya sümük,

ne de perdelere.

eski perdelerin kesilmişinden

güzel elbezi oldu,

elimin kiri demeli,

eşi dostu sıvazlamıyorum,

kimse görmeden ellerimi,

ceplerime sokmuyorum.

eski perdeleri keseli,

yenisini alamadım.

akşamları ışık yakmıyorum artık,

komşulara kızamıyorum,

perdenin arkasından

kimseye küfredemiyorum.

perdeleri keseli,

sokağa bile çıkamıyorum.', 'eski perdeleri kestim, mendil yaptım. şimdi bol bol ağlıyorum artık. ne ellerime siliyorum gözyaşlarımı salya sümük, ne de perdelere. eski p...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sımsıkı']::text[], 8.5, '{"poet":"Ahmet Sımsıkı","poet_slug":"ahmet-simsiki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eski-perdeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost''a', 'bir-dost-a-emrah-karakoc-vdgec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selam arkadaşım, selamlar sana

Mektubunla sevinç gönderdin bana

Okudum mektubun bilmem kaç defa

Kuş olup da köye gelesim geldi

Gönderdiğin resim sırdaşım oldu

Baktıkça gözüme hep yaşlar doldu

Yazmışsın sözlerim bana dert oldu

Yazan ellerimi kırasım geldi

Çok, çok güzel şeyler dersin mektup da

Nasıl yazdın o sözleri bulup da

Buradan oraya eyledim gıpta

Resmini kalbime alasım geldi

Mektubunla gittim eski günlere

Şimdi mazi olan güzel dünlere

Kurban olam onu yazan ellere

O ellerde kalem oladım geldi

Sitemle doluydu aldığın mektup

Kızmamışsın bana ne büyük lutuf

Yazdığın mektubu kaç kez okuyup

Şükür namazına durasım geldi', 'Selam arkadaşım, selamlar sana Mektubunla sevinç gönderdin bana Okudum mektubun bilmem kaç defa Kuş olup da köye gelesim geldi Gönderdiğin r...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-dost-a-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütüncü Mehmet Efendi', 'tutuncu-mehmet-efendi-halil-aksoy-uaeew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sigarasını   yakar,

Of  ulan  of  derdi.

Tütüncü    Mehmet   Efendi.

Solmadan,

Tütünleri  toplamaktı.

Bütün  derdi.

Solmuş  bir  tütün  görmeye,

Hiç  dayanamazdı.

Mehmet  Efendinin    tütünü,

Solmuş  dedirtmeyi,

Asla  göze  alamazdı.

Irgatını  ırgat  gibi  çalıştırır,

Tarlada  bir  yaprak  bile  koymazdı.

İyi  tütüncüydü

Mehmet   Efendi,

Kendi  gitti  namı  kaldı

Senin  gibi  tütüncüler,

Kalmadı  artık,

Tütünlerin  efendisi,

Tütüncü  Mehmet  Efendi.', 'Sigarasını   yakar, Of  ulan  of  derdi. Tütüncü    Mehmet   Efendi. Solmadan, Tütünleri  toplamaktı. Bütün  derdi. Solmuş  bir  tütün  görm...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tutuncu-mehmet-efendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim Var', 'hayallerim-var-halil-aksoy-sjlzn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayallerim  var.

Hayal  alır  hayal  satarım.

Yaptım  mı  kamıştan  bir  at,

Kanatlanır  uçarım.

Hayallerim  var.

Gazoz  kapağı  alır,

Gümüş  para  satarım.

Telden  arabama  binince,

Herkese  tepeden  bakarım.

Hayallerim  var.

Karpuz  kabuğu  alır,

Karpuzdan  yapılmış,

Arabalar  satarım.

Arabamın

Benzini  kendim  katarım.

Hayallerim  var.

Uçurtma  alır  uçurtma  satarım.

Uçurtmamla  kanatlanır   uçarım.

Hayallerim  var.

Karıncalara  araba  yapar,

Kuşlara  kanat  takarım.

Kartal  gibi  uçar,

Tavşan  gibi  zıplarım.

Hayallerim  var.

Rüyalarımda  alır,

Oyunlarımda  satarım.

Hayallerim  var.

Kılıçlar  yapar.

Ordular  kurarım.

Ordularımın  başında

Baş  kumandan

Düşmanlarımın  hepsini  kırarım.

Ben  bir  çocuğum.

Hayallerimle  her  şeyi  yaparım.', 'Hayallerim  var. Hayal  alır  hayal  satarım. Yaptım  mı  kamıştan  bir  at, Kanatlanır  uçarım. Hayallerim  var. Gazoz  kapağı  alır, Gümüş...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hayallerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Öyle', 'bakma-oyle-halil-aksoy-wkxxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kız  bana  bakma  öyle

Görende  bir şey  var  sanır.

Seni  bizim  mahallede,

Herkes  tanır.

Her  pencereye  çıktığında,

Komşularım,

Benim  el  ettiğimi  sanır.

Kız  bana  bakma  öyle

Seni   mahallenin  delikanlıları,

Beni  karım  kıskanır.

Çamur  atma  bana  öyle,

Yapışmasa  da  izi  kalır.

Aklını  başına  almazsan,

Sana  pencere,

Bana  balkon  yasaklanır.', 'Kız  bana  bakma  öyle Görende  bir şey  var  sanır. Seni  bizim  mahallede, Herkes  tanır. Her  pencereye  çıktığında, Komşularım, Benim  e...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakma-oyle-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldi', 'ne-guzeldi-halil-aksoy-vnmhk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir  şey  eskisi  gibi  olmayacak.

Güneş  eskisi  gibi  doğmayacak.

Ne  güzeldi  o  günler.

Bahçelerde  dolaştığımız,

Erik  yediğimiz

Kelebekleri  kovalayıp

Bulutlara  eşlik  ettiğimiz  günler

El  ele  gönül  gönüle  kaynaştığımız,

Günler  ne  güzeldi.

Ta ki  içimizdeki  yılan  çıkana  kadar.', 'Hiçbir  şey  eskisi  gibi  olmayacak. Güneş  eskisi  gibi  doğmayacak. Ne  güzeldi  o  günler. Bahçelerde  dolaştığımız, Erik  yediğimiz Kel...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-guzeldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman karaya vurma zamanı', 'zaman-karaya-vurma-zamani-ramazan-kayak-r164g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıyısına yanaşmışız hayatın 

Kara göründü görünecek

Fırtınaları çoktan atlattık

Kasırgaları yağmurları

Liman çok uzak değil 

Işıkları sızıyor fenerin 

Belirli belirsiz

Artık 

Ne el sallayan var ardımızdan 

Ne bir bekleyen

Gönlümüzdeki saat durdu

Zaman karaya vurma zamanı

Kıyısına yanaşmışız hayatın

Kara göründü görünecek

Ne geriye dönüş var

Nede ileriye gidilecek

Türküler bile sustu

Kırılgan yüreğimizde

Günler anlamını yitiriyor

Geceler karabasan

Gönlümüzde hala mırıltılar 

Oysa zaman 

Karaya vurma zamanı

Belki bu gün ya da yarın

Kıyısına vurmuşuz hayatın

Biz farkında olmasak bile

Hayat kopuk artık içimize..', 'Kıyısına yanaşmışız hayatın  Kara göründü görünecek Fırtınaları çoktan atlattık Kasırgaları yağmurları Liman çok uzak değil  Işıkları sızıyo...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zaman-karaya-vurma-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutundum Gün Gülüşüne', 'tutundum-gun-gulusune-vedat-koparan-zc286', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şair der ya gülüşün kalır bende 

Hüzün denizi geçerken içimizde 

Gülmeye kurduk saatleri yinede 

Güldeniz olsun gözlerinde 

Sen mavileri getir gecelere

Bahar rüzgârı essin harelerine

İçim acırken hatırına kış üşümesinde

Olmuyor desem de can sahtece

İnanmış görün yapmacık gülüşlere

Dağların zirvesi kahverengine 

Kara gecelerden siyah zeytine 

Süt dökümlü dalında yeşiline

Denizin bulutların mavisine

Tutuldum ay, yıldızlı gecem gülüşüne

Tutundum tutulası  güneşli düşlerine

Vedat Koparan 09.03.2006', 'Şair der ya gülüşün kalır bende  Hüzün denizi geçerken içimizde  Gülmeye kurduk saatleri yinede  Güldeniz olsun gözlerinde  Sen mavileri get...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutundum-gun-gulusune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bayramlar', 'eski-bayramlar-halil-aksoy-uksy9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalmadı  sevdalar,   coşkular.

Kalmadı,

Eski   bayramlaşmalar.

İklimler  bile  değişti  sanki

Değişti,  kelebekler  kuşlar.

Değişti,    selamlaşmalar,   bakışmalar.

Kapı  kapı  dolaşıp  el  öperdik,

Bayramlarda,öğleye  kadar.

Sonra  panayıra  gider,

Renk  renk  pamuk  şekeri  alır,

Tamaşa  seyrederdik.

Bir  sonra  ki bayramı,

Dört  gözle  beklerdik.

Çocukluğumda  her  şey,

Ne  güzelmiş  meğer.', 'Kalmadı  sevdalar,   coşkular. Kalmadı, Eski   bayramlaşmalar. İklimler  bile  değişti  sanki Değişti,  kelebekler  kuşlar. Değişti,    sela...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eski-bayramlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Üzerine', 'olmek-uzerine-halil-aksoy-423re', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümüm  gelir  aklıma.

Küçük  soğuk  bir  odada.

Bildiklerim  bir  yanımda,

Azrail  şah   damarımda.

Renkler  solmaya  başlar,

Kararır  gözlerim

Öne  eğilmiş,

Islak   gözlü  bakışlar.

Bir  el  uzanmış  zem zem  içirir.

Biri  kefeni  ayaklarımdan  giydirir.

Hep  bir  ağızdan  salavat  getirilir.

Merhum  Azrail’e   teslim  edilir.

Ölümüm  gelir  aklıma.

Karlı,  fırtınalı  havada   yürümek  gibi,

Tüylerim  ürperir.

Ne  kaçılır   o  andan,

Ne  sıra  devredilir.

Sıralanmış   meleke  gibi   atlar.

Bilinmeze  doğru  uçulur.

Nefes  verilmiş, kefen  giyilmiş.

Yol  almak  için   takılmış  kanatlar.

Belki  ölmek  için  değildir,

Çektiğimiz  acılar.

Yeni  bir  hayatın  habercisidir,

Çekilen  sancılar,

Ölüm  son  değildir.

Bir  ömür  biter,  bir  ömür  başlar.

Kim  bilir...', 'Ölümüm  gelir  aklıma. Küçük  soğuk  bir  odada. Bildiklerim  bir  yanımda, Azrail  şah   damarımda. Renkler  solmaya  başlar, Kararır  gözl...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olmek-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koğuşum', 'kogusum-huseyin-celik-ysvut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende gizli kaldı bütün sırlarım,

Penceresi güne bakan koğuşum.

On iki ay geçti tüm anılarım,

Sende gizli kalsın canım koğuşum.

Yatağım yerinde durusun her zaman 

Bozulmasın pikem, hep düzgün kalsın

Pencerene konsan minicik kuşlar,

Sakın ha incitme kalsın koğuşum.

Üzme girenleri hep sıcak davran.

Yılmasın içinde kalan insanlar.

Serin ol yazları çarpmasın güneş.

Perdeleri çeksinler güzel koğuşum.

Dolabına tozlar konmasın sakın,

Banyodaki fayans hep temiz kalsın,

Aynaya bakınca şanlı askerim,

Yüzünü görünce gülsün koğuşum.

Yerlerin cilası hep parlak olsun.

Kitaplığın masun  kalmasın sakın,

Akşam olup ışıkların yanınca, 

Hep seninle kalsam canım koğuşum', 'Sende gizli kaldı bütün sırlarım, Penceresi güne bakan koğuşum. On iki ay geçti tüm anılarım, Sende gizli kalsın canım koğuşum. Yatağım yeri...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kogusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık', 'daginik-halil-aksoy-xa9ej', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim  bir  yerde,

Aklım  bir  yerde.

Bedenim  yorgun.

Kalbim  keyfince  atıyor.

Kulaklarım  istediğini  duyuyor.

Saçlarım  dağınık,

Duygularım  darma  dağınık.

Dağınığım  bu  akşam  dağınık.

Bana  sorarsanız,

Serbest  bıraktım   onları  bu  gün.

İzin  verdim  elime,  koluma

İstedikleri  gibi  davransınlar,

Bir  şey  yapamayacaklarını  anlayınca

Kıymetimi  anlasınlar.

Her  bahar  geldiğinde,

Bir  daha  böyle  davranmasınlar.', 'Gözlerim  bir  yerde, Aklım  bir  yerde. Bedenim  yorgun. Kalbim  keyfince  atıyor. Kulaklarım  istediğini  duyuyor. Saçlarım  dağınık, Duyg...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daginik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çavuş Parkı', 'cavus-parki-huseyin-celik-wzb8b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturdum masana konuş benimle,

Sende açar çiçek, gül çavuş parkı.

Ağaçlar meyveye dönse de her yıl,

Senden gıda alır bil çavuş parkı.

Çiçekler ağaçlar ne kadar güzel,

Gölünde minicik balıklar yüzer.

Gönülden gönüle bir sevda sızar,

Sende aşık olup gör çavuş parkı.

Ağacının gölgesinde oturdum.

Çimlere çamlara çok hayran oldum.

Bir müddet seyredip orada kaldım.

Gördüm ki mutlusun sen çavuş parkı.

İçimdeki yollar uzar süzülür.

Bir çiçeğin solsa gönlüm üzülür.

Senin kaleminde sevda yazılır.

Kader değil şaka bil çavuş parkı.

Gece çöküp lambaların yanınca.

Kalbim çarpar sevgilimi anınca.

İncitemem yerde görsem karınca.

Merhametim vardır bil çavuş farkı.

Yazın serin kışın sıcak olursun.

Bu kadar insanı nerden bulursun.

Bir gün gelir Hüseyin’im ölürsün.

Sen ebedi orda kal çavuş parkı.', 'Oturdum masana konuş benimle, Sende açar çiçek, gül çavuş parkı. Ağaçlar meyveye dönse de her yıl, Senden gıda alır bil çavuş parkı. Çiçekle...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cavus-parki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Beline Kazmayı', 'vur-beline-kazmayi-i-brahim-sagir-7srpx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hâyal edip dururum o eski günler nerde? 

Eski halaylar nerde,eski düğünler nerde? 

Bozuk sazın düzeni,akort tutmuyor perde,

Sen çalışıp didindin el topladı parsayı

Dam üstünde saksağan vur beline kazmayı.

Hepyek atanlar şimdi düşeşi beğenmiyor,

Herkes başına buyruk, şu şöyledir denmiyor,

Aleyhine işledi  döndü  dolaştı skor.

Senelerdir kendine bulamadın bir dayı,

Dam üstünde saksağan vur beline kazmayı…

Başkadır siyasetin çarşambası salısı,

Şeffaflık ipi ile dokunuyor halısı,

Orta direğe batar  ipek olsa çalısı.

Sen tayına talim et onların aslan payı,

Dam üstünde saksağan vur beline kazmayı… 

Çamur atan atana yüzünün karasıyla,

Köşe dönen dönene milletin parasıyla,

Her şey karıştı artık ıskartası,hasıyla.

Keyifle içemezsin ne kahveyi,ne çayı,

Dam üstünde saksağan vur beline kazmayı…

Ey Sağır hâyallerin kaldı gelmez bahara,

Yaranamadın gitti ne ağyara ne yâra,

Diploman neye yarar etmiyorsa beş para.

Boşuna öğrenmişsin okumayı,yazmayı,

Dam üstünde saksağan vur beline kazmayı…', 'Hâyal edip dururum o eski günler nerde?  Eski halaylar nerde,eski düğünler nerde?  Bozuk sazın düzeni,akort tutmuyor perde, Sen çalışıp didi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vur-beline-kazmayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Borcu', 'vatan-borcu-huseyin-celik-5849b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anam ayrılalı birkaç gün oldu,

İnşallah bitecek bu vatan borcu.

Gözlerim yollara bakıp durur,

Zaman gelir biter bu vatan borcu.

Köyümün gülleri burnumda tüter,

Anam şu hasretin ölümden beter.

İnan ki gözümde hep yaşlar akar,

İnşallah bitecek bu vatan borcu.

Artık adım Mehmet elimde silah,

Bize yardım etsin en yüce ilah.

Kalbimde aşkı var bir sen bir Allah,

Zaman gelir biter bu vatan borcu.

Binlerce kardeşim var bu kışlada,

Bir gün dağlardayız, bir gün yaylada.

Bir haber var mıdır bana sılada? 

İnşallah bitecek bu vatan borcu.

Yarim ağlamasın söyleyin ona,

Her ezan vaktinde eyleyin dua.

Bir gün kavuşursam anam ben sana,

İnşallah bitecek bu vatan borcu.

Gerekirse ölmek boynumun borcu,

Zaman gelir biter bu vatan borcu.

Çarpışmak değil de hasretin yordu,

İnşallah bitecek bu vatan borcu.

Ben ölmeden düşman vatana girmez.

Çok savaşmak inan beni hiç yormaz.

Açarsa çiçekler ebedi solmaz.

Zaman gelir biter bu vatan borcu.', 'Anam ayrılalı birkaç gün oldu, İnşallah bitecek bu vatan borcu. Gözlerim yollara bakıp durur, Zaman gelir biter bu vatan borcu. Köyümün güll...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vatan-borcu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmedi', 'degismedi-halil-aksoy-1wrxr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuş  uçtu,  kervan  geçti.

Göçmen   kuşlar  memleketlerine  uçtu.

Ağaçlar  çiçek  açtı,,  kelebekler  uçtu.

Karlar  eridi,  havalar  değişti.

Değişmeyen  bir  tek  şey  var,

O da  senin  inadın.

Senin  inadın  hala  değişmedi.', 'Kuş  uçtu,  kervan  geçti. Göçmen   kuşlar  memleketlerine  uçtu. Ağaçlar  çiçek  açtı,,  kelebekler  uçtu. Karlar  eridi,  havalar  değişti...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/degismedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-huseyin-celik-4fgkb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler benim

En dertli saatlerim.

Zaman geçmez gecelerde

Hep seni özlerim.

Şimdi sen ne güzel

Uyuyorsun mışıl mışıl.

Ama ben hiç uyumam 

Aklımdan sen geçersin.

Aşkımızın ateşi var

Uyku girmez gözlerime.

Sensiz hiçbir şey olmuyor

Sevgilim işte.

Aradan kaç yıl geçti

Eskisi gibi taptaze aşkım.

Seni hiç unutamadım

Belki sen unutmuşsundur

O eski günlerimizi.

Yeniden kavuşalım

Paylaşalım sevgimizi.

Söyleyelim şu dünyaya

Ayırmasın ikimizi.

Yaşayalım anıların

Hepsini birer,birer.

Hep bizimle beraber ol

Felek ile yüce kader.', 'Geceler benim En dertli saatlerim. Zaman geçmez gecelerde Hep seni özlerim. Şimdi sen ne güzel Uyuyorsun mışıl mışıl. Ama ben hiç uyumam  Ak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/geceler-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkar', 'efkar-huseyin-celik-s0hub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu artık

Hayalimde anılarım.

Bilmiyorum gönül sarhoş

İçiyorum,içiyorum.

Hiç çıkmıyor mazi 

Benim aklımdan.

Hani seviştiğimiz günler var ya

Sanki masal geliyor bana.

Uzaktan görsem seni

Yüzünde gülücükler.

Benimde sana attığım 

O öpücükler.

Kim bilir o zaman

Ne his vardı içimizde.

Serseri gibi aşıktık

İkimizde.

Aklıma ne zaman gelsen 

Hüzünlenip dertlenirim.

Bağrımda bir ateş,

Gözlerim bulut misali,

Yüzüm solmuş.

Artık seni çok özledim,

Ama ne fayda,

Ne gelir elden.', 'Yine akşam oldu artık Hayalimde anılarım. Bilmiyorum gönül sarhoş İçiyorum,içiyorum. Hiç çıkmıyor mazi  Benim aklımdan. Hani seviştiğimiz gü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/efkar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Kadın', 'zor-kadin-halil-aksoy-sp1kn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zor  kadınsın.

Aynı  zamanda  güzelsin de.

Anlasana,

Sen  hem  zor,  hem  güzelsin.', 'Zor  kadınsın. Aynı  zamanda  güzelsin de. Anlasana, Sen  hem  zor,  hem  güzelsin....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zor-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Yarim Bekle', 'bekle-yarim-bekle-huseyin-celik-pex0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Telefon etmeye sıra beklerim

Dertlerim azalsa dertler eklerim

İnşallah boş çıkmaz bu emeklerim

Bekle yarim bekle dönerim bir gün.

Torosların  bulutları yağdırır

Yarim o hasretin başım ağrıtır

Turnam memleketten haber getirir

Bekle yarim bekle dönerim bir gün.

Yarim yıllarıma bakar mı her gün? 

Dün mazide kalır bugünse bugün

Geçen her saniye bu vatan için

Bekle yarim bekle dönerim bir gün.

Hüseyin’ im dünya bambaşka bana

Bir kurşun saplanır inan bağrıma

Ağlama sen canım gelirim sana

Bekle yarim bekle dönerim bir gün.', 'Telefon etmeye sıra beklerim Dertlerim azalsa dertler eklerim İnşallah boş çıkmaz bu emeklerim Bekle yarim bekle dönerim bir gün. Torosların...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekle-yarim-bekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Ne Dedi', 'bilmem-ne-dedi-huseyin-celik-9vskb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaralı gönlümden haber kuşuna

Bir haber sal dedim bilmem ne dedi? 

Ayrılık haberi kalbimi yakar

Haberim alınca bilmem ne dedi? 

Bülbül oldum güllerimi ararım,

Esen yelden kokusunu duyarım,

Uçan kuştan haberimi salarım,

Duyunca düşünüp bilmem ne dedi? 

Hava soğuk üşüyorum çulum yok

Ne bir hırka içecek bir suyum yok

Aşkın yaktı cehenneme gerek yok', 'Yaralı gönlümden haber kuşuna Bir haber sal dedim bilmem ne dedi?  Ayrılık haberi kalbimi yakar Haberim alınca bilmem ne dedi?  Bülbül oldum...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilmem-ne-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Senfonisi', 'veda-senfonisi-reyhan-sur-vk0m5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çekilir güneş 

gök savsaklar 

zamansız yağar yağmur 

gürültüyle ıslanır çatılar 

sesler savrulur 

geçerken sis tünellerinden 

apansız düşer diz üstü 

gölge olur çalılıklara akşam 

** 

unutturur rengini güllerin 

demlenmemiş gülüşler 

düşler kırılır 

içtiğimiz nar suyu kızılca şerbet 

bereket 

sızar dudaklarımızdan 

aya sıçrar rengi 

yudumlar akşam güneşi 

kırk aynadan geçer 

çelişkili bakışlarımız 

toplayıp saydamlığı 

derinliği 

geçirgenliği 

boyunduruğuna sunarız kırmızılarda 

acemi fırça darbelerinin koro sesini 

gül kokuludur akşam 

** 

güleç yüzlü böcekler geçer 

ısırgan otları arasından 

uçurum diplerinde 

zoraki kahkahalar 

barok öksürüklerde yiter 

antik anılara 

fa diyez minör 

çoğalttığımız dikteler 

gözlerdeki mumlar söner içtenliğe 

kırık hıçkırıklar kalır Veda Senfonisi’nde 

hüzündür akşam', 'çekilir güneş  gök savsaklar  zamansız yağar yağmur  gürültüyle ıslanır çatılar  sesler savrulur  geçerken sis tünellerinden  apansız düşer ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/veda-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Yılları', 'okul-yillari-huseyin-celik-ketry', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş yine ufukta 

Gökyüzü masmavi

Ne kadarda sıcak hava

Elimde çantam yine 

Okul yolunda…

Ben yine pembe hayaller peşinde

Okul aşkı hiçbir şeye benzemez derler ya

Oysa ben benzetiyorum

Alırdım bir ayakkabıyı 

Ne kadar hoş olurdu 

Zaman geçip yıprandıkça 

Güzelliği kaybolurdu

Sonunda bir çöplükte olurdu..

O güzel ayakkabım

İşte okul aşkı böyledir 

Ey benim papatyam

Bizim aşkımız sonsuza dek

Devam edip süre gelsin! 

Bir fidan dikelim toprağa

Yeşerip meyve versin 

Yok olmasın aşkım

Sen gül ben bülbül olayım

Sen güneş ol ben ışığı

Ayırmasınlar iki aşığı', 'Güneş yine ufukta  Gökyüzü masmavi Ne kadarda sıcak hava Elimde çantam yine  Okul yolunda… Ben yine pembe hayaller peşinde Okul aşkı hiçbir ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/okul-yillari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit Yoksa', 'umit-yoksa-halil-aksoy-zha8r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deste  deste  güller  versem  ne  olur.

İçinde  aşk  yoksa.

Yollarına  halı  sersem  ne  olur.

Gönül  dağında  köşküm  yoksa.

İnan  inan  sevgilim.

Halıcı  ile  çiçekçi  parasını  alır,

Zengin  olur.

Yine  olanlar  seninle  bana  olur.

Bu  aşktan  ümit  yoksa.', 'Deste  deste  güller  versem  ne  olur. İçinde  aşk  yoksa. Yollarına  halı  sersem  ne  olur. Gönül  dağında  köşküm  yoksa. İnan  inan  se...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umit-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-huseyin-celik-pold9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Atamızdan yadigar şu toprakları

Gel beraber işleyelim güzelim.

Türlü,türlü kuşlar gibi ikimiz

Gel beraber işleyelim güzelim.

Pınarlar bırakmış içsinler diye

Yaylaları vardır gezsinler diye

Saraylar yaptırmış görsünler diye

Beraber gezelim canım sevgilim.

Aşıkları destana konu olurmuş

Çölde susuz kalan serap görürmüş

Kış günleri onlar yaya yürürmüş

Beraber koşalım canım sevgilim.', 'Atamızdan yadigar şu toprakları Gel beraber işleyelim güzelim. Türlü,türlü kuşlar gibi ikimiz Gel beraber işleyelim güzelim. Pınarlar bırakm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anadolum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyor De', 'diyor-de-huseyin-celik-lc4rk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turnam sevdiğimi görürsen eğer

Vefasız olmasın sevsin diyor de.

Elini bağrına koyup düşünsün

Şu vuran kalbime girsin diyor de.

Hayatımda mutlu olamadım ben

Sevdim ben her zaman sevilmedim ben

Kadere boynumu büktüm durmadan

Yoruldum koşmaktan gelsin diyor de.

Ne acılar çektim  aşık olunca

Gözlerim yaş doldu hatırlayınca

Biraz rahatlarım ben ağlayınca

Bir nehir misali coştu diyor de.

Bir özlem yuvası oldu şu kalbim

Sensin benim tatlı, şirin sahibim

Bardağı taşıran son bir damlayım

Taşmadan şu sabrım gelsin diyor de.

Düşüne,düşüne derbeder oldum

Sonunda sevgiyi Mevla da buldum

Dünyada çok yoksul garip bir kuldum

Artık çok rahatım bilsin diyor de.', 'Turnam sevdiğimi görürsen eğer Vefasız olmasın sevsin diyor de. Elini bağrına koyup düşünsün Şu vuran kalbime girsin diyor de. Hayatımda mut...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyor-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....Çöl (CaNDostuma) ....', 'col-candostuma-i-lker-unlu-kb6kb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yer toptan çöle dönse,

Âlem su diye birbirini yese,

Kahpeler dostlarını suya satsa,

Son damla suyunu bana vermek için; 

Benle kavga edersin....

Bilirim...

Yine de susuzluktan ölecek olsak ta ikimiz,

Yüreğimiz yüreğimize mıhlanmışken

Verilir son nefesimiz...

14 Şubat 2006

İzmir', 'Her yer toptan çöle dönse, Âlem su diye birbirini yese, Kahpeler dostlarını suya satsa, Son damla suyunu bana vermek için;  Benle kavga eder...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/col-candostuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mısralar', 'misralar-halil-aksoy-8g20a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazmayacağım  dedim,  yazamıyorum.

Dayanamadım  gene  yazıyorum.

Ne  var  bilmem  şu  mısralarda,

kendimi onlarla  yaşıyor  sanıyorum.

Sanki  bana     güç  veriyorlar,

Sanki  bana  el  veriyorlar,   bel  veriyorlar.

Onları  çok  seviyorum.

Ben  nasıl  dizil  dersem,

Hepsi   öyle  diziliyorlar.

Gülmeme   ağlamama  eşlik  ediyorlar.

Onlar  beni  benden  iyi  biliyorlar.

Beni  benden  iyi  bilen  mısralar.

Söyleyin  bana,

En  güzelleriniz  ne  zaman  gelecek.

Sizler  gibi  onlarda  ne  zaman  dizilecek.

Dizildikçe   bana  hayat  verecek.', 'Yazmayacağım  dedim,  yazamıyorum. Dayanamadım  gene  yazıyorum. Ne  var  bilmem  şu  mısralarda, kendimi onlarla  yaşıyor  sanıyorum. Sanki...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/misralar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit Babam', 'sehit-babam-huseyin-celik-be40o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir şehit oğluyum,babam savaşta ölmüş.

Çarpışmış sonuna dek,orada şehit düşmüş.

Bu imanlı yolların,ne şerefli kulların,

Sonunda bu vatanın kurtarıcısı olmuş.

Kahpece düşmanların haince tuzakların,

Bütün bu olanların önüne geçen olmuş.

Bağrını siper yapan daima hakka tapan,

Vatan yolunda koşan tek yürek insan olmuş.

Atam ile başbaşa saldırmış düşmanlara,

Şu büyük taarruzda övülen insan olmuş.

Sakarya’nın önünde derin sular içinde,

O gencecik yaşında şehit düşen o olmuş.

Benim babam göklerin o güçlü bileklerin,

Kurtuluş zaferinin öncülerinden olmuş.

Tarihin en içinden vatanı en derinden,

Vurularak kalbinden şehit düşen o olmuş.', 'Ben bir şehit oğluyum,babam savaşta ölmüş. Çarpışmış sonuna dek,orada şehit düşmüş. Bu imanlı yolların,ne şerefli kulların, Sonunda bu vatan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sehit-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekmeye Geldim', 'cekmeye-geldim-huseyin-celik-frvvx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül bu ne deyim çaresi var mı? 

Aşkın acısını çekmeye geldim.

Aşk ile tutuşan bağır bendedir,

Sineme taktımda çekmeye geldim.

Sevmezsen bağlarda çiçek mi açar? 

Aşık olan bülbül havada uçar

Sevgilimi görmezsem yüreğim yanar

Ateşte kavrulup yanmaya geldim.

Serin olur sensiz bütün odalar

Ölmeden mezara beni koydular

Çok acı çektin mi? diye sordular

Çekmedim burada yanmaya geldim.

Güzel olur geceleri sevişmek

Aşkın çilesidir bazen dövüşmek

Sevgilim elinden bir kuru ekmek

Verirsen birazcık yemeye geldim.

Kalbim yanıyor hep için için

Tel tel okşasaydım  simsiyah saçın

Seni sevdiğimi söylemek için

Koşarak yanına demeye geldim.', 'Gönül bu ne deyim çaresi var mı?  Aşkın acısını çekmeye geldim. Aşk ile tutuşan bağır bendedir, Sineme taktımda çekmeye geldim. Sevmezsen ba...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cekmeye-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Söyleyince', 'ask-soyleyince-huseyin-celik-ndwe4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu bakışın beni yaktı

Yanan gönüller kahrolur.

Bir canana gönül verdim

Seven gönüller kahrolur.

Yaktı beni canan yaktı

Biraz güldü biraz baktı

Benim derdim zaten çoktu

Gülen gönüller kahrolur.

Sevda,sevda diye gezdim

Biraz şiir gazel yazdım

Sevdiğime türkü yaktım

Yanan gönüller kahrolur.

Elim ayağım karıştı

Biraz benime konuştu

Gönül kuşum hemen uçtu

Uçan gönüller kahrolur.

Hüseyin im zar eyledim

Dostlarımı terk eyledim

Güllere şarkı söyledim

Öten bülbüller kahrolur.', 'Şu bakışın beni yaktı Yanan gönüller kahrolur. Bir canana gönül verdim Seven gönüller kahrolur. Yaktı beni canan yaktı Biraz güldü biraz bak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-soyleyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kadınlar', 'guzel-kadinlar-halil-aksoy-h21w4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldanma  öyle  bakışlarına,

Güzel  kadınların.

Bakışı  hoştur,  kokusu  hoştur.

Aldanırsan,   peşlerinden,

Koştur  oğlum  koştur.', 'Aldanma  öyle  bakışlarına, Güzel  kadınların. Bakışı  hoştur,  kokusu  hoştur. Aldanırsan,   peşlerinden, Koştur  oğlum  koştur....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzel-kadinlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman Asker', 'kahraman-asker-huseyin-celik-jwvwc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En derin imanın en derin gücün

Sahibi kudreti kahraman asker.

Baş kaldırsa düşman bu topraklara

Çarpışır onunla kahraman asker.

Serden geçmez canından vazgeçer o

Namusu göklerde ay yıldızdır o

Kanı akar canı çıkar ölmez o

Ebedi gönülde kahraman asker.

Bir kişisi bin düşmana bedeldir

Coskun,coşkun akan bulanık seldir

Onun için vatan en güzel yardir

Sevgisi gönülde kahraman asker.

Sıladan bir haber alırsa eğer

Onun için en güzel duyguymuş meğer

Ondaki yücelik göklere değer

Arşa çıkar güçlü kahraman asker.

Sadık yari kara toprak olsa da

Dört bir yanı hainlerle dolsa da

Hazan vurup çiçekleri solsa da

Cennet bahçesinde kahraman asker.', 'En derin imanın en derin gücün Sahibi kudreti kahraman asker. Baş kaldırsa düşman bu topraklara Çarpışır onunla kahraman asker. Serden geçme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahraman-asker-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmurları', 'nisan-yagmurlari-halil-aksoy-xlf09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinsin  artık  şu  yağmurlar.

Güneşli   havaları  özledim.

Şu  anda  tişörtümü  giyip,

Gönlümce  dolaşmayı,

İnan  çok  isterdim.', 'Dinsin  artık  şu  yağmurlar. Güneşli   havaları  özledim. Şu  anda  tişörtümü  giyip, Gönlümce  dolaşmayı, İnan  çok  isterdim....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nisan-yagmurlari-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Kuş Olup Yanımda Uçacaksın**', 'kus-olup-yanimda-ucacaksin-i-lker-unlu-xkd2l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömür kavrulsam da acıdan dertten,

Her hücrem erise kandan terden,

Issız bir çölde bir başıma kalsam,

Yağmurda dermen olup düşer misin tenime? 

Kimsesiz kalsam en ücra köşede,

Tek bir ses olmayan en kara gecede,

Haykırsam adını bir serin yele,

Duyupta sesimi tanır mısın beni? 

En kuru iftiralar atılsa üstüme,

Layık görülse bedenim müebbet hapse,

Ruhum duvarları aşıp bakınca göğe,

Bir melek olupta güç verir misin bana? 

En zor anımda yanımda olacaksın,

Her başarıma işte sen ortaksın,

Böyle asilce düşünürken sen hep,

Bir kuş olupta yanımda uçacaksın...

İlker ÜNLÜ', 'Bir ömür kavrulsam da acıdan dertten, Her hücrem erise kandan terden, Issız bir çölde bir başıma kalsam, Yağmurda dermen olup düşer misin te...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kus-olup-yanimda-ucacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manzara 1', 'manzara-1-i-brahim-sagir-qgwgm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklı boğdu izimler,kafalar bomboş kovan,

Fikir arenasında matador dessas  şeytan.

Tepkisiz,hareketsiz,suskun bir dev cemiyet,

Azınlığın hükmüne tabi olmuş  kemiyet.

Vicdanlar çılgın mı ne eğrilerin peşinde,

Keramet aranıyor Biznslı’nıın  leşinde.

Milletine küçümser bir nazar ile bakan,

İslâmî  inancıma inatla karşı çıkan,

Geçmişini hor gören aydınlar bize kaygı,

Bildikleri sadece maymun dedeye saygı. 

Bin çeşit maske ile dolanırlar meydanda,

Sahte fikirlerine Darvin izim payanda.

Müslümanlar mürteci,ırkını seven faşist,

Zehir kusuyor hâla köksüz,ruhsuz komünist.

Ötede feministler nikaha hayır diyor,

Temiz nesep dururken illede  piç istiyor.  

Bir yanda irticayı üstümüze kışkırtan,

Durmadan dindarlara yobazlık yakıştıran,

Bir allâme  Kuran’da tesettür yoktur demiş.

Cüretin bu kadarı bir çağda  görülmemiş.

Gazete fikir değil üryan resim satıyor,

Utanmadan kızımın örtüsüne çatıyor.

Çağdaşlık moda terim köksüzün sığındığı,

Ellerinde hazine lâisizmin sandığı.

Televizyon bir afet karnaval borazanı,

Aile düzenini sarsan çıfıt  kazanı.

Filimler açık saçık,ahlâkın zerresi yok,

Fazilete atılır her yandan binlerce ok.

Aklı boğdu izimler kafalar bomboş kovan,

Fikir arenasında matador dessas şeytan… 

  

,                                               1991', 'Aklı boğdu izimler,kafalar bomboş kovan, Fikir arenasında matador dessas  şeytan. Tepkisiz,hareketsiz,suskun bir dev cemiyet, Azınlığın hükm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/manzara-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöpçü', 'copcu-halil-aksoy-1lybd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne  kadar   maharetli  alıyordu,

Çöpleri  çöp  kutusuna.

Acelesi  vardı  sanki,

Atılan  çöpü  yere  düşmeden,

Kapmanın  telaşı  içindeydi.

Yerde  çöp  görmeye

Tahammül  edemiyordu.

İnsanlara  şaşırıyordu.

Kendine  çoğu  zaman,

Neden? 

Diye  soruyordu.

Neden  kirletir  insanlar  etrafı? 

Daha  az  önce  temizlemişti  buraları.

Bir  yandan  da  ekmek  parası,

Diye  söyleniyordu.

İnsanlar  çöpleri  attıkça

İşim  garanti  diyordu.

Çöple  ekmeğin  hiç  bir  alakası  yoktu  ama,

O  ekmeğini   çöpten  yiyordu.', 'Ne  kadar   maharetli  alıyordu, Çöpleri  çöp  kutusuna. Acelesi  vardı  sanki, Atılan  çöpü  yere  düşmeden, Kapmanın  telaşı  içindeydi. Y...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/copcu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manzara 2', 'manzara-2-i-brahim-sagir-wbjw9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençliğim saman çöpü sefahatin selinde,

Feministlik bir kalkan fahişenin elinde.

Diskotek,taverna,bar namuslara  tuzaktır,

Ahlaksızın kafası din imandan  uzaktır.

İnsanî değerde ne,eski düzen eseri,

Kalmayalım bu yolda Avrupalıdan geri.

Tepişelim bayanlar,medeniyet aşkına,

Tepinelim ağalar dünya dönsün şaşkına.

Medeniyet dediğin gününü gün etmektir,

İçkiyi yudumlayıp bulutlara  gitmektir.

Hayatını yaşamak bir bohem felsefesi,

En güzel musikidir vahşi tamtamın sesi.

Millî,dinî değerler geçmiyor bu alanda,

Haya,namus talanda,haysiyetler talanda,

Kadın düştü ayağa eşitlik istedikçe,

Çıplaklık şaha kalktı örtü nedir dedikçe.

İnsaflar pas bağlamış,vicdanlar ziftten kara, 

Ecdadını beğenmez maymun nesli maskara.

Sardı kara bulutlar insanlık semasını,

Kâr sayıyor Müslüman paranın nemasını.

Evlat babaya asi,baba evlada esir,

Silinmiş yüzlerdeki o nurlu rabbiyesir.

Niçin uyanmaz insan niçin Allahım niçin? 

Değer mi bu çılgınlık bir sefil hayat için.

Gençliğim saman çöpü sefahatin selinde,

Feministlik bir kalkan fahişenin elinde… 



                                                        1991', 'Gençliğim saman çöpü sefahatin selinde, Feministlik bir kalkan fahişenin elinde. Diskotek,taverna,bar namuslara  tuzaktır, Ahlaksızın kafası...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/manzara-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hâl Fena', 'bu-h-l-fena-i-brahim-sagir-zjrza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Komünist,feminist bin türlü belâ,

Öz köküme zehir döktü durmadan.

Kül türüm edildi bir bir istilâ,

Gerçeğin üstünü sardı toz duman.

Vatan,din diyenler sayıldı suçlu,

Özüme bağlılık ihanet sanki.

Hilâle üstünlük taslarken haçlı,

Bir başka hesabın peşinde yanki.

	

Türk yurdunda Türklük yargılanıyor,

İslâm’ca yaşamak,giyinmek yasak.

Can evime bıçak girmiş  kanıyor,

Dinsiz,donsuz serbest,türbanlı tutsak…

Heyecanlar sahte,hevesler sahte,

Rezalet meydanda,fazilet kayıp,

Ahlaksızlık vardı artık son radde,

Sokaklarda ayıp üstüne ayıp.', 'Komünist,feminist bin türlü belâ, Öz köküme zehir döktü durmadan. Kül türüm edildi bir bir istilâ, Gerçeğin üstünü sardı toz duman. Vatan,di...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sağır']::text[], 8.5, '{"poet":"İbrahim Sağır","poet_slug":"i-brahim-sagir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-hal-fena-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle', 'gule-gule-esin-cinar-ofbno', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güle güle 

Hatırlamak kavramını artık yok ettin

Hatırlayamayacaksın son konuştuklarımızı

Lokalin bir köşesinde,sandalye üzerinde

Gelecektin Eylül ortalarında rüzgarlı yağmurlu bir günde 

Balığa çıkacaktık; rüzgar kalan saçlarımızı savururken

O gün olduğu gibi

İliğimize kadar ıslanacaktık yağan yağmurla

Söğecektik birbirimize belki deniz tutacak belki de kusacaktık

Ama geçmişi yeniden yaşayacaktık

Konuşurken anmıştık taşıdıklarımızı

Aslında onlarla kalan hatıralarımızı

Güçlüydük kuvvetliydik hayatı taşımıştık

Ve de taşıyacaktık hamal yaratılmıştık

Hiç yorulmamıştım bunca yükün altında

Ama bugün yoruldum

Çünkü bir yanlış yaptın

Hiç beklemiyorken 

Sen kendini taşıttın

Mecburdum omuz verdim

Seni saran tahtaya

Ama inan ortağım

Ettiğim her duaya

Olmadı Arap

Olmadı İrfan

Olmadı Arap İrfan

Bugün çok yanlış yaptın

Sen tahtanın altında

Ben üstten toprak attım

Hem bedenimi yordun

Hem kalbimi yıprattın

Güle güle Arap İrfan

Güle güle

Vücudunu kabire koyduk ama

Ruhunu kabul etsinler Cennet''e 

Esin Çınar

(21.08.2005/10.03.2006)', 'Güle güle  Hatırlamak kavramını artık yok ettin Hatırlayamayacaksın son konuştuklarımızı Lokalin bir köşesinde,sandalye üzerinde Gelecektin ...', ARRAY['Türk Edebiyatı','Şiir','Esin Çınar']::text[], 8.5, '{"poet":"Esin Çınar","poet_slug":"esin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gule-gule-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...''Kim O'' Demeden Baksana Kapıya....', 'kim-o-demeden-baksana-kapiya-i-lker-unlu-7sruh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi saat geceyi aşk geçiyor

Kalbimde sana düğümlenmiş tüm duygular,

Bir çığ oldu giderek büyüyor...

Ellerinin beyazlığı geliyor aklıma,

Üşümesin diyorum o küçük eller...

Ve gözlerin; 

Güneşin doğuşunu kıskandıran...

Tüm aydınlıklar kapkara olsa,

Dertler ardarda sıralansa,

Varlığın yetermiş dünyamı ışıldatmaya...

Aşkın her rengi kapıda,

Kapı çalıyor...

''Kim O'' demeden,

Baksana kapıya....', 'Şimdi saat geceyi aşk geçiyor Kalbimde sana düğümlenmiş tüm duygular, Bir çığ oldu giderek büyüyor... Ellerinin beyazlığı geliyor aklıma, Üş...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kim-o-demeden-baksana-kapiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bír nura bandım', 'b-r-nura-bandim-mikdat-bal-q30ie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neydi o çilveler neydi o endam

Aklımı başımdan aldı güzelim

Sanadır bu çağrım sanadır nidam

Hayalin gözüme geldi güzelim

Geceyi ışıtır güzel gözlerin

Bundan böyle bana yoldur izlerin

Ruhumu okşayan yazın, güzlerin

Her şeyin aklımda kaldı güzelim

Üzüm karasıdır sırma saçların

Cennetten mi gelir senin göçlerin

Zülfikardan keskin kirpik uçların

Dudağın şifalı bal’dı güzelim

Gördüğümde sanki bir nura bandım

O gündür bu gündür aşkınla yandım

Kendimi bir anlık cennette sandım

O cemal kalbimi çaldı güzelim

Mikdatî der sevgin ile sarındım

Kederlerden bir bir çıkıp arındım

Bahtıma ne küstüm ne de yerindim

Varlığın sisleri sildi güzelim', 'Neydi o çilveler neydi o endam Aklımı başımdan aldı güzelim Sanadır bu çağrım sanadır nidam Hayalin gözüme geldi güzelim Geceyi ışıtır güzel...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-nura-bandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürken de Özlemek', 'olurken-de-ozlemek-i-lker-unlu-a6xcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmiyor günler..

Hazin bir son sanki omuzumda,

Ertelenmiş vedaları özler mi insan? 

Ben özlüyorum...

Bir kurdun ağlaması gibisin biliyorum,

Seninle bir başlangıç olamaz görüyorum,

Ama ben sensizliği sensiz yaşamayı da

Özlüyorum....

Sensizliğimi bile yalnız bırakmazken sen birtürlü,

Ben sarı sayfalarda kaybolup,

Hatıralarda yeni bir güne uyanıyorum...

Uyanıpta görüyorum ki,

Ben aslında ölüyorum...

Ve ben öldükçe seni tüm yanlışlarınla,

Bir daha kimsece böyle özlenmemek üzere,

Kalbime gömüyorum...

Özledikçe yaşıyor,

Yaşadıkça özlüyor,

Özledikçe tekrar ölüyorum...

Ve işin garibi nedir bilir misin? 

Ben seni ölürken de özlüyorum...', 'Geçmiyor günler.. Hazin bir son sanki omuzumda, Ertelenmiş vedaları özler mi insan?  Ben özlüyorum... Bir kurdun ağlaması gibisin biliyorum,...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olurken-de-ozlemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derleme', 'derleme-ali-cengiz-turan-37h2d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya üç gündür,

Dün,bugün,yarın...

Ümit üç gündür,

Dündü,bugündü,yarındı,

Hayal üç gündür,

Dünler,bugünler,yarınlar..

Ömür bir gündür...

Dün yoktu

Bugün var

Yarın olmayacak...', 'Dünya üç gündür, Dün,bugün,yarın... Ümit üç gündür, Dündü,bugündü,yarındı, Hayal üç gündür, Dünler,bugünler,yarınlar.. Ömür bir gündür... Dü...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/derleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Aslında', 'yok-aslinda-atila-gunal-gglvg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derin gözlerin değil

Altın sarısı saçların da değil

Özlediğim

Hele ışıl ışıl tenin

İçime akıp giden gülümsemen de değil

Sen...

Yalnızca sensin Özlediğim

Hiçbirşeyinsiz,herşeyinle sen...', 'Derin gözlerin değil Altın sarısı saçların da değil Özlediğim Hele ışıl ışıl tenin İçime akıp giden gülümsemen de değil Sen... Yalnızca sens...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yok-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Şiiri', 'mutlulugun-siiri-baris-aluk-u5k95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...................................Ben imkansiza dudak bükerdim

...................................Sense halime gülerdin...

..........................................................Esra Güzelipek

Mutluluğun şiirini yaz dersin

siyah kalemimdeki mürekkep

Attığım her çizik ak kağıda

kara...

Adım mavi,

umuda çizilmiş gökler gibi.

Neylersin,

geçtiğim yollar kara...

Elbet düşecek üzerime bir gün

gölgesi beyazın

yazacağım şiirini mutluluğun.

Sarılıp beyaz kefene

düşmeden kara toprağa...

(10.03.2006)  Beyoğlu', '...................................Ben imkansiza dudak bükerdim ...................................Sense halime gülerdin... ...................', ARRAY['Türk Edebiyatı','Şiir','Barış Aluk']::text[], 8.5, '{"poet":"Barış Aluk","poet_slug":"baris-aluk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mutlulugun-siiri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik Kızımdan -BABACIĞIM', 'biricik-kizimdan-babacigim-hulya-arikan-4hibt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gül verdin babacığım

Koklamaya doyamadım

Solmasın rengi diye

Sevmelere kıyamadım

Sesini aldım sanki

Niye konuşmadın anlamadım

Bir tanecik babacığım

Kalbimdeki sevgiyi bir türlü anlatamadım

Büyülü gözlerinle

Heyecanlandırdın beni

Onca yıl baktın 

Kucağında taşıdın beni

Gece gündüz tüm çaban

bilirim ki bizim için

Bu emeğin karşısında 

Çok teşekkür ederim sana

Sena Didem ARIKAN', 'Bir gül verdin babacığım Koklamaya doyamadım Solmasın rengi diye Sevmelere kıyamadım Sesini aldım sanki Niye konuşmadın anlamadım Bir taneci...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arıkan']::text[], 8.5, '{"poet":"Hülya Arıkan","poet_slug":"hulya-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biricik-kizimdan-babacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-selami-aydemir-83uad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN YOKTUN

Beni benden başka kimse duymadı

Yağmur ve akşam tanıktı

Bağırmıştım ardından

Bağırdığımı duymadın

Tüm düşlerimin ardından koşarken 

Soluksuz kalmıştım yollarında

Vurulup düştüğüm geceleri

Ter içinde bir sızıyla

Yaralarımı taşıdım sana 

Yalnızdım

Yağmur ve akşam tanıktı

Yalnızlığıma

Düşündüm 

Kaç adam düşer

Benim gibi 

Böyle yollara

Kaç adam söyle

Kalbini avuçlayarak susma

Kaç adam

Seni benim sevdiğim kadar sevebilir

Beni benden başka kimse duymadı

Yağmur ve akşam tanıktı

Bir de suskun gözlerin

Bir yaz günü açılsaydı kapıların

Yağmur yağmazdı  böyle ipince

Ve ıslanmasaydı  ayrılıklara yüreğin

Islığımla okşayacaktım tenini

Sevdalara boğacaktım suretini

Ellerini tutup 

Birlikte yıldızlara karışmış

                düşler yaşayacaktık

Güneş saçlarında durur

Bende yüreğin olurdum.

O AN KİM BİLİR ELLERİN NASIL DURURDU? 

Sen yoktun 

Ben kederimin ellerinden tuttum

Beni benden başkası duymadı 

Yıldızlar ve gökyüzü

          yok artık düşlerinde

Beni sana bağlayan neydi? 

Bir çelişkiydi belki

Belki de bir korkuydu bilmediğim

Yirmi beş yaşın ardımda bıraktığı

Bir  DÜŞ-ANI belki! ..

Sen yoktun

Daldım karabasan geceye

Bir el feneri gibi

Antalya da şafak atmakta 

Yağmurda çiseliyor  ipince

Sen yoktun

Kültür parkında bir barakada oturmuşum

İçmişim çakır keyfim

Ve suskunum

Bu kadar susmak benimde hakım

Dalgalar bozuyor suskunluğumu

Bende senin kadar suçluyum kim bilir? 

Ondandır suskunluğum

Kalbim dururdu

Nabzım olsa duyardım

Gecenin efkarına içmezdim bu kadar

Marinadayım

Ne yağmurda kokun

Ne rüzgarda çığlığın

Sen yoksun

KİM BİLİR ŞİMDİ HANGİ GÜNEŞ 

                            SİSTEMİNDESİN? 

Kimselere sormadım seni

Yürüdüm 

Birlikte yürüdüğümüz sokaklarda

Yoruldum

Birlikte bira içtiğimiz cafelerde  soluklandım

Seni anlatan müzikler dinledim

İstanbul’a kar yağıyordu

Antalya garı çok sıcak

Ve geceye çok uzak

Ben kendimin ellerinden  tuttum

Sana geliyorum

Arka cebimde terlemiş  biletimle

Seni gırtlağına ihanet düşürmeyen 

Çığlıklara sormalı

Harem garında bir yolculukta 

Sana sormalı

Dedim:

‘Anımsamalısın

daha gün gibi gözlerin aklımda 

yazdığın şiirler 

kale kapısı, Konyaaltı  plajları

taş sektirdiğimiz deniz

yürüdüğümüz yolları

matematik kokan öğrenci evlerini 

işkence kokan evlilik kurumlarının 

önünden geçerken

içindeki korkuların

yersiz bakışlarını anımsamalısın

vurulup düştüğüm geceleri

düşlerimden sıyrılıp geldiğim geceleri

anımsamalısın’

kalbim dururdu 

nabzım olsa duyardım 

beni benden başka kimse duymadı

ben kendimin ellerinden tutup

yürüdüm geldiğim yollardan

ayrılığa çıktık

ayrılığa çıktık

ve yalnızlık ‘an’lar kadar

damdan sarkan buzlar kadar

keskin uçlu

bir kılıçtan ibaretti

bıçakladım kalbimi

kollarım benim değildi

yağmur yağmazdı eskiden  böyle

belki yağmurda sen

sen yoksun….

 BEN SADECE BİR NEHİRİ SEVMİŞTİM

ÇÜNKÜ YAKAMOZLAR ÇELMİŞTİ AKINTIMI….', 'SEN YOKTUN Beni benden başka kimse duymadı Yağmur ve akşam tanıktı Bağırmıştım ardından Bağırdığımı duymadın Tüm düşlerimin ardından koşarke...', ARRAY['Türk Edebiyatı','Şiir','Selami Aydemir']::text[], 8.5, '{"poet":"Selami Aydemir","poet_slug":"selami-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/sen-yoktun-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beliydi Zaten', 'beliydi-zaten-adem-tetik-kqdwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sende benim kadar seveseydin eğer 

Yolar yıllar ayıra bilirmiydi bizi 

Korkum olmazdı benim ölümden yana 

Yeterki gerçekçi sevseydin beni

Yoluna canımı adayacaktım 

Baharla bir olup sende yaşayacaktım

Yazık  ki canım çok geç anladım 

Senden bana yar olacak  sandım 

Daha başından biliyordum zaten 

Gözlerin  etrafa ürkek bakarken

Nereye kaçsam diye bir bahane ararken

Gideceğin en başın beliydi zaten', 'Sende benim kadar seveseydin eğer  Yolar yıllar ayıra bilirmiydi bizi  Korkum olmazdı benim ölümden yana  Yeterki gerçekçi sevseydin beni Yo...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beliydi-zaten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım Kendimi', 'anlayamadim-kendimi-mihrican-karaca-zsx24', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsmini duymuştum eskiden

Laf aralarında.

Yıllar sonra bir yerde tesadüfen karşılaştık.

Sonra ayrılınca oradan,

Düştün aklıma.

Yüzüne bile tam bakamadım o anda,

Ama gözlerini özledim.

Sımsıkı sarılmadan daha

Kokunu hissettim.

Sonra düşündüm,kendime sorular sordum,

Çıt yok tabi benden

Ne oluyordu bana.

Sanki bir selli yağmura karışmış sürükleniyordum.

ne oluyordu bana ki 

Gururum bile yok oluverdi.

Biranda kendime gelmeyi bile beceremiyordum

keşkeler dökülüyordu dudaklarımdan.

daha felakete daha çıkmaza girer gibiydim sanki...', 'İsmini duymuştum eskiden Laf aralarında. Yıllar sonra bir yerde tesadüfen karşılaştık. Sonra ayrılınca oradan, Düştün aklıma. Yüzüne bile ta...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlayamadim-kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül İle Nar', 'gul-i-le-nar-mehmet-akif-gulhan-qsp6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül nargilenin nar’ı

Papatya yaprağı diye kopardığım

Seviyor sevmiyor

Son yaprağa elim varmıyor

Şair,meczubun diğer adı

Yazıyor,yazmıyor

İyi olmak, meydan savaşı

Boş ver

Yaşıyor,yaşamıyor

Sen duygulardan haber ver bana

Efendim 

Hala anlamaya mı çalışıyorsun

Nar çiçeği kan’a mı bulaşmış

Bu saatte 

Akrepsiz yelkovansız zamanlara esirim

Boş ver 

Çöl kumunda çiçek açar mı

Mehmet Akif Gülhan 10.03.2006 Saat 22.02', 'Gül nargilenin nar’ı Papatya yaprağı diye kopardığım Seviyor sevmiyor Son yaprağa elim varmıyor Şair,meczubun diğer adı Yazıyor,yazmıyor İyi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-ile-nar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-mihrican-karaca-971s3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Batmayacak hiç ay''ın

Sönmeyecek hiç yıldız''ın.

Gökleri süsler kan kırmızın,

Benim allı Bayrağım.

Yerin hazırdır gönderde,

Nazlı nazlı süzülürsün göklerde.

Dayanamam inan ölürüm,

Görürsem eğer yerlerde,

Benim şanlı bayrağım...

Türkiye''nin gururusun,

Şehitlerin onurusun.

Kanım sana feda olsun

Yeterki rengin solmasın,

Benim allı,şanlı Bayrağım.', 'Batmayacak hiç ay''ın Sönmeyecek hiç yıldız''ın. Gökleri süsler kan kırmızın, Benim allı Bayrağım. Yerin hazırdır gönderde, Nazlı nazlı süzülü...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bayragim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filim Şeridi Gibi', 'filim-seridi-gibi-gultekin-toga-mhi9j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kısacık ömrümü düşündüm de ben, 

Meğer nice ateş yalım görmüşüm, 

Acıdan, tatlıdan her tür nesneden, 

Parça parça, bölüm bölüm görmüşüm.. 

Zaman aradaki engel bilmez hat, 

Her taze sonunda oluyor bayat, 

Kiminde dosdogru yalın bir hayat, 

Kiminde fiyaka, çalım görmüşüm.. 

Özgesinden darbe yedikçe bağır, 

Dağlanan bir yürek ne zaman soğur? 

Hançer yarasından daha da ağır, 

Ayrılık namıyle zulüm görmüşüm, 

Muhasebe ile anıp bakınca, 

Hakikatler hissedilir yakınca, 

Boşuna değilmiş dönüp bakınca, 

Hayat okulunda talim görmüşüm.. 

Sarılıp Hak yolun farizasına, 

Son verdim ruhumun arızasına, 

Güdümledim kalbi Hakk rızasına, 

Bu yolu selamet, selim görmüşüm.. 

Sentezi şifaya yılan vasıta, 

Ecel düğününe çıban vasıta 

Yollar Hakka çıkar, insan vasıta 

Ruhumu bu yola kilim görmüşüm..', 'Kısacık ömrümü düşündüm de ben,  Meğer nice ateş yalım görmüşüm,  Acıdan, tatlıdan her tür nesneden,  Parça parça, bölüm bölüm görmüşüm..  Z...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/filim-seridi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yanımda Olunca', 'sen-yanimda-olunca-mihrican-karaca-55xir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilesin,sen varsan bende varım,

Sensiz hayatta nasıl yaşarım.

Seninle dağlar,taşlar aşarım,

Aklım gider sen yanımda olunca.

Birbirimizde bulmuştuk sevgiyi aşkı,

Günahmış gibi dururduk hep suçlu suçlu.

Kalbim senindir,duyma benden kuşku,

Dünyam durur sen yanımda olunca.

Taptığım gözlerin,ilham verir

Seni yitirmek bana ölüm gelir.

Eller ne derse desin,inan vız gelir

Kalbim durur sen yanımda olunca..', 'Bilesin,sen varsan bende varım, Sensiz hayatta nasıl yaşarım. Seninle dağlar,taşlar aşarım, Aklım gider sen yanımda olunca. Birbirimizde bul...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yanimda-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çiçeği', 'sevda-cicegi-selami-aydemir-qaudm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rengini dünyaya ilk defa sunan

  adsız bir çiçek gibi parlıyorsa gözlerın

  yalnız sana yazıyorum bu siiri

  istersen bir şiir gibi okuma 

  çünkü her gün yeniden yazacağım onu

  millerce yol katletıkten sonra

 güneyi keşf eden bir kuşun sevinciyle

  ve yazmiş olacağım bırde

  her dönemde her çağda

  sevdanın kendine özgü dilliyle...', 'rengini dünyaya ilk defa sunan   adsız bir çiçek gibi parlıyorsa gözlerın   yalnız sana yazıyorum bu siiri   istersen bir şiir gibi okuma   ...', ARRAY['Türk Edebiyatı','Şiir','Selami Aydemir']::text[], 8.5, '{"poet":"Selami Aydemir","poet_slug":"selami-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-cicegi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyeliyim', 'turkiyeliyim-mihrican-karaca-w77ry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mihrican karaca''dır benim adım,

Manisa gördes Kıran köylüyüm.

Dört tarafı dağlık olan

Çukur bir o kadar yamaç yerleşimdenim.

Bazıları sıcak,bazıları soğukkanlıdır

Menfaat için ararlar birbirlerini.

Onun dışında sormazlar hal ve hatırlarını,

İşte ben bu çıkarcı köydenim.

Kışları soğuk karlıdır,

Yazları bol sıcak.

O sıcakta akşama kadar karın tokluğuna çalışırlar

Acı tütün kuru saman ve haşhaşta.

İşte ben

Bu aç,tok yatan yerdenim.

Dört bir tarafta vardır dedesi

Sormadım kimseye,bunlar neyin nesi.

Yaz kış çağlar Bodamas deresi,

İşte ben bu dedeli,dereli yerdenim.

Ayırmam lazını çerkezini,

 vede alevisini

Benim öğündüğüm şey

Türkün hası

Ben Türkiyeliyim...', 'Mihrican karaca''dır benim adım, Manisa gördes Kıran köylüyüm. Dört tarafı dağlık olan Çukur bir o kadar yamaç yerleşimdenim. Bazıları sıcak,...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/turkiyeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dram', 'aska-dram-orbay-eken-7kz13', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'An gelir dünya dar gelir

İnsana

Yekpare kanatlarında

Umudun

Taş ağarır,

Söz ağarmaz

O vakit

Paylaşmak zorundalık olur

Gündüzün karanlığında,

İki tomurcuk gül

İkircikli

Birbirini vurur acımasızca! 

ve seyircilerin

keyfine diyecek yoktur

Bu dramda,

Kavga gürültüye karışır

Acılar kana

ve aşk

Boğulur gider

Bu sularda...', 'An gelir dünya dar gelir İnsana Yekpare kanatlarında Umudun Taş ağarır, Söz ağarmaz O vakit Paylaşmak zorundalık olur Gündüzün karanlığında,...', ARRAY['Türk Edebiyatı','Şiir','Orbay Eken']::text[], 8.5, '{"poet":"Orbay Eken","poet_slug":"orbay-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aska-dram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal olsun sana herşeyim', 'helal-olsun-sana-herseyim-meryem-i-sler-73pcy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldız gözlerine bakan gözlerim

 Pamuk ellerini tutan ellerim 

Sana olan tüm sevgim helal olsun

Canım  herşeyim  kanatsız meleğim

Senin için çarpan kalbim

Aşkın uğruna yanan yüreğim

Seninle geçirdiğim her anım

Helal helal olsun sana canım

Canımı canına hediye verdiğim

Acılarını acım diye bildiğim

Seninle ağlayıp seninle güldüğüm

Helal olsun ömrüm sana gülüm

Yaşadığım yaşayacağım günlerim

Günüm güneşim çiçeğim

Toprağım suyum aldığım nefesim

Helal olsun gözümün nuru meleğim', 'Yıldız gözlerine bakan gözlerim  Pamuk ellerini tutan ellerim  Sana olan tüm sevgim helal olsun Canım  herşeyim  kanatsız meleğim Senin için...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/helal-olsun-sana-herseyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-mihrican-karaca-iqis9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek mi istiyorsun? 

Al kalbim ellerinde.

Gitmek mi istiyorsun? 

Hadi git güle güle.

Yalnızlık kadar vefalı olamadın,

Aradığın neydide bende bulamadın.

Emanet değildim ki saklayamadın,

Hadi git güle güle.

Şimdi sağ elim kalbimde,

Sol elimde havada.

Uğurluyorum seni

Hadi git artık,güle güle', 'Sevmek mi istiyorsun?  Al kalbim ellerinde. Gitmek mi istiyorsun?  Hadi git güle güle. Yalnızlık kadar vefalı olamadın, Aradığın neydide ben...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gule-gule-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince', 'sen-gidince-selami-aydemir-lbqr9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gidince geride bıraktığın 

Bir çit gibi

Baktım ki yorgun düşmüş 

Duvarların rengi

Şimdi sen 

Bir takvim yaprağından bakar gibisin

Bir yüzünde yıllar

Öbüründe umut çiçekleri

Balkonda ki o sessiz sarmaşıklar

Bilebilsen nasıl anlatıyor seni

Sen gidince mavilerde bir hüzün 

Sanki morarmış gibi duvardaki

Saatin sesi

Anılar saklambaç oynuyor

Odaların köşelerinde 

Sen gidince

Takvimler yaprak döküyor

Geceleri efkar kokuyor sigaram.', 'Sen gidince geride bıraktığın  Bir çit gibi Baktım ki yorgun düşmüş  Duvarların rengi Şimdi sen  Bir takvim yaprağından bakar gibisin Bir yü...', ARRAY['Türk Edebiyatı','Şiir','Selami Aydemir']::text[], 8.5, '{"poet":"Selami Aydemir","poet_slug":"selami-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-gidince-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzele Vurgun', 'guzele-vurgun-mustafa-guclu-a2lza', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün gün çok yorgun

öylesine sessiz öylesine durgun

ben bir güzele vurgun

güzel yine suskun

anlatamıyorum hislerimi

kendim yaşıyorum düşlerimi

tek tek yakıyorum şiirlerimi

ben bir güzele vurgun

demet demet güller serdim

yemin ederimki çok sevdim

ümitsiz aşka gönül verdim

ben bir güzele vurgun

bugün ben yine çok dalgın

içimde aşkı olmuş yangın

ben bir güzele vurgun

güzel bana dargın

                           mustafa güçlü

                                             edremit', 'bugün gün çok yorgun öylesine sessiz öylesine durgun ben bir güzele vurgun güzel yine suskun anlatamıyorum hislerimi kendim yaşıyorum düşler...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Guclu']::text[], 8.5, '{"poet":"Mustafa Guclu","poet_slug":"mustafa-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guzele-vurgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Gelme', 'artik-gelme-mihrican-karaca-47sc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O gün demiştin hani,gelirim diye

Hasrettin,bendeki bu sevgiye.

Hesap verecek birimi var, kime

Bıktım artık sende gelme.

Aptal yerine koymuştun beni,

Ölsemde unutamam  ettiklerini.

Harabeye çevirdin günlerimi

Bittim artık sende gelme.

Yalan sözlerin çınlıyor kulaklarımda,

Yaralar açtın gönül bağımda.

Dert adamı oldum gençlik çağımda

Doldum,taştım artık gelmezsen gelme..', 'O gün demiştin hani,gelirim diye Hasrettin,bendeki bu sevgiye. Hesap verecek birimi var, kime Bıktım artık sende gelme. Aptal yerine koymuşt...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-gelme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu İnsanları Anlayamıyorum', 'ben-bu-i-nsanlari-anlayamiyorum-mihrican-karaca-8xjno', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bu insanları anlayamadım,

İyilikmi kötülükmü yapıyorlar, kavrayamadım.

Herkesi kendime dost sayamadım

Ben bu insanları, anlayamıyorum.

Helali haramı hiç ayırmıyorlar,

Canın yansa bile,kayırmıyorlar.

Kimseyi adamdan saymıyorlar,

Ben bu insanları, anlayamıyorum.

Yüzüne gülüp, arkandan kuyunu kazarlar,

Derdini dinlemeden,fermanını yazarlar.

Onca insan içinde,bir güzel bozarlar

Ben bu insanları anlayamıyorum.', 'Ben bu insanları anlayamadım, İyilikmi kötülükmü yapıyorlar, kavrayamadım. Herkesi kendime dost sayamadım Ben bu insanları, anlayamıyorum. H...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bu-insanlari-anlayamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabristan', 'kabristan-muzaffer-boz-7fprq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KABRİSTAN

İbret yeridir kabristan diyorlar adına,

Burda ayrılık yok kul ile sultan bir olmuş.

Tenden can çekilmiş,bedenden eser kalmamış,

Hepsi solmuş,taş olmuş,toprak olmuş,yer olmuş.

***

Uzakları yakın, mesafeleri dar eden,

Ecel vade dolunca çıkıp gelmiş aniden,

Kalp durmuş,ruh gitmiş,kudretten kesilmiş beden,

Hep bir ağızdan; Ruhuma Fatiha der olmuş.

***

Bir yer ki sinler şehri, herkes halk, herkes avam,

Kimse demiyor bu benim işim benim davam,

Mazi olmuş rütbe, mevki, sınıf, sıfat, makam,

Bu naaşlar belki de serdar olmuş, ser olmuş.

***

Bütün malı, mülkü mezarı ile taşları,

Hakka dönük yüzü, toprağa yatmış başları,

Dolmuş defteri kimseyle kalmamış işleri,

Mabede benzemiş sessizlik burada gür olmuş.

***

Hiç kimse giymiyor allı, güllü esvap,libas,

Burda ne ipek giyeni gördüm, ne de atlas,

Bayramlık gibi yekpare vücuduna herkes,

Kefenleri bürünmüş her yer sanki kar olmuş.

***

Hepsini yatırmışlar bir araya sıra, sıra,

Bütün servetini bağlamışlar bir hasıra,

İhtiyaç kalmamış ne yalıya ne kasıra,

Can çekilmiş,kan donmuş,tenler burda mor olmuş.

***

Her kes etrafında olurken perver; pervane,

Beyhude imiş bu çabalama, bu hengame,

Getirmişler buraya yasla deli divane,

Göz yaşları sele dönmüş,acılar kor olmuş

***

Yan yana koyuvermişler valiyi, veliyi,

Bakmamışlar ameline kötü veya iyi,

Kardeş etmişler efendiyle masum köleyi,

Cehalet sone ermiş, herkes burada pir olmuş.

***

Canlılık kalmamış, ferini yitirmiş hayat,

Ne güzellik faide etmiş, nede güç heyhat,

Her yer ot olmuş, her yer sazlık, her yer nebatat,

Güller kokmuyor burda diken olmuş har olmuş.

***

Bir anlamı yok artık gece ile gündüzün,

Ne baharın anlamı var,ne yazın, ne güzün,

Diller lal olmuş manası yok kelamın sözün,

Cisimler bitmiş maneviyat burda nur olmuş.

***

Mabudu unutmazlar lakin mabede gitmezler,

Tenden yok olur gider, tinden yitmezler,

Rahmana zikreder amma ibadet etmezler,

Buraya gelen kırklara karışıp sır olmuş.

***

Ne mihrap var burda, ne minare, ne de minber,

Onları aydınlatmıyor ne güneş, ne kamer,

Zifiri karanlıkta gören bütün faniler,

Buraya gelmiş gözler ama olmuş kör olmuş.

***

Ademden beri yaşayan her kişi buraya,

Birer, birer gelip, saf tutup girmiş sıraya, 

Tekrar gelebilmek için geriye dünyaya,

Umutlar tükenmiş buradan dönüş zor olmuş 

.                                                               Muzaffer Boz', 'KABRİSTAN İbret yeridir kabristan diyorlar adına, Burda ayrılık yok kul ile sultan bir olmuş. Tenden can çekilmiş,bedenden eser kalmamış, He...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/kabristan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alır Başımı Giderim', 'alir-basimi-giderim-muzaffer-boz-zvgac', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ALIR BAŞIMI GİDERİM 

Sevgin ecelim olup alacaksa canımı,

Alır başımı giderim al diye, diye.

Aşkımla oynarken zille etek tamamda,

Alır başımı giderim şal diye, diye.

***

Ardından koşa, koşa düştüm bitkin; bitap,

Sevgimi yazsam ne defter alır, ne kitap,

Seninle yaşadıklarım olsa da serap,

Alır başımı giderim çöl diye, diye.

***

İstesen de artık buralarda duramam,

Kalbimi kırdığını asla unutamam,

O güzel siyah saçlarını tutam, tutam,

Alır başımı giderim yol diye, diye

***

Kimsesiz bir öksüze benzer benim halım,

Kader vurdu kırıldı kanadım kolum,

Kalmadı hayatta tutunacak bir dalım,

Alır başımı giderim dal diye,diye,

***

Zamanlı, zamansız dönüp(-Git..)  diyeceksen,

Ellerim böğrümde bırakıp gideceksen,

Viran halime bakıp, bakıp güleceksen,

Alır başımı giderim gül diye, diye.

***

Benimkisi deniz değil kader vurgunu,

Vücudumda beden değil gönül yorgunu,

Söndürmek için yüreğimdeki yangını,

Alır başımı giderim göl diye, diye.

***

Başımda pare, pare sevda bulutları,

Kalbimde deli dolu hasret duyguları,

Sevgi peteğinde olsam yalnız bir arı,

Alır başımı giderim bal diye, diye.

***

Ne yapalım ki oldum aşkının esiri,

Bu sevdanın yapılmaz tarifi; tabiri,

Öldür amma hor görme bu garip fakiri,

Alır başımı giderim mal diye, diye.

***

Zaman teknesinde hasretle yoğrulurken,

Aşkın ateşinde tutuşup kavrulurken,

Hayatın tozlu yollarında savrulurken,

Alır başımı giderim yel diye, diye.

***

Bahtımın kem yazısı yazılmış anlıma,

Sevdanın közü, ateşi düşmüş gönlüme,

Hasret kılıcını acımadan boynuma,

Alır başımı giderim çal diye, diye

***

Dünyada kendini kimsesiz sandığın gün,

Çaresizliğin ateşinde yandığın gün,

Muzafferim deyip adımı andığın gün,

Alır başımı giderim gel diye, diye. 

.                                                 Muzaffer Boz', 'ALIR BAŞIMI GİDERİM  Sevgin ecelim olup alacaksa canımı, Alır başımı giderim al diye, diye. Aşkımla oynarken zille etek tamamda, Alır başımı...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/alir-basimi-giderim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim..', 'ogretmenim-bahri-koksal-tsggn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kelimeyi,heceyi

Gündüz ile geceyi

Geçmişi geleceği

Öğrettin öğretmenim...

Yurdumun dağlarını

Yemyeşil bağlarını

Tarihin çağlarını

Öğrettin öğretmenim...

ATA''mın yollarını

Denizin koylarını

Bir yılın aylarını

Öğrettin öğretmenim...

Kurtuluş Savaşını

Güneşin doğuşunu

Onuncu Yıl Marşımı

Öğrettin öğretmenim...

ATATÜRK''e sevgiyi

Dostluğu-kardeşliği

Aydınlık Türkiye''yi

Öğrettin öğretmenim...

Dört yanda bu yurdumu

Edirne Erzurum''u

Milletimi,ordumu

Öğrettin öğretmenim...

''Yolumuz Cumhuriyet

Bağımsızlık hürriyet

Çocuklar bu bir servet''

Dedin sen Öğretmenim...

                     Tirebolu-14 Ekim 2005', 'Kelimeyi,heceyi Gündüz ile geceyi Geçmişi geleceği Öğrettin öğretmenim... Yurdumun dağlarını Yemyeşil bağlarını Tarihin çağlarını Öğrettin ö...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ogretmenim-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın Gibi Değilim Artık', 'biraktigin-gibi-degilim-artik-muzaffer-boz-d0l6m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BIRAKTIĞIN GİBİ DEĞİLİM ARTIK

Ben bıraktığın gibi değilim artık,

Ağaran saçlarım uzamış sakalımla,

Tam bir viraneyim şimdi.

Birazda kamburum mu çıkıyor ne? 

Bir de ellerim titriyor üstelik,

Ben eski ben değilim,

Alnımda çizgiler yüzümde kırışık,

Ben bıraktığın gibi değilim artık.

***

Sen gideli bedenimde yaşlandı,

Gönlümde.

Bunca kalabalıkta yapa yalnızım,

Avutmuyor gönlümü hiç bir şey,

Ne şarkılar, ne sinemalar,

Ne çiçeklerin açması keyif veriyor,

Nede ötüşen kuşlar,

Gönlüm darmadağın, kalbim kırık,

Ben bıraktığın gibi değilim artık.

***

Zaman durmuş yürümüyor,

Ne günlerin geçtiğinin farkındayım,,

Ne etrafımda olanların,

Sonbahar yaprakları gibi,

Savruluyorum rüzgarla.

Ruhum bitmiş gönlüm bitmiş.

İçimde hüzün, içimde hıçkırık,

Ben bıraktığın gibi değilim artık.

***

Canım deyince yangınlar yanardı içimde,

Yer yüzü dar gelirdi arşa çıkardım.

Artık gittin gideli gülmüyor yüzüm,

Her yer loş, her yer karanlık,

Belki de doğmuyor güneş,

Bu sıcakta üşüyorum.

Hissediyorum sonun başlangıcı yakın,

Umudum tükendi hayallerim yıkık,

Ben bıraktığın gibi değilim artık. 

. Muzaffer Boz', 'BIRAKTIĞIN GİBİ DEĞİLİM ARTIK Ben bıraktığın gibi değilim artık, Ağaran saçlarım uzamış sakalımla, Tam bir viraneyim şimdi. Birazda kamburum...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/biraktigin-gibi-degilim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Verem Etti', 'askin-verem-etti-mihrican-karaca-eloq6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tut ellerimden sakın bırakma,

Aşkım avucumun içinde.

Bak gözlerime sakın ayırma,

Aşkım,gözbebeğimin içinde.

Sarıl bana sakın ayrılma

Aşkın gizlidir kalbimde.

Konuşuyorum beni dinle,

Aşkın yer etmiş dilimde.

Ve öyle yer ettin ki bende,

Verem olmuşum aşkından,

İflas etti iki ciğerimde.

Hekimim olmak istiyorsan,

Susup beni dinle.

Ellerin ellerimdeyken

Gözlerimin içine bak.

Kendimi görmek istiyorum,

Senin gözlerinin içinde.', 'Tut ellerimden sakın bırakma, Aşkım avucumun içinde. Bak gözlerime sakın ayırma, Aşkım,gözbebeğimin içinde. Sarıl bana sakın ayrılma Aşkın g...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askin-verem-etti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaçam Dağlarına', 'alacam-daglarina-muzaffer-boz-36fzb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ALAÇAM   DAĞLARINA

Bahar gelmeden dorukların görünmez,

Başında pare, pare duman Alaçam.

Yürümekle bellerin aşıp geçilmez,

Eteklerin kar ile boran Alaçam.

***

Yamaçlarında meşe,kayın yetişir,

Budaklarında turna, bülbül ötüşür,

Ne kadar met etsem sana yakışır,

Gelmek istiyor gönlüm hemen Alaçam.

***

Kekik kokar yamacı, bayırı, düzü,

Kırlangıçlar sökün eyler dizi,dizi,

Yeşil başlı ördeği,çulluğu,kazı,

Görmek için az kaldı zaman Alaçam.

***

Yaylalarında koyun, kuzu yayılır,

Uzaktan çoban kavalları duyulur,

Akşam olunca herkes yola koyulur,

Hasretinle ederim figan Alaçam.

***

Alaçamın köyleri fakirdir, fakir,

Kimi iğ eğirir, kimi halı dokur,

Kimi düğün çalar, kimi ezan okur,

Yoksulluk buralarda ferman Alaçam.

***

Lapa,lapa yağar kar,tipi bol olur,

Kar eriri, yağmur yağar etraf sel olur,

Güneş yakar, kavurur bir hal olur,

Yazında, kışında pek yaman Alaçam.

***

Kaynaklarından soğuk suların akar,

Otlakların yonca, lale, sümbül kokar,

Yalçın kayalarından kartallar bakar,

Sensiz geçen günlere aman Alaçam. 

***

Uzaklardan bakınca mordur rengin, mor,

Bu ayrılık bize de ateş ile kor,

Muzafferim getirse kürek, kürek kar,

Söndürmeye yeter mi derman Alaçam? 

. Muzaffer Boz', 'ALAÇAM   DAĞLARINA Bahar gelmeden dorukların görünmez, Başında pare, pare duman Alaçam. Yürümekle bellerin aşıp geçilmez, Eteklerin kar ile ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/alacam-daglarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalım', 'kinalim-erbil-kutlu-x51yu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Solacak ise avucundaki kınan,

N’olur eyle beni,  üz beni…

Sen mutlu ol, bu her şeyden daha güzel…

Bu güzelliği yaşa ki, mutlu olayım bende…

Söz sana, gençliğimin hayrını görmeyeyim…

Gözünden akacak ise yaşların benim olduğunda,

Onların çocuksuluğunu

Kaybettirmeyecek olan, benim kardeşim olsun,

o, Sana; Sen, ona tek olasın,

Sözün özü; Sen mutlu olasın…

Bu yeter…

18/12/2005/Pazar

13.30', 'Solacak ise avucundaki kınan, N’olur eyle beni,  üz beni… Sen mutlu ol, bu her şeyden daha güzel… Bu güzelliği yaşa ki, mutlu olayım bende… ...', ARRAY['Türk Edebiyatı','Şiir','Erbil Kutlu']::text[], 8.5, '{"poet":"Erbil Kutlu","poet_slug":"erbil-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kinalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuva-yi Milliye', 'kuva-yi-milliye-muzaffer-boz-od324', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KUVA-Yİ MİLLİYE 

Düşmanın barbarca mezalimine karşı,

Milletçe bir duruştur Kuva-yi Milliye.

Millet yolunda,hürriyet yolunda hakça,

Ulusal bir görüştür Kuva-yi Milliye.

***

Bini verip de dört nala giden atına,

Hiç değer vermeden canına, hayatına,

Kanlı kefen ile Rabbin yüce katına,

Erdemli bir varıştır Kuva-yi Milliye.

***

Düşmanın toplarına bağrını açarak,

Gazalarda siperden sipere koşarak,

Hak nerde diye kendinden geçerek,

Milletçe bir soruştur Kuva-yi Milliye.

***

Hakkın cümle hakkına şahadet ederken,

Al kanların içinde masumca gülerken,

İstiklal uğrunda şehitliğe giderken,

Ulusal bir yarıştır Kuva-yi Milliye.

***

Yapışırken kılıcın kınına, sapına,

Bakmadan düşmanın tüfeğine, topuna,

Gözü yumuk savaşın kanlı girdabına,

Milletçe bir giriştir Kuva-yi Milliye,

***

Milletimizin bom boş kalan ufukları,

Memleketin üstünde kara bulutları,

Hürriyet diye, diye bütün umutları,

Ulusal bir yoruştur Kuva-yi Milliye.

***

Estirmek için istiklalin yellerini,

Kırmak için düşmanın kanlı ellerini,

Adalet bahçesinden hakkın güllerini,

Ulusça bir deriştir Kuva-yi Milliye.

***

Zeytin ağacının yaprağında, dalında,

Ak güvercinin gagasında, kanadında,

Türk Ulusunun toprağında, vatanında,

Ulusal bir barıştır Kuva-yi Milliye.

***

Hak yazmasın diye böyle günler bir daha,

Yıllar boyu geceler dönmeden sabaha,

Milletçe hep beraber aşk ile Allah''a,

Milli bir yakarıştır Kuva-yi Milliye,

Milli bir yalvarıştır Kuva-yi Milliye. 

. Muzaffer Boz', 'KUVA-Yİ MİLLİYE  Düşmanın barbarca mezalimine karşı, Milletçe bir duruştur Kuva-yi Milliye. Millet yolunda,hürriyet yolunda hakça, Ulusal bi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kuva-yi-milliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararsan Beni..', 'ararsan-beni-muzaffer-boz-hmtue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ARARSAN  BENİ

Bir gün olurda,

Bir gün olur da ararsan beni,

Bil ki andığın yerdeyim.

Hiç gider miyim senden uzaklara? 

Yapar mıyım,yapabilir miyim hiç? 

Et tırnaktan,

Can nefesten ayrılır mı? 

Durup da! 

Durup da boşuna arama beni,

Bil ki bıraktığın yerdeyim.

***

Bir gün olurda,

Bir gün olur da ararsan beni,

Bil ki baktığın yerdeyim.

Gördüğün ağaçta, öten kuşta,

Açan çiçekte ben varım.

Hiç gider miyim senden uzaklara? 

Yapar mıyım, yapabilir miyim hiç? 

Hiçbir yerde arama beni,

Mutluluktan ağladığım,

Küçücük ellerinle sildiğin,

Göz yaşlarıma karışıp da,

Bil ki aktığın yerdeyim! ... 

                             Muzaffer Boz', 'ARARSAN  BENİ Bir gün olurda, Bir gün olur da ararsan beni, Bil ki andığın yerdeyim. Hiç gider miyim senden uzaklara?  Yapar mıyım,yapabilir...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ararsan-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğini Verirdin', 'yuregini-verirdin-muzaffer-boz-lojns', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YÜREĞİNİ VERİRDİN.. 

Anam,.

Dertli kasavetli,maharetli anam.

Anacığım biliyor musun? 

Hiç kimse, ama hiç kimse sevmedi.. 

Beni senin sevdiğin kadar.

Gerçekti, hem de alabildiğine gerçekti sevgin,

Yürektendi, delice idi biliyorum.

Biliyorum da bunu anlamam zaman aldı.

Ve de sevgin öyle böyle değil,

Nasıl anlatayım bilmem ki? 

Belki de yıldızlar kadardı.

***

Küçüktü omuzların,

Ama yüklenirdi hayatın bütün yükünü.

Bir dağ gibi,

Dönüp bakmazdın ardına,

Gözlerin içine bakardı daima uzakların,

''''-Yarın....'''' derdin hep ''''-Yarın...'''' 

Yarınlarda evlatların vardı,

Hep evlatların.

***

Kırılırdın kırmazdın, üzülürdün üzmezdin, 

Meraktan çatlardın gecikirlerse biraz, 

''''-Yavrum! ...'''' derdin,

''''-Hiç böyle yapmazdı, ne ola ki! .....''''

Oysa hep yapardık,Hep meraklandırırdık seni..

Dedim ya bilmedik kıymetini.

Anacığım...

Yemedin yedirdin, 

İçmedin içirdin,

Gerekseydi eğer hiç düşünmeden, 

Yolar çıkarır,

Yüreğini verirdin! ....

Yüreğini verirdin! ....

Yüreğini verirdin! ..... 

.                                               Muzaffer Boz', 'YÜREĞİNİ VERİRDİN..  Anam,. Dertli kasavetli,maharetli anam. Anacığım biliyor musun?  Hiç kimse, ama hiç kimse sevmedi..  Beni senin sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yuregini-verirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi Halim', 'sebebi-halim-serhat-caliskan-eg43d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın değildir,sebebi halimin

Gözlerini yangın yerimi sandın,

Ben seni değil,aşkı sevmiştim

Sende kendini Leylamı sandın.

İçiyorsam hergece hatıralara,

Yakıyorsam peş peşe acı tütünü,

Aldanma zalim! 

Sana değil serzenişim,

İsyanım sana değil.

Eğer senin sevdan yaksaydı içimi

Dudaklarına bırakacak busem olsaydı,

Gelir kapanırdım ayaklarına.

Gözlerin gitmeseydi gözümden

Akardım gözlerine

Tutardım ellerini isteseydi ellerim

Sen istemesende

Severdim seni

Ama ben seni değil; 

Üzerindeki aşkı sevmiştim

Sen şimdi ihanete soyundun

Ben seni aşksız

Çırıl çıplak neyleyim.?', 'Aşkın değildir,sebebi halimin Gözlerini yangın yerimi sandın, Ben seni değil,aşkı sevmiştim Sende kendini Leylamı sandın. İçiyorsam hergece ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sebebi-halim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kalbime Kaydettim', 'seni-kalbime-kaydettim-munevver-duver-1v4kp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni kalbime kaydettim,

Kimseler görmesin diye,

Kalbimdeki seni buldum,

Beni sorgulamasın diye.

Sendeki beni gördüm

Beyninde, kara kutuya koymuşsun

Bitirmesinler bu aşkı diye

Yok etmesinler sevgimizi. 

01/03/2006-saat:04.18

Güzel yalı-ADANA

Çarşamba.

Güneyin Kızı', 'Seni kalbime kaydettim, Kimseler görmesin diye, Kalbimdeki seni buldum, Beni sorgulamasın diye. Sendeki beni gördüm Beyninde, kara kutuya ko...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-kalbime-kaydettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat''ım Olda', 'cellat-im-olda-muzaffer-boz-t7am8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'CELLAT''ım OLDA 

Saçını başını yolarım diyorsun,

Gözümün nuru gel de yol yolacaksan.

Kalbimdeki sevginin kadir kıymetini,

Dünyalar tatlısı gel de bil bileceksen.

Evim barkım yıkıldı oldu virane,

Aklım başımdan gitti oldu divane,

Halime bakıp, bakıp deli diye,

Canımın içi gel de gül güleceksen.

Cümle alem duydu sesimi avazımı,

Hak duyar mı bilmem niyazımı,

Evimin önünde cenaze namazımı,

Kömür gözlüm gel de kıl kılacaksan.

Aylar, yıllar geçti sayamadım yaşımı,

Dertten kasavetten arıtamadım başımı,

Kuytularda köşelerde mezar taşımı,

Gül yüzlüm gel de bul bulacaksan.

Rabbim muhtaç etti ocağına eline,

Sende kara saplı bir bıçak alıp eline,

Kalbimi dilim, dilim lime, lime,

Sevdiceğim gel de dil dileceksen.

Bahtımda onulmaz karalarımı,

Bağrımda kapanmaz yaralarımı,

Geceleri uykularımda rüyalarımı,

Dünyalar güzeli gel de böl böleceksen.

Seninle çıkayım istedim bu yollara,

Bu yollarda yürürken el ele kol kola,

Kızgınlıkla kalbime yalın pala,

Kara gözlüm gel de dal dalacaksan.

Gönlümdeki dinmez arzuyu 

Kalbimdeki deli dolu sızıyı,

Alnımdaki silinmez kara yazıyı,

Gül yüzlüm gel de sil sileceksen.

Güldükçe yüzünde açıyor kan gülleri,

Boncuk, boncuk gözleri bal akıyor dilleri,

Ben ağlarken takı verip de da zilleri,

Kara gözlüm gel de çal çalacaksan.

Aklımdan çıkmıyorsun gündüz gece,

Aşkımı anlatıyorum cümle, cümle, hece, hece,

Mahsun gözlerime bakıp da öylece,

Canımın içi gel de kal kalacaksan. 

Birlikte oturduğumuz tenhaları kuytuları,

Unutur muyum hiç tenindeki kokuları,

Gideceksin diye kalbime korkuları,

Kömür gözlüm gel de sal salacaksan.

Kimse bilmezken ününü sanını,

Kalbime çakıyla kazıdım adını,

Cellat olup da Muzafferin canını, 

Gül yüzlüm gel de al alacaksan. 

.                                        Muzaffer Boz', 'CELLAT''ım OLDA  Saçını başını yolarım diyorsun, Gözümün nuru gel de yol yolacaksan. Kalbimdeki sevginin kadir kıymetini, Dünyalar tatlısı ge...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/cellat-im-olda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Büyük Atam!', 'ey-buyuk-atam-bahri-koksal-ulljg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kafkasya''da,Galiçya''da,Makedonya''da

Ne mücadeleler verdik.

Kükredik Dumlupınar''da

Arslanlar gibi...

Yedi düveli dize getirdik

Çanakkale''de,Sakarya''da

Kocatepe,İnönü''de.

Senin önünde diz çöktü

Batının ''Sırtlan kümesi''

Medeniyetin

Tek dişi kalmış canavarları.

Seninle sel oldu

Tüm Anadolu.

Ardına takıldı,inanla,güvenle

Gösterdiğin

İlk hedefe yürüdü

Şanla,şerefle,onurla...

Dar ettin tüm işgalcilere

Güzel yurdumu.

Ey Atatürk''ün

Genç Mustafa Kemalleri

Artık kükremenin zamanı gelmiştir

Gelin hep beraber

Gençlik Marşını söyleyelim.

O''nun açtığı yoldan

Gösterdiği hedeften hiç ayrılmadan

O''na doğru yürüyelim.

Ayağa kalkıp söz verelim:

''Asırlar geçse de

Senin o aydınlık ışığın

Asla sönmeyecektir.

İnan ki bu güzel ülkendeki

Bütün Mustafa Kemaller

Asla tükenmeyecektir...''

                        Tirebolu-20 Ekim 2004', 'Kafkasya''da,Galiçya''da,Makedonya''da Ne mücadeleler verdik. Kükredik Dumlupınar''da Arslanlar gibi... Yedi düveli dize getirdik Çanakkale''de,S...', ARRAY['Türk Edebiyatı','Şiir','Bahri Köksal']::text[], 8.5, '{"poet":"Bahri Köksal","poet_slug":"bahri-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ey-buyuk-atam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırcın Sevgili', 'hircin-sevgili-aynur-sultan-46uyk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_______________Bedevinin çölündeki güneş kadar katil.

Seraplar gibi hain, insafsız yalancı.

__________________Fıratı ü Dicle kadar hırcın sevgili 

Yine bir şeyler karıştırıyorsun ya

 _____________ama neyse', '_______________Bedevinin çölündeki güneş kadar katil. Seraplar gibi hain, insafsız yalancı. __________________Fıratı ü Dicle kadar hırcın se...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hircin-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlere Vasiyetim Olsun', 'sairlere-vasiyetim-olsun-serhat-caliskan-n118w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben giderim,sonsuzluğa

Yazdıklarım size kalır

Can bedenden çıktığında

Şiirlerim öksüz kalır.

Yeni şair korkma yaz! 

Yoksa gözüm açık kalır

Ölüm oyun gelir bize

Şiirler hep canlı kalır

Çekici gelmiyor değil

Son nefeste şiir yazmak,

Hoşçakalın kağıt kalem

Azrail geldi gelecek', 'Ben giderim,sonsuzluğa Yazdıklarım size kalır Can bedenden çıktığında Şiirlerim öksüz kalır. Yeni şair korkma yaz!  Yoksa gözüm açık kalır Ö...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sairlere-vasiyetim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Bizim', 'yesil-bizim-yetkin-tekin-oprot', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sular bizim niye yandı

Söyleyin sizedir sözüm

Ademoğlu neye kandı

Yürekte bitmez hiç közüm

Dağlar bizim,böyle miydi

Yanlış mı görüyor gözüm

Yeşili hep sevmeliydi

Kaybolmuş gittikçe özüm

Yaprak bizim, ağaç bizim

Can veren su,toprak bizim

Kıyıyorlar yeşilliğe

Artıyor gittikçe sızım

Mevsim döndü iklim döndü

Karıştı dost kışım yazım

Yakıyorlar ormanları

Ağlıyor vurdukça sazım

Cahilliğe meyletmeyin

Hakkından gelinsin yozun

Sen de uzat elini de

Açılsın be gönül gözün

Bir olalım ey insanlar

Dağılsın şu kara hüzün

Yeşile beze yeniden

Umut dağıtsın hep yüzün

21, 08, 2004

Ödemiş', 'Sular bizim niye yandı Söyleyin sizedir sözüm Ademoğlu neye kandı Yürekte bitmez hiç közüm Dağlar bizim,böyle miydi Yanlış mı görüyor gözüm ...', ARRAY['Türk Edebiyatı','Şiir','Yetkin Tekin']::text[], 8.5, '{"poet":"Yetkin Tekin","poet_slug":"yetkin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yesil-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliyim Deli..!', 'deliyim-deli-mehmet-goden-a9lbp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben biraz deliyim..

öylesine,

bir delilik değil bu! 

aşktan deli..

mecnunsam

leyla; 

kerem olsam! 

aslı''m yok

kimseye bulaşmayan deli,

yaradanı sevmek.bu! 

Dostum  yok! 

şu dünyaya başka bakan biri,

ama; 

hiç kötülük etmeye kastım yok.

ben sadece bir deli''yim,

bir deli...

ben kendime düşmanım,

başka hasmım yok.

10.03.2006

Berlin', 'Ben biraz deliyim.. öylesine, bir delilik değil bu!  aşktan deli.. mecnunsam leyla;  kerem olsam!  aslı''m yok kimseye bulaşmayan deli, yarad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deliyim-deli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trenler Geldi Geçti', 'trenler-geldi-gecti-guzin-eye-dundar-vg1vs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ucu istasyondu caddenin 

aşı boyalı, bahçeli evin

kayası ağaçları altında küçük kız

salıncağında sevginin

hüzün sarardı  gözlerine

yalnızlıkla paylaşırdı günü

trenler geldi / geçti

ne  trenlere yolcu oldu yüreği

ne beklediği geri döndü

ıslanmadı yüzü bir kere

çocuk yüreğini vurdu hayat

caddenin bir ucunda gözleri tutsak

öylece..büyüdüçoğalarak…', 'bir ucu istasyondu caddenin  aşı boyalı, bahçeli evin kayası ağaçları altında küçük kız salıncağında sevginin hüzün sarardı  gözlerine yalnı...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/trenler-geldi-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindeyim...', 'i-cindeyim-mehmet-goden-m912p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ben kendimin içindeyim,

Giden gitti,Ardına bile bakmadan! 

Ben:ikilem içindeyim.

Ne arayanı var! ne soranı,

Öylece takılıp kaldım ömür denilen şeye,

Şakaklardaki karmı suçlu,benmi? 

İçimdeki çocukla yarış içindeyim,

Can`a minnet değmezmiş,

Beş paraya alınıp satılabilen

Bir gururu taşımak,

Gönül yorgun! ben tarumar,ışık yok,

Kendi Zindanımın içindeyim.

15.02.2006', 'Bir ben kendimin içindeyim, Giden gitti,Ardına bile bakmadan!  Ben:ikilem içindeyim. Ne arayanı var! ne soranı, Öylece takılıp kaldım ömür d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icindeyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Zor', 'hangisi-zor-yetkin-tekin-inkds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak mı zor

Ölmek mi zor

İkisi de kor

Ateş gibi kor

Dağda yürü, menevşeye sor

Yeşermek mi zor, sararmak mı zor

Der ki yeşerecem diye 

Bak kesildim mosmor

Yolda yürü yoksula sor

Açlık mı zor, tokluk mu zor

Ne bilsin o gariban

Biraz ekmek, birazcıkta lor

Yalıya git, zengine sor

Açlık mı zor, tokluk mu zor

Ne anlar ki açlıktan

Sofrada rakı, et, yanında da tarator

Hükümete sor

Hazırdır hemen rapor

Tek haneliye indi güya

Bizim koca “dinazor”

İnsanlık mı zor

İnsancık mı hor

Anlayamadım gitti

Hangisi zor

Gel de hayra yor

26,11,2004

Aydın', 'Yaşamak mı zor Ölmek mi zor İkisi de kor Ateş gibi kor Dağda yürü, menevşeye sor Yeşermek mi zor, sararmak mı zor Der ki yeşerecem diye  Bak...', ARRAY['Türk Edebiyatı','Şiir','Yetkin Tekin']::text[], 8.5, '{"poet":"Yetkin Tekin","poet_slug":"yetkin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hangisi-zor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-92 19/04/0001', 'mektuplar-92-19-04-0001-mahzun-doga-op9qe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürümek 

zor iş

uzunsa yol

daha zor

koşmak yoksa

Seninle yürümek 

hoş iş

uzunsa yol

daha hoş

koşmak yoksa', 'Yürümek  zor iş uzunsa yol daha zor koşmak yoksa Seninle yürümek  hoş iş uzunsa yol daha hoş koşmak yoksa...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektuplar-92-19-04-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayganlık Hissi', 'kayganlik-hissi-ese-ese-uhfp5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ardı ardına yalnız başına yanılmalarının

sende içinde bıraktığı kalıntı

deniz kurur ortada tekneler hani

heykel gibi

hüzün ama garip de var başında...

''hayat devam ediyor''dur mutlaka heryerde

sen durmuşsundur...

o an olanda mı

yoksa

daha önce olmuş olanda mı

anlayamazsın

garip ya.

yemek yersin açlık hissi geçmez

ilaç içersin ağrın geçmez gibi

bi bakarsın ki her şey sadece ''gibi'' dir

asıl yok

doğru yok

gerçek yok

hüzün şudur ki

mutluluk ve huzur hep kayıp gidiyor

her''in bitişinde

''o'' artık ''her'' olmuştur

yine garip bi şekilde...

hüznün kayganlık hissidir sadece...

hayat değil hüzün devam eder...', 'ardı ardına yalnız başına yanılmalarının sende içinde bıraktığı kalıntı deniz kurur ortada tekneler hani heykel gibi hüzün ama garip de var ...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayganlik-hissi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat gemisiyle batarken', 'hayat-gemisiyle-batarken-betul-cetin-gsv35', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbim tamamıyla kırık nedeni sen değilsin! 

                  Merdivenin en üst basamağına varamadığım için 

                  Kendime bu kez dahabkalın duvarlar öreceğim için 

                  Ağlamayacağım! kimse ağladığımı görmeyecek 

                  Boğazımda düğümlenenlerle sessizce içimden akacaklar 

                  Güçlü olduğumu söyleyeceğim 

                  Renkleri fark edebildiğimi  güneşli günü bildiğimi 

 Gülmeyi unutmadığımı zannedecekler 

                  Öyle sanmaları için bırakacağım siyahlar giymeyi 

                  Geceyi gündüz yaşamayı 

                  Her an ağlayabilecek gözlerle bakmayı 

                  Bırakacağım cevabı hiç değişmeyecek sorular sormayı kendime 

                  Her gün daha fazla güçlü olduğumu söyleyeceğim 

 Belki inanmamı sağlar diye 

                  Yine kalbim kırık olacak  ama nedenini sormayı çoktan bırakmış olacağım!', 'Kalbim tamamıyla kırık nedeni sen değilsin!                    Merdivenin en üst basamağına varamadığım için                    Kendime bu k...', ARRAY['Türk Edebiyatı','Şiir','Betül Çetin']::text[], 8.5, '{"poet":"Betül Çetin","poet_slug":"betul-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayat-gemisiyle-batarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüşlerinin Kokusu', 'opuslerinin-kokusu-hatice-bediroglu-46fsf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyazlığından mıdır bardağın

Bunca ağır hüzün

Sığınmakta mıyım yoksa beyaza 

Kırış kırış alnım 

Soba yanıyor yanmasına ya 

Titremelerdeyim 

Acı, düğüm düğüm soluğumda 

Yırtılsa derim aksa kanım 

Yanmaz hiç canım 

Ağır kalın kapılar çıkıyor hep önüme 

Ne açabiliyorum 

Ne kırabiliyorum 

Gölgesinde kalıyorsun düşlerimin

Savruluyor ruhum

Parlak yüzeyine aynanın

Patlatıyor olanca kahkahasını

Saklamadan hiç yüzüme

Kaşlarım ağır geliyor 

Kirpiklerimin üzerine 

Yol alıyor koynuma 

Ilık ılık damlalar 

Bir ürperme salıyor ki içime

Çelik gibi soğuk

Beynimin söylediklerini 

Yürek dinlemiyor işte dinlemiyor

Bu kadar yüklenme 

Yüklenme hayat üzerime

Çakılıyorum beyin üstü yere 

Mahkûmdur cılızlaşmaya 

Beslenmeyen sevda 

İsyanım var çıldırmış 

Dereye düşmüş çırpınan 

Yavru kedi gibiyim şimdi

Oysa... 

Oysa... 

Öpüşlerinin kokusu... 

Öpüşlerinin kokusu... 

Hala burnumda yar 

Hala burnumda

Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Beyazlığından mıdır bardağın Bunca ağır hüzün Sığınmakta mıyım yoksa beyaza  Kırış kırış alnım  Soba yanıyor yanmasına ya  Titremelerdeyim  ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/opuslerinin-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Kuşum', 'gonul-kusum-turgut-yildizan-6i10x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık vakitleri gezinende

Mısralarla konuşur gönül kuşum,

Ey vakit! ..Bu esrarlı hazinende

Sevdalarla tanışır gönül kuşum.

Yıldızların seyrine daldığında,

Işık ışık hikmeti aldığında,

Hayret edip öylece kaldığında

Seherlere danışır gönül kuşum.

Aydınlığın sesini duyduğunda, 

Yüreğini secdeye koyduğunda,

Sabhahları huzura doyduğunda

Pişmanlıkla yenişir gönül kuşum.

Derya deniz cihanı gezdiğinde,

Zamanı hep geçmişe dizdiğinde,

Takatini menzile çözdüğünde

Dünyaların dönüşür gönül kuşum.', 'Karanlık vakitleri gezinende Mısralarla konuşur gönül kuşum, Ey vakit! ..Bu esrarlı hazinende Sevdalarla tanışır gönül kuşum. Yıldızların se...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yıldızan']::text[], 8.5, '{"poet":"Turgut Yıldızan","poet_slug":"turgut-yildizan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-kusum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Multiple Skleroz', 'multiple-skleroz-ufuk-bayraktar-km5q5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

bugün öğrendim o güzel kızın

hayatının baharında

damla damla eridiğini.

sapasağlam tutunduğu her şey

zamanla tükenecek

yavaş yavaş bu hayat

güçleşecek.

adımları daha ağır

sona hızla yürüyecek.

2

gülümseyen dudağından

şu sözler döküldü bugün:

___hayat herşeye rağmen güzel

___güzellikleri görelim

___dertler kendiliğinden gelir

___biz  edinmeyelim', '1 bugün öğrendim o güzel kızın hayatının baharında damla damla eridiğini. sapasağlam tutunduğu her şey zamanla tükenecek yavaş yavaş bu haya...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/multiple-skleroz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapına düşdüm', 'kapina-dusdum-aydin-bayrakdar-ls6sw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emir miydi, demir miydi bu sevda,

bana gizliden bir erk olmalıydı.

Kalbimizi aynı anda titreten

bir pervane veya çark olmalıydı.

Samimî sevgide olmaz ki yalan,

olmaz ki yalanla mutluluk bulan,

ilan-ı aşkıma yardımcı olan

güllerin renginde fark olmalıydı.

Gün olur, sevdam ederse gıcık, 

mahcubum, yüzümde ter vıcık vıcık,

yanağıma kondurduğun öpücük

her sabah asgarî kırk olmalıydı.

Yerinde inşallah evin barakan,

olma sen açıkda beni bırakan,

hepsini boş ver de, yapman gereken

bana kızgınlığı terk olmalıydı.

Hani kavuşacakdık son ay''a

Beklemek zor, deme bana ''seneye''

havale edene bizi fitneye

cevabın ''Allah''dan kork! '' olmalıydı.

Göğün yüksekliği, toprağın dibi,

İtirafla oldum ben sana tâbi,

Öyle durma bana yabancı gibi,

Benim sevdiğim kız Türk olmalıydı.

İçimde vuslata ermek hayali,

Eriyorum, alma sen bu vebali! 

Nasreddin Hoca''nın meşhur misali:

Aydın''ın sırtında kürk olmalıydı.', 'Emir miydi, demir miydi bu sevda, bana gizliden bir erk olmalıydı. Kalbimizi aynı anda titreten bir pervane veya çark olmalıydı. Samimî sevg...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kapina-dusdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran 15', 'haziran-15-mehmet-goden-l5f4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haziran 15..! 

Yine Haziranın on beşi

Derdimi deşip geçti,

Her haziran ay’ı sanki,

Onunla yakıp, geçti

Ellerindeki sıcaklık,

Kalbime akar iken,

Sonsuz bir rüya gibi, bir anlık! 

Şavk olup,geçersin sen.

Gözyaşımın denizinde,

Kayboldun geçen gün ile.

Sakinlik bulurum yalnızken,kendimde! 

Olmayacak dalgalar vururken bir gün,

Çıkacak gibime geliyor, birden! 

Çaresiz kıyısında ağlarken ben.

Mehmet Göden,15.06.1978 İskenderun.', 'Haziran 15..!  Yine Haziranın on beşi Derdimi deşip geçti, Her haziran ay’ı sanki, Onunla yakıp, geçti Ellerindeki sıcaklık, Kalbime akar ik...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/8-haziran-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dağlarında', 'gonul-daglarinda-turgut-yildizan-5ijqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hoşça bir tutkuydu sekip giden,

Sevi çiçekleriyle bezenmiş

Gönül dağlarında.

Peşinden koştuğum umutlar

Ala geyikti yüreğimde sanki,

Güneşe yandırdı özümü.

Doruklarına tırmandım

Hasretini çektiğim iklimlerin,

Göz yaşımla suladım ümidimi

Gönüllerde yeşersin diye.

Geçit vermez boğazlarda 

Pusu kurarak,

Yakaladım da sevdamı kıskıvrak

Kilimlere düğümledim 

Desen desen.

Zirvesinin ak pak bulutuna vurulup

Gönül dağlarını tuttum mesken.', 'Hoşça bir tutkuydu sekip giden, Sevi çiçekleriyle bezenmiş Gönül dağlarında. Peşinden koştuğum umutlar Ala geyikti yüreğimde sanki, Güneşe y...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yıldızan']::text[], 8.5, '{"poet":"Turgut Yıldızan","poet_slug":"turgut-yildizan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-daglarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neylerim.!', 'neylerim-mehmet-goden-we4a0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutmu kaldı geri,gelen zamana 

Telef oldu ömür döndü harmana

Ağlıyor yüreğim dönüp birdaha

Seveyim diye birine bakmaz neylerim.

Hasret bir çırpıda, bitermiş sandım

Sarılıp boynuma,gitmezmiş sandım

Bu bahar ayları, bitmezmiş sandım

Sonbahar dallarımı döktü neylerim. 

Tarumar edildi hep gönülbahçem

Tomurcukdu gülü,kırıldı erken

Mevsimler değişti bahar beklerken

Karakış kapıma çöktü neylerim.

Ağladım ardından gitmesin deyi

Ya dönseydi,ya yıksaydı herşeyi

Biliyorken,buna sebep kişiyi

Cezayı gözyaşıma çaktı neylerim.

02.02.2006', 'Umutmu kaldı geri,gelen zamana  Telef oldu ömür döndü harmana Ağlıyor yüreğim dönüp birdaha Seveyim diye birine bakmaz neylerim. Hasret bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neylerim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört mevsimde bir sevda', 'dort-mevsimde-bir-sevda-aydin-bayrakdar-3djg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanışdığımız gün yirmibir Ocak,

kar üstünde gezsek inan haz gelir,

Gözlerini gördüm, sıcak mı sıcak,

Bu Şubat soğuğu artık vız gelir.

Kış geldi biz, bizi sardık ısındık,

Mart ayında aşkın oduyla yandık,

baharda sevdaya, vuslata kandık,

dillerimize hep tatlı söz gelir.

Bir Temmuz günüydü ayrıldığımız,

hiç sebeb yokken darıldığımız,

Ağustos ayında kavrulduğumuz

güneşlerin merkezine buz gelir.

Ağladım ardından sabahlara dek,

yalvardım Allah''a, senin için tek.

İnan sensiz hiç bir günün tadı yok,

hüzün var ya, hazan şimdi tez gelir.

Mevsimleri saymak hayır mı eder,

Güller solar, bülbül çileyi tadar,

Kavuşursa Aydın sana gül adar

Sana tüm gülleri versem az gelir.', 'Tanışdığımız gün yirmibir Ocak, kar üstünde gezsek inan haz gelir, Gözlerini gördüm, sıcak mı sıcak, Bu Şubat soğuğu artık vız gelir. Kış ge...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dort-mevsimde-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat geçdi gitti..', 'hayat-gecdi-gitti-mehmet-goden-71xpy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben umutlara atılan köprüyüm! 

Altımdan,binlerce Atlı geçti

Seferlere çıktım kendimle; 

Dönmeyen kaç sene geçti

Sallar beni; yorgun yıllar 

Yıkılmaya az biraz var,

Gerçeklere uğramayan; 

Bir ömür aktı geçti.', 'Ben umutlara atılan köprüyüm!  Altımdan,binlerce Atlı geçti Seferlere çıktım kendimle;  Dönmeyen kaç sene geçti Sallar beni; yorgun yıllar  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-gecdi-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Gözyaslar', 'sahte-gozyaslar-kemal-oguz-cefb8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha dün söylemistin bana yeminle

Iyice sarilmistin ellerime ellerinle

Gözlerinden akan damla damla yaslari

Birakarak ellerimi siliyordun mendilinle.

Seviyorum demistin gözlerime bakarak

Sensiz olamam demistin kollarimda kalarak

Bir elveda demeden, haber vermeden gittin

Gecmisle yasiyorum resimlere bakarak.

Anlamistim gözyaslarinin sahte oldugunu

Sevdiginden degil numaradan sokuldugunu

Sana inanmak istemistim bütün kalbimle

Sende ispatladin sevginin sahte oldugunu.

(Esslingen a/N, 24 Ekim 1987)', 'Daha dün söylemistin bana yeminle Iyice sarilmistin ellerime ellerinle Gözlerinden akan damla damla yaslari Birakarak ellerimi siliyordun me...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahte-gozyaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemedim', 'sevemedim-mehmet-goden-xnhfr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün gelirde unutursun

Diye seni sevemedim

Güllerimi kurutursun

Diye sana veremedim

Yalan olur sevgin ve Dün

Olur yalan o gülüşün

Nisan yağmuruyla düşüm

Biter diye sevemedim

Hüzün verir herşeyin

Unutturur gülmeyi

Bir fani olur insan

Gider diye sevemedim.

10.05.87', 'Gün gelirde unutursun Diye seni sevemedim Güllerimi kurutursun Diye sana veremedim Yalan olur sevgin ve Dün Olur yalan o gülüşün Nisan yağmu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevemedim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Değmemiş Bir Yürekle Sevdim Seni', 'el-degmemis-bir-yurekle-sevdim-seni-melih-coskun-xbb14', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'El değmemiş bir yürekle sevdim seni 

Kavgamı ve toprağımı 

Özüm bu işte benim

Yazılı en büyük günahım yaftamda 

Ne ölümden korktum

Ne kaybetmekten, 

Korkmadım 

Kör kurşundan 

Cehennem ateşinden 

Ama korktum

Yüreği beyninden küçük olanın korkaklığından

Sevdiklerimin dilinden dökülecek bir küçücük sözden

En temiz Türkçe’mle sevdim seni 

Acını ve sevincini

Yedi bölgemde

Yetmiş yedi ayrı kederini

Gözleri kan çeşmesi 

Her bir ana yüreğini 

Yaşanmamış baharları

Kavgasıyla nişanlı binlerce gencini

Sen 

Yüreğim 

Gözlerimin bulanıklaştığı uzak hayalim 

Gecemi üşümüşlüğüne yorgan yaptığım

Güzel yurdum 

Kara çalınmamış bir aşkla seviyorum seni 

Sen bilmesen de...

2006

www.melihcoskun.com', 'El değmemiş bir yürekle sevdim seni  Kavgamı ve toprağımı  Özüm bu işte benim Yazılı en büyük günahım yaftamda  Ne ölümden korktum Ne kaybet...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/el-degmemis-bir-yurekle-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığı sende tattım..', 'ayriligi-sende-tattim-mehmet-goden-5pras', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanımazken ayrılığı

Gün sürmeyen dargınlığı

Kavga edip kırgınlığı

Sen yaşattırdın bana

Tattım sende azabı ben 

Yanlış ettim hesabı ben

Geri kalan enkazı ben

Erken toplattırdım sana

Girdim hayat ile yarışa

Neler geldi dertsiz başa

Giden gitti zaten boşa

Gerisiyle öyle yaşa

Artik küllendi ateşin

Yaktığın ta içimdeki

Sen geriye dönsen bile 

Ben değilim, ilk gündeki.

15.01.06', 'Tanımazken ayrılığı Gün sürmeyen dargınlığı Kavga edip kırgınlığı Sen yaşattırdın bana Tattım sende azabı ben  Yanlış ettim hesabı ben Geri ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayriligi-sende-tattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-93 20/04/0001', 'mektuplar-93-20-04-0001-mahzun-doga-rkn6z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki anne

iki canım

eşim

annem

iki kadın

iki güven

Herşeyin ilki

yaşam

evren

bilinmeyen

ilk çokluğumuz

en azlığımız

en can

en tam

iki anne

iki canım

iki kadın

iki herşey

iki tek şeyim

Aşk

ve

sevmek', 'İki anne iki canım eşim annem iki kadın iki güven Herşeyin ilki yaşam evren bilinmeyen ilk çokluğumuz en azlığımız en can en tam iki anne ik...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mektuplar-93-20-04-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazcık sevgi', 'birazcik-sevgi-mehmet-goden-35170', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim sımsıcak duyguların pençesinde

Kıvranıyor yüreğim Ateşlerde

Dilim ses vermez gül gülistan içinde

Bülbüle başka tadı,bana başka biçimde

Demişsinki sevmemişti! onca şeyler ortada

Hava,Su bedava,Yaşamsa haram bana

Yaptıklarının bedeli var daha,

Görülmemiş,çözülmemiş davada

17.01.2006', 'Ellerim sımsıcak duyguların pençesinde Kıvranıyor yüreğim Ateşlerde Dilim ses vermez gül gülistan içinde Bülbüle başka tadı,bana başka biçim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birazcik-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-aydin-bayrakdar-qvj85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimi açdım yeni bir güne,

Merhaba dostluğa, aşka merhaba,

önce kendimizi, sonra dünyayı

saralım, diyelim meşk''e merhaba.

Dünya bize kalmaz, boş hayal kurma,

ben nasılım diye hiç bana sorma,

gönlüm viran olmuş, kendini yorma! 

Perişan ettiğin köşke merhaba.

Aydın sandı  ''gönül dengini buldu''

Bunca dertten sonra sevmekden yıldı.

Ben ondan kaçarken üstüme geldi,

dedi bana başka başka merhaba...', 'Gözlerimi açdım yeni bir güne, Merhaba dostluğa, aşka merhaba, önce kendimizi, sonra dünyayı saralım, diyelim meşk''e merhaba. Dünya bize kal...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merhaba-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakan İlhan Kurt', 'hakan-i-lhan-kurt-aydin-bayrakdar-z6t0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendisine:

İhtimal haricidir senin zulümden ürkmen

halkımın melalini destanlaşdıran Türkmen...

Cemiyete:

Kurtbala kardeşimiz yazdı mı güzel yazar,

Efkârı ebed yazar, yüreği ezel yazar.', 'Kendisine: İhtimal haricidir senin zulümden ürkmen halkımın melalini destanlaşdıran Türkmen... Cemiyete: Kurtbala kardeşimiz yazdı mı güzel ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hakan-ilhan-kurt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal...', 'hoscakal-mehmet-goden-0eadj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir daha Dünyaya gelmeyeceğim,

ve; yelkenli direkleri gibi:bir oraya bir buraya,

Eğilmeyeceğim! 

istersen kes Cezam`ı 

Ha bugün! ha yarın! ne farkeder? 

Bugün öyle geçti.Geçsin! 

Yarını belki görmeyeceğim! 

Fani denir Dünyaya,

hani! onca Yaşamışların yaşadıkları! 

ve:Kim? silivermiş birden; 

Geceye renk veren Karanlıkları.

15.02 2006', 'Ben bir daha Dünyaya gelmeyeceğim, ve; yelkenli direkleri gibi:bir oraya bir buraya, Eğilmeyeceğim!  istersen kes Cezam`ı  Ha bugün! ha yarı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hoscakal-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Bir Kırmızı Güldür Seninle', 'yurek-bir-kirmizi-guldur-seninle-bahaettin-karakoc-pb1aq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel duygular yeşerip 

Gök tatlı yemişler verince 

Gönül kanatlarını gerince 

Gördüklerine gösterip 

“Bu hal ne hâldir? ” diye 

“Bu yol ne yoldur? ” diye 

Soramazsın ki…

Sen bayramlar kadar

Canlı ve güzelsin

Bazen yanık bir türkü

Bazen gazelsin

Can masmavi bir göldür

Yürek bir kırmızı güldür seninle

İstesen de istemesen de

Koparamazsın ki…

Ellerin bir çift beyaz kuş 

Tanımıyor ki dur durak 

Gönlümde pervaza durmuş 

“Gel! ” demişse dostun sana, 

“Git! ” demişse deli yürek 

Bağlasalar da yerinde 

Duramazsın ki…

Sen bayramlar kadar canlı, 

Has bahçelerden güzelsin 

İp nerde inceliverse 

Daha sağlam bağlar sesin 

Sen hep özümde özelsin 

Yürek bir kırmızı güldür seninle 

İstesen de istemesen de 

Ayıramazsın ki…

Bahaeddin KARAKOÇ (Kar Sesi – Ocak Yay. 1983 / ANKARA)', 'Güzel duygular yeşerip  Gök tatlı yemişler verince  Gönül kanatlarını gerince  Gördüklerine gösterip  “Bu hal ne hâldir? ” diye  “Bu yol ne ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yurek-bir-kirmizi-guldur-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fıtrat Gereği', 'fitrat-geregi-ahmet-sureyya-durna-ltv7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yiğitler haykırmayı,korkaklar saklanmayı,

Kartallar canlı avı; kargalar leşi sever! .

Asiller dik duruşu,...içler yaltaklanmayı; 

Kalleş sütübozuklar,mutlak kalleşi sever! .', 'Yiğitler haykırmayı,korkaklar saklanmayı, Kartallar canlı avı; kargalar leşi sever! . Asiller dik duruşu,...içler yaltaklanmayı;  Kalleş süt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Süreyya Durna']::text[], 8.5, '{"poet":"Ahmet Süreyya Durna","poet_slug":"ahmet-sureyya-durna","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fitrat-geregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyumsa', 'duyumsa-nedret-celen-dlkta', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamın aynası

Ruhun değil mi? 

Ruhun ise

Bir gül bahçesi

Goncalar açılıp

Etrafa hoş kokular yayarken

Dikenler de batar

İnceden inceden...

Unutma! 

Arılar da azap duyar

Bal toplarken

Sanma ki hep böyle

Dümdüz uzayıp gider yollar

Kavisi,kavşağı,tüneli...

Hatta hırsızı,haydutu var

Kayalar altından kurtulursun da

Ufacık bir çakıl taşı yaralar.

Armudun sapı,üzümün çöpü,

Pirinçte taş var.

Özenle ayıklamazsan

Olamazsın bahtiyar.', 'Yaşamın aynası Ruhun değil mi?  Ruhun ise Bir gül bahçesi Goncalar açılıp Etrafa hoş kokular yayarken Dikenler de batar İnceden inceden... U...', ARRAY['Türk Edebiyatı','Şiir','Nedret Çelen']::text[], 8.5, '{"poet":"Nedret Çelen","poet_slug":"nedret-celen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duyumsa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Bir Ben', 'ben-de-bir-ben-sadik-dogan-dp7vh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ellerimi uzatsam 

dokunsam kalbinin derinliklerine 

                                   öpsem öpsem... 

silsem göz yaşlarını 

mavi bir bulut getirsem başının üstüne

rüzgarı çağırsam uzaklardan 

dalgalandırsa ipek ipek saçlarını 

                                  geçsem karşına…

kana kana içsem 

dalgalanan saçlarının içimde bıraktıklarını. 

tutsam yüreğini 

çıkarıp bütün senli duygularımı 

                                 gül yüzüne sersem. 

kalbini kalbim 

yüreğimi yüreğin 

umudumu umudun yapsam. 

sonra unutsam bütün 

senli ve benli özneleri 

söküp atsam ayrılıkları 

ve hep bizli cümleler kursam

                                çeksem içime çeksem 

ayyüzünde tüten dumanları. 

ateşimi ateşine katsam 

                               yansan yansan... 

çöl ortasında bir mahzun çiçek olsan. 

                                aksam aksam... 

damla damla yağmur olsam. 

nasıl sen ben de bir ben olmuşsan 

ben de sen de bir sen olsam. 

08.03.2006/Amasya', 'ellerimi uzatsam  dokunsam kalbinin derinliklerine                                     öpsem öpsem...  silsem göz yaşlarını  mavi bir bulut ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Doğan']::text[], 8.5, '{"poet":"Sadık Doğan","poet_slug":"sadik-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-de-bir-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Gitmiyor', 'i-yi-gitmiyor-necati-keceli-34ouj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ülkemde sokaklar, olmuyor tekin

     Sokaklarda kavga, dövüş bitmiyor

     İster asker, ister polisi, dikin

    ......Sokaklarda kavga, dövüş bitmiyor

    ......Bu işlerin sonu, iyi gitmiyor

     Hiç düşünmeden, bu işin riskini

     Aşılayıp, vatan, millet aşkını

     Örgüte sokarak, bir çok şaşkını

    ......Sokaklarda kavga, dövüş bitmiyor

    ......Bu işlerin sonu, iyi gitmiyor

   

     insanı ırk cinsle, bölüp gittiler

     Körpe çocukları, dağa ittiler

     Bir silah vererek, katil ettiler

    ......Sokaklarda kavga, dövüş bitmiyor

    ......Bu işlerin sonu, iyi gitmiyor

     Hep tuzakladırlar, nice yolları

     Unuttuk bombayla, ölen kulları

     Tarihler yazıyor, kanlı yılları

    ......Sokaklarda kavga, dövüş bitmiyor

    ......Bu işlerin sonu, iyi gitmiyor

     Sokaklara sagcı solcu PKK. doldu

     Ekonomi, kültür, çocuklar soldu

     Hangi örgüt, ne arayıp, ne buldu

    ......Sokaklarda kavga, dövüş bitmiyor

    ......Bu işlerin sonu, iyi gitmiyor

     Necati KEÇELİ

     ADANA', 'Ülkemde sokaklar, olmuyor tekin      Sokaklarda kavga, dövüş bitmiyor      İster asker, ister polisi, dikin     ......Sokaklarda kavga, dövü...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/iyi-gitmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Sen', 'ben-ve-sen-pinar-aslan-okqr8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ve Sen

Ben sana susamistim,sen yitirdiklerime

Bu yuzden apayriydik,kendi derinliklerimizde

Senle olmak lukstu,sana sahip olmak hayat

Bilinenin otesindeydik o yuzden de

Ben sana yorulmustum,sen bende mechul

Yagmur ciseliyordu senle olan duslerime 

Yapilmamislarsa hep bir adim ondeydi

Yapilmaya yuz tutmus,yitirilmis olanlardan.

Hayallerimin gercekligi,nefeslerime sigmayanim

Maddenin otesindeki varolus, ezgisini senden almakta

Bilinmedik birsey soyle bana,derinlerimiyse kanatma

Gozlerimden oluk oluk akitamadigim,yarinim,yuregim

Tut kelimelerimden,bana benim olanlardan birakma.

PINAR ASLAN

« Hep bir adim ondeydi onun susturdugu kelimeler,kalmasin istedim ne onunkilerden ne de bendekilerden »', 'Ben ve Sen Ben sana susamistim,sen yitirdiklerime Bu yuzden apayriydik,kendi derinliklerimizde Senle olmak lukstu,sana sahip olmak hayat Bil...', ARRAY['Türk Edebiyatı','Şiir','Pinar Aslan']::text[], 8.5, '{"poet":"Pinar Aslan","poet_slug":"pinar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-ve-sen-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamına Sevmek', 'yasamina-sevmek-hasan-ali-gurleyen-58cvn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölmek çok kolaydır aslında

Dert, tasa kalmaz insanda

Yaşıyorum işte sevdiğim için

Belki sadece bir mucize için

Bir mucize olur belki de

Bir kez olsun görürüm diye

Belki çok büyük bir mucize

Dokunurum saçının bir teline

Öyle zamanlar oluyor ki

Etlerim ayrılır kemiklerimden

Rüzgar içimden geçer sanki

Ellerimle yoklarım vücudumu

Tenim ben demi diye

Ölümü özlüyorum, istiyorum ölmeyi

Belki büyük mucize bekliyorum

Bakıpta gözlerinin içine

Seviyorum seni demek istiyorum', 'Ölmek çok kolaydır aslında Dert, tasa kalmaz insanda Yaşıyorum işte sevdiğim için Belki sadece bir mucize için Bir mucize olur belki de Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ali Gürleyen']::text[], 8.5, '{"poet":"Hasan Ali Gürleyen","poet_slug":"hasan-ali-gurleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamina-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel dedim duymadın', 'gel-dedim-duymadin-mikdat-bal-6wk72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel dedim duymadın benim çağrımı

Bu son olsun bir daha da gel demem

Bu  ayrılık çok zor, deldi bağrımı

Sende benim gibi asla ol demem

Başımdadır  hiç kimseye dilemem

Yanlız kaldım bundan gayrı gülemem

Bunca derdi bir  kalemde  silemem

Sen de beni öyle kolay sil demem

Sen gideli beri yoktur huzurum

Yalnız seni sevmek budur özürüm

Sen razı ol ben her zaman hazırım

Sen kendin gel mektup  filan sal demem

Nerde kaldı bal damlayan dillerin

Arz eylerim bülbülane güllerin

Bir çiçekti yüzündeki çillerin

Gülller solar sana  asla gül demem

Mikdati der yollar uzun ömürden

Etten kemiktenim değil demirden

Anlar isen gönülleri tamirden

İlacım sen benden ayrı kal demem', 'Gel dedim duymadın benim çağrımı Bu son olsun bir daha da gel demem Bu  ayrılık çok zor, deldi bağrımı Sende benim gibi asla ol demem Başımd...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-dedim-duymadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Ben Ve Annem', 'deniz-ben-ve-annem-emine-deniz-j7apt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben denizden taş toplardım

Annem umut toplardı

Denizi hep severdim ben

zeytinci kadının kızıyken de

hasret yüreğimde sızıyken de

ben denize taş atardım

annem denize bakar ağlardı

Hayallerim kadar büyüktü

belki o yüzden

belki de; 

benim olamadığım kadar 

özgürlüğünden

ben denizi severdim

annem denizin ötesini beklerdi

belki bu yüzdendi

onsekizinde bir denizciye tutuluşum

sonra

sönmüş bir sigara gibi 

unutuluşum

ben denizciyi düşünür ağlardım

annem zeytin toplardı

ben denizden sevdiğimi beklerdim

annem umut ekerdi

ben çocuktum

dağlar kadar özgürdüm

annem genç bir kadındı

aşıktı

ben kadın oldum

annem çocuk

deniz hala var

ben denize sevdalıyım

Annem kadar...

Ocak 2000

Edirne', 'Ben denizden taş toplardım Annem umut toplardı Denizi hep severdim ben zeytinci kadının kızıyken de hasret yüreğimde sızıyken de ben denize ...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/deniz-ben-ve-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hiç Sensiz Kalmadım', 'ben-hic-sensiz-kalmadim-yasar-demir-dhdqo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sisli uykulardan başladım güne bu sabah

Düş ülkemin talanıydı

baskından geride kalan

Yüzümü hasretinle yıkayıp,

çaresizliğimle kuruladım

Kahvaltımın başyargıcı sen oldun,

boğazımdan geçmeyen her sürgün senin elinden

Yine senli yağmurlar yağmaya başladı

gözlerimden öğleye doğru; 

Çok mu içmiştin ne,

Buram buram alkol kokuyordun

Kalabalıklar öğütüp,

çoğul yalnızlıklar ürettim

sokaktaki gök gürültüsünden

Koşar adım geçtim de ömür bulvarını

dönüp bakmadım ardıma

ölüm de gelir diye

Vardım, hayatın ta ortasında durdum

Caddelerde yorgun ağaçlar büyüyor,

bir Eylül konuyordu evlerin damlarına

kaldırımlar usul usul akıyordu bir bunalıma

Dört yanımda dilenci kediler dolaşıyor,

ayyaş kuşlar uçuyordu yalpalayarak

Sen, sağır senfoniler fısıldayıp durdun kulağıma

ben hiç sensiz kalmadım

Ne yedik, ne yemedik hatırlamıyorum ama

akşam da sen vardın yine soframda

Üç oldun, beş oldun, çoğaldın

Avuç avuç, renk renk tükettim seni

Hangisi gerçek sen, şaşırdım

Dişlerimde paslı insan kokusu

gönderimde kan pıhtısı

adrenalin genzimi yakıyordu

Elim, ayağım buz kesmiş,

ruhumsa, ateş topuna dönmüş yanıyordu

Kırk beş kalibre bir fay çatlağıydın beynimde

Richter bile şaşırmıştı şiddetine

sızım sızım sızladın

Gözlerim, seni yok sanıyordu

ben hiç sensiz kalmadım', 'Sisli uykulardan başladım güne bu sabah Düş ülkemin talanıydı baskından geride kalan Yüzümü hasretinle yıkayıp, çaresizliğimle kuruladım Kah...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Demir']::text[], 8.5, '{"poet":"Yaşar Demir","poet_slug":"yasar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-hic-sensiz-kalmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebu Yasir''den', 'ebu-yasir-den-metin-onal-mengusoglu-bsznb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar ezanla uyanırmış ahali, 

Ne rutubetten şikayet

Ne ağız dolusu küfür

Ne başucunda nöbeti 

Çıngıraklı saatlerin…

Bir zamanlar ezanla uyanılırmış

Güneş doğmazmış üstüne 

Uykuda insanoğlunun

Şehrin serin sokakları 

Birbiriyle selamlaşan 

Güleryüzlü kardeşleri 

Muhabbetle karşılarmış. 

Bir zamanlar ezanla uyanılırmış

Besmeleyle başlanırmış gündüze

Kepenkler besmeleyle açılır

Besmeleyle kesilirmiş kumaşlar

Kardeşine gönderirmiş müşterisini

Günün ilk işini yapan esnaflar.

Bir zamanlar ezanla uyanılırmış

Bir anda çarşı Pazar

Birbirine dua eden 

İnsanlarla dolarmış

Ve kadınlar ilk ağızda 

Komşusunun derdi için ağlarmış. 

Bir zamanlar ezanla uyanılırmış

Çiftçi işçi esnaf memur

Bir tarağın dişleri gibi eşit 

Aynı duvarın taşları gibi kenetlenirmiş 

Ne yerli ne yabancı 

Kimsenin gurbetlik çekmediği 

Şehirler varmış.

Bir zamanlar ezanla uyanılırmış

Evlerden camilere dolarmış mahalleli 

İçlerinden en münasip 

En akıllı en bilgili

En muttaki olanı geçermiş öne

Birlikte yönelirlermiş evrenin sahibine

Birlikte çözülürmüş cümle sorunlar 

Hem de camiin içinde.

Bir zamanlar ezanla uyanılırmış

Bayram namazından sonra 

Kucaklaşır helalleşir gülüşür

Kurbanlar keserlermiş Allah yoluna

Yürekler ikram etme yarışında 

Böylece bir anda çarparmış…

Bir zamanlar ezanla uyanılan 

Şehirler varmış…', 'Bir zamanlar ezanla uyanırmış ahali,  Ne rutubetten şikayet Ne ağız dolusu küfür Ne başucunda nöbeti  Çıngıraklı saatlerin… Bir zamanlar eza...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ebu-yasir-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asyalı Donkişot''a Şiir', 'asyali-donkisot-a-siir-metin-onal-mengusoglu-5rx45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbini 

Yaşanmamış acılarla kavuran

Kitaplar okuduğunu gördükçe 

İncinirim...

Dolan gözlerinde 

Beynini paslı bir demire çeviren 

Yalancı yağmurların 

Islaklığı, 

Dilinde ucuz sloganların kurduğu 

Sahte dünyalara ait marşlar

Ya da 

Daha adını bile koymadığın 

İşlere dair dualar varsa 

İncitirsin beni.



Çün çok aşağılarda zillet

Çok yukarıda serap 

Ve orta yolda saadet var.

Ayakları yere basmaz, 

Başları kopyacılığın tutsağı...

Hiçbir zaman üremeyen 

Bu kısır hayatı 

Değer mi zorlamak? 

Ne umuyorsun 

Kanı çekilmiş 

Çürük bir kırnap gibi 

Boşlukta sallanan 

Cansız damardan? 

Değer mi, söyle

Çölde 

Terkedilmiş bir yılan gömleğine karşı 

Açtığın savaş? 

Silkin hele 

Düşün hele, kainat 

Son nefeste 

Bir damla su gibi muhtaçken 

Düşünen ve düşündüren 

Gerçek mü’mine 

Değer mi kendini 

Taklide razı olmanın 

Farkedilmez yangınında 

Sarhoş bir asalak gibi harcamak? 

Bil ki

Şu dünya tarlasında yarın 

Ancak bilgiyle ekilen tohumlar 

Yeşerecektir.

Avrupa aptalı Don Kişot’a 

Hoş görüsünü ekleyen Asyalı Derviş! ..

İnsanı göklerde uçuran vaazlarında 

Kafana taktığın kompitürün 

Arızaları 

Hangi Usta’ya muhtaç biliyor musun? 

Şüphe güvesiyle 

Demir Çarkalar arasına sıkışan 

Tırnak acısına 

Çare yok şarkkari melankolide 

Komplexte, dragonlukta.

Dün ejderha korkusu

Bugün Amerika masalı 

Tank, uçak ve bilumum 

Motor fabrikaları, 

Taşır mı sanıyorsun seni 

Sonsuz mutluluğa; demir

Kömür, çimento, petrol,

Sen düşünmedikten sonra? 

Sen, 

Uyuşmuş bir kurtçuk gibi 

Kendini zehirleyen insan parçası

Kopyacı merak...', 'Kalbini  Yaşanmamış acılarla kavuran Kitaplar okuduğunu gördükçe  İncinirim... Dolan gözlerinde  Beynini paslı bir demire çeviren  Yalancı y...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/asyali-donkisot-a-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülen gamzeler', 'gulen-gamzeler-i-lhami-arslantas-0ra2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece rüyamda yar seni gördüm 

Gülerken yüzünde gamzeler vardı

O güzel  yüzüne yüzümü  sürdüm

Gülerken yüzünde gamzeler vardı

…………….Bu gece kırk yıllık yaramı sardı

Sende   yaşadığım sineyi cennet

Seni böyle sevmek farz ile sünnet

Sana helal olsun duyduğum minnet

Gülerken yüzünde gamzeler vardı

…………….Bir gece kırk yıllık yaramı sardı

Bir saniye gördüm bendesin hala

Seni  ruhen sevdim ey tatlı bela

Kaşın ay gibiydi gözlerin ela

Gülerken yüzünde gamzeler vardı

…………….Bir gece kırk yıllık yaramı sardı

Siperden  atılmış gülle bakışlar

Bahtıma  yadigâr  oldu nakış’lar

Gönülden  gönüle  nazlı akışlar

Gülerken yüzünde gamzeler vardı

…………….Bir gece kırk yıllık yaramı sardı

Der ilhami  bu bir  mavi düş  idi

Uçtu  gitti elden göçmen  kuş idi

Yaşadığım bütün ömre baş idi

Gülerken yüzümde gamzeler vardı

.......................Kırk yıllık yaramı bir gece sardı', 'Bu gece rüyamda yar seni gördüm  Gülerken yüzünde gamzeler vardı O güzel  yüzüne yüzümü  sürdüm Gülerken yüzünde gamzeler vardı …………….Bu gec...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulen-gamzeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-fevzi-gunenc-bsczl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Hangi limana gideceğini bilmeyen gemiye 

yararı olmaz'' diyorsun “rüzgârın”

İyi ama hangimiz biliyoruz ki gideceğini 

hangi limana gemimizin

ne zaman? 

Yaşam rüzgârı savurup duruyor işte 

hepimizi oradan oraya. 

kalıyoruz gidilecek liman 

bizim limanımız olmasa da.

Bilmek önemli mi gidilecek limanı

inilecek gemi, götürecek rüzgâr olmadıktan sonra.

sorun rüzgârı bulmakta. 

Keşke bir gemim olsa 

gemimi sürükleyen rüzgârım

gidilecek bir limanım olsa…

Vazgeçtim yolculuklardan

bir gemi gelse

demir atsa sularıma

sen çıksan içinden.

tuhaf baksak birbirimize

“bu mu” diye sorsa iç sesim bana, 

“beklediğin yolcu bu mu? ”

Sorsan sen de 

“gelmek istediğim liman mı burası? ”

Keşke sen olsan beklediğim yolcu

Keşke benim limanım olsa aradığın liman.', '''Hangi limana gideceğini bilmeyen gemiye  yararı olmaz'' diyorsun “rüzgârın” İyi ama hangimiz biliyoruz ki gideceğini  hangi limana gemimizin...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yolcu-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpek sevdam', 'i-pek-sevdam-elazigli-mustafa-kaya-po4cd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayaz soğuğu  bir ırmak geçiyor

inatla

çılgın ve coşkulu.

fısıltıları,

bir şarkı olup akıyor içimde

etrafı yeşil Sakarya.

özledim

sabahları  dinlemeyi

bu şehri.

kuş sürülerini

dağlardan esen yeli

pazar yerlerini

sakarya’ya,

bir tren yolculuğunu özledim

orada,

sisler içinde maşukiye

görülmeye değerdi.

bayırları ebegümeci.

yemyeşil toprağı

bereketli.

savruluyor aklım oralara

sıcak yaz günlerine

ağaçların uykularına.

ve o ağlayışlar,

ağustos acıları

kalbimin en gizli yerinde kalıyor.

göğün altında,

davetsiz bir misafir,

ruhuma çöken akşamlar.

şimdi çaresiz ipek sevdamı,

umutla …bir

lale parlaklığında 

ellerimde büyüteceğim …..



Mustafa kaya

03.03.2006 / üsküdar', 'ayaz soğuğu  bir ırmak geçiyor inatla çılgın ve coşkulu. fısıltıları, bir şarkı olup akıyor içimde etrafı yeşil Sakarya. özledim sabahları  ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ipek-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-gulseren-onay-xy5za', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yoksun dalımda bülbülüm üzgün 

Sevda ateşinden yüreğim bozgun

Gündüzler neyse de geceler kuzgun 

Gözüm yollarında kaldı gelmedin… 

Kurudu pınarım hasretin doldu

Gelmedin güneşim, gülüşüm soldu

Aşkımı anlattım bak masal oldu 

Sözüm dillerinde kaldı gelmedin

Anladım dün gece gördüğüm düştü

Tutmadığın sözler boyunu aştı

Tükeniyor korum ateşim düştü

Közüm küllerinde kaldı gelmedin 

11.03.06/ANTALYA', 'Sen yoksun dalımda bülbülüm üzgün  Sevda ateşinden yüreğim bozgun Gündüzler neyse de geceler kuzgun  Gözüm yollarında kaldı gelmedin…  Kurud...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gelmedin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye şiir', 'geceye-siir-nejat-karagoz-cow3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceyi donduran ayaza ateşleri işledim 

Seni işledim yüreğime; 

Ayazı yakan ateşi söndüresin diye.

Öyle bir cehennem ki yüreğim oysa; 

ateş yandı,

su yandı,

Sevdam yandı da,

Bir ben yanmadım gitti...

Suya yazdım gönlümün matemini

Havaya anlattım

Rüzgara dert yandım

Seni söyledim bütün aleme

Vay hasret dediler

Vay gurbet dediler..

Ah.. ateş dediler

Seni dediler

Pervane ateşe 

ateş yokluğa

yokluk ölümsüzlüğe; 

Pervane “Aşk” olmaya

Ben ateş olmaya talibim

Ateş,rüzgar,su ve toprak gibi

Sevdam,ben,sen ve ölümsüzlük

“Aşk”: Yok oluş

yeniden varoluş demek

ve her varoluş

bir yok oluşa yolcu..

ben,sen,ateş,pervane..

biz ölümsüz gerçeğiz

Gerçek biziz.', 'Geceyi donduran ayaza ateşleri işledim  Seni işledim yüreğime;  Ayazı yakan ateşi söndüresin diye. Öyle bir cehennem ki yüreğim oysa;  ateş ...', ARRAY['Türk Edebiyatı','Şiir','Nejat Karagöz']::text[], 8.5, '{"poet":"Nejat Karagöz","poet_slug":"nejat-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/geceye-siir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir nehir gibi akıyorum', 'bir-nehir-gibi-akiyorum-elazigli-mustafa-kaya-ovw1r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir nehir gibi akıyorum 

güzel bir resmin

içinde.

saçlarımı,

üstümü başımı düzeltir gibi.

hayret…hayret

vadilerden,

dağların diplerinden,

ovalardan,

otluklar arasından,

çocuğumsu bakışlarla bazen

hiç acı çekmemiş 

gibi akıyorum.

bazen,

kederler yüklenmiş.

yapyalnız

ıssız 

sonu gelmeyen,

yorgun ve,

tükenmiş …

Mustafa kaya

10.03.2006 / RİVA', 'bir nehir gibi akıyorum  güzel bir resmin içinde. saçlarımı, üstümü başımı düzeltir gibi. hayret…hayret vadilerden, dağların diplerinden, ov...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-nehir-gibi-akiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Yanına Geleceğim', 'bir-gun-yanina-gelecegim-sair-hilal-9clzk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bir elimde  iyilik

Bir elimde kötülük geleceğim yanına

Ya iyiliği alır hidayete erersin 

Ya da kötülüğü alır  gaflete düşersin

Bir gün bir elimde insafsızlık 

Bir elimde sevgi geleceğim yanına

Ya sevgiyi alır benimle birlikte gelirsin

Ya da insafsızlığı alır yoluna devam edersin

Bir gün bir elimde yalnızlık 

Bir elimde merhamet geleceğim yanına

Ya yalnızlığı alır karanlıkta kaybolursun

Ya da merhamati alır insan olursun

Bir gün bir elimde ay 

Bir elimde güneş yanına geleceğim

Ya sende benimle birlikte bu davaya ortak olursun

Ya da güneşle ay  elimden düşene kadar

Peşini bırakmam.', 'Bir gün bir elimde  iyilik Bir elimde kötülük geleceğim yanına Ya iyiliği alır hidayete erersin  Ya da kötülüğü alır  gaflete düşersin Bir g...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilal']::text[], 8.5, '{"poet":"Şair Hilal","poet_slug":"sair-hilal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gun-yanina-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Yeşili Gözlerin', 'yosun-yesili-gozlerin-savas-erdem-efbf7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göndermişsin gözlerinin yosun yeşilini 

Yine ürkek, yine çekingen 

Fakat, 

Bu sefer ateşli. 

Yakmak niyetindeymişsin 

Kalbimdeki sönmüş ateşi 

Vazgeç bir tanem vazgeç. 

Yanacak nem kaldı ki. 

Bir kalp yanar, yanar 

Kül olur. 

Sonra, 

Her şey unutulur. 

Gönderme gözlerinin yosun yeşilini 

Ne olur, istemem. 

Korkarım. 

Yine severim bir tanem.', 'Göndermişsin gözlerinin yosun yeşilini  Yine ürkek, yine çekingen  Fakat,  Bu sefer ateşli.  Yakmak niyetindeymişsin  Kalbimdeki sönmüş ateş...', ARRAY['Türk Edebiyatı','Şiir','Savaş Erdem']::text[], 8.5, '{"poet":"Savaş Erdem","poet_slug":"savas-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yosun-yesili-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Batımında', 'her-gun-batiminda-savas-erdem-p9da6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gün batımında 

Bir yeni sevgi doğar içimde 

Sana olan hasretliğim uyanır. 

Gözlerim 

Bulutların arasından kayan güneşi seyreder 

Kirpiklerim birbirine dargın 

Birleşmemeye yemin etmişçesine uzak. 

Gözbebeklerimde bir acıma 

Bir umutsuzluk 

Ve bekleyişin verdiği yorgunluk. 

Her gün batımında 

Bir başka dünyanın adamı olurum ansızın 

Yüz yüze gelirim tüm gizlerle 

Kulak zarlarım yırtılır 

En kahredici kahkahalardan. 

Her gün batımında 

Bir yeni sevgi doğar içimde 

Her zamankinden güçlü 

Her zamankinden istekli 

Bitmek bilmeyen bir ateş 

yakar bitirir sabaha dek', 'Her gün batımında  Bir yeni sevgi doğar içimde  Sana olan hasretliğim uyanır.  Gözlerim  Bulutların arasından kayan güneşi seyreder  Kirpikl...', ARRAY['Türk Edebiyatı','Şiir','Savaş Erdem']::text[], 8.5, '{"poet":"Savaş Erdem","poet_slug":"savas-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-gun-batiminda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşe Kardeşçe', 'kardese-kardesce-savas-erdem-ij0to', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elim boyalı diye 

Elini vermeyen kardeş 

Elimdeki boya 

Benim ekmeğimdir 

Bilir misin?', 'Elim boyalı diye  Elini vermeyen kardeş  Elimdeki boya  Benim ekmeğimdir  Bilir misin?...', ARRAY['Türk Edebiyatı','Şiir','Savaş Erdem']::text[], 8.5, '{"poet":"Savaş Erdem","poet_slug":"savas-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kardese-kardesce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin Yeşilinde Yıkandım', 'gozlerinin-yesilinde-yikandim-sair-karizma51741-4op3e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarın getirdiği hasretinin kokusu olmalı. 

Bu yüzdendir beynimdeki gül ağaçlarının 

kokusunu duyamamam. 

Ayrılık rüzgarlarının, dinmeyen senfonileri eşliğinde,

ayazın gücü bile düşlerimde sevdanı yenemedi. 

Hüzün çökmüştü bir kez yüreklere. 

Bir sevda türküsü geliyordu uzaklardan,

dalgaların ses çıkarmadığı zamanlarda

özgürce.

Yüreğinin titreyişini duymak çığlık çığlığa 

ve seni sormak alabildiğine. 

Ne teninin sıcaklığını duydum bedenimde,

ne gözlerinin yeşilinde yıkandım. 

Zaman dengesizce akıp giderken,

hüznün sevdalandığı anlarda tan ağarıyordu..', 'Rüzgarın getirdiği hasretinin kokusu olmalı.  Bu yüzdendir beynimdeki gül ağaçlarının  kokusunu duyamamam.  Ayrılık rüzgarlarının, dinmeyen ...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerinin-yesilinde-yikandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Hoşgeldin Ey Güzel', 'yuregime-hosgeldin-ey-guzel-sair-karizma51741-uozsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın anlamsız adımlarını atabilmenin 

derin sıkıntısı içindeyken, 

ruhumun derinliklerine 

parlayan bir güneş gibi çıkıverdin karşıma 

sen. 

Ve ben, 

O an şaşkınlığımı kelimelerle 

ifade edememenin sarhoşluğunu yaşadım 

İnsafsızca. 

Hani derler ya, 

Gözlerin, 

Bir tabanca mermisi gibi saplandı beynime de, 

Başımın içinde gül ağaçları kokularını salıverdi sanki. 

İnanılmaz bir zamanda, 

Tarifsiz sıkıntılarımı yok edercesine çıktın sen 

Tüm güzelliğinle. 

Beni böyle, 

Tüm benliğinle bağlamaya hakkın varmıydı ey sevgili. 

Genede, 

Yüreğime hoş geldin.', 'Yalnızlığın anlamsız adımlarını atabilmenin  derin sıkıntısı içindeyken,  ruhumun derinliklerine  parlayan bir güneş gibi çıkıverdin karşıma...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuregime-hosgeldin-ey-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / BULDUK', 'bir-dortluk-de-sen-yaz-bulduk-siir-perisi-grubu-70rc0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

Fazilet köşkünde sahte merasim 

Güzeli ararken ÇİRKİNİ bulduk! 

Ne zaman bitecek Ya Rab bu mevsim 

Gerçekle hayalin FARKINI bulduk! ..............(Ayak Dörtlüğü)    Zülfikar Yapar Kaleli 

1. 

Zamanın arısız kokmuş balında, 

Hep armut aradık çamın dalında, 

Sabır sarayının engin yolunda, 

Hazreti Eyyüb’un KÜRKÜNÜ bulduk! ..............Zülfikar Yapar Kaleli 

2. 

Günümüz insanı gaflete daldı 

İlimin ışığı uzakta kaldı 

Cehalet sırıttı yüzlere güldü 

Kucakta doğrunun TERKİNİ bulduk! ...............Mehmet Işıkoğlu 

3. 

Harama uzandık, helâl var iken, 

Güle bakar gözler, görülmez diken, 

Güzeli, çirkini hesaba çeken, 

Üstümüzde Hakk''ın ERKİNİ bulduk! ...............Turan Orak 

4. 

Bil ki saadet kumdan bir kale. 

Giderek sivrilir söz bile bile. 

Olurken yanılgı özde silsile, 

Yaşamda duygunun TERKİNİ bulduk! ...............Feride Özmat 

5. 

Herkes bir palyaço,oynuyor oyun 

Cambazın yerine kendini koyun 

Dönen dolaplara kulak ver,duyun 

Yaşamın içinde SİRKİNİ bulduk! .................İbrahim Coşar 

6. 

Zamanın içinde yaşarken bomboş 

Amaçsız yaşamak ne kadar nahoş 

Hedefler belirle azmet ona koş 

Hileyle hayatın ÇARKINI bulduk! ................Mehmet TEKECİ 

7. 

Aman be sultanım bu telâş niye? 

Dereni kuruttun, kaldın teşneye... 

Durduk yerde şu tay neden kişneye? 

Tahtının ardında KORKUNU bulduk! ...............Ahmet Turan Altunsu 

8. 

O baharsa senin için gül açsın. 

O hazansa ağıt yaksın ağlasın. 

Kurusun dereler, denizler taşsın. 

Yeşeren dalların UFKUNU bulduk! ................Suna Doğanay 

9. 

Neslime çatmaktır daim işleri 

Hırlayıp görünür azı dişleri 

Kesilmeli derim artık fişleri 

Haçlı zihniyetin IRKINI bulduk! ................Şemsettin DERVİŞOĞLU 

10. 

Zaman geçer gider, hesap olur mu 

Devran döner durur, sana kalır mı 

Hayat biter olur, akla gelir mi 

Bir nefes ezgide ŞARKINI bulduk! ................Ali Işık 

11. 

Yaz katip yaz halkın arzu halini 

Geçim sıkı vurmuş eğmiş belini 

Beyler zay eylemiş alın terini 

Zenginle fakirin BAHTINI bulduk! ................Mehmet Ali DEMİRCAN 

12. 

Allah''ım ne hazin bu manzaralar 

Düzensiz bu düzen beni yaralar 

Ayrılamaz olmuş aklar karalar 

Ne garpını ne de ŞARKINI bulduk! ................Samet Mehmet Bora 

13. 

Galin canlar gelin, yoldaş olalım 

Bir hep,hepimiz bir kıymet bilelim 

Güzel ülkemizde huzur bulalım 

İleri adımın ÇARKINI bulduk! ....................İsmail Doğan 

14. 

Yoksulluğun tarlasını sökerken, 

Çok yorulduk taşa tohum ekerken, 

Adamlar deliye hasret çekerken, 

Bizler enayinin KIRKINI bulduk! .................Şahin Yılmaz 

15. 

Acılar kaplamış kalbi sen yokken 

Tok anlar mı halden aç kimse varken 

Sevmeye zaman var vakit bak erken 

Bak şimdi kötünün AHTINI bulduk! ................Serdar Sayıl 

16. 

Tenimin rengiydi, Ademî Türab 

Serpiyordu ruha, suretinden Rab 

Damla damla k a n d ı k, değil di Serap 

Ç/öl de bengisuyun, ZERKİNİ Bulduk! .............ORKUN IŞIK 

17. 

Tarih sahnesinin en büyük soyu 

İnsanlığa örnek her oğuz boyu 

Hak yoldan yürüyen kınık ve kayı 

Beşbin yıl önceden TÜRKÜNÜ bulduk! ..............Hayri Arıkan Serdaroğlu 

18. 

Duygular acıtır,sızıdır kalpte 

Kaçarken acıdan,ararsın seste 

Bir tınıda bulmak,istersin kalpte 

Ararken sevgiyi,TERKİNİ bulduk! .................Ebru Rabia Berkul. 

19. 

Eloğlu yurduna seçer güzeli 

Seçilen yad eder ebed ezeli 

Bize mi ayırdın yarab özel''i! 

Güzeller dururken ÇİRKİNİ bulduk! ...............Saim Bastık 

20. 

Doğrunun tahtında yalan oturur 

Aslan yatağında çakal barınır 

Çalıntı serveti dinle arınır 

Ayaktan baş oldu FARKINI bulduk! ................Esat KORKMAZ 

21. 

Tahttan indiriyor ah padışahım 

Göz yaşları karın doyurmaz Şahım 

Belki af edilir dedim günahım 

Kalbi kaya taştan BERKİNİ bulduk! ...............Tuncay AKDENİZ 

22. 

Zannederdik gönül ahtına düşmüş 

Maalesef kara bahtına düşmüş 

Beklerken padişah tahtına düşmüş 

Terkedilmiş evin BARKINI bulduk! ................Hıfzı ÖZBEKMEZ 

23. 

Gezdik şu dünyayı seyran eyledik 

Karınca üstünde filleri gördük 

Yoksul ne haldedir diye bakındık 

Her yerde varsılın KÖŞKÜNÜ bulduk! ..............Temel Duran', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-bulduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Sevdalandığı An', 'huznun-sevdalandigi-an-sair-karizma51741-rvzq7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bu şiirlerde bitecek ve anılarda kalacak. 

kağıtlardaki solmuş yapraklar arasından fısıldayacak renkli yaşamdaki hoşnutsuzca cümleler 

ihaneti anlatacak,sevgiyi gönderecek belkide. 

kimbilir, yaşamdaki hüznün sevdalandığı an, 

vakit bulabilecekmi.............. 

bence hep yaşarız bunu,hayatımızda.

ama ne görmek mümkün nede duymak.sadece hissederiz ve sevdalanırız şuursuzca 

alabildiğince dengesiz ruhlar eşliğinde........ 

gecelere ve gündüzlere hiç bir zaman sıfat koyamayız. 

onlar çeker bizi içindeki cazibeli düşlere. 

ve bizlerde bunlara inanarak takibe başlarız.güneş kerevetin arasından süzülürken,sevgi yüklü bulutlardan damlayan mutluluk gözyaşlarının içinde dansetmek varken,

nedense hüzünlerde boğuluruz biz. 

eyvah! 

yine hüzün.

yine acı, yine keder. 

yersiz ve zamansız sıfatlar alır götürür bizi gözyaşlarına, 

söylenmemiş seranatlar eşliğinde

hüznün sevdalandığı anlara............', 'Bir gün bu şiirlerde bitecek ve anılarda kalacak.  kağıtlardaki solmuş yapraklar arasından fısıldayacak renkli yaşamdaki hoşnutsuzca cümlele...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huznun-sevdalandigi-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dörtlük de Sen Yaz / HECELER', 'bir-dortluk-de-sen-yaz-heceler-siir-perisi-grubu-hpdzz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun ŞİİR PERİSİ GRUBU yetkili şairlik sayfasında yayınlanmasına izin vermiş sayılmaktadır. Kendi dörtlüğü dışında, şiirin bir kısmını yada tamamını sayfasında yayınlamak isteyen şairler, diğerlerinden izin almak zorundadır...(Yasal Uyarı)

Şiir anı yaşar, şair onda ruh. 

Duygudan duyguya AKAR heceler. 

Umut pazarlıksız, sitemler güruh. 

Kalplere avize YAKAR heceler....................(Ayak Dörtlüğü)    Necmi Ünsal 

1. 

Hasreti öptüm ben, sılam darıldı. 

Duygu akla galip, söze sarıldı. 

Hasret yaktı arzı, toprak yarıldı. 

Gönüllere nişan TAKAR heceler...................Necmi ÜNSAL 

2. 

Ne zaman hasretin girse düşüme, 

Bir hançer saplanır o an döşüme. 

Hüsran vurgunuyla gel de üşüme! 

Dilin alevinden BIKAR heceler...................Feride Özmat 

3. 

Diller anlaştıkça dostluk oluşur 

Niyet bozuk ise yalan karışır 

Bilip bilmez yere boşa konuşur 

Anlamsız cümlede SIKAR heceler..................İbrahim COŞAR 

4. 

Sakın sanmayın ki sitem ederim 

Kendi imkanımla keder ederim 

Cana tak ederse çeker giderim 

Bir başına kalır BEKAR heceler...................Ali Işık 

5. 

Sevdan hecelere sığmayan düştür 

Ecel ki bir kafes, can tutsak kuştur. 

Tut ki zaman sapan içinde taştır 

Başımın üstünden BAKAR heceler...................Zülfikar Yapar Kaleli 

6. 

İlk kez çiçek açtı gülünden oldu. 

Beklenen umutlar düşlerde soldu. 

Özlenen şafaklar geceye yoldu. 

Dudakta asılı VAKAR heceler......................Suna Doğanay 

7. 

Ne zaman çıkarım karşına senin 

Rast gitmez işlerin benden bilirsin 

Kimseye kötülük sanma isterim 

Ben şiir yazarım OKUR heceler....................MetinYaltı 

8. 

Damla damla yaşar hayat özünü 

Aktığında açtı mana gözünü 

Yüreğinde aşkı çalar sazını 

Sözdeki manayı SÖKER heceler.....................Mehmet TEKECİ 

9. 

Bazen kara bulut eser başımda, 

Bazen gül sevgiler açar gönlümde, 

saf olur mısralar akar kalplere, 

dizi dizi yakar, ÇOŞAR heceler...................Mehmet Ali DEMİRCAN 

10. 

İnsanlıktan yana çosar sevgisi 

Türküye neşe tat katar esgisi 

Tartışılmaz güzel söze saygısı 

Zehir şer sözlerden BIKAR heceler................İsmail Doğan 

11. 

İlimdir dünyada her işin başı 

Kitaptır alimin sır arkadaşı 

Konuşarak kendini anlatır kişi 

Sözleri ortaya DÖKER heceler.....................Mehmet Işıkoğlu 

12. 

Gönülde dalgalar coşup taşıyor 

Serimdeki duman dağı aşıyor 

Adın zikrederken cümle şaşıyor 

Nağme nağme dosta AKAR heceler...................Şemsettin Ağar / DERVİŞOĞLU 

13. 

Yazdığım her şiir gönül yarası 

Okudukça kanar,kanar şurası 

Her satırda onun bir hatırası 

Hançeri bağrıma SOKAR heceler....................Saim Bastık 

14. 

Şairler saf tutmuş çağlayıp coşar 

Dizeler birbirin ardından koşar 

Serhati bunlara özlemle yaşar 

Yürekten dökülür UÇAR heceler....................Tamer Duran 

15. 

Şu aşkı ebedi onlar anlatır 

Şu gönlü ebedi onlar anlatır 

Şu bahtı ebedi onlar anlatır 

Ah mısralardan ah ÇIKAR heceler..................Serdar Sayıl 

16. 

Şairler saf tutmuş çağlayıp coşar 

Dizeler birbirin ardından koşar 

Serhati bunlara özlemle yaşar 

Yürekten dökülür UÇAR heceler....................Tamer Duran 

17. 

Hece hece böldüm, yarin adını, 

Her hecede farklı buldum tadını, 

Alevsiz, dumansız sevda od''unu, 

Rüzgârsız, kibritsiz YAKAR heceler...............Şahin Yılmaz', 'Şiir Perisi Grubumuzun ''''Bir Dörtlük de Sen Yaz/Aşığım Aşık'''' isimli ortak şiirimize bir dörtlükle katılan herkes bu dörtlüğünün, grubumuzun...', ARRAY['Türk Edebiyatı','Şiir','Şiir Perisi Grubu']::text[], 8.5, '{"poet":"Şiir Perisi Grubu","poet_slug":"siir-perisi-grubu","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/bir-dortluk-de-sen-yaz-heceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Hüzündü Benim', 'adim-huzundu-benim-sair-karizma51741-t1cs4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adım hüzündü benim 

yaşamın varolmuşluğunda. 

Yaşam denen kargaşa içinde yenik düşmemek için

tüm çabalar, 

tüm direnmeler, 

ve bitmek bilmeyen zamanlar. 

Yüzlerdeki gülümsemeler, 

sahtelikler, 

sabırsızlıklar, 

anlamsız istekler. 

Koştukça peşinden erişilmeyen gönüller, 

ulaşılmayan sevdalar, 

pertavsız üzerinden görünen ablak suratlar. 

İstemek gerekir hayatın barışıklığını. 

Yaşamak gerekir yalnızlığı,hüzünü, 

gökkuşağının o renkleri altında inançlılığı. 

Uzanıyorsun hayata doludizgin, 

ellerin kadehlerdeki zehirden benek benek, 

bir ziftin çıkardığıdumandan sapsarı olmuşçasına. 

Sapık ruhların çıkardığı teraneler, 

köhnemiş masalardaki zift kokulu tablalar arasındaki alışverişler, 

Ve kurumuş dudaklardaki anlamsız sözlerle beraber, 

manasız ifadeler. 

Adım hüzündü benim arkadaş. 

Yokolmuşluğun arasında hiçliklerle pekiştim, 

varolmuşluğu yakalayamadım. 

Bulutların arasından yüzünü gösteren güneş gibi 

yaşamın sirtaki oyunu, 

bir öyle bir böyle. 

Ve bir virane yıkılmışlığın içersinde, 

Yalnızlık oyunları. 

Varlığını hissedemeden yaşamak, 

bir gül dikeninin kanattığı gönüllerdeki sevda oyunları arasında yok olmak. 

Demli bir çayın tadı gibi buruk yaşamın içinde, 

Sek bir içkinin verdiği sarhoşluk kadar acımasız, 

bir sevda kadar kalleş, 

Ve bir dost kadar arkadaş sensizliğin çığlıkları. 

Adım hüzündü benim 

yaşamın varolmuşluğunda.', 'Adım hüzündü benim  yaşamın varolmuşluğunda.  Yaşam denen kargaşa içinde yenik düşmemek için tüm çabalar,  tüm direnmeler,  ve bitmek bilmey...', ARRAY['Türk Edebiyatı','Şiir','Şair Karizma51741']::text[], 8.5, '{"poet":"Şair Karizma51741","poet_slug":"sair-karizma51741","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/adim-huzundu-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilirsin....', 'sen-bilirsin-pinar-koc-n9c76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlettiğin kadar özlersin,

Hissettiğin kadar seversin,

Ve beklettiğin kadar beklersin………

Sen bilirsin…….

Son bir adım kalmışken,

Umutlarına umutsuzca sarılmışken,

Sevmeyi unutup,sevilmeyi seçmişken,

Özlettiğin kadar özlersin,

Beklettiğin kadar beklersin,

Ve dokunduğun kadar seversin…….

Sen bilirsin……..

                                                               11.03.06', 'Özlettiğin kadar özlersin, Hissettiğin kadar seversin, Ve beklettiğin kadar beklersin……… Sen bilirsin……. Son bir adım kalmışken, Umutlarına ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bilirsin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Mavi Sevdalar....', 'deli-mavi-sevdalar-pinar-koc-5xwsb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne deli mavi sevdalar sarardı ruhumuzu,

Mart akşamlarının sancılı soğuklarında…….

Canımız yanardı belki,

Belki yüreklerimiz üşürdü.

Şiirlerimizle ovardık donmuş hislerimizi….

Ve yüreklerimizde yanan ateşe,

Bir odunda biz atardık…..

Ve kor oluncaya dek

Bakar,bakar ağlardık…….

Ne deli mavi sevdalar sarardı hüzünlerimizi,

Bedenlerimizi hiç titretmeyen,

İçimizdeki ateşi hiç söndürmeyen……

Sessiz bir körebe oynardık acılarımızla,

Akşam kızılıklarının gün batımlarında…..

Ve yüreklerimizde kuruyan umutlarımıza,

Bir çakmak da biz çakardık……

Ve kor oluncaya dek,

Bakar,bakar ağlardık……

Ne deli mavi sevdalar hazırlardı sonlarımızı,

Sadece bakar 

Ve sadece

Ağlardık……

Deli mavi sevdalar şiir grubuna ithafen……           11.03.06', 'Ne deli mavi sevdalar sarardı ruhumuzu, Mart akşamlarının sancılı soğuklarında……. Canımız yanardı belki, Belki yüreklerimiz üşürdü. Şiirleri...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/deli-mavi-sevdalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resulullah''a Şiir', 'resulullah-a-siir-sair-hilal-g1yzu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel! karanlık basmadan gece sökmeden gel

Karanlığı aydınlatan nurunu saçarak gel

Ellerim semada diz çökmüş bekliyorum seni

Duymak istiyorum senin sesini 

Bilmek istiyorum senin de beni sevdiğini

Haykırmak istiyorum sana olan sevgimi 

Sesim çıkmıyor

Bakmak istiyorum sana doya doya 

Ama sen gelmiyorsun

Gel! saçlar ağarmadan kalpler kararmadan gel

Gel! düşler tükenmeden ümitler bitmeden gel

Seni sevmeyen kalbe mühür vurulmuş

Senin için ağlamayan gözler kurumuş

Seni sevdiğini söylemeyen diller tutulmuş

Bak ya resul! bu kalp hala senin için çarpıyor 

Bu gözler hala senin için ağlıyor

Bu dudaklar hala seni sevdiğini söylüyor

Bak! yine akşam oldu karanlık bastı

Ama gözümü kapattığım an herşey aydınlıktı

çünkü hayallerimde rüyalarım da sen varsın 

sen varsın aldığım nefeste her bir solukta

sen varsın dilimde,kalbimde, ruhumda,içimde

gel! gel kalbimde sevgin bitmeden gel

kalbimde sevgin hiç bitmeyecek

demek ki sen hiç gelmeyeceksin

bi daha gelmeyeceksin bu yalan dünya ya', 'Gel! karanlık basmadan gece sökmeden gel Karanlığı aydınlatan nurunu saçarak gel Ellerim semada diz çökmüş bekliyorum seni Duymak istiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hilal']::text[], 8.5, '{"poet":"Şair Hilal","poet_slug":"sair-hilal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/resulullah-a-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bilmek İsterim', 'seni-bilmek-i-sterim-yavuz-bayram-caliskan-0cecz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Su, sende duru, baksan bir peri,

Ay, bir adım arkasında kalır geri,

Işığıyla sevda busesinde aydınlanır dünya,

Şarap şişesinde demlenir, 

Sevilmelerde beklenir,

Bir can yüreklerde.

Narinliğinden dallar eğilir,

İğdeler sevda kokar,

Ne yapsam, ne etsem,

Seni bilmek isterim.

Ankara saçlarına sevdalı,

Birde engin gözlerine,

Duruşunda bahar saklı,

İçinde dinmeyen elemler.

Dağıt saçlarını bir tel ver.

Kelebeklerin arasında gezer,

Çiğdemler gelişini sezer,

Yaşam aşk''la uzar

Aşkın tarihini o yazar,

Ne kalemi, ne özleri,

Sadece gözleri. 

Sevginin öpüşünü bilendir, 

Canı ile sevdaya gelendir,

Hasreti özlemi nefes bilendir,

Sevdiğimdir, gözleriyle gülendir.

İnceliğinde savrulur baharlara,

Gözlerimde dökülür yağmurlara,

Nakışlarımla sevdaya, umutlara,

Aşk beklediğim andır,

Ömrümle yaşayacağım candır.

Tutup elinden gonca gülleri,

Konuşsa ben diyen dilleri,

Yarınlara uzanıp elleri,

Seni ben gibi bilmek isterim.', 'Su, sende duru, baksan bir peri, Ay, bir adım arkasında kalır geri, Işığıyla sevda busesinde aydınlanır dünya, Şarap şişesinde demlenir,  Se...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-bilmek-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-umit-tuna-sabgn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum ulan seni,

Yağan her kar tanesi hatırlatıyor bana seni,

Özledim galiba ben seni,

Yok yok ben kesin seviyorum seni.

Her taraf bembeyaz kar,

Sende özledin mi beni yar,

Ben seni çok özledim,

Saatlerce kapında bekledim.

Uludağ’ın etekleri kar,

Yüreğimde hala yangın var,

Kalbimde hala ismin var,

Gözlerim her gece usanmadan ağlar,

Dön geri yar.

Yağan kar hatırına,

Bembeyaz düşlerim adına,

Son bir kez daha dön bana,

Seni unutmadım,

Sende beni unutma! ...

ÇILGIN MUHASEBECİ', 'Seviyorum ulan seni, Yağan her kar tanesi hatırlatıyor bana seni, Özledim galiba ben seni, Yok yok ben kesin seviyorum seni. Her taraf bembe...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kar-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler', 'cicekler-kagizmanli-hifzi-bpcn7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gene al yeşile boyandı zemin

Nakışlandı bin elvana çiçekler

Kalbim irşad oldu gönlüm sevindi

Bir can bağışladı cana çiçekler

Yeşillenir budaklanır allanır

Yüzbin renkte noktalanır hallanır

Kimi yeşillenir kimi allanır

Kimi batmış kızıl kane çiçekler

Seher ağladı rahmet elendi 

Güzel gözlerinde yaş danelendi

Öğle güneşinde fervahelelendi

Az kaldı eşkimden yane çiçekler

Bağrımdaki hançer midir ok mudur? 

Benim derdim çiçeklerden çok mudur? 

İlahi bunların derdi yok mudur? 

Bilmem neden güler bu divane çiçekler? 

Saf tutmuş namaza kıyam ediyor

Yel estikçe secdesine gidiyor 

Susandıkça ab-ı rahmet yuduyor

Gözün dikmiş ol asmane çiçekler

Ruhum kızıl günden kokusun alsa 

Gam değil tikeni sinemi delse

Ne zaman sevdiğim seyrana gelse

Selam söylem o canane çiçekler

Misafirem gölgenizde kalayım 

Bir tek yaprağına kurban olayım

Kızmasan koparıp satın alayım

Ne veriyim bu gülşene çiçekler

Şeyda bülbül gül yolunda terliyor

Naşı nadan goncasını harlıyor

Karşımızda yıldız gibi parlıyor

Beni kırdı bir pervane çiçerkler

Kibreden kafirin imanı iter 

Bu alçak toprakta gör neler biter

Bulur kerameti irşade yeter 

Agah olsa bir lisane çiçekler

Akan derelerin duru suları

O da deli olmuş çeker huları

Yel ile geliyor hoş kokuları 

Cennetten bir nişane çiçekler

Seherde açmağa evdi tezlendi

Gezindi güller otlar izlendi 

Hava bulutlandı güneş gizlendi 

Yakışır mı bu dumane çiçekler 

Kimi açmış kimi tomurcuk olmuş 

Kiminin derdi var sararmış solmuş 

Kimi sergerdan boynu burulmuş 

Kimi dönmüş yay kemane çiçekler 

Kimiler sıcaktan bezmiş soyunmuş 

Kimiler gölgede saralmış sinmiş 

Kimiler eynine elvan giyinmiş 

Hoş geldiniz bu seyrane çiçekler 

Hayretten sarhoş olmuş bayılmış

Yanağına çise düşmüş ayılmış 

Gökteki yıldızlar yere yayılmış 

Ziynet vermiş bu cihane çiçekler 

Kimiler piyale billoru fül fül 

Ne güzel yakışır susane sümbül 

Kimisi ağarmış kimi kızıl gül 

Kimi benzer mor reyhane çiçekler 

Aşık maşuk misli dolaşır 

Kimler pehlivan olmuş güleşir 

Akar sudan her birisi paylaşır 

Minnet eyler bağbane çiçekler 

Bu da yaza çıkmış nasıl kıyayım 

Ruhum koymaz döşüreyim dereyim 

Götürüp desteden yare vereyim 

Hangisi ki nazikane çiçekler

Aşk nedir bilmeyen çiçeye ne der

Çiçeyin kokusu canane gider 

Durmaz gece gündüz ağlar zikreder 

İnanmıştır ol Rahmane çiçekler 

Çiçek ağlar naşilerin destinde 

Ölüm haktır civan canın kasdinde 

Dostum gelsin mezarımın üstünde

Yaran yoldaş beni sana çiçekler 

Ben HIFZI''yım sular gibi çağlarım 

Aşk oduna yüreğimi dağlarım 

Dahi bundan böyle durmaz ağlarım 

Taki göz yaşımdan kane çiçekler', 'Gene al yeşile boyandı zemin Nakışlandı bin elvana çiçekler Kalbim irşad oldu gönlüm sevindi Bir can bağışladı cana çiçekler Yeşillenir buda...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/cicekler-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünya', 'bu-dunya-kagizmanli-hifzi-1wbz7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinleyin ağalar tarif edeyim

Fani değimlidir yani bu dünya

Bir kapısız hane kimseler bilmez

Gün be gün artırır şanı bu dünya

Adem Havva evvel dadına yetti

Nice yüzyıl anlar ömür sarfetti

Encamı anlarda dünyadan gitti

Havva''dan ayırdı anı bu dünya

Adem Havva buna şaşıben kaldı

Bak iki kardaşa ne fitne saldı

Habil''in muradın elinden aldı

Kabil''e ettirdi kanı bu dünya

Kabil''i mest edip attı bir taşı

O taşa rast geldi Habil''in başı

Habil koydu gitti kavim kardaşı

Ondan bilindiki fani bu dünya

Adem Peygamber''den Nuh''a varınca

İnsanlar kaynadı misli karınca

Abadı hoş görür kendi karınca

Harap etti o mekanı bu dünya

Orda gitti insanların hayası

Nuh''a bakmadılar oldular asi

Suya gark eyledi o kadar nası

Anda oldu Nuh Tufanı bu dünya

Hep su aldı kara yerin yüzünü

Deresini tepesini düzünü

Kimisinin hak kurtardı özünü

Andan artıp oldu sani bu dünya

Bu dünyaya gelen elbette gider

Hanidir yüz yirmi dört bin peygamber

Hani Şah-ı Alem Sahib-i Mimber

Netti o Şah-ı Cihan''ı bu dünya

İnanma dünyaya uyandır dili

Hani Hak arslanı o gerçek veli

Sahibi Zülfükar Hazreti Ali

Nitti o Şah-ı Merdan''ı bu dünya

Hani nitti nida eden Bilal''ı

Hani Peygamberin dokuz helali

Hazreti Fatıma kaşı hilali

Nitti o Mah-ı tabanı bu dünya

Bu dünyadan asla vefa ummu sen

İnanma ki kimse kala sağ esen

Hazreti Hüseyin Hazreti Hasan

Nitti ol iki civanı bu dünya

Her kimi sorarsan toprakta ara

Nicesi yüzünü vermiştir yara

Çaresiz ölüme bulmuştu çare

Acep nitti o Lokman''ı bu dünya

Bir nazar et yalancı meydana bak

Cennet yapan şeddad-ı şeytana bak

Kaftan kafa hükmeden sultana bak

Yemedi mi Süleyman''ı bu dünya

Kimi yağa bala indirmez başı

Kimisine vermez doyunca aşı

Kimisi beğenmez kutnu kumaşı

Kimine vermez keteni bu dünya

Bu dünya fanidir kalmaz selamet

Bir gün kıyametten gelir alamet

Teccal çıkar dünya olur melamet

Gösterir ahır zamanı bu dünya

İsa iner teccallarla cenk eder

Bu cihanı teccallara teng eder

Tevahu fitnesi aradan gider

Kırk yıl İsa''nın mihmanı bu dünya

İsa gidip dünya halı kalınca

Cümle alem ayşınuşa dalınca

Emredip İsrafil suru çalınca

Dağıtır taht-ı divanı bu dünya

İsrafil bir kere surunu vurdu

Künfe yükün emri aleme erdi

Nice yüzyıl bir insanı gördü

Ne bir kuşu ne insanı bu dünya

O zamanda alam giyer hep kara

Kalmaz al üstünde bir kitap kara

Ay gün her taraftan olur kapkara

Harap görür asumanı bu dünya

Hak-taala evrakları saçanda

Herkes cihed bulup gözün açanda

HIFZI der ki biz mahşere göçende

Orda teslim eder canı bu dünya', 'Dinleyin ağalar tarif edeyim Fani değimlidir yani bu dünya Bir kapısız hane kimseler bilmez Gün be gün artırır şanı bu dünya Adem Havva evve...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bu-dunya-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-ayse-kok-opfy4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir deli rüzgardın o çocuk yüreğimde

        Önce serinlik verdin sonra bitmez işkence

        Boğuldu ümitlerim ayrılığın denizinde

        Yıktın bütün hayelleri bir çığ gibi üstüme

        Ve bana bırakarak onulmaz hasarları 

         Çekip gittin habersiz karartıp sabahları

         Yokluğun bir mey olup dolarken kadehlere 

          İçmek yine bana düştü o zehir akşamları

          Gecelerde gidişinin sancılı kıvranışı

          Can çekişir gözümde o günlerin anıları

          Ve içime yağarken sessiz hüzün yağmurları

          Ben yalnız yaşarım bitmek bilmez figanları

          Aşkının tek armağanı gözlerimin damlası

          Sensiz bende yaşıyor sevgimizin hatırası

          Umudumun kanadı kırık düşleyemem yarını

          Artık hiçbir sevda durdurmaz kalp ağrımı', 'Bir deli rüzgardın o çocuk yüreğimde         Önce serinlik verdin sonra bitmez işkence         Boğuldu ümitlerim ayrılığın denizinde        ...', ARRAY['Türk Edebiyatı','Şiir','Ayse Kök']::text[], 8.5, '{"poet":"Ayse Kök","poet_slug":"ayse-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vefasiz-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-kagizmanli-hifzi-tchmm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Serim sevdalanıp aşka düşeli 

Möhnet kesesinden bir pare gönül 

Sever bir gül gibi mahbubesini 

Düşer bülbül gibi bizare gönül 

Oturur kapıda hem kürşad olur 

Cahi cehaletten kah irşad olur 

Gahi çiçek misli şad olur 

Gahi gam gün ağlar biçare gönül 

Gahi viraneye benzer birç ağı 

Kış olur kar yağar dumandır dağı 

Gahi baradüşer bahçesi bağı 

Benzer bir zamanda bahara gönül 

Bu derd-i fenadan murada yetmez 

Muhabbet yanımdan uzağa gitmez 

Asla sevdiğinden feragah etmez 

Mansuri tek emiralsa bir dare gönül 

Gahi yücelerden esen yel olur 

Gahi sular ile akan sel olur 

Gahi örümcekten ince tel olur 

Resesinden kırılır mudara gönül

Gahi hikmet dolar gahi boş gibi 

Gahi meyhor olur bir sarhoş gibi 

Gahi katlanır uçar kuş gibi 

Gah yolda yorulur avare gönül 

Gahi bülbül gibi öter dillenir 

Gahi elvan çiçek açar güllenir 

Gahi yeşillenir gahi allanır 

Gah ta birer tektir gapgara gönül 

Gahi neşve bilmez gahi yücedir 

Gahi bezirgandır gahi hocadır 

Gahi zulumat karanlık gecedir 

Gah ta nur verir rihare gönül 

HIFZI''yım yanarım tütünüm çıkar 

Gahi ateş olar cismimi yakar 

Coşkun çaylar gibi çalkanıp akar 

Akibet yetişti dildare gönül', 'Serim sevdalanıp aşka düşeli  Möhnet kesesinden bir pare gönül  Sever bir gül gibi mahbubesini  Düşer bülbül gibi bizare gönül  Oturur kapıd...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gonul-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadar', 'kadar-kagizmanli-hifzi-157r7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ah ü zarımı kimler dinlesin

Bu canım canane katana kadar

Yatıp bir yastıkta yarinen helbet

Salıp canı cana katana kadar

Göksü bostan olmuş bitmiş şememe

Yüzbin şememeye değer bir meme

Hasta gönül ister memeden eme 

Al kanı damardan alana kadar

Hudam kıl müyesser murat alayım 

Leyl ü nahar dost köyünden kalayım

Canan ile can sohbeti kılayım

Her gece horozlar ötene kadar

Silse göz yaşımı baksa yüzüme

Hab-ı gaflet haram olsun gözüme

Körpe kuzu kimin alsam dizime 

Disem nenni nenni yatana kadar

Köşe-i zindanda dostun eline

Kailem berdara zülfün teline 

HIFZI''yım gözüm yok dünya malına 

Olsa gün doğandan batana kadar', 'Bu ah ü zarımı kimler dinlesin Bu canım canane katana kadar Yatıp bir yastıkta yarinen helbet Salıp canı cana katana kadar Göksü bostan olmu...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-kagizmanli-hifzi-9ec6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne lazımdır sürmelenmek bezenmek 

Ezelden halk etmiş Hüdai güzel 

Tek nazarda gönül getdi gelmedi 

Gönderdi ser''ime sevdayı güzel 

Peri misli güzellikde berkemal 

Onu seven bu dünyada neyler mal 

Nakşı pencereden gösterdi cemal 

Benzer havlet olmuş sevdası gözel 

HIFZI derki bahar geldi bu bağa 

Çıkar gül döşürür düzer tabağa 

Olmuş tülek terlan gelmez duzağa 

Sekişi hoş keklik hudası gözel', 'Ne lazımdır sürmelenmek bezenmek  Ezelden halk etmiş Hüdai güzel  Tek nazarda gönül getdi gelmedi  Gönderdi ser''ime sevdayı güzel  Peri misl...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzelleme-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-hana-dukacinac-tc6ar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman aktı, yaralar kapandı

Bir zamanlar varlığım teslimken sana

Şimdi özgürlüğüm sana karşı durmakta

Hele bir gel yeniden

Hele bir ağla gidenlere

Artık ne bu mavi gözler aynı mavilikte

Nede bu gülen yüz aynı samimilikte

Gözlerim pırıltısız,yüreğim soğuk

Uzak kaldık...

Artık ne km''lerin hesabı var nede görüşebileceğimiz günlerin özlemi....

Sevgide son şansı sana vermiştim.

Ruhum aramıyor sevgiyi 

Sona geldi azalan duygularım

senin için görülen rüyalarım,kurulan hayallerim

Bıraktım seni bıraktım kendimi

Bitiverdi ansızın Herşey...', 'Zaman aktı, yaralar kapandı Bir zamanlar varlığım teslimken sana Şimdi özgürlüğüm sana karşı durmakta Hele bir gel yeniden Hele bir ağla gid...', ARRAY['Türk Edebiyatı','Şiir','Hana Dukacinaç']::text[], 8.5, '{"poet":"Hana Dukacinaç","poet_slug":"hana-dukacinac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bitti-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine', 'kendine-kagizmanli-hifzi-imh79', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyan ey gözlerim hab-ı gafletden 

Alem ruşen oldu vakt-i şafaktır 

Günde yüzbin katar gelüben geçer 

Faniden bakiye geçmesi haktır 

Ömrüm bir bahardır cismin bir yaprak 

Birgün gazel olur döker zel firak 

Ayağım altında basdığım toprak

Akibet serimden üst olacaktır

HIFZI çok salınma,kaddin eğersin

Felek koymaz dal budağın göğersin

Gönül yucalanma kabre değersin

Bir avuç toprakdır yerin alçakdır.', 'Uyan ey gözlerim hab-ı gafletden  Alem ruşen oldu vakt-i şafaktır  Günde yüzbin katar gelüben geçer  Faniden bakiye geçmesi haktır  Ömrüm bi...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair-i Niyaz', 'sair-i-niyaz-mehmet-sukru-bas-qiif7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niyazi Yıldırım Gençosmanoğlu''na..

                                      Ölüm Allah''ın emri, kifayeti farz

                                      Lakin sen ölmedin ey Şair-i Niyaz.

                                      Manas''tan beri hakk için yollardasın,

                                      Vardın menziline şu anda Ağın''dasın.

                                      Dönüpte bir bak şu insan akınına,

                                      Kim böyle koşar evladı yakınına.

                                      Demek ki sen gönüller doruğundasın,

                                      Vardın menziline şu anda Ağın''dasın.

                                      Selam sana bin kere ey Şair-i Niyaz,

                                      Kaç bin gönüldesin, dönüver de bak biraz.

                                      Sen gönüllerde kurulan otağındasın,

                                      Vardın menziline şu anda Ağın''dasın.

                                                            ******

                                      Günışığı Gazetesi 20 Ağustos 2005', 'Niyazi Yıldırım Gençosmanoğlu''na..                                       Ölüm Allah''ın emri, kifayeti farz                                  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sair-i-niyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşer Mi', 'duser-mi-kagizmanli-hifzi-i9hdl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yarki bir yarı sevse

Varıp ağyara düşer mi

Cefakeş bülbül-i şeyda

Gonca gül hara düşer mi? 

Bulunca gamı kayguyu 

Yitirdim şirin uykuyu

Kestik can bağından suyu 

Bahçemiz bara düşer mi? 

Mecnun misli hasret kalan 

Kerem gibi olur talan 

Garip teki murad alan

Ah edip zara düşer mi? 

Aşkın badesi dolmasa

İçen sararıp solmasa 

Yar candan serin almasa

Pervane nara düşer mi? 

Her sevda serime konmaz

Aşkım cehennemdir sönmez

Ben dönsemde gönül dönmez

Dönmek dindara düşer mi? 

Ben çekeyim cevr ü cefa

Senin olsun zevk ü sefa

Hani ahdin ey bivefa

Bu kar dildara düşer mi? 

Gel zulmünden eyle hazer 

Hey muhanned kıl bir nazar

Her kes al giyinmiş gezer

HIFZI''ya kara düşer mi?', 'Bir yarki bir yarı sevse Varıp ağyara düşer mi Cefakeş bülbül-i şeyda Gonca gül hara düşer mi?  Bulunca gamı kayguyu  Yitirdim şirin uykuyu ...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/duser-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar çiçeği', 'kar-cicegi-kagizmanli-hifzi-9c5zh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onudur Şehr-i Şubatın

Şükür bitmiş kar çiçeği

Nişandır müjdeye gelmiş

Ezel-yaz, bahar çiçeği

Esir olur kar altında 

Hapsolur yerler katında

Azad olur saatında

Her bir günün var çiçeği

Kar kaldı dağlar payında 

Sular çağlanır çayında 

Açılır abrel ayında

Ağaçlarda bar çiçeği', 'Onudur Şehr-i Şubatın Şükür bitmiş kar çiçeği Nişandır müjdeye gelmiş Ezel-yaz, bahar çiçeği Esir olur kar altında  Hapsolur yerler katında ...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kar-cicegi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin...', 'sen-gittin-eren-caglar-niron-g3laj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gittin

umudum müebbet olana dek bekledim

kargalar etimden et koparırken

maskesi düşmüş bir korkuluk gibiydim

acımı hasretime sürttüm

körelen mutluluğum oldu

Sen gittin; 

ben şiirler yazdım

dostlarla takıldım

insan içine çıktım bol bol

istemiye istemiye tanıştım güzellerle

aşık bir hayvandan

sosyal bir hayvana dönüştüm 

Sen gittin 

kendimle baş başalıktan kaçar oldum

ama inatlaşıp yakalattım kendimi

bile bile yalnızlığıma

Sen gittin

yarım kaldı

soframızda sevda

tenimde tuzun

eksik kaldı

razı olmadı yürek

senden başkasına

aslında artık sana da

Sen gittin

şaka gibi geldi gidişin bir anda

ama en sonunda yalan gibi geldi

her şeyin bana

Sen gittin

korktuğun için

ve

yenilmekten bıktığın için

ve

gücün yetmediği için

sen gittin

bir de baktın ki

ben zaten

oradan çoktan çok uzakta...

Eren Caglar Niron

2003

Ankara', 'Sen gittin umudum müebbet olana dek bekledim kargalar etimden et koparırken maskesi düşmüş bir korkuluk gibiydim acımı hasretime sürttüm kör...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-gittin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-kagizmanli-hifzi-1tyza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlama gözlerim mevla kerimdir 

Her daim rüzigar böylede kalmaz 

Dermansız dert olmaz sabreyle gönül

Geçer bu ah ü zar böyle de kalmaz 

Adem Sefiyullah yedi buğdayı 

Kıldı ihtiyarsız N ehi Hudayı

Bilirdi affeder bayi gedayı

Afeder ol Digar böyle de kalmaz

Ferman Hudanındır emrolsa ondan 

Nuh-u Nebiyullah çıkar Tufan''dan 

Açılır deryanın yolu bir yandan

Görünür bir kenar böyle de kalmaz

Ne kadar çok olsa dağların karı 

Eridir Hudanın hoş bulutları

Yetişir bağların ayvası narı

Açılır nev-bahar böyle de kalmaz

Yandı nar içinde İbrahim Halil

Tevekkül dalını yandırdı zelil

Ateşi gülüstan eyledi Celil

Gördüler sönmede nar böyle kalmaz

Eyup gibi çeken varmış cefayı

Cefayı çekmiyen bulmaz sefayı

Bir derde akibet binbir şifayı

Verir Perverdigar böyle de kalmaz

Ne ise Haktandır Gal ü Beladan 

Lokman haber verdi arş ü aladan

Gel HIFZI gümanın kesme Mevaldan

Bu çark-ı bergarar böylede kalmaz.', 'Ağlama gözlerim mevla kerimdir  Her daim rüzigar böylede kalmaz  Dermansız dert olmaz sabreyle gönül Geçer bu ah ü zar böyle de kalmaz  Adem...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umut-262-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-mehmet-sukru-bas-laos9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gecenin zifiri karanlığında,

                                            Dalmışım hayaline, seni düşünüyorum.

                                            Senden çok uzakta, ama seninleyim,

                                            Seninle el ele, seninle göz gözeyim.', 'Bu gecenin zifiri karanlığında,                                             Dalmışım hayaline, seni düşünüyorum.                            ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-dusunuyorum-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Yar', 'yar-yar-kagizmanli-hifzi-usd7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aç o gönül gözünü

Bak çıbanıma yar yar

Dün ü gün vird olupdur

Bu zebanıma: yar yar

Bu sevda sere indi

Akan ciğere indi

Göz yaşım yere indi

Ter tabanıma yar yar

Bir yarın desdindeyim

Zülfünün kasdindeyim

Ben murad üstündeyim

Kıyma canıma yar yar

Yüreğim ocak oldu

Ocakdan sıcak oldu

Burçlara bucak oldu

Bak dübanıma yar yar

Aşkın aduna düşdüm

Ateşten dona düşdüm

Dediğin güne düşdüm

Gel seyranıma yar yar

Ben beni bilmem neyim

Dil bilmez divaneyim

Şem''ine pervaneyim

Gir devranıma yar yar

Seslerim yane yane

Ne mümkün yar uyana 

Bağrım boyandı kane 

Gel hicranım yar yar.', 'Aç o gönül gözünü Bak çıbanıma yar yar Dün ü gün vird olupdur Bu zebanıma: yar yar Bu sevda sere indi Akan ciğere indi Göz yaşım yere indi T...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yar-yar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-kagizmanli-hifzi-mmsl6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zulümden münezzeh adil padişah

Ey şahların şahı sana sığındım

Kulunam kapında kurbana geldim

Beklerem dergahı sana sığındım

Çok demdir çekerim aşk ile sevda

Oldum hasretinden bülbül-i şeyda

Sen sakla gülümü har oldu peyda

Elaman İlahi sana sığındım

Yedi yıldır hasretini çekerim

Menevşe misali boynum bükerim

Görmedi gözümden kan yaş dökerim

Çeküben bir ahı sana sığındım

Maşuk şirin sudur aşık balıkdır

ne kadar nuş etse bağrı yanıkdır

Ah bu nasıl seldir ne bulanıkdır

Huda, ben birmahi sana sığındım

HIFZI hayran oldu aşkın yasına

Ne kendine malik ne dünyasına

Daldı sefinesi gam deryasına 

Yunus''un Allah''ı sana sığındım.', 'Zulümden münezzeh adil padişah Ey şahların şahı sana sığındım Kulunam kapında kurbana geldim Beklerem dergahı sana sığındım Çok demdir çeker...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakaris-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasırga', 'kasirga-mehmet-sukru-bas-3l5va', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kasırgadır eser başımda,

Günümü gecemi belirsiz eder.

Bir şeyler yapmaya çalışır iken,

Eser bir kasırga yerle bir eder.', 'Bir kasırgadır eser başımda, Günümü gecemi belirsiz eder. Bir şeyler yapmaya çalışır iken, Eser bir kasırga yerle bir eder....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kasirga-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara', 'bahara-kagizmanli-hifzi-f1vlu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bölük durnalar müjde getirdi

Bugün ezel, bahar yaz eyyamıdır

''Hu''çeker ötüşür sevdalı kuşlar 

Möhübbet safası saz eyyamıdır

Ne hoş hayelendi çimenli çöller 

Ne serhoş esiyor bu şirin yeller

Durmaz dalgalanır sonalı göller

Ötüşür ördeği kaz eyyamıdır

Al yeşil giyindi dumanlı dağlar

Olur şad-ı revan çimenli çağlar

Seyreyle sevdiğim seyrangah bağlar

Sallan kanlı zalım naz eyyamıdır

Eski sözdür:''arsız gülegen olur''

HIFZI gibi dertli söylegen olur 

Her başa bir bela gelegen olur 

Durma dertli diller söz eyyamıdır.', 'Bir bölük durnalar müjde getirdi Bugün ezel, bahar yaz eyyamıdır ''Hu''çeker ötüşür sevdalı kuşlar  Möhübbet safası saz eyyamıdır Ne hoş hayel...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör..', 'kor-bahri-kayaoglu-nntn3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çirkindi, korkunçtu, sıcaktı

Gözleri çapak çapaktı..

Baktı,

Uzak yerlere uzak yerlere..

Gönlüm açılde kedere

Ne dağ gördü o, ne dere..', 'Çirkindi, korkunçtu, sıcaktı Gözleri çapak çapaktı.. Baktı, Uzak yerlere uzak yerlere.. Gönlüm açılde kedere Ne dağ gördü o, ne dere.....', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kor-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ayse-kok-obddf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensin  tüm çaresizliğimle 

     Ardımda bıraktığım 

     Yada bensiz geleceğe saldığım

     Sensin yıllara haykırdığım

  

     Sen içimde kanayan yaralarım

     Sen kaderimde yer bulamadığım

     Ve sen yüreğimde isyanlarım

     Sen uzak yıldızımsın her gece baktığım

     Sen hayatımsın hiç yaşayamadığım

     Sen anılarda sakladığım 

     Sen tanrıya dualarım

,    Ve sen anlatılmaz duygularım

     Sensin gördüğüm hüznün fotoğrafında

     Dans eder hatıralar çılgın yalnızlığımda

     Vurulur zincirlere senli düşlerim

      Bir şarkısın içimde dinleyemediğim

      Sen kahramanısın o bitmez efsanenin

      Şimdi duayenisin bensiz bir hikayenin

      Artık deli selisin şu mahzun gözlerimin

      Sen mutluluk resmimsin hiç göremediğim', 'Sensin  tüm çaresizliğimle       Ardımda bıraktığım       Yada bensiz geleceğe saldığım      Sensin yıllara haykırdığım         Sen içimde k...', ARRAY['Türk Edebiyatı','Şiir','Ayse Kök']::text[], 8.5, '{"poet":"Ayse Kök","poet_slug":"ayse-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-780-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Özlemi', 'vatan-ozlemi-kagizmanli-hifzi-b3z03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül, gurbet elde hacılık nedir? 

Sılayı rahmeyle vatan varimiş.

Heman Mekke''de mi varmış Beytullah? 

Her kande ararsan hem-civar imiş? 

Yaktıkça firkate pervane, gönül

Düşer bülbülgibi şivane gönül

Sanardım usanmış divane gönül

Meğer eğlencesi nazlı yar imiş

HIFZI der nideyim görünmez bağlar

Geçti aramıza dumanlı dağlar

Sılada sevdiğim dolukmuş ağlar

Vatandan ayrılmak çetin kar imiş', 'Gönül, gurbet elde hacılık nedir?  Sılayı rahmeyle vatan varimiş. Heman Mekke''de mi varmış Beytullah?  Her kande ararsan hem-civar imiş?  Ya...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vatan-ozlemi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Yar-2', 'yar-yar-2-kagizmanli-hifzi-iviuc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece gündüz zikrim fikrim hayalim 

Oluptur dilimde süftü gu yar yar

Azalarım dile geldi söyledi 

Ta baştan ayağa der kamu yar yar 

Agahtır ahımdan hefti felekler 

Cümle şahit oldu göğde melekler 

Kadir mevlam budur senden dilekler 

Ateş-iaşkıma yansın o yar yar

Ey Piri penahım gel imdadıma 

Eller agah olmaz bu feryadıma 

Hasreti firkati düştü yadıma 

Ogüzel gözleri bir ahu yar yar

Günbegün ateşim düştü nirana 

Ağlarım gözyaşım oldu revana 

Ruhum baykuş oldu kafe sverana 

Derun-i dilimden çeker Hu yar yar

Can canane canan cane yaraşık 

Etme aklım zülfün gibi dolaşık 

Ayrılsa maşuktan emektar aşık 

Büyük zulüm değil, nedir bu yar yar? 

HIFZI''yım Kerem''den şen mi sanarsın? 

Yanarım billahi sen de yanarsın 

Yaklaşma sevdiğim sende yanarsın 

Uzaktan ser''ime serp bir su yar yar.', 'Gece gündüz zikrim fikrim hayalim  Oluptur dilimde süftü gu yar yar Azalarım dile geldi söyledi  Ta baştan ayağa der kamu yar yar  Agahtır a...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yar-yar-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-mehmet-sukru-bas-y5iqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şairlik akıl kârı değil,

                                     El âlem yar kucağında.

                                     Ben bir cümle peşindeyim,

                                     Hele bulursam dörtlü bir mısra,

                                     Ok gibi fırlıyorum,

                                     Deli miyim ben neyim?', 'Bu şairlik akıl kârı değil,                                      El âlem yar kucağında.                                      Ben bir cümle p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sair-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulak Başında Sevgiliye', 'bulak-basinda-sevgiliye-kagizmanli-hifzi-xk6qd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldiğin izlere kurban 

Dediğin sözlere kurban 

Sürmeli gözlere kurban 

Kaşı kemanım merhaba 

Nice bir tabibe varam 

Tazelendi eski yaram 

Gel efendim benim çarem 

Derde dermanım merhaba

HIFZI ''yım gönlüm sendedir 

Bilmem sana layık nedir 

Gönlüm sana hedayadır 

Götür sultanım merhaba', 'Geldiğin izlere kurban  Dediğin sözlere kurban  Sürmeli gözlere kurban  Kaşı kemanım merhaba  Nice bir tabibe varam  Tazelendi eski yaram  G...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulak-basinda-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretten Umuda', 'hasretten-umuda-utku-demir-5x5at', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece sabaha uzanırken

Ruhum dolaşır boş duvarlarda,

Ayın gözlerinden düşen hayaller

Bir garip ses yaratır gökyüzünde

Hasretliğinden delice koşan 

Aniden ayın ışığı söner

Sesin ihtişamlı titreşimi

Ağlayan ayı beşikte sallarken

Yıldızlar sırtını döner 

Kıskanç ve küsgün

Kayan korkak meteor

Dona kalır etkisinde

Sesin kollarında umut çağrısı

Hayret dolu bakışlarda

Kararsız çağrının rengarenk şekli

Çizilir alaca karanlığa

Ay da hayran,yıldızlar da

Bu göz alıcı tabloya

Tam ortasında bir çift dudak

Batmamak üzere güneş doğuracak

Hepsi birlikte,hasretten umuda 

Gelen sesi selamlayacak...', 'Gece sabaha uzanırken Ruhum dolaşır boş duvarlarda, Ayın gözlerinden düşen hayaller Bir garip ses yaratır gökyüzünde Hasretliğinden delice k...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hasretten-umuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlara', 'kuslara-kagizmanli-hifzi-8kn5q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uçan kuşlar siz Mevlayı seversez

Selam söylen o cananı görestim

Gönülden hatrıma düştü hayali

Şirin can içinde canı görestim

Serimde dumanım tenimde narım

Söylemek temsilim ağlamak karım

Arttı bülbül gibi feryadım zarım

Lebi gonca o gül-hanı görestim

Hanıdır maralım dumanlı dağlar? 

Derunum ah çeker gözlerim ağlar

Hanı dudu gumrum balalı dağlar? 

Boyu selvi dal fidanı görestim

Göğe çıkmış soran daş ile dağı

Açanda çiçekler yaz bahar çağı

Bile gezdiğimiz bahçeyi bağı

Geçen günde her zamanı görestim

HIFZI''yım çeşminden şebnem alındı

Esti bad-ı saba gam tazelendi

Şimdi sırma teller yelpazelendi

Gene zülf-i perişanı görestim', 'Uçan kuşlar siz Mevlayı seversez Selam söylen o cananı görestim Gönülden hatrıma düştü hayali Şirin can içinde canı görestim Serimde dumanım...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuslara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-kagizmanli-hifzi-6gt35', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni sevdiğimden eden 

Sevdiğinden ayrılasın

Can canandan ayrılır mı

İki gözden kör olasın 

Bizi bilmez idi eller

Çürüsün o diyen diller 

Nazlı yara vuran eller 

Bileklerden kırılsın 

Yaralı yorgun maralım 

Allah''a ayandır halım 

Bana zulum eden zalım 

Yüreğinden vurulasın 

Kurşunların kuşa değe 

Ettikleri başa gele

Ayakların taşa değe 

Topraklara sarılasın

Mazlum HIFZI baktı fala 

Çifte yarin eller ala 

Cemdeğin kuşlara kala

İki kıçtan kırılasın', 'Beni sevdiğimden eden  Sevdiğinden ayrılasın Can canandan ayrılır mı İki gözden kör olasın  Bizi bilmez idi eller Çürüsün o diyen diller  Na...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beddua-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-kagizmanli-hifzi-dvp5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey pir-i penahım bir himmet eyle 

Duta gör elimi yaman günüdür 

Bugün korkuludur hasta vücudum

Varayım tabibe duman günüdür.

Halimi sorarsan hele ver nefes 

İnanın yanıyor verane kafes 

Ya gel al canımı ya ağrımı kes 

Ya da ver dermanın yaman günüdür.

Koşa gözlerim dahi yollara nazır 

Kır atlı kadimim hazır ol hazır

Yetiş imdadıma hazret-i Hızır 

Bu garip serimin duman günüdür.

Nice bir kalkayım yoktur idare 

Ayaklar altında kaldım biçare 

Meydanın içinde çektiler dare 

Yetiş Şah-ı merdan seyran günüdür.

Ah yardan ümidi kestim de geldim 

Vurduğum leşkeri küstüm de geldim 

Elimi üstüne bastım da geldim 

Yarama melhem kıl güman günüdür

Ben sana sığındım ey bari Hüda 

Aşığı maşuktan eyleme cüda 

Kulundur cümle bay ile geda 

Yusuf''un emrahı şivan günüdür.

Der HIFZI sığındım sana ey Ali Paşa 

Zerrece zulümün yoktur haşa bin haşa

Şevketli şahım gel et temaşa 

Bugün rihalimin duman günüdür.', 'Ey pir-i penahım bir himmet eyle  Duta gör elimi yaman günüdür  Bugün korkuludur hasta vücudum Varayım tabibe duman günüdür. Halimi sorarsan...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalvaris-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt', 'kurt-mehmet-sukru-bas-gt1r9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca dert içinde ayık gezer mi insan? 

Can mı dayanır böyle çile çekmeye? 

Yıllarca içimi kemiren bir kurt,

Hala doymadı kanım içmeye.', 'Bunca dert içinde ayık gezer mi insan?  Can mı dayanır böyle çile çekmeye?  Yıllarca içimi kemiren bir kurt, Hala doymadı kanım içmeye....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kurt-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar Gibi', 'hatirlar-gibi-gokhan-ugur-wsbfa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimin iki atışının arasında ihmal ediyorum seni,

Fakat her atışında hissediyorum,

Yokluğun hatırlatıyor bana seni,

Ama sen

Ne zaman yalnız bir kaldırım,

Gökyüzünün toprakla birleşmesiyle sonsuzlaşan bir ufuk,

Kendini bile ışıtmayan takati kalmamış

Yaralı bir sokak lambası görürsen

Beni hatırla..

13 Kasım 2001

19:10

Düzce', 'Kalbimin iki atışının arasında ihmal ediyorum seni, Fakat her atışında hissediyorum, Yokluğun hatırlatıyor bana seni, Ama sen Ne zaman yalnı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Uğur']::text[], 8.5, '{"poet":"Gökhan Uğur","poet_slug":"gokhan-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatirlar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertli Firkatli Hasretli', 'dertli-firkatli-hasretli-kagizmanli-hifzi-bnaxo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertli firkatli hasretli

Na''ralar ishak kuşları

Nedir suçum yüz bin yerden

Yaralar ishak kuşları

Ağladım eyledim seyri

İstedim ilacı hayrı

Demez ağlamaktan gayri

Çareler ishak kuşları

Her yandan gelir ah u zar

Çağrışır hezar sad hezar

Her ötüşte bin dert yazar

Karalar ishak kuşları

Öter men''olur dadıma

Ol dem yar düşer yadıma

Bir ah çeksem feryadıma

Varalar ishak kuşları

Öter her bağda niceler

Sanki ders almış heceler

Uzan mübarek geceler

Ereler ishak kuşları

Kimi ağlar kimi inler

Eder tekrar yüzler binler

Biri okur biri dinler

Sıralar ishak kuşları

Ötme ishak kuşu ötme

Garip gönlüm viran etme

Gitme yaz baharım gitme

Duralar ishak kuşları

Geceler gündüzden seyran

Seslerine oldum hayran

Değme felek böyle devran

Süreler ishak kuşları

Zikreder Hakkın adını

Dal olam duyam tadını

Yüzüm üste kanadını

Sereler ishak kuşları

Seslerim gelmez yanıma

Sesi kar etti canıma

İster bir avuç kanıma

Gireler ishak kuşları

Umarım derdime derman

Yüreğimi kıldı harman

Çok mudur katlime ferman

Vereler ishak kuşları

Bağları sardı leşkeri

Talan oldu can şehiri

Nice bin gönül askeri

Kıralar ishak kuşları

Her biri hançer belinde

Kavlederler öz dilinde

Hıfzı''yı aşkın ilinde

Vuralar ishak kuşları', 'Dertli firkatli hasretli Na''ralar ishak kuşları Nedir suçum yüz bin yerden Yaralar ishak kuşları Ağladım eyledim seyri İstedim ilacı hayrı D...', ARRAY['Türk Edebiyatı','Şiir','Kağızmanlı Hıfzı']::text[], 8.5, '{"poet":"Kağızmanlı Hıfzı","poet_slug":"kagizmanli-hifzi","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/dertli-firkatli-hasretli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Van ve İstanbul...', 'van-ve-i-stanbul-bahri-kayaoglu-2fi88', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Van''da çocuklar üşür

Van''da çocuklar aç

Van''da çocuklar ezilmiş

Van''da çoçuklar gülmez..

Üşümek nedir? 

Açlık nedir? 

Ezilmişlik nedir? 

İstanbul''da çocuklar bilmez..

İstanbul nere Van nere! ..

Çocuklar kaderiniz mi bu? 

Çocuklar aranızda ne var? 

Dağ, deniz, orman, dere..

Benim gönlüm açılır kedere..', 'Van''da çocuklar üşür Van''da çocuklar aç Van''da çocuklar ezilmiş Van''da çoçuklar gülmez.. Üşümek nedir?  Açlık nedir?  Ezilmişlik nedir?  İst...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/van-ve-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona', 'ona-mehmet-sukru-bas-qeb9a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kutsal mabed gibi, gözledim kapını her gün,

Nakşetti benliğimde, kapılar, pencereler.

Su yolu ettim kapını her gün,

Rüyalarıma girdi pencerende perdeler.', 'Bir kutsal mabed gibi, gözledim kapını her gün, Nakşetti benliğimde, kapılar, pencereler. Su yolu ettim kapını her gün, Rüyalarıma girdi pen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ona-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-yavuz-bayram-caliskan-r7oaa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni özlemiyorsa sende özleme,

Seni beklemiyorsa, sende bekleme,

Şu dünyada yaşamak varken gülüm,

Hasret ile acı çekmek ne kelime,

Zorla güzellik olmaz, 

Gül açmadan solmaz,

Beklesende gelmez,

Güzelim, o senin kıymetin bilmez,

Seveceksen yürekten sev.

Sevenlere sevilenlere inat.

Yine de sevemedim dersen,

Buna yazılacak yok kelime.', 'Seni özlemiyorsa sende özleme, Seni beklemiyorsa, sende bekleme, Şu dünyada yaşamak varken gülüm, Hasret ile acı çekmek ne kelime, Zorla güz...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasihat-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam', 'aksam-mehmet-sukru-bas-32qyk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılar dondu yüreklerde,umutlar buharlaştı,

Adım adım tükendi yollar sona yaklaştı.

beyhude didinme gönül süren doluyor,

Gün çoktan kayboldu akşam oluyor.', 'Acılar dondu yüreklerde,umutlar buharlaştı, Adım adım tükendi yollar sona yaklaştı. beyhude didinme gönül süren doluyor, Gün çoktan kayboldu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aksam-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Olmak', 'cocuk-olmak-osman-turkmen-le0dt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin ve gündüzün, gün olduğunu bilmezken,

Gözü yaşlı annemi, anlamazdım hiç.

Çünkü, bilinen tek şeydi bilmemek,

Yaşamaktı o günleri, çocuktum ben.

Ağaçlı ormanların içinde, kaybolmak bile,

Zamanı unutup, hayale dalmak bile,

Umutsuz bir güne, umutla bakmak bile,

Yaşamaktı o günleri, çocuktum ben.

Dünü bilmeden yaşamak çok zordu,

O günler bir daha gelmeyecekti.

Hayal etmek bile, sanki yaşamaktı,

Yaşamaktı o günleri, çocuktum ben.', 'Gecenin ve gündüzün, gün olduğunu bilmezken, Gözü yaşlı annemi, anlamazdım hiç. Çünkü, bilinen tek şeydi bilmemek, Yaşamaktı o günleri, çocu...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-olmak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Taş', 'tek-tas-hana-dukacinac-eh53r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir vazom vardı

içinde tüm değerli taşlarım

5 yılımıza,herbir yıl için bir değerli taşım

Akik,safir,zümrüt,elmas,pırlanta

Dört elle sıkı sıkıya tutmaktayım

Kaderimide bağlamışım kırmızı kurdalelerle bile...

Göremesinler diye cam bir vazoya sırlamışım

Ani bir karayel,poyraz,kuzey rüzgarlarının tümü

bir de tayfun...

İrademin dışındaki tüm sarsıcı etkiler...

Başlangıcın bitişimi,bitişin başlangıcı mı

Doğanın yasası mı tabiatın kanunu mu? 

Ellerimden kayıverdi.Düştü.

Tuzla buz oldu.......Yüzlerce cam kırığı varoldu

5 değerli taşım beş ayrı yönde 

Ardındayım....Batıyor ayaklarıma cam kırığı

ulaşmaya çalışıyorum,benden daha hızlı uzaklaşıyor beş taşım.

Peşimde ise bir gölge.

Geliyorum bırak geleceğini ben de bir taşım diye sesleniyor

Kulak asmıyorum.

Bağırıyor avazı çıktığı kadar

koşma ben senin geleceğinim diyerek yanıma varıyor 

artık benle omuz omuza...

Bir yılın sonunda ne taakatim kalıyor ne de umudum bu maratonda..

Yorulmuşum.....Başım önümde süzülmüş beş damla yaşım

Peşimden gelmiş olan taşım:

-Üzülme ben varım 

Sen de kimsin diyorum? 

Senin gerçek geleceğin

Yalnızlığınım

Seni bırakmayacak olan 

Tek Taşınım....', 'Bir vazom vardı içinde tüm değerli taşlarım 5 yılımıza,herbir yıl için bir değerli taşım Akik,safir,zümrüt,elmas,pırlanta Dört elle sıkı sık...', ARRAY['Türk Edebiyatı','Şiir','Hana Dukacinaç']::text[], 8.5, '{"poet":"Hana Dukacinaç","poet_slug":"hana-dukacinac","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tek-tas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat Kırılır', 'dikkat-kirilir-timur-i-likan-rks7t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimi üzerinde dikkat kırılır

ibâresi bulunan bir kutunun

içerisinde gönderiyorum sana sevdâlılar 

adlı kargo şirketiyle hemen şimdi bir tânem

Bu kutunun gideceği yer olarak

senin gönlünün adresi yazıyor

iri kıyım puntolarla harflenmiş olarak

Aman dikkat et kırılmasın kalbim

sana kutu içinde geldiğinde

bir kargo görevlisinin ellerinde

Gönderimi muhafaza et en itinâlı

bir şekilde ilk günkü gibi kalsın

sana gönderdiğim hâliyle

Artık kalbim senin ellerinde

İyi bak ona olur mu

Onu yüreğinin yanına koy ki

âhengiyle çarpsın benim yüreğim de

seninkisiyle birlikte

Hiç bir zaman durmasın tâ ki

senin yüreğinin çırpınışlarının

durduğu o son ânâ kadar

İyi bak ona iyi bak sevgilim

İyi bak nâzik kalbime

(11 Mart 2006/ istanbul)', 'Kalbimi üzerinde dikkat kırılır ibâresi bulunan bir kutunun içerisinde gönderiyorum sana sevdâlılar  adlı kargo şirketiyle hemen şimdi bir t...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dikkat-kirilir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bırak(ın)', 'beni-birak-in-tulay-sustam-d1hyo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'usumun koridorlarında

binbir düşünce kol geziyor

gecenin

arka sokaklarında yalnızım

ne yana baksam

gölgeme, güneş çevirmiş yüzünü

ayaklarım / bir bağ bozumu

ipi kopmuş darağacımın

ne yana ölsem

inadına açacak gözlerimde bir papatya 

elimde bir yaprağım kalsa da 

inadına ''''sevmeyeceğim seni''''

içimde bir kız çocuğu

Ay''a dikmiş gözlerini

Avuçlarında binlerce yıldız kayıyor

ne yana uzansam

kum taneleri örtmez üzerimi

şimdi diyorum 

yarın yok melekler için

...heybemde ağız dolusu açlığım...

aşka hangi kapımı açsam

süpürmez kirpiğimdeki toz bulutunu

şimdi gitmeliyim

yağmur beni bekler', 'usumun koridorlarında binbir düşünce kol geziyor gecenin arka sokaklarında yalnızım ne yana baksam gölgeme, güneş çevirmiş yüzünü ayaklarım ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beni-birak-in-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim', 'dort-mevsim-osman-turkmen-cmlcf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilir misin, herkes gülerken, ben ağlardım sessizce,

Çaresizlik yaşardım sadece, dört mevsimde.

Baharım heves, yazlarım umut geçerdi hep,

Kışı yaşardım sadece, dört mevsimde.

Uzun geceler geçti ömrümden, ne karanlıktı bilsen,

Yaşarken görememek, düşünürken hissedememek,

Yürürken bile, inan kaçıyordum kendimden,

Acı yaşardım sadece, dört mevsimde.

Hücreye atılmış bir mahkum muyum? 

Ölmek kolay mı yaşarken.

Madem ki sevgi yok, öyleyse acıda olmasın,

Çünkü dört mevsimi, yaşamadım hiç ben.', 'Bilir misin, herkes gülerken, ben ağlardım sessizce, Çaresizlik yaşardım sadece, dört mevsimde. Baharım heves, yazlarım umut geçerdi hep, Kı...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dort-mevsim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kin filizlenecek mi?', 'kin-filizlenecek-mi-bahri-kayaoglu-cvray', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dul kalmış bir anne:

-Babanı şu vurdu oğul

Şu kara domuz

Şu uzun boylu

Giden...

-Büyüyünce,

Sende onu vuracaksın oğul..

Kanı aksın sokaklarda

İnceden inceden...

Yetim kalmış çocuk:

-Kan kötü

Kan kokar

Anne,

Ben kan sevmem...', 'Dul kalmış bir anne: -Babanı şu vurdu oğul Şu kara domuz Şu uzun boylu Giden... -Büyüyünce, Sende onu vuracaksın oğul.. Kanı aksın sokaklard...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kin-filizlenecek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert', 'dert-mehmet-sukru-bas-jvh45', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana derdi sormayın,

Ben derdi tanıyorum.

Dertle kalkıyorum sahura,

Dertle iftar açıyorum.', 'Bana derdi sormayın, Ben derdi tanıyorum. Dertle kalkıyorum sahura, Dertle iftar açıyorum....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dert-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmişinci Gününde Ayrılığın', 'yetmisinci-gununde-ayriligin-osman-turkmen-k73op', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karalanmış sayfalar gibiyim,

Gündüz yollarda, gece karanlıklarda.

Korkunç düşlerimin katiliyim,

Yetmişinci günündeyim ayrılığın! 

Bastırılmaktayım ve de kuşatılmakta,

Daracık günlere sıkıştırılmaktayım hatta,

Geceler bulanık bense ağlamakta,

Yetmişinci günündeyim ayrılığın! 

Ölümsüz duyguların, yarım kalan uykuların,

Ne anlamı kaldı ki tüm bunların,

Dün olanların, bugünse unutulmanın,

Yetmişinci günündeyim ayrılığın! 

İfade bile alınmadan hüküm giymenin,

Sorgusuz ve sebepsiz ipe götürülmenin,

Sırf duygular yüzünden idam edilmenin,

Allah kahretsin, yetmişinci günündeyim,

Yetmişinci gününde ayrılığın!', 'Karalanmış sayfalar gibiyim, Gündüz yollarda, gece karanlıklarda. Korkunç düşlerimin katiliyim, Yetmişinci günündeyim ayrılığın!  Bastırılma...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yetmisinci-gununde-ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talih', 'talih-mehmet-sukru-bas-tan4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Böyle bir talih oldukça bende

Ne bahar gelir ömrüme, nede gün doğar.

Bir karabulut kaplar üstümü

Dondurur kanımı afakı boğar.', 'Böyle bir talih oldukça bende Ne bahar gelir ömrüme, nede gün doğar. Bir karabulut kaplar üstümü Dondurur kanımı afakı boğar....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/talih-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Kuşu (Gurbet ellerdeki annesiz, babasızlara)', 'gurbet-kusu-gurbet-ellerdeki-annesiz-babasizlara-yavuz-bayram-caliskan-162aj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah anneciğim yanında olaydım,

Ağladıkça gözlerine dolaydım,

Kapında açtım kapında solaydım,

Söyle annem, ne işim var gurbet ellerde? 

Uzaklardan her gün haber salarım,

Ufuklara bakar bakar dalarım,

Saçlarımı tutar her gün yolarım,

Söyle annem, ne işim var gurbet ellerde? 

Hasreti gurbetten içmek için mi doğdun? 

Kapında yabancımıydım da  mı kovdun? 

Şu garip kızını sılasızlıklarda boğdun.

Söyle annem, ne işim var gurbet ellerde? 

Dünyaya yaşamak için bir kere gelinir,

Mutluluk ana, baba yanında alınır,

Sılanın değeri daima bilinir,

Söyle annem, ne işim var gurbet ellerde? 

Ben bu diyarda gurbet kuşuyum,

El oğlunun ekmeğiyim aşıyım,

Ben anamın hep göz yaşıyım,

Söyle annem, ne işim var gurbet ellerde?', 'Ah anneciğim yanında olaydım, Ağladıkça gözlerine dolaydım, Kapında açtım kapında solaydım, Söyle annem, ne işim var gurbet ellerde?  Uzakla...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-kusu-gurbet-ellerdeki-annesiz-babasizlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neş''e', 'nes-e-mehmet-sukru-bas-4m1e3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neş''eden zevkten,

Ben anlayamam.

Ben derde alıştım,

Onsuz olamam.', 'Neş''eden zevkten, Ben anlayamam. Ben derde alıştım, Onsuz olamam....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nes-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifreler...1', 'sifreler-1-enes-ates-ks3e2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kesdiler ahlakın şah damarını

Geriye bir yığın arsızlık kaldı.

Tıkandı dünyanın soluk borusu,

Yürekler yaralı, yüz asık kaldı.

Ten rengi şerefin kısmî iffeti

Tüketti mühleti, attı kasketi.

Çalındı ecdadın tek vasiyeti

Sofralarda sonsuz bir kıtlık kaldı...!', 'Kesdiler ahlakın şah damarını Geriye bir yığın arsızlık kaldı. Tıkandı dünyanın soluk borusu, Yürekler yaralı, yüz asık kaldı. Ten rengi şer...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sifreler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı..!', 'yanilgi-enes-ates-cljpc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşümde gerçeği ararken içim,

.................Gerçekte düşümü farkettim biraz..', 'Düşümde gerçeği ararken içim, .................Gerçekte düşümü farkettim biraz.....', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yanilgi-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanlarım', 'hanlarim-mehmet-sukru-bas-884f1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ciğerimde iki parça,

Can evimde iki can.

birisi METEHAN''ım,

Diğeri hanlar hanı BUĞRAHAN.

Damarlarımda ki kan,

Bedenimdeki can,

Konakladığım han,

Buğrahan''la Metehan.', 'Ciğerimde iki parça, Can evimde iki can. birisi METEHAN''ım, Diğeri hanlar hanı BUĞRAHAN. Damarlarımda ki kan, Bedenimdeki can, Konakladığım ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hanlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simsiyah Çığlıklar!', 'simsiyah-cigliklar-abdusselam-bugur-x3oqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece oturdum seni düşündüm 

Ne garip şeydi yokluğun! 

Seni özlemekten üşüdüm. 

Derin hüzünler yağdi bir''an geceden 

Aydınlık gülüşün zihnimde canlanırken 

Dolanıp durdum ne yaptığımı bilmeden.

Bilmem söylemem gerekirmi sana

Ne dersen de: yaşadıkça anliyoruz.

İlk bahar çiçeklerini açiyor toplayacağım sana

Gelsen: Simsiyah çığlıkları dinse gecenin 

Duysam: yüreğimi hızlandıran tatlı sesini 

Bitse: bitmek tükenmek bilmeyen özlemlerin. 

Ne çok yoksulum senden birden karşıma çıksan 

Soluğum kesilse; tutulsa dilim. 

Gülüşünle yüzüme; sevinçten anlamlar salsan.', 'Dün gece oturdum seni düşündüm  Ne garip şeydi yokluğun!  Seni özlemekten üşüdüm.  Derin hüzünler yağdi bir''an geceden  Aydınlık gülüşün zih...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/simsiyah-cigliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifreler...2', 'sifreler-2-enes-ates-fw7m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni dilsizlerin akrebi soktu

Dilimi kopardı söz cellatları..

Sözlerim silindi sayfalarımdan,

.......Kırıldı kalemim, kanadı dünyam!', 'Beni dilsizlerin akrebi soktu Dilimi kopardı söz cellatları.. Sözlerim silindi sayfalarımdan, .......Kırıldı kalemim, kanadı dünyam!...', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sifreler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Torun Sevgisi', 'torun-sevgisi-mehmet-sukru-bas-v81p3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Menekşedeki renk,Güldeki koku,

Hayatın manası, tendeki doku.

Gözümün nurları hanlarımın hepisi,

Hayatın balı kaymağı TORUN SEVGİSİ.', 'Menekşedeki renk,Güldeki koku, Hayatın manası, tendeki doku. Gözümün nurları hanlarımın hepisi, Hayatın balı kaymağı TORUN SEVGİSİ....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/torun-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini gözlerime dikip kana kana içeceğim', 'gozlerini-gozlerime-dikip-kana-kana-icecegim-selcen-boyar-q4jp1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günün herhangi bir yerinde,

herhangi bir saat de,

beni düşündüğünü hep bileceğim.

Unutmayacağım seni o belirsizliklerde,

senelerce...

senelerce seveceğim.

Herhangi bir zaman diliminde,

herhangi bir yerde,

karşına dikileceğim.

Saatlerce gözlerimi gözlerine dikip,

kana kana o gözleri içeceğim.

Bu bir fırtına içimde,

dinmesini beklemeyeceğim.

Esen deli yeller ile

savrulup sana geleceğim.

Bu bir ölüm olsada gözlerinde,

O gözlerde öleceğim.

Gözlerin kadar kara gecelerde,

dirilip yeniden,

hep yeniden öleceğim.', 'Günün herhangi bir yerinde, herhangi bir saat de, beni düşündüğünü hep bileceğim. Unutmayacağım seni o belirsizliklerde, senelerce... senele...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerini-gozlerime-dikip-kana-kana-icecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek dileğim!', 'tek-dilegim-enes-ates-lsiq5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son sözü söylesin gözlerim...

.........Giden bahara da yazık,

Gelen hicrana da! ! 

Ağlamaklı yarınlarımda 

Suskun bir komplosun şimdi..

.............Tek dileğim,

  Dileksizlik dilemendir yüreğim...! ! !', 'Son sözü söylesin gözlerim... .........Giden bahara da yazık, Gelen hicrana da! !  Ağlamaklı yarınlarımda  Suskun bir komplosun şimdi.. .......', ARRAY['Türk Edebiyatı','Şiir','Enes Ateş']::text[], 8.5, '{"poet":"Enes Ateş","poet_slug":"enes-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tek-dilegim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı', 'sakli-kevser-gulistan-cakir-67wrb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahın içinde gece saklıdır

Kavuşmanın içinde ayrılık...

Yeşilin içinde sarı saklıdır

Dostluğun içinde yalnızlık...

Aşkın içinde tutku saklıdır

Cesaretin içinde korkaklık...

Benim içimde sen saklısın

Senin içinde hoyratlık...', 'Sabahın içinde gece saklıdır Kavuşmanın içinde ayrılık... Yeşilin içinde sarı saklıdır Dostluğun içinde yalnızlık... Aşkın içinde tutku sakl...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sakli-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kadın var...', 'bir-kadin-var-bahri-kayaoglu-85ijr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi uzak bir şehirde

Bütün gündüz ve geceleri

Aradığım bir kadın var..

Benzetemiyorum ona hiç kimseleri..

Bekliyorum; 

Bir köşeden ansızın çıksın karşıma

Ve bir ''merhaba''yla başlasın her şey

Gözlerinde ayrı bir dünya göreyim

Saçları, mısır püskülleri gibi uzun olsun

Şöyle çıtı-pıtı

Yanım sıra yürüsün

Uzanıp ellerini tutayım

Onunla yaşayayım bütün mutlulukları..

Gülersem, o da benimle gülsün

Ağlarsam,

Onun da gözyaşları karışsın gözyaşlarıma..

Heyhat! 

İşte bugünde geçti gün

Bulamadan o aradığım kadını.

Ahh.. Yüzünü bir görebilsem

Öğrenebilsem adını..', 'Şimdi uzak bir şehirde Bütün gündüz ve geceleri Aradığım bir kadın var.. Benzetemiyorum ona hiç kimseleri.. Bekliyorum;  Bir köşeden ansızın...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-kadin-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırası Var', 'hatirasi-var-erdal-ozkan-xkxpx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne diye bu kadar çok sevmişimki

İçimde kapanmaz bir yarası var

Onu ne kadar özlemişimki

Nereye baksam hatırası var

Gün olur güler doğan güneşte

Gün olur bakar yanan ateşte

Boşalan şişede biten kadehte

Çalan her şarkıda hatırası var

Hayali her yerde gezer dolanır

Gözlerim boşlukta onu aranır

Daha ne kadar kalbim dayanır

Aldığım nefeste hatırası var.', 'Ne diye bu kadar çok sevmişimki İçimde kapanmaz bir yarası var Onu ne kadar özlemişimki Nereye baksam hatırası var Gün olur güler doğan güne...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatirasi-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lefke Bağlarının Gülüsün Sen', 'lefke-baglarinin-gulusun-sen-yavuz-bayram-caliskan-ip2ci', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lefke dağlarındaki esaretimden doğan kır çiçeğisin.

Eşkiya Bekir ile Devrişe’nin biricik Ayten’isin.

Sen dün değil bir aydınlık geleceksin.

Lefke bağlarının gülüsün sen.

Gençliği yaşadın yeşilin içinde,

Yok olup gittin bir subay göçünde,

Evlendin yedinci ayın yirmisekizinde,

Lefke bağlarının gülüsün sen.

Gözlerindeki parıltıyı ben bilirim,

Anadolu’ya kızım için gelirim,

Ayten’imden mutluluğu alırım,

Lefke bağlarının gülüsün sen.

Altını çamura atsan batmaz,

Ayten’i görenler yatak yatmaz,

Onunla konuşmaya dil yetmez,

Lefke bağlarının gülüsün sen.

Saçlarındaki aklara bakıyorum ben,

Kızım, Ayten’im, yüreğine akıyorum ben,

Yağmur olup, şimşek olup çakıyorum ben,

Lefke bağlarının gülüsün sen.

Yıllar geçer, anılar kalır,

Ayten’imin gençliğini Anadolu alır,

Yavuz Bayram tüm gerçeği bilir,

Lefke bağlarının gülüsün sen.

Bülbül öter, gül solmaz,

Bu dünya kimseye kalmaz,

Beklerim Ayten’im Lefke’ye gelmez,

Lefke bağlarının gülüsün sen.

Lefke bağlarında soluk alırım,

Ararım Ayten’imi geri kalırım,

Gider onu Baymışlarda bulurum,

Lefke bağlarının gülüsün sen.

Taşıma su ile değirmen dönmez,

Ayten’in çırası Aksaray’da yanmaz,

Gül açmazsa, bülbül ötmez,

Lefke bağlarının gülüsün sen.

Ben yokluğa sen ile yanarım,

Her geleni Ayten sanarım,

Arı gibi çiçeklere konarım,

Lefke bağlarının gülüsün sen.

Dokunuşun, sevişin, “baba”, diye gelişin,

Hele bakarken gamzeli gülüşün,

Gül bakışın, bülbül ötüşün,

Lefke bağlarının gülüsün sen.

Güller gün gelir çiçekler açar,

Zafer ile Aynur elinden uçar,

Kızım gelmez Lefke’den kaçar,

Lefke bağlarının gülüsün sen.

Dönülmez akşamlara yolcuyum,

Öte dünyada bilin hancıyım,

Ben yavrumun gönlünde sancıyım,

Lefke bağlarının gülüsün sen.

Izdırabı yaşarsan ağlarsın,

Kalbin isyan ederse çağlarsın,

Ben Eşkiya Bekir’im gönlümü dağlarsın,

Lefke bağlarının gülüsün sen.

Lefke bağlarında asma ekilir,

Hasret gurbetlerde çekilir,

Ayten’ime türküler yakılır,

Lefke bağlarının dünüsün sen.', 'Lefke dağlarındaki esaretimden doğan kır çiçeğisin. Eşkiya Bekir ile Devrişe’nin biricik Ayten’isin. Sen dün değil bir aydınlık geleceksin. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/lefke-baglarinin-gulusun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oldum', 'asik-oldum-erdal-ozkan-qbgzp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir bu güzellik böyle

Kız ben sana aşık oldum

Çaresini çabuk söyle

Kız ben sana aşık oldum

Duygularım dolu dolu

Şaşırdım gittiğim yolu

Sanki ilkbaharın gülü

Kız ben sana aşık oldum

Sımsıcak gülüşüne

Yolda ki. yürüyüşüne

Şu karşımda duruşunua

Kız ben sana aşık oldum

Saçlarının her teline

O yumuşacık ellerine

Velhasılı her şeyine

Kız ben sana aşık oldum.', 'Nedir bu güzellik böyle Kız ben sana aşık oldum Çaresini çabuk söyle Kız ben sana aşık oldum Duygularım dolu dolu Şaşırdım gittiğim yolu San...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asik-oldum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Behey...', 'behey-suleyman-zaman-u6vpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir saldırgan,

 almamış  insanlıktan nasibini; 

  hata üstüne hatalar yaparken

   davranıyor hiçbir şey olmamış gibi..

      pişkin mi pişkin? 

       Çatlamış ar damarı.

Konuşurken bazen bir mafya babası; 

    eksik değildir, koltuk altında sobası.

       Görüntüsü beyefendi, davranışı  afaki

         tüm dünya onunmuş gibi davranır sanki.

Behey adam; 

  ne sanırsın kendini; 

    ne yaparsan yap,

      her şey bulur dengini.

Ve 

   unutma ki; 

     büyüktür herkesin kendine göre çapı

       kurulmuştur dünyada, boşluksuz yapı.

         Ve 

           bil ki! Tavşanda kraldır kendi çöplüğünde.

             ararım cahilliğini görgüsüz hödüklüğünde.

Adam ol oğlum adam

  hiç işe yarar mı? Cüdam

   onu kırmak, bunu kırmak

    onu kandırmak, bunu kandırmak; 

     yakışır  mı insana? 

Mektebi olmaz insanlığın

  Hoş karşılanmaz banallığın, hamlığın.

Hele akademik bir insana

 kabalık yakışır mı  sana? 

Tanı kendini; kendine dön

 sorgula benliğini, gör tutarsızlığını; 

  ölçü egemen olsun davranışlarında

    kendini beğenmişlik var senin huyunda.

Anla  yaptığın işleri,

   bil  geldiğin noktayı

    değerlendir konumunu

     başkaları yapsın yorumunu.

Samimi değilsin davranışında

  hatanı birisi sana söylediğinde

   saldırganlaşıyorsun birden bire

       yakışır mı? Bu tavır çağdaş insana

Tahammül insanın olgunluğudur

  Kibirlilik kişinin sayrılığıdır.

    Ve 

       Her zaman; boş söz zatın cahilliğidir.

İlacıdır her şeyin zaman

  Boğulur bilinmez deryaya dalan,

Ve dostum anlıyorum ben seni

  ama davranışlarınla üzdün sen beni

   bil ki, bilincimde yoktur kin

     affederim her zaman insanı

       belki de inanın bunun en güzel yanı

        bilmektir acının ve tatlının varlığını

         yaşamda belki de bu aykırı kanı.

   

İnsan ol oğlum insan

  her insana gerekli güvenli bir can.

  

                      20.03.2002', 'Bir saldırgan,  almamış  insanlıktan nasibini;    hata üstüne hatalar yaparken    davranıyor hiçbir şey olmamış gibi..       pişkin mi pişki...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/behey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrarla Sen', 'tekrarla-sen-l-tif-karagoz-4eh6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçerken evim önünden

Gözlerinin şavkı vurur.

Silemem seni gönlümden

Hüzün benden uzak durur! 

Özleşirler gözlerimiz

Yüreğimde hazın tadı.

Alevlenir közlerimiz

İçimizde sevgi adı! 

Çiçeklenir sevgim her gün

Bakışların birer öpüş.

Gönlüm coşar sanki düğün

Yaşantılar degil mi düş? 

Olur mu ya, durma söyle

Nerde öpüş bakışların? 

Geçmez oldun neden öyle

Tekrarla sen,hadi yarın! .', 'Geçerken evim önünden Gözlerinin şavkı vurur. Silemem seni gönlümden Hüzün benden uzak durur!  Özleşirler gözlerimiz Yüreğimde hazın tadı. A...', ARRAY['Türk Edebiyatı','Şiir','Lâtif Karagöz']::text[], 8.5, '{"poet":"Lâtif Karagöz","poet_slug":"l-tif-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tekrarla-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldönümü...', 'yildonumu-bahri-kayaoglu-ncthc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O deli fişek gibi gönlüne vurgun

Yenik bir savaşçı gibi yüreğim

Şimdi yorgun...

Ne sen son aşkım oldun

Ne ben ilk aşkın kaldım.

Sen şimdi başka bir mevsimin baharı

Benim ellerimde başka bir gül

Belki mor, belki pembe, belki sarı...

O gün,

O tanıştığımız gün

Bir yıl sonra bugün işte

Bir yıl sonra da aynı gün...', 'O deli fişek gibi gönlüne vurgun Yenik bir savaşçı gibi yüreğim Şimdi yorgun... Ne sen son aşkım oldun Ne ben ilk aşkın kaldım. Sen şimdi ba...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildonumu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsama', 'animsama-tulay-sustam-phdrk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.ı.

usumun

önsözüne yazdım seni

sonu gelmedi

..ıı..

yağmur

istediği kadar ıslatsın güneşi

onun ilk kıvılcımı bulutundur', '.ı. usumun önsözüne yazdım seni sonu gelmedi ..ıı.. yağmur istediği kadar ıslatsın güneşi onun ilk kıvılcımı bulutundur...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/animsama-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığım', 'isigim-nazan-i-zmirli-lntv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni   seviyorum

demek

serhat

çekmek

yarınlara.

oysa!  sen 

ışığım 

zaman 

tünelimsin

duygularımın 

sonsuzluğunda...

11.03.2006-ant-ışığım', 'seni   seviyorum demek serhat çekmek yarınlara. oysa!  sen  ışığım  zaman  tünelimsin duygularımın  sonsuzluğunda... 11.03.2006-ant-ışığım...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isigim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Bilmiyorum Adı', 'nedir-bilmiyorum-adi-arzu-corluluoglu-54lmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nedir bilmiyorum,adı nedir gerçeğin? 

Gerçek; 

Bir delikanlının alev gözlerindeki güzel kız mı? 

Bir ihtiyarın elinde tuttuğu emekli cüzdanı mı yoksa..? 

Nedir bilmiyorum, sen nerdesin? 

Kalp atışım olmasaydın dayanamazdım ki sana..

Onca alaboradan sonrası böyle sevilmezdin ki sen..

Yoksa..

Yoksa sen içimdeki gerçek misin dışımdaki hayalden öte..? 

Nedir bilmiyorum,şu hayatın içindeki kelebekleri özlemenin anlamı..? 

Ben özenmezdim böylesi,

Salınarak akıp giden günün avuçlarına..

Böylesi esmezdi rüzgar eskiden.

Şimdi rüzgarın,

Birşeyleri değiştirdiğini farkediyorum usuldan.

Ve; 

Nedir bilmiyorum şu çalan şarkının adı neydi..? 

Öyle tanıdık ki..

Sanki o yağmurda ıslandığım gün dinlemiştim.

Biryerlerde çalıyordu yavaştan.

Üzerimde lise formam...

Kalbimde o asla bitmeyeceğini sandığım sevdam...

Nedir bilmiyorum işte..

Şu çalan şarkı umurumda değil aslında.

Umurumda olan tekşey,

Aynadaki....

Aynada asırlar var ve ben,

Asırlarca yorgunum belli ki...

Nedir bilmiyorum bu sadeliğin içindeki karmaşa.

Galiba unutuyoruz bir vedalı olarak merhabalar dediğimizi.

Çok basit bir öz var tüm olayların içinde ki,

O da; 

Her insanın içinde bulduğu bir teklisi...

Nedir bilmiyorum işte...

Ben bir tek seni bulmuşken,

Bir de baktım ki...

Gözlerimin içinde cam kırıkları oluvermişsin ve,

Kan kaybeder olmuşum gözlerimden sen çağlaya çağlaya...

Şimdi nedir bilmiyorum işte,gerçeğin adı ne? 

Aynadaki mi,karşındaki mi? 

Yoksa,

Ateş böcekleri mi yalnızca...? 

Yoksa; 

Kirpiklerine bulaşan anıların mı yıllar içinde hepsine sahip çıkamadığın..? 

Yoksa; 

Gerçeğin adını boşvermek mi en iyisi acaba...? 

Nedir bilmiyorum...

Bayramlıkları artık satmıyorlar mı ne? 

Uçurtmaların hepsi mi tellere takılmış yani,yoklar...

Uykuları kabuslar bürümesin,sarılsana annene...

Nedir bilmiyorum,bu tuhaflığın anlamı..? 

Artık herşey birşeyleri anımsattığı için önemli yalnızca...

Oysa; 

Hala nefes alıyoruz...

Hala varız ve bir yerlere gölgemiz düşüyor..

Neden tek düşer şu gölge neden..? 

Bir ağaç yoldaş olur kimi zaman,

Kimi zaman yanından geçen bir kedi...

Yalnız olmaktan nefret ettiğin halde,

Neden bilmiyorum saklanmamız böylesi...

Nedir bilmiyorum işte...

Adı nedir gerçeğin.....', 'Nedir bilmiyorum,adı nedir gerçeğin?  Gerçek;  Bir delikanlının alev gözlerindeki güzel kız mı?  Bir ihtiyarın elinde tuttuğu emekli cüzdanı...', ARRAY['Türk Edebiyatı','Şiir','Arzu Çorluluoğlu']::text[], 8.5, '{"poet":"Arzu Çorluluoğlu","poet_slug":"arzu-corluluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/nedir-bilmiyorum-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilgi...', 'yenilgi-bahri-kayaoglu-pjgy0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koyver bakışlarını sonbaharlım

Mavi göklerimi eritsin.

Hızlı bir rüzgara bindirde saçlarını

Koyver üstüme üstüme gelsin..

Söz veriyorum,

Anılarımdan hangisi önüne çıkarsa sonbaharlım

Vur, teker teker hepsini öldür.

Ve ne zaman,

Seni aramaya çıkarsa o deli,

O hırçın duygularım.

Sustur konuştuğu yerde

Tüm ışıklarını söndür..

Bugün meydan senin sonbaharlım

El-pençe divanına dize geldim..

Dilediğini yap umutlarımdan

Dilediğini sat..

Ama artık ya sev beni

Ya da son kez ellerini ellerime uzat..', 'Koyver bakışlarını sonbaharlım Mavi göklerimi eritsin. Hızlı bir rüzgara bindirde saçlarını Koyver üstüme üstüme gelsin.. Söz veriyorum, Anı...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yenilgi-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuş', 'dogus-nazan-i-zmirli-x6d3q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kadının

cenini

sahiplenişi

gibi   tuttum 

seni

içimde.

inci  kümesi

oldun  besledikçe

sevgimle.

gün   gün 

sararırken

özleminden

bedenim,

can  verdin

sümbül,  yasemin

kokuların nefesimde.

kulaklarım çınladığında

mavilerine   saldın 

renk  renk   kuşlarını

çift  çift   kucaklaştık

ötüşlerinin   ritminde

besteler   yaptım

dansederken  tek  beden

sevgimize.

doğuş 

doğuşu

başka  bu  günün

sevgini

sen  içine  döktükçe.

güneş

dudaklarında  gizli

bulutlar ağlamak

istedikçe.

dök..! .

dök..! 

zerre  zerre

aksın  yaşların

sırılsıklam  olsun

sana   uçuşan

ipek   saçlarım 



ama! 

...........içindeki

.......................doğuşa

hep.............................gülümse.

11.03.2006-antalya-doğuş gülümsemende-', 'kadının cenini sahiplenişi gibi   tuttum  seni içimde. inci  kümesi oldun  besledikçe sevgimle. gün   gün  sararırken özleminden bedenim, ca...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/dogus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmezmi cânâ cêfa sebebin varmı', 'yetmezmi-c-n-c-fa-sebebin-varmi-ali-riza-unal-de65r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yetmezimi  cana cefa, sebebin varmı,

Düştüğüm bu gam-a,haberin varmı,

Onca kahrın bana şifa-i sefa,

Ben  seni düşünürüm kederin varmı.

   ----   nakarat   ----

Bitmezmi bu ayrılık nedenin varmı,

Ben sen düşünürüm kederin varmı..', 'Yetmezimi  cana cefa, sebebin varmı, Düştüğüm bu gam-a,haberin varmı, Onca kahrın bana şifa-i sefa, Ben  seni düşünürüm kederin varmı.    --...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yetmezmi-cana-cefa-sebebin-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Gitme', 'git-gitme-serpil-karabacak-sww6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acıtmaz,üşütmez, seni aklıma savuran rüzgar...', 'Acıtmaz,üşütmez, seni aklıma savuran rüzgar......', ARRAY['Türk Edebiyatı','Şiir','Serpil Karabacak']::text[], 8.5, '{"poet":"Serpil Karabacak","poet_slug":"serpil-karabacak","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/git-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul geceleri hiç de güzel değil..', 'i-stanbul-geceleri-hic-de-guzel-degil-bahri-kayaoglu-qas9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul geceleri hiç de güzel değil..

Deniz durgun değilse

Mehtap yoksa

Yakamozlar parlamıyorsa

Yanında sevdiğin bulunmuyorsa

İstanbul geceleri hiç de güzel değil...', 'İstanbul geceleri hiç de güzel değil.. Deniz durgun değilse Mehtap yoksa Yakamozlar parlamıyorsa Yanında sevdiğin bulunmuyorsa İstanbul gece...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/istanbul-geceleri-hic-de-guzel-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can mı?', 'can-mi-bahri-kayaoglu-ylm5g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kardeş o ne? 

O ellerinde ki,

Buz gibi...

Kokunca korkunç,

Ölüm gibi..

Kardeş o kim? 

Yatınca uzun

Yatınca ağır..

Dizlerinin dibinde

Kör, dilsiz, sağır..

O da can mı? 

Kardeş,

Alacan mı?', 'Kardeş o ne?  O ellerinde ki, Buz gibi... Kokunca korkunç, Ölüm gibi.. Kardeş o kim?  Yatınca uzun Yatınca ağır.. Dizlerinin dibinde Kör, di...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/can-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş..', 'gunes-bahri-kayaoglu-ymgei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu doğan güneş bizim değil bacı

Şu doğan güneş bizim değil..

Ekinde,

Yazı da, yaban da

Parmaklarına diken dolan

Elleri nasırlı insanlardan habersiz

Yurdumun en güzel yerlerinde

Soyunup bir gölgenin altında

Denize girenlerindir..', 'Şu doğan güneş bizim değil bacı Şu doğan güneş bizim değil.. Ekinde, Yazı da, yaban da Parmaklarına diken dolan Elleri nasırlı insanlardan h...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunes-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bayram mı', 'bugun-bayram-mi-fatma-saylak-7xi16', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çikolotam şekerim 

Hani nerde sevdiklerim 

Dört duvar arasında neyleyim

Bugün bayram mı

El öptürecek çocuklarım

Şeker verecek komşularım 

Yokki hiçbir yakınım

Bugün bayaram mı

Uğruna dünyaları verdiklerim

En yakınımdı çekip gidenlerim

Beni bu bayram terkedenlerim

Bugün bayram mı söylesenize', 'Çikolotam şekerim  Hani nerde sevdiklerim  Dört duvar arasında neyleyim Bugün bayram mı El öptürecek çocuklarım Şeker verecek komşularım  Yo...', ARRAY['Türk Edebiyatı','Şiir','Fatma Saylak']::text[], 8.5, '{"poet":"Fatma Saylak","poet_slug":"fatma-saylak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-bayram-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mana tutkusu', 'mana-tutkusu-fikret-polat-96ahw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir şarkı çalın bana

dede efendi''den nağmeler sunsun

bir kitap alın bana

içinde mutlaka ama

mutlaka bir şiir bulunsun

ben fani, 

ben mahkum ölüme

biri çıkıp son arzumu sorsun isterim

bir manalı söze binbir kelime

satırbaşında canını versin isterim', 'bir şarkı çalın bana dede efendi''den nağmeler sunsun bir kitap alın bana içinde mutlaka ama mutlaka bir şiir bulunsun ben fani,  ben mahkum ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Polat']::text[], 8.5, '{"poet":"Fikret Polat","poet_slug":"fikret-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mana-tutkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destanlar Yazarız', 'destanlar-yazariz-nail-demir-3tq7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Mehmet''im ölse binlercesi doğar

Vatanına el kaldıranı inan ki boğar

Düşman giremez yurduma... O''nu kovar

Bu millet ki çocuklarına Mehmet adı koyar

Tarihleri de destanları da yapan ve yazan biziz

Ülke bütünlüğü için her an biriz

Gerektiğinde bağımsızlık için ölmesini biliriz

Bu millet ki''Çanakkale Destanı''nı'' yazanları bilir

Vatan için her askerim kesilir bir aslan

Sen sahip çıkarsan batmayacaktır bu vatan

Korkusuzlardır ancak toprağa girip yatan

Bu millet ebediyyen var olmasını bilir

Nice medeniyetler geldi geçti yurdumdan

Türk oğlu Türk hiç vaz geçmedi vatanından

Ölümlerin vız geldiği şehitlerini de unutmadan

Bu millet daha nice Mehmetler yetiştirecektir

Gez, gör vatanını, anla tarihin gerçeklerini

Şöyle bir düşün ülkene vereceklerini

Unutma şehitlerini üzme sevenlerini

Bu millet tarihe nice şan ve şeref katacaktır

2006', 'Bir Mehmet''im ölse binlercesi doğar Vatanına el kaldıranı inan ki boğar Düşman giremez yurduma... O''nu kovar Bu millet ki çocuklarına Mehmet...', ARRAY['Türk Edebiyatı','Şiir','Nail Demir']::text[], 8.5, '{"poet":"Nail Demir","poet_slug":"nail-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/destanlar-yazariz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yek Vücut*', 'yek-vucut-bahri-yildirim-8n8p8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman ki çaresizim

Ne zamanki,sensiz yüreğim

Ne zamanki sen değilsin

Düşlerimin en güzeli

Bir haller oluyor bedenime

'''' Bir eğik baş

Bir boyunduruktan

Ağır gelir boynuma'''' T. Fikret

Kaldıramazsam ne zaman

Bu sevdanın yükünü

Yıkıldığımın resmidir.

En iyisi:

Herkes yansın yakılsın

Kendince hazırlansın

Yolculuk başlamıştır yarına

İki can

İki yürek

İki beden

Bir beyin beraberiz', 'Ne zaman ki çaresizim Ne zamanki,sensiz yüreğim Ne zamanki sen değilsin Düşlerimin en güzeli Bir haller oluyor bedenime '''' Bir eğik baş Bir ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yek-vucut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence de Sence', 'bence-de-sence-eren-caglar-niron-2igdg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sence geceyse 

bence gündüz değil

düşümden düştüğünse

koca bir yalan sadece

Eren Caglar Niron

Oxford

2004', 'Sence geceyse  bence gündüz değil düşümden düştüğünse koca bir yalan sadece Eren Caglar Niron Oxford 2004...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bence-de-sence-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-eren-caglar-niron-s21as', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın tatlı yanına

hep sonradan

ama illede 

tam arkası yarın sahnesine

sızıyordu bir şekilde

tarifsiz bir eksiklik duygusu

Eren Caglar Niron

Ankara

2004', 'Hayatın tatlı yanına hep sonradan ama illede  tam arkası yarın sahnesine sızıyordu bir şekilde tarifsiz bir eksiklik duygusu Eren Caglar Nir...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensizken-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süküt / söz', 'sukut-soz-nazan-i-zmirli-2281v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'söz 

.........gümüş

süküt 

.........altınsa

sevdama   söz   verdim

süküt   akacağım   yollarında

sabırla   akik   taşlarını   yontup

tesbih  dizeceğim    incilerden   boynuna 

söz

sevdam

söz

süküt 

söz   sana

11.03.2006-ant-süküt  /  söz-', 'söz  .........gümüş süküt  .........altınsa sevdama   söz   verdim süküt   akacağım   yollarında sabırla   akik   taşlarını   yontup tesbih ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sukut-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Andım', 'seni-andim-mevlude-demir-tzlp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha dün  neşeli şarkılarla, 

Seni andım  günboyu.

Şiirler yazdım,

Sevgi sözcüğü dolu

Her şarkıda seni buldum,

Sana aşık oldum.

Dudaklarımda  fısıltı,

Gözlerimde  ışıltısın.

Yüreğimden sevdanı silsem,

Ruhum seninle dolu.

Engelleri yıksanda,

Bana koşsan ne olur? 

Dudaklarımdan  öpüşün,

Sence nasıl unutulur?', 'Daha dün  neşeli şarkılarla,  Seni andım  günboyu. Şiirler yazdım, Sevgi sözcüğü dolu Her şarkıda seni buldum, Sana aşık oldum. Dudaklarımda...', ARRAY['Türk Edebiyatı','Şiir','Mevlüde Demir']::text[], 8.5, '{"poet":"Mevlüde Demir","poet_slug":"mevlude-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-andim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama ad koyalım! ..', 'yasama-ad-koyalim-mehmet-coban-zutk9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelip gitmek var

Doğ, yaşa, öl

Sessizce, habersiz

Veya 

Gürültülü, patırtılı

Tarih var, 

Birileri,

Takmış peşine insanları

Uzak diyarlara doğru

Kan dökerek 

Süslemişler yolları

Övünülüyor 

Dökülen kanlarla

Birileri var

Sessiz sedasız

Yazmışlar kitapları, 

Çizmişler resimleri, 

Yapmışlar eserleri

Çile dolu hayatları

Eserleri bize miras

Birileri var,

İnsanların sırtında,

Elini, emeğini, hayatını

Çalmışlar insanların

Oturmuşlar 

Egemenliğin,

Paranın tepelerine

Hayat biçmişler 

Çizgi çekmişler

Kendilerine efendi

İnsanlara köle demişler

Birileri var

Kutsal savaşlarda

Soyunmuşlar, kuşanmışlar

Her türlü zorbalığa karşı

Kendileri için

İnsanlar için

Özgürlük istemişler

Eserleriyle, yaşamlarıyla

Kanlarıyla, hayatlarıyla

Yaşarken terörist sayılıp

Ölünce kahraman sayılmışlar

İnsanların anılarında geziyor

Ve ben, 

Ve sen, 

Ve biz, 

Ve siz, 

Yaşama ad koyalım

Bizden sonra birileri

Bizim için

Birileri var dediğinde

Nereye koysun? 

Nerede ansın? 

11.03.2006-İzmir', 'Gelip gitmek var Doğ, yaşa, öl Sessizce, habersiz Veya  Gürültülü, patırtılı Tarih var,  Birileri, Takmış peşine insanları Uzak diyarlara do...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yasama-ad-koyalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Gibi Sev Kardeşim', 'yunus-gibi-sev-kardesim-sabahattin-hizmetli-gxxu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılmasın sevilenler,anne,baba,kardeş,dostlar,

Akrabalar,arkadaşlar,huzur içinde yaşasın.

Kırmayalım kimseleri,kapanmaz kalpte yaralar,

İnsanlığa gül ekelim,dikenler dağda yaşasın.

Yunus gibi sev kardeşim,Mevlana''yla dön kardeşim,

Gönlün güzellikle dolsun,kötülüğü kov kardeşim.

Yetimleri okşa büyüt,düşene uzat elini,

Deva bulmaz dil yarası,ölçülü söyle sözünü.

Coş sevginle seller gibi,dostluğa aç yüreğini,

Hoş görün eksik olmasın,tut verdiğin her sözünü. 

Yunus gibi sev kardeşim,Mevlana,yla dön kardeşim,

Gönlün güzellikle dolsun,kötülüğü kov kardeşim', 'Ayrılmasın sevilenler,anne,baba,kardeş,dostlar, Akrabalar,arkadaşlar,huzur içinde yaşasın. Kırmayalım kimseleri,kapanmaz kalpte yaralar, İns...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yunus-gibi-sev-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç''liğin Serüveni', 'hic-ligin-seruveni-omer-golge-jlf6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kayıtlardan kurtulma çabasında ruhum

İmkanı sınırlayan ufkun son noktasında

Zamandan ve tüm kaygılardan bağımsız

Süzülüp gözlerinden geçerek...

Lâ_ Mekan bir boyutun tam ortasında

Burada ne sen varsın..

Artık ne  ben

Ne de günlük dertlerimizden arta kalanlar

Silerek gözlerinin can yoldaşı hüznü

Sarmakta bizi gümüş rengi lâhuti dumanlar

Sonsuz bir yükselişin hazzıyla gönül

Varlığın aslıyla buluşmaktadır.

Sende, sen olduğunu vehmettiğin

Beni de ben yapan her şey dışında

Benlikten bizliğe hareket hali

Ulaşır ''hiç''liğe son noktasında.

Öyle bir hiçlik ki herşey olursun

Her zerrede soluk alan tabiat

Ekilince bire bin veren toprak

Okyanusun en derin noktasında

Balığın rızkı olan bir mercan yaprak

Kimi gün açlık kavurur seni Afrika''da

Filistin''de akan senin kanındır

Irzına geçilir, aşağılanırsın

Kan kusarsın toplama kamplarında

Hiç olmanın bedelini ödersin

Yaşayarak bütün bu acıları

Yüreğinde gözyaşıyla sulanırken umutlar

Her yerinde boy verir insanlık sancıları

İşte budur gül yüzlüm,bu ufkun ötesinde

Gözlerine dalarak çılgınca aradığım

Sende, senden de içre bulduğumu sandığım

Hiçliğin macerası uzanırken ebede

Cennetin kapısında yokluğunla yandığım





-', 'Kayıtlardan kurtulma çabasında ruhum İmkanı sınırlayan ufkun son noktasında Zamandan ve tüm kaygılardan bağımsız Süzülüp gözlerinden geçerek...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hic-ligin-seruveni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
