INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can ERZURUM Can', 'can-erzurum-can-zernisan-aydogan-3in9q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurtulduğumuz gündür bu gün

Allah Allah sesleri yükseliyor

Dadaşlar diyarından

Yürekler bir bütün olmuş

Tek damardan akıyor kan 

Gün bu gün an bu an

Bu gün senin günündür 

Can Erzurum Can

Dadaş yay gibidir 

Gerilmeye gelmez

Bir kez şaha kalkarsa

Dur durak dinlemez

Ezer çıbanın başını

Yaraları büyütmez

Gün bu gün an bu an

Bu gün senin günündür

Can Erzurum Can

Dadaşım tutuşmuş el ele

Vermiş omuz omuza

Kurtuluşunu kutluyor

Büyük bir ihtişamla

Baş barı oynanıyor

Yine havuz başında

Gün bu gün an bu an

Bu gün senin günündür

Can Erzurum Can

                     12 Mart 2006 /Erzurum

                             Zernişan Aydoğan', 'Kurtulduğumuz gündür bu gün Allah Allah sesleri yükseliyor Dadaşlar diyarından Yürekler bir bütün olmuş Tek damardan akıyor kan  Gün bu gün ...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/can-erzurum-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Disilerin Siiri', 'disilerin-siiri-i-brahim-ethem-uzun-6mv2c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eriyor buz parcasi gibi gozlerinde

Ask 

Buharlasiyor su gibi avuclarinda

Zaman

Mekan

Kayboluyor ufka ucan ucak gibi dudaklarinda

Evler

Kaderler

Vadiler

Pir donuyor pervane gibi  belinde

Yildizlar

Denizler

Zelzeleler

Daglar 

Insanlar

Yere dusuyor canak comlek gibi cehrem

Avuclarimla tasiyorum paramparca cehrem

Ariyorum bu surati satin alacak kadini

Hangi kadin dirhem verir ki eskimis canak comlekleri

Haber ver bana 

Hatta bedava olsa

Kimsenin kabul etmiyecegini bu huzunlu yuzumu

Sonunda sifira ulastim

Ne soyleyecegim

Ne soyleyeceksin

Yapayalniz tum meseleler

Karmakarisik tum mevzular

Onde olan arkada

Arkada olan onde

En yuksek tepeye tirmandik yeiste

Bagrimizi actik semada mermilerin yagdigi zirvede

Kucaklasan kollarin kirildigi beldede

Sevismenin taslandigi kosede

Beni sev 

Veya sevme

Bu senin hususiyetinde

Cozemiyorum dudaklarinin sifresini

Nasil dunyanin icine girecegim agzindan

Infilak ediyor su kayalarin altindan

Baliklar haykiriyor hurriyet icin yosunlarin arasindan

Kuslar intihar ediyor bulutlarin arasindan

Her gecen gun beni daha cok anliyorsun

Her gecen gun bana daha cok tapiyorsun 

Her gecen gun benden daha ziyade urkuyorsun

Neden gozlerim icine bakip bakip agliyorsun

Omuzlarim kaldiramaz goz yaslarini biliyorsun

Istiyorsun 

Veya istemiyorsun 

Disilik Allahin isinden

Kadinlik Allahin ilminden

Disiligini en iyi sekliyle yasayacaksin

Firsat ver erkekligim disiligini diledigi gibi dislesin

Cennetin haritasina sahip olsaydim birden

Okurdum seni satir satir basliyarak tirnaklarindan

Sularini 

Karalarini

Emin olurdum 

Deniz melteminin ne yandan estigini

Yagmurun hangi buluttan yagdigini

Simsegin ne zaman caktigini

Ayin gogsunun arasindan nasil gunduzleyin dogdugunu

Gunesin geceleyin nasil saclarinin arasina gizlendigini

Gezegenlerin nasil boynunun etrafinda donduklerini

Yolumu karanlikta nasil kaybettigimi yalin ayaklarinin altinda

Aski ariyorum pipomun dagilan dumaninda

Aski ariyorum ictigim kahve fincaninda

Aski ariyorum isittigim ezan sesinde

Aski ariyorum ermis yemislerin cekirdeginde

Aski ariyorum mezar taslarinin harflerinde

Aski ariyorum dislerinin arasindaki ekmek kirintilerinda

Sev 

Veya sevme

Seneler 

Mevsimler

Konuyor dizlerinin ustune

Agliyorum ben hungur hungur dizlerinin dibinde

Ellerin saclarimda kurutuyor icimdeki goz yaslarimi

Hatirlatiyorsun bana kasideler asrini

Su zamani

Sevgi zamani

Gul vakti

Bulbul vakti

Dolunayda sevisme ani

Sevgimi islah etmeye calisacagim

Kasenin kirilan parcalarinin birlesmeyecegini

bile bile

Ister gel

Ister gelme

Dava hak etmiyor uzun beklemeyi

Hak etmiyor efkarlanmayi

Duygularim buz tuttu unuttu gulmeyi

Hayatta tanidigim her kadin

Girdi canimin icine izinsiz

Cikti canimin icinden izinsiz

Sevdim onlari hep sebepsiz

Dusundum onlari hep sebepsiz

Butun disiler siirler yazdi civiyle kalbimde isimsiz

Her gece tutsulerle okudum o siirleri kimsesiz

Ve nihayetinde ben de iste sessiz

Disilerin siiri oldum kelimesiz hecesiz

Kadinlarin sairi oldum kimseden habersiz', 'Eriyor buz parcasi gibi gozlerinde Ask  Buharlasiyor su gibi avuclarinda Zaman Mekan Kayboluyor ufka ucan ucak gibi dudaklarinda Evler Kader...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/disilerin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Yağı', 'zeytin-yagi-timur-i-likan-gmw8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimse zeytin yağı gibi

suyun üstüne çıkmaya çalışmasın

hiç bir zaman ve hiç bir şekilde

Zeytin yağı gibi su üstüne

çıkmaya uğraş gösteren mağrur kişi

an gelir batıverir bir kurşun külçesi edâsıyla

suyun en dibine en dibine

bir daha suyun yüzünü hiç görmemecesine

sonsuza dek  sonsuza dek

(12 Mart 2006/ İstanbul)', 'Kimse zeytin yağı gibi suyun üstüne çıkmaya çalışmasın hiç bir zaman ve hiç bir şekilde Zeytin yağı gibi su üstüne çıkmaya uğraş gösteren ma...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zeytin-yagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Biliyorum Ki Bir Yerlerde Yüreğin Atmakta', 'ama-biliyorum-ki-bir-yerlerde-yuregin-atmakta-baran-demir-tky5k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni ne çok özlüyorum ceylan gözlüm 

Bu yorgunluğumu unutturuyorsun bana

Hiçe sayıyorum vucudumun beni taşımamasını 

Ruhumun yenik düşmesini zamana

Seni düşünüyorum gözlerimi kapatarak 

Yüzünün güzelliği düşüyor, yüreğinin güzelliği gibi

Uyanmak istemiyorum 

Uzandığım yerden kalkmak istemezcesine

Sesinin ahenkli tınısı çınlıyor kulaklarımda ninni gibi

Masal gibi geliyor gülümsemenle  korkulu gecelerime

Bir melek gibi düşlerimdeki zebanilere kalkan oluyorsun 

Ben korkularımı ardıma alarak seni seyre dalıyorum

Ve silkinerek uyanıyorum 

Seni göremiyorum karşımda 

Hüzünleniyorum 

Ama biliyorum ki bir yerlerde yüreğin atmakta

Nefesini duyuyorum ve mutluluk kaplıyor

Gülümsüyorum', 'Seni ne çok özlüyorum ceylan gözlüm  Bu yorgunluğumu unutturuyorsun bana Hiçe sayıyorum vucudumun beni taşımamasını  Ruhumun yenik düşmesini...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ama-biliyorum-ki-bir-yerlerde-yuregin-atmakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemeden Veren Vardı', 'i-stemeden-veren-vardi-yasar-tezel-x3c2o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benimde hayallerim vardı

Umutlarımın kovaladığı

Kaç gece karanlıkları araladı

Hüzünlendi

İçten içe ağladı

Aklıma gelmeyen dualar aradım

Cevapsız bırakmadı

Anladım

O istemeden olmazmış

Rahmet damlalarında

Hayallerim vardı', 'Benimde hayallerim vardı Umutlarımın kovaladığı Kaç gece karanlıkları araladı Hüzünlendi İçten içe ağladı Aklıma gelmeyen dualar aradım Ceva...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istemeden-veren-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlıyor musun', 'hatirliyor-musun-suleyman-bolat-cidme', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun bilmem

Hani bin yıl önce gelmiştik ya dünyaya

Sen bir ceylandın ben de avcı

Sen yalvarmıştın dur avcı 

Yapma dur diye

Ben de acımış, seni özgür bırakmıştım

Kaderin oynadığı oyuna bak sen şimdi....

Sen avcısın ben ceylan

Yay senin gözlerinde 

Gözlerinde hedef benim

Yalvarıyorum fılat oku

Vur beni 

Senin için yanan yüreğimin ortasından

Yoksa edeceğim,bin sene önceki ceylanı canından

(niğde)', 'Hatırlıyor musun bilmem Hani bin yıl önce gelmiştik ya dünyaya Sen bir ceylandın ben de avcı Sen yalvarmıştın dur avcı  Yapma dur diye Ben d...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Bolat']::text[], 8.5, '{"poet":"Süleyman Bolat","poet_slug":"suleyman-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hatirliyor-musun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yardı', 'o-yardi-yasar-tezel-4my0x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ummanda aşkın göz yaşı

Bulutlarla selam yolladım, aşka

Selamımı aldı,çiğdemler açtı

Sensizliğin dağ yamaçlarında

Irmaklarda sesin vardı

Gören göz ama kaldı

Gönül sarayı zengin

Ne aşıklar hayran kalır

Lalezar içinde yar vardı', 'Ummanda aşkın göz yaşı Bulutlarla selam yolladım, aşka Selamımı aldı,çiğdemler açtı Sensizliğin dağ yamaçlarında Irmaklarda sesin vardı Göre...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-yardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhran', 'buhran-adem-uzun-d1r09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş batıyor yine bak bugün de.

Bak bugün de yine sensiz bitiyor.

Artık gök kararıp gün döndüğünde,

Gözüme kanlı bir yaş birikiyor.

Güneş batıyor yine bak bugün de.

Oturup bir yere sen de ağlarsın,

Ummadığın anda bir terkedilsen.

Bir yanım kanıyor, orda sen varsın.

Kalbimin halini bir görebilsen,

Oturup bir yere sen de ağlarsın.

Ellerin elime dokunduğunda,

Kapladı içimi bir tatlı sızı.

Tüm aşkları silip attığım anda,

Birer birer çaldın ruhlarımızı,

Ellerin elime dokunduğunda.

Kaçırma gözünü, gözlerime bak.

Sanki bana karşı düşman gibisin.

Diz çöksem önünde ben ağlayarak,

Beni bir kez daha affeder misin? 

Kaçırma gözünü gözlerime bak.

Gelme artık çok geç, boş yere gelme,

Benim kalbim artık sensiz atacak.

Yıllardır aldanan şu yüreğime,

Doğruyu tek bir kurşun anlatacak.

Gelme artık çok geç, boş yere gelme.', 'Güneş batıyor yine bak bugün de. Bak bugün de yine sensiz bitiyor. Artık gök kararıp gün döndüğünde, Gözüme kanlı bir yaş birikiyor. Güneş b...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/buhran-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saate bakma anne...', 'saate-bakma-anne-elif-nida-ozkan-r05k6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saate bakma anne 

beni unuttuğun günü hatırlama

şu duyduğun ses var ya anne

belki israfilin son nefesidir

uyandığımda kalbime bakıyorum anne

üzerindeki ağırlıkları kaldırmak tüm günümü alıyor

tüm ömrümü alıyor anne sorularım

seccademdeki gülleri  boyuyorum

tüm günümü alıyor...

benim için beyaz bir elbise dik ne olur anne

bak biliyorsun duaların atlıkarıncalarına binerek

yükseldiğim çok oluyor.

ve anne düşmemem için sürekli hatırlamam gerekiyor günahlarımı

hatalarım beyaz elbisemde kayboluyor...

bana şarkılar dinletiyorlar anne

gözlerimde rengarenk desenli bağlar var,yanıp sönüyor...

okuyorum kitapları gözlerim bağlı 

okuyorum ve tüm kelimeler uçup gidiyor

bunları boşver anne

televizyonlar

gazeteler 

galiba kararıyor...

belki güneşin sönmesi budur ne dersin

hani yıldızlar yere düşer

ümitler yere düşer

dilekler yere düşer

ve dağlar anne unufak olur ya

yani sığınacak, hani yaslanacak 

yücelikler

unufak olur anne

olur mu anne? 

sen yine de 

saate bakma anne 

ama beni unuttuğun günü

mutlaka hatırla...

beni hatırla anne...', 'Saate bakma anne  beni unuttuğun günü hatırlama şu duyduğun ses var ya anne belki israfilin son nefesidir uyandığımda kalbime bakıyorum anne...', ARRAY['Türk Edebiyatı','Şiir','Elif Nida Özkan']::text[], 8.5, '{"poet":"Elif Nida Özkan","poet_slug":"elif-nida-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/saate-bakma-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece', 'bu-gece-ali-riza-unal-w8rge', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir ummana daldım, daldım çıktım bu gece - 

tutuldum hummaya,saldım canım bu gece 

bu ne umman-ı gümman,gül nâr imiş - 

yandım bedri beyzâ,yandım çıktım bu gece -', 'bir ummana daldım, daldım çıktım bu gece -  tutuldum hummaya,saldım canım bu gece  bu ne umman-ı gümman,gül nâr imiş -  yandım bedri beyzâ,y...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bu-gece-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
